import { useState, useEffect } from 'react';
import { useNotification } from './hooks/useNotification';

const PolicyForm = ({ policy, onSave, onClose }) => {
  const [formData, setFormData] = useState({
    name: '',
    rules: '{}',
    priority: 0,
    active: true,
  });

  useEffect(() => {
    if (policy) {
      setFormData({
        id: policy.id,
        name: policy.name || '',
        // Pretty-print JSON for better readability in the textarea
        rules: JSON.stringify(policy.rules, null, 2) || '{}',
        priority: policy.priority || 0,
        active: policy.active !== undefined ? policy.active : true,
      });
    }
  }, [policy]);

  const notification = useNotification();

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value,
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    try {
      // Parse the rules from JSON string back to an object before saving
      const rulesObject = JSON.parse(formData.rules);
      onSave({ ...formData, rules: rulesObject });
    } catch (error) {
      const notification = useNotification();
      notification.error('Invalid JSON in rules field.');
    }
  };

  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <h3>{policy ? 'Edit Policy' : 'Create New Policy'}</h3>
        <form onSubmit={handleSubmit}>
          <div className="form-group">
            <label htmlFor="name">Policy Name</label>
            <input
              type="text"
              id="name"
              name="name"
              value={formData.name}
              onChange={handleChange}
              required
            />
          </div>
          <div className="form-group">
            <label htmlFor="rules">Rules (JSON)</label>
            <textarea
              id="rules"
              name="rules"
              value={formData.rules}
              onChange={handleChange}
              rows="10"
              required
            />
          </div>
          <div className="form-group">
            <label htmlFor="priority">Priority</label>
            <input
              type="number"
              id="priority"
              name="priority"
              value={formData.priority}
              onChange={handleChange}
            />
          </div>
          <div className="form-group checkbox-group">
            <label htmlFor="active">Active</label>
            <input type="checkbox" id="active" name="active" checked={formData.active} onChange={handleChange} />
          </div>
          <div className="form-actions">
            <button type="submit">Save Policy</button>
            <button type="button" onClick={onClose}>Cancel</button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default PolicyForm;

import { useState, useEffect, useCallback } from 'react';
import { useConfirm } from './components/ConfirmProvider';
import { useNotification } from './hooks/useNotification';
import { devError } from './utils/devLogger';
import PolicyForm from './PolicyForm';

const API_URL = (import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000').replace(/\/$/, '') + '/api/v1';

const PolicyManager = () => {
  const [policies, setPolicies] = useState([]);
  const [editingPolicy, setEditingPolicy] = useState(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchPolicies = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const response = await fetch(`${API_URL}/policies`);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setPolicies(data || []);
    } catch (e) {
      setError('Failed to fetch policies. Please ensure the backend is running.');
      devError(e);
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchPolicies();
  }, [fetchPolicies]);

  const handleOpenModal = (policy = null) => {
    setEditingPolicy(policy);
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setEditingPolicy(null);
  };

  const handleSave = async (policyToSave) => {
    const isNew = !policyToSave.id;
    const url = isNew ? `${API_URL}/policies` : `${API_URL}/policies/${policyToSave.id}`;
    const method = isNew ? 'POST' : 'PUT';

    try {
      const response = await fetch(url, {
        method: method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(policyToSave),
      });

      if (!response.ok) {
        const errData = await response.json();
        throw new Error(errData.error || 'Failed to save policy');
      }

      fetchPolicies(); // Refresh the list
      handleCloseModal();
    } catch (e) {
      setError(e.message);
      devError(e);
    }
  };

  const handleDelete = async (policyId) => {
    const confirm = useConfirm();
    const notification = useNotification();
    if (!(await confirm({ title: 'Delete policy', description: 'Are you sure you want to delete this policy?' }))) return;
      try {
        const response = await fetch(`${API_URL}/policies/${policyId}`, {
          method: 'DELETE',
        });
        if (!response.ok) {
          throw new Error('Failed to delete policy');
        }
        fetchPolicies(); // Refresh the list
        notification.success('Policy deleted');
      } catch (e) {
        setError(e.message);
        devError(e);
      }
    }
  };

  if (isLoading) return <div>Loading policies...</div>;

  return (
    <div className="policy-manager">
      <h2>ABAC Policy Management</h2>
      <button onClick={() => handleOpenModal()} className="create-btn">
        Create New Policy
      </button>

      {error && <div className="error-message">{error}</div>}

      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Priority</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {policies.length > 0 ? (
            policies.map((policy) => (
              <tr key={policy.id != null && typeof policy.id !== 'object' ? String(policy.id) : ''}>
                <td>{policy.name}</td>
                <td>{policy.priority}</td>
                <td>
                  <span className={`status ${policy.active ? 'active' : 'inactive'}`}>
                    {policy.active ? 'Active' : 'Inactive'}
                  </span>
                </td>
                <td>
                  <button onClick={() => handleOpenModal(policy)}>Edit</button>
                  <button onClick={() => handleDelete(policy.id)} className="delete-btn">
                    Delete
                  </button>
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="4">No policies found.</td>
            </tr>
          )}
        </tbody>
      </table>

      {isModalOpen && (
        <PolicyForm
          policy={editingPolicy}
          onSave={handleSave}
          onClose={handleCloseModal}
        />
      )}
    </div>
  );
};

