import { Suspense, useMemo, useEffect, useCallback, useState } from 'react';
import { devError } from './utils/devLogger';
import { useDrag } from 'react-dnd';
import { listSavedQueries, cloneQuery, deleteQuery, getSavedQuery, getPreview } from './api';
import { useConfirm } from './components/ConfirmProvider';
import { useNotification } from './hooks/useNotification';
import type { SavedQuery, FullSavedQuery, ViewMeta, ExecuteResult } from './types';
import { LazyECharts } from './components/ChartLoader';
import { useDebounce } from './hooks/useDebounce';
import { ItemTypes } from './FolderBrowser';
import DuplicateQueriesPanel from './DuplicateQueriesPanel';

// eslint-disable-next-line @typescript-eslint/no-unused-vars
function DraggableQueryRow({ q, children }: { q: SavedQuery; children: React.ReactNode }) {
  const [{ isDragging }, drag] = useDrag(() => ({
    type: ItemTypes.SAVED_ITEM,
    item: { id: q.id, type: 'query' },
    // narrow the monitor shape locally to avoid `any` in many call sites
    collect: (monitor: { isDragging?: () => boolean } | undefined) => ({
      isDragging: !!monitor?.isDragging?.(),
    }),
  }));

  return (
    <div ref={drag} className={`draggable-row ${isDragging ? 'dragging' : ''}`}>
      {children}
    </div>
  );
}
interface SavedQueriesPanelProps {
  onOpen: (q: FullSavedQuery) => void;
  views: ViewMeta[];
}

export default function SavedQueriesPanel({ onOpen, views }: SavedQueriesPanelProps) {
  const [saved, setSaved] = useState<SavedQuery[]>([]);
  const [scope, setScope] = useState<'mine' | 'shared' | 'duplicates'>('mine');
  const [search, setSearch] = useState('');
  const [previewData, setPreviewData] = useState<ExecuteResult | null>(null);
  const [previewLoading, setPreviewLoading] = useState(false);
  const [hoveredItem, setHoveredItem] = useState<string | null>(null);
  const [selectedDatasource, setSelectedDatasource] = useState<string>('');
  const debouncedSearch = useDebounce(search, 300);

  const datasources = useMemo(() => [...new Set(views.map(v => v.schema))], [views]);

  useEffect(() => {
    if (datasources.length > 0 && !selectedDatasource && datasources[0]) {
      setSelectedDatasource(datasources[0]);
    }
  }, [datasources, selectedDatasource]);

  const fetchSaved = useCallback(() => {
    if (scope !== 'duplicates') {
      listSavedQueries({ scope, search: debouncedSearch }).then(setSaved).catch(err => devError('Failed to load saved queries:', err));
    }
  }, [scope, debouncedSearch]);

  useEffect(fetchSaved, [fetchSaved]);

  const confirm = useConfirm();
  const notification = useNotification();

  const handleOpen = async (id: string) => {
    try {
      const fullQuery = await getSavedQuery(id);
      onOpen(fullQuery);
    } catch (error) {
      const notification = useNotification();
      notification.error(`Failed to open query: ${(error as Error).message}`);
    }
  };

  const handleClone = async (id: string) => {
    await cloneQuery(id);
    fetchSaved(); // Refetch to get the new list with the clone
  };

  const handleDelete = async (id: string) => {
    const confirm = useConfirm();
    const notification = useNotification();
    if (await confirm({ title: 'Delete saved query', description: 'Are you sure you want to delete this query? This cannot be undone.' })) {
      try {
        await deleteQuery(id);
        setSaved(s => s.filter(q => q.id !== id));
        notification.success('Query deleted');
      } catch (err) {
        notification.error('Failed to delete query');
      }
    }
  };

  const handleMouseEnter = (q: SavedQuery) => {
    setHoveredItem(q.id);
    if (!q.preview_available) return;
    setPreviewLoading(true);
    getPreview(q.id)
      .then(setPreviewData)
      .catch(() => setPreviewData(null))
      .finally(() => setPreviewLoading(false));
  };

  const handleMouseLeave = () => {
    setHoveredItem(null);
    setPreviewData(null);
  };

  return (
    <div className="saved-queries-panel">
      <h4>Saved Queries</h4>
      <div className="panel-controls">
        <div className="scope-tabs">
          <button onClick={() => setScope('mine')} className={scope === 'mine' ? 'active' : ''}>My Queries</button>
          <button onClick={() => setScope('shared')} className={scope === 'shared' ? 'active' : ''}>Shared</button>
          <button onClick={() => setScope('duplicates')} className={scope === 'duplicates' ? 'active' : ''}>Duplicates</button>
        </div>
        {scope === 'duplicates' ? (
          <select aria-label="Select Datasource" value={selectedDatasource} onChange={e => setSelectedDatasource(e.target.value)}>
            {datasources.map(ds => <option key={ds} value={ds}>{ds}</option>)}
          </select>
        ) : (
          <input type="search" placeholder="Search name/description..." value={search} onChange={e => setSearch(e.target.value)} />
        )}
      </div>
      {scope === 'duplicates' ? (
        <DuplicateQueriesPanel datasourceId={selectedDatasource} />
      ) : (
        <>
          <ul>
            {saved.map(_q => (
              <li key={_q.id} onMouseEnter={() => handleMouseEnter(_q)} onMouseLeave={handleMouseLeave}>
                <DraggableQueryRow q={_q}>
                  <div className="query-row-content">
                    <div className="query-info" onClick={() => handleOpen(_q.id)}>
                      <span className="query-name" title={`Open "${_q.name}"`}>{_q.name}</span>
                      <small className="query-meta">
                        in <strong>{_q.view_name}</strong>
                        {scope === 'shared' && ` by ${_q.owner_user_id}`}
                      </small>
                      <small className="query-meta">
                        {_q.last_run_at ? `Ran ${new Date(_q.last_run_at).toLocaleDateString()}` : 'Never run'}
                      </small>
                    </div>
                    <div className="query-actions">
                      <button onClick={() => handleClone(_q.id)} title="Clone">Clone</button>
                      <button onClick={() => handleDelete(_q.id)} title="Delete">Delete</button>
                    </div>
                  </div>
                </DraggableQueryRow>
              </li>
            ))}
          </ul>
          {hoveredItem && (
            <>
              {previewData && (
                  <div className="preview-tooltip">
                    {/* The backend preview may return either an execute result (rows/columns)
                        or a chart preview shape. Narrow chart into a local `previewChart` variable. */}
                    {(() => {
                      const previewChart = (previewData as unknown as { chart?: unknown })?.chart;
                      return previewChart ? (
                        <Suspense fallback={<div className="chart-loading-small">Loading preview...</div>}>
                          <div className="chart-preview-size"><LazyECharts option={previewChart as unknown} /></div>
                        </Suspense>
                      ) : <pre>{JSON.stringify(previewData, null, 2)}</pre>;
                    })()}
                  </div>
              )}
              {previewLoading && <div className="preview-tooltip">Loading preview...</div>}
            </>
          )}
        </>
      )}
    </div>
  );
}

import { useState, useMemo, useEffect } from 'react';
import { useNotification } from './hooks/useNotification';
import { devError } from './utils/devLogger';
import { semanticSearch, getSavedQuery, logSearchFeedback } from './api';
import { useDebounce } from './hooks/useDebounce';
import type { SemanticSearchResult, SearchFilters, FullSavedQuery } from './types';
import SearchFiltersPanel from './SearchFiltersPanel';
import ExplainMatchPanel from './ExplainMatchPanel';
import SearchResultCard from './SearchResultCard';


interface SemanticSearchProps {
  onOpenQuery: (q: FullSavedQuery) => void;
  // onOpenWorkbook: (id: string) => void;
}

export default function SemanticSearchContainer({ onOpenQuery }: SemanticSearchProps) {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<SemanticSearchResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [filters, setFilters] = useState<SearchFilters>({ type: ['query', 'workbook'], scope: 'all', tags: [] });
  const [showOnlyAccessible, setShowOnlyAccessible] = useState(true);
  const [explainResult, setExplainResult] = useState<SemanticSearchResult | null>(null);
  const debouncedQuery = useDebounce(query, 300);
  const notification = useNotification();

  useEffect(() => {
    if (debouncedQuery.length < 3) {
      setResults([]);
      return;
    }
    setLoading(true);
    semanticSearch({ query: debouncedQuery, filters })
      .then(setResults)
        .catch((e) => { devError(e); })
        .finally(() => setLoading(false));
  }, [debouncedQuery, filters]);

  const handleFeedback = (result: SemanticSearchResult, action: 'favorited' | 'ignored') => {
    logSearchFeedback({
      query: debouncedQuery,
      result_id: result.id,
      result_type: result.type,
      action,
    });
  };

  const handleOpen = async (result: SemanticSearchResult) => {
    logSearchFeedback({
      query: debouncedQuery,
      result_id: result.id,
      result_type: result.type,
      action: 'clicked',
    });
    if (result.type === 'query') {
      // The search result is a summary. We need to fetch the full query to open it.
      const fullQuery = await getSavedQuery(result.id);
      onOpenQuery(fullQuery);
    } else {
      // onOpenWorkbook(result.id);
      const notification = useNotification();
      notification.info(`Opening workbook ${result.name} is not implemented yet.`);
    }
    setQuery(''); // Clear search after opening
    setResults([]);
  };

  const displayedResults = useMemo(() => {
    return showOnlyAccessible ? results.filter(r => r.has_access) : results;
  }, [results, showOnlyAccessible]);

  return (
    <div className="semantic-search-container">
      <div className="semantic-search-bar">
        <input
          type="search"
          placeholder="🔍 Search by meaning… e.g. 'churn trends in APAC'"
          value={query}
          onChange={e => setQuery(e.target.value)}
        />
      </div>
      <div className="search-controls">
        <SearchFiltersPanel filters={filters} onChange={setFilters} />
        <label className="access-toggle">
          <input type="checkbox" checked={showOnlyAccessible} onChange={e => setShowOnlyAccessible(e.target.checked)} />
          Show only assets I can access
        </label>
      </div>

      {loading && <div className="search-results-popup loading">Loading...</div>}
      {!loading && displayedResults.length > 0 && (
        <div className="search-results-grid">
          {displayedResults.map(res => (
            <SearchResultCard key={res.id} result={res} onOpen={handleOpen} onExplain={setExplainResult} onFeedback={handleFeedback} />
          ))}
        </div>
      )}
      {explainResult && (
        <ExplainMatchPanel result={explainResult} onClose={() => setExplainResult(null)} />
      )}
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useNotification } from './hooks/useNotification';
/* eslint-disable jsx-a11y/aria-proptypes */
import type { ViewMeta, QueryState, CompileResult, PageInfo, ColumnMeta, Explain, VizConfig, FullSavedQuery, FullWorkbook } from './types';
import { getViewIdentifier } from './types/views';
import { listViews } from './api';
import ExplorerTab from './ExplorerTab';
import SaveWorkbookModal from './SaveWorkbookModal';
import TourRunner from './TourRunner';

export type TabState = {
  id: string;
  title: string;
  savedId?: string;
  view?: ViewMeta;
  query: QueryState;
  compile?: CompileResult;
  result?: { rows: Record<string, unknown>[]; columns: ColumnMeta[]; page: PageInfo };
  viz?: VizConfig;
  explain?: Explain;
};

const createNewTab = (title: string): TabState => ({
  id: crypto.randomUUID(),
  title,
  query: { measures: [], dimensions: [], filters: [], order: [], limit: 50, offset: 0 },
});

export default function TabsManager() {
  const [tabs, setTabs] = useState<TabState[]>(() => [createNewTab('Tab 1')]);
  const [activeId, setActiveId] = useState<string | null>(tabs[0]?.id || null);
  const [views, setViews] = useState<ViewMeta[]>([]);
  const [activeTourId, setActiveTourId] = useState<string | null>(null);
  const [isSaveModalOpen, setIsSaveModalOpen] = useState(false);

  useEffect(() => {
    listViews().then(setViews);
  }, []);

  const addTab = () => {
    const newTab = createNewTab(`Tab ${tabs.length + 1}`);
    setTabs(t => [...t, newTab]);
    setActiveId(newTab.id);
  };

  const updateTab = useCallback((id: string, patch: Partial<TabState>) => {
    setTabs(ts => ts.map(t => (t.id === id ? { ...t, ...patch } : t)));
  }, []);

  const openSavedQuery = useCallback((q: FullSavedQuery) => {
    const id = crypto.randomUUID();
    // Allow saved queries to reference views by id or by name
  const viewForQuery = views.find(v => getViewIdentifier(v) === q.view_name || v.name === q.view_name);
    if (!viewForQuery) {
      const notification = useNotification();
      notification.error(`Could not open saved query: View '${q.view_name}' not found.`);
      return;
    }

    const newTab: TabState = {
      id,
      title: q.name,
      savedId: q.id,
      view: viewForQuery,
      query: (q.query as QueryState) || { measures: [], dimensions: [], filters: [], order: [], limit: 50, offset: 0 },
      viz: q.viz_config,
    };
    setTabs(t => [...t, newTab]);
    setActiveId(id);
  }, [views]);

  const openWorkbook = useCallback((workbook: FullWorkbook) => {
    const newTabs: TabState[] = workbook.tabs.map(wt => ({
      id: crypto.randomUUID(),
      title: wt.title,
  view: views.find(v => getViewIdentifier(v) === wt.view_name || v.name === wt.view_name),
      query: (wt.query as QueryState) || { measures: [], dimensions: [], filters: [], order: [], limit: 50, offset: 0 },
      viz: wt.viz_config,
      // Reset runtime state
      result: undefined,
      compile: undefined,
      explain: undefined,
    }));
    setTabs(newTabs);
    setActiveId(newTabs[0]?.id || null);
  }, [views]);

  const closeTab = (id: string) => {
    const tabIndex = tabs.findIndex(t => t.id === id);
    const newTabs = tabs.filter(t => t.id !== id);
    setTabs(newTabs);

    if (activeId === id) {
      if (newTabs.length > 0) {
        // Activate the previous tab, or the first tab if the closed one was the first
        const newActiveIndex = Math.max(0, tabIndex - 1);
        setActiveId(newTabs[newActiveIndex].id);
      } else {
        setActiveId(null);
        // Optional: create a new blank tab if the last one is closed
        addTab();
      }
    }
  };

  return (
    <div className="tabs-manager">
      <div className="tab-bar">
        <div role="tablist" aria-label="Explorer Tabs">
          {tabs.map((t, index) => {
            const isSelected = t.id === activeId;
            const controlId = t.id != null ? `tabpanel-${t.id}` : undefined;
            const ariaSelected = isSelected ? 'true' : undefined;
            return (
            <button
              /* webhint-disable axe/aria */
              key={t.id != null && typeof t.id !== 'object' ? String(t.id) : ''}
              id={`tab-${t.id}`}
              role="tab" // This is a valid ARIA role.

              aria-controls={controlId}
              {...(ariaSelected ? { 'aria-selected': ariaSelected } : {})}
              className={`tab-item-container ${t.id === activeId ? "active" : ""}`}
              onClick={(e) => {
                if ((e.target as HTMLElement).classList.contains('close-tab-btn')) {
                  e.stopPropagation();
                  closeTab(t.id);
                } else {
                  setActiveId(t.id);
                }
              }}
              onKeyDown={(e: React.KeyboardEvent) => {
                let nextIndex = -1;
                if (e.key === 'ArrowRight') nextIndex = (index + 1) % tabs.length;
                else if (e.key === 'ArrowLeft') nextIndex = (index - 1 + tabs.length) % tabs.length;
                if (nextIndex !== -1) {
                  e.preventDefault();
                  document.getElementById(`tab-${tabs[nextIndex].id}`)?.focus();
                }
              }}
              tabIndex={t.id === activeId ? 0 : -1}
            >
              <span className="tab-item-button">{t.title}</span>
              <span className="close-tab-btn" aria-hidden="true">&times;</span>
            </button>
            );
          })}
        </div>
        <button className="add-tab-btn" aria-label="Add new tab" onClick={addTab}>+</button>
        <button className="save-workbook-btn" onClick={() => setIsSaveModalOpen(true)}>Save Workbook</button>
      </div>
      <div className="tab-body">
        {tabs.filter(t => t.id === activeId).map(t => (
          <ExplorerTab
            key={t.id != null && typeof t.id !== 'object' ? String(t.id) : ''}
            tab={t}
            views={views}
            onChange={(patch) => updateTab(t.id, patch)}
            onOpenSavedQuery={openSavedQuery}
            onOpenWorkbook={openWorkbook}
            onStartTour={setActiveTourId}
          />
        ))}
      </div>
      {isSaveModalOpen && (
        <SaveWorkbookModal tabs={tabs} onClose={() => setIsSaveModalOpen(false)} onSaved={() => { /* Maybe show a confirmation */ }} />
      )}
      {activeTourId && (
        <TourRunner tourId={activeTourId} onComplete={() => setActiveTourId(null)} />
      )}
    </div>
  );
}

import { apiClient } from '../utils/apiClient';
import { APIEndpoint, APICatalog, APITest, APITestRun } from '../types/apiStudio';

const API_BASE = '/api-studio';

export const ApiStudioApi = {
    // Endpoints
    listEndpoints: async (env: string, tenantId: string): Promise<APIEndpoint[]> => {
        return apiClient<APIEndpoint[]>(`${API_BASE}/endpoints?env=${env}&tenant_id=${tenantId}`);
    },
    getEndpoint: async (id: string): Promise<APIEndpoint> => {
        return apiClient<APIEndpoint>(`${API_BASE}/endpoints/${id}`);
    },
    saveEndpoint: async (endpoint: Partial<APIEndpoint>): Promise<APIEndpoint> => {
        return apiClient<APIEndpoint>(`${API_BASE}/endpoints`, {
            method: 'POST',
            body: JSON.stringify(endpoint),
            headers: { 'Content-Type': 'application/json' }
        });
    },
    deprecateEndpoint: async (id: string): Promise<APIEndpoint> => {
        return apiClient<APIEndpoint>(`${API_BASE}/endpoints/${id}/deprecate`, { method: 'POST' });
    },
    retireEndpoint: async (id: string): Promise<APIEndpoint> => {
        return apiClient<APIEndpoint>(`${API_BASE}/endpoints/${id}/retire`, { method: 'POST' });
    },
    generateEndpointWithAI: async (prompt: string, tenantId: string): Promise<APIEndpoint> => {
        return apiClient<APIEndpoint>(`${API_BASE}/endpoints/ai`, {
            method: 'POST',
            body: JSON.stringify({ prompt, tenant_id: tenantId }),
            headers: { 'Content-Type': 'application/json' }
        });
    },

    // OpenAPI
    getOpenApiSpec: async (env: string, tenantId: string): Promise<any> => {
        return apiClient<any>(`${API_BASE}/openapi?env=${env}&tenant_id=${tenantId}`);
    },

    // Runtime Preview (calling the actual runtime)
    previewEndpoint: async (path: string, method: string, env: string, tenantId: string, params: any): Promise<any> => {
        const url = `/runtime${path}`;
        // ApiClient handles API prefixing

        // Pass validation headers for the runtime
        const headers = {
            'Content-Type': 'application/json',
            'X-Env': env,
            'X-Tenant-ID': tenantId
        };

        const config: RequestInit = {
            method,
            headers
        };

        if (method === 'GET') {
            const qs = new URLSearchParams(params).toString();
            return apiClient(`${url}?${qs}`, config);
        } else {
            config.body = JSON.stringify(params);
            return apiClient(url, config);
        }
    },

    // Performance & DX
    getSdkURL: (lang: string, env: string, tenantId: string) => {
        // This is a direct URL for valid hrefs, so we keep using the API base directly regarding path
        // but removing the /api prefix from the constant if apiClient adds it? 
        // Actually apiClient adds /api if missing. Here we return a string URL.
        // Let's assume the component consuming this knows to prepend host or use relative path.
        // Since API_BASE is now just /api-studio (apiClient handles /api prefix for requests),
        // but for a link href we need the full path.
        return `/api/api-studio/sdk/${lang}?env=${env}&tenant_id=${tenantId}`;
    },
    getEndpointMetrics: async (id: string): Promise<any> => {
        // In a real system, this would call obs_metrics
        // For now, we return mock performance data
        return Promise.resolve({
            p50: 120,
            p95: 180,
            p99: 250,
            qps: 45.5,
            cacheHitRate: 0.82,
            preaggHitRate: 0.95
        });
    }
};

import { useQuery } from '@tanstack/react-query';
import { useTenant } from '../contexts/TenantContext';
import { devDebug } from '../utils/devLogger';

export interface Lookup {
  id: string;
  tenant_id?: string;
  name: string;
  description?: string;
  is_core?: boolean;
}

export interface LookupValue {
  id: string;
  tenant_id?: string;
  name: string;
  parent_id?: string | null;
  metadata?: any;
  label?: string;
  value?: string;
  is_core?: boolean;
}

export function useLookups(tenantId?: string, q?: string, limit?: number) {
  return useQuery({
    queryKey: ['lookups', tenantId, q, limit],
    queryFn: async () => {
      if (!tenantId) return [] as Lookup[];
      const params = new URLSearchParams({ tenant_id: tenantId });
      if (q) params.set('q', q);
      if (limit && limit > 0) params.set('limit', String(limit));
      const res = await fetch(`/api/lookups?${params.toString()}`, { credentials: 'include' });
      if (!res.ok) {
        const err = await res.text();
        throw new Error(err || 'Failed to fetch lookups');
      }
      // API returns { items: Lookup[], next_cursor: number } for paginated responses.
      // Normalize that shape to return the array of lookups so callers can assume an array.
      const raw = await res.json();
      if (Array.isArray(raw)) return raw as Lookup[];
      return (raw?.items as Lookup[]) || [];
    },
    enabled: !!tenantId,
  });
}

import { useInfiniteQuery } from '@tanstack/react-query';

// Infinite lookup hook for autocompletes — returns pages and fetchNextPage helper
export function useInfiniteLookups(tenantId?: string, q?: string, limit = 50) {
  return useInfiniteQuery({
    // Use a distinct key for infinite lookups to avoid colliding with the
    // simple `useLookups` query (which returns an array). Sharing the same
    // key causes cache shape mismatches (array vs {pages: []}).
    queryKey: ['lookups/infinite', tenantId, q, limit],
    queryFn: async ({ pageParam }) => {
      if (!tenantId) return { items: [], next_cursor: undefined };
      const params = new URLSearchParams({ tenant_id: tenantId, limit: String(limit), cursor: String(pageParam) });
      if (q) params.set('q', q);
      const res = await fetch(`/api/lookups?${params.toString()}`, { credentials: 'include' });
      if (!res.ok) {
        const err = await res.text();
        throw new Error(err || 'Failed to fetch lookups');
      }
      const data = await res.json() as { items: Lookup[]; next_cursor?: number };
      return { items: data.items || [], next_cursor: data.next_cursor };
    },
    initialPageParam: 0,
    getNextPageParam: (lastPage) => (lastPage?.next_cursor ? lastPage.next_cursor : undefined),
    enabled: !!tenantId,
  });
}

export function useLookupValues(tenantId?: string, lookupId?: string, parentId?: string | null, parentValue?: string | null) {
  return useQuery({
    queryKey: ['lookup-values', tenantId, lookupId, parentId, parentValue],
    queryFn: async () => {
      if (!tenantId || !lookupId) return [] as LookupValue[];
      let url = `/api/lookups/${lookupId}/values?tenant_id=${tenantId}`;
      if (parentId) {
        url += `&parent_id=${encodeURIComponent(parentId)}`;
      } else if (parentValue) {
        url += `&parent_value=${encodeURIComponent(parentValue)}`;
      }
      const res = await fetch(url, { credentials: 'include' });
      if (!res.ok) {
        const err = await res.text();
        throw new Error(err || 'Failed to fetch lookup values');
      }
      const raw = await res.json();
      // Debug: log response and URL for troubleshooting cascading behavior
      // eslint-disable-next-line no-console
      devDebug('[useLookupValues] fetched', { url, parentId, items: raw.items || [], raw });
      // API returns { items: [...], next_cursor: ... }, so extract items array
      const items = raw.items || [];
      // Normalize server-side field names (label/value into a `name` field) and return lightweight objects
      return items.map((r: any) => ({ id: r.id, tenant_id: r.tenant_id, name: r.label || r.value || r.name, parent_id: r.parent_id || r.parentId || null, metadata: r.metadata, label: r.label, value: r.value, is_core: r.is_core }));
    },
    enabled: !!tenantId && !!lookupId,
  });
}

export function useInfiniteLookupValues(tenantId?: string, lookupId?: string, parentId?: string | null, parentValue?: string | null, limit = 50) {
  return useInfiniteQuery({
    queryKey: ['lookup-values/infinite', tenantId, lookupId, parentId, parentValue, limit],
    queryFn: async ({ pageParam }) => {
      if (!tenantId || !lookupId) return { items: [], next_cursor: undefined };
      let url = `/api/lookups/${lookupId}/values?tenant_id=${tenantId}&limit=${limit}`;
      if (pageParam) {
        url += `&cursor=${encodeURIComponent(String(pageParam))}`;
      }
      if (parentId) {
        url += `&parent_id=${encodeURIComponent(parentId)}`;
      } else if (parentValue) {
        url += `&parent_value=${encodeURIComponent(parentValue)}`;
      }
      const res = await fetch(url, { credentials: 'include' });
      if (!res.ok) {
        const err = await res.text();
        throw new Error(err || 'Failed to fetch lookup values');
      }
      const raw = await res.json();
      const items = (raw.items || []).map((r: any) => ({ id: r.id, tenant_id: r.tenant_id, name: r.label || r.value || r.name, parent_id: r.parent_id || r.parentId || null, metadata: r.metadata, label: r.label, value: r.value, is_core: r.is_core }));
      return { items, next_cursor: raw.next_cursor };
    },
    initialPageParam: 0,
    getNextPageParam: (lastPage) => (lastPage?.next_cursor ? lastPage.next_cursor : undefined),
    enabled: !!tenantId && !!lookupId,
  });
}

