export interface ReportingDatasetField {
  name: string;
  type?: string;
  description?: string;
  [key: string]: unknown;
}

export interface ReportingDataset {
  id: string;
  name: string;
  dataSourceId?: string;
  fields: ReportingDatasetField[];
  description?: string;
  [key: string]: unknown;
}

const toReportingDataset = (raw: JsonRecord | null | undefined): ReportingDataset | null => {
  if (!raw) {
    return null;
  }
  const id = (raw.id as string) ?? (raw.dataset_id as string) ?? (raw.datasetId as string);
  const name = (raw.name as string) ?? (raw.dataset_name as string) ?? (raw.title as string);
  if (!id || !name) {
    return null;
  }
  const fieldsSource = Array.isArray(raw.fields)
    ? (raw.fields as JsonRecord[])
    : Array.isArray(raw.columns)
      ? (raw.columns as JsonRecord[])
      : [];
  const fields: ReportingDatasetField[] = fieldsSource.map((field) => ({
    name: (field.name as string) ?? (field.column_name as string) ?? 'Field',
    type: (field.type as string) ?? (field.data_type as string),
    description: (field.description as string) ?? undefined,
    ...field,
  }));

  return {
    id,
    name,
    dataSourceId: (raw.data_source_id as string) ?? (raw.dataSourceId as string),
    fields,
    description: (raw.description as string) ?? undefined,
    ...raw,
  };
};

const fetchDatasets = async (tenantId: string): Promise<ReportingDataset[]> => {
  const raw = await request<unknown>(`/api/semantic/cubes`, {
    headers: {
      'X-Tenant-ID': tenantId,
    },
  });

  const cubesData = normaliseCollection(raw);

  return cubesData.map((cube: any) => ({
    id: cube.id || cube.name,
    name: cube.display_name || cube.name,
    fields: (cube.dimensions || []).concat(cube.measures || []).map((item: any) => ({
      name: item.name,
      type: item.type,
      description: item.display_name || item.name,
    })),
    description: cube.description || undefined,
  }));
};

export const useDatasets = () => {
  const { tenant } = useTenant();

  return useQuery({
    queryKey: ['reporting', 'datasets', tenant?.id],
    queryFn: () => fetchDatasets(tenant?.id || ''),
    staleTime: 60_000,
    enabled: !!tenant?.id,
  });
};

