  const id = (raw.id as string) ?? (raw.business_object_id as string);
  const name = (raw.name as string) ?? (raw.display_name as string);
  if (!id || !name) {
    return null;
  }

  const fieldsSource = Array.isArray(raw.fields) ? (raw.fields as JsonRecord[]) : [];
  const fields: BusinessObjectField[] = fieldsSource.map((field) => ({
    name: (field.name as string) ?? 'Field',
    label: (field.displayName as string) ?? (field.display_name as string) ?? (field.name as string),
    type: (field.type as string) ?? (field.data_type as string),
    description: (field.description as string) ?? undefined,
    ...field,
  }));

  return {
    id,
    name,
    key: (raw.key as string) ?? undefined,
    display_name: (raw.display_name as string) ?? name,
    fields,
    description: (raw.description as string) ?? undefined,
    tenant_id: (raw.tenant_id as string) ?? undefined,
    ...raw,
  };
};

const fetchBusinessObjects = async (tenantId: string, datasourceId?: string): Promise<BusinessObject[]> => {
  const headers: Record<string, string> = {
    'X-Tenant-ID': tenantId,
  };
  if (datasourceId) {
    headers['X-Tenant-Datasource-ID'] = datasourceId;
  }
  const raw = await request<unknown>(`/api/business-objects`, { headers });
  return normaliseCollection(raw)
    .map(toBusinessObject)
    .filter((item): item is BusinessObject => item !== null);
};

export const useBusinessObjects = (overrideDatasourceId?: string) => {
  const { tenant, datasource } = useTenant();
  const dsId = overrideDatasourceId || datasource?.id;

  return useQuery({
    queryKey: ['reporting', 'business-objects', tenant?.id, dsId],
    queryFn: () => fetchBusinessObjects(tenant?.id || '', dsId),
    staleTime: 60_000,
    enabled: !!tenant?.id,
  });
};

