export default AIPortfolioRebalancer;

import React, { useState, useMemo, useCallback } from 'react';
import { 
  useAbbreviations, 
  useAbbreviationExpansion, 
  useSemanticTermValidation
} from '../utils/abbreviationApi';
import ProfessionalSearchInput from './ProfessionalSearchInput';
import { devDebug, devError } from '../utils/devLogger';
import { useConfirm } from './ConfirmProvider';
import { useNotification } from '../hooks/useNotification';
import { useTenant } from '../contexts/TenantContext';
import { Button } from '@mui/material'; // Adding Button import if not present, checking usage
import './AbbreviationManager.css';

interface AbbreviationManagerProps {
  className?: string;
  tenantId?: string; // Optional prop if we want to force a specific tenant context
}

export const AbbreviationManager: React.FC<AbbreviationManagerProps> = ({
  className = '',
  tenantId: propsTenantId
}) => {
  const { tenant } = useTenant();
  const tenantId = propsTenantId || tenant?.id;

  const { 
    abbreviations, 
    loading, 
    error, 
    loaded, 
    fetchAbbreviations, 
    addAbbreviation, 
    updateAbbreviation, 
    deleteAbbreviation,
    totalCount,
    hasMore,
    loadMore,
    searchAbbreviations
  } = useAbbreviations(tenantId);
  const { expandColumn } = useAbbreviationExpansion();
  const { validateTerms } = useSemanticTermValidation();

  const [newAbbreviation, setNewAbbreviation] = useState('');
  const [newFullWord, setNewFullWord] = useState('');
  const [newNotes, setNewNotes] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [testColumn, setTestColumn] = useState('');
  const [testTerms, setTestTerms] = useState('');
  const [expansionResult, setExpansionResult] = useState<any>(null);
  const [validationResult, setValidationResult] = useState<any>(null);
  const [activeTab, setActiveTab] = useState<'list' | 'add' | 'test' | 'validate'>('list');

  // Edit state
  const [editingAbbreviation, setEditingAbbreviation] = useState<any>(null);
  const [showEditModal, setShowEditModal] = useState(false);

  // Debounced search
  React.useEffect(() => {
    const timer = setTimeout(() => {
      // Only search if we are in the list tab, or generally if query changes
      searchAbbreviations(searchQuery);
    }, 400);
    return () => clearTimeout(timer);
  }, [searchQuery, searchAbbreviations]);

  // Handle tab changes with lazy loading
  const handleTabChange = useCallback((tabId: 'list' | 'add' | 'test' | 'validate') => {
    setActiveTab(tabId);

    // Lazy load abbreviations when switching to the list tab
    if (tabId === 'list' && !loaded) {
      fetchAbbreviations();
    }
  }, [loaded, fetchAbbreviations]);

  // Lazy load abbreviations when component mounts and list tab is active
  React.useEffect(() => {
    if (activeTab === 'list' && !loaded) {
      fetchAbbreviations();
    }
  }, [activeTab, loaded, fetchAbbreviations]);

  // Fetch abbreviations on component mount if not already loaded is handled by useEffect above
  // but if we want to ensure data on mount:
  React.useEffect(() => {
     if (!loaded) fetchAbbreviations();
  }, []);

  // Prepare search data for the search component (Autocomplete)
  // Note: Only shows currently loaded items
  const searchData = useMemo(() => 
    (abbreviations || []).map(abbrev => ({
      id: abbrev.id,
      text: abbrev.abbreviation,
      subtext: abbrev.full_word
    }))
  , [abbreviations]);

  // Handle adding new abbreviation
  const handleAddAbbreviation = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newAbbreviation.trim() || !newFullWord.trim()) return;

    const success = await addAbbreviation(
      newAbbreviation.toUpperCase().trim(),
      newFullWord.toUpperCase().trim(),
      newNotes.trim()
    );

    if (success) {
      setNewAbbreviation('');
      setNewFullWord('');
      setNewNotes('');
    }
  };

  // ... (Test Expansion and Validation handlers remain same) ...
  const handleTestExpansion = async () => {
    if (!testColumn.trim()) return;
    try {
      const result = await expandColumn(testColumn.trim());
      setExpansionResult(result);
    } catch (err) {
      devError('Failed to test expansion:', err);
    }
  };

  const handleValidateTerms = async () => {
    if (!testTerms.trim()) return;
    const terms = testTerms.split(',').map(t => t.trim()).filter(t => t);
    if (terms.length === 0) return;
    try {
      const result = await validateTerms(terms);
      setValidationResult(result);
    } catch (err) {
      devError('Failed to validate terms:', err);
    }
  };

  const handleEditAbbreviation = (abbrev: any) => {
    setEditingAbbreviation(abbrev);
    setNewAbbreviation(abbrev.abbreviation);
    setNewFullWord(abbrev.full_word);
    setNewNotes(abbrev.notes || '');
    setShowEditModal(true);
  };

  const handleUpdateAbbreviation = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingAbbreviation || !newAbbreviation.trim() || !newFullWord.trim()) return;
    const success = await updateAbbreviation(
      editingAbbreviation.id, 
      newAbbreviation.trim(), 
      newFullWord.trim(), 
      newNotes.trim()
    );
    if (success) {
      setShowEditModal(false);
      setEditingAbbreviation(null);
      setNewAbbreviation('');
      setNewFullWord('');
      setNewNotes('');
    }
  };

  const confirm = useConfirm();
  const notification = useNotification();

  const handleDeleteAbbreviation = async (id: number) => {
    if (!(await confirm({ title: 'Delete abbreviation', description: 'Are you sure you want to delete this abbreviation?' }))) return;
    try {
      await deleteAbbreviation(id);
      notification.success('Abbreviation deleted');
    } catch (err) {
      notification.error('Failed to delete abbreviation');
    }
  };

  const handleCloseEditModal = () => {
    setShowEditModal(false);
    setEditingAbbreviation(null);
    setNewAbbreviation('');
    setNewFullWord('');
    setNewNotes('');
  };

  if (error) {
    return (
      <div className={`p-4 bg-red-50 border border-red-200 rounded-lg ${className}`}>
        <p className="text-red-600">Error: {error}</p>
      </div>
    );
  }

  return (
    <div className={`abbreviation-manager ${className}`}>
      {/* Tab Navigation */}
      <div className="tab-navigation">
        <nav className="tab-nav">
          {[
            { id: 'list', label: loaded ? `Abbreviations (${totalCount})` : 'Abbreviations' },
            { id: 'add', label: 'Add New' },
            { id: 'test', label: 'Test Expansion' },
            { id: 'validate', label: 'Validate Terms' }
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => handleTabChange(tab.id as any)}
              className={`tab-button ${activeTab === tab.id ? 'active' : ''}`}
            >
              {tab.label}
              {(tab as any).count !== undefined && tab.id !== 'list' && (
                <span className="ml-2 bg-gray-100 text-gray-600 py-1 px-2 rounded-full text-xs">
                  {(tab as any).count}
                </span>
              )}
            </button>
          ))}
        </nav>
      </div>

      <div className="tab-content">
        {/* Abbreviations List Tab */}
        {activeTab === 'list' && (
          <div>
            <div className="mb-6">
              <h3 className="text-lg font-medium">Abbreviation Dictionary</h3>
            </div>

            {/* Search Component */}
            <div className="abbreviation-search" style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
              <div style={{ flex: 1 }}>
                <ProfessionalSearchInput
                  placeholder="Search abbreviations..."
                  data={searchData}
                  onSelect={(item: any) => {
                    devDebug('[AbbreviationManager] Selected:', item);
                    setSearchQuery(item.text); // Trigger search
                  }}
                  onSearch={(query) => setSearchQuery(query)}
                />
              </div>
              <button
                onClick={() => handleTabChange('add')}
                className="form-button-primary"
                style={{
                  padding: '8px 16px',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '6px',
                  whiteSpace: 'nowrap',
                  height: '42px', // Match search input height
                }}
              >
                <span style={{ fontSize: '18px', lineHeight: 1 }}>+</span> Add New
              </button>
              <button
                onClick={() => {
                  const format = window.confirm('Export as CSV? (Cancel for JSON)') ? 'csv' : 'json';
                  const url = `/api/abbreviations/export?format=${format}`;
                  window.location.href = url;
                }}
                title="Export abbreviations"
                style={{
                  padding: '10px 20px',
                  backgroundColor: '#4CAF50',
                  border: '1px solid #45a049',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  fontSize: '14px',
                  fontWeight: '500',
                  color: 'white',
                  whiteSpace: 'nowrap',
                  transition: 'all 0.2s',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '6px',
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.backgroundColor = '#45a049';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.backgroundColor = '#4CAF50';
                }}
              >
                <span style={{ fontSize: '16px' }}>📥</span> Export
              </button>
              {searchQuery && (
                <button
                  onClick={() => setSearchQuery('')}
                  title="Clear search"
                  style={{
                    padding: '10px 20px',
                    backgroundColor: '#f5f5f5',
                    border: '1px solid #ddd',
                    borderRadius: '6px',
                    cursor: 'pointer',
                    fontSize: '14px',
                    fontWeight: '500',
                    color: '#666',
                    whiteSpace: 'nowrap',
                    transition: 'all 0.2s',
                  }}
                >
                  ✕ Reset
                </button>
              )}
            </div>

            {searchQuery && (
               <div className="search-results-info">
                 Found {totalCount} matching abbreviations
               </div>
            )}

            {loading && !abbreviations.length ? (
              <div className="text-center py-8 text-gray-500">
                Loading abbreviations...
              </div>
            ) : abbreviations.length === 0 ? (
              <div className="empty-state">
                <div className="empty-icon">📚</div>
                <div className="empty-title">
                  {searchQuery ? 'No matching abbreviations' : 'No abbreviations found'}
                </div>
                <div className="empty-description">
                  {searchQuery ? 'Try adjusting your search terms' : 'Add some abbreviations to get started'}
                </div>
              </div>
            ) : (
              <div className="abbreviations-list">
                {abbreviations.map((abbrev) => (
                  <div key={abbrev.id} className="abbreviation-card">
                    <div className="abbreviation-header">
                      <div className="abbreviation-main">
                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                          <div className="abbreviation-term">
                            {abbrev.abbreviation}
                          </div>
                          {abbrev.is_core ? (
                            <span 
                              style={{
                                padding: '2px 8px',
                                backgroundColor: '#e3f2fd',
                                color: '#1976d2',
                                borderRadius: '4px',
                                fontSize: '11px',
                                fontWeight: '600',
                                textTransform: 'uppercase',
                                letterSpacing: '0.5px',
                              }}
                              title="Core abbreviation - managed by Uisce, available to all tenants (read-only)"
                            >
                              CORE
                            </span>
                          ) : (
                            <span 
                              style={{
                                padding: '2px 8px',
                                backgroundColor: '#f3e5f5',
                                color: '#7b1fa2',
                                borderRadius: '4px',
                                fontSize: '11px',
                                fontWeight: '600',
                                textTransform: 'uppercase',
                                letterSpacing: '0.5px',
                              }}
                              title="Custom abbreviation - specific to your tenant"
                            >
                              CUSTOM
                            </span>
                          )}
                        </div>
                        <div className="abbreviation-expansion">
                          {abbrev.full_word}
                        </div>
                        {abbrev.notes && (
                          <div className="abbreviation-notes">
                            {abbrev.notes}
                          </div>
                        )}
                      </div>
                      <div className="abbreviation-actions">
                        {(!abbrev.is_core || abbrev.tenant_id === tenantId) && (
                          <>
                            <button 
                              className="abbreviation-action-btn"
                              onClick={() => handleEditAbbreviation(abbrev)}
                              title="Edit abbreviation"
                            >
                              ✏️
                            </button>
                            <button 
                              className="abbreviation-action-btn"
                              onClick={() => handleDeleteAbbreviation(abbrev.id)}
                              title="Delete abbreviation"
                            >
                              🗑️
                            </button>
                          </>
                        )}
                        {abbrev.is_core && abbrev.tenant_id !== tenantId && (
                          <span 
                            style={{ 
                              fontSize: '12px', 
                              color: '#999',
                              fontStyle: 'italic',
                              padding: '4px 8px',
                            }}
                            title="Core abbreviations cannot be edited or deleted"
                          >
                            Read-only
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                ))}

                {/* Load More Button */}
                {hasMore && (
                  <div className="load-more-container text-center py-4">
                    <button 
                      onClick={loadMore}
                      disabled={loading}
                      style={{
                        padding: '10px 20px',
                        backgroundColor: '#f0f0f0',
                        border: '1px solid #ddd',
                        borderRadius: '6px',
                        cursor: loading ? 'not-allowed' : 'pointer',
                        color: '#444'
                      }}
                    >
                      {loading ? 'Loading...' : 'Load More'}
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {/* Add New Tab */}
        {activeTab === 'add' && (
          <div>
            <h3 className="text-lg font-medium mb-4">Add New Abbreviation</h3>
            <form onSubmit={handleAddAbbreviation} className="abbreviation-form">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="form-group">
                  <label className="form-label">
                    Abbreviation *
                  </label>
                  <input
                    type="text"
                    value={newAbbreviation}
                    onChange={(e) => setNewAbbreviation(e.target.value.toUpperCase())}
                    placeholder="e.g., TXN, ACCT, CUST"
                    className="form-input"
                    required
                  />
                </div>
                <div className="form-group">
                  <label className="form-label">
                    Full Word *
                  </label>
                  <input
                    type="text"
                    value={newFullWord}
                    onChange={(e) => setNewFullWord(e.target.value.toUpperCase())}
                    placeholder="e.g., TRANSACTION, ACCOUNT, CUSTOMER"
                    className="form-input"
                    required
                  />
                </div>
              </div>
              <div className="form-group">
                <label className="form-label">
                  Notes (Optional)
                </label>
                <textarea
                  value={newNotes}
                  onChange={(e) => setNewNotes(e.target.value)}
                  placeholder="Additional context or usage notes..."
                  rows={3}
                  className="form-textarea"
                />
              </div>
              <button
                type="submit"
                className="form-button-primary"
              >
                Add Abbreviation
              </button>
            </form>
          </div>
        )}

        {/* Test Expansion Tab */}
        {activeTab === 'test' && (
          <div className="test-section">
            <div className="test-header">
              <h3 className="test-title">Test Abbreviation Expansion</h3>
            </div>

            <div className="test-input-group">
              <input
                type="text"
                value={testColumn}
                onChange={(e) => setTestColumn(e.target.value)}
                placeholder="e.g., CUST_ID, TXN_AMT, ACCT_BAL"
                className="test-input"
              />
              <button
                onClick={handleTestExpansion}
                className="test-button"
              >
                Test
              </button>
            </div>

            {expansionResult && (
              <div className="test-results">
                <h4 className="result-label">Expansion Results:</h4>
                <div className="space-y-2">
                  <div className="result-item">
                    <div className="result-label">Original:</div>
                    <div className="result-value">{expansionResult.column_name}</div>
                  </div>
                  <div className="result-item">
                    <div className="result-label">Variations:</div>
                    <ul className="ml-4 mt-1">
                      {expansionResult.variations.map((variation: string, idx: number) => (
                        <li key={idx} className="result-value">{variation}</li>
                      ))}
                    </ul>
                  </div>
                  {expansionResult.expansions && (
                    <div className="result-item">
                      <div className="result-label">Expansions:</div>
                      <div className="result-value">{expansionResult.expansions}</div>
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        )}

        {/* Validate Terms Tab */}
        {activeTab === 'validate' && (
          <div className="test-section">
            <div className="test-header">
              <h3 className="test-title">Validate Semantic Terms</h3>
            </div>

            <div className="form-group">
              <label className="form-label">
                Semantic Term Names (comma-separated)
              </label>
              <textarea
                value={testTerms}
                onChange={(e) => setTestTerms(e.target.value)}
                placeholder="e.g., CUSTOMER_ID, TXN_AMT, ACCT_BALANCE, CUST_NAME"
                rows={3}
                className="form-textarea"
              />
              <button
                onClick={handleValidateTerms}
                className="test-button"
              >
                Validate Terms
              </button>
            </div>

            {validationResult && (
              <div className="test-results">
                <h4 className="result-label">Validation Results:</h4>
                <div className="space-y-3">
                  <div className="grid grid-cols-3 gap-4 text-center">
                    <div className="result-item bg-green-50 text-green-800">
                      <div className="result-label">Valid Terms</div>
                      <div className="text-lg font-bold">{validationResult.valid_terms}</div>
                    </div>
                    <div className="result-item bg-red-50 text-red-800">
                      <div className="result-label">With Abbreviations</div>
                      <div className="text-lg font-bold">
                        {Object.keys(validationResult.violations).length}
                      </div>
                    </div>
                    <div className="result-item bg-blue-50 text-blue-800">
                      <div className="result-label">Total Terms</div>
                      <div className="text-lg font-bold">{validationResult.total_terms}</div>
                    </div>
                  </div>

                  {Object.keys(validationResult.violations).length > 0 && (
                    <div>
                      <h5 className="result-label text-red-800 mb-2">Terms with Abbreviations:</h5>
                      <div className="space-y-2">
                        {Object.entries(validationResult.violations).map(([term, violations]: [string, any]) => (
                          <div key={term} className="result-item bg-red-50 border-l-4 border-red-400">
                            <div className="result-value text-red-900">{term}</div>
                            <div className="text-red-700 text-xs mt-1">
                              Found abbreviations: {Array.isArray(violations) ? violations.join(', ') : violations}
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* Edit Modal */}
      {showEditModal && editingAbbreviation && (
        <div className="modal-overlay">
          <div className="modal-content">
            <div className="modal-header">
              <h3 className="modal-title">Edit Abbreviation</h3>
            </div>
            <div className="modal-body">
              <form onSubmit={handleUpdateAbbreviation} className="abbreviation-form">
                <div className="form-group">
                  <label className="form-label">
                    Abbreviation *
                  </label>
                  <input
                    type="text"
                    value={newAbbreviation}
                    onChange={(e) => setNewAbbreviation(e.target.value.toUpperCase())}
                    placeholder="e.g., TXN, ACCT, CUST"
                    className="form-input"
                    required
                  />
                </div>
                <div className="form-group">
                  <label className="form-label">
                    Full Word *
                  </label>
                  <input
                    type="text"
                    value={newFullWord}
                    onChange={(e) => setNewFullWord(e.target.value.toUpperCase())}
                    placeholder="e.g., TRANSACTION, ACCOUNT, CUSTOMER"
                    className="form-input"
                    required
                  />
                </div>
                <div className="form-group">
                  <label className="form-label">
                    Notes (Optional)
                  </label>
                  <textarea
                    value={newNotes}
                    onChange={(e) => setNewNotes(e.target.value)}
                    placeholder="Additional context or usage notes..."
                    className="form-textarea"
                    rows={3}
                  />
                </div>
              </form>
            </div>
            <div className="modal-footer">
              <button
                type="button"
                onClick={handleCloseEditModal}
                className="form-button-secondary"
              >
                Cancel
              </button>
              <button
                type="submit"
                onClick={handleUpdateAbbreviation}
                className="form-button-primary"
              >
                Update Abbreviation
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AbbreviationManager;

import React, { useState, useMemo, useCallback } from 'react';
import {
  useAbbreviations,
  useAbbreviationExpansion,
  useSemanticTermValidation,
} from '../utils/abbreviationApi';
import ProfessionalSearchInput from './ProfessionalSearchInput';
import { devDebug, devError } from '../utils/devLogger';
import { useConfirm } from './ConfirmProvider';
import { useNotification } from '../hooks/useNotification';
import { useTenant } from '../contexts/TenantContext';
import {
  Box,
  Button,
  Card,
  Chip,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Divider,
  Drawer,
  FormHelperText,
  Grid,
  IconButton,
  Paper,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TableSortLabel,
  TextField,
  ToggleButton,
  ToggleButtonGroup,
  Tooltip,
  Typography,
} from '@mui/material';
import {
  Add as AddIcon,
  GridView as CardViewIcon,
  Delete as DeleteIcon,
  Download as DownloadIcon,
  Edit as EditIcon,
  TableChart as TableViewIcon,
} from '@mui/icons-material';
import './AbbreviationManager.css';

type SortField = 'abbreviation' | 'full_word';
type SortOrder = 'asc' | 'desc';
type ViewMode = 'table' | 'card';
type FilterType = 'all' | 'core' | 'custom';

interface AbbreviationManagerProps {
  className?: string;
  tenantId?: string;
}

export const AbbreviationManager: React.FC<AbbreviationManagerProps> = ({
  className = '',
  tenantId: propsTenantId,
}) => {
  const { tenant } = useTenant();
  const tenantId = propsTenantId || tenant?.id;

  const {
    abbreviations,
    loading,
    error,
    loaded,
    fetchAbbreviations,
    addAbbreviation,
    updateAbbreviation,
    deleteAbbreviation,
    totalCount,
    hasMore,
    loadMore,
    searchAbbreviations,
  } = useAbbreviations(tenantId);
  const { expandColumn } = useAbbreviationExpansion();
  const { validateTerms } = useSemanticTermValidation();

  // State management
  const [newAbbreviation, setNewAbbreviation] = useState('');
  const [newFullWord, setNewFullWord] = useState('');
  const [newNotes, setNewNotes] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [testColumn, setTestColumn] = useState('');
  const [testTerms, setTestTerms] = useState('');
  const [expansionResult, setExpansionResult] = useState<any>(null);
  const [validationResult, setValidationResult] = useState<any>(null);
  const [activeTab, setActiveTab] = useState<'list' | 'add' | 'test' | 'validate'>('list');
  const [viewMode, setViewMode] = useState<ViewMode>('table');
  const [filterType, setFilterType] = useState<FilterType>('all');
  const [sortField, setSortField] = useState<SortField>('abbreviation');
  const [sortOrder, setSortOrder] = useState<SortOrder>('asc');
  const [sidebarOpen, setSidebarOpen] = useState(true);

  // Edit state
  const [editingAbbreviation, setEditingAbbreviation] = useState<any>(null);
  const [showEditModal, setShowEditModal] = useState(false);

  // Calculate facet counts
  const facetCounts = useMemo(() => {
    if (!abbreviations) return { core: 0, custom: 0, all: 0 };
    const core = abbreviations.filter((a: any) => a.is_core).length;
    const custom = abbreviations.filter((a: any) => !a.is_core).length;
    return { core, custom, all: abbreviations.length };
  }, [abbreviations]);

  // Filter and sort abbreviations
  const filteredAndSorted = useMemo(() => {
    let filtered = abbreviations || [];

    // Apply type filter
    if (filterType === 'core') {
      filtered = filtered.filter((a: any) => a.is_core);
    } else if (filterType === 'custom') {
      filtered = filtered.filter((a: any) => !a.is_core);
    }

    // Sort
    const sorted = [...filtered].sort((a: any, b: any) => {
      let aVal = a[sortField];
      let bVal = b[sortField];

      if (typeof aVal === 'string') aVal = aVal.toLowerCase();
      if (typeof bVal === 'string') bVal = bVal.toLowerCase();

      if (aVal < bVal) return sortOrder === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortOrder === 'asc' ? 1 : -1;
      return 0;
    });

    return sorted;
  }, [abbreviations, filterType, sortField, sortOrder]);

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('asc');
    }
  };

  // Debounced search
  React.useEffect(() => {
    const timer = setTimeout(() => {
      searchAbbreviations(searchQuery);
    }, 400);
    return () => clearTimeout(timer);
  }, [searchQuery, searchAbbreviations]);

  const handleTabChange = useCallback(
    (tabId: 'list' | 'add' | 'test' | 'validate') => {
      setActiveTab(tabId);
      if (tabId === 'list' && !loaded) {
        fetchAbbreviations();
      }
    },
    [loaded, fetchAbbreviations]
  );

  React.useEffect(() => {
    if (activeTab === 'list' && !loaded) {
      fetchAbbreviations();
    }
  }, [activeTab, loaded, fetchAbbreviations]);

  React.useEffect(() => {
    if (!loaded) fetchAbbreviations();
  }, []);

  const searchData = useMemo(
    () =>
      (abbreviations || []).map((abbrev) => ({
        id: abbrev.id,
        text: abbrev.abbreviation,
        subtext: abbrev.full_word,
      })),
    [abbreviations]
  );

  const handleAddAbbreviation = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newAbbreviation.trim() || !newFullWord.trim()) return;

    const success = await addAbbreviation(
      newAbbreviation.toUpperCase().trim(),
      newFullWord.toUpperCase().trim(),
      newNotes.trim()
    );

    if (success) {
      setNewAbbreviation('');
      setNewFullWord('');
      setNewNotes('');
      setActiveTab('list');
    }
  };

  const handleTestExpansion = async () => {
    if (!testColumn.trim()) return;
    try {
      const result = await expandColumn(testColumn.trim());
      setExpansionResult(result);
    } catch (err) {
      devError('Failed to test expansion:', err);
    }
  };

  const handleValidateTerms = async () => {
    if (!testTerms.trim()) return;
    const terms = testTerms.split(',').map((t) => t.trim()).filter((t) => t);
    if (terms.length === 0) return;
    try {
      const result = await validateTerms(terms);
      setValidationResult(result);
    } catch (err) {
      devError('Failed to validate terms:', err);
    }
  };

  const handleEditAbbreviation = (abbrev: any) => {
    setEditingAbbreviation(abbrev);
    setNewAbbreviation(abbrev.abbreviation);
    setNewFullWord(abbrev.full_word);
    setNewNotes(abbrev.notes || '');
    setShowEditModal(true);
  };

  const handleUpdateAbbreviation = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingAbbreviation || !newAbbreviation.trim() || !newFullWord.trim()) return;
    const success = await updateAbbreviation(
      editingAbbreviation.id,
      newAbbreviation.trim(),
      newFullWord.trim(),
      newNotes.trim()
    );
    if (success) {
      setShowEditModal(false);
      setEditingAbbreviation(null);
      setNewAbbreviation('');
      setNewFullWord('');
      setNewNotes('');
      setActiveTab('list');
    }
  };

  const confirm = useConfirm();
  const notification = useNotification();

  const handleDeleteAbbreviation = async (id: number) => {
    if (!(await confirm({ title: 'Delete abbreviation', description: 'Are you sure you want to delete this abbreviation?' })))
      return;
    try {
      await deleteAbbreviation(id);
      notification.success('Abbreviation deleted');
    } catch (err) {
      notification.error('Failed to delete abbreviation');
    }
  };

  const handleCloseEditModal = () => {
    setShowEditModal(false);
    setEditingAbbreviation(null);
    setNewAbbreviation('');
    setNewFullWord('');
    setNewNotes('');
  };

  if (error) {
    return (
      <Box sx={{ p: 4, bgcolor: 'error.50', border: '1px solid', borderColor: 'error.200', borderRadius: 1 }}>
        <Typography color="error">Error: {error}</Typography>
      </Box>
    );
  }

  // Render table view
  const renderTableView = () => (
    <Box sx={{ overflowX: 'auto' }}>
      <Table size="small">
        <TableHead sx={{ backgroundColor: '#fafafa' }}>
          <TableRow>
            <TableCell>
              <TableSortLabel
                active={sortField === 'abbreviation'}
                direction={sortField === 'abbreviation' ? sortOrder : 'asc'}
                onClick={() => handleSort('abbreviation')}
              >
                Abbreviation
              </TableSortLabel>
            </TableCell>
            <TableCell>
              <TableSortLabel active={sortField === 'full_word'} direction={sortField === 'full_word' ? sortOrder : 'asc'} onClick={() => handleSort('full_word')}>
                Full Word
              </TableSortLabel>
            </TableCell>
            <TableCell width={100}>Type</TableCell>
            <TableCell>Notes</TableCell>
            <TableCell width={200} align="right">
              Actions
            </TableCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {filteredAndSorted.map((abbrev: any) => (
            <TableRow key={abbrev.id} hover>
              <TableCell sx={{ fontWeight: 600, fontFamily: 'monospace', fontSize: '0.95rem' }}>
                {abbrev.abbreviation}
              </TableCell>
              <TableCell sx={{ color: 'text.secondary' }}>{abbrev.full_word}</TableCell>
              <TableCell>
                <Chip label={abbrev.is_core ? 'CORE' : 'CUSTOM'} size="small" color={abbrev.is_core ? 'primary' : 'default'} variant={abbrev.is_core ? 'filled' : 'outlined'} />
              </TableCell>
              <TableCell sx={{ maxWidth: 200, overflow: 'hidden', textOverflow: 'ellipsis' }}>{abbrev.notes || '—'}</TableCell>
              <TableCell align="right">
                <Tooltip title={abbrev.tenant_id === tenantId ? 'Edit' : 'Read Only'}>
                  <span>
                    <IconButton
                      size="small"
                      onClick={() => handleEditAbbreviation(abbrev)}
                      disabled={abbrev.tenant_id !== tenantId}
                      color="primary"
                    >
                      <EditIcon fontSize="small" />
                    </IconButton>
                  </span>
                </Tooltip>
                <Tooltip title={abbrev.tenant_id === tenantId ? 'Delete' : 'Read Only'}>
                  <span>
                    <IconButton
                      size="small"
                      onClick={() => handleDeleteAbbreviation(abbrev.id)}
                      disabled={abbrev.tenant_id !== tenantId}
                      color="error"
                    >
                      <DeleteIcon fontSize="small" />
                    </IconButton>
                  </span>
                </Tooltip>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </Box>
  );

  // Render card view
  const renderCardView = () => (
    <Grid container spacing={2}>
      {filteredAndSorted.map((abbrev: any) => (
        <Grid item xs={12} sm={6} md={4} key={abbrev.id}>
          <Card sx={{ display: 'flex', flexDirection: 'column', height: '100%' }} elevation={2}>
            <Box sx={{ p: 2, pb: 1 }}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'start', mb: 1 }}>
                <Typography variant="h6" sx={{ fontWeight: 600, fontFamily: 'monospace', fontSize: '1.1rem' }}>
                  {abbrev.abbreviation}
                </Typography>
                <Chip label={abbrev.is_core ? 'CORE' : 'CUSTOM'} size="small" color={abbrev.is_core ? 'primary' : 'default'} variant={abbrev.is_core ? 'filled' : 'outlined'} />
              </Box>
              <Typography variant="body2" sx={{ color: 'text.secondary', mb: 1 }}>
                {abbrev.full_word}
              </Typography>
              {abbrev.notes && <Typography variant="caption">{abbrev.notes}</Typography>}
            </Box>
            <Divider />
            <Box sx={{ p: 2, display: 'flex', gap: 0.5, justifyContent: 'flex-end' }}>
              <Tooltip title={abbrev.tenant_id === tenantId ? 'Edit' : 'Read Only'}>
                <span>
                  <IconButton
                    size="small"
                    onClick={() => handleEditAbbreviation(abbrev)}
                    disabled={abbrev.tenant_id !== tenantId}
                    color="primary"
                  >
                    <EditIcon fontSize="small" />
                  </IconButton>
                </span>
              </Tooltip>
              <Tooltip title={abbrev.tenant_id === tenantId ? 'Delete' : 'Read Only'}>
                <span>
                  <IconButton
                    size="small"
                    onClick={() => handleDeleteAbbreviation(abbrev.id)}
                    disabled={abbrev.tenant_id !== tenantId}
                    color="error"
                  >
                    <DeleteIcon fontSize="small" />
                  </IconButton>
                </span>
              </Tooltip>
            </Box>
          </Card>
        </Grid>
      ))}
    </Grid>
  );

  return (
    <Box sx={{ display: 'flex', height: '100%', bgcolor: '#fafafa' }}>
      {/* Sidebar with Facets */}
      <Drawer variant="permanent" sx={{ width: sidebarOpen ? 280 : 0, transition: 'all 0.3s', overflow: 'hidden' }} PaperProps={{ sx: { position: 'relative', width: 280, pt: 2 } }}>
        <Box sx={{ px: 2 }}>
          <Typography variant="subtitle2" sx={{ fontWeight: 600, textTransform: 'uppercase', fontSize: '0.75rem', color: 'text.secondary', mb: 2 }}>
            Type
          </Typography>
          <Stack spacing={1}>
            {[
              { key: 'all', label: 'All', count: facetCounts.all },
              { key: 'core', label: 'Core', count: facetCounts.core },
              { key: 'custom', label: 'Custom', count: facetCounts.custom },
            ].map((facet) => (
              <Button
                key={facet.key}
                variant={filterType === facet.key ? 'contained' : 'text'}
                fullWidth
                onClick={() => setFilterType(facet.key as FilterType)}
                sx={{
                  justifyContent: 'space-between',
                  textTransform: 'none',
                  fontWeight: filterType === facet.key ? 600 : 400,
                }}
              >
                <span>{facet.label}</span>
                <Chip label={facet.count} size="small" variant="outlined" sx={{ ml: 1 }} />
              </Button>
            ))}
          </Stack>
        </Box>
      </Drawer>

      {/* Main Content */}
      <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', p: 3 }}>
        {/* Header */}
        <Box sx={{ mb: 3 }}>
          <Typography variant="h5" sx={{ fontWeight: 600, mb: 3 }}>
            Abbreviations
          </Typography>

          {/* Tab Navigation */}
          <Paper sx={{ display: 'flex', gap: 1, p: 1, mb: 3 }}>
            {[
              { id: 'list', label: loaded ? `List (${totalCount})` : 'List' },
              { id: 'add', label: 'Add New' },
              { id: 'test', label: 'Test Expansion' },
              { id: 'validate', label: 'Validate Terms' },
            ].map((tab) => (
              <Button
                key={tab.id}
                onClick={() => handleTabChange(tab.id as any)}
                variant={activeTab === tab.id ? 'contained' : 'outlined'}
                sx={{ textTransform: 'none' }}
              >
                {tab.label}
              </Button>
            ))}
          </Paper>
        </Box>

        {/* List Tab */}
        {activeTab === 'list' && (
          <>
            {/* Search and Controls */}
            <Paper sx={{ p: 2, mb: 3 }}>
              <Box sx={{ display: 'flex', gap: 1, alignItems: 'center', justifyContent: 'space-between' }}>
                <TextField
                  placeholder="Search abbreviations..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  size="small"
                  sx={{ flex: 1, maxWidth: 400 }}
                />
                <Box sx={{ display: 'flex', gap: 0.5, alignItems: 'center' }}>
                  <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                    {filteredAndSorted.length}
                  </Typography>
                  <ToggleButtonGroup value={viewMode} exclusive onChange={(e, newVal) => newVal && setViewMode(newVal)} size="small">
                    <ToggleButton value="table" title="Table view">
                      <TableViewIcon fontSize="small" />
                    </ToggleButton>
                    <ToggleButton value="card" title="Card view">
                      <CardViewIcon fontSize="small" />
                    </ToggleButton>
                  </ToggleButtonGroup>
                  <Tooltip title="Add new abbreviation">
                    <IconButton size="small" onClick={() => handleTabChange('add')} color="primary">
                      <AddIcon fontSize="small" />
                    </IconButton>
                  </Tooltip>
                  <Tooltip title="Export">
                    <IconButton
                      size="small"
                      onClick={() => {
                        const format = window.confirm('Export as CSV? (Cancel for JSON)') ? 'csv' : 'json';
                        const url = `/api/abbreviations/export?format=${format}`;
                        window.location.href = url;
                      }}
                    >
                      <DownloadIcon fontSize="small" />
                    </IconButton>
                  </Tooltip>
                </Box>
              </Box>
            </Paper>

            {/* Content */}
            {loading && !abbreviations?.length ? (
              <CircularProgress sx={{ mx: 'auto' }} />
            ) : filteredAndSorted.length === 0 ? (
              <Box sx={{ textAlign: 'center', py: 6 }}>
                <Typography color="text.secondary">
                  {searchQuery ? 'No matching abbreviations' : 'No abbreviations found'}
                </Typography>
              </Box>
            ) : viewMode === 'table' ? (
              renderTableView()
            ) : (
              renderCardView()
            )}

            {/* Load More */}
            {hasMore && (
              <Box sx={{ display: 'flex', justifyContent: 'center', mt: 3 }}>
                <Button variant="outlined" onClick={loadMore} disabled={loading}>
                  {loading ? <CircularProgress size={20} /> : 'Load More'}
                </Button>
              </Box>
            )}
          </>
        )}

        {/* Add New Tab */}
        {activeTab === 'add' && (
          <Box>
            <Typography variant="h6" sx={{ mb: 3 }}>
              Add New Abbreviation
            </Typography>
            <Paper sx={{ p: 3, maxWidth: 600 }}>
              <Stack spacing={2}>
                <TextField
                  label="Abbreviation"
                  value={newAbbreviation}
                  onChange={(e) => setNewAbbreviation(e.target.value.toUpperCase())}
                  placeholder="e.g., TXN"
                  fullWidth
                  required
                />
                <TextField
                  label="Full Word"
                  value={newFullWord}
                  onChange={(e) => setNewFullWord(e.target.value.toUpperCase())}
                  placeholder="e.g., TRANSACTION"
                  fullWidth
                  required
                />
                <TextField
                  label="Notes"
                  value={newNotes}
                  onChange={(e) => setNewNotes(e.target.value)}
                  placeholder="Additional context..."
                  multiline
                  rows={3}
                  fullWidth
                />
                <Stack direction="row" spacing={2}>
                  <Button variant="contained" onClick={handleAddAbbreviation} disabled={!newAbbreviation.trim() || !newFullWord.trim()}>
                    Add Abbreviation
                  </Button>
                  <Button variant="outlined" onClick={() => { setNewAbbreviation(''); setNewFullWord(''); setNewNotes(''); }}>
                    Clear
                  </Button>
                </Stack>
              </Stack>
            </Paper>
          </Box>
        )}

        {/* Test Tab */}
        {activeTab === 'test' && (
          <Box>
            <Typography variant="h6" sx={{ mb: 3 }}>
              Test Abbreviation Expansion
            </Typography>
            <Paper sx={{ p: 3, maxWidth: 600 }}>
              <Stack spacing={2}>
                <TextField
                  label="Column Name"
                  value={testColumn}
                  onChange={(e) => setTestColumn(e.target.value)}
                  placeholder="e.g., CUST_ID"
                  fullWidth
                />
                <Button variant="contained" onClick={handleTestExpansion} disabled={!testColumn.trim()}>
                  Test Expansion
                </Button>
                {expansionResult && (
                  <Box sx={{ mt: 2, p: 2, bgcolor: 'info.50', borderRadius: 1 }}>
                    <Typography variant="subtitle2" sx={{ mb: 1 }}>
                      Results:
                    </Typography>
                    <Typography variant="body2">
                      <strong>Original:</strong> {expansionResult.column_name}
                    </Typography>
                    {expansionResult.variations && (
                      <Typography variant="body2">
                        <strong>Variations:</strong> {expansionResult.variations.join(', ')}
                      </Typography>
                    )}
                  </Box>
                )}
              </Stack>
            </Paper>
          </Box>
        )}

        {/* Validate Tab */}
        {activeTab === 'validate' && (
          <Box>
            <Typography variant="h6" sx={{ mb: 3 }}>
              Validate Semantic Terms
            </Typography>
            <Paper sx={{ p: 3, maxWidth: 600 }}>
              <Stack spacing={2}>
                <TextField
                  label="Semantic Terms"
                  value={testTerms}
                  onChange={(e) => setTestTerms(e.target.value)}
                  placeholder="e.g., CUSTOMER_ID, TXN_AMT"
                  multiline
                  rows={4}
                  fullWidth
                  helperText="Enter terms separated by commas"
                />
                <Button variant="contained" onClick={handleValidateTerms} disabled={!testTerms.trim()}>
                  Validate Terms
                </Button>
                {validationResult && (
                  <Box sx={{ mt: 2, p: 2, bgcolor: 'info.50', borderRadius: 1 }}>
                    <Typography variant="subtitle2" sx={{ mb: 2 }}>
                      Validation Results:
                    </Typography>
                    <Grid container spacing={2}>
                      <Grid item xs={6}>
                        <Box sx={{ p: 1, bgcolor: 'success.50', borderRadius: 1 }}>
                          <Typography variant="caption">Valid Terms</Typography>
                          <Typography variant="h6">{validationResult.valid_terms}</Typography>
                        </Box>
                      </Grid>
                      <Grid item xs={6}>
                        <Box sx={{ p: 1, bgcolor: 'error.50', borderRadius: 1 }}>
                          <Typography variant="caption">With Abbreviations</Typography>
                          <Typography variant="h6">{Object.keys(validationResult.violations || {}).length}</Typography>
                        </Box>
                      </Grid>
                    </Grid>
                  </Box>
                )}
              </Stack>
            </Paper>
          </Box>
        )}
      </Box>

      {/* Edit Modal */}
      <Dialog open={showEditModal} onClose={handleCloseEditModal} maxWidth="sm" fullWidth>
        <DialogTitle>Edit Abbreviation</DialogTitle>
        <DialogContent>
          <Stack spacing={2} sx={{ mt: 2 }}>
            <TextField
              label="Abbreviation"
              value={newAbbreviation}
              onChange={(e) => setNewAbbreviation(e.target.value.toUpperCase())}
              fullWidth
              required
            />
            <TextField
              label="Full Word"
              value={newFullWord}
              onChange={(e) => setNewFullWord(e.target.value.toUpperCase())}
              fullWidth
              required
            />
            <TextField label="Notes" value={newNotes} onChange={(e) => setNewNotes(e.target.value)} multiline rows={3} fullWidth />
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseEditModal}>Cancel</Button>
          <Button variant="contained" onClick={handleUpdateAbbreviation}>
            Update
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default AbbreviationManager;

import React, { useState } from 'react';
import { 
  Box, 
  Button, 
  Typography, 
  Stepper, 
  Step, 
  StepLabel, 
  Paper, 
  CircularProgress,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  Checkbox,
  TextField,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Alert
} from '@mui/material';
import AutoFixHighIcon from '@mui/icons-material/AutoFixHigh';
import SearchIcon from '@mui/icons-material/Search';
import SaveIcon from '@mui/icons-material/Save';
import { useAbbreviationWizard, useAbbreviations, SuggestionResult } from '../utils/abbreviationApi';

// Step definitions
const STEPS = ['Scan Database', 'Review Candidates', 'Get Suggestions', 'Final Review'];

interface AbbreviationWizardProps {
  onCompletion?: () => void;
}

export const AbbreviationWizard: React.FC<AbbreviationWizardProps> = ({ onCompletion }) => {
  const [activeStep, setActiveStep] = useState(0);
  const [scannedCandidates, setScannedCandidates] = useState<string[]>([]);
  const [selectedCandidates, setSelectedCandidates] = useState<string[]>([]);
  const [suggestions, setSuggestions] = useState<SuggestionResult>({});
  const [finalReviewData, setFinalReviewData] = useState<{abbr: string, full: string}[]>([]);

  const { scan, suggest, loading: wizardLoading, error: wizardError } = useAbbreviationWizard();
  const { addAbbreviation } = useAbbreviations();
  const [bulkSaveLoading, setBulkSaveLoading] = useState(false);

  // --- Step Handlers ---

  const handleScan = async () => {
    const result = await scan();
    if (result) {
      setScannedCandidates(result.candidates);
      setSelectedCandidates(result.candidates); // Select all by default
      setActiveStep(1);
    }
  };

  const handleSuggest = async () => {
    const result = await suggest(selectedCandidates);
    if (result) {
      setSuggestions(result);
      // Pre-populate final review data
      const reviewData = selectedCandidates.map(abbr => ({
        abbr,
        full: result[abbr] || ''
      }));
      setFinalReviewData(reviewData);
      setActiveStep(3);
    }
  };

  const handleSave = async () => {
    setBulkSaveLoading(true);
    let successCount = 0;

    // Filter out items with empty full words
    const itemsToSave = finalReviewData.filter(item => item.full.trim() !== '');

    for (const item of itemsToSave) {
      const success = await addAbbreviation(item.abbr, item.full, 'Added via Wizard');
      if (success) successCount++;
    }

    setBulkSaveLoading(false);
    if (onCompletion) onCompletion();
    // Maybe show toast here? "Saved X abbreviations"
  };

  // --- Step Content Renderers ---

  const renderScanStep = () => (
    <Box sx={{ textAlign: 'center', py: 4 }}>
      <SearchIcon sx={{ 
        fontSize: 60, 
        color: wizardLoading ? 'primary.main' : 'text.secondary', 
        mb: 2,
        animation: wizardLoading ? 'spin 2s linear infinite' : 'none',
        '@keyframes spin': {
          '0%': { transform: 'rotate(0deg)' },
          '100%': { transform: 'rotate(360deg)' },
        },
      }} />
      <Typography variant="h6" gutterBottom>
        Scan Database for Abbreviations
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 4 }}>
        This will scan all database columns to identify frequent unknown tokens that might be abbreviations.
      </Typography>
      <Button 
        variant="contained" 
        onClick={handleScan} 
        disabled={wizardLoading}
        startIcon={wizardLoading ? <CircularProgress size={20} /> : <SearchIcon />}
      >
        {wizardLoading ? 'Scanning...' : 'Start Scan'}
      </Button>
      {wizardError && <Alert severity="error" sx={{ mt: 2 }}>{wizardError}</Alert>}
    </Box>
  );

  const renderReviewCandidatesStep = () => (
    <Box>
      <Typography variant="subtitle1" gutterBottom>
        Found {scannedCandidates.length} potential abbreviations. Select the ones you want to process.
      </Typography>
      <Paper variant="outlined" sx={{ maxHeight: 400, overflow: 'auto', mb: 2 }}>
        <List dense>
          {scannedCandidates.map((abbr) => {
             const labelId = `checkbox-list-label-${abbr}`;
             return (
               <ListItem
                 key={abbr}
                 button
                 onClick={() => {
                   const currentIndex = selectedCandidates.indexOf(abbr);
                   const newChecked = [...selectedCandidates];
                   if (currentIndex === -1) {
                     newChecked.push(abbr);
                   } else {
                     newChecked.splice(currentIndex, 1);
                   }
                   setSelectedCandidates(newChecked);
                 }}
               >
                 <ListItemIcon>
                   <Checkbox
                     edge="start"
                     checked={selectedCandidates.indexOf(abbr) !== -1}
                     tabIndex={-1}
                     disableRipple
                     inputProps={{ 'aria-labelledby': labelId }}
                   />
                 </ListItemIcon>
                 <ListItemText id={labelId} primary={abbr} />
               </ListItem>
             );
          })}
        </List>
      </Paper>
      <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1 }}>
        <Button onClick={() => setActiveStep(0)}>Back</Button>
        <Button 
          variant="contained" 
          onClick={() => setActiveStep(2)}
          disabled={selectedCandidates.length === 0}
        >
          Next
        </Button>
      </Box>
    </Box>
  );

  const renderGetSuggestionsStep = () => (
    <Box sx={{ textAlign: 'center', py: 4 }}>
      <AutoFixHighIcon sx={{ 
        fontSize: 60, 
        color: 'primary.main', 
        mb: 2,
        animation: wizardLoading ? 'glow 1.5s ease-in-out infinite' : 'none',
        '@keyframes glow': {
          '0%, 100%': { filter: 'brightness(1)' },
          '50%': { filter: 'brightness(1.5)' },
        },
      }} />
      <Typography variant="h6" gutterBottom>
        Generate AI Suggestions
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 4 }}>
        Using AI to suggest full word expansions for {selectedCandidates.length} selected abbreviations...
      </Typography>
      <Button 
        variant="contained" 
        onClick={handleSuggest} 
        disabled={wizardLoading}
        startIcon={wizardLoading ? <CircularProgress size={20} /> : <AutoFixHighIcon />}
      >
        {wizardLoading ? 'Generating...' : 'Generate Suggestions'}
      </Button>
      {wizardError && <Alert severity="error" sx={{ mt: 2 }}>{wizardError}</Alert>}
      <Box sx={{ mt: 2 }}>
        <Button onClick={() => setActiveStep(1)} disabled={wizardLoading}>Back</Button>
      </Box>
    </Box>
  );

  const renderFinalReviewStep = () => (
    <Box>
      <Typography variant="subtitle1" gutterBottom>
        Review and edit the suggested expansions before saving.
      </Typography>
      <TableContainer component={Paper} variant="outlined" sx={{ maxHeight: 400, mb: 2 }}>
        <Table stickyHeader size="small">
          <TableHead>
            <TableRow>
              <TableCell>Abbreviation</TableCell>
              <TableCell>Full Word (Editable)</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {finalReviewData.map((row, index) => (
              <TableRow key={row.abbr}>
                <TableCell>{row.abbr}</TableCell>
                <TableCell>
                  <TextField 
                    fullWidth 
                    variant="standard" 
                    value={row.full} 
                    onChange={(e) => {
                      const newData = [...finalReviewData];
                      newData[index].full = e.target.value.toUpperCase();
                      setFinalReviewData(newData);
                    }}
                    placeholder="Enter full word..."
                  />
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1 }}>
        <Button onClick={() => setActiveStep(2)} disabled={bulkSaveLoading}>Back</Button>
        <Button 
          variant="contained" 
          onClick={handleSave}
          disabled={bulkSaveLoading}
          startIcon={bulkSaveLoading ? <CircularProgress size={20} /> : <SaveIcon />}
        >
          {bulkSaveLoading ? 'Saving...' : 'Save All'}
        </Button>
      </Box>
    </Box>
  );

  return (
    <Box sx={{ width: '100%', p: 2 }}>
      <Stepper activeStep={activeStep} alternativeLabel sx={{ mb: 4 }}>
        {STEPS.map((label, index) => (
          <Step key={label} completed={index < activeStep}>
            <StepLabel 
              sx={{
                '& .MuiStepLabel-label': {
                  color: index === activeStep ? 'primary.main' : index < activeStep ? 'success.main' : 'text.secondary',
                  fontWeight: index === activeStep ? 'bold' : 'normal',
                },
                '& .MuiStepIcon-root': {
                  color: index < activeStep ? 'success.main' : undefined,
                  '&.Mui-active': {
                    color: 'primary.main',
                    animation: 'pulse 1.5s ease-in-out infinite',
                  },
                },
                '@keyframes pulse': {
                  '0%, 100%': { transform: 'scale(1)' },
                  '50%': { transform: 'scale(1.1)' },
                },
              }}
            >
              {label}
            </StepLabel>
          </Step>
        ))}
      </Stepper>

      {activeStep === 0 && renderScanStep()}
      {activeStep === 1 && renderReviewCandidatesStep()}
      {activeStep === 2 && renderGetSuggestionsStep()}
      {activeStep === 3 && renderFinalReviewStep()}
    </Box>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Typography,
  Box,
  CircularProgress,
  Alert,
  TextField,
  Autocomplete,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  Chip,
  FormControlLabel,
  Checkbox
} from '@mui/material';
import {
  AddLink as AddLinkIcon,
  Description as TermIcon,
  TableChart as TableIcon,
  ViewColumn as ColumnIcon,
  Label as TagIcon
} from '@mui/icons-material';
import { useEdgeTypes } from '../api/edgeTypes';
import { useNodeTypes } from '../api/nodeTypes';
import { useCreateTermEdge } from '../api/glossary';
import { useTenant } from '../contexts/TenantContext';
import { LineageService } from '../services/lineageService';

interface AddEdgeDialogProps {
  open: boolean;
  onClose: () => void;
  sourceNodeId: string;
  sourceNodeType: string; // 'business_term', 'semantic_term', 'column', 'table' etc.
  onEdgeAdded?: () => void;
}

const AddEdgeDialog: React.FC<AddEdgeDialogProps> = ({
  open,
  onClose,
  sourceNodeId,
  sourceNodeType,
  onEdgeAdded
}) => {
  const { tenant, datasource } = useTenant();
  const [selectedEdgeTypeId, setSelectedEdgeTypeId] = useState<string>('');
  const [targetSearchQuery, setTargetSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<any[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [selectedTargetNode, setSelectedTargetNode] = useState<any | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [propertyValues, setPropertyValues] = useState<Record<string, any>>({});

  // APIs
  const { data: edgeTypes, isLoading: loadingEdgeTypes } = useEdgeTypes(tenant?.id || '');
  const { data: nodeTypes } = useNodeTypes(tenant?.id || '');
  const createEdgeMutation = useCreateTermEdge();
  const lineageService = useMemo(() => new LineageService(), []);

  // Helper to map string type to ID
  const getNodeTypeId = (typeName: string) => {
    return nodeTypes?.find(nt => nt.catalog_type_name === typeName)?.id;
  };

  const getNodeTypeName = (typeId: string) => {
    return nodeTypes?.find(nt => nt.id === typeId)?.catalog_type_name;
  };

  // Filter valid edge types for this source
  const validEdgeTypes = useMemo(() => {
    if (!edgeTypes || !nodeTypes) return [];

    const sourceTypeId = getNodeTypeId(sourceNodeType);
    if (!sourceTypeId) return [];

    return (edgeTypes || []).filter(et => {
      if (!et.is_active) return false;
      return et.subject_node_type_id === sourceTypeId || et.object_node_type_id === sourceTypeId;
    });
  }, [edgeTypes, nodeTypes, sourceNodeType]);

  const selectedEdgeType = useMemo(() => 
    edgeTypes?.find(et => et.id === selectedEdgeTypeId),
    [edgeTypes, selectedEdgeTypeId]
  );

  useEffect(() => {
    if (selectedEdgeType?.properties) {
      const initialValues: Record<string, any> = {};
      selectedEdgeType.properties.forEach(prop => {
        initialValues[prop.name] = prop.default_value ?? '';
      });
      setPropertyValues(initialValues);
    } else {
      setPropertyValues({});
    }
  }, [selectedEdgeType]);

  const targetNodeTypeName = useMemo(() => {
    if (!selectedEdgeType) return null;
    const sourceTypeId = getNodeTypeId(sourceNodeType);
    if (!sourceTypeId) return null;

    if (sourceTypeId === selectedEdgeType.subject_node_type_id) {
      return getNodeTypeName(selectedEdgeType.object_node_type_id);
    } else if (sourceTypeId === selectedEdgeType.object_node_type_id) {
      return getNodeTypeName(selectedEdgeType.subject_node_type_id);
    }
    return null;
  }, [selectedEdgeType, sourceNodeType, nodeTypes]);

  const isReversedEdge = useMemo(() => {
    if (!selectedEdgeType) return false;
    const sourceTypeId = getNodeTypeId(sourceNodeType);
    return sourceTypeId === selectedEdgeType.object_node_type_id;
  }, [selectedEdgeType, sourceNodeType, nodeTypes]);

  const debounceTimerRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);

    if (!targetSearchQuery.trim() || !targetNodeTypeName) {
      setSearchResults([]);
      return;
    }

    debounceTimerRef.current = setTimeout(async () => {
      setIsSearching(true);
      setError(null);

      try {
        const isBusinessTerm = targetNodeTypeName.toLowerCase() === 'business_term';
        const isSemanticTerm = targetNodeTypeName.toLowerCase() === 'semantic_term';

        if (isBusinessTerm) {
          const results = await lineageService.searchBusinessTerms({
            query: targetSearchQuery,
            limit: 20
          });
          setSearchResults(results.business_terms || []);
        } else if (isSemanticTerm) {
          const response = await fetch('/api/semantic-terms/search', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'X-Tenant-ID': tenant?.id || '',
              'X-Tenant-Datasource-ID': datasource?.id || '',
            },
            body: JSON.stringify({ query: targetSearchQuery, limit: 20 })
          });
          if (response.ok) {
            const data = await response.json();
            setSearchResults(data.semantic_terms || []);
          }
        } else {
          const params = new URLSearchParams({ q: targetSearchQuery, type: targetNodeTypeName, limit: '20' });
          const url = `/api/catalog/nodes?${params.toString()}`;
          const results = await fetch(url, {
             headers: {
               'X-Tenant-ID': tenant?.id || '',
               'X-Tenant-Datasource-ID': datasource?.id || '',
               'Content-Type': 'application/json'
             }
          }).then(res => res.ok ? res.json() : []);
          setSearchResults(results || []);
        }
      } catch (e) {
        console.error('Search failed', e);
        setError('Search failed. Please try again.');
        setSearchResults([]);
      } finally {
        setIsSearching(false);
      }
    }, 300);

    return () => {
      if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
    };
  }, [targetSearchQuery, targetNodeTypeName, tenant?.id, lineageService, datasource?.id]);

  const handleCreate = () => {
    if (!selectedEdgeTypeId || !selectedTargetNode) return;
    const isReversed = isReversedEdge;

    createEdgeMutation.mutate({
      subject_node_id: isReversed ? selectedTargetNode.id : sourceNodeId,
      object_node_id: isReversed ? sourceNodeId : selectedTargetNode.id,
      edge_type_id: selectedEdgeTypeId,
      properties: propertyValues
    }, {
      onSuccess: () => {
        if (onEdgeAdded) onEdgeAdded();
        handleClose();
      },
      onError: (err: any) => {
        setError(err.message || 'Failed to create edge');
      }
    });
  };

  const handleClose = () => {
    setSelectedEdgeTypeId('');
    setTargetSearchQuery('');
    setSearchResults([]);
    setSelectedTargetNode(null);
    setError(null);
    onClose();
  };

  const getIconForType = (type: string) => {
    const lowerType = type.toLowerCase();
    if (lowerType.includes('table')) return <TableIcon fontSize="small" />;
    if (lowerType.includes('column')) return <ColumnIcon fontSize="small" />;
    if (lowerType.includes('term')) return <TermIcon fontSize="small" />;
    return <TermIcon fontSize="small" />;
  };

  return (
    <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
      <DialogTitle>Add Relationship</DialogTitle>
      <DialogContent>
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3, pt: 1 }}>
          {error && <Alert severity="error">{error}</Alert>}

          <FormControl fullWidth size="small">
            <InputLabel>Relationship Type</InputLabel>
            <Select
              value={selectedEdgeTypeId}
              label="Relationship Type"
              onChange={(e) => {
                setSelectedEdgeTypeId(e.target.value);
                setSearchResults([]);
                setSelectedTargetNode(null);
              }}
            >
              {validEdgeTypes.map(et => {
                const sourceTypeId = getNodeTypeId(sourceNodeType);
                const isReversed = sourceTypeId === et.object_node_type_id;
                const targetTypeId = isReversed ? et.subject_node_type_id : et.object_node_type_id;
                const targetTypeName = getNodeTypeName(targetTypeId);
                const arrow = isReversed ? '←' : '→';
                return (
                  <MenuItem key={et.id} value={et.id}>
                    {et.edge_type_name} {arrow} {targetTypeName}
                  </MenuItem>
                );
              })}
            </Select>
          </FormControl>

          {selectedEdgeTypeId && targetNodeTypeName && (
            <Box>
              <Typography variant="subtitle2" gutterBottom>
                Select Target {targetNodeTypeName.replace('_', ' ')}
              </Typography>

              <Autocomplete
                fullWidth
                size="small"
                open={open && targetSearchQuery.length > 0 && !selectedTargetNode}
                options={searchResults}
                loading={isSearching}
                getOptionLabel={(option) => option.node_name || option.name || ''}
                filterOptions={(x) => x}
                onInputChange={(_, newInputValue) => setTargetSearchQuery(newInputValue)}
                onChange={(_, newValue) => setSelectedTargetNode(newValue)}
                value={selectedTargetNode}
                renderInput={(params) => (
                  <TextField
                    {...params}
                    placeholder={`Search ${targetNodeTypeName}s...`}
                    InputProps={{
                      ...params.InputProps,
                      endAdornment: (
                        <>
                          {isSearching ? <CircularProgress color="inherit" size={20} /> : null}
                          {params.InputProps.endAdornment}
                        </>
                      ),
                    }}
                  />
                )}
                renderOption={(props, option) => {
                  const { key, ...optionProps } = props;
                  return (
                    <li key={key} {...optionProps}>
                      <Box sx={{ display: 'flex', flexDirection: 'column', width: '100%' }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          {getIconForType(targetNodeTypeName || '')}
                          <Typography variant="body2" fontWeight={500}>
                            {option.node_name || option.name}
                          </Typography>
                        </Box>
                        {option.qualified_path && (
                          <Typography variant="caption" color="primary">
                            {option.qualified_path}
                          </Typography>
                        )}
                        {option.description && (
                          <Typography variant="caption" color="text.secondary" sx={{ display: 'block', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                            {option.description}
                          </Typography>
                        )}
                      </Box>
                    </li>
                  );
                }}
                noOptionsText={targetSearchQuery && !isSearching ? "No results found" : "Type to search..."}
              />

              {selectedTargetNode && (
                <Box sx={{ mt: 2 }}>
                  <Alert severity="info" action={<Button color="inherit" size="small" onClick={() => setSelectedTargetNode(null)}>Change</Button>}>
                    <Box>
                      <Typography variant="body2">Selected: <strong>{selectedTargetNode.node_name || selectedTargetNode.name}</strong></Typography>
                      {selectedTargetNode.qualified_path && <Typography variant="caption" color="primary">{selectedTargetNode.qualified_path}</Typography>}
                    </Box>
                  </Alert>
                </Box>
              )}
            </Box>
          )}

          {selectedEdgeType?.properties && selectedEdgeType.properties.length > 0 && (
            <Box sx={{ mt: 3 }}>
              <Typography variant="subtitle2" gutterBottom>Edge Properties</Typography>
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                {selectedEdgeType.properties.map((prop) => {
                  const value = propertyValues[prop.name] ?? '';
                  if (prop.input_type === 'textarea' || prop.input_type === 'text') {
                    return <TextField key={prop.name} label={prop.label} value={value} onChange={(e) => setPropertyValues(prev => ({ ...prev, [prop.name]: e.target.value }))} fullWidth size="small" required={!prop.nullable} multiline={prop.input_type === 'textarea'} rows={prop.input_type === 'textarea' ? 3 : 1} helperText={prop.format} />;
                  }
                  if (prop.input_type === 'checkbox') {
                    return <FormControlLabel key={prop.name} control={<Checkbox checked={!!value} onChange={(e) => setPropertyValues(prev => ({ ...prev, [prop.name]: e.target.checked }))} />} label={prop.label} />;
                  }
                  if (prop.input_type === 'select' && prop.options) {
                    return <FormControl key={prop.name} fullWidth size="small" required={!prop.nullable}><InputLabel>{prop.label}</InputLabel><Select value={value} onChange={(e) => setPropertyValues(prev => ({ ...prev, [prop.name]: e.target.value }))} label={prop.label}><MenuItem value=""><em>None</em></MenuItem>{prop.options.map(opt => (<MenuItem key={opt} value={opt}>{opt}</MenuItem>))}</Select></FormControl>;
                  }
                  return <TextField key={prop.name} label={prop.label} value={value} onChange={(e) => setPropertyValues(prev => ({ ...prev, [prop.name]: e.target.value }))} fullWidth size="small" required={!prop.nullable} helperText={prop.format} />;
                })}
              </Box>
            </Box>
          )}
        </Box>
      </DialogContent>
      <DialogActions>
        <Button onClick={handleClose}>Cancel</Button>
        <Button variant="contained" onClick={handleCreate} disabled={!selectedEdgeTypeId || !selectedTargetNode || createEdgeMutation.isPending} startIcon={<AddLinkIcon />}>
          Add Relationship
        </Button>
      </DialogActions>
    </Dialog>
  );
};

