                  onClick={() => setFormData({ ...formData, stepType: st.type })}
                  className={`p-3 rounded-lg border-2 transition-all text-center ${
                    formData.stepType === st.type
                      ? `border-${st.color.split('-')[1]}-600 ${st.bgColor}`
                      : 'border-gray-300 hover:border-gray-400'
                  }`}
                >
                  <st.icon size={20} className="mx-auto mb-1" />
                  <div className="text-xs font-semibold">{st.label}</div>
                </button>
              ))}
            </div>
          </div>

          {/* Step Name */}
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">Step Name *</label>
            <input
              type="text"
              value={formData.stepName}
              onChange={(e) => setFormData({ ...formData, stepName: e.target.value })}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              placeholder="e.g., Verify Employee Information"
            />
          </div>

          {/* Description */}
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">Description</label>
            <textarea
              value={formData.description || ''}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              rows={3}
              placeholder="Add details about this step..."
            />
          </div>

          {/* Duration & Escalation */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2 flex items-center gap-2">
                <Clock size={16} /> Duration (hours)
              </label>
              <input
                type="number"
                min="0.5"
                step="0.5"
                value={formData.durationHours}
                onChange={(e) => setFormData({ ...formData, durationHours: parseFloat(e.target.value) })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                title="Step duration in hours"
                placeholder="1.0"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2 flex items-center gap-2">
                <AlertTriangle size={16} /> Escalation Threshold (hours)
              </label>
              <input
                type="number"
                min="0.5"
                step="0.5"
                value={formData.escalationThresholdHours || 0}
                onChange={(e) => setFormData({ ...formData, escalationThresholdHours: parseFloat(e.target.value) })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                title="Escalation threshold in hours"
                placeholder="2.0"
              />
            </div>
          </div>

          {/* Role Assignment (for approve/notify steps) */}
          {(formData.stepType === 'approve' || formData.stepType === 'notify') && (
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2 flex items-center gap-2">
                <User size={16} /> Assign Role
              </label>
              <select
                value={formData.assigneeRole || ''}
                onChange={(e) => setFormData({ ...formData, assigneeRole: e.target.value })}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                title="Select assignee role"
                aria-label="Select assignee role"
              >
                <option value="">Select a role...</option>
                {AVAILABLE_ROLES.map(role => (
                  <option key={role} value={role}>{role}</option>
                ))}
              </select>
            </div>
          )}

          {/* Validation Rules (for validate steps) */}
          {formData.stepType === 'validate' && (
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2 flex items-center gap-2">
                <CheckCircle size={16} /> Validation Rules
              </label>
              <div className="space-y-2">
                <input
                  type="text"
                  placeholder="e.g., Email format, Non-negative salary"
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  title="Add validation rule"
                  onKeyPress={(e) => {
                    if (e.key === 'Enter' && (e.target as HTMLInputElement).value) {
                      const rule = (e.target as HTMLInputElement).value;
                      setFormData({
                        ...formData,
                        validationRules: [...(formData.validationRules || []), rule]
                      });
                      (e.target as HTMLInputElement).value = '';
                    }
                  }}
                />
                <div className="flex flex-wrap gap-2">
                  {(formData.validationRules || []).map((rule, idx) => (
                    <div key={idx} className="bg-green-100 text-green-700 px-3 py-1 rounded-full text-sm flex items-center gap-2">
                      {rule}
                      <button
                        onClick={() => setFormData({
                          ...formData,
                          validationRules: formData.validationRules?.filter((_, i) => i !== idx)
                        })}
                        className="hover:text-red-600"
                        title="Remove validation rule"
                        aria-label="Remove validation rule"
                      >
                        <X size={14} />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* ========== ADVANCED FEATURES ========== */}

          {/* Parallel Execution */}
          <ParallelExecutionConfig
            executionMode={formData.executionMode}
            parallelGroup={formData.parallelGroup}
            waitForAll={formData.waitForAll}
            onExecutionModeChange={(mode) => setFormData({ ...formData, executionMode: mode })}
            onParallelGroupChange={(group) => setFormData({ ...formData, parallelGroup: group })}
            onWaitForAllChange={(wait) => setFormData({ ...formData, waitForAll: wait })}
          />

          {/* Advanced Conditional Logic (for condition step types) */}
          {formData.stepType === 'condition' && (
            <AdvancedConditionBuilder
              condition={formData.conditionLogic}
              onChange={(condition) => setFormData({ ...formData, conditionLogic: condition })}
              availableFields={availableFields}
              availableSteps={[]} // Will be populated from parent component
            />
          )}

          {/* Approval Chain (for approve step types) */}
          {formData.stepType === 'approve' && (
            <ApprovalChainConfig
              approvalChain={formData.approvalChain}
              onChange={(chain) => setFormData({ ...formData, approvalChain: chain })}
              availableRoles={AVAILABLE_ROLES}
            />
          )}

          {/* Step Dependencies */}
          <StepDependenciesManager
            dependsOn={formData.dependsOn || []}
            skipCondition={formData.skipCondition}
            availableSteps={[]} // Will be populated from parent component
            availableFields={availableFields}
            onDependsOnChange={(deps) => setFormData({ ...formData, dependsOn: deps })}
            onSkipConditionChange={(condition) => setFormData({ ...formData, skipCondition: condition })}
          />
        </div>

        {/* Footer */}
        <div className="bg-gray-50 px-6 py-4 flex justify-end gap-3 border-t">
          <button
            onClick={onCancel}
            className="px-6 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 font-semibold"
          >
            Cancel
          </button>
          <button
            onClick={handleSave}
            className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-semibold flex items-center gap-2"
          >
            <Check size={18} />
            Save Step
          </button>
        </div>
      </div>
    </div>
  );
};

// Canvas View - Visual Workflow Designer
const CanvasView: React.FC<{
  steps: BPStep[];
  onEditStep: (step: BPStep) => void;
  onDeleteStep: (stepId: string) => void;
  onAddStep: () => void;
  onReorderSteps: (steps: BPStep[]) => void;
}> = ({ steps, onEditStep, onDeleteStep, onAddStep, onReorderSteps }) => {
  const [draggedStep, setDraggedStep] = useState<string | null>(null);

  const moveStep = (fromIdx: number, toIdx: number) => {
    const newSteps = [...steps];
    const [movedStep] = newSteps.splice(fromIdx, 1);
    newSteps.splice(toIdx, 0, movedStep);
    newSteps.forEach((step, idx) => step.stepOrder = idx + 1);
    onReorderSteps(newSteps);
  };

  return (
    <div className="space-y-4">
      <div className="bg-gradient-to-r from-blue-50 to-indigo-50 border border-blue-200 rounded-lg p-4">
        <div className="flex items-start gap-3">
          <Workflow className="text-blue-600 flex-shrink-0 mt-0.5" size={20} />
          <div>
            <h4 className="font-semibold text-gray-900">Visual Workflow</h4>
            <p className="text-sm text-gray-600">Drag steps to reorder. Click to edit. Connections show workflow flow.</p>
          </div>
        </div>
      </div>

      <div className="space-y-3">
        {steps.map((step, idx) => {
          const stepType = STEP_TYPES.find(t => t.type === step.stepType)!;
          const IconComponent = stepType.icon;

          return (
            <React.Fragment key={step.id}>
              <div
                draggable
                onDragStart={() => setDraggedStep(step.id)}
                onDragOver={(e) => e.preventDefault()}
                onDrop={() => {
                  const draggedIdx = steps.findIndex(s => s.id === draggedStep);
                  if (draggedIdx !== undefined) {
                    moveStep(draggedIdx, idx);
                  }
                }}
                onDragEnd={() => setDraggedStep(null)}
                className={`${stepType.bgColor} border-2 ${stepType.borderColor} rounded-lg p-4 cursor-move transition-all ${
                  draggedStep === step.id ? 'opacity-50' : ''
                } hover:shadow-md`}
              >
                <div className="flex items-start justify-between gap-4">
                  <div className="flex items-start gap-4 flex-1">
                    <div className={`p-3 bg-gradient-to-br ${stepType.color} text-white rounded-lg flex-shrink-0`}>
                      <IconComponent size={20} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <h4 className="font-semibold text-gray-900">{step.stepName}</h4>
                        <span className={`${stepType.badgeColor} px-2 py-1 rounded text-xs font-semibold whitespace-nowrap`}>
                          Step {step.stepOrder}
                        </span>
                      </div>
                      <p className="text-sm text-gray-600 mt-1">{step.description}</p>
                      <div className="flex items-center gap-4 mt-3 text-sm text-gray-600">
                        {step.durationHours && (
                          <div className="flex items-center gap-1">
                            <Clock size={14} />
                            {step.durationHours}h
                          </div>
                        )}
                        {step.escalationThresholdHours && (
                          <div className="flex items-center gap-1 text-red-600">
                            <AlertTriangle size={14} />
                            Escalate: {step.escalationThresholdHours}h
                          </div>
                        )}
                        {step.assigneeRole && (
                          <div className="flex items-center gap-1">
                            <User size={14} />
                            {step.assigneeRole}
                          </div>
                        )}
                        {(step.validationRules?.length ?? 0) > 0 && (
                          <div className="flex items-center gap-1">
                            <CheckCircle size={14} />
                            {step.validationRules?.length} rules
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-2 flex-shrink-0">
                    <button
                      onClick={() => onEditStep(step)}
                      className="p-2 hover:bg-white hover:bg-opacity-50 rounded-lg transition-all"
                      title="Edit step"
                      aria-label="Edit step"
                    >
                      <Settings size={18} className="text-gray-600" />
                    </button>
                    <button
                      onClick={() => onDeleteStep(step.id)}
                      className="p-2 hover:bg-red-100 rounded-lg transition-all"
                      title="Delete step"
                      aria-label="Delete step"
                    >
                      <Trash2 size={18} className="text-red-600" />
                    </button>
                  </div>
                </div>
              </div>

              {idx < steps.length - 1 && (
                <div className="flex justify-center">
                  <ArrowRight className="text-gray-400 rotate-90" size={20} />
                </div>
              )}
            </React.Fragment>
          );
        })}
      </div>

      <button
        onClick={onAddStep}
        className="w-full p-4 border-2 border-dashed border-blue-300 rounded-lg hover:bg-blue-50 transition-all flex items-center justify-center gap-2 text-blue-600 font-semibold"
      >
        <Plus size={20} />
        Add Step
      </button>
    </div>
  );
};

// Main BP Builder Component
export const BusinessProcessBuilderEnhanced: React.FC = () => {
  const { tenant, datasource } = useTenant();
  const [viewMode, setViewMode] = useState<ViewMode>('canvas');
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' | 'info' } | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [editingStepIndex, setEditingStepIndex] = useState<number | null>(null);
  const [isMaximized, setIsMaximized] = useState(false);
  const [showNLBuilder, setShowNLBuilder] = useState(false);
  const scopeMissing = !tenant?.id || !datasource?.id;

  // API Hooks
  const createBPMutation = useCreateBusinessProcess();
  const updateBPMutation = useUpdateBusinessProcess();
  const _deleteBPMutation = useDeleteBusinessProcess();
  const publishBPMutation = usePublishBusinessProcess();
  const simulateBPMutation = useSimulateBusinessProcess();
  const _duplicateBPMutation = useDuplicateBusinessProcess();

  // Process State
  const [currentProcess, setCurrentProcess] = useState<BusinessProcess>({
    id: '',
    processName: '',
    entity: AVAILABLE_ENTITIES[0],
    description: '',
    steps: [],
    isActive: false,
    createdBy: 'bp_builder_agent',
    createdAt: new Date().toISOString(),
    version: 1,
    tags: [],
  });

  const handleAddStep = () => {
    setEditingStepIndex(currentProcess.steps.length);
  };

  const handleEditStep = (idx: number) => {
    setEditingStepIndex(idx);
  };

  const handleSaveStep = (step: BPStep) => {
    const updatedSteps = [...currentProcess.steps];
    if (editingStepIndex !== null) {
      updatedSteps[editingStepIndex] = { ...step, stepOrder: editingStepIndex + 1 };
    }
    setCurrentProcess({ ...currentProcess, steps: updatedSteps });
    setEditingStepIndex(null);
    setToast({ message: 'Step saved successfully', type: 'success' });
  };

  const handleDeleteStep = (stepId: string) => {
    const updatedSteps = currentProcess.steps.filter(s => s.id !== stepId);
    updatedSteps.forEach((step, idx) => step.stepOrder = idx + 1);
    setCurrentProcess({ ...currentProcess, steps: updatedSteps });
    setToast({ message: 'Step deleted', type: 'info' });
  };

  const handleReorderSteps = (reorderedSteps: BPStep[]) => {
    setCurrentProcess({ ...currentProcess, steps: reorderedSteps });
  };

  const handleNLGenerated = (process: BusinessProcess) => {
    setCurrentProcess({
      ...process,
      id: '',
      createdBy: 'nl_builder',
      createdAt: new Date().toISOString(),
      version: 1,
    });
    setShowNLBuilder(false);
    setToast({ message: 'Process generated! Review and save when ready.', type: 'success' });
  };

  const handleSaveProcess = async () => {
    if (scopeMissing) {
      setToast({ message: 'Select a tenant and datasource before saving', type: 'error' });
      return;
    }
    if (!currentProcess.processName.trim()) {
      setToast({ message: 'Process name is required', type: 'error' });
      return;
    }
    if (currentProcess.steps.length === 0) {
      setToast({ message: 'Add at least one step', type: 'error' });
      return;
    }

    setIsLoading(true);
    try {
      const isNewProcess = !currentProcess.id;
      if (isNewProcess) {
        const { id: _id, createdAt: _createdAt, updatedAt: _updatedAt, version: _version, ...createPayload } = currentProcess;
        const result = await createBPMutation.mutateAsync(
          createPayload as Omit<BusinessProcess, 'id' | 'createdAt' | 'updatedAt' | 'version'>
        );
        setCurrentProcess(result!);
      } else {
        const result = await updateBPMutation.mutateAsync(currentProcess);
        setCurrentProcess(result!);
      }
      setToast({ message: 'Process saved successfully', type: 'success' });
    } catch (error) {
      setToast({ message: error instanceof Error ? error.message : 'Failed to save', type: 'error' });
    } finally {
      setIsLoading(false);
    }
  };

  const handlePublish = async () => {
    if (scopeMissing) {
      setToast({ message: 'Select a tenant and datasource before publishing', type: 'error' });
      return;
    }
    if (!currentProcess.id) {
      setToast({ message: 'Save process first before publishing', type: 'error' });
      return;
    }

    setIsLoading(true);
    try {
      const result = await publishBPMutation.mutateAsync(currentProcess.id);
      setCurrentProcess(result!);
      setToast({ message: 'Process published successfully', type: 'success' });
    } catch (error) {
      setToast({ message: error instanceof Error ? error.message : 'Failed to publish', type: 'error' });
    } finally {
      setIsLoading(false);
    }
  };

  const handleSimulate = async () => {
    if (scopeMissing) {
      setToast({ message: 'Select a tenant and datasource before running simulations', type: 'error' });
      return;
    }
    if (!currentProcess.id) {
      setToast({ message: 'Save the process before running a simulation', type: 'error' });
      return;
    }
    setIsLoading(true);
    try {
      const result = await simulateBPMutation.mutateAsync({
        processId: currentProcess.id,
        testData: {},
      });
      setToast({ message: `Simulation completed: ${result.message || 'Success'}`, type: 'success' });
    } catch (error) {
      setToast({ message: error instanceof Error ? error.message : 'Simulation failed', type: 'error' });
    } finally {
      setIsLoading(false);
    }
  };

  const handleExport = () => {
    const dataStr = JSON.stringify(currentProcess, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(dataBlob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${currentProcess.processName}-v${currentProcess.version}.json`;
    link.click();
    setToast({ message: 'Process exported', type: 'success' });
  };

  const containerClass = isMaximized ? 'fixed inset-0 z-50 bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50' : 'w-full';

  const headerLarge = "bg-gradient-to-r from-indigo-600 via-blue-600 to-purple-600 text-white px-8 py-6 shadow-2xl border-b border-white/10";
  const headerCompact = "bg-transparent text-gray-900 px-4 py-3 border-b border-gray-100";

  if (scopeMissing) {
    return (
      <div className="p-10">
        <div className="max-w-2xl mx-auto bg-white border border-amber-200 rounded-2xl shadow-sm p-10 text-center">
          <div className="text-4xl mb-4">🔐</div>
          <h2 className="text-2xl font-semibold mb-2">Select a tenant + datasource</h2>
          <p className="text-gray-600 mb-6">
            The Business Process Builder calls tenant-scoped APIs. Use the Fabric Builder scope picker in the shell
            to choose a tenant, product, and datasource, or seed&nbsp;`localStorage` using the values from
            <code className="mx-1 bg-gray-100 px-1 rounded">TenantContext</code> before returning.
          </p>
          <p className="text-sm text-gray-500">
            Tip: in headless sessions you can run <code className="bg-gray-100 px-1 rounded">localStorage.setItem('selected_tenant', ...)</code>
            then reload to unlock the designer.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className={`flex flex-col ${containerClass}`}>
      {/* Header - large when maximized, compact when embedded inside app shell */}
      <div className={isMaximized ? headerLarge : headerCompact}>
        <div className={` ${isMaximized ? 'max-w-screen-2xl mx-auto flex items-center justify-between' : 'flex items-center justify-between w-full'}`}>
          <div className={`flex items-center gap-4 ${isMaximized ? '' : 'w-full'}`}>
            <div className={`${isMaximized ? 'bg-white/20 backdrop-blur-sm p-3 rounded-xl' : 'p-2 rounded-md'}`}>
              <Workflow size={isMaximized ? 32 : 20} className={isMaximized ? 'drop-shadow-lg' : ''} />
            </div>
            <div className={isMaximized ? '' : 'flex-1'}>
              <h1 className={`${isMaximized ? 'text-3xl font-bold tracking-tight' : 'text-lg font-semibold'}`}>Business Process Builder</h1>
              {isMaximized && <p className="text-sm text-blue-100 mt-1">Visual workflow designer for enterprise automation</p>}
            </div>
          </div>
          <div className="flex items-center gap-3">
            {isMaximized ? (
              <>
                <div className="bg-white/10 backdrop-blur-sm px-4 py-2 rounded-lg border border-white/20">
                  <span className="text-xs text-blue-100">Process Steps: </span>
                  <span className="text-lg font-bold">{currentProcess.steps.length}</span>
                </div>
                <button
                  onClick={() => setIsMaximized(!isMaximized)}
                  className="hover:bg-white/20 p-2 rounded-lg transition-all backdrop-blur-sm"
                  title={isMaximized ? 'Restore window' : 'Maximize window'}
                  aria-label={isMaximized ? 'Restore window' : 'Maximize window'}
                >
                  {isMaximized ? <Minimize2 size={22} /> : <Maximize2 size={22} />}
                </button>
              </>
            ) : (
              <button
                onClick={() => setIsMaximized(true)}
                className="px-3 py-1 border border-gray-200 rounded-md text-sm hover:bg-gray-50"
                title="Open in full screen"
                aria-label="Open in full screen"
              >
                Open
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex h-full overflow-hidden max-w-screen-2xl mx-auto w-full">
        {/* Left Panel - Config with Modern Card Design */}
        <div className="w-96 border-r border-gray-200 overflow-y-auto p-6 space-y-5 bg-white/60 backdrop-blur-sm">
          {/* Process Configuration Card */}
          <div className="bg-white rounded-xl shadow-lg border border-gray-200 p-6 space-y-5">
            <div className="flex items-center gap-3 mb-4">
              <div className="bg-gradient-to-br from-blue-500 to-indigo-600 p-2 rounded-lg">
                <Settings size={20} className="text-white" />
              </div>
              <h2 className="text-lg font-bold text-gray-900">Process Configuration</h2>
            </div>

            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">
                Process Name <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                value={currentProcess.processName}
                onChange={(e) => setCurrentProcess({ ...currentProcess, processName: e.target.value })}
                className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all"
                placeholder="e.g., Employee Onboarding"
              />
            </div>

            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Entity Type</label>
              <select
                value={currentProcess.entity}
                onChange={(e) => setCurrentProcess({ ...currentProcess, entity: e.target.value })}
                className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all bg-white"
                title="Select entity type"
                aria-label="Select entity type"
              >
                {AVAILABLE_ENTITIES.map(entity => (
                  <option key={entity} value={entity}>{entity}</option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Description</label>
              <textarea
                value={currentProcess.description}
                onChange={(e) => setCurrentProcess({ ...currentProcess, description: e.target.value })}
                className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all resize-none"
                rows={3}
                placeholder="Describe the process purpose and scope..."
              />
            </div>
          </div>

          {/* Stats Card */}
          <div className="bg-gradient-to-br from-blue-500 to-indigo-600 rounded-xl shadow-lg p-6 text-white">
            <h3 className="text-sm font-semibold mb-4 opacity-90">Process Metrics</h3>
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Layers size={18} className="opacity-80" />
                  <span className="text-sm">Total Steps</span>
                </div>
                <span className="text-2xl font-bold">{currentProcess.steps.length}</span>
              </div>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Clock size={18} className="opacity-80" />
                  <span className="text-sm">Duration</span>
                </div>
                <span className="text-2xl font-bold">{currentProcess.steps.reduce((sum, s) => sum + s.durationHours, 0)}h</span>
              </div>
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Activity size={18} className="opacity-80" />
                  <span className="text-sm">Status</span>
                </div>
                <span className={`px-3 py-1 rounded-full text-xs font-bold ${
                  currentProcess.isActive 
                    ? 'bg-green-400 text-green-900' 
                    : 'bg-white/20 text-white'
                }`}>
                  {currentProcess.isActive ? '● Published' : '○ Draft'}
                </span>
              </div>
            </div>
          </div>

          {/* AI Builder Button */}
          <button
            onClick={() => setShowNLBuilder(true)}
            className="w-full px-6 py-4 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-xl hover:from-purple-700 hover:to-indigo-700 font-semibold text-base flex items-center justify-center gap-3 transition-all shadow-lg hover:shadow-xl transform hover:scale-[1.02]"
          >
            <Wand2 size={20} />
            Create with AI
          </button>

          {/* Analytics Button */}
          <button
            onClick={() => setViewMode('analytics')}
            className="w-full px-6 py-4 bg-gradient-to-r from-blue-600 to-cyan-600 text-white rounded-xl hover:from-blue-700 hover:to-cyan-700 font-semibold text-base flex items-center justify-center gap-3 transition-all shadow-lg hover:shadow-xl transform hover:scale-[1.02]"
          >
            <BarChart3 size={20} />
            View Analytics
          </button>

          {/* Live Monitor Button */}
          <button
            onClick={() => setViewMode('monitor')}
            className="w-full px-6 py-4 bg-gradient-to-r from-green-600 to-emerald-600 text-white rounded-xl hover:from-green-700 hover:to-emerald-700 font-semibold text-base flex items-center justify-center gap-3 transition-all shadow-lg hover:shadow-xl transform hover:scale-[1.02]"
          >
            <Activity size={20} />
            Live Monitor
          </button>

          {/* AI Optimize Button */}
          <button
            onClick={() => setViewMode('optimize')}
            className="w-full px-6 py-4 bg-gradient-to-r from-purple-600 to-pink-600 text-white rounded-xl hover:from-purple-700 hover:to-pink-700 font-semibold text-base flex items-center justify-center gap-3 transition-all shadow-lg hover:shadow-xl transform hover:scale-[1.02]"
          >
            <Zap size={20} />
            AI Optimize
          </button>

          {/* Integrations Button */}
          <button
            onClick={() => setViewMode('integrations')}
            className="w-full px-6 py-4 bg-gradient-to-r from-green-600 to-teal-600 text-white rounded-xl hover:from-green-700 hover:to-teal-700 font-semibold text-base flex items-center justify-center gap-3 transition-all shadow-lg hover:shadow-xl transform hover:scale-[1.02]"
          >
            <Package size={20} />
            Integrations
          </button>

          {/* Templates Button */}
          <button
            onClick={() => setViewMode('templates')}
            className="w-full px-6 py-4 bg-gradient-to-r from-indigo-600 to-purple-600 text-white rounded-xl hover:from-indigo-700 hover:to-purple-700 font-semibold text-base flex items-center justify-center gap-3 transition-all shadow-lg hover:shadow-xl transform hover:scale-[1.02]"
          >
            <Layers size={20} />
            Templates
          </button>

          {/* Action Buttons */}
          <div className="space-y-3 pt-2">
            <button
              onClick={handleSaveProcess}
              disabled={isLoading}
              className="w-full px-4 py-3.5 bg-gradient-to-r from-blue-600 to-blue-700 text-white rounded-xl hover:from-blue-700 hover:to-blue-800 font-semibold flex items-center justify-center gap-2 disabled:opacity-50 shadow-lg hover:shadow-xl transition-all transform hover:scale-[1.02]"
            >
              {isLoading ? <Loader size={20} className="animate-spin" /> : <Save size={20} />}
              Save Process
            </button>
            <button
              onClick={handlePublish}
              disabled={isLoading || currentProcess.steps.length === 0}
              className="w-full px-4 py-3.5 bg-gradient-to-r from-green-600 to-emerald-600 text-white rounded-xl hover:from-green-700 hover:to-emerald-700 font-semibold flex items-center justify-center gap-2 disabled:opacity-50 shadow-lg hover:shadow-xl transition-all transform hover:scale-[1.02]"
            >
              {isLoading ? <Loader size={20} className="animate-spin" /> : <Upload size={20} />}
              Publish
            </button>
            <button
              onClick={handleSimulate}
              disabled={isLoading || currentProcess.steps.length === 0}
              className="w-full px-4 py-3.5 bg-gradient-to-r from-purple-600 to-pink-600 text-white rounded-xl hover:from-purple-700 hover:to-pink-700 font-semibold flex items-center justify-center gap-2 disabled:opacity-50 shadow-lg hover:shadow-xl transition-all transform hover:scale-[1.02]"
            >
              {isLoading ? <Loader size={20} className="animate-spin" /> : <Play size={20} />}
              Simulate
            </button>
            <button
              onClick={handleExport}
              className="w-full px-4 py-3.5 bg-gradient-to-r from-indigo-600 to-purple-600 text-white rounded-xl hover:from-indigo-700 hover:to-purple-700 font-semibold flex items-center justify-center gap-2 shadow-lg hover:shadow-xl transition-all transform hover:scale-[1.02]"
            >
              <Download size={20} />
              Export
            </button>
          </div>
        </div>

        {/* Right Panel - Canvas */}
        <div className="flex-1 overflow-y-auto p-8 bg-white/40">
          {/* View Mode Selector */}
          <div className="flex gap-3 mb-8">
            {[
              { mode: 'canvas' as ViewMode, icon: Grid3X3, label: 'Canvas' },
              { mode: 'timeline' as ViewMode, icon: Activity, label: 'Timeline' },
              { mode: 'json' as ViewMode, icon: Code, label: 'JSON' },
            ].map(({ mode, icon: Icon, label }) => (
              <button
                key={mode}
                onClick={() => setViewMode(mode)}
                className={`px-6 py-3 rounded-xl font-semibold flex items-center gap-2 transition-all shadow-sm ${
                  viewMode === mode
                    ? 'bg-gradient-to-r from-blue-600 to-indigo-600 text-white shadow-lg scale-105'
                    : 'bg-white text-gray-700 hover:bg-gray-50 border-2 border-gray-200'
                }`}
              >
                <Icon size={20} />
                {label}
              </button>
            ))}
          </div>

          {/* View Content */}
          {viewMode === 'canvas' && (
            <CanvasView
              steps={currentProcess.steps}
              onEditStep={(step) => {
                const idx = currentProcess.steps.findIndex((s) => s.id === step.id);
                if (idx >= 0) {
                  handleEditStep(idx);
                }
              }}
              onDeleteStep={handleDeleteStep}
              onAddStep={handleAddStep}
              onReorderSteps={handleReorderSteps}
            />
          )}

          {viewMode === 'timeline' && (
            <div className="space-y-4">
              <div className="relative">
                {currentProcess.steps.map((step, idx) => {
                  const stepType = STEP_TYPES.find(t => t.type === step.stepType)!;
                  const accumulatedTime = currentProcess.steps.slice(0, idx).reduce((sum, s) => sum + s.durationHours, 0);

                  return (
                    <div key={step.id} className="flex gap-4 mb-6">
                      <div className="w-24 text-right">
                        <div className="text-sm font-bold text-gray-900">{accumulatedTime.toFixed(1)}h</div>
                        <div className="text-xs text-gray-500">+{step.durationHours}h</div>
                      </div>
                      <div className="relative flex-1">
                        <div className={`absolute -left-12 top-2 w-6 h-6 ${stepType.bgColor} border-2 ${stepType.borderColor} rounded-full`} />
                        {idx < currentProcess.steps.length - 1 && (
                          <div className="absolute -left-10 top-8 w-0.5 h-20 bg-gray-300" />
                        )}
                        <div className={`${stepType.bgColor} border-2 ${stepType.borderColor} rounded-lg p-4`}>
                          <h4 className="font-semibold text-gray-900">{step.stepName}</h4>
                          <p className="text-sm text-gray-600">{step.description}</p>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {viewMode === 'json' && (
            <div className="bg-gray-900 text-gray-100 rounded-lg p-4 font-mono text-sm overflow-x-auto">
              <pre>{JSON.stringify(currentProcess, null, 2)}</pre>
            </div>
          )}

          {viewMode === 'analytics' && tenant && datasource && (
            <ProcessAnalyticsDashboard
              tenant={tenant}
              datasource={datasource}
            />
          )}

          {viewMode === 'monitor' && tenant && datasource && (
            <ProcessMonitorDashboard
              tenant={tenant}
              datasource={datasource}
            />
          )}

          {viewMode === 'optimize' && tenant && datasource && (
            <ProcessOptimizationDashboard
              tenant={tenant}
              datasource={datasource}
            />
          )}

          {viewMode === 'integrations' && tenant && datasource && (
            <IntegrationMarketplaceBrowser
              tenant={tenant}
              datasource={datasource}
            />
          )}

          {viewMode === 'templates' && tenant && datasource && (
            <ProcessTemplatesLibrary
              tenant={tenant}
              datasource={datasource}
              onTemplateCloned={(processId) => {
                // Refresh or navigate to cloned process
                setViewMode('canvas');
                showNotification('Template cloned successfully!', 'success');
              }}
            />
          )}
        </div>
      </div>

      {/* Step Editor Modal */}
      {editingStepIndex !== null && (
        <StepEditor
          step={currentProcess.steps[editingStepIndex]}
          onSave={handleSaveStep}
          onCancel={() => setEditingStepIndex(null)}
          stepOrder={editingStepIndex + 1}
        />
      )}

      {/* Natural Language Builder Modal */}
      {showNLBuilder && (
        <NaturalLanguageBuilder
          onProcessGenerated={handleNLGenerated}
          onCancel={() => setShowNLBuilder(false)}
          tenant={tenant!}
          datasource={datasource!}
        />
      )}

      {/* Toast Notifications */}
      {toast && (
        <div className="fixed bottom-6 right-6 z-50">
          <Toast
            message={toast.message}
            type={toast.type}
            onClose={() => setToast(null)}
          />
        </div>
      )}
    </div>
  );
};

export default BusinessProcessBuilderEnhanced;

import React, { useState, useEffect } from 'react';
import {
  Search,
  Package,
  Zap,
  MessageSquare,
  Mail,
  Webhook,
  Database,
  BarChart3,
  Settings,
  Check,
  X,
  ExternalLink,
  Play,
  Trash2,
  ToggleLeft,
  ToggleRight,
  Clock,
  AlertCircle,
  CheckCircle2,
  XCircle,
  TrendingUp,
  Download,
  Plus,
  Activity,
  Eye,
  RefreshCw,
} from 'lucide-react';

interface IntegrationMarketplaceBrowserProps {
  tenant: { id: string; display_name: string };
  datasource: { id: string; source_name: string };
}

interface MarketplaceIntegration {
  id: string;
  integration_key: string;
  name: string;
  description: string;
  category: string;
  provider: string;
  icon_url: string;
  version: string;
  is_official: boolean;
  is_active: boolean;
  config_schema: Record<string, any>;
  auth_type: string;
  supports_webhooks: boolean;
  supports_polling: boolean;
  supports_actions: boolean;
  documentation_url: string;
  setup_guide: string;
  example_payload: Record<string, any>;
  install_count: number;
  rating: number;
  created_at: string;
  updated_at: string;
}

interface InstalledIntegration {
  id: string;
  tenant_id: string;
  datasource_id: string;
  integration_id: string;
  installed_by: string;
  installed_at: string;
  is_enabled: boolean;
  config: Record<string, any>;
  last_used_at?: string;
  execution_count: number;
  success_count: number;
  failure_count: number;
  integration_name: string;
  integration_key: string;
  integration_icon_url: string;
}

interface IntegrationExecution {
  id: string;
  action: string;
  status: string;
  started_at: string;
  completed_at?: string;
  duration_ms: number;
  error_message?: string;
  workflow_type?: string;
  step_name?: string;
}

export const IntegrationMarketplaceBrowser: React.FC<IntegrationMarketplaceBrowserProps> = ({
  tenant,
  datasource,
}) => {
  const [viewMode, setViewMode] = useState<'marketplace' | 'installed' | 'logs'>('marketplace');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [marketplaceIntegrations, setMarketplaceIntegrations] = useState<MarketplaceIntegration[]>([]);
  const [installedIntegrations, setInstalledIntegrations] = useState<InstalledIntegration[]>([]);
  const [executionLogs, setExecutionLogs] = useState<IntegrationExecution[]>([]);
  const [selectedIntegration, setSelectedIntegration] = useState<MarketplaceIntegration | null>(null);
  const [showInstallModal, setShowInstallModal] = useState(false);
  const [showConfigModal, setShowConfigModal] = useState(false);
  const [configFormData, setConfigFormData] = useState<Record<string, any>>({});
  const [isLoading, setIsLoading] = useState(false);

  const categories = [
    { key: 'all', label: 'All Integrations', icon: Package },
    { key: 'communication', label: 'Communication', icon: MessageSquare },
    { key: 'automation', label: 'Automation', icon: Zap },
    { key: 'storage', label: 'Storage', icon: Database },
    { key: 'analytics', label: 'Analytics', icon: BarChart3 },
    { key: 'ai', label: 'AI', icon: Activity },
  ];

  useEffect(() => {
    if (viewMode === 'marketplace') {
      fetchMarketplaceIntegrations();
    } else if (viewMode === 'installed') {
      fetchInstalledIntegrations();
    } else if (viewMode === 'logs') {
      fetchExecutionLogs();
    }
  }, [viewMode, selectedCategory, tenant.id, datasource.id]);

  async function fetchMarketplaceIntegrations() {
    try {
      const params = new URLSearchParams();
      if (selectedCategory !== 'all') {
        params.set('category', selectedCategory);
      }
      if (searchQuery) {
        params.set('search', searchQuery);
      }

      const response = await fetch(`/api/integrations/marketplace?${params}`);
      if (!response.ok) throw new Error('Failed to fetch');

      const data = await response.json();
      setMarketplaceIntegrations(data || []);
    } catch (error) {
      console.error('Error fetching marketplace integrations:', error);
    }
  }

  async function fetchInstalledIntegrations() {
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id,
      });

      const response = await fetch(`/api/integrations/installed?${params}`);
      if (!response.ok) throw new Error('Failed to fetch');

      const data = await response.json();
      setInstalledIntegrations(data || []);
    } catch (error) {
      console.error('Error fetching installed integrations:', error);
    }
  }

  async function fetchExecutionLogs() {
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id,
      });

      const response = await fetch(`/api/integrations/executions?${params}`);
      if (!response.ok) throw new Error('Failed to fetch');

      const data = await response.json();
      setExecutionLogs(data || []);
    } catch (error) {
      console.error('Error fetching execution logs:', error);
    }
  }

  async function installIntegration() {
    if (!selectedIntegration) return;

    setIsLoading(true);
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id,
      });

      const response = await fetch(`/api/integrations/install?${params}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          integration_key: selectedIntegration.integration_key,
          config: configFormData,
          credentials: {}, // Would be populated from form
        }),
      });

      if (!response.ok) throw new Error('Installation failed');

      alert('Integration installed successfully!');
      setShowInstallModal(false);
      setSelectedIntegration(null);
      setConfigFormData({});
      fetchInstalledIntegrations();
    } catch (error) {
      console.error('Error installing integration:', error);
      alert('Failed to install integration: ' + error);
    } finally {
      setIsLoading(false);
    }
  }

  async function toggleIntegration(installationId: string, currentState: boolean) {
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id,
      });

      const response = await fetch(`/api/integrations/installed/${installationId}/toggle?${params}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ enabled: !currentState }),
      });

      if (!response.ok) throw new Error('Toggle failed');

      fetchInstalledIntegrations();
    } catch (error) {
      console.error('Error toggling integration:', error);
    }
  }

  async function uninstallIntegration(installationId: string) {
    if (!confirm('Are you sure you want to uninstall this integration?')) return;

    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id,
      });

      const response = await fetch(`/api/integrations/installed/${installationId}?${params}`, {
        method: 'DELETE',
      });

      if (!response.ok) throw new Error('Uninstall failed');

      alert('Integration uninstalled successfully!');
      fetchInstalledIntegrations();
    } catch (error) {
      console.error('Error uninstalling integration:', error);
      alert('Failed to uninstall integration');
    }
  }

  async function testIntegration(installationId: string) {
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id,
      });

      const response = await fetch(`/api/integrations/test/${installationId}?${params}`, {
        method: 'POST',
      });

      if (!response.ok) throw new Error('Test failed');

      const result = await response.json();
      alert(result.success ? 'Connection test successful!' : 'Connection test failed: ' + result.message);
    } catch (error) {
      console.error('Error testing integration:', error);
      alert('Test failed: ' + error);
    }
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'success':
        return <CheckCircle2 size={16} className="text-green-600" />;
      case 'failed':
        return <XCircle size={16} className="text-red-600" />;
      case 'pending':
        return <Clock size={16} className="text-yellow-600" />;
      default:
        return <AlertCircle size={16} className="text-gray-600" />;
    }
  };

  const getCategoryIcon = (category: string) => {
    const cat = categories.find((c) => c.key === category);
    return cat ? cat.icon : Package;
  };

  return (
    <div className="h-full flex flex-col bg-gray-50">
      {/* Header */}
      <div className="bg-white border-b px-6 py-4">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
              <Package size={28} className="text-blue-600" />
              Integration Marketplace
            </h1>
            <p className="text-sm text-gray-500 mt-1">
              Browse, install, and manage workflow integrations
            </p>
          </div>
          <div className="flex gap-3">
            <button
              onClick={() => setViewMode('marketplace')}
              className={`px-4 py-2 rounded-lg font-medium transition-all ${
                viewMode === 'marketplace'
                  ? 'bg-blue-600 text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              <Download size={18} className="inline mr-2" />
              Marketplace
            </button>
            <button
              onClick={() => setViewMode('installed')}
              className={`px-4 py-2 rounded-lg font-medium transition-all ${
                viewMode === 'installed'
                  ? 'bg-blue-600 text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              <Check size={18} className="inline mr-2" />
              Installed ({installedIntegrations.length})
            </button>
            <button
              onClick={() => setViewMode('logs')}
              className={`px-4 py-2 rounded-lg font-medium transition-all ${
                viewMode === 'logs'
                  ? 'bg-blue-600 text-white'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              <Activity size={18} className="inline mr-2" />
              Execution Logs
            </button>
          </div>
        </div>

        {/* Search and Filters */}
        {viewMode === 'marketplace' && (
          <div className="flex gap-4">
            <div className="flex-1 relative">
              <Search size={20} className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
              <input
                type="text"
                placeholder="Search integrations..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && fetchMarketplaceIntegrations()}
                className="w-full pl-10 pr-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
            <button
              onClick={fetchMarketplaceIntegrations}
              className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-all"
            >
              Search
            </button>
          </div>
        )}
      </div>

      <div className="flex-1 overflow-hidden flex">
        {/* Sidebar - Categories */}
        {viewMode === 'marketplace' && (
          <div className="w-64 bg-white border-r p-4 overflow-y-auto">
            <h3 className="text-sm font-semibold text-gray-700 mb-3">Categories</h3>
            <div className="space-y-1">
              {categories.map((cat) => {
                const Icon = cat.icon;
                return (
                  <button
                    key={cat.key}
                    onClick={() => setSelectedCategory(cat.key)}
                    className={`w-full flex items-center gap-3 px-3 py-2 rounded-lg text-left transition-all ${
                      selectedCategory === cat.key
                        ? 'bg-blue-100 text-blue-700 font-medium'
                        : 'text-gray-700 hover:bg-gray-100'
                    }`}
                  >
                    <Icon size={18} />
                    <span className="text-sm">{cat.label}</span>
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* Main Content */}
        <div className="flex-1 overflow-y-auto p-6">
          {viewMode === 'marketplace' && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {marketplaceIntegrations.map((integration) => {
                const Icon = getCategoryIcon(integration.category);
                const isInstalled = installedIntegrations.some(
                  (inst) => inst.integration_id === integration.id
                );

                return (
                  <div
                    key={integration.id}
                    className="bg-white rounded-lg border p-4 hover:shadow-lg transition-all cursor-pointer"
                    onClick={() => {
                      setSelectedIntegration(integration);
                      if (!isInstalled) {
                        setShowInstallModal(true);
                      }
                    }}
                  >
                    <div className="flex items-start gap-3 mb-3">
                      <div className="p-3 rounded-lg bg-blue-100">
                        <Icon size={24} className="text-blue-600" />
                      </div>
                      <div className="flex-1">
                        <div className="flex items-center gap-2">
                          <h3 className="font-semibold text-gray-900">{integration.name}</h3>
                          {integration.is_official && (
                            <span className="px-2 py-0.5 bg-blue-100 text-blue-700 text-xs rounded-full font-medium">
                              Official
                            </span>
                          )}
                        </div>
                        <p className="text-xs text-gray-500 mt-1">{integration.provider}</p>
                      </div>
                    </div>

                    <p className="text-sm text-gray-600 mb-3 line-clamp-2">{integration.description}</p>

                    <div className="flex items-center justify-between text-xs text-gray-500 mb-3">
                      <span className="flex items-center gap-1">
                        <TrendingUp size={14} />
                        {integration.install_count} installs
                      </span>
                      <span className="flex items-center gap-1">
                        ⭐ {integration.rating.toFixed(1)}
                      </span>
                    </div>

                    <div className="flex gap-2">
                      {isInstalled ? (
                        <span className="flex-1 px-3 py-2 bg-green-100 text-green-700 rounded-lg text-sm font-medium text-center flex items-center justify-center gap-2">
                          <Check size={16} />
                          Installed
                        </span>
                      ) : (
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            setSelectedIntegration(integration);
                            setShowInstallModal(true);
                          }}
                          className="flex-1 px-3 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-all"
                        >
                          <Plus size={16} className="inline mr-1" />
                          Install
                        </button>
                      )}
                      {integration.documentation_url && (
                        <a
                          href={integration.documentation_url}
                          target="_blank"
                          rel="noopener noreferrer"
                          onClick={(e) => e.stopPropagation()}
                          className="px-3 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-all"
                        >
                          <ExternalLink size={16} />
                        </a>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}

          {viewMode === 'installed' && (
            <div className="space-y-4">
              {installedIntegrations.length === 0 ? (
                <div className="text-center py-12 text-gray-500">
                  <Package size={48} className="mx-auto mb-4 text-gray-400" />
                  <p className="text-lg font-medium">No integrations installed</p>
                  <p className="text-sm mt-2">Browse the marketplace to install integrations</p>
                </div>
              ) : (
                installedIntegrations.map((installation) => {
                  const successRate =
                    installation.execution_count > 0
                      ? (installation.success_count / installation.execution_count) * 100
                      : 0;

                  return (
                    <div key={installation.id} className="bg-white rounded-lg border p-4">
                      <div className="flex items-start justify-between">
                        <div className="flex items-start gap-3 flex-1">
                          <div className="p-3 rounded-lg bg-blue-100">
                            <Package size={24} className="text-blue-600" />
                          </div>
                          <div className="flex-1">
                            <h3 className="font-semibold text-gray-900 flex items-center gap-2">
                              {installation.integration_name}
                              {installation.is_enabled ? (
                                <span className="px-2 py-0.5 bg-green-100 text-green-700 text-xs rounded-full">
                                  Enabled
                                </span>
                              ) : (
                                <span className="px-2 py-0.5 bg-gray-100 text-gray-700 text-xs rounded-full">
                                  Disabled
                                </span>
                              )}
                            </h3>
                            <p className="text-xs text-gray-500 mt-1">
                              Installed {new Date(installation.installed_at).toLocaleDateString()}
                            </p>

                            <div className="flex items-center gap-4 mt-3 text-sm">
                              <div className="flex items-center gap-1">
                                <Activity size={16} className="text-blue-600" />
                                <span className="font-medium">{installation.execution_count}</span>
                                <span className="text-gray-500">executions</span>
                              </div>
                              <div className="flex items-center gap-1">
                                <CheckCircle2 size={16} className="text-green-600" />
                                <span className="font-medium">{successRate.toFixed(1)}%</span>
                                <span className="text-gray-500">success</span>
                              </div>
                              {installation.last_used_at && (
                                <div className="flex items-center gap-1 text-gray-500">
                                  <Clock size={16} />
                                  Last used {new Date(installation.last_used_at).toLocaleString()}
                                </div>
                              )}
                            </div>
                          </div>
                        </div>

                        <div className="flex gap-2">
                          <button
                            onClick={() => toggleIntegration(installation.id, installation.is_enabled)}
                            className="px-3 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-all"
                            title={installation.is_enabled ? 'Disable' : 'Enable'}
                          >
                            {installation.is_enabled ? (
                              <ToggleRight size={18} className="text-green-600" />
                            ) : (
                              <ToggleLeft size={18} />
                            )}
                          </button>
                          <button
                            onClick={() => testIntegration(installation.id)}
                            className="px-3 py-2 bg-blue-100 text-blue-700 rounded-lg hover:bg-blue-200 transition-all"
                            title="Test Connection"
                          >
                            <Play size={18} />
                          </button>
                          <button
                            onClick={() => {
                              /* Open config modal */
                            }}
                            className="px-3 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-all"
                            title="Configure"
                          >
                            <Settings size={18} />
                          </button>
                          <button
                            onClick={() => uninstallIntegration(installation.id)}
                            className="px-3 py-2 bg-red-100 text-red-700 rounded-lg hover:bg-red-200 transition-all"
                            title="Uninstall"
                          >
                            <Trash2 size={18} />
                          </button>
                        </div>
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          )}

          {viewMode === 'logs' && (
            <div className="bg-white rounded-lg border">
              <table className="w-full">
                <thead className="bg-gray-50 border-b">
                  <tr>
                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                      Status
                    </th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                      Action
                    </th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                      Workflow
                    </th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                      Duration
                    </th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                      Time
                    </th>
                    <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y">
                  {executionLogs.map((log) => (
                    <tr key={log.id} className="hover:bg-gray-50">
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-2">
                          {getStatusIcon(log.status)}
                          <span className="text-sm font-medium">{log.status}</span>
                        </div>
                      </td>
                      <td className="px-4 py-3 text-sm text-gray-900">{log.action}</td>
                      <td className="px-4 py-3 text-sm text-gray-600">
                        {log.workflow_type || '-'}
                        {log.step_name && (
                          <div className="text-xs text-gray-500">{log.step_name}</div>
                        )}
                      </td>
                      <td className="px-4 py-3 text-sm text-gray-600">{log.duration_ms}ms</td>
                      <td className="px-4 py-3 text-sm text-gray-600">
                        {new Date(log.started_at).toLocaleString()}
                      </td>
                      <td className="px-4 py-3">
                        <button className="text-blue-600 hover:text-blue-800 text-sm font-medium">
                          <Eye size={16} className="inline mr-1" />
                          View
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>

      {/* Install Modal */}
      {showInstallModal && selectedIntegration && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl max-w-2xl w-full mx-4 max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b">
              <div className="flex items-center justify-between">
                <h2 className="text-xl font-bold text-gray-900">Install {selectedIntegration.name}</h2>
                <button
                  onClick={() => {
                    setShowInstallModal(false);
                    setSelectedIntegration(null);
                  }}
                  className="text-gray-400 hover:text-gray-600"
                >
                  <X size={24} />
                </button>
              </div>
            </div>

            <div className="p-6">
              <p className="text-gray-600 mb-4">{selectedIntegration.description}</p>

              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Configuration
                  </label>
                  <p className="text-sm text-gray-500 mb-2">
                    {selectedIntegration.setup_guide || 'Configure the integration settings below.'}
                  </p>
                  {/* Configuration form would go here based on config_schema */}
                  <div className="bg-gray-50 border rounded-lg p-4">
                    <p className="text-sm text-gray-600">
                      Configuration form based on integration schema will be displayed here.
                    </p>
                  </div>
                </div>
              </div>
            </div>

            <div className="p-6 border-t flex justify-end gap-3">
              <button
                onClick={() => {
                  setShowInstallModal(false);
                  setSelectedIntegration(null);
                }}
                className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-all"
              >
                Cancel
              </button>
              <button
                onClick={installIntegration}
                disabled={isLoading}
                className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-all disabled:opacity-50 flex items-center gap-2"
              >
                {isLoading ? (
                  <>
                    <RefreshCw size={18} className="animate-spin" />
                    Installing...
                  </>
                ) : (
                  <>
                    <Plus size={18} />
                    Install Integration
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Wand2, Sparkles, AlertCircle, Check, Loader, Edit3, Zap, MessageSquare, FileText, ArrowRight } from 'lucide-react';
import { BusinessProcess, BPStep } from './useBPBuilderAPI';

interface NaturalLanguageBuilderProps {
  onProcessGenerated: (process: BusinessProcess) => void;
  onCancel: () => void;
  tenant: { id: string };
  datasource: { id: string };
}

const EXAMPLE_PROMPTS = [
  {
    title: "Expense Approval",
    text: "Create an expense approval process. Under $1000 goes to manager for approval. Over $1000 requires CFO approval. Send email notifications at each step and after final approval.",
    icon: "💰"
  },
  {
    title: "Employee Onboarding",
    text: "Create an employee onboarding workflow. First collect employee information, then validate it. Send welcome email, create accounts in parallel (IT system, payroll, benefits). Finally assign a buddy and notify HR when complete.",
    icon: "👋"
  },
  {
    title: "Purchase Order",
    text: "Create a purchase order workflow. Validate the order details first. If amount is under $5000, manager approves. If over $5000, both manager and finance director must approve in parallel. After approval, send to procurement and notify requestor.",
    icon: "🛒"
  },
  {
    title: "Document Review",
    text: "Create a document review process. Submit document for review. Route to legal team for review. If changes needed, send back to submitter. If approved, get final signature from department head and archive the document.",
    icon: "📄"
  }
];

export const NaturalLanguageBuilder: React.FC<NaturalLanguageBuilderProps> = ({
  onProcessGenerated,
  onCancel,
  tenant,
  datasource
}) => {
  const [input, setInput] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [generatedProcess, setGeneratedProcess] = useState<BusinessProcess | null>(null);
  const [showPreview, setShowPreview] = useState(false);
  const [aiInsights, setAiInsights] = useState<string[]>([]);

  const handleGenerate = async () => {
    if (!input.trim()) {
      setError('Please describe your workflow');
      return;
    }

    setIsProcessing(true);
    setError(null);
    setAiInsights([]);

    try {
      const response = await fetch(`/api/business-processes/generate-from-nl?tenant_id=${tenant.id}&datasource_id=${datasource.id}`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Tenant-ID': tenant.id,
          'X-Tenant-Datasource-ID': datasource.id,
        },
        body: JSON.stringify({
          description: input,
          tenant_id: tenant.id,
          datasource_id: datasource.id
        })
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to generate process');
      }

      const data = await response.json();

      if (data.success && data.data) {
        setGeneratedProcess(data.data.process);
        setAiInsights(data.data.insights || []);
        setShowPreview(true);
      } else {
        throw new Error(data.error || 'Failed to generate process');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to generate process');
    } finally {
      setIsProcessing(false);
    }
  };

  const handleAccept = () => {
    if (generatedProcess) {
      onProcessGenerated(generatedProcess);
    }
  };

  const handleUseExample = (exampleText: string) => {
    setInput(exampleText);
    setShowPreview(false);
    setGeneratedProcess(null);
    setError(null);
  };

  if (showPreview && generatedProcess) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-purple-50 via-blue-50 to-indigo-50 p-6">
        <div className="max-w-6xl mx-auto">
          {/* Header */}
          <div className="bg-white rounded-xl shadow-lg p-6 mb-6">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-3 bg-gradient-to-br from-purple-500 to-indigo-600 rounded-lg">
                  <Sparkles className="text-white" size={24} />
                </div>
                <div>
                  <h2 className="text-2xl font-bold text-gray-900">AI-Generated Process Preview</h2>
                  <p className="text-gray-600">Review and customize before saving</p>
                </div>
              </div>
              <div className="flex gap-3">
                <button
                  onClick={() => setShowPreview(false)}
                  className="px-4 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 font-semibold"
                >
                  Back to Edit
                </button>
                <button
                  onClick={handleAccept}
                  className="px-6 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-lg hover:from-purple-700 hover:to-indigo-700 font-semibold flex items-center gap-2"
                >
                  <Check size={18} />
                  Accept & Continue
                </button>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-6">
            {/* Process Details */}
            <div className="col-span-2 space-y-6">
              <div className="bg-white rounded-xl shadow-lg p-6">
                <h3 className="text-lg font-bold text-gray-900 mb-4 flex items-center gap-2">
                  <FileText size={20} />
                  Process Overview
                </h3>
                <div className="space-y-3">
                  <div>
                    <label className="text-sm font-semibold text-gray-600">Process Name</label>
                    <p className="text-lg text-gray-900 mt-1">{generatedProcess.processName}</p>
                  </div>
                  <div>
                    <label className="text-sm font-semibold text-gray-600">Entity Type</label>
                    <p className="text-gray-900 mt-1">{generatedProcess.entity}</p>
                  </div>
                  <div>
                    <label className="text-sm font-semibold text-gray-600">Description</label>
                    <p className="text-gray-700 mt-1">{generatedProcess.description}</p>
                  </div>
                </div>
              </div>

              {/* Steps Preview */}
              <div className="bg-white rounded-xl shadow-lg p-6">
                <h3 className="text-lg font-bold text-gray-900 mb-4">
                  Workflow Steps ({generatedProcess.steps.length})
                </h3>
                <div className="space-y-3">
                  {generatedProcess.steps.map((step, idx) => (
                    <div key={step.id} className="border border-gray-200 rounded-lg p-4">
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <div className="flex items-center gap-2 mb-2">
                            <span className="px-2 py-1 bg-blue-100 text-blue-700 rounded text-xs font-semibold">
                              Step {step.stepOrder}
                            </span>
                            <span className="px-2 py-1 bg-gray-100 text-gray-700 rounded text-xs font-semibold">
                              {step.stepType}
                            </span>
                            {step.executionMode === 'parallel' && (
                              <span className="px-2 py-1 bg-purple-100 text-purple-700 rounded text-xs font-semibold">
                                Parallel
                              </span>
                            )}
                          </div>
                          <h4 className="font-semibold text-gray-900">{step.stepName}</h4>
                          {step.description && (
                            <p className="text-sm text-gray-600 mt-1">{step.description}</p>
                          )}
                          <div className="flex items-center gap-4 mt-2 text-sm text-gray-600">
                            {step.durationHours && (
                              <span>⏱️ {step.durationHours}h</span>
                            )}
                            {step.assigneeRole && (
                              <span>👤 {step.assigneeRole}</span>
                            )}
                            {step.conditionLogic && (
                              <span>🔀 Conditional</span>
                            )}
                            {step.approvalChain && (
                              <span>✅ {step.approvalChain.approvalMode} approval</span>
                            )}
                          </div>
                        </div>
                      </div>
                      {idx < generatedProcess.steps.length - 1 && (
                        <div className="flex justify-center mt-2">
                          <ArrowRight className="text-gray-400 rotate-90" size={20} />
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* AI Insights Sidebar */}
            <div className="space-y-6">
              <div className="bg-gradient-to-br from-purple-100 to-indigo-100 rounded-xl shadow-lg p-6">
                <h3 className="text-lg font-bold text-gray-900 mb-4 flex items-center gap-2">
                  <Sparkles size={20} className="text-purple-600" />
                  AI Insights
                </h3>
                <div className="space-y-3">
                  {aiInsights.map((insight, idx) => (
                    <div key={idx} className="bg-white rounded-lg p-3 text-sm text-gray-700">
                      {insight}
                    </div>
                  ))}
                  {aiInsights.length === 0 && (
                    <p className="text-sm text-gray-600">No additional insights for this process.</p>
                  )}
                </div>
              </div>

              <div className="bg-white rounded-xl shadow-lg p-6">
                <h3 className="text-lg font-bold text-gray-900 mb-4">Quick Stats</h3>
                <div className="space-y-3">
                  <div className="flex justify-between items-center">
                    <span className="text-gray-600">Total Steps</span>
                    <span className="font-semibold text-gray-900">{generatedProcess.steps.length}</span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-gray-600">Est. Duration</span>
                    <span className="font-semibold text-gray-900">
                      {generatedProcess.steps.reduce((acc, s) => acc + s.durationHours, 0)}h
                    </span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-gray-600">Approval Steps</span>
                    <span className="font-semibold text-gray-900">
                      {generatedProcess.steps.filter(s => s.stepType === 'approve').length}
                    </span>
                  </div>
                  <div className="flex justify-between items-center">
                    <span className="text-gray-600">Parallel Steps</span>
                    <span className="font-semibold text-gray-900">
                      {generatedProcess.steps.filter(s => s.executionMode === 'parallel').length}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-50 via-blue-50 to-indigo-50 p-6">
      <div className="max-w-5xl mx-auto">
        {/* Header */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center gap-3 mb-4">
            <div className="p-4 bg-gradient-to-br from-purple-500 to-indigo-600 rounded-2xl">
              <Wand2 className="text-white" size={32} />
            </div>
            <h1 className="text-4xl font-bold bg-gradient-to-r from-purple-600 to-indigo-600 bg-clip-text text-transparent">
              Natural Language Process Builder
            </h1>
          </div>
          <p className="text-xl text-gray-600 max-w-2xl mx-auto">
            Describe your workflow in plain English, and AI will create a complete business process for you
          </p>
        </div>

        {/* Main Input Card */}
        <div className="bg-white rounded-2xl shadow-xl p-8 mb-6">
          <div className="mb-6">
            <label className="flex items-center gap-2 text-lg font-semibold text-gray-900 mb-3">
              <MessageSquare size={20} />
              Describe Your Workflow
            </label>
            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Example: Create an expense approval process. Under $1000 goes to manager. Over $1000 requires CFO approval. Send email notifications at each step..."
              className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:ring-2 focus:ring-purple-500 focus:border-transparent resize-none text-gray-900 placeholder-gray-400"
              rows={6}
              disabled={isProcessing}
            />
            <div className="flex items-center justify-between mt-3">
              <p className="text-sm text-gray-500">
                💡 Tip: Mention approvals, conditions, notifications, and parallel steps
              </p>
              <span className="text-sm text-gray-400">
                {input.length} characters
              </span>
            </div>
          </div>

          {error && (
            <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg flex items-start gap-3">
              <AlertCircle className="text-red-600 flex-shrink-0 mt-0.5" size={20} />
              <div>
                <h4 className="font-semibold text-red-900">Error</h4>
                <p className="text-sm text-red-700">{error}</p>
              </div>
            </div>
          )}

          <div className="flex gap-3">
            <button
              onClick={handleGenerate}
              disabled={isProcessing || !input.trim()}
              className="flex-1 px-6 py-3 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-xl hover:from-purple-700 hover:to-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed font-semibold text-lg flex items-center justify-center gap-3 transition-all"
            >
              {isProcessing ? (
                <>
                  <Loader className="animate-spin" size={24} />
                  Generating with AI...
                </>
              ) : (
                <>
                  <Sparkles size={24} />
                  Generate Process
                </>
              )}
            </button>
            <button
              onClick={onCancel}
              className="px-6 py-3 border-2 border-gray-300 rounded-xl text-gray-700 hover:bg-gray-50 font-semibold transition-all"
            >
              Cancel
            </button>
          </div>
        </div>

        {/* Example Prompts */}
        <div className="bg-white rounded-2xl shadow-xl p-8">
          <div className="flex items-center gap-2 mb-6">
            <Zap className="text-purple-600" size={24} />
            <h3 className="text-xl font-bold text-gray-900">Example Workflows</h3>
          </div>
          <div className="grid grid-cols-2 gap-4">
            {EXAMPLE_PROMPTS.map((example, idx) => (
              <button
                key={idx}
                onClick={() => handleUseExample(example.text)}
                disabled={isProcessing}
                className="text-left p-4 border-2 border-gray-200 rounded-xl hover:border-purple-400 hover:bg-purple-50 transition-all group disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <div className="flex items-start gap-3">
                  <span className="text-3xl">{example.icon}</span>
                  <div className="flex-1">
                    <h4 className="font-semibold text-gray-900 group-hover:text-purple-600 mb-2">
                      {example.title}
                    </h4>
                    <p className="text-sm text-gray-600 line-clamp-3">
                      {example.text}
                    </p>
                  </div>
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Features */}
        <div className="mt-8 grid grid-cols-3 gap-6">
          <div className="bg-white rounded-xl shadow-lg p-6 text-center">
            <div className="w-12 h-12 bg-purple-100 rounded-full flex items-center justify-center mx-auto mb-3">
              <Sparkles className="text-purple-600" size={24} />
            </div>
            <h4 className="font-semibold text-gray-900 mb-2">AI-Powered</h4>
            <p className="text-sm text-gray-600">
              Advanced AI understands workflow nuances and generates optimized processes
            </p>
