  return (
    <div className="bg-white rounded-2xl shadow-xl p-6">
      <div className="mb-6">
        <h2 className="text-2xl font-bold text-gray-900 flex items-center gap-3">
          <Target className="w-7 h-7 text-purple-600" />
          Performance Gap Analysis
        </h2>
        <p className="text-gray-600 mt-1">
          Identify and close gaps between current and target performance
        </p>
      </div>

      <div className="space-y-6">
        {gaps.map((gap, index) => (
          <div key={index} className="border-2 border-gray-200 rounded-xl p-6">
            <div className="flex items-center justify-between mb-4">
              <div>
                <h3 className="text-xl font-bold text-gray-900">{gap.dimension}</h3>
                <span className={`inline-block mt-2 px-3 py-1 rounded-full text-xs font-bold border-2 ${getPriorityColor(gap.priority)}`}>
                  {gap.priority.toUpperCase()} PRIORITY
                </span>
              </div>
              <div className="text-right">
                <div className="text-4xl font-bold text-red-600">{gap.gap}</div>
                <div className="text-sm text-gray-600">point gap</div>
              </div>
            </div>

            <div className="mb-4">
              <div className="flex justify-between text-sm text-gray-600 mb-2">
                <span>Current: {gap.current_score}</span>
                <span>Target: {gap.target_score}</span>
              </div>
              <div className="relative h-4 bg-gray-100 rounded-full overflow-hidden">
                <div
                  className="h-full bg-gradient-to-r from-red-400 to-orange-400 rounded-full"
                  style={{ width: `${gap.current_score}%` }}
                />
                <div
                  className="absolute top-0 bottom-0 w-1 bg-green-600"
                  style={{ left: `${gap.target_score}%` }}
                />
              </div>
            </div>

            <div>
              <h4 className="font-bold text-gray-900 mb-2">Recommendations</h4>
              <ul className="space-y-2">
                {gap.recommendations.map((rec, idx) => (
                  <li key={idx} className="flex gap-2 text-gray-700">
                    <CheckCircle2 className="w-5 h-5 text-green-600 flex-shrink-0 mt-0.5" />
                    <span>{rec}</span>
                  </li>
                ))}
              </ul>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import {
  Activity,
  AlertCircle,
  CheckCircle2,
  Clock,
  Filter,
  Play,
  Pause,
  X,
  SkipForward,
  UserPlus,
  RefreshCw,
  Wifi,
  WifiOff,
} from 'lucide-react';
import { useProcessMonitorWebSocket, ProcessEvent } from '../hooks/useProcessMonitorWebSocket';
import { devLog} from '../../utils/devLogger';


interface ProcessMonitorDashboardProps {
  tenant: { id: string; display_name: string };
  datasource: { id: string; source_name: string };
}

interface ProcessInstance {
  workflow_id: string;
  workflow_type: string;
  status: string; // running, completed, failed
  current_step: string | null;
  started_at: string;
  last_activity_at: string;
  steps_completed: number;
  steps_total: number;
  sla_deadline: string | null;
  time_remaining: number | null; // minutes
  health_score: number; // 0-100
  tenant_id: string;
  datasource_id: string;
  owner: string | null;
  metadata: Record<string, any>;
  execution_history?: StepExecution[];
}

interface StepExecution {
  step_name: string;
  status: string;
  started_at: string;
  completed_at: string | null;
  duration: number | null; // seconds
  error_msg: string | null;
  metadata: Record<string, any>;
}

interface MonitoringStats {
  total_active: number;
  running_count: number;
  completed_count: number;
  failed_count: number;
  workflow_types: number;
}

export const ProcessMonitorDashboard: React.FC<ProcessMonitorDashboardProps> = ({
  tenant,
  datasource,
}) => {
  const [instances, setInstances] = useState<ProcessInstance[]>([]);
  const [selectedInstance, setSelectedInstance] = useState<ProcessInstance | null>(null);
  const [stats, setStats] = useState<MonitoringStats>({
    total_active: 0,
    running_count: 0,
    completed_count: 0,
    failed_count: 0,
    workflow_types: 0,
  });
  const [filters, setFilters] = useState({
    workflow_type: '',
    status: '',
  });
  const [showInterventionModal, setShowInterventionModal] = useState(false);
  const [interventionAction, setInterventionAction] = useState<'skip_step' | 'reassign' | 'cancel' | 'retry'>('skip_step');
  const [interventionReason, setInterventionReason] = useState('');

  // WebSocket connection for real-time updates
  const { isConnected, lastEvent, updateFilters } = useProcessMonitorWebSocket({
    tenantId: tenant.id,
    datasourceId: datasource.id,
    filters,
    onEvent: handleProcessEvent,
    autoReconnect: true,
  });

  function handleProcessEvent(event: ProcessEvent) {
    devLog('Received process event:', event);

    // Update instances based on event type
    if (event.type === 'workflow_started') {
      fetchActiveInstances(); // Refresh to get new workflow
    } else if (event.type === 'step_completed' || event.type === 'step_failed') {
      // Update specific instance
      setInstances((prev) =>
        prev.map((inst) =>
          inst.workflow_id === event.workflow_id
            ? {
                ...inst,
                current_step: event.step_name || inst.current_step,
                last_activity_at: event.timestamp,
                status: event.status,
              }
            : inst
        )
      );
    } else if (event.type === 'workflow_completed') {
      // Mark workflow as completed
      setInstances((prev) =>
        prev.map((inst) =>
          inst.workflow_id === event.workflow_id
            ? { ...inst, status: 'completed', last_activity_at: event.timestamp }
            : inst
        )
      );
    }
  }

  async function fetchActiveInstances() {
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id,
      });

      if (filters.workflow_type) params.append('workflow_type', filters.workflow_type);
      if (filters.status) params.append('status', filters.status);

      const response = await fetch(`/api/process-monitor/active-instances?${params}`);
      if (!response.ok) throw new Error('Failed to fetch active instances');

      const data = await response.json();
      setInstances(data || []);
    } catch (error) {
      console.error('Error fetching active instances:', error);
    }
  }

  async function fetchStats() {
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id,
      });

      const response = await fetch(`/api/process-monitor/stats?${params}`);
      if (!response.ok) throw new Error('Failed to fetch stats');

      const data = await response.json();
      setStats(data.stats || {});
    } catch (error) {
      console.error('Error fetching stats:', error);
    }
  }

  async function fetchInstanceDetails(workflowId: string) {
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id,
      });

      const response = await fetch(`/api/process-monitor/instance/${workflowId}?${params}`);
      if (!response.ok) throw new Error('Failed to fetch instance details');

      const data = await response.json();
      setSelectedInstance(data);
    } catch (error) {
      console.error('Error fetching instance details:', error);
    }
  }

  async function handleIntervention() {
    if (!selectedInstance) return;

    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id,
      });

      const response = await fetch(`/api/process-monitor/intervene?${params}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: interventionAction,
          workflow_id: selectedInstance.workflow_id,
          step_name: selectedInstance.current_step,
          reason: interventionReason,
        }),
      });

      if (!response.ok) throw new Error('Intervention failed');

      const result = await response.json();
      devLog('Intervention result:', result);

      // Refresh data
      fetchActiveInstances();
      setShowInterventionModal(false);
      setInterventionReason('');
    } catch (error) {
      console.error('Error executing intervention:', error);
      alert('Failed to execute intervention: ' + error);
    }
  }

  useEffect(() => {
    fetchActiveInstances();
    fetchStats();

    const interval = setInterval(() => {
      fetchActiveInstances();
      fetchStats();
    }, 30000); // Refresh every 30 seconds

    return () => clearInterval(interval);
  }, [tenant.id, datasource.id, filters]);

  useEffect(() => {
    if (filters.workflow_type || filters.status) {
      updateFilters(filters);
    }
  }, [filters, updateFilters]);

  const workflowTypes = useMemo(() => {
    const types = new Set(instances.map((i) => i.workflow_type));
    return Array.from(types);
  }, [instances]);

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'running':
        return 'text-blue-600 bg-blue-100';
      case 'completed':
        return 'text-green-600 bg-green-100';
      case 'failed':
        return 'text-red-600 bg-red-100';
      default:
        return 'text-gray-600 bg-gray-100';
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'running':
        return <Activity className="animate-pulse" size={16} />;
      case 'completed':
        return <CheckCircle2 size={16} />;
      case 'failed':
        return <AlertCircle size={16} />;
      default:
        return <Clock size={16} />;
    }
  };

  const formatDuration = (seconds: number | null) => {
    if (!seconds) return 'N/A';
    if (seconds < 60) return `${Math.round(seconds)}s`;
    if (seconds < 3600) return `${Math.round(seconds / 60)}m`;
    return `${Math.round(seconds / 3600)}h`;
  };

  const formatTimeRemaining = (minutes: number | null) => {
    if (!minutes) return 'No SLA';
    if (minutes < 0) return <span className="text-red-600 font-semibold">SLA Violated</span>;
    if (minutes < 60) return `${Math.round(minutes)}m remaining`;
    return `${Math.round(minutes / 60)}h remaining`;
  };

  return (
    <div className="h-full flex flex-col bg-gray-50">
      {/* Header */}
      <div className="bg-white border-b px-6 py-4">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-gray-900">Live Process Monitor</h1>
            <p className="text-sm text-gray-500 mt-1">
              Real-time visibility into running workflow instances
            </p>
          </div>
          <div className="flex items-center gap-3">
            <div className={`flex items-center gap-2 px-3 py-1.5 rounded-lg ${isConnected ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
              {isConnected ? <Wifi size={16} /> : <WifiOff size={16} />}
              <span className="text-sm font-medium">
                {isConnected ? 'Live' : 'Disconnected'}
              </span>
            </div>
          </div>
        </div>

        {/* Stats Row */}
        <div className="grid grid-cols-5 gap-4 mt-4">
          <div className="bg-gradient-to-br from-blue-50 to-blue-100 rounded-lg px-4 py-3">
            <div className="text-sm text-blue-600 font-medium">Total Active</div>
            <div className="text-2xl font-bold text-blue-700 mt-1">{stats.total_active}</div>
          </div>
          <div className="bg-gradient-to-br from-purple-50 to-purple-100 rounded-lg px-4 py-3">
            <div className="text-sm text-purple-600 font-medium">Running</div>
            <div className="text-2xl font-bold text-purple-700 mt-1 flex items-center gap-2">
              {stats.running_count}
              <Activity className="animate-pulse text-purple-500" size={20} />
            </div>
          </div>
          <div className="bg-gradient-to-br from-green-50 to-green-100 rounded-lg px-4 py-3">
            <div className="text-sm text-green-600 font-medium">Completed</div>
            <div className="text-2xl font-bold text-green-700 mt-1">{stats.completed_count}</div>
          </div>
          <div className="bg-gradient-to-br from-red-50 to-red-100 rounded-lg px-4 py-3">
            <div className="text-sm text-red-600 font-medium">Failed</div>
            <div className="text-2xl font-bold text-red-700 mt-1">{stats.failed_count}</div>
          </div>
          <div className="bg-gradient-to-br from-gray-50 to-gray-100 rounded-lg px-4 py-3">
            <div className="text-sm text-gray-600 font-medium">Workflow Types</div>
            <div className="text-2xl font-bold text-gray-700 mt-1">{stats.workflow_types}</div>
          </div>
        </div>

        {/* Filters */}
        <div className="flex items-center gap-3 mt-4">
          <Filter size={18} className="text-gray-500" />
          <select
            value={filters.workflow_type}
            onChange={(e) => setFilters({ ...filters, workflow_type: e.target.value })}
            className="px-3 py-1.5 border rounded-lg text-sm"
          >
            <option value="">All Workflow Types</option>
            {workflowTypes.map((type) => (
              <option key={type} value={type}>
                {type}
              </option>
            ))}
          </select>
          <select
            value={filters.status}
            onChange={(e) => setFilters({ ...filters, status: e.target.value })}
            className="px-3 py-1.5 border rounded-lg text-sm"
          >
            <option value="">All Statuses</option>
            <option value="running">Running</option>
            <option value="completed">Completed</option>
            <option value="failed">Failed</option>
          </select>
          {(filters.workflow_type || filters.status) && (
            <button
              onClick={() => setFilters({ workflow_type: '', status: '' })}
              className="text-sm text-gray-600 hover:text-gray-800 underline"
            >
              Clear Filters
            </button>
          )}
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-hidden flex">
        {/* Instance List */}
        <div className="w-1/2 border-r overflow-y-auto p-4">
          {instances.length === 0 ? (
            <div className="text-center py-12 text-gray-500">
              <Activity size={48} className="mx-auto mb-4 text-gray-400" />
              <p className="text-lg font-medium">No active process instances</p>
              <p className="text-sm mt-2">Instances will appear here when workflows are running</p>
            </div>
          ) : (
            <div className="space-y-3">
              {instances.map((instance) => (
                <div
                  key={instance.workflow_id}
                  onClick={() => fetchInstanceDetails(instance.workflow_id)}
                  className={`bg-white rounded-lg border-2 p-4 cursor-pointer transition-all hover:shadow-md ${
                    selectedInstance?.workflow_id === instance.workflow_id
                      ? 'border-blue-500 shadow-lg'
                      : 'border-gray-200'
                  }`}
                >
                  <div className="flex items-start justify-between">
                    <div className="flex-1">
                      <div className="flex items-center gap-2 mb-2">
                        <span className={`px-2 py-1 rounded-full text-xs font-medium flex items-center gap-1 ${getStatusColor(instance.status)}`}>
                          {getStatusIcon(instance.status)}
                          {instance.status}
                        </span>
                        <span className="text-xs text-gray-500">{instance.workflow_type}</span>
                      </div>
                      <div className="text-sm font-mono text-gray-600 mb-1">
                        {instance.workflow_id.substring(0, 12)}...
                      </div>
                      {instance.current_step && (
                        <div className="text-sm text-gray-700">
                          <span className="font-medium">Current:</span> {instance.current_step}
                        </div>
                      )}
                      <div className="flex items-center gap-4 mt-2 text-xs text-gray-500">
                        <span>{instance.steps_completed} / {instance.steps_total} steps</span>
                        <span>Health: {instance.health_score}%</span>
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="text-xs text-gray-500 mb-1">
                        {formatTimeRemaining(instance.time_remaining)}
                      </div>
                      <div className="text-xs text-gray-400">
                        {new Date(instance.last_activity_at).toLocaleTimeString()}
                      </div>
                    </div>
                  </div>
                  <div className="mt-2 bg-gray-100 rounded-full h-2 overflow-hidden">
                    <div
                      className={`h-full transition-all ${
                        instance.status === 'failed' ? 'bg-red-500' :
                        instance.status === 'completed' ? 'bg-green-500' :
                        'bg-blue-500'
                      }`}
                      style={{ width: `${(instance.steps_completed / instance.steps_total) * 100}%` }}
                    />
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Instance Details */}
        <div className="w-1/2 overflow-y-auto p-4">
          {!selectedInstance ? (
            <div className="text-center py-12 text-gray-500">
              <Play size={48} className="mx-auto mb-4 text-gray-400" />
              <p className="text-lg font-medium">Select an instance</p>
              <p className="text-sm mt-2">Click an instance to view details and execution history</p>
            </div>
          ) : (
            <div>
              <div className="bg-white rounded-lg border p-4 mb-4">
                <div className="flex items-start justify-between mb-4">
                  <div>
                    <h3 className="text-lg font-bold text-gray-900">{selectedInstance.workflow_type}</h3>
                    <p className="text-sm font-mono text-gray-500 mt-1">{selectedInstance.workflow_id}</p>
                  </div>
                  <button
                    onClick={() => setSelectedInstance(null)}
                    className="text-gray-400 hover:text-gray-600"
                  >
                    <X size={20} />
                  </button>
                </div>

                <div className="grid grid-cols-2 gap-4 mb-4">
                  <div>
                    <div className="text-xs text-gray-500">Status</div>
                    <div className={`mt-1 px-2 py-1 rounded-full text-sm font-medium inline-flex items-center gap-1 ${getStatusColor(selectedInstance.status)}`}>
                      {getStatusIcon(selectedInstance.status)}
                      {selectedInstance.status}
                    </div>
                  </div>
                  <div>
                    <div className="text-xs text-gray-500">Health Score</div>
                    <div className="text-2xl font-bold text-gray-900 mt-1">{selectedInstance.health_score}%</div>
                  </div>
                  <div>
                    <div className="text-xs text-gray-500">Steps Progress</div>
                    <div className="text-sm font-medium text-gray-900 mt-1">
                      {selectedInstance.steps_completed} / {selectedInstance.steps_total}
                    </div>
                  </div>
                  <div>
                    <div className="text-xs text-gray-500">Started</div>
                    <div className="text-sm font-medium text-gray-900 mt-1">
                      {new Date(selectedInstance.started_at).toLocaleString()}
                    </div>
                  </div>
                </div>

                {selectedInstance.status === 'running' && (
                  <div className="border-t pt-4">
                    <h4 className="text-sm font-semibold text-gray-700 mb-3">Intervention Actions</h4>
                    <div className="flex gap-2">
                      <button
                        onClick={() => {
                          setInterventionAction('skip_step');
                          setShowInterventionModal(true);
                        }}
                        className="flex items-center gap-2 px-3 py-2 bg-yellow-100 text-yellow-700 rounded-lg hover:bg-yellow-200 text-sm font-medium"
                      >
                        <SkipForward size={16} />
                        Skip Step
                      </button>
                      <button
                        onClick={() => {
                          setInterventionAction('reassign');
                          setShowInterventionModal(true);
                        }}
                        className="flex items-center gap-2 px-3 py-2 bg-blue-100 text-blue-700 rounded-lg hover:bg-blue-200 text-sm font-medium"
                      >
                        <UserPlus size={16} />
                        Reassign
                      </button>
                      <button
                        onClick={() => {
                          setInterventionAction('retry');
                          setShowInterventionModal(true);
                        }}
                        className="flex items-center gap-2 px-3 py-2 bg-green-100 text-green-700 rounded-lg hover:bg-green-200 text-sm font-medium"
                      >
                        <RefreshCw size={16} />
                        Retry
                      </button>
                      <button
                        onClick={() => {
                          setInterventionAction('cancel');
                          setShowInterventionModal(true);
                        }}
                        className="flex items-center gap-2 px-3 py-2 bg-red-100 text-red-700 rounded-lg hover:bg-red-200 text-sm font-medium"
                      >
                        <X size={16} />
                        Cancel
                      </button>
                    </div>
                  </div>
                )}
              </div>

              {/* Execution History */}
              {selectedInstance.execution_history && selectedInstance.execution_history.length > 0 && (
                <div className="bg-white rounded-lg border p-4">
                  <h4 className="text-sm font-semibold text-gray-700 mb-3">Execution History</h4>
                  <div className="space-y-2">
                    {selectedInstance.execution_history.map((step, idx) => (
                      <div key={idx} className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg">
                        <div className={`p-2 rounded-full ${getStatusColor(step.status)}`}>
                          {getStatusIcon(step.status)}
                        </div>
                        <div className="flex-1">
                          <div className="text-sm font-medium text-gray-900">{step.step_name}</div>
                          <div className="text-xs text-gray-500 mt-1">
                            {step.completed_at ? (
                              <>Duration: {formatDuration(step.duration)}</>
                            ) : (
                              <>Started: {new Date(step.started_at).toLocaleTimeString()}</>
                            )}
                          </div>
                          {step.error_msg && (
                            <div className="text-xs text-red-600 mt-1">{step.error_msg}</div>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Intervention Modal */}
      {showInterventionModal && selectedInstance && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-md w-full">
            <h3 className="text-lg font-bold text-gray-900 mb-4">
              Confirm Intervention: {interventionAction.replace('_', ' ').toUpperCase()}
            </h3>
            <p className="text-sm text-gray-600 mb-4">
              This will {interventionAction.replace('_', ' ')} for workflow: {selectedInstance.workflow_id}
            </p>
            <textarea
              value={interventionReason}
              onChange={(e) => setInterventionReason(e.target.value)}
              placeholder="Reason for intervention (required)"
              className="w-full px-3 py-2 border rounded-lg text-sm mb-4"
              rows={3}
              required
            />
            <div className="flex gap-3">
              <button
                onClick={handleIntervention}
                disabled={!interventionReason.trim()}
                className="flex-1 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 disabled:opacity-50 disabled:cursor-not-allowed font-medium"
              >
                Execute
              </button>
              <button
                onClick={() => {
                  setShowInterventionModal(false);
                  setInterventionReason('');
                }}
                className="flex-1 px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 font-medium"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import {
import { devLog} from '../../utils/devLogger';

  Zap,
  TrendingUp,
  Clock,
  DollarSign,
  CheckCircle2,
  X,
  AlertTriangle,
  Info,
  BarChart3,
  Settings,
  Play,
  RefreshCw,
  ThumbsUp,
  ThumbsDown,
  Sparkles,
  Target,
} from 'lucide-react';

interface ProcessOptimizationDashboardProps {
  tenant: { id: string; display_name: string };
  datasource: { id: string; source_name: string };
}

interface OptimizationSuggestion {
  id: string;
  workflow_type: string;
  suggestion_type: string;
  title: string;
  description: string;
  confidence_score: number;
  expected_improvement: string;
  impact_metrics: Record<string, any>;
  target_steps: string[];
  action_details: Record<string, any>;
  based_on_executions: number;
  status: string;
  priority: string;
  created_at: string;
}

interface AppliedOptimization {
  id: string;
  suggestion_id: string;
  workflow_type: string;
  applied_at: string;
  applied_by: string;
  before_metrics: Record<string, any>;
  after_metrics: Record<string, any>;
  actual_improvement: number;
  rollback_available: boolean;
}

export const ProcessOptimizationDashboard: React.FC<ProcessOptimizationDashboardProps> = ({
  tenant,
  datasource,
}) => {
  const [suggestions, setSuggestions] = useState<OptimizationSuggestion[]>([]);
  const [appliedOptimizations, setAppliedOptimizations] = useState<AppliedOptimization[]>([]);
  const [selectedSuggestion, setSelectedSuggestion] = useState<OptimizationSuggestion | null>(null);
  const [viewMode, setViewMode] = useState<'suggestions' | 'applied' | 'auto-tune'>('suggestions');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [autoTuneEnabled, setAutoTuneEnabled] = useState(false);
  const [confidenceThreshold, setConfidenceThreshold] = useState(80);

  async function fetchSuggestions() {
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id,
        status: 'pending',
      });

      const response = await fetch(`/api/process-optimization/suggestions?${params}`);
      if (!response.ok) throw new Error('Failed to fetch suggestions');

      const data = await response.json();
      setSuggestions(data || []);
    } catch (error) {
      console.error('Error fetching suggestions:', error);
    }
  }

  async function fetchApplied() {
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id,
      });

      const response = await fetch(`/api/process-optimization/applied?${params}`);
      if (!response.ok) throw new Error('Failed to fetch applied');

      const data = await response.json();
      setAppliedOptimizations(data || []);
    } catch (error) {
      console.error('Error fetching applied:', error);
    }
  }

  async function runAnalysis() {
    setIsAnalyzing(true);
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id,
      });

      const response = await fetch(`/api/process-optimization/analyze?${params}`, {
        method: 'POST',
      });

      if (!response.ok) throw new Error('Analysis failed');

      const data = await response.json();
      devLog(`Generated ${data.suggestions_generated} suggestions`);

      await fetchSuggestions();
    } catch (error) {
      console.error('Error running analysis:', error);
      alert('Failed to run analysis: ' + error);
    } finally {
      setIsAnalyzing(false);
    }
  }

  async function applySuggestion(suggestionId: string) {
    if (!confirm('Apply this optimization? This will modify your workflow definition.')) {
      return;
    }

    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id,
      });

      const response = await fetch(`/api/process-optimization/apply/${suggestionId}?${params}`, {
        method: 'POST',
      });

      if (!response.ok) throw new Error('Failed to apply optimization');

      const data = await response.json();
      devLog('Applied:', data);

      await fetchSuggestions();
      await fetchApplied();
      setSelectedSuggestion(null);
    } catch (error) {
      console.error('Error applying suggestion:', error);
      alert('Failed to apply optimization: ' + error);
    }
  }

  async function dismissSuggestion(suggestionId: string) {
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id,
      });

      const response = await fetch(`/api/process-optimization/dismiss/${suggestionId}?${params}`, {
        method: 'POST',
      });

      if (!response.ok) throw new Error('Failed to dismiss suggestion');

      await fetchSuggestions();
      setSelectedSuggestion(null);
    } catch (error) {
      console.error('Error dismissing suggestion:', error);
    }
  }

  async function toggleAutoTune() {
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id,
      });

      const response = await fetch(`/api/process-optimization/auto-tune/enable?${params}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          enabled: !autoTuneEnabled,
          confidence_threshold: confidenceThreshold,
          auto_apply_types: ['sla_adjustment'],
        }),
      });

      if (!response.ok) throw new Error('Failed to toggle auto-tune');

      setAutoTuneEnabled(!autoTuneEnabled);
    } catch (error) {
      console.error('Error toggling auto-tune:', error);
    }
  }

  useEffect(() => {
    fetchSuggestions();
    fetchApplied();

    const interval = setInterval(() => {
      if (viewMode === 'suggestions') fetchSuggestions();
      else if (viewMode === 'applied') fetchApplied();
    }, 60000);

    return () => clearInterval(interval);
  }, [tenant.id, datasource.id, viewMode]);

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'critical':
        return 'text-red-600 bg-red-100 border-red-300';
      case 'high':
        return 'text-orange-600 bg-orange-100 border-orange-300';
      case 'medium':
        return 'text-yellow-600 bg-yellow-100 border-yellow-300';
      default:
        return 'text-gray-600 bg-gray-100 border-gray-300';
    }
  };

  const getSuggestionIcon = (type: string) => {
    switch (type) {
      case 'parallel_execution':
        return <Zap size={20} className="text-purple-600" />;
      case 'reorder_steps':
        return <RefreshCw size={20} className="text-blue-600" />;
      case 'remove_step':
        return <X size={20} className="text-red-600" />;
      case 'sla_adjustment':
        return <Clock size={20} className="text-green-600" />;
      case 'resource_allocation':
        return <Settings size={20} className="text-orange-600" />;
      default:
        return <Sparkles size={20} className="text-gray-600" />;
    }
  };

  return (
    <div className="h-full flex flex-col bg-gray-50">
      {/* Header */}
      <div className="bg-white border-b px-6 py-4">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-2">
              <Sparkles size={28} className="text-purple-600" />
              AI Process Optimization
            </h1>
            <p className="text-sm text-gray-500 mt-1">
              ML-powered suggestions to improve workflow performance
            </p>
          </div>
          <div className="flex items-center gap-3">
            <button
              onClick={runAnalysis}
              disabled={isAnalyzing}
              className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 disabled:opacity-50 flex items-center gap-2 font-medium transition-all"
            >
              {isAnalyzing ? (
                <>
                  <RefreshCw size={18} className="animate-spin" />
                  Analyzing...
                </>
              ) : (
                <>
                  <Target size={18} />
                  Run Analysis
                </>
              )}
            </button>
          </div>
        </div>

        {/* View Tabs */}
        <div className="flex gap-2 mt-4">
          <button
            onClick={() => setViewMode('suggestions')}
            className={`px-4 py-2 rounded-lg font-medium transition-all ${
              viewMode === 'suggestions'
                ? 'bg-purple-600 text-white'
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
          >
            Suggestions ({suggestions.length})
          </button>
          <button
            onClick={() => setViewMode('applied')}
            className={`px-4 py-2 rounded-lg font-medium transition-all ${
              viewMode === 'applied'
                ? 'bg-purple-600 text-white'
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
          >
            Applied ({appliedOptimizations.length})
          </button>
          <button
            onClick={() => setViewMode('auto-tune')}
            className={`px-4 py-2 rounded-lg font-medium transition-all ${
              viewMode === 'auto-tune'
                ? 'bg-purple-600 text-white'
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
          >
            Auto-Tune
          </button>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-hidden flex">
        {viewMode === 'suggestions' && (
          <>
            {/* Suggestions List */}
            <div className="w-1/2 border-r overflow-y-auto p-4">
              {suggestions.length === 0 ? (
                <div className="text-center py-12 text-gray-500">
                  <Sparkles size={48} className="mx-auto mb-4 text-gray-400" />
                  <p className="text-lg font-medium">No suggestions yet</p>
                  <p className="text-sm mt-2">Click "Run Analysis" to generate optimization suggestions</p>
                </div>
              ) : (
                <div className="space-y-3">
                  {suggestions.map((suggestion) => (
                    <div
                      key={suggestion.id}
                      onClick={() => setSelectedSuggestion(suggestion)}
                      className={`bg-white rounded-lg border-2 p-4 cursor-pointer transition-all hover:shadow-md ${
                        selectedSuggestion?.id === suggestion.id
                          ? 'border-purple-500 shadow-lg'
                          : 'border-gray-200'
                      }`}
                    >
                      <div className="flex items-start gap-3">
                        <div className="p-2 rounded-lg bg-gray-50">
                          {getSuggestionIcon(suggestion.suggestion_type)}
                        </div>
                        <div className="flex-1">
                          <div className="flex items-center gap-2 mb-2">
                            <span className={`px-2 py-1 rounded-full text-xs font-medium border ${getPriorityColor(suggestion.priority)}`}>
                              {suggestion.priority}
                            </span>
                            <span className="text-xs text-gray-500">
                              {suggestion.suggestion_type.replace(/_/g, ' ')}
                            </span>
                          </div>
                          <h3 className="text-sm font-semibold text-gray-900 mb-1">
                            {suggestion.title}
                          </h3>
                          <p className="text-xs text-gray-600 line-clamp-2 mb-2">
                            {suggestion.description}
                          </p>
                          <div className="flex items-center gap-4 text-xs text-gray-500">
                            <span className="flex items-center gap-1">
                              <TrendingUp size={14} />
                              {suggestion.confidence_score}% confidence
                            </span>
                            <span className="flex items-center gap-1">
                              <BarChart3 size={14} />
                              {suggestion.based_on_executions} samples
                            </span>
                          </div>
                        </div>
                      </div>
                      <div className="mt-3 p-2 bg-green-50 rounded text-xs text-green-700 font-medium">
                        💡 {suggestion.expected_improvement}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Suggestion Details */}
            <div className="w-1/2 overflow-y-auto p-4">
              {!selectedSuggestion ? (
                <div className="text-center py-12 text-gray-500">
                  <Info size={48} className="mx-auto mb-4 text-gray-400" />
                  <p className="text-lg font-medium">Select a suggestion</p>
                  <p className="text-sm mt-2">Click a suggestion to view details and take action</p>
                </div>
              ) : (
                <div>
                  <div className="bg-white rounded-lg border p-6 mb-4">
                    <div className="flex items-start justify-between mb-4">
                      <div className="flex items-center gap-3">
                        <div className="p-3 rounded-xl bg-purple-100">
                          {getSuggestionIcon(selectedSuggestion.suggestion_type)}
                        </div>
                        <div>
                          <h2 className="text-xl font-bold text-gray-900">
                            {selectedSuggestion.title}
                          </h2>
                          <p className="text-sm text-gray-500 mt-1">
                            {selectedSuggestion.workflow_type}
                          </p>
                        </div>
                      </div>
                      <button
                        onClick={() => setSelectedSuggestion(null)}
                        className="text-gray-400 hover:text-gray-600"
                      >
                        <X size={20} />
                      </button>
                    </div>

                    <div className="space-y-4">
                      <div>
                        <h4 className="text-sm font-semibold text-gray-700 mb-2">Description</h4>
                        <p className="text-sm text-gray-600">{selectedSuggestion.description}</p>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                        <div>
                          <h4 className="text-xs font-semibold text-gray-700 mb-1">Confidence Score</h4>
                          <div className="flex items-center gap-2">
                            <div className="flex-1 bg-gray-200 rounded-full h-2">
                              <div
                                className="bg-purple-600 h-2 rounded-full"
                                style={{ width: `${selectedSuggestion.confidence_score}%` }}
                              />
                            </div>
                            <span className="text-sm font-bold text-purple-600">
                              {selectedSuggestion.confidence_score}%
                            </span>
                          </div>
                        </div>
                        <div>
                          <h4 className="text-xs font-semibold text-gray-700 mb-1">Based On</h4>
                          <p className="text-sm text-gray-900">
                            {selectedSuggestion.based_on_executions} executions
                          </p>
                        </div>
                      </div>

                      {selectedSuggestion.target_steps.length > 0 && (
                        <div>
                          <h4 className="text-sm font-semibold text-gray-700 mb-2">Affected Steps</h4>
                          <div className="flex flex-wrap gap-2">
                            {selectedSuggestion.target_steps.map((step, idx) => (
                              <span
                                key={idx}
                                className="px-3 py-1 bg-blue-100 text-blue-700 rounded-full text-xs font-medium"
                              >
                                {step}
                              </span>
                            ))}
                          </div>
                        </div>
                      )}

                      <div>
                        <h4 className="text-sm font-semibold text-gray-700 mb-2">Expected Impact</h4>
                        <div className="bg-gradient-to-r from-green-50 to-emerald-50 border border-green-200 rounded-lg p-4">
                          <div className="flex items-center gap-2 mb-3">
                            <TrendingUp size={20} className="text-green-600" />
                            <span className="text-sm font-semibold text-green-800">
                              {selectedSuggestion.expected_improvement}
                            </span>
                          </div>
                          {Object.entries(selectedSuggestion.impact_metrics).map(([key, value]) => (
                            <div key={key} className="flex justify-between text-xs text-gray-600 mb-1">
                              <span>{key.replace(/_/g, ' ')}:</span>
                              <span className="font-medium">{JSON.stringify(value)}</span>
                            </div>
                          ))}
                        </div>
                      </div>

                      <div className="border-t pt-4">
                        <h4 className="text-sm font-semibold text-gray-700 mb-2">Action Details</h4>
                        <pre className="text-xs bg-gray-50 p-3 rounded overflow-x-auto">
                          {JSON.stringify(selectedSuggestion.action_details, null, 2)}
                        </pre>
                      </div>
                    </div>
                  </div>

                  {/* Action Buttons */}
                  <div className="flex gap-3">
                    <button
                      onClick={() => applySuggestion(selectedSuggestion.id)}
                      className="flex-1 px-6 py-3 bg-gradient-to-r from-green-600 to-emerald-600 text-white rounded-lg hover:from-green-700 hover:to-emerald-700 font-semibold flex items-center justify-center gap-2 shadow-lg hover:shadow-xl transition-all"
                    >
                      <CheckCircle2 size={20} />
                      Apply Optimization
                    </button>
                    <button
                      onClick={() => dismissSuggestion(selectedSuggestion.id)}
                      className="flex-1 px-6 py-3 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 font-semibold flex items-center justify-center gap-2 transition-all"
                    >
                      <ThumbsDown size={20} />
                      Dismiss
                    </button>
                  </div>
                </div>
              )}
            </div>
          </>
        )}

        {viewMode === 'applied' && (
          <div className="flex-1 overflow-y-auto p-4">
            {appliedOptimizations.length === 0 ? (
              <div className="text-center py-12 text-gray-500">
                <CheckCircle2 size={48} className="mx-auto mb-4 text-gray-400" />
                <p className="text-lg font-medium">No applied optimizations yet</p>
                <p className="text-sm mt-2">Applied optimizations will appear here</p>
              </div>
            ) : (
              <div className="grid grid-cols-2 gap-4">
                {appliedOptimizations.map((opt) => (
                  <div key={opt.id} className="bg-white rounded-lg border p-4">
                    <div className="flex items-center gap-2 mb-3">
                      <CheckCircle2 size={18} className="text-green-600" />
                      <h3 className="font-semibold text-gray-900">{opt.workflow_type}</h3>
                    </div>
                    <div className="space-y-2 text-sm text-gray-600">
                      <div>
                        <span className="font-medium">Applied:</span>{' '}
                        {new Date(opt.applied_at).toLocaleString()}
                      </div>
                      <div>
                        <span className="font-medium">By:</span> {opt.applied_by}
                      </div>
                      {opt.actual_improvement > 0 && (
                        <div className="flex items-center gap-2 text-green-600 font-semibold">
                          <TrendingUp size={16} />
                          {opt.actual_improvement.toFixed(1)}% improvement
                        </div>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {viewMode === 'auto-tune' && (
          <div className="flex-1 overflow-y-auto p-6">
            <div className="max-w-2xl mx-auto">
              <div className="bg-white rounded-lg border p-6 mb-6">
                <h2 className="text-xl font-bold text-gray-900 mb-4">Auto-Tune Configuration</h2>

                <div className="space-y-6">
                  <div className="flex items-center justify-between">
                    <div>
                      <h4 className="font-semibold text-gray-900">Enable Auto-Tune</h4>
                      <p className="text-sm text-gray-600 mt-1">
                        Automatically apply low-risk optimizations
                      </p>
                    </div>
                    <button
                      onClick={toggleAutoTune}
                      className={`relative inline-flex h-8 w-14 items-center rounded-full transition-colors ${
                        autoTuneEnabled ? 'bg-purple-600' : 'bg-gray-300'
                      }`}
                    >
                      <span
                        className={`inline-block h-6 w-6 transform rounded-full bg-white transition-transform ${
                          autoTuneEnabled ? 'translate-x-7' : 'translate-x-1'
                        }`}
                      />
                    </button>
                  </div>

                  <div>
                    <label className="block text-sm font-semibold text-gray-900 mb-2">
                      Confidence Threshold: {confidenceThreshold}%
                    </label>
                    <input
                      type="range"
                      min="50"
                      max="95"
                      step="5"
                      value={confidenceThreshold}
                      onChange={(e) => setConfidenceThreshold(parseInt(e.target.value))}
                      className="w-full"
                    />
                    <p className="text-xs text-gray-600 mt-1">
                      Only apply suggestions with confidence above this threshold
                    </p>
                  </div>

                  <div className="border-t pt-6">
                    <h4 className="font-semibold text-gray-900 mb-3">Auto-Apply Types</h4>
                    <div className="space-y-2">
                      {['SLA Adjustment', 'Resource Allocation'].map((type) => (
                        <label key={type} className="flex items-center gap-2">
                          <input
                            type="checkbox"
                            defaultChecked={type === 'SLA Adjustment'}
                            className="rounded"
                          />
                          <span className="text-sm text-gray-700">{type}</span>
                        </label>
                      ))}
                    </div>
                  </div>
                </div>
              </div>

              <div className="bg-gradient-to-r from-blue-50 to-purple-50 border border-purple-200 rounded-lg p-6">
                <div className="flex items-start gap-3">
                  <Info size={24} className="text-purple-600 flex-shrink-0 mt-1" />
                  <div>
                    <h4 className="font-semibold text-purple-900 mb-2">About Auto-Tune</h4>
                    <p className="text-sm text-purple-800 mb-3">
                      Auto-Tune continuously monitors your workflows and applies safe, proven optimizations automatically.
                    </p>
                    <ul className="text-sm text-purple-700 space-y-1 list-disc list-inside">
                      <li>Only applies optimizations above confidence threshold</li>
                      <li>Rollback available for all changes</li>
                      <li>Weekly reports sent to your email</li>
                      <li>Can be disabled anytime</li>
                    </ul>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import {
  Package, Search, Star, Users, Clock, ChevronRight, Copy, CheckCircle,
  FileText, AlertCircle, BookOpen, TrendingUp, Award, Filter, X, Eye,
  Download, Heart, MessageSquare, ThumbsUp, BarChart3
} from 'lucide-react';

// ============================================================================
// TYPES
// ============================================================================

interface ProcessTemplate {
  id: string;
  template_key: string;
  name: string;
  description: string;
  category: string;
  tags: string[];
  icon_name: string;
  difficulty_level: 'beginner' | 'intermediate' | 'advanced';
  estimated_setup_time_minutes: number;
  is_official: boolean;
  is_featured: boolean;
  template_definition: any;
  customization_guide: string;
  example_use_cases: string[];
  author_name: string;
  author_organization: string;
  version: string;
  usage_count: number;
  clone_count: number;
  favorite_count: number;
  rating_average: number;
  rating_count: number;
  screenshot_url: string;
  documentation_url: string;
  demo_video_url: string;
  created_at: string;
  published_at: string;
}

interface TemplateCategory {
  id: string;
  category_key: string;
  display_name: string;
  description: string;
  icon_name: string;
  template_count: number;
}

interface TemplateRating {
  id: string;
  rating: number;
  review_text: string;
  review_title: string;
  reviewer_name: string;
  reviewer_role: string;
  helpful_count: number;
  is_verified_user: boolean;
  created_at: string;
}

interface Tenant {
  id: string;
  display_name: string;
}

interface Datasource {
  id: string;
  source_name: string;
}

interface Props {
  tenant: Tenant;
  datasource: Datasource;
  onTemplateCloned?: (processId: string) => void;
}

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export const ProcessTemplatesLibrary: React.FC<Props> = ({ tenant, datasource, onTemplateCloned }) => {
  const [viewMode, setViewMode] = useState<'browse' | 'preview' | 'clones'>('browse');
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<'rating' | 'usage' | 'recent' | 'name'>('rating');
  const [difficultyFilter, setDifficultyFilter] = useState<string>('all');

  const [templates, setTemplates] = useState<ProcessTemplate[]>([]);
  const [categories, setCategories] = useState<TemplateCategory[]>([]);
  const [featuredTemplates, setFeaturedTemplates] = useState<ProcessTemplate[]>([]);
  const [selectedTemplate, setSelectedTemplate] = useState<ProcessTemplate | null>(null);
  const [ratings, setRatings] = useState<TemplateRating[]>([]);

  const [showCloneModal, setShowCloneModal] = useState(false);
  const [cloning, setCloning] = useState(false);
  const [processName, setProcessName] = useState('');
  const [customizationNotes, setCustomizationNotes] = useState('');

  // Fetch categories
  useEffect(() => {
    fetchCategories();
    fetchFeaturedTemplates();
  }, []);

  // Fetch templates when filters change
  useEffect(() => {
    if (viewMode === 'browse') {
      fetchTemplates();
    }
  }, [selectedCategory, searchQuery, sortBy, difficultyFilter, viewMode]);

  const fetchCategories = async () => {
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id
      });
      const response = await fetch(`/api/templates/categories?${params}`);
      const data = await response.json();
      setCategories(data || []);
    } catch (error) {
      console.error('Failed to fetch categories:', error);
    }
  };

  const fetchFeaturedTemplates = async () => {
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id
      });
      const response = await fetch(`/api/templates/featured?${params}`);
      const data = await response.json();
      setFeaturedTemplates(data || []);
    } catch (error) {
      console.error('Failed to fetch featured templates:', error);
    }
  };

  const fetchTemplates = async () => {
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id,
        sort_by: sortBy
      });

      if (selectedCategory !== 'all') {
        params.set('category', selectedCategory);
      }
      if (searchQuery) {
        params.set('search', searchQuery);
      }
      if (difficultyFilter !== 'all') {
        params.set('difficulty', difficultyFilter);
      }

      const response = await fetch(`/api/templates?${params}`);
      const data = await response.json();
      setTemplates(data || []);
    } catch (error) {
      console.error('Failed to fetch templates:', error);
    }
  };

  const fetchTemplateRatings = async (templateId: string) => {
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id
      });
      const response = await fetch(`/api/templates/${templateId}/ratings?${params}`);
      const data = await response.json();
      setRatings(data || []);
    } catch (error) {
      console.error('Failed to fetch ratings:', error);
    }
  };

  const handleTemplateClick = async (template: ProcessTemplate) => {
    setSelectedTemplate(template);
    setProcessName(template.name + ' (Copy)');
    setViewMode('preview');
    fetchTemplateRatings(template.id);
  };

  const handleCloneTemplate = async () => {
    if (!selectedTemplate) return;

    setCloning(true);
    try {
      const params = new URLSearchParams({
        tenant_id: tenant.id,
        datasource_id: datasource.id
      });

      const response = await fetch(`/api/templates/clone/${selectedTemplate.id}?${params}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          process_name: processName,
          customization_notes: customizationNotes,
          cloned_by: 'current_user' // Replace with actual user ID
        })
      });

      if (response.ok) {
        const result = await response.json();
        alert(`Template cloned successfully! Process ID: ${result.process_id}`);
        setShowCloneModal(false);
        setViewMode('browse');
        if (onTemplateCloned) {
          onTemplateCloned(result.process_id);
        }
      } else {
        alert('Failed to clone template');
      }
    } catch (error) {
      console.error('Failed to clone template:', error);
      alert('Failed to clone template');
    } finally {
      setCloning(false);
    }
  };

  const getCategoryIcon = (iconName: string) => {
    const icons: any = {
      CheckCircle, FileText, Users, Clock, AlertCircle, Package, TrendingUp
    };
    return icons[iconName] || FileText;
  };

  const getDifficultyColor = (level: string) => {
    switch (level) {
      case 'beginner': return 'bg-green-100 text-green-700';
      case 'intermediate': return 'bg-yellow-100 text-yellow-700';
      case 'advanced': return 'bg-red-100 text-red-700';
      default: return 'bg-gray-100 text-gray-700';
    }
  };

  return (
    <div className="h-full flex flex-col bg-gray-50">
      {/* Header */}
      <div className="bg-gradient-to-r from-indigo-600 to-purple-600 text-white p-6 shadow-lg">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Package size={32} />
            <div>
              <h1 className="text-2xl font-bold">Process Templates Library</h1>
              <p className="text-indigo-100 text-sm">Start faster with pre-built workflow templates</p>
            </div>
          </div>

          {/* View Mode Buttons */}
          <div className="flex gap-2">
            <button
              onClick={() => setViewMode('browse')}
              className={`px-4 py-2 rounded-lg font-medium transition-all ${
                viewMode === 'browse'
                  ? 'bg-white text-indigo-600'
                  : 'bg-indigo-500 text-white hover:bg-indigo-400'
              }`}
            >
              Browse Templates
            </button>
            <button
              onClick={() => setViewMode('clones')}
              className={`px-4 py-2 rounded-lg font-medium transition-all ${
                viewMode === 'clones'
                  ? 'bg-white text-indigo-600'
                  : 'bg-indigo-500 text-white hover:bg-indigo-400'
              }`}
            >
              My Clones
            </button>
          </div>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        {/* Browse View */}
        {viewMode === 'browse' && (
          <>
            {/* Sidebar */}
            <div className="w-64 bg-white border-r border-gray-200 p-4 overflow-y-auto">
              <div className="space-y-6">
                {/* Search */}
                <div>
                  <label className="text-sm font-medium text-gray-700 mb-2 block">Search</label>
                  <div className="relative">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
                    <input
                      type="text"
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      placeholder="Search templates..."
                      className="w-full pl-10 pr-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
                    />
                  </div>
                </div>

                {/* Categories */}
                <div>
                  <label className="text-sm font-medium text-gray-700 mb-2 block">Categories</label>
                  <div className="space-y-1">
                    <button
                      onClick={() => setSelectedCategory('all')}
                      className={`w-full flex items-center justify-between px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                        selectedCategory === 'all'
                          ? 'bg-indigo-100 text-indigo-700'
                          : 'text-gray-700 hover:bg-gray-100'
                      }`}
                    >
                      <span>All Templates</span>
                      <span className="text-xs">{templates.length}</span>
                    </button>
                    {categories.map((cat) => {
                      const Icon = getCategoryIcon(cat.icon_name);
                      return (
                        <button
                          key={cat.id}
                          onClick={() => setSelectedCategory(cat.category_key)}
                          className={`w-full flex items-center justify-between px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                            selectedCategory === cat.category_key
                              ? 'bg-indigo-100 text-indigo-700'
                              : 'text-gray-700 hover:bg-gray-100'
                          }`}
                        >
                          <div className="flex items-center gap-2">
                            <Icon size={16} />
                            <span>{cat.display_name}</span>
                          </div>
                          <span className="text-xs">{cat.template_count}</span>
                        </button>
                      );
                    })}
                  </div>
                </div>

                {/* Difficulty Filter */}
                <div>
                  <label className="text-sm font-medium text-gray-700 mb-2 block">Difficulty</label>
                  <select
                    value={difficultyFilter}
                    onChange={(e) => setDifficultyFilter(e.target.value)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500"
                  >
                    <option value="all">All Levels</option>
                    <option value="beginner">Beginner</option>
                    <option value="intermediate">Intermediate</option>
                    <option value="advanced">Advanced</option>
                  </select>
                </div>

                {/* Sort By */}
                <div>
                  <label className="text-sm font-medium text-gray-700 mb-2 block">Sort By</label>
                  <select
                    value={sortBy}
                    onChange={(e) => setSortBy(e.target.value as any)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500"
                  >
                    <option value="rating">Highest Rated</option>
                    <option value="usage">Most Popular</option>
                    <option value="recent">Recently Added</option>
                    <option value="name">Name (A-Z)</option>
                  </select>
                </div>
              </div>
            </div>

            {/* Main Content */}
            <div className="flex-1 overflow-y-auto p-6">
              {/* Featured Templates */}
              {selectedCategory === 'all' && featuredTemplates.length > 0 && (
                <div className="mb-8">
                  <div className="flex items-center gap-2 mb-4">
                    <Award className="text-yellow-500" size={24} />
                    <h2 className="text-xl font-bold text-gray-900">Featured Templates</h2>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {featuredTemplates.map((template) => (
                      <TemplateCard
                        key={template.id}
                        template={template}
                        onClick={() => handleTemplateClick(template)}
                        getDifficultyColor={getDifficultyColor}
                      />
                    ))}
                  </div>
                </div>
              )}

              {/* All Templates */}
              <div>
                <h2 className="text-xl font-bold text-gray-900 mb-4">
                  {selectedCategory === 'all' ? 'All Templates' : categories.find(c => c.category_key === selectedCategory)?.display_name}
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {templates.map((template) => (
                    <TemplateCard
                      key={template.id}
                      template={template}
                      onClick={() => handleTemplateClick(template)}
                      getDifficultyColor={getDifficultyColor}
                    />
                  ))}
                </div>
                {templates.length === 0 && (
                  <div className="text-center py-12">
                    <Package className="mx-auto text-gray-400 mb-4" size={48} />
                    <p className="text-gray-500 text-lg">No templates found</p>
                    <p className="text-gray-400 text-sm">Try adjusting your filters</p>
                  </div>
                )}
              </div>
            </div>
          </>
        )}

        {/* Preview View */}
        {viewMode === 'preview' && selectedTemplate && (
          <div className="flex-1 overflow-y-auto">
            <TemplatePreview
              template={selectedTemplate}
              ratings={ratings}
              onBack={() => setViewMode('browse')}
              onClone={() => setShowCloneModal(true)}
              getDifficultyColor={getDifficultyColor}
            />
          </div>
        )}

        {/* My Clones View */}
        {viewMode === 'clones' && (
          <div className="flex-1 overflow-y-auto p-6">
            <div className="text-center py-12">
              <Copy className="mx-auto text-gray-400 mb-4" size={48} />
              <p className="text-gray-500 text-lg">Your cloned templates will appear here</p>
              <p className="text-gray-400 text-sm">Start by cloning a template from the library</p>
            </div>
          </div>
        )}
      </div>

      {/* Clone Modal */}
      {showCloneModal && selectedTemplate && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b border-gray-200">
              <div className="flex items-center justify-between">
                <h3 className="text-xl font-bold text-gray-900">Clone Template</h3>
                <button
                  onClick={() => setShowCloneModal(false)}
                  className="text-gray-400 hover:text-gray-600"
                >
                  <X size={24} />
                </button>
              </div>
            </div>

            <div className="p-6 space-y-6">
              <div>
                <h4 className="font-semibold text-gray-900 mb-2">{selectedTemplate.name}</h4>
                <p className="text-gray-600 text-sm">{selectedTemplate.description}</p>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Process Name <span className="text-red-500">*</span>
                </label>
                <input
                  type="text"
                  value={processName}
                  onChange={(e) => setProcessName(e.target.value)}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500"
                  placeholder="Enter a name for your process"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Customization Notes (Optional)
                </label>
                <textarea
                  value={customizationNotes}
                  onChange={(e) => setCustomizationNotes(e.target.value)}
                  rows={4}
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500"
                  placeholder="Add notes about how you plan to customize this template..."
                />
              </div>

              {selectedTemplate.customization_guide && (
                <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                  <div className="flex items-start gap-2">
                    <BookOpen className="text-blue-600 flex-shrink-0 mt-1" size={20} />
                    <div>
                      <h5 className="font-medium text-blue-900 mb-1">Customization Guide</h5>
                      <p className="text-blue-700 text-sm whitespace-pre-wrap">{selectedTemplate.customization_guide}</p>
                    </div>
                  </div>
                </div>
              )}
            </div>

            <div className="p-6 border-t border-gray-200 flex justify-end gap-3">
              <button
                onClick={() => setShowCloneModal(false)}
                className="px-6 py-2 border border-gray-300 rounded-lg hover:bg-gray-50 font-medium"
                disabled={cloning}
              >
                Cancel
              </button>
              <button
                onClick={handleCloneTemplate}
                disabled={!processName || cloning}
                className="px-6 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 font-medium disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
              >
                {cloning ? (
                  <>
                    <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent" />
                    Cloning...
                  </>
                ) : (
                  <>
                    <Copy size={18} />
                    Clone Template
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

