        {/* Pending Dependencies */}
        {status.pending_dependencies && status.pending_dependencies.length > 0 && (
          <Box sx={{ mb: 3 }}>
            <Typography variant="subtitle2" gutterBottom>
              Pending Dependencies ({status.pending_dependencies.length})
