/**
 * Get template by name
 */
export function getTemplate(name: keyof typeof ComponentTemplates): CustomComponent {
  const templateFn = ComponentTemplates[name];
  if (!templateFn) {
    throw new Error(`Template not found: ${name}`);
  }
  return templateFn();
}

