import { Database, Link, Unlink } from 'lucide-react'
import FolderIcon from '@mui/icons-material/Folder'
import TableChartIcon from '@mui/icons-material/TableChart'
import ViewColumnIcon from '@mui/icons-material/ViewColumn'
import AccountTreeIcon from '@mui/icons-material/AccountTree'
import RefreshIcon from '@mui/icons-material/Refresh'
import ExpandLess from '@mui/icons-material/ExpandLess'
import ExpandMore from '@mui/icons-material/ExpandMore'
import { hasTenantScope } from '../utils/tenantScope'

type CatalogNode = {
  id: string
  node_name: string
  qualified_path?: string
  catalog_type?: string
  parent_id?: string
  properties?: any
}

interface DatabaseTreePanelProps {
  title?: string
  subtitle?: string
  showColumnSelection?: boolean
  showSchemaSelection?: boolean
  showTableSelection?: boolean
  showColumns?: boolean
  onSelectionChange?: (selectedSchemas: string[], selectedTables: string[], selectedColumns: string[]) => void
  initialSelectedSchemas?: string[]
  initialSelectedTables?: string[]
  initialSelectedColumns?: string[]
  height?: string
  // Filter props
  // Filter props
  mappedFilter?: Set<string>
  setMappedFilter?: (filter: Set<any>) => void
  mappingCounts?: { all: number; mapped: number; unmapped: number; pending: number }
  mappings?: any[]
}

export default function DatabaseTreePanel({
  title = "Database",
  subtitle = "Schemas, tables, and columns",
  showColumnSelection = false,
  showSchemaSelection: _showSchemaSelection = true,
  showTableSelection: _showTableSelection = true,
  showColumns = true,
  onSelectionChange,
  initialSelectedSchemas = [],
  initialSelectedTables = [],
  initialSelectedColumns = [],
  height = '72vh',
  mappedFilter,
  setMappedFilter,
  mappingCounts,
  mappings = []
}: DatabaseTreePanelProps) {
  const [schemas, setSchemas] = useState<CatalogNode[]>([])
  const [expandedSchemas, setExpandedSchemas] = useState<string[]>([])
  const [expandedTables, setExpandedTables] = useState<string[]>([])
  const [tablesBySchema, setTablesBySchema] = useState<Record<string, CatalogNode[]>>({})
  const [columnsByTable, setColumnsByTable] = useState<Record<string, CatalogNode[]>>({})
  const [selectedSchemas, setSelectedSchemas] = useState<string[]>(initialSelectedSchemas)
  const [selectedTables, setSelectedTables] = useState<string[]>(initialSelectedTables)
  const [selectedColumns, setSelectedColumns] = useState<string[]>(initialSelectedColumns)
  const [loading, setLoading] = useState(false)

  const canUseScope = hasTenantScope()
  const scope = useScope()

  // Calculate match counts per schema and table
  const matchCounts = useMemo(() => {
    const counts: Record<string, { schema: number; tables: Record<string, number> }> = {}

    mappings.forEach((mapping: any) => {
      if (mapping.ignored) return

      const schemaName = mapping.database_column?.schema || ''
      const tableName = mapping.database_column?.table || ''

      if (!counts[schemaName]) {
        counts[schemaName] = { schema: 0, tables: {} }
      }

      counts[schemaName].schema++

      if (!counts[schemaName].tables[tableName]) {
        counts[schemaName].tables[tableName] = 0
      }

      counts[schemaName].tables[tableName]++
    })

    return counts
  }, [mappings])

  const makeApiUrl = (path: string) => {
    try {
      if ((typeof process !== 'undefined' && process.env && process.env.NODE_ENV === 'test') || import.meta.env.MODE === 'test') return path
      const base = (typeof window !== 'undefined' && (window as any).location && (window as any).location.origin) ? (window as any).location.origin : 'http://localhost'
      return new URL(path, base).toString()
    } catch (e) {
      return path
    }
  }

  const fetchSchemas = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch(makeApiUrl('/api/catalog/nodes?type=schema&limit=500'), { credentials: 'include' })
      if (!res.ok) throw new Error(await res.text())
      const data = await res.json()
      setSchemas(Array.isArray(data) ? data : [])
    } catch (err: any) {
      devError('[DatabaseTreePanel] fetchSchemas error', err)
      setSchemas([])
    } finally {
      setLoading(false)
    }
  }, [])

  const fetchTables = useCallback(async (schemaId: string) => {
    if (tablesBySchema[schemaId]) return
    try {
      const res = await fetch(makeApiUrl(`/api/catalog/nodes?type=table&parent_id=${encodeURIComponent(schemaId)}&limit=500`), { credentials: 'include' })
      if (!res.ok) throw new Error(await res.text())
      const data = await res.json()
      setTablesBySchema(prev => ({ ...prev, [schemaId]: Array.isArray(data) ? data : [] }))
    } catch (err) {
      devError('[DatabaseTreePanel] fetchTables error', err)
      setTablesBySchema(prev => ({ ...prev, [schemaId]: [] }))
    }
  }, [tablesBySchema])

  const fetchColumns = useCallback(async (tableId: string) => {
    if (columnsByTable[tableId]) return
    try {
      const res = await fetch(makeApiUrl(`/api/catalog/nodes?type=column&parent_id=${encodeURIComponent(tableId)}&limit=500`), { credentials: 'include' })
      if (!res.ok) throw new Error(await res.text())
      const data = await res.json()
      setColumnsByTable(prev => ({ ...prev, [tableId]: Array.isArray(data) ? data : [] }))
    } catch (err) {
      devError('[DatabaseTreePanel] fetchColumns error', err)
      setColumnsByTable(prev => ({ ...prev, [tableId]: [] }))
    }
  }, [columnsByTable])

  useEffect(() => {
    if (canUseScope) {
      fetchSchemas()
    }
  }, [canUseScope, fetchSchemas])

  // Update scope context when selections change
  useEffect(() => {
    if (selectedSchemas.length > 0 || selectedTables.length > 0 || selectedColumns.length > 0) {
      // Find schema IDs and names
      const schemaIds: string[] = []
      const schemaNames: string[] = []
      const tableIds: string[] = []
      const tableNames: string[] = []
      const columnIds: string[] = []
      const columnNames: string[] = []

      schemas.forEach(schema => {
        if (selectedSchemas.includes(schema.node_name)) {
          schemaIds.push(schema.id)
          schemaNames.push(schema.node_name)
        }
      })

      Object.entries(tablesBySchema).forEach(([, tables]) => {
        tables.forEach(table => {
          if (selectedTables.includes(table.node_name)) {
            tableIds.push(table.id)
            tableNames.push(table.node_name)
          }
        })
      })

      Object.entries(columnsByTable).forEach(([, columns]) => {
        columns.forEach(column => {
          if (selectedColumns.includes(column.node_name)) {
            columnIds.push(column.id)
            columnNames.push(column.node_name)
          }
        })
      })

      scope.setSchemaIds(schemaIds)
      scope.setSchemaNames(schemaNames)
      scope.setTableIds(tableIds)
      scope.setTableNames(tableNames)
      scope.setColumnIds(columnIds)
      scope.setColumnNames(columnNames)

      if (onSelectionChange) {
        onSelectionChange(selectedSchemas, selectedTables, selectedColumns)
      }
    }
  }, [selectedSchemas, selectedTables, selectedColumns, schemas, tablesBySchema, columnsByTable, scope, onSelectionChange])

  const toggleSchema = async (schemaName: string) => {
    const schema = schemas.find(s => s.node_name === schemaName)
    if (!schema) return

    if (!tablesBySchema[schema.id]) {
      await fetchTables(schema.id)
    }

    setExpandedSchemas(prev =>
      prev.includes(schemaName) ? prev.filter(name => name !== schemaName) : [...prev, schemaName]
    )
  }

  const toggleTable = async (tableId: string) => {
    if (!columnsByTable[tableId]) {
      await fetchColumns(tableId)
    }

    setExpandedTables(prev =>
      prev.includes(tableId) ? prev.filter(id => id !== tableId) : [...prev, tableId]
    )
  }

  const toggleSchemaSelection = (schemaName: string) => {
    // When clicking on a schema, set it as the selected schema (single selection)
    setSelectedSchemas([schemaName])
    setSelectedTables([]) // Clear table selection when selecting a schema
    setSelectedColumns([])
  }

  const toggleTableSelection = (tableName: string) => {
    // When clicking on a table, set it as the selected table (single selection)
    setSelectedTables([tableName])
    setSelectedSchemas([]) // Clear schema selection when selecting a table
    setSelectedColumns([])
  }

  const toggleColumnSelection = (columnName: string) => {
    setSelectedColumns(prev =>
      prev.includes(columnName) ? prev.filter(name => name !== columnName) : [...prev, columnName]
    )
  }

  if (!canUseScope) {
    return (
      <Box sx={{ width: '360px', flexShrink: 0 }}>
        <Alert severity="warning">Select a tenant and datasource to enable database browsing</Alert>
      </Box>
    )
  }

  return (
    <Box sx={{ width: '360px', flexShrink: 0 }}>
      <Paper sx={{ p: 2, mb: 2, display: 'flex', alignItems: 'center', gap: 1 }}>
        <AccountTreeIcon />
        <Box>
          <Typography variant="h6">{title}</Typography>
          <Typography variant="body2" color="text.secondary">{subtitle}</Typography>
        </Box>
        <Box sx={{ flex: 1 }} />
        <IconButton size="small" onClick={() => { setTablesBySchema({}); setColumnsByTable({}); fetchSchemas() }}>
          <RefreshIcon />
        </IconButton>
      </Paper>



      <Paper sx={{ maxHeight: height, overflow: 'auto', p: 1 }}>
        {loading ? (
          <Box sx={{ p: 3, textAlign: 'center' }}><CircularProgress size={28} /></Box>
        ) : schemas.length === 0 ? (
          <Box sx={{ p: 2 }}><Typography>No schemas found</Typography></Box>
        ) : (
          <List>
            {schemas.map(schema => {
              const isExpanded = expandedSchemas.includes(schema.node_name)
              const tables = tablesBySchema[schema.id] || []
              return (
                <div key={schema.id}>
                  <ListItem
                    secondaryAction={
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <Typography variant="caption" color="text.secondary">
                          {matchCounts[schema.node_name]?.schema || 0} matches
                        </Typography>
                        {isExpanded ? <ExpandLess /> : <ExpandMore />}
                      </Box>
                    }
                    button
                    onClick={() => {
                      toggleSchema(schema.node_name)
                      toggleSchemaSelection(schema.node_name)
                    }}
                    data-testid={`schema-${schema.node_name}`}
                    sx={{
                      bgcolor: selectedSchemas.includes(schema.node_name) ? 'action.selected' : 'transparent',
                      '&:hover': { bgcolor: 'action.hover' }
                    }}
                  >
                    <ListItemIcon><FolderIcon fontSize="small" /></ListItemIcon>
                    <ListItemText primary={schema.node_name} />
                  </ListItem>

                  <Collapse in={isExpanded} timeout="auto" unmountOnExit>
                    <List component="div" disablePadding>
                      {tables.map(table => {
                        const isTableExpanded = expandedTables.includes(table.id)
                        const columns = columnsByTable[table.id] || []
                        return (
                          <div key={table.id}>
                            <ListItem
                              button
                              sx={{ pl: 4, bgcolor: selectedTables.includes(table.node_name) ? 'action.selected' : 'transparent', '&:hover': { bgcolor: 'action.hover' } }}
                              secondaryAction={
                                showColumns && columns.length > 0 ? (
                                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                    <Typography variant="caption" color="text.secondary">
                                      {matchCounts[schemas.find(s => s.id === table.parent_id)?.node_name || '']?.tables[table.node_name] || 0} matches
                                    </Typography>
                                    {isTableExpanded ? <ExpandLess /> : <ExpandMore />}
                                  </Box>
                                ) : (
                                  <Typography variant="caption" color="text.secondary">
                                    {matchCounts[schemas.find(s => s.id === table.parent_id)?.node_name || '']?.tables[table.node_name] || 0} matches
                                  </Typography>
                                )
                              }
                              onClick={() => showColumns ? toggleTable(table.id) : toggleTableSelection(table.node_name)}
                              data-testid={`table-${table.node_name}`}
                            >
                              <ListItemIcon><TableChartIcon fontSize="small" /></ListItemIcon>
                              <ListItemText primary={table.node_name} />
                            </ListItem>

                            {showColumns && (
                              <Collapse in={isTableExpanded} timeout="auto" unmountOnExit>
                                <List component="div" disablePadding>
                                  {columns.map(column => (
                                    <ListItem key={column.id} sx={{ pl: 6 }} data-testid={`column-${column.node_name}`}>
                                      {showColumnSelection && (
                                        <ListItemIcon>
                                          <Checkbox
                                            edge="start"
                                            size="small"
                                            checked={selectedColumns.includes(column.node_name)}
                                            onClick={(e) => { e.stopPropagation(); toggleColumnSelection(column.node_name); }}
                                            inputProps={{ 'aria-label': `select-column-${column.node_name}` }}
                                          />
                                        </ListItemIcon>
                                      )}
                                      <ListItemIcon><ViewColumnIcon fontSize="small" /></ListItemIcon>
                                      <ListItemText primary={column.node_name} />
                                    </ListItem>
                                  ))}
                                </List>
                              </Collapse>
                            )}
                          </div>
                        )
                      })}
                    </List>
                  </Collapse>
                </div>
              )
            })}
          </List>
        )}
      </Paper>
    </Box>
  )
}

import { useState, useEffect, Suspense } from 'react';
import {
  Dialog, DialogContent, DialogActions, Button, FormControl,
  InputLabel, Select, MenuItem, Alert, Box, Typography,
  FormControlLabel, Switch, TextField
} from '@mui/material';
import ModalHeader from '@/components/ModalHeader';
import MonacoCodeEditor from './UnifiedSemanticBuilder/MonacoCodeEditor.lazy';
import { useQuery } from '@apollo/client';
import { Product, DataSource } from '../types';
import { GET_ALPHA_DATASOURCES } from '../graphql/queries/tenantQueries';


interface TenantProductDatasource {
  id: string;
  source_name: string;
  config: object;
  alpha_datasource_id: string;
}

interface DatasourceDialogProps {
  open: boolean;
  product: Product | null;
  datasource: DataSource | null;
  onClose: () => void;
  onSave: (id: string, config: object, isActive: boolean, sourceName: string, isNew: boolean) => Promise<void>;
}

export const DatasourceDialog: React.FC<DatasourceDialogProps> = ({
  open, product, datasource, onClose, onSave
}) => {
  const [sourceName, setSourceName] = useState<string>('');
  const [selectedDatasourceId, setSelectedDatasourceId] = useState<string>('');
  const [config, setConfig] = useState<string>('');
  const [isActive, setIsActive] = useState<boolean>(true);
  const [error, setError] = useState<string>('');
  const [saving, setSaving] = useState<boolean>(false);

  const { data: alphaDatasourceData, loading: datasourcesLoading } = useQuery(GET_ALPHA_DATASOURCES);
  const alphaDatasources = alphaDatasourceData?.alpha_datasource || [];


  const isEditMode = !!datasource;
  const dialogTitle = isEditMode
    ? `Edit Datasource for ${product?.alpha_product?.product_name}`
    : `Add Datasource to ${product?.alpha_product?.product_name}`;

  useEffect(() => {
    if (open) {
      setError('');
      if (isEditMode && datasource) {
        setSourceName(datasource.source_name || '');
        setSelectedDatasourceId(datasource.alpha_datasource_id || '');
        setConfig(JSON.stringify(datasource.config || {}, null, 2));
        setIsActive(datasource.is_active);
      } else {
        setSourceName('');
        setSelectedDatasourceId('');
        setConfig('');
        setIsActive(true);
      }
    }
  }, [open, datasource, isEditMode]);

  useEffect(() => {
    if (!isEditMode && selectedDatasourceId && alphaDatasources.length > 0) {
      const selectedDs = alphaDatasources.find(
        (ds: any) => ds.id === selectedDatasourceId
      );

      if (selectedDs) {
        // For new datasources from template, we might start with empty config or template config
        setConfig(JSON.stringify(selectedDs.config || {}, null, 2));
      }
    }
  }, [selectedDatasourceId, isEditMode, alphaDatasources]);


  const handleSave = async () => {
    setError('');
    if (!sourceName.trim()) {
      setError('Source Name is a required field.');
      return;
    }
    if (!isEditMode && !selectedDatasourceId) {
      setError('Please select a datasource type.');
      return;
    }
    let parsedConfig: object;
    try {
      parsedConfig = JSON.parse(config);
    } catch (err) {
      setError('The configuration is not valid JSON.');
      return;
    }
    setSaving(true);
    try {
      const idToSave = isEditMode ? datasource!.id : selectedDatasourceId;
      await onSave(idToSave, parsedConfig, isActive, sourceName, !isEditMode);
      onClose();
    } catch (err) {
      setError('Failed to save the datasource. Please try again.');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onClose={() => !saving && onClose()} fullWidth maxWidth="md">
      <ModalHeader title={dialogTitle} onClose={() => !saving && onClose()} />
      <DialogContent>
        <Box component="form" sx={{ display: 'flex', flexDirection: 'column', gap: 3, pt: 1 }}>
          {error && <Alert severity="error">{error}</Alert>}

          <TextField
            autoFocus
            required
            margin="dense"
            id="source_name"
            label="Source Name"
            type="text"
            fullWidth
            variant="outlined"
            value={sourceName}
            onChange={(e) => setSourceName(e.target.value)}
            disabled={saving}
          />

          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 2 }}>
            {!isEditMode ? (
              <FormControl fullWidth required>
                <InputLabel id="datasource-select-label">Datasource Type</InputLabel>
                <Select
                  labelId="datasource-select-label"
                  value={selectedDatasourceId}
                  label="Datasource Type"
                  onChange={(e) => setSelectedDatasourceId(e.target.value)}
                  disabled={saving || datasourcesLoading}
                >
                  {alphaDatasources.map((type: any) => (
                    <MenuItem key={type.id} value={type.id}>
                      {type.datasource_name} ({type.datasource_type})
                    </MenuItem>
                  ))}

                </Select>
              </FormControl>
            ) : (
              <Typography variant="h6">
                Type: {datasource?.alpha_datasource?.datasource_name}
              </Typography>
            )}
            <FormControlLabel
              control={<Switch checked={isActive} onChange={(e) => setIsActive(e.target.checked)} />}
              label="Active"
              sx={{ whiteSpace: 'nowrap' }}
              disabled={saving}
            />
          </Box>

          {(selectedDatasourceId || isEditMode) && (
          <Box>
            <Typography variant="subtitle1" sx={{mb: 1}}>Configuration</Typography>
            <Box border={1} borderColor="grey.400" borderRadius={1} sx={{ height: 400 }}>
              <Suspense fallback={<div>Loading editor...</div>}>
                  <div className="editor-wrapper-full editor-h-400">
                    <MonacoCodeEditor
                      value={typeof config === 'string' ? config : JSON.stringify(config, null, 2)}
                      language="json"
                      onChange={(val: string) => setConfig(val)}
                    />
                  </div>
              </Suspense>
            </Box>
        </Box>
          )}
        </Box>
      </DialogContent>
      <DialogActions>
        <Button onClick={() => !saving && onClose()}>Cancel</Button>
        <Button onClick={handleSave} variant="contained" disabled={saving || !sourceName.trim()}>
          {saving ? 'Saving...' : (isEditMode ? 'Update' : 'Add')}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

import { useEffect, useState, useCallback } from 'react'
import { devError } from '../utils/devLogger';
import { useScope } from '../contexts/ScopeContext'
import { Box, Button, CircularProgress, Paper, Typography, Table, TableHead, TableRow, TableCell, TableBody, Alert, IconButton, List, ListItem, ListItemIcon, ListItemText, Collapse, Checkbox, Chip, Tooltip } from '@mui/material'
import ProfessionalSearchInput from './common/ProfessionalSearchInput'
import FolderIcon from '@mui/icons-material/Folder'
import TableChartIcon from '@mui/icons-material/TableChart'
import AccountTreeIcon from '@mui/icons-material/AccountTree'
import RefreshIcon from '@mui/icons-material/Refresh'
import CheckCircleOutlineIcon from '@mui/icons-material/CheckCircleOutline'
import ExpandLess from '@mui/icons-material/ExpandLess'
import ExpandMore from '@mui/icons-material/ExpandMore'
import { useTenant } from '../contexts/TenantContext'

type DbScannerProps = {
  refreshMappings?: () => Promise<void>
  onProfile?: (schemaId: string | null, tableName: string | null, tableNames?: string[]) => void
  registerRunScan?: (fn: () => void) => void
  searchTerm?: string
}
import { hasTenantScope } from '../utils/tenantScope'

type CatalogNode = {
  id: string
  node_name: string
  qualified_path?: string
  catalog_type?: string
  parent_id?: string
  properties?: any
}

export default function DbScanner({ refreshMappings: _refreshMappings, onProfile, registerRunScan, searchTerm }: DbScannerProps) {
  const { tenant, datasource } = useTenant()
  const makeApiUrl = (path: string) => {
    // During test runs we prefer returning the relative path so the test's fetch
    // mock can intercept it without attempting real network connections.
    try {
      if ((typeof process !== 'undefined' && process.env && process.env.NODE_ENV === 'test') || import.meta.env.MODE === 'test') return path
      const base = (typeof window !== 'undefined' && (window as any).location && (window as any).location.origin) ? (window as any).location.origin : 'http://localhost'
      return new URL(path, base).toString()
    } catch (e) {
      return path
    }
  }
  const [schemas, setSchemas] = useState<CatalogNode[]>([])
  const [expanded, setExpanded] = useState<string[]>([])
  const [tablesBySchema, setTablesBySchema] = useState<Record<string, CatalogNode[]>>({})
  const [columnsByTable, setColumnsByTable] = useState<Record<string, CatalogNode[]>>({})
  const [profiledColumns, setProfiledColumns] = useState<Record<string, boolean>>({})
  // pagination state per table
  const [columnsPageByTable, setColumnsPageByTable] = useState<Record<string, { offset: number; limit: number; hasMore: boolean }>>({})
  const [columnsLoadingByTable, setColumnsLoadingByTable] = useState<Record<string, boolean>>({})
  const [selectedForScan, setSelectedForScan] = useState<Record<string, boolean>>({})
  const [selectedTable, setSelectedTable] = useState<CatalogNode | null>(null)
  const [selectedTablesForProfile, setSelectedTablesForProfile] = useState<string[]>([])
  const [columnFilter, setColumnFilter] = useState<string>('')
  const [loading, setLoading] = useState(false)
  const [scanRunning, setScanRunning] = useState(false)
  const [scanMessage, setScanMessage] = useState<string | null>(null)

  const canUseScope = hasTenantScope() && !!datasource && !!tenant

  const fetchSchemas = useCallback(async () => {
    setLoading(true)
    try {
  const res = await fetch(makeApiUrl('/api/catalog/nodes?type=schema&limit=500'), { credentials: 'include' })
      if (!res.ok) throw new Error(await res.text())
      const data = await res.json()
      setSchemas(Array.isArray(data) ? data : [])
    } catch (err: any) {
      devError('[DbScanner] fetchSchemas error', err)
      setSchemas([])
    } finally {
      setLoading(false)
    }
  }, [])

  const fetchTables = useCallback(async (schemaId: string) => {
    if (tablesBySchema[schemaId]) return
    try {
  const res = await fetch(makeApiUrl(`/api/catalog/nodes?type=table&parent_id=${encodeURIComponent(schemaId)}&limit=500`), { credentials: 'include' })
      if (!res.ok) throw new Error(await res.text())
      const data = await res.json()
      setTablesBySchema(prev => ({ ...prev, [schemaId]: Array.isArray(data) ? data : [] }))
    } catch (err) {
      devError('[DbScanner] fetchTables error', err)
      setTablesBySchema(prev => ({ ...prev, [schemaId]: [] }))
    }
  }, [tablesBySchema])

  // Fetch columns lazily with pagination. Keeps previous columns for the table and appends new ones.
  const fetchColumns = useCallback(async (tableId: string, opts?: { offset?: number; limit?: number; reset?: boolean; q?: string }) => {
    const limit = opts?.limit ?? 200
    const q = opts?.q ?? columnFilter
    const offset = opts?.offset ?? (opts?.reset ? 0 : (columnsPageByTable[tableId]?.offset ?? 0))
    // if no more items and not resetting, skip
    if (!opts?.reset && columnsPageByTable[tableId] && !columnsPageByTable[tableId].hasMore) return

    try {
      setColumnsLoadingByTable(prev => ({ ...prev, [tableId]: true }))
      const qParam = q ? `&q=${encodeURIComponent(String(q))}` : ''
  const res = await fetch(makeApiUrl(`/api/catalog/nodes?type=column&parent_id=${encodeURIComponent(tableId)}&limit=${limit}&offset=${offset}${qParam}`), { credentials: 'include' })
      if (!res.ok) throw new Error(await res.text())
      const data = await res.json()
      const items: CatalogNode[] = Array.isArray(data) ? data : []

      setColumnsByTable(prev => ({
        ...prev,
        [tableId]: opts?.reset ? items : [...(prev[tableId] || []), ...items]
      }))

      setColumnsPageByTable(prev => ({
        ...prev,
        [tableId]: {
          offset: offset + items.length,
          limit,
          hasMore: items.length === limit
        }
      }))
    } catch (err) {
      devError('[DbScanner] fetchColumns error', err)
      setColumnsByTable(prev => ({ ...prev, [tableId]: prev[tableId] || [] }))
      setColumnsPageByTable(prev => ({ ...prev, [tableId]: { offset: prev[tableId]?.offset ?? 0, limit: prev[tableId]?.limit ?? 200, hasMore: false } }))
    } finally {
      setColumnsLoadingByTable(prev => ({ ...prev, [tableId]: false }))
    }
  }, [columnsPageByTable, columnFilter])

  // when the columnFilter changes, reload first page for the currently selected table
  // Note: we intentionally do NOT include `selectedTable` in the dependency array to avoid
  // triggering a duplicate fetch when a table is selected (handleTableSelect already
  // performs the initial load). This effect should only run when the filter itself
  // changes while a table is selected.
  useEffect(() => {
    if (selectedTable) {
      const query = searchTerm || columnFilter
      // reset stored columns and pages for this table and fetch first page with q
      setColumnsByTable(prev => ({ ...prev, [selectedTable.id]: [] }))
      setColumnsPageByTable(prev => ({ ...prev, [selectedTable.id]: { offset: 0, limit: prev[selectedTable.id]?.limit ?? 200, hasMore: true } }))
      fetchColumns(selectedTable.id, { offset: 0, limit: columnsPageByTable[selectedTable.id]?.limit ?? 200, reset: true, q: query })
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [columnFilter, searchTerm])

  useEffect(() => {
    if (canUseScope) fetchSchemas()
  }, [canUseScope, fetchSchemas])

  const scope = useScope()

  const applySelectionToMapper = () => {
    if (!selectedTable) return
    // find parent schema id by searching tablesBySchema
    let parentSchemaId: string | undefined
    let parentSchemaName: string | undefined
    for (const s of schemas) {
      const tables = tablesBySchema[s.id] || []
      if (tables.find(t => t.id === selectedTable.id)) {
        parentSchemaId = s.id
        parentSchemaName = s.node_name
        break
      }
    }

    try {
      if (parentSchemaId) {
        scope.setSchemaIds([parentSchemaId])
        scope.setSchemaNames([parentSchemaName || ''])
      }
      scope.setTableIds([selectedTable.id])
      scope.setTableNames([selectedTable.node_name])
      // Optionally refresh mappings if caller passed refreshMappings
      if (typeof _refreshMappings === 'function') _refreshMappings()
    } catch (e) {
      devError('[DbScanner] applySelectionToMapper error', e)
    }
  }
  const handleTableSelect = async (table: CatalogNode) => {
    setSelectedTable(table)
    // reset pagination and load first page
    await fetchColumns(table.id, { offset: 0, limit: 200, reset: true })
    // find parent schema name for this table (used for profiling lookup)
    let parentSchemaName: string | undefined
    for (const s of schemas) {
      const tables = tablesBySchema[s.id] || []
      if (tables.find(t => t.id === table.id)) {
        parentSchemaName = s.node_name
        break
      }
    }
    if (parentSchemaName) {
      // fetch profiler results for this table to determine which columns are profiled
      fetchProfileForTable(parentSchemaName, table.node_name)
    }
    // Do not auto-apply: selection just shows details. User can click "Apply to Semantic Mapper" to apply.
    // Still, update selectedTable which is used in the details pane.
  }

  const fetchProfileForTable = async (schemaName: string, tableName: string) => {
    try {
  const res = await fetch(makeApiUrl(`/api/profiler/results?schema=${encodeURIComponent(schemaName)}&table=${encodeURIComponent(tableName)}&limit=500`), { credentials: 'include' })
      if (!res.ok) return
      const data = await res.json().catch(() => null)
      if (!data || !Array.isArray(data.profiles)) return
      const map: Record<string, boolean> = {}
      data.profiles.forEach((p: any) => { if (p.ColumnName) map[p.ColumnName] = true })
      setProfiledColumns(map)
    } catch (err) {
      // ignore
    }
  }

  // profile the currently selected table (call back to parent)
  const handleRunProfile = () => {
    if (!selectedTable) return
    // find parent schema id
    let parentSchemaName: string | null = null
    for (const s of schemas) {
      const tables = tablesBySchema[s.id] || []
      if (tables.find(t => t.id === selectedTable.id)) {
        parentSchemaName = s.node_name
        break
      }
    }
    try {
      if (typeof onProfile === 'function') onProfile(parentSchemaName, selectedTable.node_name)
    } catch (e) {
      // swallow
    }
  }

  // keyboard shortcut: press 'p' to profile selected table
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'p' || e.key === 'P') {
        if (selectedTable) {
          e.preventDefault()
          handleRunProfile()
        }
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [selectedTable, schemas, tablesBySchema])

  // (applySelectionToMapper removed) Selection now only shows details; applying selection
  // to the Semantic Mapper is handled elsewhere when needed.

  const runScan = async () => {
    if (!datasource) return
    const selectedSchemaNames = schemas.filter(s => selectedForScan[s.id]).map(s => s.node_name)
    setScanRunning(true)
    setScanMessage(null)
    try {
      const body: any = { datasource_id: datasource.id }
      if (selectedSchemaNames.length > 0) body.schema_names = selectedSchemaNames
  const res = await fetch(makeApiUrl('/api/catalog/scan'), { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body), credentials: 'include' })
      const data = await res.json().catch(() => null)
      if (!res.ok) {
        setScanMessage(`Scan failed: ${res.status} ${res.statusText} ${data?.error || ''}`)
      } else {
        if (data && data.results) {
          const succeeded = (data.results.filter ? data.results.filter((r: any) => r.success).length : 0)
          setScanMessage(`${data.message || 'Scan completed'} (${succeeded} succeeded, ${data.results.length - succeeded} failed)`)
        } else if (data && data.message) {
          setScanMessage(data.message)
        } else {
          setScanMessage('Scan completed')
        }
        // refresh schemas/tables
        await fetchSchemas()
        setTablesBySchema({})
        setColumnsByTable({})
      }
    } catch (err: any) {
      devError('[DbScanner] runScan error', err)
      setScanMessage(String(err.message || err))
    } finally {
      setScanRunning(false)
    }
  }

  // expose runScan to parent if requested
  useEffect(() => {
    try {
      if (typeof registerRunScan === 'function') {
        registerRunScan(runScan)
      }
    } catch (e) {}
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return (
    <Box sx={{ display: 'flex', gap: 3 }}>
      {!canUseScope && (
        <Alert severity="warning">Select a tenant and datasource to enable DB scanning</Alert>
      )}

      <Box sx={{ width: '360px', flexShrink: 0 }}>
        <Paper sx={{ p: 2, mb: 2, display: 'flex', alignItems: 'center', gap: 1 }}>
          <AccountTreeIcon />
          <Box>
            <Typography variant="h6">Database</Typography>
            <Typography variant="body2" color="text.secondary">Schemas and tables</Typography>
          </Box>
          <Box sx={{ flex: 1 }} />
          <IconButton size="small" onClick={() => { setTablesBySchema({}); setColumnsByTable({}); fetchSchemas() }}><RefreshIcon /></IconButton>
        </Paper>

        <Paper sx={{ maxHeight: '72vh', overflow: 'auto', p: 1 }}>
          {loading ? (
            <Box sx={{ p: 3, textAlign: 'center' }}><CircularProgress size={28} /></Box>
          ) : schemas.length === 0 ? (
            <Box sx={{ p: 2 }}><Typography>No schemas found</Typography></Box>
          ) : (
            <List>
              {schemas.map(schema => {
                const isExpanded = expanded.includes(schema.id)
                return (
                  <div key={schema.id}>
                    <ListItem
                      secondaryAction={isExpanded ? <ExpandLess /> : <ExpandMore />}
                      button
                      onClick={async () => {
                        // ensure tables are loaded, then toggle expand
                        if (!tablesBySchema[schema.id]) await fetchTables(schema.id)
                        setExpanded(prev => prev.includes(schema.id) ? prev.filter(id => id !== schema.id) : [...prev, schema.id])
                      }}
                      onKeyDown={async (e) => {
                        if (e.key === 'Enter' || e.key === ' ') {
                          e.preventDefault()
                          if (!tablesBySchema[schema.id]) await fetchTables(schema.id)
                          setExpanded(prev => prev.includes(schema.id) ? prev.filter(id => id !== schema.id) : [...prev, schema.id])
                        }
                      }}
                      data-testid={`schema-${schema.node_name}`}
                    >
                      <ListItemIcon>
                        <Checkbox
                          edge="start"
                          size="small"
                          checked={!!selectedForScan[schema.id]}
                          onClick={(e) => { e.stopPropagation(); setSelectedForScan(prev => ({ ...prev, [schema.id]: !prev[schema.id] })); }}
                        />
                      </ListItemIcon>
                      <ListItemIcon><FolderIcon fontSize="small" /></ListItemIcon>
                      <ListItemText primary={schema.node_name} />
                    </ListItem>

                    <Collapse in={isExpanded} timeout="auto" unmountOnExit>
                      <List component="div" disablePadding>
                          {(tablesBySchema[schema.id] || []).map(table => (
                          <ListItem key={table.id} button sx={{ pl: 4 }} onClick={() => handleTableSelect(table)} onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); handleTableSelect(table) } }} data-testid={`table-${table.node_name}`}>
                            <ListItemIcon>
                              <Checkbox
                                edge="start"
                                size="small"
                                checked={selectedTablesForProfile.includes(table.node_name)}
                                onClick={(e) => { e.stopPropagation(); setSelectedTablesForProfile(prev => prev.includes(table.node_name) ? prev.filter(x => x !== table.node_name) : [...prev, table.node_name]) }}
                                inputProps={{ 'aria-label': `profile-select-${table.node_name}` }}
                              />
                            </ListItemIcon>
                            <ListItemIcon><TableChartIcon fontSize="small" /></ListItemIcon>
                            <ListItemText primary={table.node_name} />
                          </ListItem>
                        ))}
                      </List>
                    </Collapse>
                  </div>
                )
              })}
            </List>
          )}
        </Paper>



        {scanMessage && <Typography variant="body2" sx={{ mt: 1 }}>{scanMessage}</Typography>}
      </Box>

      <Box sx={{ flex: 1 }}>
        <Paper sx={{ p: 2, mb: 2, display: 'flex', alignItems: 'center' }}>
          <TableChartIcon sx={{ mr: 1 }} />
          <Box>
            <Typography variant="h6">Table Details</Typography>
            <Typography variant="body2" color="text.secondary">Select a table to view its columns and properties.</Typography>
          </Box>
          <Box sx={{ flex: 1 }} />
          <Box sx={{ display: 'flex', gap: 1 }}>
            <Button variant="contained" size="small" onClick={applySelectionToMapper} disabled={!selectedTable} data-testid="apply-to-mapper">Apply to Semantic Mapper</Button>
            <Button variant="outlined" size="small" onClick={handleRunProfile} disabled={!selectedTable} data-testid="run-profile">Run Data Profile</Button>
            <Button variant="outlined" size="small" onClick={() => { setSelectedForScan({}); setTablesBySchema({}); setColumnsByTable({}); fetchSchemas() }}>Reload</Button>
          </Box>
        </Paper>

        <Paper sx={{ p: 2, minHeight: '50vh' }}>
          {!selectedTable ? (
            <Typography variant="body2" color="text.secondary">No table selected</Typography>
          ) : (
            <>
              <Box sx={{ display: 'flex', alignItems: 'baseline', justifyContent: 'space-between' }}>
                <Box>
                  <Typography variant="subtitle1" sx={{ mb: 0 }}>{selectedTable.node_name}</Typography>
                  <Typography variant="caption" color="text.secondary">{selectedTable.qualified_path}</Typography>
                </Box>
              </Box>

              <Box sx={{ mt: 2 }}>
                {/* Search is now in global header */}
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Column</TableCell>
                      <TableCell>Type</TableCell>
                      <TableCell>Nullable</TableCell>
                      <TableCell>Extras</TableCell>
                    </TableRow>
                  </TableHead>
                      <TableBody>
                        {(
                          (columnsByTable[selectedTable.id] || [])
                            .filter(c => {
                              if (!columnFilter) return true
                              const q = columnFilter.toLowerCase()
                              return String(c.node_name || '').toLowerCase().includes(q) || String(parseColumnType(c.properties) || '').toLowerCase().includes(q) || JSON.stringify(c.properties || '').toLowerCase().includes(q)
                            })
                            .map(col => (
                          <TableRow key={col.id} data-testid={`column-${col.node_name}`}>
                            <TableCell sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                              {col.node_name}
                              {profiledColumns[col.node_name] ? (
                                <Tooltip title={`Profile exists for ${col.node_name}`} arrow>
                                  <CheckCircleOutlineIcon color="success" sx={{ fontSize: 18, ml: 1 }} data-testid={`profile-indicator-${col.node_name}`} aria-label={`profile-exists-${col.node_name}`} />
                                </Tooltip>
                              ) : null}
                            </TableCell>
                            <TableCell>
                              <Chip label={String(parseColumnType(col.properties) || '-')} size="small" data-testid={`type-${col.node_name}`} />
                            </TableCell>
                            <TableCell data-testid={`nullable-${col.node_name}`}>{formatNullable(col.properties)}</TableCell>
                            <TableCell>
                              {col.properties ? (
                                <Box component="pre" sx={{ margin: 0, whiteSpace: 'pre-wrap', fontSize: '0.85rem' }} data-testid={`props-${col.node_name}`}>{JSON.stringify(col.properties, null, 2)}</Box>
                              ) : '-'}
                            </TableCell>
                          </TableRow>
                        ))
                        )}
                      </TableBody>
                </Table>
                {/* Load more control for lazy pagination */}
                <Box sx={{ mt: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', gap: 1 }}>
                  {selectedTable && columnsPageByTable[selectedTable.id]?.hasMore && (
                    <Button size="small" onClick={() => fetchColumns(selectedTable.id, { offset: columnsPageByTable[selectedTable.id]?.offset ?? 0, limit: columnsPageByTable[selectedTable.id]?.limit ?? 200 })} disabled={!!columnsLoadingByTable[selectedTable.id]} data-testid="load-more">
                      {columnsLoadingByTable[selectedTable.id] ? 'Loading...' : 'Load more'}
                    </Button>
                  )}
                </Box>
              </Box>
            </>
          )}
        </Paper>
      </Box>
    </Box>
  )
}

// Helpers to normalize/format column type and nullable info
function parseColumnType(properties: any) {
  if (!properties) return '-'
  // common property keys observed in catalog nodes
  if (properties.data_type) return String(properties.data_type)
  if (properties.type) return String(properties.type)
  if (properties.column_type) return String(properties.column_type)
  if (properties.udt_name) return String(properties.udt_name)
  // fallback: try to infer from properties object
  if (properties.format) return String(properties.format)
  if (typeof properties === 'string') return properties
  return '-'
}

function formatNullable(properties: any) {
  if (!properties) return '-'
  if (properties.is_nullable !== undefined) return String(properties.is_nullable)
  if (properties.nullable !== undefined) return String(properties.nullable)
  return '-'
}

import React, { useState } from 'react';
import { Alert, AlertTitle, Link, Button, Dialog, DialogTitle, DialogContent, DialogActions } from '@mui/material';

const DevProxyWarning: React.FC = () => {
  const [dismissed, setDismissed] = useState(false);

  try {
    const env: any = (import.meta as any).env || {};
    const useProxy = String(env?.VITE_USE_PROXY || 'false').toLowerCase() === 'true';
    const backendTarget = String(env?.VITE_BACKEND_TARGET || env?.VITE_API_BASE_URL || '').toLowerCase();
    const runningOnHost = typeof window !== 'undefined' && window.location && (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1');

    const isProblem = useProxy && runningOnHost && backendTarget.includes('host.docker.internal');

    if (isProblem && !dismissed) {
      // Blocking modal — user must either 'Fix and reload' or 'Proceed anyway'
      return (
        <Dialog open={true} aria-labelledby="dev-proxy-warning-title">
          <DialogTitle id="dev-proxy-warning-title">Dev Proxy Misconfigured</DialogTitle>
          <DialogContent>
            <Alert severity="error" style={{ marginBottom: '8px' }}>
              <AlertTitle>Proxy points at <code>{backendTarget}</code></AlertTitle>
              You are running the frontend on <code>localhost</code> while the Vite proxy target points at <code>host.docker.internal</code>.
              This commonly prevents the proxy from reaching the backend. Set <code>VITE_BACKEND_TARGET</code> and <code>VITE_API_BASE_URL</code> to <code>http://localhost:8082</code> in <code>frontend/.env.local</code> and restart the dev server.
            </Alert>
            <div>Please choose an action below to continue.</div>
          </DialogContent>
          <DialogActions>
            <Button onClick={() => window.location.reload()} color="primary">I've fixed it — reload</Button>
            <Button onClick={() => setDismissed(true)} color="inherit">Proceed anyway</Button>
          </DialogActions>
        </Dialog>
      );
    }
  } catch (e) {
    // ignore runtime errors in the check
  }
  // If dismissed, render a subtle non-blocking warning variant
  if (dismissed) {
    const envAny: any = (import.meta as any).env || {};
    const backendTarget = String(envAny?.VITE_BACKEND_TARGET || envAny?.VITE_API_BASE_URL || '');
    return (
      <Alert severity="warning" style={{ margin: '8px' }}>
        Dev Proxy may be misconfigured (target: <code>{backendTarget}</code>). Actions may fail.
      </Alert>
    );
  }

  return null;
};

export default DevProxyWarning;

// src/components/DimensionBuilder/ViewDimensionDetails.tsx
import { Info, Code, ChevronDown, ChevronRight } from 'lucide-react';
import { Dimension } from './types';
import { CaseEditor } from './CaseEditor';
import GranularitySection from './GranularitySection';

interface ViewDimensionDetailsProps {
  dimension: Dimension;
  onUpdate: (id: string, updates: Partial<Dimension>) => void;
  expandedSections: {[key: string]: boolean};
  onToggleSection: (sectionId: string) => void;
}

export function ViewDimensionDetails({
  dimension,
  onUpdate,
  expandedSections,
  onToggleSection
}: ViewDimensionDetailsProps) {
  const getSectionKey = (suffix: string) => `${dimension.id}_${suffix}`;

  const updateCase = (caseObj: Dimension['case']) => {
    onUpdate(dimension.id, { case: caseObj });
  };

  return (
    <div className="space-y-6">
      {/* Basic Info */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="bg-gray-50 p-3 rounded-lg">
          <label className="block text-xs font-medium text-gray-500 mb-1">SQL Expression</label>
          <code className="text-sm font-mono text-gray-900 break-all">{dimension.sql}</code>
        </div>

        {dimension.description && (
          <div className="bg-gray-50 p-3 rounded-lg">
            <label className="block text-xs font-medium text-gray-500 mb-1">Description</label>
            <p className="text-sm text-gray-700">{dimension.description}</p>
          </div>
        )}
      </div>

      {/* Case Section */}
      <div className="border border-gray-200 rounded-lg">
        <button
          onClick={() => onToggleSection(getSectionKey('case'))}
          className="w-full flex items-center justify-between p-4 hover:bg-gray-50 transition-colors"
        >
          <div className="flex items-center gap-2">
            <Info className="w-5 h-5 text-blue-500" />
            <span className="font-medium">Case Statement</span>
            {dimension.case && (
              <span className="text-sm text-gray-500">
                ({dimension.case.when.length} conditions)
              </span>
            )}
          </div>
          {expandedSections[getSectionKey('case')] ? (
            <ChevronDown className="w-5 h-5 text-gray-400" />
          ) : (
            <ChevronRight className="w-5 h-5 text-gray-400" />
          )}
        </button>

        {expandedSections[getSectionKey('case')] && (
          <div className="border-t border-gray-200 p-4">
            <CaseEditor
              caseObj={dimension.case}
              onUpdate={updateCase}
            />
          </div>
        )}
      </div>

      {/* Granularities Section (only for time dimensions) */}
      {dimension.type === 'time' && (
        <GranularitySection
          dimension={dimension}
          onUpdate={onUpdate}
          expandedSections={expandedSections}
          onToggleSection={onToggleSection}
        />
      )}

      {/* Meta Information */}
      {dimension.meta && Object.keys(dimension.meta).length > 0 && (
        <div className="border border-gray-200 rounded-lg">
          <button
            onClick={() => onToggleSection(getSectionKey('meta'))}
            className="w-full flex items-center justify-between p-4 hover:bg-gray-50 transition-colors"
          >
            <div className="flex items-center gap-2">
              <Code className="w-5 h-5 text-purple-500" />
              <span className="font-medium">Meta Information</span>
            </div>
            {expandedSections[getSectionKey('meta')] ? (
              <ChevronDown className="w-5 h-5 text-gray-400" />
            ) : (
              <ChevronRight className="w-5 h-5 text-gray-400" />
            )}
          </button>

          {expandedSections[getSectionKey('meta')] && (
            <div className="border-t border-gray-200 p-4">
              <div className="space-y-2">
                {Object.entries(dimension.meta as Record<string, any>).map(([key, value]) => {
                  // UUID regex pattern
                  const uuidRegex = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;

                  let displayValue: any = value;

                  // Special handling for 'type' field
                  if (key === 'type' && typeof value === 'string') {
                    // If it's a UUID, try to map to dimension type or show readable format
                    if (uuidRegex.test(value)) {
                      // Map common type UUIDs to readable names if we have them
                      // Otherwise show the primary dimension type as fallback
                      const typeMapping: Record<string, string> = {
                        'string': 'string',
                        'number': 'number', 
                        'time': 'time',
                        'boolean': 'boolean',
                        'geo': 'geo'
                      };
                      // Use the dimension's own type as reference, otherwise show UUID with indicator
                      displayValue = `${dimension.type || 'unknown'} (from ${value.substring(0, 8)}...)`;
                    }
                  } else if (typeof value === 'string' && uuidRegex.test(value)) {
                    // Other UUID fields - show abbreviated UUID
                    displayValue = `${value.substring(0, 8)}... (UUID)`;
                  } else if (typeof value === 'boolean') {
                    displayValue = value ? 'Yes' : 'No';
                  } else if (typeof value === 'object') {
                    displayValue = JSON.stringify(value, null, 2);
                  }

                  return (
                    <div key={key} className="flex justify-between items-start py-2 border-b border-gray-100 last:border-b-0">
                      <span className="text-sm font-mono text-gray-600 capitalize">{key}:</span>
                      <span className="text-sm text-gray-900 font-mono text-right max-w-xs break-words">{displayValue}</span>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import React from 'react';
import {
  TextField,
  FormControlLabel,
  Checkbox,
  Box,
  Typography,
  Alert,
} from '@mui/material';

export interface PropertyMetadata {
  name: string;
  label: string;
  order: number;
  nullable?: boolean;
  data_type: string;
  input_type: string;
  description?: string;
  placeholder?: string;
  options?: { label: string; value: any }[];
}

export interface DynamicPropertyFormProps {
  properties: PropertyMetadata[];
  values: Record<string, any>;
  onChange: (field: string, value: any) => void;
  errors?: Record<string, string>;
  disabled?: boolean;
}

const DynamicPropertyForm: React.FC<DynamicPropertyFormProps> = ({
  properties,
  values,
  onChange,
  errors = {},
  disabled = false,
}) => {
  // Sort properties by order
  const sortedProperties = [...properties].sort((a, b) => (a.order ?? 999) - (b.order ?? 999));

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
      {sortedProperties.length === 0 && (
         <Typography variant="body2" color="text.secondary">No properties defined.</Typography>
      )}

      {sortedProperties.map((prop) => {
        const error = errors[prop.name];

        // START: Special handling for SQL, Description, etc based on name or input_type

        // Checkbox for booleans
        if (prop.input_type === 'checkbox' || prop.data_type === 'boolean') {
          return (
            <FormControlLabel
              key={prop.name}
              control={
                <Checkbox
                  checked={!!values[prop.name]}
                  onChange={(e) => onChange(prop.name, e.target.checked)}
                  disabled={disabled}
                />
              }
              label={
                <Box>
                    <Typography>{prop.label || prop.name}</Typography>
                    {prop.description && (
                         <Typography variant="caption" color="text.secondary">{prop.description}</Typography>
                    )}
                </Box>
              }
            />
          );
        }

        // Text Area for SQL or lengthy text
        const isMultiline = 
            prop.input_type === 'textarea' || 
            prop.name === 'sql' || 
            prop.name === 'description' ||
            prop.name === 'meta' ||
            prop.name === 'filters'; // heuristic

        if (prop.input_type === 'select' && prop.options) {
          return (
            <TextField
              key={prop.name}
              select
              label={prop.label || prop.name}
              value={values[prop.name] ?? ''}
              onChange={(e) => onChange(prop.name, e.target.value)}
              disabled={disabled}
              fullWidth
              required={!prop.nullable}
              error={!!error}
              helperText={error || prop.description}
              SelectProps={{ native: true }}
            >
              <option value="" disabled>Select {prop.label}</option>
              {prop.options.map((opt) => (
                <option key={opt.value} value={opt.value}>
                  {opt.label}
                </option>
              ))}
            </TextField>
          );
        }

        return (
          <TextField
            key={prop.name}
            label={prop.label || prop.name}
            value={values[prop.name] ?? ''}
            onChange={(e) => onChange(prop.name, e.target.value)}
            disabled={disabled}
            fullWidth
            required={!prop.nullable}
            error={!!error}
            helperText={error || prop.description}
            placeholder={prop.placeholder}
            type={prop.data_type === 'number' || prop.input_type === 'number' ? 'number' : 'text'}
            multiline={isMultiline}
            rows={isMultiline ? (prop.name === 'sql' ? 4 : 2) : 1}
            InputProps={prop.name === 'sql' ? {
                sx: { fontFamily: 'monospace' }
            } : undefined}
          />
        );
      })}
    </Box>
  );
};

export default DynamicPropertyForm;

import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Box,
  Typography,
  Alert,
  FormControlLabel,
  Checkbox,
} from '@mui/material';

interface EditColumnDialogProps {
  open: boolean;
  onClose: () => void;
  column: {
    id: string;
    name: string;
    description?: string;
    type?: string;
    properties?: any;
    tenant_id?: string;
    tenant_datasource_id?: string;
  };
  onSave?: () => void;
}

const EditColumnDialog: React.FC<EditColumnDialogProps> = ({
  open,
  onClose,
  column,
  onSave
}) => {
  const [formData, setFormData] = useState({
    name: '',
    description: '',
    type: '',
    nullable: true,
    isPrimaryKey: false,
    isForeignKey: false,
    defaultValue: '',
  });
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (open && column) {
      setFormData({
        name: column.name || '',
        description: column.description || '',
        type: column.type || '',
        nullable: column.properties?.nullable ?? true,
        isPrimaryKey: column.properties?.is_primary_key || false,
        isForeignKey: column.properties?.is_foreign_key || false,
        defaultValue: column.properties?.default_value || '',
      });
      setError(null);
    }
  }, [open, column]);

  const handleChange = (field: string, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleSave = async () => {
    setError(null);
    setSaving(true);

    try {
      // Build properties object
      const properties = {
        ...column.properties,
        nullable: formData.nullable,
        is_primary_key: formData.isPrimaryKey,
        is_foreign_key: formData.isForeignKey,
        default_value: formData.defaultValue || undefined,
      };

      // Update column via API
      const response = await fetch(`/api/catalog/nodes/${column.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'X-Tenant-ID': column.tenant_id || 'default',
          'X-Tenant-Datasource-ID': column.tenant_datasource_id || '',
        },
        body: JSON.stringify({
          node_name: formData.name,
          description: formData.description,
          properties,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to update column');
      }

      if (onSave) onSave();
      onClose();
    } catch (err: any) {
      setError(err.message || 'Failed to save changes');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="md" fullWidth>
      <DialogTitle>Edit Column</DialogTitle>
      <DialogContent>
        {error && (
          <Alert severity="error" sx={{ mb: 2 }}>
            {error}
          </Alert>
        )}

        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
          {/* Basic Info */}
          <Typography variant="subtitle2" color="text.secondary" sx={{ mt: 1 }}>
            Basic Information
          </Typography>

          <TextField
            label="Column Name"
            value={formData.name}
            onChange={(e) => handleChange('name', e.target.value)}
            fullWidth
            required
            helperText="Name of the database column"
          />

          <TextField
            label="Description"
            value={formData.description}
            onChange={(e) => handleChange('description', e.target.value)}
            fullWidth
            multiline
            rows={2}
            helperText="Documentation for this column"
          />

          {/* Column Properties */}
          <Typography variant="subtitle2" color="text.secondary" sx={{ mt: 2 }}>
            Column Properties
          </Typography>

          <TextField
            label="Data Type"
            value={formData.type}
            onChange={(e) => handleChange('type', e.target.value)}
            fullWidth
            helperText="Database data type (e.g., VARCHAR, INTEGER, TIMESTAMP)"
            placeholder="e.g., VARCHAR(255)"
          />

          <TextField
            label="Default Value"
            value={formData.defaultValue}
            onChange={(e) => handleChange('defaultValue', e.target.value)}
            fullWidth
            helperText="Default value for this column"
          />

          <FormControlLabel
            control={
              <Checkbox
                checked={formData.nullable}
                onChange={(e) => handleChange('nullable', e.target.checked)}
              />
            }
            label="Nullable (allows NULL values)"
          />

          <FormControlLabel
            control={
              <Checkbox
                checked={formData.isPrimaryKey}
                onChange={(e) => handleChange('isPrimaryKey', e.target.checked)}
              />
            }
            label="Primary Key"
          />

          <FormControlLabel
            control={
              <Checkbox
                checked={formData.isForeignKey}
                onChange={(e) => handleChange('isForeignKey', e.target.checked)}
              />
            }
            label="Foreign Key"
          />
        </Box>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} disabled={saving}>
          Cancel
        </Button>
        <Button onClick={handleSave} variant="contained" disabled={saving}>
          {saving ? 'Saving...' : 'Save Changes'}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default EditColumnDialog;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import {
  Box,
  Button,
  Chip,
  Dialog,
  DialogTitle,
  DialogActions,
  DialogContent,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  TextField,
  IconButton,
  Tooltip,
  Paper,
  Typography,
} from '@mui/material';
import { 
    SimpleTreeView as TreeView, 
    TreeItem 
} from '@mui/x-tree-view';
import {
  ExpandMore as ExpandMoreIcon,
  ChevronRight as ChevronRightIcon,
  Add as AddIcon,
  Delete as DeleteIcon,
  Edit as EditIcon,
  Save as SaveIcon,
  Search as SearchIcon,
  ArrowUpward as ArrowUpIcon,
  ArrowDownward as ArrowDownIcon,
  CheckCircle as CheckCircleIcon,
  MoreVert as MoreVertIcon,
} from '@mui/icons-material';

import { useSnackbar } from 'notistack';
import { useConfirm } from './ConfirmProvider';
import { useNotification } from '../hooks/useNotification';
import { useEnhancedSemanticTerms, semanticTermToField } from '../hooks/useEnhancedSemanticTerms';
import { saveEntitySchema } from '../api/entitySchema';
import { createEvent } from '../api/events';
import { useTenant } from '../contexts/TenantContext';
import { devError } from '../utils/devLogger';
import type { Entities, Entity, Field } from '../types/entity-schema';

// Styles
// Styles removed (MUI Standard) 

interface EntityDetailsEditorProps {
  entityKey: string;
  entity: Entity;
  entities: Entities;
  datasourceId?: string;
  onEntityUpdate: (updatedEntity: Entity) => void;
  validationRules?: any[];
}

interface SelectedNode {
  type: 'entity' | 'subtype';
  subtypeKey?: string;
}

interface HierarchyNode {
  title: React.ReactNode;
  key: string;
  children?: HierarchyNode[];
}

export default function EntityDetailsEditor({
  entityKey,
  entity,
  entities,
  datasourceId,
  onEntityUpdate,
  validationRules,
}: EntityDetailsEditorProps) {
  const [selectedNode, setSelectedNode] = useState<SelectedNode>({ type: 'entity' });
  const [editingEntity, setEditingEntity] = useState<Entity>(entity);
  const [showFieldModal, setShowFieldModal] = useState(false);
  const [selectedFieldTarget, setSelectedFieldTarget] = useState<{ subtypeKey?: string } | null>(null);

  // Semantic Search State
  const [semanticSearchTerm, setSemanticSearchTerm] = useState('');
  const [selectedTermIds, setSelectedTermIds] = useState<string[]>([]);

  // Subtype Modal
  const [addSubtypeModalVisible, setAddSubtypeModalVisible] = useState(false);
  const [newSubtypeData, setNewSubtypeData] = useState({ name: '', description: '', isCore: false });

  const { semanticTerms } = useEnhancedSemanticTerms(datasourceId);
  const { tenant, datasource } = useTenant();
  const { enqueueSnackbar } = useSnackbar();
  const confirm = useConfirm();
  const notification = useNotification();

  // Sync editingEntity when entity prop changes
  useEffect(() => {
    setEditingEntity(entity);
  }, [entity]);

  // Build Hierarchy Tree
  const hierarchyTree: HierarchyNode[] = useMemo(() => [
    {
      title: (
        <div className="flex items-center gap-2 px-3 py-2 bg-blue-600/10 text-blue-600 rounded-lg font-semibold cursor-pointer w-full">
          <span className="material-symbols-outlined text-[20px]">folder_open</span>
          <span>{editingEntity.businessName || editingEntity.name}</span>
        </div>
      ),
      key: 'entity',
      children: editingEntity.subtypes
        ? Object.entries(editingEntity.subtypes).map(([subtypeKey, subtype]) => ({
            title: (
              <div className="flex items-center gap-2 px-3 py-2 text-[#60758a] dark:text-[#94a3b8] hover:bg-[#f0f2f5] dark:hover:bg-[#1c2630] hover:text-[#111418] dark:hover:text-white rounded-lg cursor-pointer transition-colors w-full group">
                <span className="material-symbols-outlined text-[20px] text-gray-400 group-hover:text-gray-600">wysiwyg</span>
                <span>{subtype.businessName || subtype.name}</span>
                {!subtype.isCore && (
                     <button 
                         className="ml-auto text-gray-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                         onClick={(e) => {
                             e.stopPropagation();
                             handleDeleteSubtype(subtypeKey);
                         }}
                     >
                         <DeleteIcon sx={{ fontSize: 16 }} />
                     </button>
                 )}
              </div>
            ),
            key: subtypeKey,
          }))
        : [],
    },
  ], [editingEntity]);

  // Get Fields for Selected Node
  const getSelectedFields = () => {
    if (selectedNode.type === 'entity') {
      return {
        inherited: [],
        assigned: editingEntity.entity_fields || [],
      };
    }

    if (selectedNode.type === 'subtype' && selectedNode.subtypeKey) {
      const subtype = editingEntity.subtypes?.[selectedNode.subtypeKey];
      if (!subtype) return { inherited: [], assigned: [] };

      return {
        inherited: editingEntity.entity_fields || [],
        assigned: subtype.subtype_fields || [],
      };
    }

    return { inherited: [], assigned: [] };
  };

  const { inherited, assigned } = getSelectedFields();

  // Helper: Get Validation Rules for Field
  const getValidationRulesForField = (field: Field) => {
    if (!validationRules || validationRules.length === 0) return [];
    return validationRules.filter((rule: any) => {
      if (!rule.condition_json) return false;
      try {
        const condition = typeof rule.condition_json === 'string' ? JSON.parse(rule.condition_json) : rule.condition_json;
        return condition?.field === field.key || condition?.field_name === field.technicalName || condition?.fields?.includes(field.key);
      } catch { return false; }
    });
  };

  // -- Handlers --

  const handleTreeSelect = (event: React.SyntheticEvent, itemId: string | null) => {
      if (!itemId) return;
      if (itemId === 'entity') {
          setSelectedNode({ type: 'entity' });
      } else {
          setSelectedNode({ type: 'subtype', subtypeKey: itemId });
      }
  };

  const handleAddSubtype = () => {
      if (!newSubtypeData.name) {
          notification.error("Subtype name is required");
          return;
      }

      const key = newSubtypeData.name.toLowerCase().replace(/\s+/g, '_');
      // Simple uniqueness check
      if (editingEntity.subtypes && editingEntity.subtypes[key]) {
          notification.error("Subtype with this name already exists");
          return;
      }

      const updated = { ...editingEntity };
      if (!updated.subtypes) updated.subtypes = {};

      updated.subtypes[key] = {

          key: key,
          name: key, // technical name

          businessName: newSubtypeData.name,
          technicalName: key,

          isCore: newSubtypeData.isCore,
          subtype_fields: [],
      };

      setEditingEntity(updated);
      setAddSubtypeModalVisible(false);
      setNewSubtypeData({ name: '', description: '', isCore: false });
      notification.success("Subtype added");
  };

  const handleDeleteSubtype = async (subtypeKey: string) => {
      if (!(await confirm({ title: 'Delete subtype', description: 'This will permanently delete this subtype.' }))) return;

      const updated = { ...editingEntity };
      if (updated.subtypes) {
          delete updated.subtypes[subtypeKey];
          setEditingEntity(updated);
          if (selectedNode.type === 'subtype' && selectedNode.subtypeKey === subtypeKey) {
              setSelectedNode({ type: 'entity' });
          }
          notification.success("Subtype deleted");
      }
  };

  const handleAddFieldClick = () => {
      setSelectedFieldTarget({ subtypeKey: selectedNode.type === 'subtype' ? selectedNode.subtypeKey : undefined });
      setSemanticSearchTerm('');
      setSelectedTermIds([]);
      setShowFieldModal(true);
  };

  const handleAddSelectedFields = () => {
    if (selectedTermIds.length === 0) return;

    const updated = JSON.parse(JSON.stringify(editingEntity));
    let addedCount = 0;

    selectedTermIds.forEach(termId => {
      const term = semanticTerms.find((t) => t.id === termId);
      if (!term) return;

      const newField = semanticTermToField(term, 0);
      if (!newField.key) newField.key = `field_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

      if (!selectedFieldTarget?.subtypeKey) {
        // Adding to entity
        if (!updated.entity_fields) updated.entity_fields = [];
        updated.entity_fields.push(newField);
      } else {
        // Adding to subtype
        const subtypeKey = selectedFieldTarget.subtypeKey;
        if (updated.subtypes && updated.subtypes[subtypeKey]) {
            if (!updated.subtypes[subtypeKey].subtype_fields) updated.subtypes[subtypeKey].subtype_fields = [];
            updated.subtypes[subtypeKey].subtype_fields.push(newField);
        }
      }
      addedCount++;
    });

    setEditingEntity(updated);
    setShowFieldModal(false);
    setSelectedTermIds([]);
    notification.success(`${addedCount} fields added`);
  };

  const handleDeleteField = (fieldKey: string) => {
      const updated = JSON.parse(JSON.stringify(editingEntity));
      if (selectedNode.type === 'entity') {
          updated.entity_fields = (updated.entity_fields || []).filter((f: Field) => f.key !== fieldKey);
      } else if (selectedNode.subtypeKey && updated.subtypes?.[selectedNode.subtypeKey]) {
          updated.subtypes[selectedNode.subtypeKey].subtype_fields = (updated.subtypes[selectedNode.subtypeKey].subtype_fields || []).filter((f: Field) => f.key !== fieldKey);
      }
      setEditingEntity(updated);
  };

  const handleSave = async () => {
      try {
          // Detect changes logic (simplified from original for brevity, but retains core save)
          onEntityUpdate(editingEntity);

          const updatedEntities = { ...entities, [entityKey]: editingEntity };
          await saveEntitySchema(updatedEntities, tenant?.id, datasource?.id);
          notification.success("Entity saved successfully");
      } catch (e: any) {
          devError("Failed to save entity", e);
          notification.error(`Failed to save: ${e.message}`);
      }
  };

  // --- Render ---

  return (
    <Box sx={{ display: 'flex', flexDirection: { xs: 'column', lg: 'row' }, gap: 3, minHeight: 600 }}>

      {/* Left Pane: Hierarchy */}
      <Box sx={{ width: { xs: '100%', lg: '30%', xl: '25%' } }}>
        <Paper variant="outlined" sx={{ height: '100%', display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
            <Box sx={{ p: 2, borderBottom: 1, borderColor: 'divider' }}>
            <Typography variant="overline" fontWeight="bold" color="text.primary">Object Structure</Typography>
            <Box sx={{ position: 'relative', mt: 1 }}>
                <TextField
                    fullWidth
                    size="small"
                    placeholder="Filter hierarchy..."
                    variant="outlined"
                    InputProps={{
                        startAdornment: <SearchIcon fontSize="small" color="action" sx={{ mr: 1 }} />
                    }}
                    sx={{
                        '& .MuiOutlinedInput-root': {
                            bgcolor: 'action.hover',
                        }
                    }}
                />
            </Box>
            </Box>

            <Box sx={{ flex: 1, overflowY: 'auto', p: 1 }}>
                <TreeView
                    slots={{ expandIcon: ChevronRightIcon, collapseIcon: ExpandMoreIcon }}
                    selectedItems={selectedNode.type === 'entity' ? 'entity' : selectedNode.subtypeKey}
                    onItemSelectionToggle={handleTreeSelect}
                    defaultExpandedItems={['entity']}
                >
                    {hierarchyTree.map((node) => (
                        <TreeItem key={node.key} itemId={node.key} label={node.title}>
                            {node.children?.map((child) => (
                                <TreeItem key={child.key} itemId={child.key} label={child.title} />
                            ))}
                        </TreeItem>
                    ))}
                </TreeView>
            </Box>
        </Paper>
      </Box>

      {/* Right Pane: Fields */}
      <Box sx={{ width: { xs: '100%', lg: '70%', xl: '75%' } }}>
        <Paper variant="outlined" sx={{ height: '100%', display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>

            {/* Header */}
            <Box sx={{ p: 3, borderBottom: 1, borderColor: 'divider', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 2 }}>
                <Box>
                    <Typography variant="h6" fontWeight="bold" sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <span className="material-symbols-outlined" style={{ color: '#1976d2' }}>dataset</span>
                        Fields for '{selectedNode.type === 'entity' ? editingEntity.businessName : editingEntity.subtypes?.[selectedNode.subtypeKey!]?.businessName}'
                    </Typography>
                    <Typography variant="body2" color="text.secondary" sx={{ mt: 0.5 }}>
                        {selectedNode.type === 'entity' ? 'Define data types, constraints, and display logic for the core entity.' : 'Manage extension fields specific to this subtype.'}
                    </Typography>
                </Box>
                <Box sx={{ display: 'flex', gap: 1 }}>
                    <Button 
                        variant="outlined" 
                        startIcon={<SaveIcon />}
                        onClick={handleSave}
                        color="inherit"
                    >
                        Save
                    </Button>
                    <Button 
                        variant="contained" 
                        startIcon={<AddIcon />}
                        onClick={handleAddFieldClick}
                    >
                        Add Field
                    </Button>
                </Box>
            </Box>

            {/* Content */}
            <Box sx={{ flex: 1, overflowX: 'auto' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse', minWidth: 600 }}>
                    <thead>
                        <tr style={{ background: 'var(--mui-palette-action-hover)', borderBottom: '1px solid var(--mui-palette-divider)' }}>
                            <th style={{ padding: '12px 16px', textAlign: 'left', fontSize: '0.75rem', fontWeight: 600, textTransform: 'uppercase', color: 'var(--mui-palette-text-secondary)' }}>Technical Name</th>
                            <th style={{ padding: '12px 16px', textAlign: 'left', fontSize: '0.75rem', fontWeight: 600, textTransform: 'uppercase', color: 'var(--mui-palette-text-secondary)' }}>Display Label</th>
                            <th style={{ padding: '12px 16px', textAlign: 'left', fontSize: '0.75rem', fontWeight: 600, textTransform: 'uppercase', color: 'var(--mui-palette-text-secondary)' }}>Data Type</th>
                            <th style={{ padding: '12px 16px', textAlign: 'left', fontSize: '0.75rem', fontWeight: 600, textTransform: 'uppercase', color: 'var(--mui-palette-text-secondary)' }}>Validation</th>
                            <th style={{ padding: '12px 16px', textAlign: 'right', fontSize: '0.75rem', fontWeight: 600, textTransform: 'uppercase', color: 'var(--mui-palette-text-secondary)' }}>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {/* Inherited Fields */}
                        {inherited.map(field => {
                            const rules = getValidationRulesForField(field);
                            return (
                                <tr key={field.key} style={{ borderBottom: '1px solid var(--mui-palette-divider)', background: 'var(--mui-palette-action-hover)' }}>
                                    <td style={{ padding: '16px', fontSize: '0.875rem' }}>
                                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, color: 'text.secondary' }}>
                                            <span className="material-symbols-outlined" style={{ fontSize: 16 }}>lock</span>
                                            {field.technicalName}
                                        </Box>
                                    </td>
                                    <td style={{ padding: '16px', fontSize: '0.875rem', color: 'var(--mui-palette-text-secondary)' }}>{field.businessName || field.name}</td>
                                    <td style={{ padding: '16px' }}>
                                        <Chip label={field.type} size="small" variant="outlined" />
                                    </td>
                                    <td style={{ padding: '16px' }}>
                                        {rules.length > 0 ? (
                                            <Chip icon={<CheckCircleIcon />} label={`${rules.length} Rules`} size="small" color="success" variant="outlined" />
                                        ) : (
                                            <Typography variant="body2" color="text.secondary">-</Typography>
                                        )}
                                    </td>
                                    <td style={{ padding: '16px', textAlign: 'right' }}>
                                        <Typography variant="caption" fontStyle="italic" color="text.secondary">Inherited</Typography>
                                    </td>
                                </tr>
                            );
                        })}

                        {/* Assigned Fields */}
                        {assigned.map((field) => {
                            const rules = getValidationRulesForField(field);
                            return (
                                <tr key={field.key} style={{ borderBottom: '1px solid var(--mui-palette-divider)' }}>
                                    <td style={{ padding: '16px', fontSize: '0.875rem', fontWeight: 500 }}>{field.technicalName}</td>
                                    <td style={{ padding: '16px', fontSize: '0.875rem', color: 'var(--mui-palette-text-secondary)' }}>{field.businessName || field.name}</td>
                                    <td style={{ padding: '16px' }}>
                                        <Chip label={field.type} size="small" color="primary" variant="outlined" sx={{ bgcolor: 'primary.50' }} />
                                    </td>
                                    <td style={{ padding: '16px' }}>
                                        {rules.length > 0 ? (
                                            <Chip icon={<CheckCircleIcon />} label="Valid" size="small" color="success" variant="outlined" />
                                        ) : (
                                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, color: 'text.disabled' }}>
                                                <span className="material-symbols-outlined" style={{ fontSize: 18 }}>remove_circle_outline</span>
                                                <Typography variant="body2">None</Typography>
                                            </Box>
                                        )}
                                    </td>
                                    <td style={{ padding: '16px', textAlign: 'right' }}>
                                        <IconButton size="small" onClick={() => handleDeleteField(field.key)} color="error">
                                            <DeleteIcon fontSize="small" />
                                        </IconButton>
                                    </td>
                                </tr>
                            );
                        })}

                        {assigned.length === 0 && inherited.length === 0 && (
                            <tr>
                                <td colSpan={5} style={{ padding: '48px', textAlign: 'center', color: 'var(--mui-palette-text-secondary)' }}>
                                    No fields defined. Click "Add Field" to assume control.
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </Box>

            {/* Footer */}
            <Box sx={{ p: 2, borderTop: 1, borderColor: 'divider', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <Typography variant="body2" color="text.secondary">
                    Showing <Box component="span" fontWeight="bold" color="text.primary">{assigned.length + inherited.length}</Box> fields
                </Typography>
            </Box>
        </Paper>
      </Box>

      {/* Add Fields Dialog */}
      <Dialog open={showFieldModal} onClose={() => setShowFieldModal(false)} maxWidth="md" fullWidth>
        <DialogTitle>Add Fields from Semantic Terms</DialogTitle>
        <DialogContent>
            <Box sx={{ mt: 2 }}>
                <TextField 
                    fullWidth 
                    placeholder="Search semantic terms..."
                    InputProps={{ startAdornment: <SearchIcon color="action" /> }}
                    value={semanticSearchTerm}
                    onChange={(e) => setSemanticSearchTerm(e.target.value)}
                    sx={{ mb: 2 }}
                />

                <Paper variant="outlined" sx={{ maxHeight: 240, overflowY: 'auto' }}>
                    {semanticTerms
                        .filter(t => t.businessName?.toLowerCase().includes(semanticSearchTerm.toLowerCase()) || t.node_name.toLowerCase().includes(semanticSearchTerm.toLowerCase()))
                        .slice(0, 50)
                        .map(term => (
                            <Box 
                                key={term.id} 
                                sx={{ 
                                    p: 1.5, 
                                    display: 'flex', 
                                    alignItems: 'center', 
                                    gap: 1.5,
                                    cursor: 'pointer',
                                    bgcolor: selectedTermIds.includes(term.id) ? 'action.selected' : 'inherit',
                                    '&:hover': { bgcolor: 'action.hover' }
                                }}
                                onClick={() => {
                                    if (selectedTermIds.includes(term.id)) {
                                        setSelectedTermIds(prev => prev.filter(id => id !== term.id));
                                    } else {
                                        setSelectedTermIds(prev => [...prev, term.id]);
                                    }
                                }}
                            >
                                <input type="checkbox" checked={selectedTermIds.includes(term.id)} readOnly style={{ pointerEvents: 'none' }} />
                                <Box>
                                    <Typography variant="body2" fontWeight="medium">{term.businessName || term.node_name}</Typography>
                                    <Typography variant="caption" color="text.secondary">{term.dataType}</Typography>
                                </Box>
                            </Box>
                        ))
                    }
                </Paper>
            </Box>
        </DialogContent>
        <DialogActions>
            <Button onClick={() => setShowFieldModal(false)}>Cancel</Button>
            <Button onClick={handleAddSelectedFields} variant="contained" disabled={selectedTermIds.length === 0}>
                Add Selected ({selectedTermIds.length})
            </Button>
        </DialogActions>
      </Dialog>

      {/* Add Subtype Dialog */}
      <Dialog open={addSubtypeModalVisible} onClose={() => setAddSubtypeModalVisible(false)}>
          <DialogTitle>Add New Subtype</DialogTitle>
          <DialogContent>
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1, minWidth: 400 }}>
                  <TextField 
                      label="Subtype Name" 
                      fullWidth 
                      value={newSubtypeData.name} 
                      onChange={(e) => setNewSubtypeData(prev => ({ ...prev, name: e.target.value }))}
                  />
                  <TextField 
                      label="Description" 
                      fullWidth 
                      multiline 
                      rows={2} 
                      value={newSubtypeData.description} 
                      onChange={(e) => setNewSubtypeData(prev => ({ ...prev, description: e.target.value }))}
                  />
                  <FormControl fullWidth>
                      <InputLabel>Type</InputLabel>
                      <Select
                          value={newSubtypeData.isCore ? 'core' : 'custom'}
                          label="Type"
                          onChange={(e) => setNewSubtypeData(prev => ({ ...prev, isCore: e.target.value === 'core' }))}
                      >
                          <MenuItem value="custom">Custom (Extension)</MenuItem>
                          <MenuItem value="core">Core (Standard)</MenuItem>
                      </Select>
                  </FormControl>
              </Box>
          </DialogContent>
          <DialogActions>
              <Button onClick={() => setAddSubtypeModalVisible(false)}>Cancel</Button>
              <Button onClick={handleAddSubtype} variant="contained">Create Subtype</Button>
          </DialogActions>
      </Dialog>
    </Box>
  );
}

