// ============================================================================
// Types
// ============================================================================

export interface FieldDefinition {
  name: string;
  type: 'string' | 'number' | 'date' | 'boolean' | 'enum' | 'array' | 'object';
  label: string;
  description?: string;
  enumValues?: string[];
  nullable?: boolean;
  entity?: string; // For cross-entity fields
  path?: string;   // Full path for nested fields
}

export interface EntityDefinition {
  name: string;
  label: string;
  fields: FieldDefinition[];
  relationships: Array<{
    name: string;
    targetEntity: string;
    type: 'one-to-one' | 'one-to-many' | 'many-to-one' | 'many-to-many';
    label: string;
  }>;
}

export interface Condition {
  id: string;
  type: 'condition';
  field: string;
  fieldPath?: string; // For cross-entity: "order.customer.name"
  operator: string;
  value: string | number | boolean | string[];
  valueType?: string;
  secondValue?: string | number; // For 'between' operator
  isValid?: boolean;
  validationError?: string;
}

export interface ConditionGroup {
  id: string;
  type: 'group';
  operator: 'AND' | 'OR' | 'NOT';
  conditions: ConditionNode[];
  isCollapsed?: boolean;
  label?: string; // Optional label for complex groups
}

export type ConditionNode = Condition | ConditionGroup;

export interface OperatorDefinition {
  value: string;
  label: string;
  description?: string;
  requiresValue: boolean;
  requiresSecondValue?: boolean;
  valueType?: 'single' | 'multiple' | 'range' | 'none';
  icon?: React.ReactNode;
}

