/**
 * Marketplace Validation Rules Browser & Importer Component
 *
 * Allows users to browse, filter, and import validation rules from the marketplace
 */

import React, { useState, useEffect, useMemo } from 'react';
import {
  MARKETPLACE_VALIDATION_RULES,
} from '../data/marketplaceValidationRules';

interface MarketplaceValidationRule {
  id: string;
  name: string;
  description: string;
  category?: string;
  rule_type: string;
  scope: string | string[];
  severity: string;
  frequency: string;
  evaluationOrder: number;
  parameters: Record<string, any>;
  isActive?: boolean;
  effectiveFrom?: string;
  tags?: string[];
  downloadsCount?: number;
  usageCount?: number;
  rating?: number;
}
import {
  importMarketplaceValidationRules,
  getMarketplaceRulesSummary,
} from '../utils/marketplaceImportHandler';
import { useConfirm } from './ConfirmProvider';
import { useNotification } from '../hooks/useNotification';
import styles from './MarketplaceValidationRulesBrowser.module.css';

export interface MarketplaceRulesBrowserProps {
  tenantId: string;
  datasourceId: string;
  onImportComplete?: (result: any) => void;
  onClose?: () => void;
}

export const MarketplaceValidationRulesBrowser: React.FC<
  MarketplaceRulesBrowserProps
> = ({ tenantId, datasourceId, onImportComplete, onClose }) => {
  const [selectedRuleIds, setSelectedRuleIds] = useState<Set<string>>(new Set());
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [viewMode, setViewMode] = useState<'browse' | 'summary'>('browse');
  const [importing, setImporting] = useState(false);
  const [importMessage, setImportMessage] = useState<string | null>(null);
  const [marketplaceRules, setMarketplaceRules] = useState<MarketplaceValidationRule[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const confirm = useConfirm();
  const notification = useNotification();

  // Fetch marketplace validation rules from API
  useEffect(() => {
    const fetchMarketplaceRules = async () => {
      try {
        setLoading(true);
        setError(null);

  // Fetch validation rules (public endpoint)
        const response = await fetch(
          `/api/marketplace/validation-rules`,
          {
            headers: {
              // Marketplace rules are public, no tenant scope required
            },
          }
        );

        if (!response.ok) {
          throw new Error(`Failed to fetch validation rules: ${response.status}`);
        }

        const data = await response.json();
  // Data received; populate rules
        setMarketplaceRules(data.rules || []);
      } catch (err) {
        console.error('[MarketplaceValidationRulesBrowser] Failed to fetch marketplace validation rules:', err);
        setError(err instanceof Error ? err.message : 'Failed to load marketplace validation rules');
        // Fallback to static data
        setMarketplaceRules(MARKETPLACE_VALIDATION_RULES);
      } finally {
        setLoading(false);
      }
    };

    fetchMarketplaceRules();
  }, [tenantId, datasourceId]);

  const categories = useMemo(() => {
    const uniqueCategories = new Set(marketplaceRules.map(rule => rule.category).filter(Boolean));
    return Array.from(uniqueCategories).sort() as string[];
  }, [marketplaceRules]);
  const summary = useMemo(() => {
    const bySeverity = marketplaceRules.reduce((acc, rule) => {
      const severity = rule.severity.toLowerCase();
      acc[severity] = (acc[severity] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);

    const byCategory = categories.map(category => {
      const categoryRules = marketplaceRules.filter(rule => rule.category === category);
      const byRisk = categoryRules.reduce((acc, rule) => {
        const risk = rule.severity.toLowerCase();
        acc[risk] = (acc[risk] || 0) + 1;
        return acc;
      }, {} as Record<string, number>);
      return {
        category,
        count: categoryRules.length,
        byRisk
      };
    });

    return {
      totalRules: marketplaceRules.length,
      totalCategories: categories.length,
      bySeverity,
      byCategory
    };
  }, [marketplaceRules, categories]);

  // Filter rules based on search and category
  const filteredRules = useMemo(() => {
    let rules = marketplaceRules;

    if (searchQuery) {
      rules = rules.filter((r: MarketplaceValidationRule) =>
        r.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        r.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
        (r.category && r.category.toLowerCase().includes(searchQuery.toLowerCase()))
      );
    }

    if (selectedCategory) {
      rules = rules.filter((r: MarketplaceValidationRule) => r.category === selectedCategory);
    }

    return rules;
  }, [marketplaceRules, searchQuery, selectedCategory]);

  // Handle individual rule selection
  const toggleRuleSelection = (ruleId: string) => {
    const newSelected = new Set(selectedRuleIds);
    if (newSelected.has(ruleId)) {
      newSelected.delete(ruleId);
    } else {
      newSelected.add(ruleId);
    }
    setSelectedRuleIds(newSelected);
  };

  // Handle select/deselect all in current view
  const toggleAllInView = () => {
    const currentRuleIds = new Set(
      filteredRules.map((r) => r.id)
    );

    const newSelected = new Set(selectedRuleIds);
    let allSelected = true;

    for (const id of currentRuleIds) {
      if (!newSelected.has(id)) {
        allSelected = false;
        break;
      }
    }

    if (allSelected) {
      // Deselect all in view
      for (const id of currentRuleIds) {
        newSelected.delete(id);
      }
    } else {
      // Select all in view
      for (const id of currentRuleIds) {
        newSelected.add(id);
      }
    }

    setSelectedRuleIds(newSelected);
  };

  // Handle import
  const handleImport = async () => {
    if (selectedRuleIds.size === 0) {
      notification.error('Please select at least one rule to import');
      return;
    }

    if (!(await confirm({ title: 'Import rules', description: `Import ${selectedRuleIds.size} validation rule(s) into the current tenant/datasource?` }))) {
      return;
    }

    setImporting(true);
    setImportMessage('Importing rules...');

    try {
      const result = await importMarketplaceValidationRules(
        tenantId,
        datasourceId,
        Array.from(selectedRuleIds)
      );

      let message = `✓ Created: ${result.created}\n`;
      if (result.updated > 0) message += `✓ Updated: ${result.updated}\n`;
      if (result.skipped > 0) message += `⚠ Skipped: ${result.skipped}\n`;

      if (result.failed.length > 0) {
        message += `\n❌ Failed rules:\n`;
        result.failed.forEach((f) => {
          message += `  - ${f.ruleName}: ${f.error}\n`;
        });
      }

      setImportMessage(message);
      notification.success('Marketplace rules imported successfully');

      if (onImportComplete) {
        onImportComplete(result);
      }

      // Clear selection after successful import
      if (result.failed.length === 0) {
        setSelectedRuleIds(new Set());
        setTimeout(() => {
          if (onClose) onClose();
        }, 2000);
      }
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      setImportMessage(`❌ Import failed: ${errorMsg}`);
    } finally {
      setImporting(false);
    }
  };

  // Render browse mode with left-side facets
  const renderBrowseMode = () => (
    <div className={styles.browseContainer}>
      <div className={styles.sidebar}>
        {/* Search Bar */}
        <div className={styles.searchBar}>
          <input
            type="text"
            placeholder="Search rules by name, description, or tags..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className={styles.searchInput}
          />
        </div>

        {/* Category Filter (facets) */}
        <div className={styles.categoryFilter}>
          <button
            className={`${styles.categoryBtn} ${
              selectedCategory === null ? styles.active : ''
            }`}
            onClick={() => setSelectedCategory(null)}
          >
            All ({marketplaceRules.length})
          </button>
          {categories.map((cat: string) => {
            const count = marketplaceRules.filter((r: MarketplaceValidationRule) => r.category === cat).length;
            return (
              <button
                key={cat}
                className={`${styles.categoryBtn} ${
                  selectedCategory === cat ? styles.active : ''
                }`}
                onClick={() => setSelectedCategory(cat)}
              >
                {cat} ({count})
              </button>
            );
          })}
        </div>

        {/* Select All */}
        <div className={styles.selectAllContainer}>
          <label className={styles.selectAllLabel}>
            <input
              type="checkbox"
              checked={selectedRuleIds.size > 0 && filteredRules.every((r) => selectedRuleIds.has(r.id))}
              onChange={toggleAllInView}
            />
            Select all in view ({filteredRules.length})
          </label>
        </div>
      </div>

      {/* Main content: rules list */}
      <div className={styles.mainContent}>
        <div className={styles.rulesList}>
          {filteredRules.length === 0 ? (
            <div className={styles.noRules}>No rules found</div>
          ) : (
            filteredRules.map((rule) => (
              <div
                key={rule.id}
                className={`${styles.ruleCard} ${
                  selectedRuleIds.has(rule.id) ? styles.selected : ''
                }`}
                onClick={() => toggleRuleSelection(rule.id)}
              >
                <div className={styles.ruleHeader}>
                  <input
                    type="checkbox"
                    checked={selectedRuleIds.has(rule.id)}
                    onChange={(e) => {
                      e.stopPropagation();
                      toggleRuleSelection(rule.id);
                    }}
                    title="Select this rule for import"
                    aria-label={`Select ${rule.name}`}
                  />
                  <h3 className={styles.ruleName}>{rule.name}</h3>
                  <span className={`${styles.severity} ${styles[`severity-${rule.severity.toLowerCase()}`]}`}>
                    {rule.severity}
                  </span>
                </div>

                <p className={styles.ruleDescription}>{rule.description}</p>

                <div className={styles.ruleMetadata}>
                  <div className={styles.metaItem}>
                    <span className={styles.label}>Type:</span>
                    <span className={styles.value}>{rule.rule_type}</span>
                  </div>
                  <div className={styles.metaItem}>
                    <span className={styles.label}>Frequency:</span>
                    <span className={styles.value}>{rule.frequency}</span>
                  </div>
                  <div className={styles.metaItem}>
                    <span className={styles.label}>Category:</span>
                    <span className={styles.value}>{rule.category}</span>
                  </div>
                </div>

                {rule.tags && rule.tags.length > 0 && (
                  <div className={styles.tags}>
                    {rule.tags.map((tag: string) => (
                      <span key={tag} className={styles.tag}>
                        {tag}
                      </span>
                    ))}
                  </div>
                )}
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );

  // Render summary mode
  const renderSummaryMode = () => (
    <div className={styles.summaryContainer}>
      <div className={styles.summaryStats}>
        <div className={styles.statCard}>
          <div className={styles.statNumber}>{summary.totalRules}</div>
          <div className={styles.statLabel}>Total Rules</div>
        </div>
        <div className={styles.statCard}>
          <div className={styles.statNumber}>{summary.totalCategories}</div>
          <div className={styles.statLabel}>Categories</div>
        </div>
        <div className={`${styles.statCard} ${styles.block}`}>
          <div className={styles.statNumber}>{summary.bySeverity.block}</div>
          <div className={styles.statLabel}>BLOCK Rules</div>
        </div>
        <div className={`${styles.statCard} ${styles.warning}`}>
          <div className={styles.statNumber}>{summary.bySeverity.warning}</div>
          <div className={styles.statLabel}>WARNING Rules</div>
        </div>
        <div className={`${styles.statCard} ${styles.info}`}>
          <div className={styles.statNumber}>{summary.bySeverity.info}</div>
          <div className={styles.statLabel}>INFO Rules</div>
        </div>
      </div>

      <div className={styles.categorySummary}>
        <h3>Rules by Category</h3>
        {summary.byCategory.map((cat) => (
          <div key={cat.category} className={styles.categorySummaryItem}>
            <div className={styles.categoryName}>{cat.category}</div>
            <div className={styles.categoryBreakdown}>
              <span className={`${styles.risk} ${styles.block}`}>
                BLOCK: {cat.byRisk.block}
              </span>
              <span className={`${styles.risk} ${styles.warning}`}>
                WARNING: {cat.byRisk.warning}
              </span>
              <span className={`${styles.risk} ${styles.info}`}>
                INFO: {cat.byRisk.info}
              </span>
              <span className={styles.total}>Total: {cat.count}</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <h2>📦 Marketplace Validation Rules</h2>
        <div className={styles.viewToggle}>
          <button
            className={`${styles.toggleBtn} ${viewMode === 'browse' ? styles.active : ''}`}
            onClick={() => setViewMode('browse')}
          >
            Browse
          </button>
          <button
            className={`${styles.toggleBtn} ${viewMode === 'summary' ? styles.active : ''}`}
            onClick={() => setViewMode('summary')}
          >
            Summary
          </button>
        </div>
      </div>

      {/* Loading State */}
      {loading && (
        <div className={styles.loadingState}>
          <div className={styles.spinner}></div>
          <p>Loading marketplace validation rules...</p>
        </div>
      )}

      {/* Error State */}
      {error && (
        <div className={styles.errorState}>
          <p>❌ {error}</p>
          <button
            onClick={() => window.location.reload()}
            className={styles.retryBtn}
          >
            Retry
          </button>
        </div>
      )}

      {/* Content */}
      {!loading && !error && (
        <>
          {viewMode === 'browse' ? renderBrowseMode() : renderSummaryMode()}
        </>
      )}

      {/* Import Section */}
      <div className={styles.footer}>
        {importMessage && (
          <div className={`${styles.message} ${styles[importing ? 'loading' : 'done']}`}>
            <pre>{importMessage}</pre>
          </div>
        )}

        <div className={styles.actions}>
          <button
            className={`${styles.btn} ${styles.secondary}`}
            onClick={onClose}
            disabled={importing}
          >
            Close
          </button>
          {selectedRuleIds.size > 0 && (
            <button
              className={`${styles.btn} ${styles.primary}`}
              onClick={handleImport}
              disabled={importing}
            >
              {importing ? 'Importing...' : `Import ${selectedRuleIds.size} Rule(s)`}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default MarketplaceValidationRulesBrowser;

import React, { useState, useEffect } from 'react';
import { Search, Database, Layers, TrendingUp, RefreshCw, Zap, Link2, Filter } from 'lucide-react';

interface BusinessObject {
  id: string;
  name: string;
  display_name: string;
  description: string;
  status: string;
  version: number;
  fields: Array<{
    name: string;
    type: string;
    label: string;
    is_required: boolean;
  }>;
  is_core: boolean;
  category: string;
}

interface SemanticView {
  view_id: string;
  view_name: string;
  tenant_id: string;
  version: number;
  fields: Array<{
    field_name: string;
    field_type: string;
    description?: string;
  }>;
}

interface UnifiedMetadata {
  tenant_id: string;
  business_objects: BusinessObject[];
  semantic_views: SemanticView[];
  cached_at: string;
}

interface CacheMetrics {
  business_objects: {
    hits: number;
    misses: number;
    hit_rate: number;
    item_count: number;
    memory_bytes: number;
  };
  semantic_views: {
    semantic_view_count: number;
    cache_ttl_hours: number;
  };
}

const MetadataExplorer: React.FC = () => {
  const [metadata, setMetadata] = useState<UnifiedMetadata | null>(null);
  const [metrics, setMetrics] = useState<CacheMetrics | null>(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<'business-objects' | 'semantic-views' | 'mappings'>('business-objects');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedBO, setSelectedBO] = useState<BusinessObject | null>(null);
  const [selectedView, setSelectedView] = useState<SemanticView | null>(null);

  useEffect(() => {
    fetchMetadata();
    fetchMetrics();
  }, []);

  const fetchMetadata = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/metadata/unified', {
        headers: {
          'X-Tenant-ID': 'default-tenant', // Replace with actual tenant
        },
      });
      const data = await response.json();
      setMetadata(data);
    } catch (error) {
      console.error('Failed to fetch metadata:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchMetrics = async () => {
    try {
      const response = await fetch('/api/metadata/unified/metrics');
      const data = await response.json();
      setMetrics(data);
    } catch (error) {
      console.error('Failed to fetch metrics:', error);
    }
  };

  const invalidateCache = async () => {
    try {
      await fetch('/api/metadata/unified/invalidate', {
        method: 'POST',
        headers: {
          'X-Tenant-ID': 'default-tenant',
          'Content-Type': 'application/json',
        },
      });
      fetchMetadata();
      fetchMetrics();
    } catch (error) {
      console.error('Failed to invalidate cache:', error);
    }
  };

  const filteredBusinessObjects = metadata?.business_objects.filter(bo =>
    bo.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    bo.display_name.toLowerCase().includes(searchQuery.toLowerCase())
  ) || [];

  const filteredSemanticViews = metadata?.semantic_views.filter(view =>
    view.view_name.toLowerCase().includes(searchQuery.toLowerCase())
  ) || [];

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 dark:from-slate-900 dark:via-slate-800 dark:to-indigo-950">
      {/* Header */}
      <div className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-200 dark:border-slate-700 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <div className="p-3 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-xl shadow-lg">
                <Database className="w-6 h-6 text-white" />
              </div>
              <div>
                <h1 className="text-2xl font-bold bg-gradient-to-r from-blue-600 to-indigo-600 bg-clip-text text-transparent">
                  Metadata Explorer
                </h1>
                <p className="text-sm text-slate-600 dark:text-slate-400">
                  Unified Business Objects & Semantic Views
                </p>
              </div>
            </div>

            <div className="flex items-center space-x-3">
              <button
                onClick={invalidateCache}
                className="flex items-center space-x-2 px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700 transition-all shadow-sm"
              >
                <RefreshCw className="w-4 h-4" />
                <span className="text-sm font-medium">Refresh</span>
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Metrics Dashboard */}
      {metrics && (
        <div className="max-w-7xl mx-auto px-6 py-6">
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <MetricCard
              icon={<Database className="w-5 h-5" />}
              label="Business Objects"
              value={metrics.business_objects.item_count.toString()}
              subtitle={`${(metrics.business_objects.hit_rate * 100).toFixed(1)}% hit rate`}
              color="blue"
            />
            <MetricCard
              icon={<Layers className="w-5 h-5" />}
              label="Semantic Views"
              value={metrics.semantic_views.semantic_view_count.toString()}
              subtitle={`${metrics.semantic_views.cache_ttl_hours}h TTL`}
              color="indigo"
            />
            <MetricCard
              icon={<Zap className="w-5 h-5" />}
              label="Cache Hits"
              value={metrics.business_objects.hits.toLocaleString()}
              subtitle={`${metrics.business_objects.misses} misses`}
              color="green"
            />
            <MetricCard
              icon={<TrendingUp className="w-5 h-5" />}
              label="Memory Usage"
              value={`${(metrics.business_objects.memory_bytes / 1024).toFixed(0)} KB`}
              subtitle="In-memory cache"
              color="purple"
            />
          </div>
        </div>
      )}

      {/* Main Content */}
      <div className="max-w-7xl mx-auto px-6 py-6">
        <div className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl rounded-2xl shadow-xl border border-slate-200 dark:border-slate-700 overflow-hidden">
          {/* Tabs */}
          <div className="flex border-b border-slate-200 dark:border-slate-700">
            <TabButton
              active={activeTab === 'business-objects'}
              onClick={() => setActiveTab('business-objects')}
              icon={<Database className="w-4 h-4" />}
              label="Business Objects"
              count={metadata?.business_objects.length || 0}
            />
            <TabButton
              active={activeTab === 'semantic-views'}
              onClick={() => setActiveTab('semantic-views')}
              icon={<Layers className="w-4 h-4" />}
              label="Semantic Views"
              count={metadata?.semantic_views.length || 0}
            />
            <TabButton
              active={activeTab === 'mappings'}
              onClick={() => setActiveTab('mappings')}
              icon={<Link2 className="w-4 h-4" />}
              label="Mappings"
              count={0}
            />
          </div>

          {/* Search */}
          <div className="p-6 border-b border-slate-200 dark:border-slate-700">
            <div className="relative">
              <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 w-5 h-5 text-slate-400" />
              <input
                type="text"
                placeholder="Search metadata..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-12 pr-4 py-3 bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all"
              />
            </div>
          </div>

          {/* Content */}
          <div className="p-6">
            {loading ? (
              <div className="flex items-center justify-center py-12">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
              </div>
            ) : (
              <>
                {activeTab === 'business-objects' && (
                  <BusinessObjectsGrid
                    businessObjects={filteredBusinessObjects}
                    selectedBO={selectedBO}
                    onSelect={setSelectedBO}
                  />
                )}
                {activeTab === 'semantic-views' && (
                  <SemanticViewsGrid
                    semanticViews={filteredSemanticViews}
                    selectedView={selectedView}
                    onSelect={setSelectedView}
                  />
                )}
                {activeTab === 'mappings' && (
                  <MappingsView />
                )}
              </>
            )}
          </div>
        </div>
      </div>

      {/* Detail Panel */}
      {(selectedBO || selectedView) && (
        <DetailPanel
          businessObject={selectedBO}
          semanticView={selectedView}
          onClose={() => {
            setSelectedBO(null);
            setSelectedView(null);
          }}
        />
      )}
    </div>
  );
};

