                    <CardActionArea 
                      onClick={() => handleOpenModal(notif)}
                      sx={{ p: 2, borderRadius: 3 }}
                    >
                      <Stack direction={{ xs: 'column', sm: 'row' }} spacing={3} alignItems="flex-start">
                        {/* Icon */}
