                            sx={{ 
                              bgcolor: alpha(theme.palette.primary.main, 0.05),
                              color: 'primary.main',
                              border: 1,
                              borderColor: 'divider'
                            }}
                          >
                            {getChannelIcon(notif.channel)}
                          </Avatar>
                          {notif.priority === 'urgent' && (
                            <Box 
                              sx={{ 
                                position: 'absolute', 
                                bottom: -4, 
                                right: -4, 
                                bgcolor: 'error.main', 
                                color: 'white', 
                                borderRadius: '50%', 
                                width: 20, 
                                height: 20, 
                                display: 'flex', 
                                alignItems: 'center', 
