import React, { useEffect, useState } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Typography,
  Chip,
  Box,
  Divider,
  Stack,
  IconButton,
  Grid,
  useTheme,
  alpha
} from '@mui/material';
import {
  Close as CloseIcon,
  Email as EmailIcon,
  Sms as SmsIcon,
  Chat as ChatIcon,
  Group as GroupIcon,
  NotificationsActive as NotificationsActiveIcon,
  Notifications as NotificationsIcon,
  Check as CheckIcon,
  Drafts as DraftsIcon,
  Error as ErrorIcon
} from '@mui/icons-material';

interface NotificationDetailModalProps {
  notification: {
    id: string;
    subject: string;
    body: string;
    channel: string;
    priority: string;
    sent_at: string;
    opened_at?: string | null;
    action_taken?: string | null;
    action_taken_at?: string | null;
  } | null;
  isOpen: boolean;
  onClose: () => void;
  onMarkAsRead: () => void;
  onApprove: () => void;
  onReject: () => void;
}

export const NotificationDetailModal: React.FC<NotificationDetailModalProps> = ({
  notification,
  isOpen,
  onClose,
  onMarkAsRead,
  onApprove,
  onReject,
}) => {
  const theme = useTheme();

  if (!notification) return null;

  const getChannelIcon = (channel: string) => {
    switch (channel) {
      case 'email': return <EmailIcon />;
      case 'sms': return <SmsIcon />;
      case 'slack': return <ChatIcon />;
      case 'teams': return <GroupIcon />;
      case 'push': return <NotificationsActiveIcon />;
      default: return <NotificationsIcon />;
    }
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'urgent': return 'error';
      case 'high': return 'warning';
      case 'normal': return 'info';
      case 'low': return 'default';
      default: return 'default';
    }
  };

  const formatDateTime = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
      hour12: true,
    });
  };

  return (
    <Dialog 
      open={isOpen} 
      onClose={onClose} 
      maxWidth="sm" 
      fullWidth
      PaperProps={{
        elevation: 24,
        sx: { borderRadius: 3 }
      }}
    >
      {/* Header */}
      <DialogTitle sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', p: 3, pb: 2 }}>
        <Stack direction="row" spacing={2} alignItems="center" overflow="hidden">
          <Box 
            sx={{ 
              width: 48, 
              height: 48, 
              borderRadius: 2, 
              bgcolor: alpha(theme.palette.primary.main, 0.1),
              color: 'primary.main',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center' 
            }}
          >
            {getChannelIcon(notification.channel)}
          </Box>
          <Box overflow="hidden">
            <Typography variant="h6" noWrap>
              {notification.subject}
            </Typography>
            <Typography variant="caption" color="text.secondary">
              via {notification.channel} • {formatDateTime(notification.sent_at)}
            </Typography>
          </Box>
        </Stack>
        <IconButton onClick={onClose} size="small">
          <CloseIcon />
        </IconButton>
      </DialogTitle>

      <Divider />

      <DialogContent sx={{ p: 3 }}>
        <Stack spacing={2} direction="row" mb={3}>
          {!notification.opened_at && (
            <Chip 
              icon={<DraftsIcon />} 
              label="New" 
              color="primary" 
              size="small" 
              variant="outlined" 
            />
          )}
          <Chip 
            label={`${notification.priority} Priority`} 
            color={getPriorityColor(notification.priority) as any} 
            size="small" 
            sx={{ textTransform: 'capitalize' }}
          />
        </Stack>

        <Typography paragraph variant="body1" color="text.primary" sx={{ lineHeight: 1.7, whiteSpace: 'pre-line' }}>
          {notification.body}
        </Typography>

        <Box sx={{ mt: 4, bgcolor: 'action.hover', p: 3, borderRadius: 2 }}>
           <Typography variant="subtitle2" color="text.secondary" gutterBottom textTransform="uppercase" letterSpacing={1}>
             Notification Details
           </Typography>
           <Grid container spacing={2} mt={0.5}>
             <Grid item xs={6}>
               <Typography variant="caption" color="text.secondary" display="block">Opened</Typography>
               <Typography variant="body2" fontWeight="medium">
                 {notification.opened_at ? formatDateTime(notification.opened_at) : 'Not yet opened'}
               </Typography>
             </Grid>
             <Grid item xs={6}>
               <Typography variant="caption" color="text.secondary" display="block">Action Status</Typography>
               <Stack direction="row" spacing={1} alignItems="center">
                 <Box 
                   sx={{ 
                     width: 8, 
                     height: 8, 
                     borderRadius: '50%', 
                     bgcolor: notification.action_taken ? 'success.main' : 'text.disabled'
                   }} 
                 />
                 <Typography variant="body2" fontWeight="medium" textTransform="capitalize">
                   {notification.action_taken || 'Pending'}
                 </Typography>
               </Stack>
             </Grid>
           </Grid>
        </Box>
      </DialogContent>

      <Divider />

      <DialogActions sx={{ p: 3, bgcolor: 'background.default' }}>
        {!notification.opened_at && (
           <Button 
             startIcon={<DraftsIcon />} 
             onClick={onMarkAsRead}
             color="inherit"
             sx={{ mr: 'auto' }}
           >
             Mark as Read
           </Button>
        )}

        {notification.priority === 'urgent' && !notification.action_taken ? (
          <>
            <Button onClick={onReject} variant="outlined" color="error">
              Reject
            </Button>
            <Button onClick={onApprove} variant="contained" color="primary" autoFocus>
              Approve
            </Button>
          </>
        ) : (
          <Button onClick={onClose} variant="outlined" color="inherit">
            Close
          </Button>
        )}
      </DialogActions>
    </Dialog>
  );
};

/**
 * Template Editor - Visual Notification Template Builder
 * 
 * Features:
 * - Visual template creation and editing
 * - Variable picker with drag-drop placeholders
 * - Channel configuration (email/SMS/Slack/Teams/push)
 * - Conditional rules builder
 * - Live preview with sample data
 * - Test send functionality
 * - Escalation settings
 * - Quick actions configuration
 */

import React, { useState, useEffect } from 'react';
import {
  Mail,
  MessageSquare,
  Smartphone,
  Plus,
  Save,
  Eye,
  Send,
  X,
  AlertCircle,
  CheckCircle,
  Copy,
  Zap,
  Clock,
  Users,
} from 'lucide-react';

// ============================================================================
// TYPE DEFINITIONS
// ============================================================================

interface Template {
  id?: string;
  template_key: string;
  template_name: string;
  description: string;
  category: string;
  subject_template: string;
  body_template: string;
  template_variables: string[];
  enabled_channels: string[];
  default_channel: string;
  digest_mode: string;
  escalation_enabled: boolean;
  escalation_delay_minutes?: number;
  escalation_recipient_roles: string[];
  is_active: boolean;
  priority: string;
  include_quick_actions: boolean;
  quick_actions?: any;
}

interface TemplateEditorProps {
  tenant: { id: string; display_name: string };
  datasource: { id: string; source_name: string };
  templateId?: string;
  onSave?: () => void;
  onCancel?: () => void;
}

const AVAILABLE_VARIABLES = [
  'user_name',
  'process_name',
  'process_link',
  'step_name',
  'requester_name',
  'assigned_by',
  'due_date',
  'description',
  'error_message',
  'sla_deadline',
  'time_remaining',
  'completion_percentage',
  'comment_text',
  'commenter_name',
];

const CATEGORIES = ['approval', 'reminder', 'alert', 'info', 'escalation'];
const PRIORITIES = ['low', 'normal', 'high', 'urgent'];
const CHANNELS = ['email', 'sms', 'slack', 'teams', 'push'];
const DIGEST_MODES = ['immediate', 'hourly', 'daily', 'weekly'];

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export const TemplateEditor: React.FC<TemplateEditorProps> = ({
  tenant,
  datasource,
  templateId,
  onSave,
  onCancel,
}) => {
  const [template, setTemplate] = useState<Template>({
    template_key: '',
    template_name: '',
    description: '',
    category: 'info',
    subject_template: '',
    body_template: '',
    template_variables: [],
    enabled_channels: ['email'],
    default_channel: 'email',
    digest_mode: 'immediate',
    escalation_enabled: false,
    escalation_recipient_roles: [],
    is_active: true,
    priority: 'normal',
    include_quick_actions: false,
  });

  const [previewData, setPreviewData] = useState<Record<string, string>>({
    user_name: 'John Doe',
    process_name: 'Employee Onboarding',
    step_name: 'Manager Approval',
    requester_name: 'Jane Smith',
    due_date: '2025-01-15',
    description: 'Please review and approve the onboarding checklist',
    process_link: 'https://app.example.com/processes/123',
  });

  const [showPreview, setShowPreview] = useState(false);
  const [preview, setPreview] = useState<{ subject: string; body: string } | null>(null);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);

  // Load template if editing
  useEffect(() => {
    if (templateId) {
      loadTemplate();
    }
  }, [templateId]);

  const loadTemplate = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/bp-notifications/templates/${templateId}`);
      const data = await response.json();
      setTemplate(data);
    } catch (error) {
      console.error('Failed to load template:', error);
    } finally {
      setLoading(false);
    }
  };

  // Save template
  const saveTemplate = async () => {
    try {
      setSaving(true);
      const url = templateId
        ? `/api/bp-notifications/templates/${templateId}?tenant_id=${tenant.id}&datasource_id=${datasource.id}`
        : `/api/bp-notifications/templates?tenant_id=${tenant.id}&datasource_id=${datasource.id}`;

      const response = await fetch(url, {
        method: templateId ? 'PUT' : 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(template),
      });

      if (response.ok) {
        onSave?.();
      }
    } catch (error) {
      console.error('Failed to save template:', error);
    } finally {
      setSaving(false);
    }
  };

  // Generate preview
  const generatePreview = async () => {
    if (!templateId && (!template.subject_template || !template.body_template)) {
      return;
    }

    try {
      const url = templateId
        ? `/api/bp-notifications/templates/${templateId}/render`
        : '/api/bp-notifications/templates/preview';

      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          subject_template: template.subject_template,
          body_template: template.body_template,
          variables: previewData,
        }),
      });

      const data = await response.json();
      setPreview(data);
      setShowPreview(true);
    } catch (error) {
      console.error('Failed to generate preview:', error);
    }
  };

  // Insert variable at cursor
  const insertVariable = (field: 'subject_template' | 'body_template', variable: string) => {
    const placeholder = `{${variable}}`;
    setTemplate((prev) => ({
      ...prev,
      [field]: prev[field] + placeholder,
      template_variables: prev.template_variables.includes(variable)
        ? prev.template_variables
        : [...prev.template_variables, variable],
    }));
  };

  // Toggle channel
  const toggleChannel = (channel: string) => {
    setTemplate((prev) => {
      const enabled = prev.enabled_channels.includes(channel);
      const newChannels = enabled
        ? prev.enabled_channels.filter((c) => c !== channel)
        : [...prev.enabled_channels, channel];

      // If removing default channel, set new default
      let newDefault = prev.default_channel;
      if (enabled && prev.default_channel === channel && newChannels.length > 0) {
        newDefault = newChannels[0];
      }

      return {
        ...prev,
        enabled_channels: newChannels,
        default_channel: newDefault,
      };
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-gray-600">Loading template...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 p-6">
      {/* Header */}
      <div className="mb-8">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-gray-900 flex items-center gap-3">
              <Mail className="w-8 h-8 text-blue-600" />
              {templateId ? 'Edit Template' : 'Create Template'}
            </h1>
            <p className="text-gray-600 mt-2">
              Design notification templates with multi-channel support
            </p>
          </div>
          <div className="flex items-center gap-3">
            <button
              onClick={generatePreview}
              className="px-4 py-2 bg-purple-600 text-white rounded-lg font-medium hover:bg-purple-700 transition-all flex items-center gap-2"
            >
              <Eye className="w-4 h-4" />
              Preview
            </button>
            <button
              onClick={saveTemplate}
              disabled={saving}
              className="px-4 py-2 bg-green-600 text-white rounded-lg font-medium hover:bg-green-700 transition-all flex items-center gap-2 disabled:opacity-50"
            >
              <Save className="w-4 h-4" />
              {saving ? 'Saving...' : 'Save'}
            </button>
            {onCancel && (
              <button
                onClick={onCancel}
                className="px-4 py-2 bg-gray-200 text-gray-700 rounded-lg font-medium hover:bg-gray-300 transition-all"
              >
                Cancel
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Main Form */}
        <div className="lg:col-span-2 space-y-6">
          {/* Basic Info */}
          <div className="bg-white rounded-2xl shadow-xl p-6">
            <h3 className="text-xl font-bold text-gray-900 mb-4">Basic Information</h3>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Template Key *
                </label>
                <input
                  type="text"
                  value={template.template_key}
                  onChange={(e) =>
                    setTemplate({ ...template, template_key: e.target.value })
                  }
                  placeholder="bp_approval_required"
