import React, { useState, useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import './ProfessionalSearchInput.css';
import type { SearchResult as SearchResultType } from '../types/search';

interface ProfessionalSearchInputProps<T = any> {
  placeholder?: string;
  data: SearchResultType<T>[];
  // onSelect returns the payload (full object) if provided, else undefined
  onSelect: (payload: T | undefined) => void;
  onSearch?: (query: string) => void;
  className?: string;
  debounceMs?: number;
  // optional initial selected item (useful for edit mode)
  initialSelected?: SearchResultType<T> | null;
  // If provided, the component will call this when scroll hits bottom (for infinite load)
  onLoadMore?: () => void;
}

export const ProfessionalSearchInput = <T,>({
  placeholder = 'Type to search...',
  data,
  onSelect,
  onSearch,
  className = '',
  debounceMs = 300,
  initialSelected = null,
  onLoadMore,
}: ProfessionalSearchInputProps<T>) => {
  const [query, setQuery] = useState(initialSelected?.text || '');
  const [isOpen, setIsOpen] = useState(false);
  const [filteredResults, setFilteredResults] = useState<SearchResultType<T>[]>([]);
  const [highlightedIndex, setHighlightedIndex] = useState(-1);
  const searchRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const { t } = useTranslation();

  // Update query when initialSelected changes (for edit mode)
  useEffect(() => {
    if (initialSelected?.text) {
      setQuery(initialSelected.text);
    }
  }, [initialSelected?.id]);

  // Debounced search effect
  useEffect(() => {
    const timer = setTimeout(() => {
      if (query.trim()) {
        // Filter results based on query
        const q = query.toLowerCase();
        const filtered = data.filter((item) =>
          item.text.toLowerCase().includes(q) ||
          (item.subtext && item.subtext.toLowerCase().includes(q))
        );
        setFilteredResults(filtered);
        setIsOpen(filtered.length > 0);
        onSearch?.(query);
      } else {
        setFilteredResults([]);
        setIsOpen(false);
      }
      setHighlightedIndex(-1);
    }, debounceMs);

    return () => clearTimeout(timer);
  }, [query, data, onSearch, debounceMs]);

  // Handle keyboard navigation
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (!isOpen) return;

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setHighlightedIndex((prev) => (prev < filteredResults.length - 1 ? prev + 1 : prev));
        break;
      case 'ArrowUp':
        e.preventDefault();
        setHighlightedIndex((prev) => (prev > 0 ? prev - 1 : -1));
        break;
      case 'Enter':
        e.preventDefault();
        if (highlightedIndex >= 0 && filteredResults[highlightedIndex]) {
          handleSelect(filteredResults[highlightedIndex]);
        } else if (filteredResults.length === 1) {
          // If only one result, allow Enter to select it
          handleSelect(filteredResults[0]);
        }
        break;
      case 'Escape':
        setIsOpen(false);
        setHighlightedIndex(-1);
        inputRef.current?.blur();
        break;
    }
  };

  const handleSelect = (item: SearchResultType<T>) => {
    setQuery(item.text);
    setIsOpen(false);
    setHighlightedIndex(-1);
    // Return only the payload (the full object) to simplify consumers. If no payload, return undefined.
    onSelect(item.payload ?? undefined);
    inputRef.current?.blur();
  };

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(event.target as Node)) {
        setIsOpen(false);
        setHighlightedIndex(-1);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const highlightMatch = (text: string, query: string) => {
    if (!query.trim()) return text;

    const regex = new RegExp(`(${query})`, 'gi');
    const parts = text.split(regex);

    return parts.map((part, index) => 
      regex.test(part) ? (
        <mark key={index} className="search-highlight">{part}</mark>
      ) : (
        part
      )
    );
  };

  const handleClear = () => {
    setQuery('');
    setIsOpen(false);
    setHighlightedIndex(-1);
    onSearch?.('');
    inputRef.current?.focus();
  };

  return (
    <div ref={searchRef} className={`professional-search ${className}`}>
      <div className="search-input-container">
        <input
          ref={inputRef}
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder={placeholder ?? t('search.placeholder', 'Type to search...')}
          className="search-input"
          autoComplete="off"
        />
        <div className="search-icon">
          🔍
        </div>
        {query && (
          <button
            type="button"
            onClick={handleClear}
            className="clear-button"
            title={t('search.clear', 'Clear search')}
            aria-label={t('search.clear', 'Clear search')}
          >
            ✕
          </button>
        )}
      </div>

      {isOpen && filteredResults.length > 0 && (
        <div className="search-dropdown">
          <div className="search-results" role="listbox" aria-label="Search results" aria-activedescendant={highlightedIndex >= 0 && filteredResults[highlightedIndex] ? `search-option-${filteredResults[highlightedIndex].id}` : undefined} onScroll={(e) => {
            const el = e.currentTarget as HTMLElement;
            if (onLoadMore && el.scrollTop + el.clientHeight >= el.scrollHeight - 10) {
              // trigger load more when near bottom
              onLoadMore();
            }
          }}>
            {filteredResults.map((item, index) => {
              const isSelected = index === highlightedIndex;
              const ariaSelected = isSelected ? 'true' : undefined;
              return (
              <div
                key={item.id}
                id={`search-option-${item.id}`}
                className={`search-result-item ${index === highlightedIndex ? 'highlighted' : ''}`}
                onClick={() => handleSelect(item)}
                onMouseEnter={() => setHighlightedIndex(index)}
                role="option"

                tabIndex={-1}
              >
                <div className="result-text">{highlightMatch(item.text, query)}</div>
                {item.subtext && <div className="result-subtext">{highlightMatch(item.subtext, query)}</div>}
              </div>
              );
            })}
          </div>

          {filteredResults.length > 0 && (
            <div className="search-footer">
              <span className="results-count">
                {t('search.results_count', { count: filteredResults.length })}
              </span>
                <span className="keyboard-hint">
                {t('search.keyboard_hint', '↑↓ to navigate • Enter to select • Esc to close')}
              </span>
            </div>
          )}
        </div>
      )}

      {isOpen && query.trim() && filteredResults.length === 0 && (
        <div className="search-dropdown">
          <div className="no-results">
            <div className="no-results-icon">🔍</div>
            <div className="no-results-text">{t('search.no_results', 'No results found')}</div>
            <div className="no-results-subtext">
              {t('search.no_results_subtext', 'Try adjusting your search terms')}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessionalSearchInput;

import React, { useState } from 'react';
import {
  Box,
  Typography,
  IconButton,
  Button,
  TextField,
  MenuItem,
  Stack,
  Collapse,
  Card,
  Divider,
  alpha,
  useTheme,
  Tooltip
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import KeyboardArrowDownIcon from '@mui/icons-material/KeyboardArrowDown';
import KeyboardArrowRightIcon from '@mui/icons-material/KeyboardArrowRight';
import HelpOutlineIcon from '@mui/icons-material/HelpOutline';

export interface PropertyDefinition {
  name: string;
  label: string;
  data_type: 'string' | 'integer' | 'boolean' | 'date' | 'float' | 'json' | 'text' | 'object';
  nullable: boolean;
  description?: string;
  required?: boolean;
  properties?: PropertyDefinition[]; // For hierarchical objects
}

interface PropertyEditorProps {
  properties: PropertyDefinition[];
  onChange: (properties: PropertyDefinition[]) => void;
}

const PROPERTY_TYPES = [
  { value: 'string', label: 'String' },
  { value: 'integer', label: 'Integer' },
  { value: 'float', label: 'Float' },
  { value: 'boolean', label: 'Boolean' },
  { value: 'date', label: 'Date' },
  { value: 'text', label: 'Long Text' },
  { value: 'object', label: 'Nested Object' },
  { value: 'json', label: 'JSON' },
];

export const PropertyEditor: React.FC<PropertyEditorProps> = ({ properties, onChange }) => {
  const theme = useTheme();

  const handleUpdate = (path: number[], updatedProp: PropertyDefinition | null) => {
    const newProps = [...properties];
    let current: any = newProps;

    for (let i = 0; i < path.length - 1; i++) {
      current = current[path[i]].properties;
    }

    const index = path[path.length - 1];
    if (updatedProp === null) {
      current.splice(index, 1);
    } else {
      current[index] = updatedProp;
    }

    onChange(newProps);
  };

  const handleAdd = (path: number[] = []) => {
    const newProps = [...properties];
    const newProp: PropertyDefinition = {
      name: `prop_${Date.now()}`,
      label: '',
      data_type: 'string',
      nullable: true,
      required: false
    };

    if (path.length === 0) {
      newProps.push(newProp);
    } else {
      let current: any = newProps;
      for (let i = 0; i < path.length; i++) {
        if (!current[path[i]].properties) {
          current[path[i]].properties = [];
        }
        current = current[path[i]].properties;
      }
      current.push(newProp);
    }

    onChange(newProps);
  };

  return (
    <Box sx={{ width: '100%' }}>
      <Stack spacing={2}>
        {properties.map((prop, idx) => (
          <PropertyItem
            key={idx}
            property={prop}
            path={[idx]}
            onUpdate={handleUpdate}
            onAddChild={handleAdd}
          />
        ))}
        <Button
          startIcon={<AddIcon />}
          onClick={() => handleAdd()}
          variant="outlined"
          sx={{ 
            mt: 1, 
            borderStyle: 'dashed',
            color: theme.palette.text.secondary,
            borderColor: theme.palette.divider,
            '&:hover': {
              borderColor: theme.palette.primary.main,
              background: alpha(theme.palette.primary.main, 0.05)
            }
          }}
          fullWidth
        >
          Add Property
        </Button>
      </Stack>
    </Box>
  );
};

interface PropertyItemProps {
  property: PropertyDefinition;
  path: number[];
  onUpdate: (path: number[], updatedProp: PropertyDefinition | null) => void;
  onAddChild: (path: number[]) => void;
}

const PropertyItem: React.FC<PropertyItemProps> = ({ property, path, onUpdate, onAddChild }) => {
  const theme = useTheme();
  const [expanded, setExpanded] = useState(true);

  const handleChange = (field: keyof PropertyDefinition, value: any) => {
    onUpdate(path, { ...property, [field]: value });
  };

  const isContainer = property.data_type === 'object';

  return (
    <Card 
      variant="outlined" 
      sx={{ 
        p: 2, 
        border: `1px solid ${theme.palette.divider}`,
        transition: 'all 0.2s',
        '&:hover': {
          borderColor: theme.palette.primary.light,
          boxShadow: `0 2px 8px ${alpha(theme.palette.primary.main, 0.1)}`
        }
      }}
    >
      <Box sx={{ display: 'flex', gap: 2, alignItems: 'center' }}>
        <Box sx={{ display: 'flex', alignItems: 'center', minWidth: 24 }}>
          {isContainer ? (
            <IconButton size="small" onClick={() => setExpanded(!expanded)}>
              {expanded ? <KeyboardArrowDownIcon /> : <KeyboardArrowRightIcon />}
            </IconButton>
          ) : (
            <Box sx={{ width: 28 }} />
          )}
        </Box>

        <TextField
          size="small"
          label="Field Name"
          value={property.name}
          onChange={(e) => handleChange('name', e.target.value)}
          sx={{ flex: 1 }}
        />

        <TextField
          size="small"
          label="Label"
          value={property.label || ''}
          onChange={(e) => handleChange('label', e.target.value)}
          sx={{ flex: 1 }}
        />

        <TextField
          select
          size="small"
          label="Type"
          value={property.data_type}
          onChange={(e) => handleChange('data_type', e.target.value)}
          sx={{ minWidth: 150 }}
        >
          {PROPERTY_TYPES.map((option) => (
            <MenuItem key={option.value} value={option.value}>
              {option.label}
            </MenuItem>
          ))}
        </TextField>

        <Stack direction="row" spacing={0.5}>
          <Tooltip title="Delete Property">
            <IconButton 
              size="small" 
              color="error" 
              onClick={() => onUpdate(path, null)}
            >
              <DeleteOutlineIcon fontSize="small" />
            </IconButton>
          </Tooltip>
        </Stack>
      </Box>

      {/* Nested Properties */}
      {isContainer && (
        <Collapse in={expanded} timeout="auto" unmountOnExit>
          <Box sx={{ ml: 6, mt: 2, pl: 2, borderLeft: `2px solid ${theme.palette.divider}` }}>
            <Stack spacing={2}>
              {property.properties?.map((child, cIdx) => (
                <PropertyItem
                  key={cIdx}
                  property={child}
                  path={[...path, cIdx]}
                  onUpdate={(childPath, updated) => {
                    const localIdx = childPath[childPath.length - 1];
                    const newProps = [...(property.properties || [])];
                    if (updated === null) {
                      newProps.splice(localIdx, 1);
                    } else {
                      newProps[localIdx] = updated;
                    }
                    handleChange('properties', newProps);
                  }}
                  onAddChild={onAddChild}
                />
              ))}
              <Button
                size="small"
                startIcon={<AddIcon />}
                onClick={() => {
                  const newProps = [...(property.properties || [])];
                  newProps.push({
                    name: `field_${Date.now()}`,
                    label: '',
                    data_type: 'string',
                    nullable: true,
                    required: false
                  });
                  handleChange('properties', newProps);
                }}
                sx={{ alignSelf: 'flex-start', color: theme.palette.text.secondary }}
              >
                Add Nested Field
              </Button>
            </Stack>
          </Box>
        </Collapse>
      )}
    </Card>
  );
};

/**
 * Delegation Manager - Approval Authority Delegation
 * 
 * Features:
 * - Create temporary approval delegations
 * - Configure date ranges and conditions
 * - Delegation usage tracking and audit trail
 * - Backup and vacation coverage
 * - Active delegation visualization
 */

import React, { useState, useEffect, useMemo } from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Grid,
  IconButton,
  InputAdornment,
  MenuItem,
  Paper,
  Select,
  TextField,
  Typography,
  FormControl,
  InputLabel,
  ToggleButton,
  ToggleButtonGroup,
  Stack,
  Tooltip,
  Autocomplete,
  AutocompleteRenderInputParams,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Avatar,
} from '@mui/material';
import {
  Search as SearchIcon,
  Add as AddIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  Event as CalendarIcon,
  Security as SecurityIcon,
  CheckCircle as CheckCircleIcon,
  Cancel as CancelIcon,
  TrendingUp as TrendingUpIcon,
  AssignmentInd as AssignmentIndIcon,
  ViewList as ViewListIcon,
  ViewModule as ViewModuleIcon,
} from '@mui/icons-material';

// ============================================================================
// TYPE DEFINITIONS
// ============================================================================

interface Role {
  id: string;
  role_name: string;
  role_key: string;
}

interface Delegation {
  id: string;
  delegator_user_id: string;
  delegator_name?: string;
  delegate_user_id: string;
  delegate_name?: string;
  delegation_type: 'full' | 'partial' | 'backup';
  resource_type?: string;
  resource_id?: string;
  start_date: string;
  end_date?: string;
  reason?: string;
  is_active: boolean;
  usage_count?: number;
}

interface DelegationManagerProps {
  tenant: { id: string; display_name: string };
  datasource: { id: string; source_name: string };
}

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export const DelegationManager: React.FC<DelegationManagerProps> = ({
  tenant,
  datasource,
}) => {
  const [delegations, setDelegations] = useState<Delegation[]>([]);
  const [users, setUsers] = useState<any[]>([]); // User list for autocomplete
  const [roles, setRoles] = useState<Role[]>([]); // Role list for resource autocomplete
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<string>('all');
  const [filterStatus, setFilterStatus] = useState<string>('active');
  const [loading, setLoading] = useState(true);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [saving, setSaving] = useState(false);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('table');

  // Form state
  const [formData, setFormData] = useState({
    delegator_user_id: '',
    delegate_user_id: '',
    delegation_type: 'full' as 'full' | 'partial' | 'backup',
    resource_type_selection: 'Role', // 'Role' or 'Custom' (UI only helper)
    resource_type: 'role', // Actual value sent to API (default to role)
    resource_id: '',
    start_date: '',
    end_date: '',
    reason: '',
  });

  // Fetch users for autocomplete
  const fetchUsers = async () => {
    try {
      const response = await fetch(`/api/rbac/users?tenant_id=${tenant.id}`);
      const data = await response.json();
      setUsers(Array.isArray(data) ? data : []);
    } catch (error) {
      console.error('Failed to fetch users:', error);
      setUsers([]);
    }
  };

  // Fetch roles for resource autocomplete
  const fetchRoles = async () => {
    try {
      const response = await fetch(`/api/rbac/roles?tenant_id=${tenant.id}&datasource_id=${datasource.id}`);
      const data = await response.json();
      setRoles(Array.isArray(data) ? data : []);
    } catch (error) {
        console.error('Failed to fetch roles:', error);
        setRoles([]);
    }
  };

  // Fetch delegations
  const fetchDelegations = async () => {
    try {
      setLoading(true);
      const response = await fetch(
        `/api/rbac/delegations?tenant_id=${tenant.id}&datasource_id=${datasource.id}`
      );
      const data = await response.json();
      setDelegations(Array.isArray(data) ? data : []);
    } catch (error) {
      console.error('Failed to fetch delegations:', error);
      setDelegations([]);
    } finally {
      setLoading(false);
    }
  };

  // Create delegation
  const createDelegation = async () => {
    try {
      setSaving(true);
      // Ensure resource type matches selection
      const finalResourceType = formData.delegation_type === 'partial' 
        ? (formData.resource_type_selection === 'Role' ? 'role' : formData.resource_type)
        : '';

      const finalResourceId = formData.delegation_type === 'partial' ? formData.resource_id : '';

      await fetch(`/api/rbac/delegations`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...formData,
          resource_type: finalResourceType,
          resource_id: finalResourceId,
          tenant_id: tenant.id,
          datasource_id: datasource.id,
        }),
      });
      await fetchDelegations();
      setShowCreateModal(false);
      resetForm();
    } catch (error) {
      console.error('Failed to create delegation:', error);
    } finally {
      setSaving(false);
    }
  };

  // Delete delegation
  const deleteDelegation = async (delegationId: string) => {
    if (!confirm('Are you sure you want to revoke this delegation?')) return;

    try {
      await fetch(`/api/rbac/delegations/${delegationId}`, { method: 'DELETE' });
      await fetchDelegations();
    } catch (error) {
      console.error('Failed to delete delegation:', error);
    }
  };

  // Reset form
  const resetForm = () => {
    setFormData({
      delegator_user_id: '',
      delegate_user_id: '',
      delegation_type: 'full',
      resource_type_selection: 'Role',
      resource_type: '',
      resource_id: '',
      start_date: '',
      end_date: '',
      reason: '',
    });
  };

  // Filter delegations
  const filteredDelegations = useMemo(() => {
    return delegations.map(d => ({
      ...d,
      delegator_name: users.find(u => u.id === d.delegator_user_id)?.name || d.delegator_name,
      delegate_name: users.find(u => u.id === d.delegate_user_id)?.name || d.delegate_name,
    })).filter(delegation => {
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = searchTerm === '' ||
        (delegation.delegator_name || delegation.delegator_user_id || '').toLowerCase().includes(searchLower) ||
        (delegation.delegate_name || delegation.delegate_user_id || '').toLowerCase().includes(searchLower) ||
        (delegation.reason || '').toLowerCase().includes(searchLower);

      const matchesType = filterType === 'all' || delegation.delegation_type === filterType;

      let matchesStatus = true;
      if (filterStatus === 'active') {
        matchesStatus = delegation.is_active;
      } else if (filterStatus === 'inactive') {
        matchesStatus = !delegation.is_active;
      }

      return matchesSearch && matchesType && matchesStatus;
    });
  }, [delegations, users, searchTerm, filterType, filterStatus]);

  useEffect(() => {
    if (tenant.id) {
        fetchDelegations();
        fetchUsers();
        fetchRoles();
    }
  }, [tenant.id]);

  const isActive = (delegation: Delegation) => {
    const now = new Date();
    const start = new Date(delegation.start_date);
    const end = delegation.end_date ? new Date(delegation.end_date) : null;
    return delegation.is_active && now >= start && (!end || now <= end);
  };

  const getStatusChip = (delegation: Delegation) => {
    const active = isActive(delegation);
    const expired = delegation.end_date && new Date(delegation.end_date) < new Date();

    if (active) {
      return <Chip icon={<CheckCircleIcon />} label="Active" color="success" size="small" variant="outlined" />;
    }
    if (expired) {
      return <Chip icon={<CancelIcon />} label="Expired" color="error" size="small" variant="outlined" />;
    }
    return <Chip label="Inactive" size="small" variant="outlined" />;
  };

  if (loading) {
    return (
      <Box display="flex" alignItems="center" justifyContent="center" minHeight="50vh">
        <Typography>Loading delegations...</Typography>
      </Box>
    );
  }

  // Helper for Autocomplete
  const getUserOptions = () => users.map(u => ({ 
    label: `${u.name} (${u.username})`, 
    id: u.id,
    username: u.username 
  }));

  const getRoleOptions = () => roles.map(r => ({
      label: r.role_name,
      id: r.id,
      key: r.role_key
  }));

  const getDelegatorValue = () => {
    const user = users.find(u => u.id === formData.delegator_user_id);
    return user ? { label: `${user.name} (${user.username})`, id: user.id } : null;
  }

    const getDelegateValue = () => {
    const user = users.find(u => u.id === formData.delegate_user_id);
    return user ? { label: `${user.name} (${user.username})`, id: user.id } : null;
  }

  const getRoleValue = () => {
      const role = roles.find(r => r.id === formData.resource_id);
      return role ? { label: role.role_name, id: role.id, key: role.role_key } : null;
  }

  return (
    <Box sx={{ p: 4 }}>
      {/* Header */}
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={4}>
        <Box>
          <Box display="flex" alignItems="center" gap={1.5} mb={0.5}>
            <AssignmentIndIcon color="primary" sx={{ fontSize: 32 }} />
            <Typography variant="h4" fontWeight={600}>
              Delegation Overview
            </Typography>
          </Box>
          <Typography variant="body1" color="text.secondary">
            Manage approval authority delegations for {tenant.display_name}
          </Typography>
        </Box>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => {
            resetForm();
            setShowCreateModal(true);
          }}
          sx={{ textTransform: 'none', fontWeight: 600 }}
        >
          Create Delegation
        </Button>
      </Box>

      {/* Filters and View Toggle */}
      <Paper elevation={0} variant="outlined" sx={{ p: 2, mb: 4, bgcolor: 'background.paper', borderRadius: 2 }}>
        <Grid container spacing={2} alignItems="center">
          <Grid item xs={12} md={4}>
            <Autocomplete
              freeSolo
              options={delegations.flatMap(d => [
                d.delegator_name || d.delegator_user_id, 
                d.delegate_name || d.delegate_user_id
              ]).filter(Boolean)}
              value={searchTerm}
              onInputChange={(_, newValue) => setSearchTerm(newValue || '')}
              renderInput={(params) => (
                <TextField 
                    {...params}
                    fullWidth 
                    size="small" 
                    placeholder="Search delegations..." 
                    InputProps={{
                        ...params.InputProps,
                        startAdornment: (
                        <InputAdornment position="start">
                            <SearchIcon fontSize="small" />
                        </InputAdornment>
                        ),
                    }}
                />
              )}
            />
          </Grid>
          <Grid item xs={12} md={3}>
            <FormControl fullWidth size="small">
              <Select
                value={filterType}
                onChange={(e) => setFilterType(e.target.value)}
                displayEmpty
              >
                <MenuItem value="all">All Types</MenuItem>
                <MenuItem value="full">Full Authority</MenuItem>
                <MenuItem value="partial">Specific Approval</MenuItem>
                <MenuItem value="backup">Backup Only</MenuItem>
              </Select>
            </FormControl>
          </Grid>
          <Grid item xs={12} md={3}>
            <ToggleButtonGroup
              value={filterStatus}
              exclusive
              onChange={(_, value) => value && setFilterStatus(value)}
              size="small"
              fullWidth
            >
              <ToggleButton value="active" sx={{ textTransform: 'none' }}>Active</ToggleButton>
              <ToggleButton value="inactive" sx={{ textTransform: 'none' }}>Inactive</ToggleButton>
            </ToggleButtonGroup>
          </Grid>
          <Grid item xs={12} md={2} display="flex" justifyContent="flex-end">
             <ToggleButtonGroup
              value={viewMode}
              exclusive
              onChange={(_, value) => value && setViewMode(value)}
              size="small"
            >
              <ToggleButton value="table" aria-label="table view">
                <ViewListIcon fontSize="small" />
              </ToggleButton>
              <ToggleButton value="grid" aria-label="grid view">
                <ViewModuleIcon fontSize="small" />
              </ToggleButton>
            </ToggleButtonGroup>
          </Grid>
        </Grid>
      </Paper>

      {/* Content */}
      {filteredDelegations.length === 0 ? (
        <Box 
          display="flex" 
          flexDirection="column" 
          alignItems="center" 
          justifyContent="center" 
          py={8}
          bgcolor="background.paper"
          borderRadius={2}
          border={1}
          borderColor="divider"
        >
          <AssignmentIndIcon sx={{ fontSize: 64, color: 'text.disabled', mb: 2 }} />
          <Typography variant="h6" color="text.primary" gutterBottom>
            No Delegations Found
          </Typography>
          <Typography color="text.secondary" mb={3}>
            Create your first delegation to enable approval authority transfer
          </Typography>
          <Button
            variant="contained"
            onClick={() => {
              resetForm();
              setShowCreateModal(true);
            }}
            sx={{ textTransform: 'none' }}
          >
            Create Delegation
          </Button>
        </Box>
      ) : viewMode === 'table' ? (
         <TableContainer component={Paper} variant="outlined" sx={{ borderRadius: 2 }}>
          <Table size="medium">
            <TableHead sx={{ bgcolor: 'grey.50' }}>
              <TableRow>
                <TableCell><Typography variant="subtitle2" fontWeight={600}>Delegator</Typography></TableCell>
                <TableCell><Typography variant="subtitle2" fontWeight={600}>Delegate</Typography></TableCell>
                <TableCell><Typography variant="subtitle2" fontWeight={600}>Type</Typography></TableCell>
                <TableCell><Typography variant="subtitle2" fontWeight={600}>Resource</Typography></TableCell>
                <TableCell><Typography variant="subtitle2" fontWeight={600}>Duration</Typography></TableCell>
                <TableCell><Typography variant="subtitle2" fontWeight={600}>Status</Typography></TableCell>
                <TableCell align="right"><Typography variant="subtitle2" fontWeight={600}>Actions</Typography></TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredDelegations.map((delegation) => (
                <TableRow key={delegation.id} hover>
                  <TableCell>
                    <Box display="flex" alignItems="center" gap={1}>
                       <Avatar sx={{ width: 24, height: 24, fontSize: '0.75rem' }}>
                          {(delegation.delegator_name || delegation.delegator_user_id || 'U')[0].toUpperCase()}
                       </Avatar>
                       <Typography variant="body2">{delegation.delegator_name || delegation.delegator_user_id}</Typography>
                    </Box>
                  </TableCell>
                  <TableCell>
                     <Box display="flex" alignItems="center" gap={1}>
                       <Avatar sx={{ width: 24, height: 24, fontSize: '0.75rem', bgcolor: 'secondary.main' }}>
                          {(delegation.delegate_name || delegation.delegate_user_id || 'U')[0].toUpperCase()}
                       </Avatar>
                       <Typography variant="body2">{delegation.delegate_name || delegation.delegate_user_id}</Typography>
                    </Box>
                  </TableCell>
                  <TableCell>
                    <Chip 
                      label={delegation.delegation_type === 'partial' ? 'Specific' : delegation.delegation_type} 
                      size="small" 
                      color="primary" 
                      variant="outlined" 
                    />
                  </TableCell>
                  <TableCell>
                    {(delegation.resource_id || delegation.resource_type) ? (
                      <Box display="flex" alignItems="center" gap={0.5}>
                        <SecurityIcon fontSize="small" color="action" sx={{ fontSize: 16 }} />
                        <Typography variant="caption" color="text.secondary">
                          {getRoleOptions().find(r => r.id === delegation.resource_id)?.label || 
                           (delegation.resource_type === 'role' ? 'Role' : delegation.resource_type) + ': ' + (delegation.resource_id ? delegation.resource_id.substring(0, 8) + '...' : '')}
                        </Typography>
                      </Box>
                    ) : (
                      <Typography variant="caption" color="text.secondary">-</Typography>
                    )}
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2">
                        {new Date(delegation.start_date).toLocaleDateString()}
                    </Typography>
                    {delegation.end_date && (
                        <Typography variant="caption" color="text.secondary">
                             - {new Date(delegation.end_date).toLocaleDateString()}
                        </Typography>
                    )}
                  </TableCell>
                  <TableCell>{getStatusChip(delegation)}</TableCell>
                  <TableCell align="right">
                    <Tooltip title="Revoke Delegation">
                      <IconButton 
                        size="small" 
                        color="error" 
                        onClick={() => deleteDelegation(delegation.id)}
                      >
                        <DeleteIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      ) : (
        <Grid container spacing={3}>
          {filteredDelegations.map(delegation => (
            <Grid item xs={12} md={6} lg={4} key={delegation.id}>
              <Card elevation={2} sx={{ height: '100%', borderRadius: 2 }}>
                <CardContent>
                  <Box display="flex" justifyContent="space-between" alignItems="flex-start" mb={2}>
                    <Box>
                      <Box display="flex" alignItems="center" gap={1} mb={0.5}>
                        <Typography variant="subtitle1" fontWeight={600}>
                          {delegation.delegator_name || delegation.delegator_user_id}
                        </Typography>
                        <Typography color="text.secondary">→</Typography>
                        <Typography variant="subtitle1" fontWeight={600}>
                          {delegation.delegate_name || delegation.delegate_user_id}
                        </Typography>
                      </Box>
                      {delegation.reason && (
                        <Typography variant="body2" color="text.secondary" sx={{ 
                          display: '-webkit-box',
                          overflow: 'hidden',
                          WebkitBoxOrient: 'vertical',
                          WebkitLineClamp: 2,
                        }}>
                          {delegation.reason}
                        </Typography>
                      )}
                    </Box>
                    <IconButton 
                      size="small" 
                      color="error" 
                      onClick={() => deleteDelegation(delegation.id)}
                    >
                      <DeleteIcon fontSize="small" />
                    </IconButton>
                  </Box>

                  <Box display="flex" flexWrap="wrap" gap={1} mb={2}>
                    {getStatusChip(delegation)}
                    <Chip 
                      label={delegation.delegation_type === 'partial' ? 'Specific Approval' : delegation.delegation_type} 
                      size="small" 
                      color="primary" 
                      variant="outlined" 
                    />
                    {delegation.usage_count !== undefined && (
                      <Chip 
                        icon={<TrendingUpIcon />} 
                        label={`${delegation.usage_count} uses`} 
                        size="small" 
                        variant="outlined" 
                      />
                    )}
                  </Box>

                  <Stack spacing={1}>
                    <Box display="flex" alignItems="center" gap={1}>
                      <CalendarIcon fontSize="small" color="action" />
                      <Typography variant="caption" color="text.secondary">
                        {new Date(delegation.start_date).toLocaleDateString()} 
                        {delegation.end_date && ` - ${new Date(delegation.end_date).toLocaleDateString()}`}
                      </Typography>
                    </Box>
                    {/* Display Role Name if it's a role delegation, otherwise show resource ID */}
                    {(delegation.resource_id || delegation.resource_type) && (
                      <Box display="flex" alignItems="center" gap={1}>
                        <SecurityIcon fontSize="small" color="action" />
                        <Typography variant="caption" color="text.secondary">
                          {getRoleOptions().find(r => r.id === delegation.resource_id)?.label || 
                           (delegation.resource_type === 'role' ? 'Role' : delegation.resource_type) + ': ' + (delegation.resource_id ? delegation.resource_id.substring(0, 8) + '...' : '')}
                        </Typography>
                      </Box>
                    )}
                  </Stack>
                </CardContent>
              </Card>
            </Grid>
          ))}
        </Grid>
      )}

      {/* Create Modal */}
      <Dialog
        open={showCreateModal}
        onClose={() => setShowCreateModal(false)}
        maxWidth="sm"
        fullWidth
        PaperProps={{ elevation: 8, sx: { borderRadius: 2 } }}
      >
        <DialogTitle>
          <Stack direction="row" justifyContent="space-between" alignItems="center">
            <Typography variant="h6" fontWeight={600}>
              Create/Edit Delegation
            </Typography>
            <IconButton onClick={() => setShowCreateModal(false)} size="small">
              <CancelIcon />
            </IconButton>
          </Stack>
        </DialogTitle>
        <DialogContent dividers>
          <Stack spacing={3} mt={1}>

            {/* Delegator Autocomplete */}
            <Autocomplete
                options={getUserOptions()}
                value={getDelegatorValue()}
                onChange={(_, newValue: { label: string; id: string; username?: string } | null) => {
                    setFormData({ ...formData, delegator_user_id: newValue ? newValue.id : '' });
                }}
                renderInput={(params: AutocompleteRenderInputParams) => (
                    <TextField {...params} label="Delegator User" required error={!formData.delegator_user_id} helperText={!formData.delegator_user_id ? "Required" : ""} />
                )}
            />

            {/* Delegate Autocomplete */}
            <Autocomplete
                options={getUserOptions()}
                value={getDelegateValue()}
                onChange={(_, newValue: { label: string; id: string; username?: string } | null) => {
                    setFormData({ ...formData, delegate_user_id: newValue ? newValue.id : '' });
                }}
                renderInput={(params: AutocompleteRenderInputParams) => (
                    <TextField {...params} label="Delegate User" required error={!formData.delegate_user_id} helperText={!formData.delegate_user_id ? "Required" : ""} />
                )}
            />

            <FormControl fullWidth required>
              <InputLabel>Delegation Type</InputLabel>
              <Select
                value={formData.delegation_type}
                label="Delegation Type"
                onChange={(e) => setFormData({ ...formData, delegation_type: e.target.value as any })}
              >
                <MenuItem value="full">Full Authority</MenuItem>
                <MenuItem value="partial">Specific Approval</MenuItem>
                <MenuItem value="backup">Backup Only</MenuItem>
              </Select>
            </FormControl>

            <Grid container spacing={2}>
              <Grid item xs={6}>
                <TextField
                  label="Start Date"
                  type="datetime-local"
                  fullWidth
                  required
                  InputLabelProps={{ shrink: true }}
                  value={formData.start_date}
                  onChange={(e) => setFormData({ ...formData, start_date: e.target.value })}
                  helperText="This field is required."
                  error={!formData.start_date}
                />
              </Grid>
              <Grid item xs={6}>
                <TextField
                  label="End Date"
                  type="datetime-local"
                  fullWidth
                  InputLabelProps={{ shrink: true }}
                  value={formData.end_date}
                  onChange={(e) => setFormData({ ...formData, end_date: e.target.value })}
                  placeholder="Optional"
                />
              </Grid>
            </Grid>

            <TextField
              label="Reason"
              fullWidth
              multiline
              rows={3}
              value={formData.reason}
              onChange={(e) => setFormData({ ...formData, reason: e.target.value })}
              placeholder="e.g., Vacation coverage, Backup approver"
            />

            {/* Conditional Fields for Specific Approval */}
            {formData.delegation_type === 'partial' && (
                <>
                    <FormControl fullWidth required>
                        <InputLabel>Resource Type</InputLabel>
                        <Select
                            value={formData.resource_type_selection}
                            label="Resource Type"
                            onChange={(e) => {
                                const selection = e.target.value;
                                setFormData({ 
                                    ...formData, 
                                    resource_type_selection: selection,
                                    resource_type: selection === 'Role' ? 'role' : '', // Clear or set default
                                    resource_id: '' // Reset ID when type changes
                                });
                            }}
                        >
                            <MenuItem value="Role">Role (Standard)</MenuItem>
                            <MenuItem value="Custom">Custom / Other</MenuItem>
                        </Select>
                    </FormControl>

                    {formData.resource_type_selection === 'Role' ? (
                        <Autocomplete
                            options={getRoleOptions()}
                            value={getRoleValue()}
                            onChange={(_, newValue: { label: string; id: string; key: string } | null) => {
                                setFormData({ ...formData, resource_id: newValue ? newValue.id : '' });
                            }}
                            renderInput={(params: AutocompleteRenderInputParams) => (
                                <TextField {...params} label="Select Role" required error={!formData.resource_id} helperText={!formData.resource_id ? "Required" : ""} />
                            )}
                        />
                    ) : (
                        <>
                            <TextField
                            label="Custom Resource Type"
                            fullWidth
                            required
                            value={formData.resource_type}
                            onChange={(e) => setFormData({ ...formData, resource_type: e.target.value })}
                            />
                            <TextField
                            label="Custom Resource ID"
                            fullWidth
                            required
                            value={formData.resource_id}
                            onChange={(e) => setFormData({ ...formData, resource_id: e.target.value })}
                            error={!formData.resource_id}
                            helperText={!formData.resource_id ? "Required" : ""}
                            />
                        </>
                    )}
                </>
            )}

          </Stack>
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 2 }}>
          <Button onClick={() => setShowCreateModal(false)} sx={{ textTransform: 'none' }}>
            Cancel
          </Button>
          <Button
            variant="contained"
            onClick={createDelegation}
            disabled={
                !formData.delegator_user_id || 
                !formData.delegate_user_id || 
                !formData.start_date || 
                (formData.delegation_type === 'partial' && (!formData.resource_id)) ||
                saving
            }
            sx={{ textTransform: 'none', fontWeight: 600 }}
          >
            {saving ? 'Creating...' : 'Create Delegation'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

/**
 * Field Permission Editor - Enterprise Field-Level Security
 * 
 * Features:
 * - Field-level access control configuration
 * - PII masking pattern management
 * - Role-to-field permission matrix
 * - Visual masking preview
 * - Compliance-ready security rules
 */

import React, { useState, useEffect, useMemo } from 'react';
import {
  Lock,
  Eye,
  EyeOff,
  Edit2,
  Shield,
  Save,
  X,
  Plus,
  Trash2,
  AlertTriangle,
  CheckCircle2,
  Search,
} from 'lucide-react';

// ============================================================================
// TYPE DEFINITIONS
// ============================================================================

interface FieldPermission {
  id: string;
  role_id: string;
  role_key: string;
  role_name: string;
  resource_type: string;
  field_name: string;
  permission_level: 'none' | 'read' | 'write' | 'mask';
}

interface MaskingRule {
  id: string;
  resource_type: string;
  field_name: string;
  masking_type: 'full' | 'partial' | 'hash' | 'tokenize';
  masking_pattern: string;
  unmasked_roles: string[];
}

interface Role {
  id: string;
  role_key: string;
  role_name: string;
  role_level: string;
}

interface FieldPermissionEditorProps {
  tenant: { id: string; display_name: string };
  datasource: { id: string; source_name: string };
}

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export const FieldPermissionEditor: React.FC<FieldPermissionEditorProps> = ({
  tenant,
  datasource,
}) => {
  const [roles, setRoles] = useState<Role[]>([]);
  const [fieldPermissions, setFieldPermissions] = useState<FieldPermission[]>([]);
  const [maskingRules, setMaskingRules] = useState<MaskingRule[]>([]);
  const [selectedRole, setSelectedRole] = useState<Role | null>(null);
  const [selectedResource, setSelectedResource] = useState<string>('process');
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);
  const [showMaskingModal, setShowMaskingModal] = useState(false);
  const [saving, setSaving] = useState(false);

  // Common sensitive fields
  const sensitiveFields = [
    { name: 'ssn', label: 'Social Security Number', category: 'PII' },
    { name: 'tax_id', label: 'Tax ID', category: 'PII' },
    { name: 'bank_account', label: 'Bank Account', category: 'Financial' },
    { name: 'credit_card', label: 'Credit Card', category: 'Financial' },
    { name: 'email', label: 'Email Address', category: 'PII' },
    { name: 'phone', label: 'Phone Number', category: 'PII' },
    { name: 'salary', label: 'Salary', category: 'Financial' },
    { name: 'account_balance', label: 'Account Balance', category: 'Financial' },
  ];

  // Masking form state
  const [maskingForm, setMaskingForm] = useState({
    resource_type: 'process',
    field_name: '',
    masking_type: 'partial' as 'full' | 'partial' | 'hash' | 'tokenize',
    masking_pattern: '',
    unmasked_roles: [] as string[],
  });

  // Fetch roles
  const fetchRoles = async () => {
    try {
      const response = await fetch(
        `/api/rbac/roles?tenant_id=${tenant.id}&datasource_id=${datasource.id}`
      );
      const data = await response.json();
      setRoles(data || []);
    } catch (error) {
      console.error('Failed to fetch roles:', error);
    }
  };

  // Fetch field permissions
  const fetchFieldPermissions = async () => {
    try {
      setLoading(true);
      const response = await fetch(
        `/api/rbac/field-permissions?tenant_id=${tenant.id}&datasource_id=${datasource.id}`
      );
      const data = await response.json();
      setFieldPermissions(data || []);
    } catch (error) {
      console.error('Failed to fetch field permissions:', error);
    } finally {
      setLoading(false);
    }
  };

  // Set field permission
  const setFieldPermission = async (
    roleId: string,
    fieldName: string,
    level: 'none' | 'read' | 'write' | 'mask'
  ) => {
    try {
      setSaving(true);
      await fetch(`/api/rbac/field-permissions`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          tenant_id: tenant.id,
          datasource_id: datasource.id,
          role_id: roleId,
          resource_type: selectedResource,
          field_name: fieldName,
          permission_level: level,
        }),
      });
      await fetchFieldPermissions();
    } catch (error) {
      console.error('Failed to set field permission:', error);
    } finally {
      setSaving(false);
    }
  };

  // Create masking rule
  const createMaskingRule = async () => {
    try {
      setSaving(true);
      await fetch(`/api/rbac/field-masking-rules`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...maskingForm,
          tenant_id: tenant.id,
          datasource_id: datasource.id,
        }),
      });
      await fetchFieldPermissions();
      setShowMaskingModal(false);
      resetMaskingForm();
    } catch (error) {
      console.error('Failed to create masking rule:', error);
    } finally {
      setSaving(false);
    }
  };

  // Reset masking form
  const resetMaskingForm = () => {
    setMaskingForm({
      resource_type: 'process',
      field_name: '',
      masking_type: 'partial',
      masking_pattern: '',
      unmasked_roles: [],
    });
  };

  // Get permission for role and field
  const getPermission = (roleId: string, fieldName: string): 'none' | 'read' | 'write' | 'mask' => {
    const perm = fieldPermissions.find(
      p => p.role_id === roleId && p.field_name === fieldName && p.resource_type === selectedResource
    );
    return perm?.permission_level || 'none';
  };

  // Filter fields by search
  const filteredFields = useMemo(() => {
    return sensitiveFields.filter(field =>
      field.label.toLowerCase().includes(searchTerm.toLowerCase()) ||
      field.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      field.category.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [searchTerm]);

  useEffect(() => {
    fetchRoles();
    fetchFieldPermissions();
  }, [tenant.id]);

  const getPermissionColor = (level: string) => {
    const colors = {
      none: 'bg-red-100 text-red-700 border-red-300',
      read: 'bg-green-100 text-green-700 border-green-300',
      write: 'bg-blue-100 text-blue-700 border-blue-300',
      mask: 'bg-yellow-100 text-yellow-700 border-yellow-300',
    };
    return colors[level as keyof typeof colors] || 'bg-gray-100 text-gray-700 border-gray-300';
  };

  const getPermissionIcon = (level: string) => {
    const icons = {
      none: <EyeOff className="w-4 h-4" />,
      read: <Eye className="w-4 h-4" />,
      write: <Edit2 className="w-4 h-4" />,
      mask: <Lock className="w-4 h-4" />,
    };
    return icons[level as keyof typeof icons] || <EyeOff className="w-4 h-4" />;
  };

  const maskingPatterns = {
    ssn: 'XXX-XX-####',
    tax_id: 'XX-XXXXXXX',
    bank_account: 'XXXX-####',
    credit_card: 'XXXX-XXXX-XXXX-####',
    email: 'X***@domain.com',
    phone: '(XXX) XXX-####',
  };

  const getExampleMasked = (fieldName: string, pattern: string) => {
    const examples = {
      ssn: { original: '123-45-6789', masked: 'XXX-XX-6789' },
      tax_id: { original: '12-3456789', masked: 'XX-XXXXXX9' },
      bank_account: { original: '1234-5678', masked: 'XXXX-5678' },
      credit_card: { original: '1234-5678-9012-3456', masked: 'XXXX-XXXX-XXXX-3456' },
      email: { original: 'john.doe@example.com', masked: 'j***@example.com' },
      phone: { original: '(555) 123-4567', masked: '(XXX) XXX-4567' },
    };
    return examples[fieldName as keyof typeof examples] || { original: 'Sample', masked: 'XXXX' };
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="flex flex-col items-center gap-4">
          <Shield className="w-12 h-12 animate-pulse text-blue-500" />
          <p className="text-gray-600">Loading field permissions...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 p-6">
      {/* Header */}
      <div className="mb-8">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-gray-900 flex items-center gap-3">
              <Lock className="w-8 h-8 text-blue-600" />
              Field Permission Editor
            </h1>
            <p className="text-gray-600 mt-2">
              Configure field-level security and masking rules for {tenant.display_name}
            </p>
          </div>
          <button
            onClick={() => {
              resetMaskingForm();
              setShowMaskingModal(true);
            }}
            className="px-6 py-3 bg-purple-600 text-white rounded-lg font-medium hover:bg-purple-700 transition-all flex items-center gap-2 shadow-lg"
          >
            <Plus className="w-5 h-5" />
            Add Masking Rule
          </button>
        </div>

        {/* Resource Type & Search */}
        <div className="flex gap-4 mt-6">
          <select
            value={selectedResource}
            onChange={(e) => setSelectedResource(e.target.value)}
            className="px-4 py-3 border-2 border-gray-200 rounded-lg focus:outline-none focus:border-blue-500 bg-white"
          >
            <option value="process">Process</option>
            <option value="step">Step</option>
            <option value="document">Document</option>
          </select>
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input
              type="text"
              placeholder="Search fields..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-3 border-2 border-gray-200 rounded-lg focus:outline-none focus:border-blue-500"
            />
          </div>
        </div>
      </div>

      {/* Permission Matrix */}
      <div className="bg-white rounded-2xl shadow-xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full">
            <thead className="bg-gray-100">
              <tr>
                <th className="text-left py-4 px-6 font-bold text-gray-700 sticky left-0 bg-gray-100 z-10">
                  Field Name
                </th>
                <th className="text-left py-4 px-6 font-bold text-gray-700">Category</th>
                {roles.map(role => (
                  <th key={role.id} className="text-center py-4 px-4 font-bold text-gray-700 min-w-[150px]">
                    <div className="flex flex-col items-center gap-1">
                      <span>{role.role_name}</span>
                      <span className="text-xs text-gray-500 font-normal">{role.role_level}</span>
                    </div>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {filteredFields.map((field, idx) => (
                <tr key={field.name} className={idx % 2 === 0 ? 'bg-white' : 'bg-gray-50'}>
                  <td className="py-4 px-6 font-medium text-gray-900 sticky left-0 bg-inherit z-10">
                    <div>
                      <div className="font-bold">{field.label}</div>
                      <div className="text-xs text-gray-500">{field.name}</div>
                    </div>
                  </td>
                  <td className="py-4 px-6">
                    <span className={`px-3 py-1 rounded-full text-xs font-bold ${
                      field.category === 'PII'
                        ? 'bg-purple-100 text-purple-700 border border-purple-300'
                        : 'bg-green-100 text-green-700 border border-green-300'
                    }`}>
                      {field.category}
                    </span>
                  </td>
                  {roles.map(role => {
                    const currentLevel = getPermission(role.id, field.name);
                    return (
                      <td key={role.id} className="py-4 px-4">
                        <div className="flex flex-col gap-1">
                          {(['none', 'read', 'write', 'mask'] as const).map(level => (
                            <button
                              key={level}
                              onClick={() => setFieldPermission(role.id, field.name, level)}
                              disabled={saving}
                              className={`px-3 py-2 rounded-lg text-xs font-bold border-2 transition-all flex items-center justify-center gap-2 ${
                                currentLevel === level
                                  ? getPermissionColor(level)
                                  : 'bg-white text-gray-400 border-gray-200 hover:border-gray-300'
                              }`}
                            >
                              {getPermissionIcon(level)}
                              {level.toUpperCase()}
                            </button>
                          ))}
                        </div>
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Legend */}
      <div className="mt-6 bg-white rounded-2xl shadow-xl p-6">
        <h3 className="text-lg font-bold text-gray-900 mb-4">Permission Levels</h3>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <div className="flex items-center gap-3">
            <div className={`px-4 py-2 rounded-lg border-2 ${getPermissionColor('none')}`}>
              {getPermissionIcon('none')}
            </div>
            <div>
              <div className="font-medium text-gray-900">None</div>
              <div className="text-xs text-gray-600">No access (hidden)</div>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <div className={`px-4 py-2 rounded-lg border-2 ${getPermissionColor('read')}`}>
              {getPermissionIcon('read')}
            </div>
            <div>
              <div className="font-medium text-gray-900">Read</div>
              <div className="text-xs text-gray-600">Full visibility</div>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <div className={`px-4 py-2 rounded-lg border-2 ${getPermissionColor('write')}`}>
              {getPermissionIcon('write')}
            </div>
            <div>
              <div className="font-medium text-gray-900">Write</div>
              <div className="text-xs text-gray-600">Full access</div>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <div className={`px-4 py-2 rounded-lg border-2 ${getPermissionColor('mask')}`}>
              {getPermissionIcon('mask')}
            </div>
            <div>
              <div className="font-medium text-gray-900">Mask</div>
              <div className="text-xs text-gray-600">Partial visibility</div>
            </div>
          </div>
        </div>
      </div>

      {/* Masking Modal */}
      {showMaskingModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
            <div className="p-6 border-b-2 border-gray-200">
              <div className="flex items-center justify-between">
                <h3 className="text-2xl font-bold text-gray-900">Add Masking Rule</h3>
                <button
                  onClick={() => setShowMaskingModal(false)}
                  className="p-2 hover:bg-gray-100 rounded-lg transition-all"
                >
                  <X className="w-6 h-6 text-gray-600" />
                </button>
              </div>
            </div>

            <div className="p-6 space-y-6">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Field Name *
                </label>
                <select
                  value={maskingForm.field_name}
                  onChange={(e) => {
                    const fieldName = e.target.value;
                    setMaskingForm({
                      ...maskingForm,
                      field_name: fieldName,
                      masking_pattern: maskingPatterns[fieldName as keyof typeof maskingPatterns] || '',
                    });
                  }}
                  className="w-full p-3 border-2 border-gray-200 rounded-lg focus:outline-none focus:border-blue-500"
                >
                  <option value="">Select a field</option>
                  {sensitiveFields.map(field => (
                    <option key={field.name} value={field.name}>
                      {field.label} ({field.name})
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Masking Type *
                </label>
                <select
                  value={maskingForm.masking_type}
                  onChange={(e) =>
                    setMaskingForm({
                      ...maskingForm,
                      masking_type: e.target.value as 'full' | 'partial' | 'hash' | 'tokenize',
                    })
                  }
                  className="w-full p-3 border-2 border-gray-200 rounded-lg focus:outline-none focus:border-blue-500"
                >
                  <option value="full">Full Masking (****)</option>
                  <option value="partial">Partial Masking (XXX-XX-1234)</option>
                  <option value="hash">Hash (SHA-256)</option>
                  <option value="tokenize">Tokenize (Replace with token)</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Masking Pattern *
                </label>
                <input
                  type="text"
                  value={maskingForm.masking_pattern}
                  onChange={(e) =>
                    setMaskingForm({ ...maskingForm, masking_pattern: e.target.value })
                  }
                  className="w-full p-3 border-2 border-gray-200 rounded-lg focus:outline-none focus:border-blue-500"
                  placeholder="e.g., XXX-XX-####"
                />
                <p className="text-xs text-gray-500 mt-2">
                  Use X for masked characters, # for visible characters from the end
                </p>
              </div>

              {/* Preview */}
              {maskingForm.field_name && maskingForm.masking_pattern && (
                <div className="p-4 bg-blue-50 border-2 border-blue-200 rounded-xl">
                  <h4 className="font-bold text-gray-900 mb-3">Masking Preview</h4>
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="text-sm text-gray-600">Original</p>
                      <p className="font-mono text-lg text-gray-900">
                        {getExampleMasked(maskingForm.field_name, maskingForm.masking_pattern).original}
                      </p>
                    </div>
                    <div className="text-2xl text-gray-400">→</div>
                    <div>
                      <p className="text-sm text-gray-600">Masked</p>
                      <p className="font-mono text-lg font-bold text-blue-600">
                        {maskingForm.masking_pattern}
                      </p>
                    </div>
                  </div>
                </div>
              )}

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Unmasked Roles (Full Access)
                </label>
                <div className="space-y-2 max-h-48 overflow-y-auto border-2 border-gray-200 rounded-lg p-4">
                  {roles.map(role => (
                    <label key={role.id} className="flex items-center gap-3 cursor-pointer">
                      <input
                        type="checkbox"
                        checked={maskingForm.unmasked_roles.includes(role.id)}
                        onChange={(e) => {
                          if (e.target.checked) {
                            setMaskingForm({
                              ...maskingForm,
                              unmasked_roles: [...maskingForm.unmasked_roles, role.id],
                            });
                          } else {
                            setMaskingForm({
                              ...maskingForm,
                              unmasked_roles: maskingForm.unmasked_roles.filter(id => id !== role.id),
                            });
                          }
                        }}
                        className="w-5 h-5 text-blue-600 border-2 border-gray-300 rounded"
                      />
                      <span className="font-medium text-gray-900">{role.role_name}</span>
                      <span className="text-xs text-gray-500">({role.role_level})</span>
                    </label>
                  ))}
                </div>
              </div>
            </div>

            <div className="p-6 border-t-2 border-gray-200 flex justify-end gap-3">
              <button
                onClick={() => setShowMaskingModal(false)}
                className="px-6 py-3 bg-gray-100 text-gray-700 rounded-lg font-medium hover:bg-gray-200 transition-all"
              >
                Cancel
              </button>
              <button
                onClick={createMaskingRule}
                disabled={!maskingForm.field_name || !maskingForm.masking_pattern || saving}
                className="px-6 py-3 bg-purple-600 text-white rounded-lg font-medium hover:bg-purple-700 transition-all flex items-center gap-2 disabled:opacity-50"
              >
                <Save className="w-5 h-5" />
                {saving ? 'Saving...' : 'Save Rule'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

