// ============================================================================
// TYPE DEFINITIONS
// ============================================================================

interface Role {
  id: string;
  role_key: string;
  role_name: string;
  description: string;
  role_type: 'system' | 'custom';
  role_level: 'viewer' | 'editor' | 'approver' | 'admin' | 'super_admin';
  is_active: boolean;
  created_at: string;
  updated_at: string;
  permission_count?: number;
  user_count?: number;
}

interface Permission {
  id: string;
  permission_key: string;
  permission_name: string;
  description: string;
  resource_type: string;
  action: string;
  is_system: boolean;
}

interface RoleManagerProps {
  tenant: { id: string; display_name: string };
  datasource: { id: string; source_name: string };
}

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export const RoleManager: React.FC<RoleManagerProps> = ({ tenant, datasource }) => {
  const [roles, setRoles] = useState<Role[]>([]);
  const [permissions, setPermissions] = useState<Permission[]>([]);
  const [selectedRole, setSelectedRole] = useState<Role | null>(null);
  const [rolePermissions, setRolePermissions] = useState<Set<string>>(new Set());
  const [isCreating, setIsCreating] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterLevel, setFilterLevel] = useState<string>('all');
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('table');

  // Role Details Dialog State
  const [detailsOpen, setDetailsOpen] = useState(false);
  const [activeTab, setActiveTab] = useState(0);
  const [roleUsers, setRoleUsers] = useState<any[]>([]);
  const [roleFieldPerms, setRoleFieldPerms] = useState<any[]>([]);

  // Form state for role editing

  // Form state for role editing
  const [formData, setFormData] = useState({
    role_key: '',
    role_name: '',
    description: '',
    role_level: 'viewer' as Role['role_level'],
  });

  // Fetch roles
  const fetchRoles = async () => {
    try {
      setLoading(true);
      const response = await fetch(
        `/api/rbac/roles?tenant_id=${tenant.id}&datasource_id=${datasource.id}`
      );
      const data = await response.json();
      setRoles(data || [
        {
          id: '1',
          role_key: 'administrator',
          role_name: 'Administrator',
          description: 'Full access to all features and data.',
          role_type: 'system',
          role_level: 'admin',
          is_active: true,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        },
        {
          id: '2',
          role_key: 'manager',
          role_name: 'Manager',
          description: 'Manage users, roles, and basic settings.',
          role_type: 'system',
          role_level: 'editor',
          is_active: true,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        },
        {
          id: '3',
          role_key: 'editor',
          role_name: 'Editor',
          description: 'Create and edit content within assigned teams.',
          role_type: 'system',
          role_level: 'editor',
          is_active: true,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        },
        {
          id: '4',
          role_key: 'viewer',
          role_name: 'Viewer',
          description: 'View project details and progress.',
          role_type: 'system',
          role_level: 'viewer',
          is_active: true,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        },
      ]);
    } catch (error) {
      console.error('Failed to fetch roles:', error);
    } finally {
      setLoading(false);
    }
  };

  // Fetch permissions
  const fetchPermissions = async () => {
    try {
      const response = await fetch(`/api/rbac/permissions?tenant_id=${tenant.id}`);
      const data = await response.json();
      setPermissions(data || [
        { id: '1', permission_key: 'view_dashboard', permission_name: 'View Dashboard', description: '', resource_type: 'dashboard', action: 'view', is_system: true },
        { id: '2', permission_key: 'manage_users', permission_name: 'Manage Users', description: '', resource_type: 'users', action: 'manage', is_system: true },
        { id: '3', permission_key: 'edit_settings', permission_name: 'Edit Settings', description: '', resource_type: 'settings', action: 'edit', is_system: true },
        { id: '4', permission_key: 'create_reports', permission_name: 'Create Reports', description: '', resource_type: 'reports', action: 'create', is_system: true },
        { id: '5', permission_key: 'export_data', permission_name: 'Export Data', description: '', resource_type: 'data', action: 'export', is_system: true },
      ]);
    } catch (error) {
      console.error('Failed to fetch permissions:', error);
    }
  };

  // Create role
  const createRole = async () => {
    try {
      setSaving(true);
      const response = await fetch(
        `/api/rbac/roles?tenant_id=${tenant.id}&datasource_id=${datasource.id}`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            ...formData,
            permissions: Array.from(rolePermissions),
          }),
        }
      );

      if (response.ok) {
        await fetchRoles();
        resetForm();
      }
    } catch (error) {
      console.error('Failed to create role:', error);
    } finally {
      setSaving(false);
    }
  };

  // Delete role
  const deleteRole = async (roleId: string) => {
    if (!confirm('Are you sure you want to delete this role?')) return;

    try {
      await fetch(`/api/rbac/roles/${roleId}`, { method: 'DELETE' });
      await fetchRoles();
    } catch (error) {
      console.error('Failed to delete role:', error);
    }
  };

  // Reset form
  const resetForm = () => {
    setFormData({
      role_key: '',
      role_name: '',
      description: '',
      role_level: 'viewer',
    });
    setRolePermissions(new Set());
    setIsCreating(false);
  };

  // Toggle permission
  const togglePermission = (permId: string) => {
    const newPerms = new Set(rolePermissions);
    if (newPerms.has(permId)) {
      newPerms.delete(permId);
    } else {
      newPerms.add(permId);
    }
    setRolePermissions(newPerms);
  };

  // View role details
  const handleViewRole = (role: Role) => {
    setSelectedRole(role);
    setRoleUsers([]); // Placeholder - would fetch real users
    setRoleFieldPerms([]); // Placeholder - would fetch real permissions
    setDetailsOpen(true);
  };

  // Filter roles
  const filteredRoles = useMemo(() => {
    return roles.filter(role => {
      const matchesSearch = role.role_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          role.role_key.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesLevel = filterLevel === 'all' || role.role_level === filterLevel;
      return matchesSearch && matchesLevel;
    });
  }, [roles, searchTerm, filterLevel]);

  useEffect(() => {
    fetchRoles();
    fetchPermissions();
  }, [tenant.id]);

  if (loading) {
    return (
      <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', minHeight: '100vh', bgcolor: '#fafafa' }}>
        <Typography>Loading roles...</Typography>
      </Box>
    );
  }

  return (
    <Box sx={{ minHeight: '100vh', bgcolor: '#fafafa' }}>
      {/* Header */}
      <AppBar position="static" color="default" elevation={0} sx={{ bgcolor: 'white', borderBottom: '1px solid #e0e0e0' }}>
        <Toolbar>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mr: 4 }}>
            <Box sx={{ width: 24, height: 24, bgcolor: 'black', borderRadius: 0.5 }} />
            <Typography variant="h6" sx={{ fontWeight: 600 }}>
              Role Manager
            </Typography>
          </Box>
          <Box sx={{ display: 'flex', gap: 3, flexGrow: 1 }}>
            <Button color="inherit" sx={{ textTransform: 'none' }}>Dashboard</Button>
            <Button color="inherit" sx={{ textTransform: 'none', fontWeight: 600 }}>Roles</Button>
            <Button color="inherit" sx={{ textTransform: 'none' }}>Users</Button>
            <Button color="inherit" sx={{ textTransform: 'none' }}>Permissions</Button>
          </Box>
          <TextField
            size="small"
            placeholder="Search"
            sx={{ width: 250, mr: 2 }}
            InputProps={{
              endAdornment: (
                <InputAdornment position="end">
                  <SearchIcon sx={{ fontSize: 14 }} />
                </InputAdornment>
              ),
            }}
          />
          <Avatar sx={{ width: 40, height: 40, bgcolor: '#bdbdbd' }} />
        </Toolbar>
      </AppBar>

      {/* Main Content */}
      <Container maxWidth="lg" sx={{ py: 4 }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
          <Typography variant="h4" sx={{ fontWeight: 700 }}>
            Roles
          </Typography>
          <Button
            variant="contained"
            onClick={() => setIsCreating(true)}
            sx={{
              bgcolor: '#f5f5f5',
              color: 'text.primary',
              textTransform: 'none',
              boxShadow: 'none',
              '&:hover': { bgcolor: '#eeeeee', boxShadow: 'none' },
            }}
          >
            Create Role
          </Button>
        </Box>

        {/* Search and Filter */}
        <Paper sx={{ p: 2, mb: 3, boxShadow: 'none', border: '1px solid #e0e0e0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Box display="flex" gap={2} flexGrow={1}>
            <Autocomplete
                freeSolo
                options={roles.map(r => r.role_name)}
                value={searchTerm}
                onInputChange={(_, newValue) => setSearchTerm(newValue || '')}
                renderInput={(params) => (
                    <TextField
                        {...params}
                        size="small"
                        placeholder="Search roles"
                        InputProps={{
                        ...params.InputProps,
                        startAdornment: (
                            <InputAdornment position="start">
                            <SearchIcon sx={{ fontSize: 14 }} />
                            </InputAdornment>
                        ),
                        }}
                    />
                )}
                sx={{ width: 300 }}
            />
            <Button
                variant="outlined"
                size="small"
                endIcon={<ExpandMoreIcon />}
                sx={{ textTransform: 'none' }}
            >
                Level
            </Button>
          </Box>
           <ToggleButtonGroup
              value={viewMode}
              exclusive
              onChange={(_, value) => value && setViewMode(value)}
              size="small"
            >
              <ToggleButton value="table" aria-label="table view">
                <ViewListIcon fontSize="small" />
              </ToggleButton>
              <ToggleButton value="grid" aria-label="grid view">
                <ViewModuleIcon fontSize="small" />
              </ToggleButton>
            </ToggleButtonGroup>
        </Paper>

        {/* Roles Content */}
        {viewMode === 'table' ? (
            <TableContainer component={Paper} sx={{ boxShadow: 'none', border: '1px solid #e0e0e0' }}>
            <Table>
                <TableHead sx={{ bgcolor: '#fafafa' }}>
                <TableRow>
                    <TableCell sx={{ fontWeight: 600 }}>Role Name</TableCell>
                    <TableCell sx={{ fontWeight: 600 }}>Level</TableCell>
                    <TableCell sx={{ fontWeight: 600 }}>Description</TableCell>
                    <TableCell sx={{ fontWeight: 600 }}>Actions</TableCell>
                </TableRow>
                </TableHead>
                <TableBody>
                {filteredRoles.map((role) => (
                    <TableRow key={role.id} hover>
                    <TableCell sx={{ fontWeight: 500 }}>{role.role_name}</TableCell>
                    <TableCell>
                        <Chip label={role.role_level} size="small" color="primary" variant="outlined" />
                    </TableCell>
                    <TableCell sx={{ color: 'text.secondary' }}>{role.description}</TableCell>
                    <TableCell>
                        <Box sx={{ display: 'flex', gap: 1 }}>
                        <Button
                            size="small"
                            startIcon={<EyeIcon fontSize="small" />}
                            sx={{ textTransform: 'none', minWidth: 'auto' }}
                            onClick={() => handleViewRole(role)}
                        >
                            Eye
                        </Button>
                        <Button
                            size="small"
                            startIcon={<EditIcon fontSize="small" />}
                            sx={{ textTransform: 'none', minWidth: 'auto' }}
                        >
                            Pencil
                        </Button>
                        <Button
                            size="small"
                            startIcon={<DeleteIcon fontSize="small" />}
                            onClick={() => deleteRole(role.id)}
                            sx={{ textTransform: 'none', minWidth: 'auto' }}
                        >
                            Trash
                        </Button>
                        </Box>
                    </TableCell>
                    </TableRow>
                ))}
                </TableBody>
            </Table>
            </TableContainer>
        ) : (
            <Grid container spacing={3}>
                {filteredRoles.map((role) => (
                    <Grid item xs={12} sm={6} md={4} key={role.id}>
                         <Card elevation={0} sx={{ border: '1px solid #e0e0e0', borderRadius: 2, height: '100%', display: 'flex', flexDirection: 'column' }}>
                            <CardContent sx={{ flexGrow: 1 }}>
                                <Box display="flex" justifyContent="space-between" alignItems="flex-start" mb={2}>
                                    <Typography variant="h6" fontWeight={600}>
                                        {role.role_name}
                                    </Typography>
                                    <Chip label={role.role_level} size="small" color="primary" variant="outlined" />
                                </Box>
                                <Typography variant="body2" color="text.secondary" sx={{ mb: 2, minHeight: 40 }}>
                                    {role.description || 'No description provided.'}
                                </Typography>
                                 <Typography variant="caption" color="text.secondary" display="block">
                                    Key: {role.role_key}
                                </Typography>
                            </CardContent>
                            <CardActions sx={{ px: 2, pb: 2, pt: 0, justifyContent: 'flex-end' }}>
                                 <Button
                                    size="small"
                                    startIcon={<EyeIcon />}
                                    sx={{ textTransform: 'none' }}
                                    onClick={() => handleViewRole(role)}
                                >
                                    Details
                                </Button>
                                <Button
                                    size="small"
                                    startIcon={<EditIcon />}
                                    sx={{ textTransform: 'none' }}
                                >
                                    Edit
                                </Button>
                                <Button
                                    size="small"
                                    startIcon={<DeleteIcon />}
                                    onClick={() => deleteRole(role.id)}
                                    color="error"
                                    sx={{ textTransform: 'none' }}
                                >
                                    Delete
                                </Button>
                            </CardActions>
                         </Card>
                    </Grid>
                ))}
            </Grid>
        )}
      </Container>

      {/* Create Role Dialog */}
      <Dialog open={isCreating} onClose={resetForm} maxWidth="sm" fullWidth>
        <DialogTitle sx={{ fontWeight: 700, fontSize: '1.5rem' }}>Create Role</DialogTitle>
        <DialogContent>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2.5, pt: 2 }}>
            <TextField
              fullWidth
              label="Role Key"
              placeholder="Enter role key"
              value={formData.role_key}
              onChange={(e) => setFormData({ ...formData, role_key: e.target.value })}
            />
            <TextField
              fullWidth
              label="Role Name"
              placeholder="Enter role name"
              value={formData.role_name}
              onChange={(e) => setFormData({ ...formData, role_name: e.target.value })}
            />
            <TextField
              fullWidth
              label="Description"
              placeholder="Enter role description"
              multiline
              rows={3}
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            />
            <FormControl fullWidth>
              <InputLabel>Role Level</InputLabel>
              <Select
                value={formData.role_level}
                label="Role Level"
                onChange={(e) => setFormData({ ...formData, role_level: e.target.value as any })}
              >
                <MenuItem value="viewer">Viewer</MenuItem>
                <MenuItem value="editor">Editor</MenuItem>
                <MenuItem value="approver">Approver</MenuItem>
                <MenuItem value="admin">Admin</MenuItem>
              </Select>
            </FormControl>
            <Box>
              <Typography variant="subtitle2" sx={{ mb: 1, fontWeight: 600 }}>
                Permissions
              </Typography>
              <FormGroup>
                {permissions.map((perm) => (
                  <FormControlLabel
                    key={perm.id}
                    control={
                      <Checkbox
                        checked={rolePermissions.has(perm.id)}
                        onChange={() => togglePermission(perm.id)}
                      />
                    }
                    label={perm.permission_name}
                  />
                ))}
              </FormGroup>
            </Box>
          </Box>
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 3 }}>
          <Button onClick={resetForm} sx={{ textTransform: 'none' }}>
            Cancel
          </Button>
          <Button
            onClick={createRole}
            variant="contained"
            disabled={saving}
            sx={{ textTransform: 'none' }}
          >
            {saving ? 'Saving...' : 'Save'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Role Details Dialog */}
      <Dialog open={detailsOpen} onClose={() => setDetailsOpen(false)} maxWidth="md" fullWidth>
        <DialogTitle sx={{ display: 'flex', alignItems: 'center', gap: 2, pb: 0 }}>
            <Box>
                <Typography variant="h6" fontWeight={700}>{selectedRole?.role_name || 'Role Details'}</Typography>
                <Typography variant="caption" color="text.secondary">{selectedRole?.role_key}</Typography>
            </Box>
            {selectedRole && <Chip label={selectedRole.role_level} size="small" color="primary" variant="outlined" sx={{ ml: 'auto' }} />}
        </DialogTitle>
        <DialogContent sx={{ p: 0 }}>
            <Box sx={{ borderBottom: 1, borderColor: 'divider', px: 3 }}>
                <Tabs value={activeTab} onChange={(_, v) => setActiveTab(v)}>
                    <Tab label="Overview" />
                    <Tab label={`Users (${roleUsers.length})`} />
                    <Tab label={`Field Permissions (${roleFieldPerms.length})`} />
                </Tabs>
            </Box>

            {/* Overview Tab */}
            {activeTab === 0 && (
                <Box p={3}>
                    <Typography variant="subtitle2" gutterBottom>Description</Typography>
                    <Typography variant="body2" color="text.secondary" paragraph>
                        {selectedRole?.description || 'No description provided.'}
                    </Typography>
                    <Grid container spacing={2} mt={1}>
                        <Grid item xs={6}>
                            <Paper variant="outlined" sx={{ p: 2, textAlign: 'center' }}>
                                <Typography variant="h4" color="primary">{roleUsers.length}</Typography>
                                <Typography variant="caption" color="text.secondary">Assigned Users</Typography>
                            </Paper>
                        </Grid>
                        <Grid item xs={6}>
                            <Paper variant="outlined" sx={{ p: 2, textAlign: 'center' }}>
                                <Typography variant="h4" color="secondary">{roleFieldPerms.length}</Typography>
                                <Typography variant="caption" color="text.secondary">Field Policies</Typography>
                            </Paper>
                        </Grid>
                    </Grid>
                </Box>
            )}

            {/* Users Tab */}
            {activeTab === 1 && (
                <List sx={{ p: 0 }}>
                    {roleUsers.length === 0 ? (
                        <Box p={3} textAlign="center"><Typography color="text.secondary">No users assigned to this role.</Typography></Box>
                    ) : (
                        roleUsers.map((user, i) => (
                            <React.Fragment key={user.id}>
                                {i > 0 && <Divider />}
                                <ListItem>
                                    <ListItemAvatar>
                                        <Avatar>{user.username?.charAt(0).toUpperCase()}</Avatar>
                                    </ListItemAvatar>
                                    <ListItemText 
                                        primary={user.name || user.username} 
                                        secondary={user.email} 
                                    />
                                    <Typography variant="caption" color="text.secondary">
                                        Assigned: {new Date(user.assigned_at).toLocaleDateString()}
                                    </Typography>
                                </ListItem>
                            </React.Fragment>
                        ))
                    )}
                </List>
            )}

            {/* Field Permissions Tab */}
            {activeTab === 2 && (
                <TableContainer sx={{ maxHeight: 400 }}>
                    <Table stickyHeader size="small">
                        <TableHead>
                            <TableRow>
                                <TableCell>Field</TableCell>
                                <TableCell>Resource/Context</TableCell>
                                <TableCell>Permission</TableCell>
                            </TableRow>
                        </TableHead>
                        <TableBody>
                            {roleFieldPerms.length === 0 ? (
                                <TableRow><TableCell colSpan={3} align="center">No field permissions configured.</TableCell></TableRow>
                            ) : (
                                roleFieldPerms.map((fp) => (
                                    <TableRow key={fp.id} hover>
                                        <TableCell sx={{ fontWeight: 500 }}>{fp.field_name}</TableCell>
                                        <TableCell>{fp.resource_type}</TableCell>
                                        <TableCell>
                                            <Chip 
                                                label={fp.permission_level} 
                                                size="small" 
                                                color={fp.permission_level === 'write' ? 'success' : fp.permission_level === 'read' ? 'info' : 'warning'} 
                                                variant="outlined"
                                                sx={{ minWidth: 60, height: 20, fontSize: '0.7rem' }}
                                            />
                                        </TableCell>
                                    </TableRow>
                                ))
                            )}
                        </TableBody>
                    </Table>
                </TableContainer>
            )}
        </DialogContent>
        <DialogActions>
            <Button onClick={() => setDetailsOpen(false)}>Close</Button>
            <Button variant="contained" onClick={() => { setDetailsOpen(false); setIsCreating(true); /* TODO Edit logic */ }}>Edit Role</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

/**
 * Role Manager - Enterprise Role & Permission Configuration
 * 
 * Professional RBAC interface featuring Material Design 3:
 * - Material elevation and shadows
 * - Material typography scale
 * - Material icons and buttons
 * - Proper 8px grid spacing
 */

import React, { useState, useEffect, useMemo } from 'react';
import {
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  IconButton,
  InputAdornment,
  MenuItem,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Tooltip,
  Typography,
  AppBar,
  Toolbar,
} from '@mui/material';
import {
  Search as SearchIcon,
  Add as AddIcon,
  Visibility as ViewIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  Security as SecurityIcon,
  FilterList as FilterIcon,
  PersonAdd as PersonAddIcon,
} from '@mui/icons-material';

import {
  Avatar,
  Divider,
  Grid,
  List,
  ListItem,
  ListItemAvatar,
  ListItemText,
  Tab,
  Tabs,
} from '@mui/material';

// ============================================================================
// TYPE DEFINITIONS
// ============================================================================

interface Role {
  id: string;
  role_key: string;
  role_name: string;
  description: string;
  role_type: 'system' | 'custom';
  role_level: 'viewer' | 'editor' | 'approver' | 'admin' | 'super_admin';
  is_active: boolean;
  created_at: string;
  updated_at: string;
  permission_count?: number;
  user_count?: number;
}

interface Permission {
  id: string;
  permission_key: string;
  permission_name: string;
  description: string;
  resource_type: string;
  action: string;
  is_system: boolean;
}

interface RoleManagerProps {
  tenant: { id: string; display_name: string };
  datasource: { id: string; source_name: string };
}

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export const RoleManagerStyled: React.FC<RoleManagerProps> = ({ tenant, datasource }) => {
  const [roles, setRoles] = useState<Role[]>([]);
  const [_permissions, setPermissions] = useState<Permission[]>([]);
  const [selectedRole, setSelectedRole] = useState<Role | null>(null);
  const [rolePermissions, setRolePermissions] = useState<Set<string>>(new Set());
  const [_isEditing, setIsEditing] = useState(false);
  const [_isCreating, setIsCreating] = useState(false);
  const [isViewing, setIsViewing] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterLevel, _setFilterLevel] = useState<string>('all');
  const [loading, setLoading] = useState(true);
  const [_saving, setSaving] = useState(false);
  const [_expandedGroups, _setExpandedGroups] = useState<Set<string>>(new Set(['process', 'step']));

  // Role Details State
  const [activeTab, setActiveTab] = useState(0);
  const [roleUsers, setRoleUsers] = useState<any[]>([]);
  const [roleFieldPerms, setRoleFieldPerms] = useState<any[]>([]);

  // Form state for role editing
  const [formData, setFormData] = useState({
    role_key: '',
    role_name: '',
    description: '',
    role_level: 'viewer' as Role['role_level'],
  });

  // Fetch roles
  const fetchRoles = async () => {
    try {
      setLoading(true);
      const response = await fetch(
        `/api/rbac/roles?tenant_id=${tenant.id}&datasource_id=${datasource.id}`
      );
      const data = await response.json();

      // Ensure we always set an array
      const rolesArray = Array.isArray(data) ? data : (data?.roles || data?.data || []);

      setRoles(rolesArray.length > 0 ? rolesArray : [
        {
          id: '1',
          role_key: 'administrator',
          role_name: 'Administrator',
          description: 'Full access to all features and data.',
          role_type: 'system',
          role_level: 'admin',
          is_active: true,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
          permission_count: 45,
          user_count: 5,
        },
        {
          id: '2',
          role_key: 'manager',
          role_name: 'Manager',
          description: 'Manage users, roles, and basic settings.',
          role_type: 'system',
          role_level: 'editor',
          is_active: true,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
          permission_count: 28,
          user_count: 12,
        },
        {
          id: '3',
          role_key: 'editor',
          role_name: 'Editor',
          description: 'Create and edit content within assigned teams.',
          role_type: 'system',
          role_level: 'editor',
          is_active: true,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
          permission_count: 15,
          user_count: 34,
        },
        {
          id: '4',
          role_key: 'viewer',
          role_name: 'Viewer',
          description: 'View project details and progress.',
          role_type: 'system',
          role_level: 'viewer',
          is_active: true,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
          permission_count: 8,
          user_count: 89,
        },
        {
          id: '5',
          role_key: 'guest',
          role_name: 'Guest',
          description: 'Limited access to public information.',
          role_type: 'system',
          role_level: 'viewer',
          is_active: true,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
          permission_count: 3,
          user_count: 156,
        },
      ]);
    } catch (error) {
      console.error('Failed to fetch roles:', error);
      setRoles([]); // Set empty array on error
    } finally {
      setLoading(false);
    }
  };

  // Fetch permissions
  const fetchPermissions = async () => {
    try {
      const response = await fetch(`/api/rbac/permissions?tenant_id=${tenant.id}`);
      const data = await response.json();
      setPermissions(data || []);
    } catch (error) {
      console.error('Failed to fetch permissions:', error);
    }
  };

  // Fetch role permissions
  const _fetchRolePermissions = async (roleId: string) => {
    try {
      const response = await fetch(
        `/api/rbac/roles/${roleId}/permissions?tenant_id=${tenant.id}&datasource_id=${datasource.id}`
      );
      const data = await response.json();
      const permIds = new Set(data.map((p: Permission) => p.id) as string[]);
      setRolePermissions(permIds);
    } catch (error) {
      console.error('Failed to fetch role permissions:', error);
    }
  };

  // Fetch role details
  const handleViewRole = async (role: Role) => {
    setSelectedRole(role);
    setFormData({
      role_key: role.role_key,
      role_name: role.role_name,
      description: role.description,
      role_level: role.role_level,
    });
    setActiveTab(0);
    setIsViewing(true);

    // Fetch Users
    try {
      const usersRes = await fetch(`/api/rbac/roles/${role.id}/users?tenant_id=${tenant.id}&datasource_id=${datasource.id}`);
      if (usersRes.ok) {
        const usersData = await usersRes.json();
        setRoleUsers(usersData || []);
      }
    } catch (e) {
      console.error("Failed to fetch role users", e);
    }

    // Fetch Field Permissions
    try {
      const permsRes = await fetch(`/api/rbac/field-permissions?tenant_id=${tenant.id}&datasource_id=${datasource.id}&role_id=${role.id}`);
      if (permsRes.ok) {
        const permsData = await permsRes.json();
        setRoleFieldPerms(permsData || []);
      }
    } catch (e) {
      console.error("Failed to fetch role field permissions", e);
    }
  };

  // Create role

  // Create role
  const createRole = async () => {
    try {
      setSaving(true);
      const response = await fetch(
        `/api/rbac/roles?tenant_id=${tenant.id}&datasource_id=${datasource.id}`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            ...formData,
            permissions: Array.from(rolePermissions),
          }),
        }
      );

      if (response.ok) {
        await fetchRoles();
        resetForm();
      }
    } catch (error) {
      console.error('Failed to create role:', error);
    } finally {
      setSaving(false);
    }
  };

  // Save role handler for dialog
  const handleSaveRole = () => {
    createRole();
  };

  // Update role
  const _updateRole = async () => {
    if (!selectedRole) return;

    try {
      setSaving(true);
      await fetch(`/api/rbac/roles/${selectedRole.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          role_name: formData.role_name,
          description: formData.description,
          is_active: true,
        }),
      });

      await Promise.all(
        Array.from(rolePermissions).map(permId =>
          fetch(`/api/rbac/role-permissions`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              role_id: selectedRole.id,
              permission_id: permId,
            }),
          })
        )
      );

      await fetchRoles();
      resetForm();
    } catch (error) {
      console.error('Failed to update role:', error);
    } finally {
      setSaving(false);
    }
  };

  // Delete role
  const _deleteRole = async (roleId: string) => {
    if (!confirm('Are you sure you want to delete this role?')) {
      return;
    }

    try {
      await fetch(`/api/rbac/roles/${roleId}`, { method: 'DELETE' });
      await fetchRoles();
      if (selectedRole?.id === roleId) {
        resetForm();
      }
    } catch (error) {
      console.error('Failed to delete role:', error);
    }
  };

  // Reset form
  const resetForm = () => {
    setFormData({
      role_key: '',
      role_name: '',
      description: '',
      role_level: 'viewer',
    });
    setRolePermissions(new Set());
    setSelectedRole(null);
    setIsEditing(false);
    setIsCreating(false);
  };

  // Toggle permission
  const _togglePermission = (permId: string) => {
    const newPerms = new Set(rolePermissions);
    if (newPerms.has(permId)) {
      newPerms.delete(permId);
    } else {
      newPerms.add(permId);
    }
    setRolePermissions(newPerms);
  };

  // Filter roles
  const filteredRoles = useMemo(() => {
    return roles.filter(role => {
      const matchesSearch = role.role_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          role.role_key.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesLevel = filterLevel === 'all' || role.role_level === filterLevel;
      return matchesSearch && matchesLevel;
    });
  }, [roles, searchTerm, filterLevel]);

  useEffect(() => {
    fetchRoles();
    fetchPermissions();
  }, [tenant.id]);

  if (loading) {
    return (
      <Box 
        display="flex" 
        alignItems="center" 
        justifyContent="center" 
        minHeight="100vh"
        bgcolor="background.default"
      >
        <Box display="flex" flexDirection="column" alignItems="center" gap={2}>
          <SecurityIcon sx={{ fontSize: 48, animation: 'spin 2s linear infinite', color: 'primary.main' }} />
          <Typography variant="body1" color="text.secondary">
            Loading roles...
          </Typography>
        </Box>
      </Box>
    );
  }

  return (
    <Box sx={{ width: '100%', minHeight: '100vh', bgcolor: 'background.default' }}>
      {/* Material AppBar Header */}
      <AppBar position="sticky" color="default" elevation={1} sx={{ bgcolor: 'background.paper' }}>
        <Toolbar sx={{ px: 3, py: 1 }}>
          <Box display="flex" alignItems="center" gap={1.5} flexGrow={1}>
            <SecurityIcon sx={{ fontSize: 28, color: 'primary.main' }} />
            <Typography variant="h6" component="div" fontWeight={600}>
              Role Manager
            </Typography>
          </Box>
          <Box display="flex" alignItems="center" gap={2}>
            <TextField
              size="small"
              placeholder="Search"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon sx={{ fontSize: 18 }} />
                  </InputAdornment>
                ),
              }}
              sx={{ width: 240 }}
            />
          </Box>
        </Toolbar>
      </AppBar>

      {/* Main Content */}
      <Box component="main" sx={{ px: 4, py: 4 }}>
        <Box display="flex" justifyContent="space-between" alignItems="center" mb={4}>
          <Typography variant="h4" fontWeight={600} color="text.primary">
            Roles
          </Typography>
          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => {
              resetForm();
              setIsCreating(true);
            }}
            sx={{ textTransform: 'none', fontWeight: 500 }}
          >
            Create Role
          </Button>
        </Box>

        {/* Search and Filter Bar */}
        <Box display="flex" gap={2} mb={3}>
          <TextField
            fullWidth
            size="medium"
            placeholder="Search roles"
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon sx={{ fontSize: 20 }} />
                </InputAdornment>
              ),
            }}
          />
          <Button
            variant="outlined"
            endIcon={<FilterIcon />}
            sx={{ textTransform: 'none', fontWeight: 500, minWidth: 120 }}
          >
            Level
          </Button>
        </Box>

        {/* Roles Table with Material Elevation */}
        <Paper elevation={2} sx={{ borderRadius: 2, overflow: 'hidden' }}>
          <TableContainer>
            <Table>
              <TableHead>
                <TableRow sx={{ bgcolor: 'grey.50' }}>
                  <TableCell>
                    <Typography variant="subtitle2" fontWeight={600}>Role Name</Typography>
                  </TableCell>
                  <TableCell>
                    <Typography variant="subtitle2" fontWeight={600}>Level</Typography>
                  </TableCell>
                  <TableCell>
                    <Typography variant="subtitle2" fontWeight={600}>Description</Typography>
                  </TableCell>
                  <TableCell>
                    <Typography variant="subtitle2" fontWeight={600}>Actions</Typography>
                  </TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {filteredRoles.map((role) => (
                  <TableRow 
                    key={role.id}
                    hover
                    sx={{ '&:last-child td': { borderBottom: 0 } }}
                  >
                    <TableCell>
                      <Typography variant="body2" fontWeight={500}>
                        {role.role_name}
                      </Typography>
                    </TableCell>
                    <TableCell>
                      <Chip 
                        label={role.role_level.replace(/_/g, ' ').split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ')}
                        size="small"
                        color="primary"
                        variant="outlined"
                      />
                    </TableCell>
                    <TableCell>
                      <Typography variant="body2" color="text.secondary">
                        {role.description}
                      </Typography>
                    </TableCell>
                    <TableCell>
                      <Box display="flex" gap={1}>
                        <Tooltip title="View">
                          <IconButton 
                            size="small" 
                            color="primary"
                            onClick={() => handleViewRole(role)}
                          >
                            <ViewIcon fontSize="small" />
                          </IconButton>
                        </Tooltip>
                        <Tooltip title="Edit">
                          <IconButton 
                            size="small" 
                            color="primary"
                            onClick={() => {
                              setSelectedRole(role);
                              setFormData({
                                role_key: role.role_key,
                                role_name: role.role_name,
                                description: role.description,
                                role_level: role.role_level,
                              });
                              setIsEditing(true);
                            }}
                          >
                            <EditIcon fontSize="small" />
                          </IconButton>
                        </Tooltip>
                        <Tooltip title="Delete">
                          <IconButton 
                            size="small" 
                            color="error"
                            onClick={() => _deleteRole(role.id)}
                          >
                            <DeleteIcon fontSize="small" />
                          </IconButton>
                        </Tooltip>
                      </Box>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
      </Box>

      {/* Create Role Material Dialog */}
      <Dialog 
        open={_isCreating} 
        onClose={resetForm}
        maxWidth="sm"
        fullWidth
        PaperProps={{
          elevation: 8,
          sx: { borderRadius: 2 }
        }}
      >
        <DialogTitle>
          <Typography variant="h5" fontWeight={600}>
            Create Role
          </Typography>
        </DialogTitle>
        <DialogContent sx={{ pt: 2 }}>
          <Box display="flex" flexDirection="column" gap={3} mt={1}>
            <TextField
              fullWidth
              label="Role Key"
              placeholder="Enter role key"
              value={formData.role_key}
              onChange={(e) => setFormData({ ...formData, role_key: e.target.value })}
              variant="outlined"
            />

            <TextField
              fullWidth
              label="Role Name"
              placeholder="Enter role name"
              value={formData.role_name}
              onChange={(e) => setFormData({ ...formData, role_name: e.target.value })}
              variant="outlined"
            />

            <TextField
              fullWidth
              multiline
              rows={3}
              label="Description"
              placeholder="Enter role description"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              variant="outlined"
            />

            <TextField
              fullWidth
              select
              label="Role Level"
              value={formData.role_level}
              onChange={(e) => setFormData({ ...formData, role_level: e.target.value as any })}
              variant="outlined"
            >
              <MenuItem value="viewer">Viewer</MenuItem>
              <MenuItem value="editor">Editor</MenuItem>
              <MenuItem value="approver">Approver</MenuItem>
              <MenuItem value="admin">Admin</MenuItem>
              <MenuItem value="super_admin">Super Admin</MenuItem>
            </TextField>
          </Box>
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 2 }}>
          <Button onClick={resetForm} sx={{ textTransform: 'none' }}>
            Cancel
          </Button>
          <Button 
            variant="contained" 
            onClick={handleSaveRole}
            sx={{ textTransform: 'none', fontWeight: 500 }}
          >
            Create
          </Button>
        </DialogActions>
      </Dialog>

      {/* Edit Role Material Dialog */}
      <Dialog 
        open={_isEditing} 
        onClose={resetForm}
        maxWidth="sm"
        fullWidth
        PaperProps={{
          elevation: 8,
          sx: { borderRadius: 2 }
        }}
      >
        <DialogTitle>
          <Typography variant="h5" fontWeight={600}>
            Edit Role
          </Typography>
        </DialogTitle>
        <DialogContent sx={{ pt: 2 }}>
          <Box display="flex" flexDirection="column" gap={3} mt={1}>
            <TextField
              fullWidth
              label="Role Key"
              value={formData.role_key}
              disabled
              variant="outlined"
              helperText="Role key cannot be changed"
            />

            <TextField
              fullWidth
              label="Role Name"
              placeholder="Enter role name"
              value={formData.role_name}
              onChange={(e) => setFormData({ ...formData, role_name: e.target.value })}
              variant="outlined"
            />

            <TextField
              fullWidth
              multiline
              rows={3}
              label="Description"
              placeholder="Enter role description"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              variant="outlined"
            />

            <TextField
              fullWidth
              select
              label="Role Level"
              value={formData.role_level}
              onChange={(e) => setFormData({ ...formData, role_level: e.target.value as any })}
              variant="outlined"
            >
              <MenuItem value="viewer">Viewer</MenuItem>
              <MenuItem value="editor">Editor</MenuItem>
              <MenuItem value="approver">Approver</MenuItem>
              <MenuItem value="admin">Admin</MenuItem>
              <MenuItem value="super_admin">Super Admin</MenuItem>
            </TextField>

            {selectedRole && (
              <Box display="flex" alignItems="center" justifyContent="space-between" p={2} bgcolor="grey.50" borderRadius={1} mt={2}>
                <Box>
                  <Typography variant="subtitle2" fontWeight={600}>
                    Role Status
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    {selectedRole.is_active ? 'Active - Users can be assigned this role' : 'Inactive - Role is disabled'}
                  </Typography>
                </Box>
                <Button
                  variant={selectedRole.is_active ? "outlined" : "contained"}
                  color={selectedRole.is_active ? "error" : "success"}
                  onClick={async () => {
                    try {
                      await fetch(`/api/rbac/roles/${selectedRole.id}?tenant_id=${tenant.id}&datasource_id=${datasource.id}`, {
                        method: 'PUT',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                          role_name: selectedRole.role_name,
                          description: selectedRole.description,
                          is_active: !selectedRole.is_active,
                        }),
                      });
                      await fetchRoles();
                      setSelectedRole({ ...selectedRole, is_active: !selectedRole.is_active });
                    } catch (error) {
                      console.error('Failed to toggle role status:', error);
                    }
                  }}
                  sx={{ textTransform: 'none', fontWeight: 500 }}
                >
                  {selectedRole.is_active ? 'Deactivate' : 'Activate'}
                </Button>
              </Box>
            )}
          </Box>
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 2 }}>
          <Button onClick={resetForm} sx={{ textTransform: 'none' }}>
            Cancel
          </Button>
          <Button 
            variant="contained" 
            onClick={_updateRole}
            sx={{ textTransform: 'none', fontWeight: 500 }}
          >
            Save Changes
          </Button>
        </DialogActions>
      </Dialog>

      {/* View Role Material Dialog (Read-Only) */}
      <Dialog 
        open={isViewing} 
        onClose={() => setIsViewing(false)}
        maxWidth="sm"
        fullWidth
        PaperProps={{
          elevation: 8,
          sx: { borderRadius: 2 }
        }}
      >
        <DialogTitle>
          <Typography variant="h5" fontWeight={600}>
            Role Details
          </Typography>
        </DialogTitle>
        <DialogContent sx={{ pt: 2 }}>
            {/* Tabs */}
            <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 2 }}>
              <Tabs value={activeTab} onChange={(_, v) => setActiveTab(v)}>
                <Tab label="Overview" />
                <Tab label={`Users (${roleUsers.length})`} />
                <Tab label={`Field Permissions (${roleFieldPerms.length})`} />
              </Tabs>
            </Box>

            {/* Overview Tab */}
            {activeTab === 0 && (
              <Box display="flex" flexDirection="column" gap={3}>
                <TextField
                  fullWidth
                  label="Role Key"
                  value={formData.role_key}
                  disabled
                  variant="outlined"
                />
                <TextField
                  fullWidth
                  label="Role Name"
                  value={formData.role_name}
                  disabled
                  variant="outlined"
                />
                <TextField
                  fullWidth
                  multiline
                  rows={3}
                  label="Description"
                  value={formData.description}
                  disabled
                  variant="outlined"
                />
                <TextField
                  fullWidth
                  label="Role Level"
                  value={formData.role_level.replace(/_/g, ' ').split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ')}
                  disabled
                  variant="outlined"
                />
                {selectedRole && (
                  <>
                    <TextField
                      fullWidth
                      label="Status"
                      value={selectedRole.is_active ? 'Active' : 'Inactive'}
                      disabled
                      variant="outlined"
                    />
                     <TextField
                      fullWidth
                      label="Created At"
                      value={new Date(selectedRole.created_at).toLocaleString()}
                      disabled
                      variant="outlined"
                    />
                  </>
                )}
              </Box>
            )}

            {/* Users Tab */}
            {activeTab === 1 && (
              <List sx={{ p: 0, maxHeight: 400, overflow: 'auto' }}>
                {roleUsers.length === 0 ? (
                  <Box p={3} textAlign="center"><Typography color="text.secondary">No users assigned to this role.</Typography></Box>
                ) : (
                  roleUsers.map((user, i) => (
                    <React.Fragment key={user.id}>
                      {i > 0 && <Divider />}
                      <ListItem>
                        <ListItemAvatar>
                          <Avatar>{user.username?.charAt(0).toUpperCase()}</Avatar>
                        </ListItemAvatar>
                        <ListItemText 
                          primary={user.name || user.username} 
                          secondary={user.email} 
                        />
                        <Typography variant="caption" color="text.secondary">
                          Assigned: {new Date(user.assigned_at).toLocaleDateString()}
                        </Typography>
                      </ListItem>
                    </React.Fragment>
                  ))
                )}
              </List>
            )}

            {/* Field Permissions Tab */}
            {activeTab === 2 && (
              <TableContainer sx={{ maxHeight: 400 }}>
                <Table stickyHeader size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Field</TableCell>
                      <TableCell>Resource/Context</TableCell>
                      <TableCell>Permission</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {roleFieldPerms.length === 0 ? (
                      <TableRow><TableCell colSpan={3} align="center">No field permissions configured.</TableCell></TableRow>
                    ) : (
                      roleFieldPerms.map((fp) => (
                        <TableRow key={fp.id} hover>
                          <TableCell sx={{ fontWeight: 500 }}>{fp.field_name}</TableCell>
                          <TableCell>{fp.resource_type}</TableCell>
                          <TableCell>
                            <Chip 
                              label={fp.permission_level} 
                              size="small" 
                              color={fp.permission_level === 'write' ? 'success' : fp.permission_level === 'read' ? 'info' : 'warning'} 
                              variant="outlined"
                              sx={{ minWidth: 60, height: 20, fontSize: '0.7rem' }}
                            />
                          </TableCell>
                        </TableRow>
                      ))
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            )}
        </DialogContent>
        <DialogActions sx={{ px: 3, pb: 2 }}>
          <Button onClick={() => setIsViewing(false)} sx={{ textTransform: 'none' }}>
            Close
          </Button>
          <Button 
            variant="outlined"
            startIcon={<PersonAddIcon />}
            onClick={() => {
              if (selectedRole) {
                // Open user assignment in a new component/page
                alert('User assignment feature: Navigate to /admin/rbac/assign-users or open UserRoleAssignmentDialog component');
              }
            }}
            sx={{ textTransform: 'none', fontWeight: 500 }}
          >
            Assign Users
          </Button>
          <Button 
            variant="contained" 
            onClick={() => {
              setIsViewing(false);
              setIsEditing(true);
            }}
            sx={{ textTransform: 'none', fontWeight: 500 }}
          >
            Edit Role
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

/**
 * Team Manager - Enterprise Team & Department Management
 * 
 * Features:
 * - Team creation and configuration
 * - Member roster management
 * - Role-in-team assignments
 * - Team permission configuration
 * - Cross-functional team support
 */

import React, { useState, useEffect, useMemo } from 'react';
import {
  Users,
  Plus,
  X,
  Save,
  Trash2,
  UserPlus,
  UserMinus,
  Search,
  Filter,
  Shield,
  Building2,
  Target,
  Network,
  Crown,
  CheckCircle2,
} from 'lucide-react';

// ============================================================================
// TYPE DEFINITIONS
// ============================================================================

interface Team {
  id: string;
  team_key: string;
  team_name: string;
  description: string;
  team_type: 'functional' | 'project' | 'cross_functional';
  manager_user_id: string;
  manager_name?: string;
  member_count?: number;
  created_at: string;
}

interface TeamMember {
  id: string;
  team_id: string;
  user_id: string;
  user_name: string;
  user_email: string;
  role_in_team: 'member' | 'lead' | 'admin';
  joined_at: string;
}

interface User {
  id: string;
  username: string;
  email: string;
  full_name: string;
  department: string;
}

interface TeamManagerProps {
  tenant: { id: string; display_name: string };
  datasource: { id: string; source_name: string };
}

// ============================================================================
// MAIN COMPONENT
// ============================================================================

export const TeamManager: React.FC<TeamManagerProps> = ({ tenant, datasource }) => {
  const [teams, setTeams] = useState<Team[]>([]);
  const [selectedTeam, setSelectedTeam] = useState<Team | null>(null);
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showAddMemberModal, setShowAddMemberModal] = useState(false);
  const [saving, setSaving] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [typeFilter, setTypeFilter] = useState<string>('all');

  // Create team form
  const [teamForm, setTeamForm] = useState({
    team_key: '',
    team_name: '',
    description: '',
    team_type: 'functional' as 'functional' | 'project' | 'cross_functional',
    manager_user_id: '',
  });

  // Add member form
  const [memberForm, setMemberForm] = useState({
    user_id: '',
    role_in_team: 'member' as 'member' | 'lead' | 'admin',
  });

  // Fetch teams
  const fetchTeams = async () => {
    try {
      setLoading(true);
      const response = await fetch(
        `/api/rbac/teams?tenant_id=${tenant.id}&datasource_id=${datasource.id}`
      );
      const data = await response.json();
      setTeams(data || []);
    } catch (error) {
      console.error('Failed to fetch teams:', error);
    } finally {
      setLoading(false);
    }
  };

  // Fetch team members
  const fetchTeamMembers = async (teamId: string) => {
    try {
      const response = await fetch(
        `/api/rbac/teams/${teamId}/members?tenant_id=${tenant.id}&datasource_id=${datasource.id}`
      );
      const data = await response.json();
      setTeamMembers(data || []);
    } catch (error) {
      console.error('Failed to fetch team members:', error);
    }
  };

  // Fetch users
  const fetchUsers = async () => {
    try {
      const response = await fetch(`/api/users?tenant_id=${tenant.id}`);
      const data = await response.json();
      setUsers(data || []);
    } catch (error) {
      console.error('Failed to fetch users:', error);
    }
  };

  // Create team
  const createTeam = async () => {
    try {
      setSaving(true);
      const response = await fetch(`/api/rbac/teams`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...teamForm,
          tenant_id: tenant.id,
          datasource_id: datasource.id,
        }),
      });
      await fetchTeams();
      setShowCreateModal(false);
      resetTeamForm();
    } catch (error) {
      console.error('Failed to create team:', error);
    } finally {
      setSaving(false);
    }
  };

  // Delete team
  const deleteTeam = async (teamId: string) => {
    if (!confirm('Are you sure you want to delete this team?')) return;

    try {
      setSaving(true);
      await fetch(`/api/rbac/teams/${teamId}`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tenant_id: tenant.id, datasource_id: datasource.id }),
      });
      await fetchTeams();
      if (selectedTeam?.id === teamId) {
        setSelectedTeam(null);
        setTeamMembers([]);
      }
    } catch (error) {
      console.error('Failed to delete team:', error);
    } finally {
      setSaving(false);
    }
  };

  // Add team member
  const addTeamMember = async () => {
    if (!selectedTeam) return;

    try {
      setSaving(true);
      await fetch(`/api/rbac/teams/${selectedTeam.id}/members`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...memberForm,
          tenant_id: tenant.id,
          datasource_id: datasource.id,
        }),
      });
      await fetchTeamMembers(selectedTeam.id);
      await fetchTeams(); // Refresh member count
      setShowAddMemberModal(false);
      resetMemberForm();
    } catch (error) {
      console.error('Failed to add team member:', error);
    } finally {
      setSaving(false);
    }
  };

  // Remove team member
  const removeTeamMember = async (memberId: string) => {
    if (!selectedTeam || !confirm('Remove this member from the team?')) return;

    try {
      setSaving(true);
      await fetch(`/api/rbac/teams/${selectedTeam.id}/members/${memberId}`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tenant_id: tenant.id, datasource_id: datasource.id }),
      });
      await fetchTeamMembers(selectedTeam.id);
      await fetchTeams(); // Refresh member count
    } catch (error) {
      console.error('Failed to remove team member:', error);
    } finally {
      setSaving(false);
    }
  };

  // Reset team form
  const resetTeamForm = () => {
    setTeamForm({
      team_key: '',
      team_name: '',
      description: '',
      team_type: 'functional',
      manager_user_id: '',
    });
  };

  // Reset member form
  const resetMemberForm = () => {
    setMemberForm({
      user_id: '',
      role_in_team: 'member',
    });
  };

  // Filter teams
  const filteredTeams = useMemo(() => {
    return teams.filter(team => {
      const matchesSearch =
        team.team_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        team.team_key.toLowerCase().includes(searchTerm.toLowerCase()) ||
        team.description?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesType = typeFilter === 'all' || team.team_type === typeFilter;
      return matchesSearch && matchesType;
    });
  }, [teams, searchTerm, typeFilter]);

  useEffect(() => {
    fetchTeams();
    fetchUsers();
  }, [tenant.id]);

  useEffect(() => {
    if (selectedTeam) {
      fetchTeamMembers(selectedTeam.id);
    }
  }, [selectedTeam]);

  const getTeamTypeIcon = (type: string) => {
    const icons = {
      functional: <Building2 className="w-5 h-5" />,
      project: <Target className="w-5 h-5" />,
      cross_functional: <Network className="w-5 h-5" />,
    };
    return icons[type as keyof typeof icons] || <Users className="w-5 h-5" />;
  };

  const getTeamTypeColor = (type: string) => {
    const colors = {
      functional: 'bg-blue-100 text-blue-700 border-blue-300',
      project: 'bg-green-100 text-green-700 border-green-300',
      cross_functional: 'bg-purple-100 text-purple-700 border-purple-300',
    };
    return colors[type as keyof typeof colors] || 'bg-gray-100 text-gray-700 border-gray-300';
  };

  const getRoleIcon = (role: string) => {
    const icons = {
      admin: <Crown className="w-4 h-4" />,
      lead: <Shield className="w-4 h-4" />,
      member: <CheckCircle2 className="w-4 h-4" />,
    };
    return icons[role as keyof typeof icons] || <CheckCircle2 className="w-4 h-4" />;
  };

  const getRoleColor = (role: string) => {
    const colors = {
      admin: 'bg-red-100 text-red-700 border-red-300',
      lead: 'bg-orange-100 text-orange-700 border-orange-300',
      member: 'bg-blue-100 text-blue-700 border-blue-300',
    };
    return colors[role as keyof typeof colors] || 'bg-gray-100 text-gray-700 border-gray-300';
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="flex flex-col items-center gap-4">
          <Users className="w-12 h-12 animate-pulse text-blue-500" />
          <p className="text-gray-600">Loading teams...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 p-6">
      {/* Header */}
      <div className="mb-8">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-gray-900 flex items-center gap-3">
              <Users className="w-8 h-8 text-blue-600" />
              Team Manager
            </h1>
            <p className="text-gray-600 mt-2">
              Manage teams and departments for {tenant.display_name}
            </p>
          </div>
          <button
            onClick={() => {
              resetTeamForm();
              setShowCreateModal(true);
            }}
            className="px-6 py-3 bg-blue-600 text-white rounded-lg font-medium hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg"
          >
            <Plus className="w-5 h-5" />
            Create Team
          </button>
        </div>

        {/* Search and Filters */}
        <div className="flex gap-4 mt-6">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input
              type="text"
              placeholder="Search teams..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-3 border-2 border-gray-200 rounded-lg focus:outline-none focus:border-blue-500"
            />
          </div>
          <select
            value={typeFilter}
            onChange={(e) => setTypeFilter(e.target.value)}
            className="px-4 py-3 border-2 border-gray-200 rounded-lg focus:outline-none focus:border-blue-500 bg-white"
          >
            <option value="all">All Types</option>
