import { devDebug, devError } from '../utils/devLogger';


export default function SemanticMapper({ onOpenWizard }: { onOpenWizard?: () => void }) {
  const {
    mappings, setMappings, loading, toast, setToast,
    loadMappings, searchSemanticTerms, createNewSemanticTerm,
    createEdges, replaceMapping, persistIgnores
  } = useSemanticMapper();

  const getUniqueId = (m: Mapping) => getMappingUniqueId(m);

  const [globalSearchTerm, setGlobalSearchTerm] = useState('');
  const [savedRows, setSavedRows] = useState<Set<string>>(new Set());
  const [selectedMappings, setSelectedMappings] = useState<Set<string>>(new Set());
  const [sortBy, setSortBy] = useState<'confidence' | 'name' | 'none'>('confidence');
  const [mappedFilter, setMappedFilter] = useState<Set<'all' | 'mapped' | 'unmapped' | 'selected' | 'highConfidence' | 'pending'>>(new Set(['all']));
  const [currentMatchIndex, setCurrentMatchIndex] = useState<number>(0);
  const [suggestions, setSuggestions] = useState<any[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [highlightedIndex, setHighlightedIndex] = useState(-1);
  const searchInputRef = useRef<HTMLInputElement>(null);

  const updateMappings = useCallback((updater: (prev: Mapping[]) => Mapping[]) => {
    setMappings((prev: Mapping[]) => {
      const next = updater(prev);
      setSelectedMappings(new Set(next.filter((m: Mapping) => m.selected).map((m: Mapping) => getUniqueId(m))));
      return next;
    });
  }, [setMappings, setSelectedMappings, getUniqueId]);

  // Debounced search for semantic terms with useRef to avoid recreating
  const searchTimeoutRef = useRef<NodeJS.Timeout>();

  const debouncedSearch = useCallback((query: string) => {
    // Clear previous timeout
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    if (query.trim().length < 2) {
      setSuggestions([]);
      setShowSuggestions(false);
      return;
    }

    searchTimeoutRef.current = setTimeout(async () => {
      try {
        const results = await searchSemanticTerms(query);
        const formattedSuggestions = results.map((term: any) => ({
          id: term.node_id || term.term_name,
          title: term.term_name,
          subtitle: term.description || 'Semantic Term',
          type: 'semantic-term'
        }));
        setSuggestions(formattedSuggestions);
        setShowSuggestions(true);
        setHighlightedIndex(-1);
      } catch (error) {
        devError('Error searching semantic terms:', error);
        setSuggestions([]);
        setShowSuggestions(false);
      }
    }, 300);
  }, [searchSemanticTerms]);

  const handleSuggestionSelect = (suggestion: any) => {
    // When a semantic term is selected, set it as the search term
    setGlobalSearchTerm(suggestion.title);
    setShowSuggestions(false);
    setCurrentMatchIndex(0);
  };

  const handleSearchFocus = () => {
    if (suggestions.length > 0 && globalSearchTerm.trim().length >= 2) {
      setShowSuggestions(true);
    }
  };

  const handleSearchBlur = () => {
    // Delay hiding suggestions to allow clicks
    setTimeout(() => setShowSuggestions(false), 200);
  };

  const handleNavigateMatch = (direction: 1 | -1) => {
    const totalMatches = filteredMappings.length;
    if (totalMatches === 0) return;

    const newIndex = direction === 1 
      ? Math.min(currentMatchIndex + 1, totalMatches - 1)
      : Math.max(currentMatchIndex - 1, 0);

    setCurrentMatchIndex(newIndex);
  };

  const handleSearchChange = useCallback((newTerm: string) => {
    setGlobalSearchTerm(newTerm);
    setCurrentMatchIndex(0);
    debouncedSearch(newTerm);
  }, [debouncedSearch]);

  // Cleanup timeout on unmount
  useEffect(() => {
    return () => {
      if (searchTimeoutRef.current) {
        clearTimeout(searchTimeoutRef.current);
      }
    };
  }, []);
  const [compactRows] = useState<boolean>(() => {
    try { const v = localStorage.getItem('semantic_mapper_compact_rows'); return v === null ? true : v === '1' || v === 'true'; } catch (e) { return true }
  });

  const [wizardOpen, setWizardOpen] = useState(false);
  const [lineageModalOpen, setLineageModalOpen] = useState(false);
  const [lineageSelectedAsset, setLineageSelectedAsset] = useState<any | null>(null);
  const [lineageDatasourceId, setLineageDatasourceId] = useState<string | null>(null);
  const lineageData = useLineageData(lineageDatasourceId || '');

  const TabPanel = (props: { children?: React.ReactNode; index: number; value: number }) => {
    const { children, value, index, ...other } = props;
    return (
      <div
        role="tabpanel"
        hidden={value !== index}
        id={`semantic-mapper-tabpanel-${index}`}
        aria-labelledby={`semantic-mapper-tab-${index}`}
        {...other}
      >
        {value === index && <Box sx={{ p: 3 }}>{children}</Box>}
      </div>
    );
  };

  const [activeTab, setActiveTab] = useState(0);
  // profile preselection state (set by DbScanner)
  const [profileSchema, setProfileSchema] = useState<string | null>(null);
  const [profileTable, setProfileTable] = useState<string | null>(null);
  const [profileTables, setProfileTables] = useState<string[] | null>(null);
  const scope = useScope();
  const { tenant, datasource } = useTenant();
  const runScanRef = (window as any).runScanRef || { current: null };

  const toggleMapping = (mappingId: string) => {
    updateMappings((prev: Mapping[]) => prev.map((m: Mapping) => {
      if (getUniqueId(m) === mappingId) {
        return { ...m, selected: !m.selected };
      }
      return m;
    }));
  };

  const confirmEditing = async (id: string, _typedTerm?: string) => {
    // This is no longer needed - we handle everything through selectSemanticTerm and handleCreateAndSelectTerm
    setSavedRows(s => { const n = new Set(s); n.add(id); setTimeout(() => { setSavedRows(prev => { const r = new Set(prev); r.delete(id); return r; }); }, 3000); return n; });
  };

  const setOverride = (id: string, val: boolean) => {
    updateMappings((prev: Mapping[]) => prev.map((m: Mapping) => {
      if (getUniqueId(m) === id) {
        return { ...m, override: val, selected: val ? true : m.selected };
      }
      return m;
    }));
  };

  const setIgnored = (id: string, val: boolean) => {
    updateMappings((prev: Mapping[]) => prev.map((m: Mapping) => {
      if (getUniqueId(m) === id) {
        return { ...m, ignored: val, selected: val ? false : m.selected };
      }
      return m;
    }));
  };

  const filteredMappings = useMemo(() => {
    const searchTerm = globalSearchTerm.toLowerCase().trim();

    return mappings.filter((m: Mapping) => {
      // Skip ignored mappings
      if (m.ignored) return false;

      // Apply filters
      if (!mappedFilter.has('all')) {
        // If we have specific filters, check them
        // Note: These can be additive or exclusive. 
        // Logic: if any single positive filter is active, we check if it matches.
        // If multiple are active, usually we interpret as OR or AND. 
        // Based on typical UI, if 'Pending' and 'High Confidence' are clicked, it might mean "Pending AND High Conf" or "Pending OR High Conf".
        // Given the simplistic set, let's assume if specific filters are on, at least one must match (OR logic) or all must match (AND).
        // Let's go with behavior:
        // If 'mapped' is on -> must be mapped
        // If 'unmapped' is on -> must be unmapped
        // If 'pending' is on -> must be pending

        // But commonly, "Mapped" vs "Unmapped" are mutually exclusive.
        // "High Confidence" is a subset.

        // Revised Logic:
        // If 'mapped' is active, include mapped.
        // If 'unmapped' is active, include unmapped.
        // If 'pending' is active, include pending.
        // If 'highConfidence' is active, include high confidence.
        // If 'selected' is active, include selected.

        // We act as an OR filter if multiple are selected? 
        // Or is it a replacement? "Clicking High Confidence shows ONLY High Confidence".
        // The user said "make these aggregates filters". Usually clicking a stat card filters to THAT category.
        // So likely we treat the Set as having usually one active filter, or we allow multiple.
        // Implementation: Check if ANY active filter matches.

        const activeFilters = Array.from(mappedFilter);
        const matchesAny = activeFilters.some(f => {
          if (f === 'mapped') return m.edge_exists;
          if (f === 'unmapped') return !m.edge_exists;
          if (f === 'pending') return m.is_pending;
          if (f === 'highConfidence') return m.confidence >= 0.75;
          if (f === 'selected') return m.selected;
          return false;
        });

        if (!matchesAny) return false;
      }

      // Apply scope filters (sidebar selection)
      if (scope.schemaNames.length > 0 && !scope.schemaNames.includes(m.database_column.schema || '')) return false;
      if (scope.tableNames.length > 0 && !scope.tableNames.includes(m.database_column.table || '')) return false;
      if (scope.columnNames.length > 0 && !scope.columnNames.includes(m.database_column.column || '')) return false;

      // Apply search term filter
      if (searchTerm) {
        const col = m.database_column;
        const semanticTerm = m.semantic_term || '';
        const matchReason = m.match_reason || '';

        const searchableText = [
          col.schema || '',
          col.table || '',
          col.column || '',
          semanticTerm,
          matchReason,
          col.data_type || ''
        ].join(' ').toLowerCase();

        // Check if search term matches any part of the searchable text
        const matches = searchTerm.split(' ').every(term => 
          term.length === 0 || searchableText.includes(term)
        );

        if (!matches) return false;
      }

      return true;
    }).sort((a: any, b: any) => {
      // Pending items float to top if sorting by confidence
      if (a.is_pending && !b.is_pending) return -1;

      const aT = a as Mapping; const bT = b as Mapping;
      if (sortBy === 'confidence') return bT.confidence - aT.confidence;
      if (sortBy === 'name') return aT.database_column.column.localeCompare(bT.database_column.column);
      return 0;
    });
  }, [mappings, globalSearchTerm, mappedFilter, scope, sortBy]);

  const mappingCounts = useMemo(() => {
    const counts = { all: 0, mapped: 0, unmapped: 0, pending: 0 };
    mappings.forEach((m: Mapping) => {
      if (m.ignored) return;
      counts.all++;
      if (m.edge_exists) {
        counts.mapped++;
      } else {
        counts.unmapped++;
      }
      if (m.is_pending) counts.pending++;
    });
    return counts;
  }, [mappings]);

  const highConfidenceCount = useMemo(() => filteredMappings.filter(m => m.confidence >= 0.75).length, [filteredMappings]);

  const averageConfidence = useMemo(() => {
    if (filteredMappings.length === 0) return 0;
    return filteredMappings.reduce((s, m) => s + (m.confidence || 0), 0) / filteredMappings.length;
  }, [filteredMappings]);

  const sortedMappings = filteredMappings; // Renaming for clarity as we already sorted in filteredMappings


  const [confirmOpen, setConfirmOpen] = useState(false);
  const [replaceConfirmOpen, setReplaceConfirmOpen] = useState(false);
  const [replaceIndex, setReplaceIndex] = useState<number | null>(null);
  const openConfirm = () => { if (selectedMappings.size > 0) setConfirmOpen(true); };
  const closeConfirm = () => setConfirmOpen(false);
  const confirmCreate = async () => { 
    closeConfirm(); 
    const selected = mappings.filter((m: any) => selectedMappings.has(getUniqueId(m)) && !m.ignored && !m.edge_exists);
    devDebug('[SemanticMapper] Creating edges for mappings:', selected.map(m => ({
      column: m.database_column.column,
      semantic_term: m.semantic_term,
      semantic_term_id: m.semantic_term_id,
      is_new_term: m.is_new_term,
      override: m.override,
      edge_exists: m.edge_exists,
      has_tenant_id: !!m.database_column.tenant_id,
      has_datasource_id: !!m.database_column.tenant_datasource_id,
      full_db_column: m.database_column
    })));

    if (selected.length === 0) {
      setToast({ type: 'error', message: 'No mappings selected for edge creation. Make sure mappings are checked and have semantic terms assigned.' });
      return;
    }

    await createEdges(selected); 
    setSelectedMappings(new Set()); 
  };
  const openReplaceConfirm = (idx: number) => { setReplaceIndex(idx); setReplaceConfirmOpen(true); };
  const closeReplaceConfirm = () => { setReplaceIndex(null); setReplaceConfirmOpen(false); };
  const confirmReplace = async () => { if (replaceIndex !== null) await replaceMapping(mappings[replaceIndex]); closeReplaceConfirm(); };

  useEffect(() => { try { localStorage.setItem('semantic_mapper_compact_rows', compactRows ? '1' : '0'); } catch (e) {} }, [compactRows]);

  return (
    <Fragment>
    <Box sx={{ minHeight: '100vh', bgcolor: 'grey.50', p: 3 }}>
        <Box sx={{ maxWidth: '1600px', margin: '0 auto' }}>
        <Box className="semantic-topbar">
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', maxWidth: '1600px', margin: '0 auto', px: 2 }}>
            <Typography className="title">Semantic Mapper</Typography>
            {activeTab === 0 && (
              <Button variant="contained" onClick={() => { if (runScanRef.current) runScanRef.current(); }} data-testid="top-scan-button">Scan</Button>
            )}
          </Box>
        </Box>
        {!hasTenantScope() && (
          <Alert severity="warning" sx={{ mb: 3 }}>
            <Typography variant="body2" sx={{ fontWeight: 600 }}>Tenant selection required</Typography>
            <Typography variant="body2" sx={{ mt: 0.5 }}>Please select a tenant and datasource using the selector in the navigation to enable catalog filtering and searches. Without tenant scope, API requests for schemas, tables, and columns will be blocked.</Typography>
          </Alert>
        )}

        {mappings.filter((m: any) => m.override && m.selected && m.semantic_term_id && !m.edge_exists).length > 0 && (
          <Alert severity="success" sx={{ mb: 3 }}>
            <Typography variant="body2" sx={{ fontWeight: 600 }}>✅ Override Ready to Apply</Typography>
            <Typography variant="body2" sx={{ mt: 0.5 }}>
              {mappings.filter((m: any) => m.override && m.selected && m.semantic_term_id && !m.edge_exists).length} override mapping{mappings.filter((m: any) => m.override && m.selected && m.semantic_term_id && !m.edge_exists).length > 1 ? 's are' : ' is'} selected and ready.
              Click "Create Edges" to persist {mappings.filter((m: any) => m.override && m.selected && m.semantic_term_id && !m.edge_exists).length > 1 ? 'them' : 'it'} to the knowledge graph.
            </Typography>
          </Alert>
        )}

        {mappings.filter((m: any) => m.override && !m.semantic_term_id).length > 0 && (
          <Alert severity="info" sx={{ mb: 3 }}>
            <Typography variant="body2" sx={{ fontWeight: 600 }}>ℹ️ Override in Progress</Typography>
            <Typography variant="body2" sx={{ mt: 0.5 }}>
              {mappings.filter((m: any) => m.override && !m.semantic_term_id).length} mapping{mappings.filter((m: any) => m.override && !m.semantic_term_id).length > 1 ? 's are' : ' is'} in override mode.
              Type a semantic term name or select from suggestions, then create or apply the term.
            </Typography>
          </Alert>
        )}

        {mappings.filter((m: any) => m.override).length > 0 && (
          <Alert severity="warning" sx={{ mb: 3 }}>
            <Typography variant="body2" sx={{ fontWeight: 600 }}>Override Mode Active</Typography>
            <Typography variant="body2" sx={{ mt: 0.5 }}>
              {mappings.filter((m: any) => m.override).length} mapping{mappings.filter((m: any) => m.override).length > 1 ? 's' : ''} currently in override mode.
              These mappings will use custom semantic terms instead of automated suggestions. Review and confirm changes before creating edges.
            </Typography>
          </Alert>
        )}

      <Box sx={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
        {/* Global Header */}
        <Box sx={{ 
          p: 2, 
          pb: 0,
          display: 'flex', 
          justifyContent: 'space-between', 
          alignItems: 'center',
          borderBottom: 1, 
          borderColor: 'divider',
          bgcolor: 'background.paper',
          gap: 4
        }}>
          {/* Tabs */}
          <Tabs 
            value={activeTab} 
            onChange={(_, newValue) => setActiveTab(newValue)} 
            aria-label="semantic mapper tabs"
            sx={{
              '& .MuiTab-root': {
                textTransform: 'none',
                fontWeight: 600,
                fontSize: '0.95rem',
                minHeight: 48,
                px: 3,
                color: '#64748b',
                '&.Mui-selected': {
                  color: '#2563eb',
                },
              },
              '& .MuiTabs-indicator': {
                height: 3,
                borderRadius: '3px 3px 0 0',
                backgroundColor: '#2563eb',
              }
            }}
          >
            <Tab 
              label="Scan"
              icon={<ScanSearch width={18} height={18} />}
              iconPosition="start"
            />
            <Tab 
              label="Profile"
              icon={<BarChart3 width={18} height={18} />}
              iconPosition="start"
            />
            <Tab 
              label="Semantics"
              icon={<Tag width={18} height={18} />}
              iconPosition="start"
            />
            <Tab 
              label="Business"
              icon={<Briefcase width={18} height={18} />}
              iconPosition="start"
            />
          </Tabs>

          {/* Right Side: Search & Wizard */}
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, flex: 1, justifyContent: 'flex-end', mb: 1 }}>
            <Box sx={{ width: '100%', maxWidth: 400 }}>
              <ProfessionalSearchInput
                value={globalSearchTerm}
                onChange={setGlobalSearchTerm}
                onClear={() => setGlobalSearchTerm('')}
                placeholder={
                  activeTab === 0 ? "Search schemas, tables, columns..." :
                  activeTab === 2 ? "Search mappings, columns, semantic terms..." :
                  activeTab === 3 ? "Search business terms..." :
                  "Search..."
                }
                mode="suggestions"
                suggestions={activeTab === 2 ? suggestions : []}
                showSuggestions={activeTab === 2 && showSuggestions}
                highlightedIndex={activeTab === 2 ? highlightedIndex : -1}
                onSuggestionSelect={handleSuggestionSelect}
                onHighlightChange={setHighlightedIndex}
                onFocus={handleSearchFocus}
                onBlur={handleSearchBlur}
                inputRef={searchInputRef}
                size="sm"
                variant="enhanced"
                navigationEnabled={activeTab === 2}
                currentMatch={currentMatchIndex}
                totalMatches={activeTab === 2 ? filteredMappings.length : undefined}
                onNavigateMatch={handleNavigateMatch}
              />
            </Box>

            {onOpenWizard && (
              <Button
                onClick={onOpenWizard}
                variant="contained"
                size="small"
                startIcon={<Wand2 width={16} height={16} />}
                sx={{
                  borderRadius: 2,
                  textTransform: 'none',
                  whiteSpace: 'nowrap',
                  fontWeight: 600,
                  height: 40,
                  background: 'linear-gradient(135deg, #8b5cf6 0%, #7c3aed 100%)',
                  boxShadow: '0 4px 12px rgba(139, 92, 246, 0.3)',
                  '&:hover': {
                    background: 'linear-gradient(135deg, #7c3aed 0%, #6d28d9 100%)',
                    boxShadow: '0 6px 16px rgba(139, 92, 246, 0.4)',
                  }
                }}
              >
                Open AI Wizard
              </Button>
            )}
          </Box>
        </Box>

        {/* Tab Content Panels */}
        <Box sx={{ flex: 1, overflow: 'hidden', p: 3 }}>
        <TabPanel value={activeTab} index={0}>
          <DbScanner
            refreshMappings={loadMappings}
            registerRunScan={(fn: any) => { runScanRef.current = fn; (window as any).runScanRef = runScanRef }}
            onProfile={(schemaName: string | null, tableName: string | null, tableNames?: string[]) => {
              setProfileSchema(schemaName);
              setProfileTable(tableName);
              setProfileTables(tableNames ?? null);
              setActiveTab(1); // switch to Profile tab
            }}
            searchTerm={globalSearchTerm}
          />
        </TabPanel>
        <TabPanel value={activeTab} index={1}>
          <ProfilerPage preselectedSchema={profileSchema} preselectedTable={profileTable} preselectedTables={profileTables} />
        </TabPanel>
        <TabPanel value={activeTab} index={2}>
          <SemanticMapperHeader
            loading={loading}
            loadMappings={loadMappings}
            filteredMappingsCount={filteredMappings.length}
            selectedMappingsCount={selectedMappings.size}
            highConfidenceCount={highConfidenceCount}
            pendingCount={mappingCounts.pending}
            averageScore={averageConfidence * 100}
            hasScopeFilter={scope.schemaNames.length > 0 || scope.tableNames.length > 0 || scope.columnNames.length > 0}
            sortBy={sortBy}
            setSortBy={setSortBy}
            openConfirm={openConfirm}
            mappedFilter={mappedFilter}
            setMappedFilter={setMappedFilter}
            mappingCounts={mappingCounts}
          />

          <Box sx={{ display: 'flex', gap: 3, alignItems: 'flex-start' }}>
            <DatabaseTreePanel
              title="Database Browser"
              subtitle="Matches by schema and table"
              showSchemaSelection={false}
              showTableSelection={false}
              showColumnSelection={false}
              showColumns={false}
              initialSelectedSchemas={scope.schemaNames}
              initialSelectedTables={scope.tableNames}
              initialSelectedColumns={scope.columnNames}
              mappedFilter={mappedFilter}
              setMappedFilter={setMappedFilter}
              mappingCounts={mappingCounts}
              mappings={mappings}
            />

            <Box sx={{ flex: 1, minHeight: '70vh', maxHeight: '80vh', overflow: 'auto' }}>
              {loading && mappings.length === 0 ? (
                <Card sx={{ p: 6, textAlign: 'center', borderRadius: 2 }} elevation={2}>
                  <RefreshCw className="animate-spin" width={48} height={48} style={{ margin: '0 auto 16px', color: '#1976d2' }} />
                  <Typography variant="h6" color="text.secondary">Loading mappings...</Typography>
                </Card>
              ) : (
                <MappingList
                  loading={loading}
                  mappings={filteredMappings}
                  savedRows={savedRows}
                  compactRows={compactRows}
                  keyboardExpanded={false}
                  setKeyboardExpanded={() => {}}
                  toggleMapping={toggleMapping}
                  confirmEditing={confirmEditing}
                  searchSemanticTerms={searchSemanticTerms}
                  selectSemanticTerm={(term: SemanticTerm, id: string) => {
                    updateMappings((prev: Mapping[]) => prev.map((m: Mapping) => {
                      if (getUniqueId(m) === id) {
                        // Preserve the entire database_column object with tenant info
                        return { 
                          ...m,
                          database_column: { ...m.database_column }, // Preserve tenant_id and tenant_datasource_id
                          semantic_term: term.term_name, 
                          semantic_term_id: term.node_id, 
                          is_new_term: false, 
                          confidence: 1.0, 
                          override: true, 
                          selected: true,
                          edge_exists: false // Will be updated after creating edge
                        };
                      }
                      return m;
                    }));
                    setToast({ type: 'success', message: `Applied semantic term "${term.term_name}". Click "Create Edges" to persist the mapping.` });
                  }}
                  handleCreateAndSelectTerm={async (id: string, name: string) => { 
                    const t = await createNewSemanticTerm(name); 
                    if (t) { 
                      updateMappings((prev: Mapping[]) => prev.map((m: Mapping) => {
                        if (getUniqueId(m) === id) {
                          // Preserve the entire database_column object with tenant info
                          return { 
                            ...m,
                            database_column: { ...m.database_column }, // Preserve tenant_id and tenant_datasource_id
                            semantic_term: t.term_name || name.toUpperCase(), 
                            semantic_term_id: t.node_id || '', 
                            is_new_term: true, 
                            confidence: 1.0, 
                            override: true, 
                            selected: true,
                            edge_exists: false // Mark as not yet persisted
                          };
                        }
                        return m;
                      })); 
                      setToast({ type: 'success', message: `Created semantic term "${t.term_name}". Click "Create Edges" to persist the mapping.` });
                    } 
                    return t; 
                  }}
                  setOverride={setOverride}
                  setIgnored={(id: string, val: boolean) => { setIgnored(id, val); if (val) { const mapping = mappings.find((m: any) => getUniqueId(m) === id); if (mapping) persistIgnores([mapping]); } }}
                  openReplaceConfirm={openReplaceConfirm}
                  openLineageModal={(mapping: Mapping) => { 
                    const asset = { 
                      type: 'table', 
                      id: `${mapping.database_column.schema || 'public'}.${mapping.database_column.table}`, 
                      name: `${mapping.database_column.schema || 'public'}.${mapping.database_column.table}`, 
                      qualifiedPath: `${mapping.database_column.schema || 'public'}.${mapping.database_column.table}`, 
                      isCore: false 
                    }; 
                    setLineageSelectedAsset(asset); 
                    setLineageDatasourceId(mapping.database_column?.tenant_datasource_id || ''); 
                    setLineageModalOpen(true); 
                  }}
                />
              )}
            </Box>
          </Box>
        </TabPanel>
        <TabPanel value={activeTab} index={3}>
          <BusinessTermMapper />
        </TabPanel>
      </Box> {/* Close Content Panels */}
      </Box> {/* Close Global Wrapper */}
    </Box> {/* Close outer Box */}
    </Box> {/* Close maxWidth Box */}

    {toast && (
      <Box className={`toast ${toast?.type === 'success' ? 'toast-success' : 'toast-error'}`} role="status" aria-live="polite">
        <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <Typography variant="body2" fontWeight={600}>{toast?.message}</Typography>
          <Button onClick={() => setToast(null)} size="small" className="toast-dismiss">Dismiss</Button>
        </Box>
      </Box>
    )}

    {/* Confirmation Dialogs */}
    <ConfirmationDialogs
      confirmOpen={confirmOpen}
      closeConfirm={closeConfirm}
      confirmCreate={confirmCreate}
      replaceConfirmOpen={replaceConfirmOpen}
      closeReplaceConfirm={closeReplaceConfirm}
      confirmReplace={confirmReplace}
      selectedCount={selectedMappings.size}
    />

    {/* Lineage Modal */}
    <LineageModal
      open={lineageModalOpen}
      onClose={() => setLineageModalOpen(false)}
      selectedAsset={lineageSelectedAsset}
      lineageData={lineageData}
      loading={false}
    />

    {/* AI Wizard */}
    <Dialog
      open={wizardOpen}
      onClose={() => setWizardOpen(false)}
      maxWidth="lg"
      fullWidth
      PaperProps={{
        sx: { height: '90vh', display: 'flex', flexDirection: 'column' }
      }}
    >
      <SemanticMappingWizard 
        tenantId={tenant?.id || ''} 
        datasourceId={datasource?.id || ''} 
        onClose={() => { 
            setWizardOpen(false); 
            loadMappings(); 
            if (activeTab !== 2) setActiveTab(2);
        }}
        onMappingsApplied={() => {
            // Refresh mappings to show newly created semantic terms in sidebar
            loadMappings();
        }}
      />
    </Dialog>
    </Fragment>
  );
}

import React, { useState, useEffect } from 'react';
import {
  Box,
  Button,
  Stepper,
  Step,
  StepLabel,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Checkbox,
  Chip,
  CircularProgress,
  Alert,
  TextField,
  IconButton,
  LinearProgress,
} from '@mui/material';
import { gql, useMutation } from '@apollo/client';
import SearchIcon from '@mui/icons-material/Search';
import AutoFixHighIcon from '@mui/icons-material/AutoFixHigh';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import PendingIcon from '@mui/icons-material/Pending';
import EditIcon from '@mui/icons-material/Edit';
import CheckIcon from '@mui/icons-material/Check';
import CloseIcon from '@mui/icons-material/Close';
import { devDebug } from '../utils/devLogger';

const STEPS = ['Scan & Expand', 'Generate Mappings', 'Review Auto-Created', 'Approve Pending', 'Summary'];

interface GeneratedMapping {
  column_id: string;
  column_name: string;
  table_name?: string;
  expanded_column_name: string;
  suggested_semantic_term: string;
  suggested_business_term: string;
  semantic_type?: string; // dimension, measure, time_dimension
  confidence: number;
  reasoning: string;
  will_auto_create: boolean;
  needs_approval: boolean;
}

interface PendingMapping {
  id: string;
  column_name: string;
  expanded_column_name: string;
  suggested_semantic_term: string;
  suggested_business_term: string;
  confidence: number;
  reasoning: string;
}

interface SemanticMappingWizardProps {
  tenantId: string;
  datasourceId: string;
  onClose: () => void;
  onMappingsApplied?: () => void; // Callback to refresh sidebar/catalog after mappings are applied
}

const LOG_TERM_FEEDBACK = gql`
  mutation LogTermAISuggestionFeedback($input: LogTermFeedbackInput!) {
    logTermAISuggestionFeedback(input: $input)
  }
`;

export const SemanticMappingWizard: React.FC<SemanticMappingWizardProps> = ({
  tenantId,
  datasourceId,
  onClose,
  onMappingsApplied,
}) => {

  const [activeStep, setActiveStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [progressMessage, setProgressMessage] = useState<string>('');

  // Manual approval and rejection state
  const [manualApprovals, setManualApprovals] = useState<Set<string>>(new Set());
  const [rejectedMappings, setRejectedMappings] = useState<Set<string>>(new Set());

  // Simulated progress simulation for better UX
  const [progressSteps, setProgressSteps] = useState([
    { label: "Scanning database columns", status: 'waiting' },
    { label: "Identifying abbreviations", status: 'waiting' },
    { label: "Expanding table names", status: 'waiting' },
    { label: "Consulting AI knowledge base", status: 'waiting' },
    { label: "Generating semantic terms", status: 'waiting' },
    { label: "Calculating confidence scores", status: 'waiting' },
    { label: "Finalizing suggestions", status: 'waiting' }
  ]);

  // Feedback logging mutation
  const [logTermFeedback] = useMutation(LOG_TERM_FEEDBACK, {
    onError: (e) => console.error('Failed to log feedback:', e)
  });

  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (loading) {
      let stepIndex = 0;

      // Reset steps
      setProgressSteps(prev => prev.map(s => ({ ...s, status: 'waiting' })));

      const updateSteps = () => {
        setProgressSteps(prev => prev.map((s, i) => {
          if (i < stepIndex) return { ...s, status: 'completed' };
          if (i === stepIndex) return { ...s, status: 'active' };
          return { ...s, status: 'waiting' };
        }));

        stepIndex++;
        if (stepIndex >= 7) { 
           // keep the last one active or completed until loading finishes
           // actually let's just loop the last few if it takes longer, or just hold at verifying
        }
      };

      updateSteps(); // Initial state
      interval = setInterval(() => {
        if (stepIndex < 7) {
            updateSteps();
        }
      }, 800); // 800ms per step for a ~5-6s total animation which feels "fast but real"
    }
    return () => clearInterval(interval);
  }, [loading]);

  // Step 1 & 2: Generated mappings
  const [mappings, setMappings] = useState<GeneratedMapping[]>([]);
  const [totalColumns, setTotalColumns] = useState(0);

  // Step 3: Auto-created results
  const [autoCreatedCount, setAutoCreatedCount] = useState(0);
  const [autoCreatedMappings, setAutoCreatedMappings] = useState<GeneratedMapping[]>([]);

  // Step 4: Pending approvals
  const [pendingMappings, setPendingMappings] = useState<PendingMapping[]>([]);
  const [selectedPending, setSelectedPending] = useState<Set<string>>(new Set());

  // Step 5: Summary
  const [summary, setSummary] = useState({
    auto_created: 0,
    pending_approval: 0,
    skipped: 0,
    errors: 0,
  });

  // Created mappings to display
  const [createdMappings, setCreatedMappings] = useState<any[]>([]);

  // Sort and search state for mappings table
  const [mappingsSortField, setMappingsSortField] = useState<'table' | 'column' | 'expanded' | 'term' | 'confidence'>('column');
  const [mappingsSortOrder, setMappingsSortOrder] = useState<'asc' | 'desc'>('asc');
  const [mappingsSearchTerm, setMappingsSearchTerm] = useState('');

  const handleGenerateMappings = async () => {
    if (!tenantId || !datasourceId) {
      setError("Missing tenant or datasource context. Please select a tenant and datasource.");
      return;
    }

    setLoading(true);
    setError(null);

    // Debug: log what we're sending
    devDebug('[Wizard] Sending request with:', { tenant_id: tenantId, datasource_id: datasourceId });

    try {
      const response = await fetch('/api/semantic-mapping/wizard/generate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ tenant_id: tenantId, datasource_id: datasourceId }),
      });

      if (!response.ok) {
        const text = await response.text();
        console.error('[Wizard] API error:', text);
        throw new Error(`Failed to generate mappings: ${text}`);
      }

      const data = await response.json();
      devDebug('[Wizard] Success! Received:', data);
      setMappings(data.mappings || []);
      setTotalColumns(data.total_columns || 0);
      setMappingsSearchTerm(''); // Reset search
      setMappingsSortField('column'); // Reset sort
      setActiveStep(1);
    } catch (err: any) {
      console.error('[Wizard] Error:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleRejectMapping = async (mapping: GeneratedMapping) => {
    try {
      // Call backend to ignore this column-term pair
      await fetch('/api/semantic-mappings/ignore', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          tenant_id: tenantId,
          datasource_id: datasourceId,
          column_id: mapping.column_id,
          semantic_term: mapping.suggested_semantic_term,
          reason: 'user_rejected'
        })
      });

      // Remove from local state
      setRejectedMappings(prev => new Set(prev).add(mapping.column_id));

      // Log rejection feedback
      logTermFeedback({
        variables: {
          input: {
            tenantId,
            datasourceId,
            termId: "", // No term created yet
            nodeId: mapping.column_id, // Use column ID as related node
            suggestionId: mapping.column_id + "_suggestion", // Synthesis ID since we don't have explicit one
            action: 'rejected',
            reason: 'manual_rejection',
            features: {
                semantic_term: mapping.suggested_semantic_term,
                business_term: mapping.suggested_business_term,
                column_name: mapping.column_name,
                confidence: mapping.confidence
            }
          }
        }
      });
    } catch (error) {
      console.error('Failed to reject mapping:', error);
    }
  };

  const handleApplyMappings = async () => {
    setLoading(true);
    setError(null);

    // Separate mappings by decision
    const approvedMappings = mappings.filter(m => 
      m.confidence >= 0.85 || manualApprovals.has(m.column_id)
    );

    const rejectedMappingsList = mappings.filter(m => 
      rejectedMappings.has(m.column_id)
    );

    const noDecisionMappings = mappings.filter(m => 
      m.confidence < 0.85 && 
      !manualApprovals.has(m.column_id) && 
      !rejectedMappings.has(m.column_id)
    );

    // Adjust confidence for manually approved items
    const adjustedMappings = [
      ...approvedMappings.map(m => ({ ...m, confidence: 0.85 })),
      ...noDecisionMappings
    ];

    try {
      const response = await fetch('/api/semantic-mapping/wizard/apply', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          tenant_id: tenantId,
          datasource_id: datasourceId,
          auto_create_threshold: 0.85,
          approval_threshold: 0.60,
          mappings: adjustedMappings,
        }),
      });

      if (!response.ok) throw new Error('Failed to apply mappings');

      const data = await response.json();
      setSummary(data);
      setAutoCreatedCount(data.auto_created);
      setAutoCreatedMappings(adjustedMappings.filter(m => m.confidence >= 0.85));

      // Fetch created mappings to show results
      await fetchCreatedMappings();

      // Fetch pending approvals
      await fetchPendingApprovals();

      // Trigger sidebar refresh if callback provided
      if (onMappingsApplied) {
        onMappingsApplied();
      }

      setActiveStep(2);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const fetchPendingApprovals = async () => {
    try {
      const response = await fetch(
        `/api/semantic-mapping/wizard/pending?tenant_id=${tenantId}&datasource_id=${datasourceId}`
      );

      if (!response.ok) throw new Error('Failed to fetch pending approvals');

      const data = await response.json();
      setPendingMappings(data.pending_approvals || []);
    } catch (err: any) {
      console.error('Failed to fetch pending approvals:', err);
    }
  };

  const fetchCreatedMappings = async () => {
    try {
      const response = await fetch(
        `/api/semantic-mapping/wizard/created?tenant_id=${tenantId}&datasource_id=${datasourceId}&limit=20`
      );

      if (response.ok) {
        const data = await response.json();
        setCreatedMappings(data.mappings || []);
      }
    } catch (err: any) {
      console.error('Failed to fetch created mappings:', err);
    }
  };

  const handleApprovePending = async (mappingId: string, approved: boolean) => {
    try {
      const response = await fetch(`/api/semantic-mapping/wizard/approve/${mappingId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ approved, user_id: 'current-user' }),
      });

      if (!response.ok) throw new Error('Failed to approve/reject mapping');

      const data = await response.json();
      const termId = data.term_id || "";

      // Log feedback
      logTermFeedback({
        variables: {
          input: {
            tenantId,
            datasourceId,
            termId: termId, // Use returned term ID (empty if rejected)
             // Use mapping ID as weak node_id reference, though it's the PENDING mapping ID
            suggestionId: mappingId, 
            action: approved ? 'approved' : 'rejected',
            features: {
                mapping_id: mappingId,
                approved: approved
            }
          }
        }
      });

      // Remove from pending list
      setPendingMappings(prev => prev.filter(m => m.id !== mappingId));
      setSelectedPending(prev => {
        const newSet = new Set(prev);
        newSet.delete(mappingId);
        return newSet;
      });
    } catch (err: any) {
      setError(err.message);
    }
  };

  const handleBulkApprove = async () => {
    setLoading(true);
    for (const id of selectedPending) {
      await handleApprovePending(id, true);
    }
    setLoading(false);
    setActiveStep(4);
  };

  const getConfidenceBadge = (confidence: number) => {
    if (confidence >= 0.85) {
      return <Chip label={`${(confidence * 100).toFixed(0)}%`} color="success" size="small" />;
    } else if (confidence >= 0.60) {
      return <Chip label={`${(confidence * 100).toFixed(0)}%`} color="warning" size="small" />;
    } else {
      return <Chip label={`${(confidence * 100).toFixed(0)}%`} color="error" size="small" />;
    }
  };

  const renderScanStep = () => (
    <Box sx={{ textAlign: 'center', py: 4, maxWidth: 600, mx: 'auto' }}>
      <SearchIcon sx={{ 
        fontSize: 60, 
        color: loading ? 'primary.main' : 'text.secondary', 
        mb: 2,
        animation: loading ? 'spin 2s linear infinite' : 'none',
        '@keyframes spin': {
          '0%': { transform: 'rotate(0deg)' },
          '100%': { transform: 'rotate(360deg)' },
        },
      }} />
      <Typography variant="h6" gutterBottom>
        Scan Database & Generate Semantic Mappings
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 4 }}>
        This will scan all unmapped columns, expand abbreviations, and use AI to suggest semantic terms.
      </Typography>

      <Box sx={{ width: '100%', mb: 3, minHeight: '60px', bgcolor: 'grey.50', p: 2, borderRadius: 1, border: '1px dashed', borderColor: 'grey.300' }}>
        {error ? (
          <Alert severity="error">{error}</Alert>
        ) : loading ? (
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
            <Typography variant="body2" fontWeight="bold" color="primary" sx={{ mb: 1 }}>
              Running Analysis...
            </Typography>
            {progressSteps.map((step, index) => (
              <Box key={index} sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                 {step.status === 'completed' && <CheckIcon color="success" fontSize="small" />}
                 {step.status === 'active' && <CircularProgress size={14} thickness={5} />}
                 {step.status === 'waiting' && <Box sx={{ width: 14, height: 14, borderRadius: '50%', border: '1px solid', borderColor: 'text.disabled' }} />}

                 <Typography 
                   variant="caption" 
                   sx={{ 
                     color: step.status === 'active' ? 'text.primary' : step.status === 'completed' ? 'text.secondary' : 'text.disabled',
                     fontWeight: step.status === 'active' ? 600 : 400
                   }}
                 >
                   {step.label}
                 </Typography>
              </Box>
            ))}
          </Box>
        ) : (
          <Typography variant="body2" color="text.secondary" sx={{ fontStyle: 'italic', textAlign: 'center', py: 2 }}>
            Ready to scan. Click the button below to start.
          </Typography>
        )}
      </Box>

      <Button 
        variant="contained" 
        onClick={handleGenerateMappings} 
        disabled={loading}
        size="large"
      >
        {loading ? 'Scanning & Generating...' : 'Start Scan'}
      </Button>
    </Box>
  );

  const renderMappingsReview = () => {
    // Filter out rejected mappings
    const visibleMappings = mappings.filter(m => !rejectedMappings.has(m.column_id));

    // Apply search filter
    const searchLower = mappingsSearchTerm.toLowerCase();
    const searchedMappings = visibleMappings.filter(m =>
      m.table_name?.toLowerCase().includes(searchLower) ||
      m.column_name?.toLowerCase().includes(searchLower) ||
      m.expanded_column_name?.toLowerCase().includes(searchLower) ||
      m.suggested_semantic_term?.toLowerCase().includes(searchLower)
    );

    // Apply sorting
    const sortedMappings = [...searchedMappings].sort((a, b) => {
      let aVal: string | number = '';
      let bVal: string | number = '';

      switch (mappingsSortField) {
        case 'table':
          aVal = (a.table_name || '').toLowerCase();
          bVal = (b.table_name || '').toLowerCase();
          break;
        case 'column':
          aVal = (a.column_name || '').toLowerCase();
          bVal = (b.column_name || '').toLowerCase();
          break;
        case 'expanded':
          aVal = (a.expanded_column_name || '').toLowerCase();
          bVal = (b.expanded_column_name || '').toLowerCase();
          break;
        case 'term':
          aVal = (a.suggested_semantic_term || '').toLowerCase();
          bVal = (b.suggested_semantic_term || '').toLowerCase();
          break;
        case 'confidence':
          aVal = a.confidence || 0;
          bVal = b.confidence || 0;
          break;
      }

      if (typeof aVal === 'string' && typeof bVal === 'string') {
        return mappingsSortOrder === 'asc' ? aVal.localeCompare(bVal) : bVal.localeCompare(aVal);
      } else {
        return mappingsSortOrder === 'asc' ? (aVal > bVal ? 1 : -1) : (bVal > aVal ? 1 : -1);
      }
    });

    const handleSortClick = (field: 'table' | 'column' | 'expanded' | 'term' | 'confidence') => {
      if (mappingsSortField === field) {
        setMappingsSortOrder(mappingsSortOrder === 'asc' ? 'desc' : 'asc');
      } else {
        setMappingsSortField(field);
        setMappingsSortOrder('asc');
      }
    };

    return (
      <Box>
        <Typography variant="h6" gutterBottom>
          Generated Mappings ({sortedMappings.length} columns)
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          Review the AI-generated semantic term suggestions. Click column headers to sort, use search to filter.
        </Typography>

        {/* Typeahead Search */}
        <TextField
          placeholder="Search by table, column, expanded name, or semantic term..."
          size="small"
          fullWidth
          value={mappingsSearchTerm}
          onChange={(e) => setMappingsSearchTerm(e.target.value)}
          sx={{ mb: 2 }}
          InputProps={{
            startAdornment: (
              <Box sx={{ mr: 1, display: 'flex', alignItems: 'center' }}>
                🔍
              </Box>
            ),
          }}
        />

        <TableContainer component={Paper} sx={{ maxHeight: 600 }}>
          <Table stickyHeader size="small">
            <TableHead>
              <TableRow sx={{ backgroundColor: 'action.hover' }}>
                <TableCell 
                  onClick={() => handleSortClick('table')}
                  sx={{ cursor: 'pointer', fontWeight: 'bold', userSelect: 'none', '&:hover': { backgroundColor: 'action.selected' } }}
                >
                  Table {mappingsSortField === 'table' && (mappingsSortOrder === 'asc' ? '▲' : '▼')}
                </TableCell>
                <TableCell 
                  onClick={() => handleSortClick('column')}
                  sx={{ cursor: 'pointer', fontWeight: 'bold', userSelect: 'none', '&:hover': { backgroundColor: 'action.selected' } }}
                >
                  Column {mappingsSortField === 'column' && (mappingsSortOrder === 'asc' ? '▲' : '▼')}
                </TableCell>
                <TableCell 
                  onClick={() => handleSortClick('expanded')}
                  sx={{ cursor: 'pointer', fontWeight: 'bold', userSelect: 'none', '&:hover': { backgroundColor: 'action.selected' } }}
                >
                  Expanded {mappingsSortField === 'expanded' && (mappingsSortOrder === 'asc' ? '▲' : '▼')}
                </TableCell>
                <TableCell 
                  onClick={() => handleSortClick('term')}
                  sx={{ cursor: 'pointer', fontWeight: 'bold', userSelect: 'none', '&:hover': { backgroundColor: 'action.selected' } }}
                >
                  Semantic Term {mappingsSortField === 'term' && (mappingsSortOrder === 'asc' ? '▲' : '▼')}
                </TableCell>
                <TableCell sx={{ fontWeight: 'bold' }}>Type</TableCell>
                <TableCell 
                  onClick={() => handleSortClick('confidence')}
                  sx={{ cursor: 'pointer', fontWeight: 'bold', userSelect: 'none', '&:hover': { backgroundColor: 'action.selected' } }}
                  align="center"
                >
                  Confidence {mappingsSortField === 'confidence' && (mappingsSortOrder === 'asc' ? '▲' : '▼')}
                </TableCell>
                <TableCell sx={{ fontWeight: 'bold' }}>Decision</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {sortedMappings.map((mapping) => {
                // Determine current decision state
                let currentDecision = 'none';
                if (mapping.confidence >= 0.85) {
                  currentDecision = 'approve'; // Auto-approved
                } else if (manualApprovals.has(mapping.column_id)) {
                  currentDecision = 'approve';
                } else if (rejectedMappings.has(mapping.column_id)) {
                  currentDecision = 'reject';
                }

                return (
                  <TableRow key={mapping.column_id} hover>
                    <TableCell sx={{ fontWeight: 500, color: 'text.secondary' }}>
                      {mapping.table_name || 'N/A'}
                    </TableCell>
                    <TableCell>{mapping.column_name}</TableCell>
                    <TableCell>{mapping.expanded_column_name}</TableCell>
                    <TableCell>
                      <TextField
                        size="small"
                        variant="standard"
                        value={mapping.suggested_semantic_term}
                        onChange={(e) => {
                          const newValue = e.target.value.toUpperCase(); // Force uppercase
                          setMappings(prev => prev.map(m => 
                            m.column_id === mapping.column_id 
                              ? { ...m, suggested_semantic_term: newValue, confidence: 1.0 } 
                              : m
                          ));
                          // Auto-approve
                          setManualApprovals(prev => new Set(prev).add(mapping.column_id));
                          setRejectedMappings(prev => {
                            const next = new Set(prev);
                            next.delete(mapping.column_id);
                            return next;
                          });
                        }}
                        sx={{ minWidth: 200 }}
                      />
                    </TableCell>
                    <TableCell>
                      <Chip 
                        label={mapping.semantic_type || 'dimension'}
                        size="small"
                        color={mapping.semantic_type === 'measure' ? 'primary' : mapping.semantic_type === 'time_dimension' ? 'secondary' : 'default'}
                        variant="outlined"
                      />
                    </TableCell>
                    <TableCell align="center">{getConfidenceBadge(mapping.confidence)}</TableCell>
                    <TableCell>
                      {mapping.confidence >= 0.85 ? (
                        <Chip label="Auto-Approved" color="success" size="small" icon={<CheckCircleIcon />} />
                      ) : (
                        <Box sx={{ display: 'flex', gap: 0.5 }}>
                          <Button
                            size="small"
                            variant={currentDecision === 'approve' ? 'contained' : 'outlined'}
                            color="success"
                            onClick={() => {
                              const newApprovals = new Set(manualApprovals);
                              const newRejections = new Set(rejectedMappings);
                              newApprovals.add(mapping.column_id);
                              newRejections.delete(mapping.column_id);
                              setManualApprovals(newApprovals);
                              setRejectedMappings(newRejections);
                            }}
                            sx={{ minWidth: '70px' }}
                          >
                            Approve
                          </Button>
                          <Button
                            size="small"
                            variant={currentDecision === 'reject' ? 'contained' : 'outlined'}
                            color="error"
                            onClick={() => {
                              handleRejectMapping(mapping);
                              const newApprovals = new Set(manualApprovals);
                              newApprovals.delete(mapping.column_id);
                              setManualApprovals(newApprovals);
                            }}
                            sx={{ minWidth: '70px' }}
                          >
                            Reject
                          </Button>
                          <Button
                            size="small"
                            variant={currentDecision === 'none' ? 'contained' : 'outlined'}
                            color="inherit"
                            onClick={() => {
                              const newApprovals = new Set(manualApprovals);
                              const newRejections = new Set(rejectedMappings);
                              newApprovals.delete(mapping.column_id);
                              newRejections.delete(mapping.column_id);
                              setManualApprovals(newApprovals);
                              setRejectedMappings(newRejections);
                            }}
                            sx={{ minWidth: '70px' }}
                          >
                            None
                          </Button>
                        </Box>
                      )}
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </TableContainer>

        {sortedMappings.length === 0 && mappingsSearchTerm && (
          <Typography variant="body2" color="text.secondary" sx={{ mt: 2, textAlign: 'center' }}>
            No mappings match your search.
          </Typography>
        )}

        <Box sx={{ mt: 3, display: 'flex', justifyContent: 'space-between' }}>
          <Button onClick={() => setActiveStep(0)}>Back</Button>
          <Button 
            variant="contained" 
            onClick={handleApplyMappings}
            disabled={loading}
          >
            {loading ? 'Applying...' : 'Apply Mappings'}
          </Button>
        </Box>
      </Box>
    );
  };

  const renderAutoCreatedReview = () => (
    <Box>
      <Typography variant="h6" gutterBottom>
        Auto-Created Semantic Terms ({autoCreatedCount})
      </Typography>
      <Alert severity="success" sx={{ mb: 2 }}>
        {autoCreatedCount} semantic terms were automatically created with high confidence (≥85%).
      </Alert>

      <TableContainer component={Paper} sx={{ maxHeight: 300, mb: 3 }}>
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell>Column</TableCell>
              <TableCell>Semantic Term</TableCell>
              <TableCell>Confidence</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {autoCreatedMappings.map((mapping) => (
              <TableRow key={mapping.column_id}>
                <TableCell>{mapping.column_name}</TableCell>
                <TableCell>{mapping.suggested_semantic_term}</TableCell>
                <TableCell>{getConfidenceBadge(mapping.confidence)}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 2 }}>
        {pendingMappings.length > 0 ? (
          <Button variant="contained" onClick={() => setActiveStep(3)}>
            Review Pending Approvals ({pendingMappings.length})
          </Button>
        ) : (
          <Button variant="contained" color="success" onClick={() => setActiveStep(4)}>
            Finish & View Summary
          </Button>
        )}
      </Box>
    </Box>
  );

  const renderPendingApprovals = () => (
    <Box>
      <Typography variant="h6" gutterBottom>
        Pending Approvals ({pendingMappings.length})
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        These mappings have medium confidence (60-84%) and require your approval.
      </Typography>

      <TableContainer component={Paper} sx={{ maxHeight: 400 }}>
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell padding="checkbox">
                <Checkbox
                  checked={selectedPending.size === pendingMappings.length && pendingMappings.length > 0}
                  onChange={(e) => {
                    if (e.target.checked) {
                      setSelectedPending(new Set(pendingMappings.map(m => m.id)));
                    } else {
                      setSelectedPending(new Set());
                    }
                  }}
                />
              </TableCell>
              <TableCell>Column</TableCell>
              <TableCell>Semantic Term</TableCell>
              <TableCell>Confidence</TableCell>
              <TableCell>Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {pendingMappings.map((mapping) => (
              <TableRow key={mapping.id}>
                <TableCell padding="checkbox">
                  <Checkbox
                    checked={selectedPending.has(mapping.id)}
                    onChange={(e) => {
                      const newSet = new Set(selectedPending);
                      if (e.target.checked) {
                        newSet.add(mapping.id);
                      } else {
                        newSet.delete(mapping.id);
                      }
                      setSelectedPending(newSet);
                    }}
                  />
                </TableCell>
                <TableCell>{mapping.column_name}</TableCell>
                <TableCell>{mapping.suggested_semantic_term}</TableCell>
                <TableCell>{getConfidenceBadge(mapping.confidence)}</TableCell>
                <TableCell>
                  <IconButton 
                    size="small" 
                    color="success"
                    onClick={() => handleApprovePending(mapping.id, true)}
                  >
                    <CheckIcon />
                  </IconButton>
                  <IconButton 
                    size="small" 
                    color="error"
                    onClick={() => handleApprovePending(mapping.id, false)}
                  >
                    <CloseIcon />
                  </IconButton>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      <Box sx={{ mt: 3, display: 'flex', justifyContent: 'space-between' }}>
        <Button onClick={() => setActiveStep(2)}>Back</Button>
        <Box sx={{ display: 'flex', gap: 2 }}>
          <Button 
            onClick={onClose}
            color="secondary"
          >
            Save Pending & Close
          </Button>
          <Button 
            variant="contained" 
            onClick={handleBulkApprove}
            disabled={selectedPending.size === 0 || loading}
          >
            Approve Selected ({selectedPending.size})
          </Button>
        </Box>
      </Box>
    </Box>
  );

  const renderSummary = () => (
    <Box sx={{ textAlign: 'center', py: 4 }}>
      <CheckCircleIcon sx={{ fontSize: 60, color: 'success.main', mb: 2 }} />
      <Typography variant="h6" gutterBottom>
        Semantic Mapping Complete!
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        All changes have been saved. You can review pending items in the main grid.
      </Typography>

      <Box sx={{ mt: 3, display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: 2, maxWidth: 400, mx: 'auto' }}>
        <Paper sx={{ p: 2 }}>
          <Typography variant="h4" color="success.main">{summary.auto_created}</Typography>
          <Typography variant="body2">Auto-Created</Typography>
        </Paper>
        <Paper sx={{ p: 2 }}>
          <Typography variant="h4" color="warning.main">{summary.pending_approval}</Typography>
          <Typography variant="body2">Pending</Typography>
        </Paper>
        <Paper sx={{ p: 2 }}>
          <Typography variant="h4" color="text.secondary">{summary.skipped}</Typography>
          <Typography variant="body2">Skipped</Typography>
        </Paper>
        <Paper sx={{ p: 2 }}>
          <Typography variant="h4" color="error.main">{summary.errors}</Typography>
          <Typography variant="body2">Errors</Typography>
        </Paper>
      </Box>

      {createdMappings.length > 0 && (
        <Box sx={{ mt: 4, maxWidth: 800, mx: 'auto' }}>
          <Typography variant="h6" gutterBottom>Created Mappings (Latest {createdMappings.length})</Typography>
          <TableContainer component={Paper}>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Column</TableCell>
                  <TableCell>Semantic Term</TableCell>
                  <TableCell>Business Term</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {createdMappings.map((m, idx) => (
                  <TableRow key={idx}>
                    <TableCell>{m.column_name}</TableCell>
                    <TableCell>{m.semantic_term}</TableCell>
                    <TableCell>{m.business_term || '—'}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Box>
      )}

      <Button variant="contained" onClick={onClose} sx={{ mt: 4 }}>
        Close Wizard
      </Button>
    </Box>
  );

  const renderStepContent = () => {
    switch (activeStep) {
      case 0:
        return renderScanStep();
      case 1:
        return renderMappingsReview();
      case 2:
        return renderAutoCreatedReview();
      case 3:
        return renderPendingApprovals();
      case 4:
        return renderSummary();
      default:
        return null;
    }
  };

  return (
    <Box sx={{ width: '100%', p: 2, position: 'relative' }}>
      <IconButton 
        onClick={onClose} 
        sx={{ position: 'absolute', top: 0, right: 0, zIndex: 10 }}
        aria-label="close wizard"
      >
        <CloseIcon />
      </IconButton>

      <Stepper activeStep={activeStep} alternativeLabel sx={{ mb: 4, mt: 2 }}>
        {STEPS.map((label, index) => (
          <Step key={label} completed={index < activeStep}>
            <StepLabel 
              sx={{
                '& .MuiStepLabel-label': {
                  color: index === activeStep ? 'primary.main' : index < activeStep ? 'success.main' : 'text.secondary',
                  fontWeight: index === activeStep ? 'bold' : 'normal',
                },
                '& .MuiStepIcon-root': {
                  color: index < activeStep ? 'success.main' : undefined,
                  '&.Mui-active': {
                    color: 'primary.main',
                    animation: 'pulse 1.5s ease-in-out infinite',
                  },
                },
                '@keyframes pulse': {
                  '0%, 100%': { transform: 'scale(1)' },
                  '50%': { transform: 'scale(1.1)' },
                },
              }}
            >
              {label}
            </StepLabel>
          </Step>
        ))}
      </Stepper>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      <Paper sx={{ p: 3, minHeight: 400 }}>
        {renderStepContent()}
      </Paper>
    </Box>
  );
};

import React, { useState, useEffect } from 'react';
import { Play, Code, Download, TrendingUp, Calendar, Filter as FilterIcon, Plus, X } from 'lucide-react';

interface Cube {
  id: string;
  name: string;
  display_name: string;
  dimensions: Dimension[];
  measures: Measure[];
}

interface Dimension {
  name: string;
  display_name: string;
  type: string;
}

interface Measure {
  name: string;
  display_name: string;
  type: string;
}

interface QueryFilter {
  member: string;
  operator: string;
  values: string[];
}

const SemanticQueryBuilder: React.FC = () => {
  const [cubes, setCubes] = useState<Cube[]>([]);
  const [selectedCube, setSelectedCube] = useState<Cube | null>(null);
  const [selectedMeasures, setSelectedMeasures] = useState<string[]>([]);
  const [selectedDimensions, setSelectedDimensions] = useState<string[]>([]);
  const [filters, setFilters] = useState<QueryFilter[]>([]);
  const [timeDimension, setTimeDimension] = useState<string>('');
  const [timeGranularity, setTimeGranularity] = useState<string>('day');
  const [limit, setLimit] = useState<number>(100);
  const [queryResult, setQueryResult] = useState<any>(null);
  const [generatedSQL, setGeneratedSQL] = useState<string>('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchCubes();
  }, []);

  const fetchCubes = async () => {
    try {
      const response = await fetch('/api/semantic/cubes', {
        headers: { 'X-Tenant-ID': 'default-tenant' },
      });
      const data = await response.json();
      setCubes(data);
      if (data.length > 0) {
        setSelectedCube(data[0]);
      }
    } catch (error) {
      console.error('Failed to fetch cubes:', error);
    }
  };

  const executeQuery = async () => {
    if (!selectedCube || selectedMeasures.length === 0) return;

    setLoading(true);
    try {
      const query = {
        measures: selectedMeasures,
        dimensions: selectedDimensions,
        timeDimensions: timeDimension ? [{
          dimension: timeDimension,
          granularity: timeGranularity,
        }] : [],
        filters: filters,
        limit: limit,
      };

      const response = await fetch('/api/semantic/query', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Tenant-ID': 'default-tenant',
        },
        body: JSON.stringify(query),
      });

      const result = await response.json();
      setQueryResult(result);
      setGeneratedSQL(result.annotation?.generatedSQL || '');
    } catch (error) {
      console.error('Failed to execute query:', error);
    } finally {
      setLoading(false);
    }
  };

  const toggleMeasure = (measure: string) => {
    setSelectedMeasures(prev =>
      prev.includes(measure) ? prev.filter(m => m !== measure) : [...prev, measure]
    );
  };

  const toggleDimension = (dimension: string) => {
    setSelectedDimensions(prev =>
      prev.includes(dimension) ? prev.filter(d => d !== dimension) : [...prev, dimension]
    );
  };

  const addFilter = () => {
    setFilters([...filters, { member: '', operator: 'equals', values: [''] }]);
  };

  const removeFilter = (index: number) => {
    setFilters(filters.filter((_, i) => i !== index));
  };

  const updateFilter = (index: number, field: keyof QueryFilter, value: any) => {
    const newFilters = [...filters];
    newFilters[index] = { ...newFilters[index], [field]: value };
    setFilters(newFilters);
  };

  return (
    <div className="h-screen flex flex-col bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 dark:from-slate-900 dark:via-slate-800 dark:to-indigo-950">
      {/* Header */}
      <div className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-200 dark:border-slate-700 px-6 py-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-4">
            <div className="p-3 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-xl">
              <TrendingUp className="w-6 h-6 text-white" />
            </div>
            <div>
              <h1 className="text-2xl font-bold bg-gradient-to-r from-blue-600 to-indigo-600 bg-clip-text text-transparent">
                Query Builder
              </h1>
              <p className="text-sm text-slate-600 dark:text-slate-400">
                Build and execute semantic queries
              </p>
            </div>
          </div>

          <button
            onClick={executeQuery}
            disabled={loading || selectedMeasures.length === 0}
            className="flex items-center space-x-2 px-6 py-3 bg-gradient-to-r from-blue-500 to-indigo-600 text-white rounded-xl hover:shadow-lg transition-all disabled:opacity-50"
          >
            <Play className="w-5 h-5" />
            <span className="font-semibold">Run Query</span>
          </button>
        </div>
      </div>

      <div className="flex-1 flex overflow-hidden">
        {/* Left Panel - Query Builder */}
        <div className="w-1/3 border-r border-slate-200 dark:border-slate-700 overflow-y-auto p-6 space-y-6">
          {/* Cube Selector */}
          <div>
            <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">
              Data Source
            </label>
            <select
              value={selectedCube?.name || ''}
              onChange={(e) => {
                const cube = cubes.find(c => c.name === e.target.value);
                setSelectedCube(cube || null);
                setSelectedMeasures([]);
                setSelectedDimensions([]);
              }}
              className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              {cubes.map(cube => (
                <option key={cube.id} value={cube.name}>
                  {cube.display_name}
                </option>
              ))}
            </select>
          </div>

          {/* Measures */}
          <div>
            <h3 className="text-sm font-semibold text-slate-700 dark:text-slate-300 mb-3 flex items-center">
              <div className="w-2 h-2 bg-green-500 rounded-full mr-2"></div>
              Measures
            </h3>
            <div className="space-y-2">
              {selectedCube?.measures.map(measure => (
                <button
                  key={measure.name}
                  onClick={() => toggleMeasure(`${selectedCube.name}.${measure.name}`)}
                  className={`w-full text-left px-4 py-3 rounded-lg border-2 transition-all ${
                    selectedMeasures.includes(`${selectedCube.name}.${measure.name}`)
                      ? 'border-green-500 bg-green-50 dark:bg-green-950/20'
                      : 'border-slate-200 dark:border-slate-700 hover:border-green-300'
                  }`}
                >
                  <div className="font-medium text-slate-900 dark:text-white">{measure.display_name}</div>
                  <div className="text-xs text-slate-500 dark:text-slate-500">{measure.type}</div>
                </button>
              ))}
            </div>
          </div>

          {/* Dimensions */}
          <div>
            <h3 className="text-sm font-semibold text-slate-700 dark:text-slate-300 mb-3 flex items-center">
              <div className="w-2 h-2 bg-blue-500 rounded-full mr-2"></div>
              Dimensions
            </h3>
            <div className="space-y-2">
              {selectedCube?.dimensions.filter(d => d.type !== 'time').map(dimension => (
                <button
                  key={dimension.name}
                  onClick={() => toggleDimension(`${selectedCube.name}.${dimension.name}`)}
                  className={`w-full text-left px-4 py-3 rounded-lg border-2 transition-all ${
                    selectedDimensions.includes(`${selectedCube.name}.${dimension.name}`)
                      ? 'border-blue-500 bg-blue-50 dark:bg-blue-950/20'
                      : 'border-slate-200 dark:border-slate-700 hover:border-blue-300'
                  }`}
                >
                  <div className="font-medium text-slate-900 dark:text-white">{dimension.display_name}</div>
                  <div className="text-xs text-slate-500 dark:text-slate-500">{dimension.type}</div>
                </button>
              ))}
            </div>
          </div>

          {/* Time Dimension */}
          <div>
            <h3 className="text-sm font-semibold text-slate-700 dark:text-slate-300 mb-3 flex items-center">
              <Calendar className="w-4 h-4 mr-2" />
              Time Dimension
            </h3>
            <select
              value={timeDimension}
              onChange={(e) => setTimeDimension(e.target.value)}
              className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 mb-2"
            >
              <option value="">None</option>
              {selectedCube?.dimensions.filter(d => d.type === 'time').map(dimension => (
                <option key={dimension.name} value={`${selectedCube.name}.${dimension.name}`}>
                  {dimension.display_name}
                </option>
              ))}
            </select>
            {timeDimension && (
              <select
                value={timeGranularity}
                onChange={(e) => setTimeGranularity(e.target.value)}
                className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500"
              >
                <option value="hour">Hour</option>
                <option value="day">Day</option>
                <option value="week">Week</option>
                <option value="month">Month</option>
                <option value="quarter">Quarter</option>
                <option value="year">Year</option>
              </select>
            )}
          </div>

          {/* Filters */}
          <div>
            <div className="flex items-center justify-between mb-3">
              <h3 className="text-sm font-semibold text-slate-700 dark:text-slate-300 flex items-center">
                <FilterIcon className="w-4 h-4 mr-2" />
                Filters
              </h3>
              <button
                onClick={addFilter}
                className="p-1 hover:bg-slate-100 dark:hover:bg-slate-800 rounded"
              >
                <Plus className="w-4 h-4" />
              </button>
            </div>
            <div className="space-y-2">
              {filters.map((filter, index) => (
                <div key={index} className="p-3 bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-xs font-semibold text-slate-600 dark:text-slate-400">Filter {index + 1}</span>
                    <button onClick={() => removeFilter(index)} className="text-red-500 hover:text-red-700">
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                  <select
                    value={filter.member}
                    onChange={(e) => updateFilter(index, 'member', e.target.value)}
                    className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg text-sm mb-2"
                  >
                    <option value="">Select field...</option>
                    {selectedCube?.dimensions.map(d => (
                      <option key={d.name} value={`${selectedCube.name}.${d.name}`}>{d.display_name}</option>
                    ))}
                  </select>
                  <select
                    value={filter.operator}
                    onChange={(e) => updateFilter(index, 'operator', e.target.value)}
                    className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg text-sm mb-2"
                  >
                    <option value="equals">Equals</option>
                    <option value="notEquals">Not Equals</option>
                    <option value="contains">Contains</option>
                    <option value="gt">Greater Than</option>
                    <option value="lt">Less Than</option>
                  </select>
                  <input
                    type="text"
                    value={filter.values[0] || ''}
                    onChange={(e) => updateFilter(index, 'values', [e.target.value])}
                    placeholder="Value..."
                    className="w-full px-3 py-2 bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg text-sm"
                  />
                </div>
              ))}
            </div>
          </div>

          {/* Limit */}
          <div>
            <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">
              Limit
            </label>
            <input
              type="number"
              value={limit}
              onChange={(e) => setLimit(parseInt(e.target.value) || 100)}
              className="w-full px-4 py-3 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
        </div>

        {/* Right Panel - Results */}
        <div className="flex-1 flex flex-col overflow-hidden">
          {/* Tabs */}
          <div className="bg-white/80 dark:bg-slate-900/80 backdrop-blur-xl border-b border-slate-200 dark:border-slate-700 px-6">
            <div className="flex space-x-4">
              <button className="px-4 py-3 border-b-2 border-blue-500 text-blue-600 dark:text-blue-400 font-medium">
                Results
              </button>
              <button className="px-4 py-3 text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white">
                SQL
              </button>
            </div>
          </div>

          {/* Results Table */}
          <div className="flex-1 overflow-auto p-6">
            {loading ? (
              <div className="flex items-center justify-center h-full">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
              </div>
            ) : queryResult ? (
              <div>
                <div className="mb-4 flex items-center justify-between">
                  <div className="text-sm text-slate-600 dark:text-slate-400">
                    {queryResult.data.length} rows • {queryResult.executionTime}ms
                    {queryResult.cacheHit && <span className="ml-2 px-2 py-1 bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400 rounded-full text-xs font-semibold">CACHED</span>}
                  </div>
                  <button className="flex items-center space-x-2 px-4 py-2 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-700">
                    <Download className="w-4 h-4" />
                    <span className="text-sm">Export</span>
                  </button>
                </div>
                <div className="bg-white dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 overflow-hidden">
                  <table className="w-full">
                    <thead className="bg-slate-50 dark:bg-slate-900">
                      <tr>
                        {queryResult.data[0] && Object.keys(queryResult.data[0]).map((key: string) => (
                          <th key={key} className="px-4 py-3 text-left text-xs font-semibold text-slate-600 dark:text-slate-400 uppercase">
                            {key}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-200 dark:divide-slate-700">
