  onClose: () => void;
  onSave: (rule: SharedValidationRule) => void | Promise<void>;
  tenantId: string;
  datasourceId: string;
  availableEntities: string[];
  entitySchema?: Record<string, unknown>;
  fieldMetadata?: Record<string, FieldTypeInfo>;
