export const ValidationRuleCreator = ({
  isOpen,
  onClose,
  onSave,
  tenantId,
  datasourceId,
  availableEntities,
  entitySchema = {},
  editingRule,
  defaultTargetEntity,
  initialScope,
  subtypes = {},
  coreFields = [],
  customFields = [],
}: ValidationRuleCreatorProps) => {
  const theme = useTheme();
  const isEditMode = !!editingRule;

  // Wizard step state
  const [currentStep, setCurrentStep] = useState(0);
  const [logicTab, setLogicTab] = useState(0); // 0 = Script, 1 = Conditions

  const [formData, setFormData] = useState({
    rule_name: '',
    rule_type: 'asl' as 'asl' | 'business_logic',
    target_entity: '',
    sub_entity_type: initialScope?.subtype || '',
    severity: 'error' as 'error' | 'warning' | 'info',
    description: '',
    error_message: '',
    is_global: false,
    is_active: true,
    match_type: 'ALL' as 'ALL' | 'ANY',
    conditions: [] as Condition[],
    script_content: ''
  });

  const [errors, setErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(false);
  const [schemaContext, setSchemaContext] = useState<string>('');
  const [semanticTerms, setSemanticTerms] = useState<Record<string, any>>({});
  const [fieldById, setFieldById] = useState<Record<string, any>>({});
  const [forceRerenderKey, setForceRerenderKey] = useState(0);
  // const [simulationOpen, setSimulationOpen] = useState(false); // Removed separate state

  // UUID detection helper
  const isUUID = (value: string | undefined | null): boolean => {
    if (!value) return false;
    return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);
  };

  // Fetch both schema (fields + terms) and semantic terms for field path resolution
  useEffect(() => {
    const fetchSchema = async () => {
      let boId = '';
      if (formData.target_entity && entitySchema && (entitySchema as any)[formData.target_entity]) {
          boId = (entitySchema as any)[formData.target_entity].id;
      }

      if (!boId && formData.target_entity) {
          boId = formData.target_entity;
      }

      devLog('[ValidationRuleCreator] fetchSchema - target_entity:', formData.target_entity, 'boId:', boId, 'tenantId:', tenantId);

      if (tenantId && boId) {
        try {
          const res = await fetch(`/api/business-objects/${boId}/validations/schema?datasource_id=${datasourceId}&locale=en`, {
            headers: {
              'X-Tenant-ID': tenantId,
              'X-Tenant-Datasource-ID': datasourceId || '',
            }
          });
          if (res.ok) {
            const data = await res.json();

            // Extract fields and build fieldById map
            if (data.fields && Array.isArray(data.fields)) {
              const fieldMap: Record<string, any> = {};
              data.fields.forEach((field: any) => {
                fieldMap[field.id] = field;
              });
              devLog('schema.fields', data.fields);
              setFieldById(fieldMap);
            }

            // Extract terms and build termsById map
            if (data.terms && Array.isArray(data.terms)) {
              const termsMap: Record<string, any> = {};
              data.terms.forEach((term: any) => {
                termsMap[term.id] = term;
              });
              setSemanticTerms(termsMap);
            }

            setSchemaContext(data.schema || '');
          } else {
            devWarn("Failed to fetch CUE schema");
            setSchemaContext('');
            setFieldById({});
            setSemanticTerms({});
          }
        } catch (e) {
          console.error(e);
          setSchemaContext('');
          setFieldById({});
          setSemanticTerms({});
        }
      } else {
        setSchemaContext('');
        setFieldById({});
        setSemanticTerms({});
      }
    };

    if (formData.target_entity) {
        fetchSchema();
    }
  }, [formData.target_entity, tenantId, datasourceId, entitySchema]);

  // Fetch semantic terms for field path resolution (fallback if schema endpoint doesn't return them)
  useEffect(() => {
    const fetchSemanticTerms = async () => {
      if (!tenantId || !datasourceId) return;

      try {
        const response = await fetch(`/api/glossary/semantic-terms?tenant_id=${tenantId}&datasource_id=${datasourceId}`);
        if (response.ok) {
          const terms = await response.json();
          const termsMap: Record<string, any> = {};
          terms.forEach((term: any) => {
            // Parse properties if it's a string
            if (typeof term.properties === 'string') {
              try {
                term.properties = JSON.parse(term.properties);
              } catch (e) {
                devWarn('Failed to parse term properties', term.id, e);
              }
            }
            // Only merge if not already in schema terms
            if (!semanticTerms[term.id]) {
              termsMap[term.id] = term;
            }
          });
          setSemanticTerms(prev => ({ ...prev, ...termsMap }));
          setForceRerenderKey(Date.now());
        }
      } catch (error) {
        console.error('Failed to fetch semantic terms:', error);
      }
    };

    if (isOpen) {
      fetchSemanticTerms();
    }
  }, [isOpen, tenantId, datasourceId]);

  // Helper to resolve UUID/ID to readable field name or path
  const resolveTermOrField = (id: string | undefined): string => {
    if (!id) return '';

    // Check if it's a semantic term ID
    if (semanticTerms[id]) {
      const term = semanticTerms[id];

      // Prefer the code or name if not a UUID
      if (term.code && !isUUID(term.code)) {
        // Convert code to path notation (CUSTOMER_NAME -> customer.name)
        return `input.${term.code.toLowerCase().replace(/_/g, '.')}`;
      }

      // Try properties for field path
      if (term.properties?.field_path && Array.isArray(term.properties.field_path)) {
        return `input.${term.properties.field_path.join('.')}`;
      }

      // Try physical mapping
      if (term.properties?.physical_mapping) {
        const { table, column } = term.properties.physical_mapping;
        if (table && column) {
          return `input.${table}.${column}`;
        }
      }

      // Fallback to term name
      if (term.name) {
        return `input.${term.name.toLowerCase().replace(/\s/g, '_')}`;
      }
    }

    // Check if it's a field ID
    if (fieldById[id]) {
      const field = fieldById[id];

      // Prefer explicit path
      if (field.path && !isUUID(field.path)) {
        return `input.${field.path}`;
      }

      // Fallback to field name
      if (field.name && !isUUID(field.name)) {
        return `input.${field.name.toLowerCase().replace(/\s/g, '_')}`;
      }
    }

    // Last resort: if it's not a UUID itself, use it as-is
    if (!isUUID(id)) {
      return `input.${id}`;
    }

    // Can't resolve - return placeholder
    return id;
  };

  // Fallback field name resolution (from schema if available)
  const fallbackFieldNameFromFieldsList = (id: string): string => {
    const field = fieldById[id];
    if (!field) return id;

    // Prefer explicit path if present
    if (field.path && !isUUID(field.path)) {
      return `input.${field.path}`;
    }

    // Fallback to name
    if (field.name && !isUUID(field.name)) {
      return `input.${field.name.toLowerCase().replace(/\s/g, '_')}`;
    }

    return id;
  };

  // Convert conditions to ASL code
  const generateAslFromConditions = (): string => {
    if (!formData.conditions || formData.conditions.length === 0) {
      return `// Validation Rule: ${formData.rule_name}
// ${formData.description}

true // default to valid`;
    }

    // Helper to resolve field UUID to semantic path
    const resolveFieldPath = (fieldKey: string): string => {
      // First try the new unified resolver
      const resolved = resolveTermOrField(fieldKey);

      // If it returned something that isn't a UUID, use it
      if (resolved && !isUUID(resolved.replace('input.', ''))) {
        return resolved.replace('input.', ''); // Remove prefix for local use
      }

      // Fallback to old logic
      // fieldKey is the semantic_term_id
      if (semanticTerms[fieldKey]) {
        const term = semanticTerms[fieldKey];

        // Strategy 1: field_path array (Legacy)
        if (term.properties?.field_path && Array.isArray(term.properties.field_path)) {
          return term.properties.field_path.join('.');
        }

        // Strategy 2: physical_mapping object (Standard)
        if (term.properties?.physical_mapping) {
            const { table, column } = term.properties.physical_mapping;
            if (table && column) {
                // Determine if we need to include table name. 
                // Usually ASL is "input.column" if flat, or "input.table.column" if joined.
                // But current BO context is usually flattened.
                // However, based on user request "input.customer.address", it implies nested.
                // For now, let's use the field path style.
                return `${table}.${column}`;
            }
        }

        // Strategy 3: code property (if not a UUID)
        if (term.code && !isUUID(term.code)) {
          return term.code.toLowerCase().replace(/_/g, '.');
        }
      }
      // Fallback to fieldKey (which might be a name or UUID)
      return fieldKey;
    };

    const operators: Record<string, { format: (field: string, value: string) => string }> = {
      equals: {
        format: (field, value) => `input.${field} == "${value}"`
      },
      not_equals: {
        format: (field, value) => `input.${field} != "${value}"`
      },
      contains: {
        format: (field, value) => `input.${field}.contains("${value}")`
      },
      starts_with: {
        format: (field, value) => `input.${field}.startsWith("${value}")`
      },
      ends_with: {
        format: (field, value) => `input.${field}.endsWith("${value}")`
      },
      greater_than: {
        format: (field, value) => `input.${field} > ${value}`
      },
      less_than: {
        format: (field, value) => `input.${field} < ${value}`
      },
      is_empty: {
        format: (field) => `input.${field} == ""`
      },
      is_not_empty: {
        format: (field) => `input.${field} != ""`
      }
    };

    // Build condition checks
    // ASL uses standard logical operators
    const availableFields = getAllAvailableFields();
    const conditionChecks = formData.conditions.map(cond => {
      const opConfig = operators[cond.operator];
      if (!opConfig) return '';

      // cond.field could be either a field UUID or a field key
      let resolvedField = '';

      // Strategy 1: Check if it's a field UUID in our fieldById map (from schema API)
      if (cond.field && fieldById[cond.field]) {
        const field = fieldById[cond.field];

        // Try to get path from field
        if (field.path && !isUUID(field.path)) {
          resolvedField = field.path;
        } else if (field.name && !isUUID(field.name)) {
          resolvedField = field.name.toLowerCase().replace(/\s/g, '_');
        }
      }

      // Strategy 2: Try to find in availableFields by key or semanticTermId
      if (!resolvedField) {
        const fieldObj = availableFields.find(f => 
          f.key === cond.field || 
          f.semanticTermId === cond.field ||
          f.name === cond.field
        );

        if (fieldObj) {
          // Try semantic term resolution first
          if (fieldObj.semanticTermId && semanticTerms[fieldObj.semanticTermId]) {
            const term = semanticTerms[fieldObj.semanticTermId];
            if (term.properties?.field_path && Array.isArray(term.properties.field_path)) {
              resolvedField = term.properties.field_path.join('.');
            } else if (term.code && !isUUID(term.code)) {
              resolvedField = term.code.toLowerCase().replace(/_/g, '.');
            }
          }

          // Fallback to field name (prefer name over key if key is a UUID)
          if (!resolvedField) {
            // Use name first since it's the actual field name (e.g., "customer_address")
            // Key might be a UUID in some cases
            const candidateKey = fieldObj.key;
            const candidateName = fieldObj.name;

            if (candidateName && !isUUID(candidateName)) {
              resolvedField = candidateName.toLowerCase().replace(/\s/g, '_');
            } else if (candidateKey && !isUUID(candidateKey)) {
              resolvedField = candidateKey.toLowerCase().replace(/\s/g, '_');
            } else {
              // Both are UUIDs or invalid - try businessName as last resort
              const candidateBizName = fieldObj.businessName;
              if (candidateBizName && !isUUID(candidateBizName)) {
                resolvedField = candidateBizName.toLowerCase().replace(/\s/g, '_');
              }
            }
          }

        }
      }

      // Strategy 3: Direct resolver as last resort
      if (!resolvedField) {
        resolvedField = resolveFieldPath(cond.field);
      }

      // Final fallback: if still unresolved, log warning and use original value
      // Don't convert dashes to dots as that breaks UUIDs into invalid paths
      if (!resolvedField || isUUID(resolvedField)) {
        devWarn('[generateAslFromConditions] Could not resolve field to human-readable name:', cond.field);
        // Keep the original value without UUID-to-dots transformation
        resolvedField = cond.field;
      }


      // Simple numeric heuristic
      if (['greater_than', 'less_than'].includes(cond.operator)) {
        return `input.${resolvedField} ${cond.operator === 'greater_than' ? '>' : '<'} ${cond.value}`;
      }
      return opConfig.format(resolvedField, cond.value);
    });

    const joinOp = formData.match_type === 'ALL' ? ' && ' : ' || ';
    const body = conditionChecks.filter(Boolean).join(joinOp);

    return `// Validation Rule: ${formData.rule_name}
// ${formData.description}

${body}`;
  };

  // Get fields for entity
  const getFieldsForEntity = (entityName: string): Array<{ key: string; name: string; type: string; businessName: string; semanticTermId?: string }> => {
    const entity = (entitySchema && (entitySchema as Record<string, unknown>)[entityName]) as Record<string, unknown> | undefined;
    if (!entity || !Array.isArray(entity['entity_fields'])) {
      return [];
    }
    return (entity['entity_fields'] as unknown) as Array<{ key: string; name: string; type: string; businessName: string; semanticTermId?: string }>;
  };

  const getAllAvailableFields = (): Array<{ key: string; name: string; type: string; businessName: string; semanticTermId?: string }> => {
    // If a subtype is selected, return only the fields for that subtype
    if (formData.sub_entity_type && subtypes && subtypes[formData.sub_entity_type]) {
      const subtype = subtypes[formData.sub_entity_type];
      const subtypeFields = subtype.subtypeFields || subtype.fields || [];
      return subtypeFields.map((f: any) => ({
        key: f.key || f.name || '',
        name: f.name || '',
        type: f.type || '',
        businessName: f.displayName || f.name || '',
        semanticTermId: f.semanticTermId || f.semantic_term_id || f.properties?.semantic_term_id,
      }));
    }

    // Otherwise, use the business object's core and custom fields
    const allFields = [...(coreFields || []), ...(customFields || [])];
    return allFields.map((f: any) => ({
      key: f.key || f.name || '',
      name: f.name || '',
      type: f.type || '',
      businessName: f.displayName || f.name || '',
      semanticTermId: f.semanticTermId || f.semantic_term_id || f.properties?.semantic_term_id,
    }));
  };

  // Initialize form data
  useEffect(() => {
    if (isEditMode && editingRule && isOpen) {
      const editingAny = editingRule as any;
      let conditions = [];
      let matchType = 'ALL';

      if (editingAny.condition_json) {
        const cj = typeof editingAny.condition_json === 'string' 
          ? JSON.parse(editingAny.condition_json) 
          : editingAny.condition_json;
        conditions = cj.conditions || []; // Don't normalize here - do it after schema loads
        matchType = cj.match_type || 'ALL';
      }

      setFormData({
        rule_name: editingRule.rule_name || editingAny.name || '',
        rule_type: editingRule.rule_type === 'asl' ? 'asl' : 'business_logic',
        target_entity: editingRule.target_entity || editingAny.entity || '',
        sub_entity_type: editingRule.sub_entity_type || '',
        severity: editingRule.severity || 'error',
        description: editingRule.description || '',
        error_message: editingRule.error_message || '',
        is_global: false,
        is_active: editingRule.is_active ?? true,
        match_type: matchType as 'ALL' | 'ANY',
        conditions: conditions,
        script_content: (editingRule as any).script_content || ''
      });
      setLogicTab(editingRule.rule_type === 'asl' ? 0 : 1);
    } else if (defaultTargetEntity && isOpen && !isEditMode) {
      setFormData(prev => ({ 
        ...prev, 
        target_entity: defaultTargetEntity,
        sub_entity_type: initialScope?.subtype || '',
      }));
    }
  }, [isEditMode, editingRule, isOpen, defaultTargetEntity, initialScope]);

  // Memoize available fields to prevent unnecessary re-renders
  const availableFieldsList = useMemo(() => {
     return getAllAvailableFields();
  }, [formData.sub_entity_type, subtypes, coreFields, customFields]);

  // Build reverse mapping from semanticTermId to fieldId
  const semanticTermToFieldId = useMemo(() => {
    const mapping: Record<string, string> = {};
    availableFieldsList.forEach(f => {
      if (f.semanticTermId) {
        mapping[f.semanticTermId] = f.key;
      }
    });
    return mapping;
  }, [availableFieldsList]);

  // Normalize field selection: convert semanticTermId to fieldId for storage (for backward compatibility with existing rules)
  const normalizeFieldSelection = (selectedValue: string): string => {
    // If it's a semantic term ID from old rules, map it to the corresponding field ID
    if (semanticTermToFieldId[selectedValue]) {
      devLog('[normalizeFieldSelection] Converting semanticTermId to fieldId:', selectedValue, '->', semanticTermToFieldId[selectedValue]);
      return semanticTermToFieldId[selectedValue];
    }

    // If it's already a field ID (exists in fieldById or availableFieldsList)
    const fields = getAllAvailableFields();
    const fieldExists = fields.some(f => f.key === selectedValue) || fieldById[selectedValue];
    if (fieldExists) {
      return selectedValue;
    }

    devWarn('[normalizeFieldSelection] Could not resolve field:', selectedValue);
    return selectedValue;
  };

  // Migrate existing conditions from semanticTermId to fieldId after schema loads
  useEffect(() => {
    if (isEditMode && formData.conditions.length > 0 && Object.keys(semanticTermToFieldId).length > 0) {
      const migratedConditions = formData.conditions.map((cond: any) => ({
        ...cond,
        field: normalizeFieldSelection(cond.field)
      }));

      // Only update if there are actual changes
      const hasChanges = migratedConditions.some((cond: any, index: number) => 
        cond.field !== formData.conditions[index].field
      );

      if (hasChanges) {
        setFormData(prev => ({ ...prev, conditions: migratedConditions }));
      }
    }
  }, [isEditMode, semanticTermToFieldId, formData.conditions.length]);

  // Reset step when dialog opens
  useEffect(() => {
    if (isOpen) {
      setCurrentStep(0);
    }
  }, [isOpen]);

  const validateStep = (step: number): boolean => {
    const newErrors: Record<string, string> = {};

    if (step === 0) {
      if (!formData.rule_name.trim()) newErrors.rule_name = 'Reference ID is required';
      if (!formData.description.trim()) newErrors.description = 'Description is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleNext = () => {
    if (validateStep(currentStep)) {
      setCurrentStep(prev => Math.min(prev + 1, 3));
    }
  };

  const handleBack = () => {
    setCurrentStep(prev => Math.max(prev - 1, 0));
  };

  const handleSubmit = async () => {
    setLoading(true);

    try {
      devLog('[ValidationRuleCreator] handleSubmit started');
      devLog('[ValidationRuleCreator] formData.rule_type:', formData.rule_type);
      devLog('[ValidationRuleCreator] formData.conditions:', formData.conditions);

      // Always use starlark as the rule_type and always generate script_content
      let scriptContent = '';
      let conditionJson = null;

      // Check if we have conditions from the builder (even if rule_type is 'asl')
      const hasConditions = formData.conditions && formData.conditions.length > 0;

      devLog('[ValidationRuleCreator] hasConditions:', hasConditions);

      if (hasConditions) {
        // Generate ASL from conditions builder
        devLog('[ValidationRuleCreator] Generating ASL from conditions builder');
        scriptContent = generateAslFromConditions();
        devLog('[ValidationRuleCreator] Generated ASL:', scriptContent);

        conditionJson = {
          match_type: formData.match_type,
          conditions: formData.conditions,
        };
        devLog('[ValidationRuleCreator] conditionJson:', conditionJson);
      } else if (formData.rule_type === 'asl' && formData.script_content) {
        // Use manually entered ASL script
        devLog('[ValidationRuleCreator] Using manually entered ASL script');
        scriptContent = formData.script_content;
      } else {
        devLog('[ValidationRuleCreator] No conditions and no script_content');
      }

      const ruleData = {
        id: isEditMode && editingRule ? editingRule.id : undefined,
        rule_name: formData.rule_name.trim(),
        rule_type: 'asl', // Default to asl for script/conditions
        target_entity: defaultTargetEntity || formData.target_entity,
        sub_entity_type: formData.sub_entity_type,
        description: formData.description,
        error_message: formData.error_message,
        severity: formData.severity,
        is_global: formData.is_global,
        is_active: formData.is_active,
        condition_json: conditionJson, // Store conditions if from conditions builder for editing
        script_content: scriptContent,
      };

      devLog('[ValidationRuleCreator] Final ruleData being saved:', ruleData);
      devLog('[ValidationRuleCreator] script_content length:', scriptContent.length);

      await onSave(ruleData);
      handleClose();
    } catch (err) {
      console.error('[ValidationRuleCreator] Error in handleSubmit:', err);
      setErrors({ submit: err instanceof Error ? err.message : 'Unknown error occurred' });
    } finally {
      setLoading(false);
    }
  };

  const handleClose = () => {
    setFormData({
      rule_name: '',
      rule_type: 'asl',
      target_entity: '',
      sub_entity_type: '',
      severity: 'error',
      description: '',
      error_message: '',
      is_global: false,
      is_active: true,
      match_type: 'ALL',
      conditions: [],
      script_content: ''
    });
    setErrors({});
    setCurrentStep(0);
    onClose();
  };

  const addCondition = () => {
    setFormData({
      ...formData,
      conditions: [...formData.conditions, { field: '', operator: 'equals', value: '' }]
    });
  };

  const removeCondition = (index: number) => {
    setFormData({
      ...formData,
      conditions: formData.conditions.filter((_, i) => i !== index)
    });
  };

  const updateCondition = (index: number, field: keyof Condition, value: string) => {
    const newConditions = [...formData.conditions];
    newConditions[index] = { ...newConditions[index], [field]: value };
    if (field === 'operator' && (value === 'is_empty' || value === 'is_not_empty')) {
      newConditions[index].value = '';
    }
    setFormData({ ...formData, conditions: newConditions });
  };

  const handleLogicTabChange = (_: React.SyntheticEvent, newValue: number) => {
    setLogicTab(newValue);
    setFormData(prev => ({ ...prev, rule_type: newValue === 0 ? 'asl' : 'business_logic' }));
  };

  // Memoize completions to prevent Monaco provider flickering/disposal on every keystroke
  const dynamicCompletions = useMemo(() => {
     return availableFieldsList.map(f => {
        const termId = f.semanticTermId;

        // Start with a reasonable field path - prefer name over key if key is a UUID
        let fieldPath = '';
        if (f.name && !isUUID(f.name)) {
          fieldPath = f.name.toLowerCase().replace(/\s/g, '_');
        } else if (f.key && !isUUID(f.key)) {
          fieldPath = f.key.toLowerCase().replace(/\s/g, '_');
        } else if (f.businessName && !isUUID(f.businessName)) {
          fieldPath = f.businessName.toLowerCase().replace(/\s/g, '_');
        } else {
          // All identifiers are UUIDs - keep as-is (this will show as unresolved)
          fieldPath = f.key || f.name || '';
        }

        // Try to get a better path from semantic term if available
        if (termId && semanticTerms[termId]) {
           const term = semanticTerms[termId];
           if (term.properties?.physical_mapping?.table && term.properties?.physical_mapping?.column) {
              fieldPath = `${term.properties.physical_mapping.table}.${term.properties.physical_mapping.column}`;
           } else if (term.properties?.field_path) {
                fieldPath = Array.isArray(term.properties.field_path) ? term.properties.field_path.join('.') : term.properties.field_path;
           } else if (term.code && !isUUID(term.code)) {
              // Use term code as path if available and not a UUID
              fieldPath = term.code.toLowerCase().replace(/_/g, '.');
           }
        }

        const fullPath = `input.${fieldPath}`;
        return {
          label: fullPath, 
          insertText: fullPath, 
          kind: 10,
          documentation: f.businessName || f.name,
          // Store the fieldId for resolution
          fieldId: f.key
        };
     });
  }, [availableFieldsList, semanticTerms]);


  const progressPercent = ((currentStep + 1) / 4) * 100;
  const stepLabels = ['Basic Info', 'Logic & Severity', 'Simulation', 'Review & Save'];

  // ============ STEP 1: Basic Info ============
  const renderStep1 = () => (
    <Stack spacing={4}>
      <TextField
        label="Reference ID"
        placeholder="e.g., VR-2023-001"
        value={formData.rule_name}
        onChange={(e) => setFormData({ ...formData, rule_name: e.target.value })}
        error={!!errors.rule_name}
        helperText={errors.rule_name || 'Unique identifier for this rule'}
        fullWidth
        required
      />

      <TextField
        label="Description"
        placeholder="Describe the purpose and logic of this validation rule for documentation..."
        value={formData.description}
        onChange={(e) => setFormData({ ...formData, description: e.target.value })}
        error={!!errors.description}
        helperText={errors.description}
        fullWidth
        multiline
        rows={3}
        required
      />

      <TextField
        label="Validation Message"
        placeholder="e.g., The invoice date cannot be in the future."
        value={formData.error_message}
        onChange={(e) => setFormData({ ...formData, error_message: e.target.value })}
        helperText="Displayed to end-users when validation fails"
        fullWidth
        InputProps={{
          startAdornment: <ChatBubbleOutlineIcon sx={{ mr: 1, color: 'text.secondary' }} />
        }}
      />

      {/* Tip */}
      <Box sx={{ display: 'flex', gap: 1.5, color: 'text.secondary', px: 1 }}>
        <LightbulbIcon sx={{ fontSize: 20, mt: 0.25 }} />
        <Typography variant="body2">
          Tip: A clear Reference ID helps your team find rules quickly later. Try using a prefix like 'INV-' for invoice rules.
        </Typography>
      </Box>
    </Stack>
  );

  // ============ STEP 2: Logic & Severity ============
  const renderStep2 = () => (
    <Stack spacing={4}>
      {/* Script / Conditions Tabs */}
      <Paper variant="outlined" sx={{ borderRadius: 2 }}>
        <Tabs
          value={logicTab}
          onChange={handleLogicTabChange}
          sx={{ borderBottom: 1, borderColor: 'divider', px: 2 }}
        >
          <Tab 
            icon={<CodeIcon />} 
            iconPosition="start" 
            label="ASL Script" 
            sx={{ textTransform: 'none', fontWeight: 600 }} 
          />
          <Tab 
            icon={<AccountTreeIcon />} 
            iconPosition="start" 
            label="Conditions Builder" 
            sx={{ textTransform: 'none', fontWeight: 600 }} 
          />
        </Tabs>

        <Box sx={{ p: 0 }}>
          {logicTab === 0 ? (
            <Box sx={{ height: 400, borderBottomLeftRadius: 8, borderBottomRightRadius: 8, overflow: 'hidden' }}>
              <MonacoCodeEditor
                value={formData.script_content}
                onChange={(val: string | undefined) => setFormData({ ...formData, script_content: val || '' })}
                language="python"
                height="100%"
                theme="vs-dark"
                options={{
                  minimap: { enabled: false },
                  scrollBeyondLastLine: false,
                  fontSize: 14,
                  lineNumbers: 'on',
                }}
                dynamicCompletions={dynamicCompletions}
              />
            </Box>
          ) : (
            <Box sx={{ p: 3 }}>
              <Stack spacing={3}>
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, flexWrap: 'wrap' }}>
                  <Typography variant="body2" fontWeight={600}>Execute if</Typography>
                  <FormControl size="small" sx={{ minWidth: 80 }}>
                    <Select
                      value={formData.match_type}
                      onChange={(e) => setFormData({ ...formData, match_type: e.target.value as 'ALL' | 'ANY' })}
                    >
                      <MenuItem value="ALL">ALL</MenuItem>
                      <MenuItem value="ANY">ANY</MenuItem>
                    </Select>
                  </FormControl>
                  <Typography variant="body2" fontWeight={600}>conditions are met:</Typography>
                </Box>

            <Stack spacing={2} key={forceRerenderKey}>
              {formData.conditions.map((condition, index) => (
                <Paper key={index} variant="outlined" sx={{ p: 2, borderRadius: 2 }}>
                  <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems="flex-start">
                    {index > 0 && (
                      <Chip 
                        label={formData.match_type === 'ALL' ? 'AND' : 'OR'} 
                        size="small" 
                        color="primary" 
                        variant="outlined"
                      />
                    )}
                    <FormControl size="small" sx={{ minWidth: 150 }}>
                      <InputLabel>Field</InputLabel>
                      <Select
                        value={condition.field}
                        label="Field"
                        onChange={(e) => {
                          const normalizedValue = normalizeFieldSelection(e.target.value);
                          updateCondition(index, 'field', normalizedValue);
                        }}
                        renderValue={(selected) => {
                           const fields = getAllAvailableFields();
                           devLog('[ValidationRuleCreator] Debug renderValue:', { 
                               selected, 
                               fieldsCount: fields.length, 
                               fieldFound: fields.find(f => f.key === selected),
                               schemaFieldFound: fieldById[selected]
                           });

                           // Primary: find by fieldId (f.key) - this is what we're storing now
                           const field = fields.find(f => f.key === selected);
                           if (field) {
                             return field.businessName || field.name;
                           }

                           // Secondary: try schema fields (from API)
                           const fieldByFieldId = fieldById[selected];
                           if (fieldByFieldId) {
                             return fieldByFieldId.displayName || fieldByFieldId.name;
                           }

                           // Backward compatibility: check if it's a semanticTermId
                           const fieldBySemanticTerm = fields.find(f => f.semanticTermId === selected);
                           if (fieldBySemanticTerm) return fieldBySemanticTerm.businessName || fieldBySemanticTerm.name;

                           return selected;
                        }}
                      >
                        {getAllAvailableFields().map(f => (
                          <MenuItem key={f.key} value={f.key}>{f.businessName || f.name}</MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                    <FormControl size="small" sx={{ minWidth: 130 }}>
                      <InputLabel>Operator</InputLabel>
                      <Select
                        value={condition.operator}
                        label="Operator"
                        onChange={(e) => updateCondition(index, 'operator', e.target.value)}
                      >
                        {OPERATORS.map(op => (
                          <MenuItem key={op.value} value={op.value}>{op.label}</MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                    {condition.operator !== 'is_empty' && condition.operator !== 'is_not_empty' && (
                      <TextField
                        size="small"
                        label="Value"
                        value={condition.value}
                        onChange={(e) => updateCondition(index, 'value', e.target.value)}
                        sx={{ flex: 1 }}
                      />
                    )}
                    <IconButton onClick={() => removeCondition(index)} color="error" size="small">
                      <DeleteIcon />
                    </IconButton>
                  </Stack>
                </Paper>
              ))}

              <Button startIcon={<AddIcon />} onClick={addCondition} variant="outlined" sx={{ alignSelf: 'flex-start' }}>
                Add Condition
              </Button>
            </Stack>
          </Stack>
        </Box>
          )}
        </Box>
      </Paper>

      {/* Simulation Button */}
      {/* Simulation Button Removed - Moved to Step 3 */}

      {/* Severity & Status Grid */}
      <Stack direction={{ xs: 'column', md: 'row' }} spacing={3}>
        {/* Severity Section */}
        <Paper variant="outlined" sx={{ flex: 2, p: 3, borderRadius: 2 }}>
          <Typography variant="subtitle1" fontWeight={700} gutterBottom>Severity Level</Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Determine the impact when this rule is triggered.
          </Typography>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1.5}>
            {SEVERITY_LEVELS.map((level) => {
              const Icon = level.icon;
              const isSelected = formData.severity === level.value;
              return (
                <Paper
                  key={level.value}
                  onClick={() => setFormData({ ...formData, severity: level.value as any })}
                  sx={{
                    flex: 1,
                    p: 2,
                    cursor: 'pointer',
                    borderRadius: 2,
                    border: '2px solid',
                    borderColor: isSelected ? level.color : 'divider',
                    bgcolor: isSelected ? level.bgColor : 'transparent',
                    transition: 'all 0.2s ease',
                    '&:hover': {
                      borderColor: level.color,
                      bgcolor: alpha(level.color, 0.05),
                    },
                  }}
                >
                  <Stack spacing={1}>
                    <Stack direction="row" spacing={1} alignItems="center" sx={{ color: level.color }}>
                      <Icon />
                      <Typography variant="body2" fontWeight={700}>{level.label}</Typography>
                    </Stack>
                    <Typography variant="caption" color="text.secondary">{level.description}</Typography>
                  </Stack>
                </Paper>
              );
            })}
          </Stack>
        </Paper>

        {/* Status Section */}
        <Paper variant="outlined" sx={{ flex: 1, p: 3, borderRadius: 2 }}>
          <Typography variant="subtitle1" fontWeight={700} gutterBottom>Rule Status</Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Enable or disable this rule immediately.
          </Typography>
          <Paper variant="outlined" sx={{ p: 2, display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderRadius: 2, bgcolor: 'action.hover' }}>
            <Typography variant="body2" fontWeight={600}>Active</Typography>
            <Switch
              checked={formData.is_active}
              onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
              color="primary"
            />
          </Paper>
        </Paper>
      </Stack>
    </Stack>
  );

  // ============ STEP 3: Simulation ============
  const renderStep3 = () => (
    <Box sx={{ height: 600, display: 'flex', flexDirection: 'column' }}>
        <Typography variant="subtitle1" fontWeight={700} gutterBottom>
            Simulation & Testing
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Test your rule against sample data to verify the logic before saving.
        </Typography>
        <Box sx={{ flex: 1, border: '1px solid', borderColor: 'divider', borderRadius: 2, overflow: 'hidden' }}>
            <RuleTestingPanel
                rule={{
                    name: formData.rule_name,
                    category: 'validation',
                    description: formData.description,
                    conditions: {
                        operator: formData.match_type === 'ALL' ? 'AND' : 'OR',
                        conditions: formData.conditions.map(c => ({
                            field: c.field,
                            operator: c.operator,
                            value: c.value
                        }))
                    },
                    actions: [],
                    cel_expression: formData.rule_type === 'asl' ? formData.script_content : generateAslFromConditions()
                }}
                tenantId={tenantId}
                datasourceId={datasourceId}
                // onClose is optional, not needed when embedded
            />
        </Box>
    </Box>
  );

  // ============ STEP 4: Review & Save ============
  const renderStep4 = () => {
    const severityConfig = SEVERITY_LEVELS.find(s => s.value === formData.severity);

    return (
      <Stack spacing={0}>
        {errors.submit && (
          <Alert severity="error" sx={{ mb: 3 }}>{errors.submit}</Alert>
        )}

        {/* Basic Information */}
        <Paper variant="outlined" sx={{ borderRadius: 2, overflow: 'hidden' }}>
          <Box sx={{ p: 3, borderBottom: 1, borderColor: 'divider' }}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
              <Typography variant="subtitle1" fontWeight={700}>Basic Information</Typography>
              <Button size="small" startIcon={<EditIcon />} onClick={() => setCurrentStep(0)}>Edit</Button>
            </Box>
            <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr' }, gap: 3 }}>
              <Box>
                <Typography variant="caption" color="text.secondary" sx={{ textTransform: 'uppercase', letterSpacing: 1 }}>Rule Name</Typography>
                <Typography variant="body2" fontWeight={500}>{formData.rule_name || '—'}</Typography>
              </Box>
              <Box>
                <Typography variant="caption" color="text.secondary" sx={{ textTransform: 'uppercase', letterSpacing: 1 }}>Target Object</Typography>
                <Typography variant="body2" fontWeight={500} sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                  <RuleIcon sx={{ fontSize: 16, color: 'text.secondary' }} /> {formData.target_entity || '—'}
                </Typography>
              </Box>
              <Box sx={{ gridColumn: { sm: '1 / -1' } }}>
                <Typography variant="caption" color="text.secondary" sx={{ textTransform: 'uppercase', letterSpacing: 1 }}>Description</Typography>
                <Typography variant="body2">{formData.description || '—'}</Typography>
              </Box>
            </Box>
          </Box>

          {/* Logic Configuration */}
          <Box sx={{ p: 3, borderBottom: 1, borderColor: 'divider', bgcolor: 'action.hover' }}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
              <Typography variant="subtitle1" fontWeight={700}>Logic Configuration</Typography>
              <Button size="small" startIcon={<EditIcon />} onClick={() => setCurrentStep(1)}>Edit</Button>
            </Box>
            <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr' }, gap: 3 }}>
              <Box>
                <Typography variant="caption" color="text.secondary" sx={{ textTransform: 'uppercase', letterSpacing: 1 }}>Logic Type</Typography>
                <Typography variant="body2" fontWeight={500}>
                  {formData.rule_type === 'asl' ? 'ASL Script' : 'Conditions Builder'}
                </Typography>
              </Box>
              <Box>
                <Typography variant="caption" color="text.secondary" sx={{ textTransform: 'uppercase', letterSpacing: 1 }}>Error Message</Typography>
                <Typography variant="body2" fontWeight={500} color="error.main" sx={{ fontStyle: 'italic' }}>
                  "{formData.error_message || 'Not specified'}"
                </Typography>
              </Box>



              <Box sx={{ gridColumn: '1 / -1' }}>
                <Typography variant="caption" color="text.secondary" sx={{ textTransform: 'uppercase', letterSpacing: 1, mb: 1, display: 'block' }}>Script Preview</Typography>
                <Paper sx={{ bgcolor: '#1e293b', p: 2, borderRadius: 2, fontFamily: 'monospace', fontSize: '0.8rem', color: '#94a3b8', maxHeight: 120, overflow: 'auto' }}>
                  <Box component="pre" sx={{ margin: 0, whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>
                    {formData.rule_type === 'asl' ? formData.script_content : generateAslFromConditions()}
                  </Box>
                </Paper>
              </Box>
            </Box>
          </Box>

          {/* Settings */}
          <Box sx={{ p: 3 }}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
              <Typography variant="subtitle1" fontWeight={700}>Settings</Typography>
              <Button size="small" startIcon={<EditIcon />} onClick={() => setCurrentStep(1)}>Edit</Button>
            </Box>
            <Stack direction="row" spacing={4}>
              <Box>
                <Typography variant="caption" color="text.secondary" sx={{ textTransform: 'uppercase', letterSpacing: 1, mb: 1, display: 'block' }}>Severity</Typography>
                {severityConfig && (
                  <Chip
                    icon={<severityConfig.icon />}
                    label={severityConfig.label}
                    size="small"
                    sx={{
                      bgcolor: severityConfig.bgColor,
                      color: severityConfig.color,
                      border: `1px solid ${severityConfig.borderColor}`,
                      fontWeight: 600,
                    }}
                  />
                )}
              </Box>
              <Box>
                <Typography variant="caption" color="text.secondary" sx={{ textTransform: 'uppercase', letterSpacing: 1, mb: 1, display: 'block' }}>Status</Typography>
                <Chip
                  icon={formData.is_active ? <CheckCircleIcon /> : undefined}
                  label={formData.is_active ? 'Active' : 'Inactive'}
                  size="small"
                  color={formData.is_active ? 'success' : 'default'}
                  sx={{ fontWeight: 600 }}
                />
              </Box>
            </Stack>
          </Box>
        </Paper>
      </Stack>
    );
  };

  return (
    <Dialog 
      open={isOpen} 
      onClose={handleClose} 
      maxWidth="md" 
      fullWidth
      PaperProps={{
        sx: { 
          maxHeight: '90vh',
          borderRadius: 3,
        }
      }}
    >
      {/* Progress Header */}
      <DialogTitle sx={{ pb: 1 }}>
        <Stack spacing={2}>
          <Stack direction="row" justifyContent="space-between" alignItems="flex-start">
            <Box>
              <Typography variant="h5" fontWeight={700}>
                {isEditMode ? 'Edit Validation Rule' : 'Create Validation Rule'}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {currentStep === 0 && 'Define the core identification and scope for this rule.'}
                {currentStep === 1 && 'Configure how the validation rule behaves and its impact.'}
                {currentStep === 2 && 'Please verify the details below before saving.'}
              </Typography>
            </Box>
            <Stack direction="row" alignItems="center" spacing={1}>
              <Typography variant="body2" color="primary" fontWeight={600}>
                Step {currentStep + 1} of 4
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {stepLabels[currentStep]}
              </Typography>
              <IconButton onClick={handleClose} size="small" sx={{ ml: 1 }}>
                <CloseIcon />
              </IconButton>
            </Stack>
          </Stack>
          <LinearProgress 
            variant="determinate" 
            value={progressPercent} 
            sx={{ 
              height: 8, 
              borderRadius: 4,
              bgcolor: 'action.hover',
              '& .MuiLinearProgress-bar': {
                borderRadius: 4,
              }
            }} 
          />
        </Stack>
      </DialogTitle>

      <DialogContent sx={{ pt: 3 }}>
        {currentStep === 0 && renderStep1()}
        {currentStep === 1 && renderStep2()}
        {currentStep === 2 && renderStep3()}
        {currentStep === 3 && renderStep4()}
      </DialogContent>

      <DialogActions sx={{ px: 3, py: 2.5, borderTop: 1, borderColor: 'divider', bgcolor: 'action.hover', justifyContent: 'space-between' }}>
        <Button onClick={handleClose} color="inherit">
          Cancel
        </Button>
        <Stack direction="row" spacing={2}>
          {currentStep > 0 && (
            <Button startIcon={<ArrowBackIcon />} onClick={handleBack} variant="outlined">
              Back
            </Button>
          )}
          {currentStep < 3 ? (
            <Button 
              endIcon={<ArrowForwardIcon />} 
              onClick={handleNext} 
              variant="contained"
              sx={{ px: 3 }}
            >
              Next Step
            </Button>
          ) : (
            <Button
              startIcon={loading ? <CircularProgress size={18} color="inherit" /> : <SaveIcon />}
              onClick={handleSubmit}
              variant="contained"
              disabled={loading}
              sx={{ px: 4 }}
            >
              {loading ? 'Saving...' : 'Save Rule'}
            </Button>
          )}
        </Stack>
      </DialogActions>

      {/* Simulation Dialog Removed */}
    </Dialog>
  );
};

