import React, { useState } from 'react';
import {
  Form,
  Button,
  Select,
  Input,
  Card,
  Space,
  Tag,
  Switch,
  Divider,
  message,
} from 'antd';
import { useABAC } from './ABACProvider';
import type { ABACPolicy } from './ABACProvider';

/**
 * PolicyBuilder Component
 * 
 * UI for creating and editing ABAC policies.
 * Supports:
 * - Subject rules (roles, users, departments)
 * - Action rules (allowed/denied actions)
 * - Resource rules (types, exclusions)
 * - Environment rules (locations, time windows)
 * 
 * All policies are tenant-scoped and automatically enforce multi-tenancy.
 */

interface PolicyBuilderProps {
  onPolicySaved?: (policy: ABACPolicy) => void;
  initialPolicy?: ABACPolicy;
}

export const PolicyBuilder: React.FC<PolicyBuilderProps> = ({
  onPolicySaved,
  initialPolicy,
}) => {
  const { createPolicy, updatePolicy, canExecute } = useABAC();
  const [form] = Form.useForm();
  const [loading, setLoading] = useState(false);
  const [policy, setPolicy] = useState<Partial<ABACPolicy>>(
    initialPolicy || {
      name: '',
      effect: 'allow',
      priority: 100,
      enabled: true,
      subject: {},
      action: {},
      resource: {},
      environment: {},
    }
  );

  const handleSave = async () => {
    try {
      // Check if user has permission to create/edit policies
      const hasPermission = await canExecute('create_policy', 'abac');
      if (!hasPermission) {
        message.error('You do not have permission to create policies');
        return;
      }

      setLoading(true);

      const policyData = {
        ...policy,
        name: policy.name || 'Untitled Policy',
        priority: policy.priority || 100,
      } as ABACPolicy;

      let result;
      if (initialPolicy?.id) {
        result = await updatePolicy(initialPolicy.id, policyData);
        message.success('Policy updated');
      } else {
        result = await createPolicy(policyData as Omit<ABACPolicy, 'id'>);
        message.success('Policy created');
      }

      onPolicySaved?.(result);
      form.resetFields();
    } catch (error) {
      const msg = error instanceof Error ? error.message : 'Failed to save policy';
      message.error(msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="policy-builder-container">
      <Card title="Create ABAC Policy">
        <Form form={form} layout="vertical">
          {/* Basic Info */}
          <Form.Item label="Policy Name" required>
            <Input
              placeholder="e.g., Compliance Officer Read-Only"
              value={policy.name}
              onChange={(e) => setPolicy({ ...policy, name: e.target.value })}
            />
          </Form.Item>

          <Form.Item label="Description">
            <Input.TextArea
              placeholder="Policy description"
              rows={2}
              value={policy.description}
              onChange={(e) =>
                setPolicy({ ...policy, description: e.target.value })
              }
            />
          </Form.Item>

          <Divider />

          {/* Effect */}
          <Space style={{ marginBottom: 16 }}>
            <span>Effect:</span>
            <Select
              style={{ width: 150 }}
              value={policy.effect}
              onChange={(value) => setPolicy({ ...policy, effect: value })}
              options={[
                { label: '✅ Allow', value: 'allow' },
                { label: '❌ Deny', value: 'deny' },
              ]}
            />
            <span>Priority:</span>
            <Input
              type="number"
              style={{ width: 80 }}
              value={policy.priority}
              onChange={(e) =>
                setPolicy({ ...policy, priority: parseInt(e.target.value) })
              }
            />
            <Switch
              checked={policy.enabled}
              onChange={(checked) => setPolicy({ ...policy, enabled: checked })}
            />
            <span>{policy.enabled ? 'Enabled' : 'Disabled'}</span>
          </Space>

          <Divider />

          {/* Subject Rules */}
          <h4>Subject Rules</h4>
          <Form.Item label="Roles">
            <Select
              mode="multiple"
              placeholder="e.g., ComplianceOfficer, Analyst, Admin"
              value={policy.subject?.roles}
              onChange={(roles) =>
                setPolicy({ ...policy, subject: { ...policy.subject, roles } })
              }
            />
          </Form.Item>

          <Form.Item label="Users">
            <Select
              mode="multiple"
              placeholder="Specific user UUIDs"
              value={policy.subject?.users}
              onChange={(users) =>
                setPolicy({ ...policy, subject: { ...policy.subject, users } })
              }
            />
          </Form.Item>

          <Form.Item label="Departments">
            <Select
              mode="multiple"
              placeholder="e.g., Compliance, Risk, Operations"
              value={policy.subject?.departments}
              onChange={(departments) =>
                setPolicy({
                  ...policy,
                  subject: { ...policy.subject, departments },
                })
              }
            />
          </Form.Item>

          <Divider />

          {/* Action Rules */}
          <h4>Action Rules</h4>
          <Form.Item label="Allowed Actions">
            <Select
              mode="multiple"
              placeholder="e.g., read, list, view"
              value={policy.action?.allowed}
              onChange={(allowed) =>
                setPolicy({ ...policy, action: { ...policy.action, allowed } })
              }
            />
          </Form.Item>

          <Form.Item label="Denied Actions">
            <Select
              mode="multiple"
              placeholder="e.g., create, edit, delete"
              value={policy.action?.denied}
              onChange={(denied) =>
                setPolicy({ ...policy, action: { ...policy.action, denied } })
              }
            />
          </Form.Item>

          <Divider />

          {/* Resource Rules */}
          <h4>Resource Rules</h4>
          <Form.Item label="Resource Types">
            <Select
              mode="multiple"
              placeholder="e.g., triggers, policies, processes"
              value={policy.resource?.types}
              onChange={(types) =>
                setPolicy({ ...policy, resource: { ...policy.resource, types } })
              }
            />
          </Form.Item>

          <Form.Item label="Excluded Resources">
            <Select
              mode="multiple"
              placeholder="Resources to exclude"
              value={policy.resource?.excluded}
              onChange={(excluded) =>
                setPolicy({
                  ...policy,
                  resource: { ...policy.resource, excluded },
                })
              }
            />
          </Form.Item>

          <Divider />

          {/* Environment Rules */}
          <h4>Environment Rules (Optional)</h4>
          <Form.Item label="Allowed Locations">
            <Select
              mode="multiple"
              placeholder="e.g., US, EU, JP"
              value={policy.environment?.locations}
              onChange={(locations) =>
                setPolicy({
                  ...policy,
                  environment: { ...policy.environment, locations },
                })
              }
            />
          </Form.Item>

          <Divider />

          {/* Actions */}
          <Space>
            <Button
              type="primary"
              onClick={handleSave}
              loading={loading}
              icon={<PlusOutlined />}
            >
              {initialPolicy ? 'Update' : 'Create'} Policy
            </Button>
          </Space>
        </Form>
      </Card>
    </div>
  );
};

export default PolicyBuilder;

import React from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Chip,
  Grid,
  Stack,
  Alert,
  Table,
  TableBody,
  TableCell,
  TableRow,
  Paper,
  Button,
} from '@mui/material';
import {
  AutoFixHigh,
  TrendingUp,
  Speed,
  Schedule,
  Storage,
  QueryStats,
  CheckCircle,
  Warning,
  Info,
  Science,
} from '@mui/icons-material';
import { useParams } from 'react-router-dom';
import { ASOOptimization, useASOOptimization } from '../../hooks/useASO';
import OptimizationMLCard, { MLEvidence, ExplainPayload } from './OptimizationMLCard';
import { OptimizationExplainabilityCard, OptimizationSimulationCard } from './OptimizationMLCard';
import OptimizationActions from './OptimizationActions';

interface ASOOptimizationDetailProps {
  optimization?: ASOOptimization;
  onApply?: () => Promise<void>;
  onApprove?: () => Promise<void>;
  onReject?: (reason: string) => Promise<void>;
  onSimulate?: () => void;
}

export const ASOOptimizationDetail: React.FC<ASOOptimizationDetailProps> = ({
  optimization: propOptimization,
  onApply,
  onApprove,
  onReject,
  onSimulate,
}) => {
  const { optimizationId } = useParams<{ optimizationId: string }>();
  const { optimization: fetchedOptimization, loading, error } = useASOOptimization(propOptimization ? undefined : optimizationId);

  const optimization = propOptimization || fetchedOptimization;

  if (loading) {
    return <Box sx={{ p: 4 }}><Typography>Loading optimization details...</Typography></Box>;
  }

  if (error) {
    return <Alert severity="error">{error}</Alert>;
  }

  if (!optimization) {
     return <Alert severity="warning">Optimization not found</Alert>;
  }

  // Parse details
  const details = optimization.details || {};

  // Extract Explain Payload if available
  const explain = details.explain as ExplainPayload | undefined;

  // Construct ML Evidence if not in explain payload but available on optimization
  const mlEvidence: MLEvidence | undefined = explain?.ml || (optimization.ml_score !== undefined ? {
    score: optimization.ml_score,
    confidence: optimization.confidence || 0.8,
    predicted_speedup: optimization.predicted_speedup || 0,
    predicted_cost_savings: optimization.predicted_cost_savings || 0,
    risk_score: optimization.risk_score || 0,
    top_factors: optimization.top_factors || [],
  } as MLEvidence : undefined);

  // Construct Simulation Evidence
  const simulationEvidence = explain?.simulation;

  return (
    <Box>
      {/* Header */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Stack direction="row" justifyContent="space-between" alignItems="flex-start">
            <Stack direction="row" spacing={2} alignItems="center">
              <AutoFixHigh sx={{ fontSize: 40, color: 'primary.main' }} />
              <Box>
                <Typography variant="h5" fontWeight="bold">
                  {formatOptimizationType(optimization.optimization_type)}
                </Typography>
                <Typography color="text.secondary">
                  Target: {optimization.target_name} ({optimization.target_type})
                </Typography>
              </Box>
            </Stack>
            <Stack direction="row" spacing={1} alignItems="center">
              <Chip label={optimization.env} size="small" />
              <Chip
                label={optimization.scope}
                size="small"
                color={optimization.scope === 'core' ? 'primary' : 'default'}
                variant="outlined"
              />
              <StatusChip status={optimization.status} />
            </Stack>
          </Stack>

          <Box sx={{ mt: 2, display: 'flex', justifyContent: 'flex-end' }}>
            <OptimizationActions 
              optimization={optimization}
              onApprove={onApprove}
              onApply={onApply}
              onReject={onReject}
              onSimulate={onSimulate}
            />
          </Box>
        </CardContent>
      </Card>

      {/* ML & Explainability Section (New) */}
      <Grid container spacing={3} mb={3}>
        {mlEvidence && (
          <Grid item xs={12}>
            <OptimizationMLCard ml={mlEvidence} />
          </Grid>
        )}
        {explain && (
          <Grid item xs={12}>
            <OptimizationExplainabilityCard explain={explain} />
          </Grid>
        )}
        {simulationEvidence && (
          <Grid item xs={12}>
            <OptimizationSimulationCard simulation={simulationEvidence} />
          </Grid>
        )}
      </Grid>

      {/* Legacy/Standard Details */}
      <Grid container spacing={3}>
        <Grid item xs={12}>
          <Card sx={{ mb: 3 }}>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                <Info sx={{ mr: 1, verticalAlign: 'middle' }} />
                Optimization Details
              </Typography>
              <Alert severity="info" sx={{ mb: 2 }}>
                {optimization.reason}
              </Alert>

              {/* Workload Metrics */}
              <Typography variant="subtitle2" gutterBottom sx={{ mt: 2 }}>
                Workload Metrics (Last {optimization.workload_window_days} Days)
              </Typography>
              <Grid container spacing={2}>
                {optimization.queries_per_day !== undefined && (
                  <Grid item xs={6} md={3}>
                    <MetricBox
                      label="Queries/Day"
                      value={optimization.queries_per_day.toFixed(0)}
                      icon={<QueryStats />}
                    />
                  </Grid>
                )}
                {optimization.avg_latency_ms !== undefined && (
                  <Grid item xs={6} md={3}>
                    <MetricBox
                      label="Avg Latency"
                      value={`${optimization.avg_latency_ms.toFixed(0)}ms`}
                      icon={<Speed />}
                    />
                  </Grid>
                )}
                {optimization.p95_latency_ms !== undefined && (
                  <Grid item xs={6} md={3}>
                    <MetricBox
                      label="P95 Latency"
                      value={`${optimization.p95_latency_ms.toFixed(0)}ms`}
                      icon={<Speed />}
                      highlight={optimization.p95_latency_ms > 1000}
                    />
                  </Grid>
                )}
              </Grid>
            </CardContent>
          </Card>

          {/* Type Specific Details */}
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                <TrendingUp sx={{ mr: 1, verticalAlign: 'middle' }} />
                Implementation Plan
              </Typography>
              {optimization.optimization_type === 'create_preagg' && (
                <CreatePreAggDetails details={details} />
              )}
              {optimization.optimization_type === 'tune_refresh' && (
                <TuneRefreshDetails details={details} />
              )}
              {optimization.optimization_type === 'retire_asset' && (
                <RetireAssetDetails details={details} />
              )}
              {optimization.optimization_type === 'prewarm' && (
                <PrewarmDetails details={details} />
              )}
            </CardContent>
          </Card>
        </Grid>
      </Grid>
    </Box>
  );
};

// ============================================================================
// Helper Components (Reused)
// ============================================================================

const StatusChip: React.FC<{ status: string }> = ({ status }) => {
  const config: Record<string, { color: 'success' | 'warning' | 'error' | 'info' | 'default'; icon: React.ReactNode }> = {
    proposed: { color: 'warning', icon: <Warning /> },
    approved: { color: 'info', icon: <CheckCircle /> },
    applied: { color: 'success', icon: <CheckCircle /> },
    rejected: { color: 'error', icon: <Warning /> },
    failed: { color: 'error', icon: <Warning /> },
    superseded: { color: 'default', icon: null },
  };
  const c = config[status] || { color: 'default', icon: null };
  return <Chip label={status} color={c.color} size="small" />;
};

interface MetricBoxProps {
  label: string;
  value: string | number;
  icon: React.ReactNode;
  highlight?: boolean;
}

const MetricBox: React.FC<MetricBoxProps> = ({ label, value, icon, highlight }) => (
  <Paper variant="outlined" sx={{ p: 2, bgcolor: highlight ? 'error.light' : 'transparent' }}>
    <Stack direction="row" spacing={1} alignItems="center">
      {icon}
      <Box>
        <Typography variant="caption" color="text.secondary">
          {label}
        </Typography>
        <Typography variant="h6" fontWeight="bold">
          {value}
        </Typography>
      </Box>
    </Stack>
  </Paper>
);

// ============================================================================
// Detail Components by Type
// ============================================================================

const CreatePreAggDetails: React.FC<{ details: Record<string, any> }> = ({ details }) => (
  <Box>
    <Table size="small">
      <TableBody>
        <TableRow>
          <TableCell>Grain</TableCell>
          <TableCell>{(details.grain || []).join(', ')}</TableCell>
        </TableRow>
        <TableRow>
          <TableCell>Measures</TableCell>
          <TableCell>{(details.measures || []).join(', ')}</TableCell>
        </TableRow>
        {details.filters?.length > 0 && (
          <TableRow>
            <TableCell>Filters</TableCell>
            <TableCell>{details.filters.join(', ')}</TableCell>
          </TableRow>
        )}
      </TableBody>
    </Table>

    {details.cost_estimate && (
      <Box sx={{ mt: 2 }}>
        <Typography variant="subtitle2" gutterBottom>Estimated Resources</Typography>
        <Grid container spacing={2}>
           <Grid item xs={4}>
             <Typography variant="caption">Storage</Typography>
             <Typography variant="body1">{formatBytes(details.cost_estimate.estimated_storage_bytes)}</Typography>
           </Grid>
           <Grid item xs={4}>
             <Typography variant="caption">Refresh Cost</Typography>
             <Typography variant="body1">${details.cost_estimate.estimated_refresh_cost?.toFixed(2)}</Typography>
           </Grid>
        </Grid>
      </Box>
    )}
  </Box>
);

const TuneRefreshDetails: React.FC<{ details: Record<string, any> }> = ({ details }) => (
  <Table size="small">
    <TableBody>
      <TableRow>
        <TableCell>Current</TableCell>
        <TableCell>{details.current_refresh_interval}</TableCell>
      </TableRow>
      <TableRow>
        <TableCell>Proposed</TableCell>
        <TableCell sx={{ color: 'success.main', fontWeight: 'bold' }}>
          {details.proposed_refresh_interval}
        </TableCell>
      </TableRow>
    </TableBody>
  </Table>
);

const RetireAssetDetails: React.FC<{ details: Record<string, any> }> = ({ details }) => (
   <Typography variant="body2">
     Asset unused since {details.last_used_at}. Storage: {formatBytes(details.storage_bytes)}.
   </Typography>
);

const PrewarmDetails: React.FC<{ details: Record<string, any> }> = ({ details }) => (
  <Table size="small">
    <TableBody>
      <TableRow>
        <TableCell>Schedule</TableCell>
        <TableCell>{details.proposed_schedule}</TableCell>
      </TableRow>
    </TableBody>
  </Table>
);

function formatOptimizationType(type: string): string {
  return type.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
}

function formatBytes(bytes: number): string {
  if (!bytes) return '0 B';
  if (bytes >= 1073741824) return (bytes / 1073741824).toFixed(1) + ' GB';
  if (bytes >= 1048576) return (bytes / 1048576).toFixed(1) + ' MB';
  if (bytes >= 1024) return (bytes / 1024).toFixed(1) + ' KB';
  return bytes + ' B';
}

export default ASOOptimizationDetail;

import React, { useState } from 'react';
import {
  AuditEvent,
  ChangeSet,
  AIExplanation,
  useAuditEvents,
  useExplainAudit,
  useCreateChangeSetFromAI,
  useAuditExplainerFlow,
  ImpactedEntityType,
} from '@/hooks/useAuditGraphHooks';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Loader2, AlertCircle, CheckCircle, Zap } from 'lucide-react';

interface AuditExplorerGraphProps {
  scope: 'global' | 'multi-tenant-assigned' | 'tenant' | 'tenant-ops';
  role: 'GLOBAL_ADMIN' | 'GLOBAL_OPS' | 'TENANT_ADMIN' | 'TENANT_OPS';
  tenantIds: string[];
}

/**
 * AuditExplorerGraph - Main audit explorer component for role-aware audit event visualization
 */
export const AuditExplorerGraph: React.FC<AuditExplorerGraphProps> = ({ scope, role, tenantIds }) => {
  const [timeRange, setTimeRange] = useState({ from: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000), to: new Date() });
  const [selectedEvent, setSelectedEvent] = useState<AuditEvent | null>(null);
  const [activeTab, setActiveTab] = useState<'timeline' | 'entities' | 'incidents' | 'compliance' | 'ai'>('timeline');

  const { data: events, isLoading: eventsLoading } = useAuditEvents(tenantIds, timeRange.from, timeRange.to);

  return (
    <div className="flex h-full gap-4 p-4">
      {/* Main timeline view */}
      <div className="flex-1">
        <Card>
          <CardHeader>
            <CardTitle>Audit Timeline</CardTitle>
            <CardDescription>Events across {tenantIds.length} tenant(s)</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {eventsLoading ? (
                <div className="flex items-center justify-center py-8">
                  <Loader2 className="h-6 w-6 animate-spin" />
                </div>
              ) : events && events.length > 0 ? (
                <TimelineViewGraph events={events} onSelect={setSelectedEvent} selectedId={selectedEvent?.id} />
              ) : (
                <div className="py-8 text-center text-gray-500">No events found</div>
              )}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Right panel: AI Explanation + ChangeSet Proposal */}
      {selectedEvent && <AIPanelWithChangeSetProposal event={selectedEvent} />}
    </div>
  );
};

/**
 * TimelineViewGraph - Renders a unified timeline of audit events
 */
const TimelineViewGraph: React.FC<{
  events: AuditEvent[];
  onSelect: (event: AuditEvent) => void;
  selectedId?: string;
}> = ({ events, onSelect, selectedId }) => {
  return (
    <div className="space-y-2">
      {events.map((event) => (
        <TimelineRowGraph
          key={event.id}
          event={event}
          onSelect={onSelect}
          isSelected={event.id === selectedId}
        />
      ))}
    </div>
  );
};

/**
 * TimelineRowGraph - Renders a single audit event row
 */
const TimelineRowGraph: React.FC<{
  event: AuditEvent;
  onSelect: (event: AuditEvent) => void;
  isSelected: boolean;
}> = ({ event, onSelect, isSelected }) => {
  const getIcon = (type: string) => {
    switch (type) {
      case 'JOB_RUN':
        return '⚙️';
      case 'DAG_RUN':
        return '🔄';
      case 'INCIDENT':
        return '⚠️';
      case 'CHANGESET_EVENT':
        return '📝';
      case 'COMPLIANCE_EVENT':
        return '🔒';
      case 'AI_SUGGESTION':
        return '💡';
      default:
        return '📋';
    }
  };

  const getStatusBadgeColor = (status?: string) => {
    if (!status) return 'gray';
    if (status.includes('SUCCESS')) return 'green';
    if (status.includes('FAIL')) return 'red';
    return 'yellow';
  };

  return (
    <div
      onClick={() => onSelect(event)}
      className={`p-3 rounded-lg border cursor-pointer transition-colors ${
        isSelected ? 'bg-blue-50 border-blue-400' : 'bg-white hover:bg-gray-50 border-gray-200'
      }`}
    >
      <div className="flex items-start gap-3">
        <div className="text-2xl">{getIcon(event.type)}</div>
        <div className="flex-1">
          <div className="flex items-center gap-2">
            <span className="font-mono text-sm text-gray-500">{new Date(event.timestamp).toLocaleTimeString()}</span>
            <Badge variant="outline" className="text-xs">
              {event.type}
            </Badge>
            {event.status && (
              <Badge className={`text-xs bg-${getStatusBadgeColor(event.status)}-100`}>{event.status}</Badge>
            )}
          </div>
          <p className="text-sm font-medium mt-1">{event.title || event.artifactType}</p>
          {event.metadata?.error_message && (
            <p className="text-sm text-red-600 mt-1">{event.metadata.error_message}</p>
          )}
        </div>
        {isSelected && <Zap className="h-5 w-5 text-blue-500" />}
      </div>
    </div>
  );
};

/**
 * AIPanelWithChangeSetProposal - Right-side panel showing AI explanation and ChangeSet proposal
 */
const AIPanelWithChangeSetProposal: React.FC<{ event: AuditEvent }> = ({ event }) => {
  const [explanation, setExplanation] = useState<AIExplanation | null>(null);
  const [showChangeSetModal, setShowChangeSetModal] = useState(false);
  const explainFlow = useAuditExplainerFlow(event);

  const handleExplain = async () => {
    const result = await explainFlow.explain.mutate();
    if (result) {
      setExplanation(result);
    }
  };

  return (
    <div className="w-96 space-y-4">
      {/* Explanation Card */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base">AI Analysis</CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          {explanation ? (
            <div className="space-y-3 text-sm">
              <div>
                <p className="font-semibold text-gray-700 mb-1">Narrative</p>
                <p className="text-gray-600">{explanation.narrative}</p>
              </div>
              <div>
                <p className="font-semibold text-gray-700 mb-1">Root Cause</p>
                <p className="text-gray-600">{explanation.rootCause}</p>
              </div>
              <div>
                <p className="font-semibold text-gray-700 mb-1">Blast Radius</p>
                <p className="text-gray-600">{explanation.blastRadius}</p>
              </div>
              <div>
                <p className="font-semibold text-gray-700 mb-1">Recommended Fix</p>
                <p className="text-gray-600">{explanation.recommendedFix}</p>
              </div>
              {explanation.confidence && (
                <div className="flex items-center gap-2 pt-2">
                  <div className="flex-1 bg-gray-200 rounded h-2">
                    <div className="bg-blue-500 h-2 rounded" style={{ width: `${explanation.confidence * 100}%` }} />
                  </div>
                  <span className="text-xs text-gray-500">{Math.round(explanation.confidence * 100)}%</span>
                </div>
              )}
              <Button
                onClick={() => setShowChangeSetModal(true)}
                className="w-full mt-3"
                variant="default"
                size="sm"
              >
                Propose ChangeSet
              </Button>
            </div>
          ) : (
            <Button onClick={handleExplain} disabled={explainFlow.explain.isLoading} className="w-full" size="sm">
              {explainFlow.explain.isLoading ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Analyzing...
                </>
              ) : (
                <>
                  <Zap className="mr-2 h-4 w-4" />
                  Explain with AI
                </>
              )}
            </Button>
          )}
        </CardContent>
      </Card>

      {/* ChangeSet Proposal Modal */}
      {showChangeSetModal && explanation && (
        <ChangeSetProposalModalGraph
          explanation={explanation}
          event={event}
          onClose={() => setShowChangeSetModal(false)}
        />
      )}
    </div>
  );
};

/**
 * ChangeSetProposalModalGraph - Modal for creating a ChangeSet from AI suggestion
 */
const ChangeSetProposalModalGraph: React.FC<{
  explanation: AIExplanation;
  event: AuditEvent;
  onClose: () => void;
}> = ({ explanation, event, onClose }) => {
  const [title, setTitle] = useState(explanation.suggestedChangeSetSummary);
  const [description, setDescription] = useState(
    `${explanation.narrative}\n\nRoot Cause: ${explanation.rootCause}\n\nRecommendation: ${explanation.recommendedFix}`
  );
  const createChangeSetMutation = useCreateChangeSetFromAI();

  const handleCreateChangeSet = async () => {
    await createChangeSetMutation.mutateAsync({
      title,
      description,
      tenantId: event.tenantId,
      sourceEventId: event.id,
      impactedEntities: [], // In real impl, extract from explanation/graph
    });
    onClose();
  };

  return (
    <Card className="border-blue-200 bg-blue-50">
      <CardHeader>
        <CardTitle className="text-base">Propose ChangeSet</CardTitle>
      </CardHeader>
      <CardContent className="space-y-3">
        <div>
          <label className="text-sm font-semibold">Title</label>
          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="w-full mt-1 p-2 border rounded text-sm"
          />
        </div>
        <div>
          <label className="text-sm font-semibold">Description</label>
          <textarea
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            className="w-full mt-1 p-2 border rounded text-sm h-24"
          />
        </div>
        <div className="flex gap-2">
          <Button onClick={handleCreateChangeSet} disabled={createChangeSetMutation.isPending} className="flex-1" size="sm">
            {createChangeSetMutation.isPending ? <Loader2 className="mr-2 h-4 w-4 animate-spin" /> : null}
            Create ChangeSet
          </Button>
          <Button onClick={onClose} variant="outline" className="flex-1" size="sm">
            Cancel
          </Button>
        </div>
      </CardContent>
    </Card>
  );
};

export default AuditExplorerGraph;

