    <Box component="ul" sx={{ listStyle: 'none', p: 0, m: 0 }}>
      {nodes.map((node) => (
        <HierarchyTreeNode
          key={node.id}
          node={node}
          expandedNodes={expandedNodes}
          onNodeToggle={onNodeToggle}
        />
      ))}
    </Box>
