  type: 'continuous' | 'daily' | 'weekly' | 'monthly' | 'quarterly';
  timezone: string;
  days_of_week?: number[];
  time_of_day?: string;
}

export interface NotificationConfig {
  email: boolean;
  in_app: boolean;
  webhook_url?: string;
  threshold_triggered: boolean;
}

