export const RDLRuleBuilder: React.FC<RDLRuleBuilderProps> = ({
  tenantId,
  datasourceId,
  initialRule,
  onSave,
  onTest,
  onCancel,
}) => {
  // State
  const [activeTab, setActiveTab] = useState(0);
  const [rule, setRule] = useState<Partial<RuleDefinition>>({
    tenant_id: tenantId,
    rule_id: '',
    type: 'tax_loss_harvesting',
    version: '1.0.0',
    name: '',
    description: '',
    jurisdiction: 'US',
    parameters: {},
    expression: RULE_TYPE_CONFIGS.tax_loss_harvesting.defaultExpression,
    active: true,
    ...initialRule,
  });

  const [testResult, setTestResult] = useState<{ passed: boolean; score?: number; message?: string } | null>(null);
  const [validationErrors, setValidationErrors] = useState<string[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [isTesting, setIsTesting] = useState(false);

  // Get current rule type config
  const currentConfig = useMemo(() => {
    return RULE_TYPE_CONFIGS[rule.type || 'tax_loss_harvesting'];
  }, [rule.type]);

  // Initialize parameters with defaults when rule type changes
  const handleRuleTypeChange = useCallback((newType: RuleType) => {
    const config = RULE_TYPE_CONFIGS[newType];
    const defaultParams: Record<string, any> = {};

    config.parameterSchema.forEach(param => {
      defaultParams[param.name] = param.default;
    });

    setRule(prev => ({
      ...prev,
      type: newType,
      expression: config.defaultExpression,
      parameters: defaultParams,
    }));
    setTestResult(null);
  }, []);

  // Update a single parameter
  const handleParameterChange = useCallback((name: string, value: any) => {
    setRule(prev => ({
      ...prev,
      parameters: {
        ...prev.parameters,
        [name]: value,
      },
    }));
  }, []);

  // Validate rule before saving
  const validateRule = useCallback((): boolean => {
    const errors: string[] = [];

    if (!rule.rule_id?.trim()) {
      errors.push('Rule ID is required');
    }
    if (!rule.name?.trim()) {
      errors.push('Rule name is required');
    }
    if (!rule.expression?.trim()) {
      errors.push('CEL expression is required');
    }

    setValidationErrors(errors);
    return errors.length === 0;
  }, [rule]);

  // Handle save
  const handleSave = useCallback(async () => {
    if (!validateRule()) return;

    setIsSaving(true);
    try {
      if (onSave) {
        await onSave(rule as RuleDefinition);
      }
    } catch (error) {
      console.error('Failed to save rule:', error);
      setValidationErrors(['Failed to save rule. Please try again.']);
    } finally {
      setIsSaving(false);
    }
  }, [rule, validateRule, onSave]);

  // Handle test
  const handleTest = useCallback(async () => {
    if (!validateRule()) return;

    setIsTesting(true);
    setTestResult(null);
    try {
      if (onTest) {
        const result = await onTest(rule as RuleDefinition);
        setTestResult(result);
      } else {
        // Mock test result
        setTestResult({
          passed: true,
          score: 0.85,
          message: 'Rule syntax is valid',
        });
      }
    } catch (error) {
      setTestResult({
        passed: false,
        message: `Test failed: ${error}`,
      });
    } finally {
      setIsTesting(false);
    }
  }, [rule, validateRule, onTest]);

  // Generate JSON preview
  const jsonPreview = useMemo(() => {
    return JSON.stringify(rule, null, 2);
  }, [rule]);

  return (
    <Box sx={{ width: '100%', maxWidth: 1200 }}>
      {/* Header */}
      <Box sx={{ display: 'flex', alignItems: 'center', mb: 3, gap: 2 }}>
        <Typography variant="h5" sx={{ fontWeight: 600 }}>
          {currentConfig.icon} Rule Builder
        </Typography>
        <Chip
          label={currentConfig.label}
          color="primary"
          variant="outlined"
          size="small"
        />
      </Box>

      {/* Validation Errors */}
      {validationErrors.length > 0 && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {validationErrors.map((error, idx) => (
            <div key={idx}>{error}</div>
          ))}
        </Alert>
      )}

      {/* Test Result */}
      {testResult && (
        <Alert
          severity={testResult.passed ? 'success' : 'error'}
          icon={testResult.passed ? <CheckIcon /> : <WarningIcon />}
          sx={{ mb: 2 }}
        >
          {testResult.message}
          {testResult.score !== undefined && (
            <Typography variant="body2" sx={{ mt: 0.5 }}>
              Score: {(testResult.score * 100).toFixed(1)}%
            </Typography>
          )}
        </Alert>
      )}

      {/* Tabs */}
      <Paper sx={{ mb: 2 }}>
        <Tabs value={activeTab} onChange={(_, v) => setActiveTab(v)}>
          <Tab label="Configuration" />
          <Tab label="Parameters" />
          <Tab label="Expression" />
          <Tab label="Advanced" />
          <Tab label="Preview" icon={<PreviewIcon />} iconPosition="start" />
        </Tabs>
      </Paper>

      {/* Tab Panels */}
      <Box>
        {/* Tab 0: Basic Configuration */}
        {activeTab === 0 && (
          <Card>
            <CardContent>
              <Grid container spacing={3}>
                <Grid item xs={12} md={6}>
                  <FormControl fullWidth>
                    <InputLabel>Rule Type</InputLabel>
                    <Select
                      value={rule.type}
                      label="Rule Type"
                      onChange={(e) => handleRuleTypeChange(e.target.value as RuleType)}
                    >
                      {Object.entries(RULE_TYPE_CONFIGS).map(([key, config]) => (
                        <MenuItem key={key} value={key}>
                          {config.icon} {config.label}
                        </MenuItem>
                      ))}
                    </Select>
                    <FormHelperText>{currentConfig.description}</FormHelperText>
                  </FormControl>
                </Grid>

                <Grid item xs={12} md={6}>
                  <FormControl fullWidth>
                    <InputLabel>Jurisdiction</InputLabel>
                    <Select
                      value={rule.jurisdiction || 'US'}
                      label="Jurisdiction"
                      onChange={(e) => setRule(prev => ({ ...prev, jurisdiction: e.target.value }))}
                    >
                      {JURISDICTIONS.map(j => (
                        <MenuItem key={j.value} value={j.value}>{j.label}</MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    required
                    label="Rule ID"
                    value={rule.rule_id}
                    onChange={(e) => setRule(prev => ({ ...prev, rule_id: e.target.value }))}
                    helperText="Unique identifier (e.g., TLH_US_STANDARD)"
                    placeholder="TLH_US_STANDARD"
                  />
                </Grid>

                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label="Version"
                    value={rule.version}
                    onChange={(e) => setRule(prev => ({ ...prev, version: e.target.value }))}
                    placeholder="1.0.0"
                  />
                </Grid>

                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    required
                    label="Rule Name"
                    value={rule.name}
                    onChange={(e) => setRule(prev => ({ ...prev, name: e.target.value }))}
                    placeholder="US Tax-Loss Harvesting - Standard"
                  />
                </Grid>

                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    multiline
                    rows={3}
                    label="Description"
                    value={rule.description}
                    onChange={(e) => setRule(prev => ({ ...prev, description: e.target.value }))}
                    placeholder="Describe what this rule does and when it should trigger..."
                  />
                </Grid>

                <Grid item xs={12}>
                  <FormControlLabel
                    control={
                      <Switch
                        checked={rule.active}
                        onChange={(e) => setRule(prev => ({ ...prev, active: e.target.checked }))}
                      />
                    }
                    label="Rule Active"
                  />
                </Grid>
              </Grid>
            </CardContent>
          </Card>
        )}

        {/* Tab 1: Parameters */}
        {activeTab === 1 && (
          <Card>
            <CardContent>
              <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 600 }}>
                {currentConfig.label} Parameters
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
                Configure the parameters for this rule type. These values will be available as <code>params.*</code> in the CEL expression.
              </Typography>

              <Grid container spacing={3}>
                {currentConfig.parameterSchema.map(param => (
                  <Grid item xs={12} md={6} key={param.name}>
                    {param.type === 'slider' ? (
                      <Box>
                        <Typography variant="body2" gutterBottom>
                          {param.label}: {rule.parameters?.[param.name] ?? param.default}
                          {param.name.includes('pct') || param.name.includes('rate') || param.name.includes('weight') ? '%' : ''}
                        </Typography>
                        <Slider
                          value={rule.parameters?.[param.name] ?? param.default}
                          onChange={(_, value) => handleParameterChange(param.name, value)}
                          min={param.min}
                          max={param.max}
                          step={param.step}
                          marks
                          valueLabelDisplay="auto"
                        />
                        {param.helpText && (
                          <FormHelperText>{param.helpText}</FormHelperText>
                        )}
                      </Box>
                    ) : param.type === 'boolean' ? (
                      <FormControlLabel
                        control={
                          <Switch
                            checked={rule.parameters?.[param.name] ?? param.default}
                            onChange={(e) => handleParameterChange(param.name, e.target.checked)}
                          />
                        }
                        label={
                          <Box>
                            {param.label}
                            {param.helpText && (
                              <Typography variant="caption" display="block" color="text.secondary">
                                {param.helpText}
                              </Typography>
                            )}
                          </Box>
                        }
                      />
                    ) : param.type === 'select' ? (
                      <FormControl fullWidth>
                        <InputLabel>{param.label}</InputLabel>
                        <Select
                          value={rule.parameters?.[param.name] ?? param.default}
                          label={param.label}
                          onChange={(e) => handleParameterChange(param.name, e.target.value)}
                        >
                          {param.options?.map(opt => (
                            <MenuItem key={opt.value} value={opt.value}>{opt.label}</MenuItem>
                          ))}
                        </Select>
                        {param.helpText && <FormHelperText>{param.helpText}</FormHelperText>}
                      </FormControl>
                    ) : (
                      <TextField
                        fullWidth
                        type={param.type}
                        label={param.label}
                        value={rule.parameters?.[param.name] ?? param.default}
                        onChange={(e) => handleParameterChange(
                          param.name,
                          param.type === 'number' ? parseFloat(e.target.value) : e.target.value
                        )}
                        helperText={param.helpText}
                        inputProps={param.type === 'number' ? { min: param.min, max: param.max } : undefined}
                      />
                    )}
                  </Grid>
                ))}

                {currentConfig.parameterSchema.length === 0 && (
                  <Grid item xs={12}>
                    <Alert severity="info">
                      Custom rules have no predefined parameters. Define your parameters in the JSON below or in the Expression tab.
                    </Alert>
                    <TextField
                      fullWidth
                      multiline
                      rows={6}
                      label="Custom Parameters (JSON)"
                      value={JSON.stringify(rule.parameters || {}, null, 2)}
                      onChange={(e) => {
                        try {
                          setRule(prev => ({ ...prev, parameters: JSON.parse(e.target.value) }));
                        } catch { /* ignore parse errors while typing */ }
                      }}
                      sx={{ mt: 2, fontFamily: 'monospace' }}
                    />
                  </Grid>
                )}
              </Grid>
            </CardContent>
          </Card>
        )}

        {/* Tab 2: Expression */}
        {activeTab === 2 && (
          <Card>
            <CardContent>
              <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 600 }}>
                CEL Expression
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                Write the Common Expression Language (CEL) expression that determines when this rule triggers.
                Use <code>input.*</code> for evaluation data and <code>params.*</code> for configured parameters.
              </Typography>

              <TextField
                fullWidth
                multiline
                rows={6}
                value={rule.expression}
                onChange={(e) => setRule(prev => ({ ...prev, expression: e.target.value }))}
                placeholder="input.unrealized_loss_pct >= params.min_loss_pct && input.days_held >= params.min_holding_days"
                sx={{ fontFamily: 'monospace', fontSize: 14 }}
              />

              <Divider sx={{ my: 3 }} />

              <Typography variant="subtitle2" gutterBottom>
                Available Variables
              </Typography>

              <Accordion>
                <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                  <Typography variant="body2">Input Variables (input.*)</Typography>
                </AccordionSummary>
                <AccordionDetails>
                  <Typography variant="body2" component="div" sx={{ fontFamily: 'monospace', fontSize: 12 }}>
                    input.portfolio_id - Portfolio identifier<br/>
                    input.ticker - Security ticker<br/>
                    input.unrealized_loss_pct - Unrealized loss percentage<br/>
                    input.unrealized_loss_usd - Unrealized loss in USD<br/>
                    input.cost_basis - Position cost basis<br/>
                    input.current_value - Current market value<br/>
                    input.days_held - Days position has been held<br/>
                    input.account_type - Account type (TAXABLE, IRA, etc.)<br/>
                    input.nav - Portfolio net asset value<br/>
                    input.drift_pct - Portfolio drift percentage<br/>
                    input.sector_weight - Position sector weight<br/>
                    input.position_weight - Position weight in portfolio
                  </Typography>
                </AccordionDetails>
              </Accordion>

              <Accordion>
                <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                  <Typography variant="body2">Custom Functions</Typography>
                </AccordionSummary>
                <AccordionDetails>
                  <Typography variant="body2" component="div" sx={{ fontFamily: 'monospace', fontSize: 12 }}>
                    isInWashSaleWindow(household_id, ticker) - Check if in wash sale window<br/>
                    hasRecentPurchase(household_id, ticker, days) - Check for recent purchases<br/>
                    daysSince(timestamp) - Calculate days since a date
                  </Typography>
                </AccordionDetails>
              </Accordion>

              <Box sx={{ mt: 2 }}>
                <Button
                  variant="outlined"
                  startIcon={<RefreshIcon />}
                  onClick={() => setRule(prev => ({ ...prev, expression: currentConfig.defaultExpression }))}
                >
                  Reset to Default
                </Button>
              </Box>
            </CardContent>
          </Card>
        )}

        {/* Tab 3: Advanced */}
        {activeTab === 3 && (
          <Card>
            <CardContent>
              <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 600 }}>
                Advanced Configuration
              </Typography>

              <Grid container spacing={3}>
                <Grid item xs={12}>
                  <Typography variant="subtitle2" gutterBottom>Scoring Formula (Optional)</Typography>
                  <TextField
                    fullWidth
                    multiline
                    rows={2}
                    value={rule.scoring_formula || ''}
                    onChange={(e) => setRule(prev => ({ ...prev, scoring_formula: e.target.value }))}
                    placeholder="input.unrealized_loss_usd * params.estimated_tax_rate / 100"
                    helperText="CEL expression to calculate a score/priority for this rule trigger"
                    sx={{ fontFamily: 'monospace' }}
                  />
                </Grid>

                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    type="date"
                    label="Effective From"
                    value={rule.effective_from || ''}
                    onChange={(e) => setRule(prev => ({ ...prev, effective_from: e.target.value }))}
                    InputLabelProps={{ shrink: true }}
                    helperText="Rule becomes active from this date"
                  />
                </Grid>

                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    type="date"
                    label="Effective To"
                    value={rule.effective_to || ''}
                    onChange={(e) => setRule(prev => ({ ...prev, effective_to: e.target.value }))}
                    InputLabelProps={{ shrink: true }}
                    helperText="Rule expires after this date"
                  />
                </Grid>

                {/* Wash Sale Config for TLH rules */}
                {(rule.type === 'tax_loss_harvesting' || rule.type === 'wash_sale') && (
                  <Grid item xs={12}>
                    <Accordion>
                      <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                        <Typography>Wash Sale Configuration</Typography>
                      </AccordionSummary>
                      <AccordionDetails>
                        <Grid container spacing={2}>
                          <Grid item xs={12} md={4}>
                            <TextField
                              fullWidth
                              type="number"
                              label="Window Days Before"
                              value={rule.wash_sale_config?.window_days_before ?? 30}
                              onChange={(e) => setRule(prev => ({
                                ...prev,
                                wash_sale_config: {
                                  ...prev.wash_sale_config,
                                  window_days_before: parseInt(e.target.value),
                                } as WashSaleConfig,
                              }))}
                            />
                          </Grid>
                          <Grid item xs={12} md={4}>
                            <TextField
                              fullWidth
                              type="number"
                              label="Window Days After"
                              value={rule.wash_sale_config?.window_days_after ?? 30}
                              onChange={(e) => setRule(prev => ({
                                ...prev,
                                wash_sale_config: {
                                  ...prev.wash_sale_config,
                                  window_days_after: parseInt(e.target.value),
                                } as WashSaleConfig,
                              }))}
                            />
                          </Grid>
                          <Grid item xs={12} md={4}>
                            <FormControlLabel
                              control={
                                <Switch
                                  checked={rule.wash_sale_config?.check_household ?? true}
                                  onChange={(e) => setRule(prev => ({
                                    ...prev,
                                    wash_sale_config: {
                                      ...prev.wash_sale_config,
                                      check_household: e.target.checked,
                                    } as WashSaleConfig,
                                  }))}
                                />
                              }
                              label="Check Household"
                            />
                          </Grid>
                        </Grid>
                      </AccordionDetails>
                    </Accordion>
                  </Grid>
                )}

                {/* Notifications */}
                <Grid item xs={12}>
                  <Accordion>
                    <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                      <Typography>Notifications</Typography>
                    </AccordionSummary>
                    <AccordionDetails>
                      <Grid container spacing={2}>
                        <Grid item xs={12} md={4}>
                          <FormControlLabel
                            control={
                              <Switch
                                checked={rule.notifications?.email ?? true}
                                onChange={(e) => setRule(prev => ({
                                  ...prev,
                                  notifications: {
                                    ...prev.notifications,
                                    email: e.target.checked,
                                  } as NotificationConfig,
                                }))}
                              />
                            }
                            label="Email Notifications"
                          />
                        </Grid>
                        <Grid item xs={12} md={4}>
                          <FormControlLabel
                            control={
                              <Switch
                                checked={rule.notifications?.in_app ?? true}
                                onChange={(e) => setRule(prev => ({
                                  ...prev,
                                  notifications: {
                                    ...prev.notifications,
                                    in_app: e.target.checked,
                                  } as NotificationConfig,
                                }))}
                              />
                            }
                            label="In-App Notifications"
                          />
                        </Grid>
                        <Grid item xs={12}>
                          <TextField
                            fullWidth
                            label="Webhook URL"
                            value={rule.notifications?.webhook_url || ''}
                            onChange={(e) => setRule(prev => ({
                              ...prev,
                              notifications: {
                                ...prev.notifications,
                                webhook_url: e.target.value,
                              } as NotificationConfig,
                            }))}
                            placeholder="https://your-webhook.com/notify"
                          />
                        </Grid>
                      </Grid>
                    </AccordionDetails>
                  </Accordion>
                </Grid>
              </Grid>
            </CardContent>
          </Card>
        )}

        {/* Tab 4: JSON Preview */}
        {activeTab === 4 && (
          <Card>
            <CardContent>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                <Typography variant="subtitle1" sx={{ fontWeight: 600 }}>
                  JSON Preview
                </Typography>
                <Tooltip title="Copy to clipboard">
                  <IconButton
                    onClick={() => navigator.clipboard.writeText(jsonPreview)}
                    size="small"
                  >
                    <CopyIcon />
                  </IconButton>
                </Tooltip>
              </Box>
              <Paper
                sx={{
                  p: 2,
                  bgcolor: 'grey.900',
                  color: 'grey.100',
                  fontFamily: 'monospace',
                  fontSize: 12,
                  overflow: 'auto',
                  maxHeight: 500,
                }}
              ><pre>{jsonPreview}</pre>
              </Paper>
            </CardContent>
          </Card>
        )}
      </Box>

      {/* Actions */}
      <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 2, mt: 3 }}>
        {onCancel && (
          <Button variant="outlined" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button
          variant="outlined"
          startIcon={<TestIcon />}
          onClick={handleTest}
          disabled={isTesting}
        >
          {isTesting ? 'Testing...' : 'Test Rule'}
        </Button>
        <Button
          variant="contained"
          startIcon={<SaveIcon />}
          onClick={handleSave}
          disabled={isSaving}
        >
          {isSaving ? 'Saving...' : 'Save Rule'}
        </Button>
      </Box>
    </Box>
  );
};

export default RDLRuleBuilder;

import React, { useState, useCallback, useEffect } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Stepper,
  Step,
  StepLabel,
  Typography,
  Box,
  IconButton,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Checkbox,
  Chip,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Alert,
  CircularProgress,
  LinearProgress,
  Tooltip,
  Stack,
} from '@mui/material';
import {
  Close,
  Check,
  Edit,
  Cancel,
  Link as LinkIcon,
  LinkOff,
  Search,
  AutoFixHigh,
} from '@mui/icons-material';
import { useTenant } from '../../contexts/TenantContext';

// Types
interface RelationshipCandidate {
  left_table_id: string;
  left_table_name: string;
  left_column: string;
  right_table_id: string;
  right_table_name: string;
  right_column: string;
  cardinality: string;
  confidence: number;
  join_condition: string;
  join_type: string;
  origin: string;
  lookup_candidate: boolean;
  profile?: {
    left_distinct: number;
    right_distinct: number;
    left_row_count: number;
    right_row_count: number;
    join_selectivity: number;
    left_unique: boolean;
    right_unique: boolean;
  };
  match_reasons?: string[];
}

interface TableInfo {
  id: string;
  name: string;
  schema?: string;
  row_count?: number;
}

interface TableRelationshipWizardProps {
  open: boolean;
  onClose: () => void;
  onComplete?: () => void;
  initialTables?: TableInfo[];
}

export const TableRelationshipWizard: React.FC<TableRelationshipWizardProps> = ({
  open,
  onClose,
  onComplete,
  initialTables = [],
}) => {
  const { tenant, datasource } = useTenant();
  const tenantId = tenant?.id || '';
  const datasourceId = datasource?.id || '';

  const [activeStep, setActiveStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Step 1: Table selection
  const [availableTables, setAvailableTables] = useState<TableInfo[]>(initialTables);
  const [selectedTableIds, setSelectedTableIds] = useState<Set<string>>(new Set());
  const [tableSearch, setTableSearch] = useState('');

  // Step 2: Candidates
  const [candidates, setCandidates] = useState<RelationshipCandidate[]>([]);
  const [acceptedCandidates, setAcceptedCandidates] = useState<Set<number>>(new Set());
  const [rejectedCandidates, setRejectedCandidates] = useState<Set<number>>(new Set());

  // Step 3: Edit
  const [editingIndex, setEditingIndex] = useState<number | null>(null);
  const [editForm, setEditForm] = useState<Partial<RelationshipCandidate>>({});

  // Step 4: Results
  const [createdCount, setCreatedCount] = useState(0);

  const steps = ['Select Tables', 'Review Candidates', 'Edit & Confirm', 'Create Relationships'];

  useEffect(() => {
    if (open && availableTables.length === 0) {
      fetchTables();
    }
  }, [open]);

  const fetchTables = async () => {
    try {
      setLoading(true);
      const res = await fetch('/api/catalog/tables', {
        headers: {
          'X-Tenant-ID': tenantId,
          'X-Tenant-Datasource-ID': datasourceId,
        },
      });
      if (!res.ok) throw new Error('Failed to fetch tables');
      const data = await res.json();
      setAvailableTables(Array.isArray(data) ? data : data.tables || []);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load tables');
    } finally {
      setLoading(false);
    }
  };

  const discoverRelationships = async () => {
    if (selectedTableIds.size === 0) return;

    try {
      setLoading(true);
      setError(null);

      const res = await fetch('/api/relationships/infer', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Tenant-ID': tenantId,
          'X-Tenant-Datasource-ID': datasourceId,
        },
        body: JSON.stringify({
          table_ids: Array.from(selectedTableIds),
        }),
      });

      if (!res.ok) throw new Error('Failed to discover relationships');

      const data = await res.json();
      setCandidates(data.candidates || []);
      setAcceptedCandidates(new Set());
      setRejectedCandidates(new Set());
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Discovery failed');
    } finally {
      setLoading(false);
    }
  };

  const createRelationships = async () => {
    const toCreate = candidates.filter((_, idx) => acceptedCandidates.has(idx));
    if (toCreate.length === 0) return;

    try {
      setLoading(true);
      let created = 0;

      for (const candidate of toCreate) {
        const res = await fetch('/api/relationships/physical', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-Tenant-ID': tenantId,
            'X-Tenant-Datasource-ID': datasourceId,
          },
          body: JSON.stringify({
            source_table_id: candidate.left_table_id,
            target_table_id: candidate.right_table_id,
            join_condition: candidate.join_condition,
            join_type: candidate.join_type,
            cardinality: candidate.cardinality,
            confidence: candidate.confidence,
            origin: candidate.origin,
            lookup_candidate: candidate.lookup_candidate,
          }),
        });

        if (res.ok) created++;
      }

      setCreatedCount(created);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create relationships');
    } finally {
      setLoading(false);
    }
  };

  const handleNext = async () => {
    if (activeStep === 0) {
      await discoverRelationships();
    } else if (activeStep === 2) {
      await createRelationships();
    }
    setActiveStep((prev) => prev + 1);
  };

  const handleBack = () => setActiveStep((prev) => prev - 1);

  const handleClose = () => {
    onClose();
    if (createdCount > 0 && onComplete) {
      onComplete();
    }
    // Reset state
    setTimeout(() => {
      setActiveStep(0);
      setCandidates([]);
      setAcceptedCandidates(new Set());
      setRejectedCandidates(new Set());
      setCreatedCount(0);
      setError(null);
    }, 300);
  };

  const toggleTableSelection = (id: string) => {
    const newSet = new Set(selectedTableIds);
    if (newSet.has(id)) {
      newSet.delete(id);
    } else {
      newSet.add(id);
    }
    setSelectedTableIds(newSet);
  };

  const toggleCandidate = (idx: number, accept: boolean) => {
    if (accept) {
      const newAccepted = new Set(acceptedCandidates);
      if (newAccepted.has(idx)) {
        newAccepted.delete(idx);
      } else {
        newAccepted.add(idx);
        rejectedCandidates.delete(idx);
        setRejectedCandidates(new Set(rejectedCandidates));
      }
      setAcceptedCandidates(newAccepted);
    } else {
      const newRejected = new Set(rejectedCandidates);
      if (newRejected.has(idx)) {
        newRejected.delete(idx);
      } else {
        newRejected.add(idx);
        acceptedCandidates.delete(idx);
        setAcceptedCandidates(new Set(acceptedCandidates));
      }
      setRejectedCandidates(newRejected);
    }
  };

  const startEdit = (idx: number) => {
    setEditingIndex(idx);
    setEditForm({ ...candidates[idx] });
  };

  const saveEdit = () => {
    if (editingIndex !== null) {
      const updated = [...candidates];
      updated[editingIndex] = { ...candidates[editingIndex], ...editForm };
      setCandidates(updated);
      setEditingIndex(null);
    }
  };

  const filteredTables = availableTables.filter((t) =>
    t.name.toLowerCase().includes(tableSearch.toLowerCase())
  );

  const getConfidenceColor = (confidence: number) => {
    if (confidence >= 0.8) return 'success';
    if (confidence >= 0.6) return 'warning';
    return 'error';
  };

  const isNextDisabled = () => {
    if (activeStep === 0) return selectedTableIds.size < 2;
    if (activeStep === 2) return acceptedCandidates.size === 0;
    return loading;
  };

  return (
    <Dialog open={open} onClose={handleClose} maxWidth="lg" fullWidth>
      <DialogTitle>
        <Stack direction="row" alignItems="center" spacing={1}>
          <AutoFixHigh color="primary" />
          <Typography variant="h6">Table Relationship Wizard</Typography>
        </Stack>
        <IconButton onClick={handleClose} sx={{ position: 'absolute', right: 8, top: 8 }}>
          <Close />
        </IconButton>
      </DialogTitle>

      <DialogContent dividers>
        <Stepper activeStep={activeStep} sx={{ mb: 4 }}>
          {steps.map((label) => (
            <Step key={label}>
              <StepLabel>{label}</StepLabel>
            </Step>
          ))}
        </Stepper>

        {loading && <LinearProgress sx={{ mb: 2 }} />}
        {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}

        {/* Step 1: Select Tables */}
        {activeStep === 0 && (
          <Box>
            <Typography variant="subtitle1" gutterBottom>
              Select tables to analyze for relationships
            </Typography>
            <TextField
              fullWidth
              size="small"
              placeholder="Search tables..."
              value={tableSearch}
              onChange={(e) => setTableSearch(e.target.value)}
              InputProps={{ startAdornment: <Search sx={{ mr: 1, color: 'text.secondary' }} /> }}
              sx={{ mb: 2 }}
            />
            <Paper variant="outlined" sx={{ maxHeight: 400, overflow: 'auto' }}>
              <Table size="small" stickyHeader>
                <TableHead>
                  <TableRow>
                    <TableCell padding="checkbox"></TableCell>
                    <TableCell>Table Name</TableCell>
                    <TableCell>Schema</TableCell>
                    <TableCell align="right">Row Count</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {filteredTables.map((table) => (
                    <TableRow
                      key={table.id}
                      hover
                      onClick={() => toggleTableSelection(table.id)}
                      sx={{ cursor: 'pointer' }}
                    >
                      <TableCell padding="checkbox">
                        <Checkbox checked={selectedTableIds.has(table.id)} />
                      </TableCell>
                      <TableCell>{table.name}</TableCell>
                      <TableCell>{table.schema || '-'}</TableCell>
                      <TableCell align="right">
                        {table.row_count?.toLocaleString() || '-'}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </Paper>
            <Typography variant="caption" sx={{ mt: 1, display: 'block' }}>
              Selected: {selectedTableIds.size} tables
            </Typography>
          </Box>
        )}

        {/* Step 2: Review Candidates */}
        {activeStep === 1 && (
          <Box>
            <Typography variant="subtitle1" gutterBottom>
              Review discovered relationship candidates ({candidates.length} found)
            </Typography>
            {candidates.length === 0 ? (
              <Alert severity="info">
                No relationship candidates found. Try selecting more tables or tables with matching column names.
              </Alert>
            ) : (
              <TableContainer component={Paper} variant="outlined" sx={{ maxHeight: 400 }}>
                <Table size="small" stickyHeader>
                  <TableHead>
                    <TableRow>
                      <TableCell>Left Table</TableCell>
                      <TableCell>Right Table</TableCell>
                      <TableCell>Join Condition</TableCell>
                      <TableCell>Cardinality</TableCell>
                      <TableCell>Confidence</TableCell>
                      <TableCell>Lookup</TableCell>
                      <TableCell align="center">Actions</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {candidates.map((candidate, idx) => (
                      <TableRow
                        key={idx}
                        sx={{
                          bgcolor: acceptedCandidates.has(idx)
                            ? 'success.light'
                            : rejectedCandidates.has(idx)
                            ? 'error.light'
                            : 'inherit',
                          opacity: rejectedCandidates.has(idx) ? 0.5 : 1,
                        }}
                      >
                        <TableCell>{candidate.left_table_name}</TableCell>
                        <TableCell>{candidate.right_table_name}</TableCell>
                        <TableCell>
                          <Typography variant="caption" fontFamily="monospace">
                            {candidate.join_condition}
                          </Typography>
                        </TableCell>
                        <TableCell>
                          <Chip label={candidate.cardinality} size="small" variant="outlined" />
                        </TableCell>
                        <TableCell>
                          <Chip
                            label={`${Math.round(candidate.confidence * 100)}%`}
                            size="small"
                            color={getConfidenceColor(candidate.confidence)}
                          />
                        </TableCell>
                        <TableCell>
                          {candidate.lookup_candidate && (
                            <Chip label="Lookup" size="small" color="info" variant="outlined" />
                          )}
                        </TableCell>
                        <TableCell align="center">
                          <Stack direction="row" spacing={0.5} justifyContent="center">
                            <Tooltip title="Accept">
                              <IconButton
                                size="small"
                                color={acceptedCandidates.has(idx) ? 'success' : 'default'}
                                onClick={() => toggleCandidate(idx, true)}
                              >
                                <Check />
                              </IconButton>
                            </Tooltip>
                            <Tooltip title="Reject">
                              <IconButton
                                size="small"
                                color={rejectedCandidates.has(idx) ? 'error' : 'default'}
                                onClick={() => toggleCandidate(idx, false)}
                              >
                                <Cancel />
                              </IconButton>
                            </Tooltip>
                            <Tooltip title="Edit">
                              <IconButton size="small" onClick={() => startEdit(idx)}>
                                <Edit />
                              </IconButton>
                            </Tooltip>
                          </Stack>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            )}
            <Typography variant="caption" sx={{ mt: 1, display: 'block' }}>
              Accepted: {acceptedCandidates.size} | Rejected: {rejectedCandidates.size}
            </Typography>
          </Box>
        )}

        {/* Step 3: Edit & Confirm */}
        {activeStep === 2 && (
          <Box>
            <Typography variant="subtitle1" gutterBottom>
              Review accepted relationships before creating
            </Typography>
            {acceptedCandidates.size === 0 ? (
              <Alert severity="warning">
                No relationships accepted. Go back and accept at least one candidate.
              </Alert>
            ) : (
              <TableContainer component={Paper} variant="outlined">
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Left Table → Right Table</TableCell>
                      <TableCell>Join Condition</TableCell>
                      <TableCell>Cardinality</TableCell>
                      <TableCell>Type</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {candidates
                      .filter((_, idx) => acceptedCandidates.has(idx))
                      .map((c, i) => (
                        <TableRow key={i}>
                          <TableCell>
                            {c.left_table_name} → {c.right_table_name}
                          </TableCell>
                          <TableCell>
                            <Typography variant="caption" fontFamily="monospace">
                              {c.join_condition}
                            </Typography>
                          </TableCell>
                          <TableCell>{c.cardinality}</TableCell>
                          <TableCell>
                            {c.lookup_candidate ? 'Lookup' : 'Regular'}
                          </TableCell>
                        </TableRow>
                      ))}
                  </TableBody>
                </Table>
              </TableContainer>
            )}
          </Box>
        )}

        {/* Step 4: Results */}
        {activeStep === 3 && (
          <Box textAlign="center" py={4}>
            {loading ? (
              <>
                <CircularProgress />
                <Typography sx={{ mt: 2 }}>Creating relationships...</Typography>
              </>
            ) : (
              <>
                <LinkIcon sx={{ fontSize: 64, color: 'success.main', mb: 2 }} />
                <Typography variant="h5" gutterBottom>
                  {createdCount} Relationship{createdCount !== 1 ? 's' : ''} Created
                </Typography>
                <Typography color="text.secondary">
                  Physical table relationships have been saved. These will be available for BO inheritance.
                </Typography>
              </>
            )}
          </Box>
        )}

        {/* Edit Dialog */}
        <Dialog open={editingIndex !== null} onClose={() => setEditingIndex(null)} maxWidth="sm" fullWidth>
          <DialogTitle>Edit Relationship</DialogTitle>
          <DialogContent>
            <Stack spacing={2} sx={{ mt: 2 }}>
              <TextField
                fullWidth
                label="Join Condition"
                value={editForm.join_condition || ''}
                onChange={(e) => setEditForm({ ...editForm, join_condition: e.target.value })}
              />
              <FormControl fullWidth>
                <InputLabel>Join Type</InputLabel>
                <Select
                  value={editForm.join_type || 'left'}
                  label="Join Type"
                  onChange={(e) => setEditForm({ ...editForm, join_type: e.target.value })}
                >
                  <MenuItem value="inner">Inner</MenuItem>
                  <MenuItem value="left">Left</MenuItem>
                  <MenuItem value="right">Right</MenuItem>
                  <MenuItem value="full">Full</MenuItem>
                </Select>
              </FormControl>
              <FormControl fullWidth>
                <InputLabel>Cardinality</InputLabel>
                <Select
                  value={editForm.cardinality || 'unknown'}
                  label="Cardinality"
                  onChange={(e) => setEditForm({ ...editForm, cardinality: e.target.value })}
                >
                  <MenuItem value="1:1">1:1 (One-to-One)</MenuItem>
                  <MenuItem value="1:M">1:M (One-to-Many)</MenuItem>
                  <MenuItem value="M:1">M:1 (Many-to-One)</MenuItem>
                  <MenuItem value="M:M">M:M (Many-to-Many)</MenuItem>
                  <MenuItem value="unknown">Unknown</MenuItem>
                </Select>
              </FormControl>
            </Stack>
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setEditingIndex(null)}>Cancel</Button>
            <Button variant="contained" onClick={saveEdit}>Save</Button>
          </DialogActions>
        </Dialog>
      </DialogContent>

      <DialogActions>
        <Button onClick={handleBack} disabled={activeStep === 0 || loading}>
          Back
        </Button>
        {activeStep < steps.length - 1 ? (
          <Button
            variant="contained"
            onClick={handleNext}
            disabled={isNextDisabled()}
          >
            {activeStep === 2 ? 'Create Relationships' : 'Next'}
          </Button>
        ) : (
          <Button variant="contained" onClick={handleClose}>
            Done
          </Button>
        )}
      </DialogActions>
    </Dialog>
  );
};

