interface ColumnTag {
  id: string;
  label: string;
  type: 'id' | 'text' | 'date';
  originalType?: string;
  description?: string;
  databaseColumn: string; // Actual database column name (technical_name)
  tableAlias?: string;
}

export const QueryLibraryDashboard: React.FC = () => {
  const [queryName, setQueryName] = useState('Untitled Query');
  const [selectedDataset, setSelectedDataset] = useState<string>('');
  const [selectedColumns, setSelectedColumns] = useState<ColumnTag[]>([]);
  const [activeTab, setActiveTab] = useState(0);
  const [settingsAnchorEl, setSettingsAnchorEl] = useState<null | HTMLElement>(null);
  const [density, setDensity] = useState('Compact');
  const [expandedNodes, setExpandedNodes] = useState<Set<string>>(new Set());
  const [conditionsJson, setConditionsJson] = useState<string>('{}');
  const [queryResults, setQueryResults] = useState<any[]>([]);
  const [isExecuting, setIsExecuting] = useState(false);
  const [queryError, setQueryError] = useState<string | null>(null);
  const [selectedSemanticTerm, setSelectedSemanticTerm] = useState<any>(null);
  const [semanticTermModalOpen, setSemanticTermModalOpen] = useState(false);

  // Fetch real data
  const { data: datasets, isLoading: isLoadingDatasets } = useDatasets();
  const { data: savedQueries, isLoading: isLoadingQueries, error: queriesError } = useReportTemplates();
  // Pass selectedDataset to useBusinessObjects to filter by the selected scope
  const { data: businessObjects, isLoading: isLoadingBO, error: boError } = useBusinessObjects(selectedDataset);

  // Auto-select first dataset
  const activeDataset = useMemo(() => {
    if (selectedDataset && datasets) {
      return datasets.find(d => d.id === selectedDataset);
    }
    if (datasets?.length && !selectedDataset) {
      setSelectedDataset(datasets[0].id);
      return datasets[0];
    }
    return undefined;
  }, [datasets, selectedDataset]);

  // Extract available fields from active dataset
  const availableFields = useMemo(() => {
    if (!activeDataset?.fields) return [];
    return activeDataset.fields.map((field, idx) => ({
      id: `field_${idx}`,
      label: field.name || 'Field',
      type: getFieldTypeCategory(field.type),
      originalType: field.type,
      description: field.description,
      databaseColumn: field.name || 'unknown',
      tableAlias: 't0',
    }));
  }, [activeDataset]);

  const getFieldTypeCategory = (type?: string): 'id' | 'text' | 'date' => {
    if (!type) return 'text';
    const lower = type.toLowerCase();
    if (lower.includes('date') || lower.includes('time')) return 'date';
    if (lower.includes('int') || lower.includes('bigint') || lower.includes('numeric')) return 'id';
    return 'text';
  };

  const handleSettingsClick = (event: React.MouseEvent<HTMLElement>) => {
    setSettingsAnchorEl(event.currentTarget);
  };

  const handleSettingsClose = () => {
    setSettingsAnchorEl(null);
  };

  const handleDensityChange = (newDensity: string) => {
    setDensity(newDensity);
    handleSettingsClose();
  };

  const handleRemoveColumn = (id: string) => {
    setSelectedColumns(selectedColumns.filter(col => col.id !== id));
  };

  const toggleNode = (nodeId: string) => {
    const newExpanded = new Set(expandedNodes);
    if (newExpanded.has(nodeId)) {
      newExpanded.delete(nodeId);
    } else {
      newExpanded.add(nodeId);
    }
    setExpandedNodes(newExpanded);
  };

  const getFieldIcon = (type: 'id' | 'text' | 'date') => {
    switch (type) {
      case 'id':
        return <CodeIcon sx={{ fontSize: 14 }} />;
      case 'text':
        return <TextFieldsIcon sx={{ fontSize: 14 }} />;
      case 'date':
        return <AccessTimeIcon sx={{ fontSize: 14 }} />;
    }
  };

  const normalizeFieldReference = (value: string): string => {
    const trimmed = value.trim();
    if (!trimmed) return '';
    if (trimmed.includes('.')) return trimmed;
    return `t0.${trimmed.replace(/\s+/g, '_')}`;
  };

  const buildSqlWhere = (condition: any): string => {
    if (!condition || typeof condition !== 'object') {
      return '';
    }
    if (condition.type && Array.isArray(condition.conditions)) {
      const childSql = condition.conditions
        .map(buildSqlWhere)
        .filter(Boolean);
      if (childSql.length === 0) {
        return '';
      }
      if (condition.type === 'NOT') {
        return `NOT (${childSql[0]})`;
      }
      return `(${childSql.join(` ${condition.type} `)})`;
    }
    if (!condition.field || !condition.operator) {
      return '';
    }

    const field = normalizeFieldReference(String(condition.field ?? ''));
    if (!field) return '';
    const rawValue = String(condition.value ?? '');
    const numericValue = rawValue !== '' && !Number.isNaN(Number(rawValue)) ? Number(rawValue) : null;
    const quoteValue = (value: string) => `'${value.replace(/'/g, "''")}'`;

    switch (condition.operator) {
      case 'contains':
        return `${field} LIKE ${quoteValue(`%${rawValue}%`)}`;
      case 'startsWith':
        return `${field} LIKE ${quoteValue(`${rawValue}%`)}`;
      case 'endsWith':
        return `${field} LIKE ${quoteValue(`%${rawValue}`)}`;
      case 'in': {
        const values = rawValue.split(',').map((v: string) => v.trim()).filter(Boolean);
        if (values.length === 0) return '';
        const formatted = values.map((v: string) => (Number.isNaN(Number(v)) ? quoteValue(v) : String(Number(v))));
        return `${field} IN (${formatted.join(', ')})`;
      }
      case 'regex': {
        if (!rawValue) return '';
        return `${field} ~ ${quoteValue(rawValue)}`;
      }
      case 'between': {
        const parts = rawValue.split(',').map((v: string) => v.trim()).filter(Boolean);
        if (parts.length < 2) return '';
        const left = Number.isNaN(Number(parts[0])) ? quoteValue(parts[0]) : String(Number(parts[0]));
        const right = Number.isNaN(Number(parts[1])) ? quoteValue(parts[1]) : String(Number(parts[1]));
        return `${field} BETWEEN ${left} AND ${right}`;
      }
      case 'isEmpty':
        return `(${field} IS NULL OR ${field} = '')`;
      default: {
        if (!rawValue) return '';
        const formattedValue = numericValue === null ? quoteValue(rawValue) : String(numericValue);
        return `${field} ${condition.operator} ${formattedValue}`;
      }
    }
  };

  const sqlWhere = useMemo(() => {
    try {
      const parsed = JSON.parse(conditionsJson);
      return buildSqlWhere(parsed);
    } catch {
      return '';
    }
  }, [conditionsJson]);

  const sqlCode = `SELECT ${selectedColumns.length > 0 ? selectedColumns.map(c => `t0.${c.databaseColumn}`).join(', ') : '-- Select columns to generate SQL'}
${activeDataset ? `FROM ${activeDataset.name} t0` : '-- Select a dataset'}
${sqlWhere ? `WHERE ${sqlWhere}` : ''}
LIMIT 100;`;

  const isLoading = isLoadingDatasets || isLoadingQueries || isLoadingBO;

  const handleAddField = (field: any) => {
    if (!selectedColumns.find(c => c.id === field.id)) {
      setSelectedColumns([...selectedColumns, {
        id: field.id,
        label: field.label,
        type: field.type,
        originalType: field.originalType,
        description: field.description,
        databaseColumn: field.databaseColumn || field.label.toLowerCase().replace(/\s+/g, '_'),
        tableAlias: 't0',
      } as any]);
    }
  };

  const getBOPropertyType = (dataType?: string): 'id' | 'text' | 'date' => {
    if (!dataType) return 'text';
    const lower = dataType.toLowerCase();
    if (lower.includes('date') || lower.includes('time')) return 'date';
    if (lower.includes('int') || lower.includes('bigint') || lower.includes('numeric') || lower.includes('number')) return 'id';
    return 'text';
  };

  const handleRunQuery = async () => {
    try {
      setIsExecuting(true);
      setQueryError(null);
      // Mock execution - replace with actual API call
      const mockResults = selectedColumns.map((col, idx) => ({
        ...selectedColumns.reduce((acc, c) => ({ ...acc, [c.label]: `Value ${idx}` }), {}),
      })).slice(0, 10);
      setTimeout(() => {
        setQueryResults(mockResults);
        setIsExecuting(false);
      }, 500);
    } catch (error) {
      setQueryError(error instanceof Error ? error.message : 'Failed to execute query');
      setIsExecuting(false);
    }
  };

  const handleFieldInfoClick = async (field: any) => {
    try {
      // Try to fetch semantic term details if available
      if (field.semanticTermId) {
        const response = await fetch(`/api/glossary/terms/${field.semanticTermId}`);
        if (response.ok) {
          const data = await response.json();
          setSelectedSemanticTerm(data);
          setSemanticTermModalOpen(true);
        }
      } else {
        // Show basic field info in modal
        setSelectedSemanticTerm({
          node_name: field.label,
          description: field.description || 'No description available',
          type: field.originalType,
          is_semantic: false,
        });
        setSemanticTermModalOpen(true);
      }
    } catch (error) {
      devLog('Could not fetch semantic term details');
      setSelectedSemanticTerm({
        node_name: field.label,
        description: field.description || 'No description available',
        type: field.originalType,
        is_semantic: false,
      });
      setSemanticTermModalOpen(true);
    }
  };

  return (
    <Box sx={{ height: '100vh', display: 'flex', flexDirection: 'column', bgcolor: '#f4f6f8' }}>
      {isLoading && (
        <Box sx={{ height: '100vh', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
          <CircularProgress />
        </Box>
      )}

      {!isLoading && (
        <>
          {/* Header */}
         <Box
        sx={{
          height: 56,
          bgcolor: '#1976d2', // Material Blue
          color: 'white',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          px: 2,
          boxShadow: 1,
          zIndex: 1200,
        }}
      >
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
          <Button sx={{ color: 'white', minWidth: 'auto', p: 1 }}><MenuIcon /></Button>
          <Typography variant="subtitle1" fontWeight={600} sx={{ letterSpacing: 0.5 }}>
            Enterprise Query Builder
          </Typography>
        </Box>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <Button
            variant="outlined"
            size="small"
            startIcon={<SaveIcon />}
            sx={{
              color: 'white',
              borderColor: 'rgba(255,255,255,0.5)',
              '&:hover': { borderColor: 'white', bgcolor: 'rgba(255,255,255,0.1)' },
            }}
          >
            Save Query
          </Button>
          <Button
            variant="contained"
            size="small"
            onClick={handleRunQuery}
            disabled={isExecuting || selectedColumns.length === 0}
            sx={{
              bgcolor: 'white',
              color: '#1976d2',
              fontWeight: 600,
              '&:hover': { bgcolor: '#f5f5f5' },
            }}
          >
            Run Query
          </Button>
          <IconButton size="small" sx={{ color: 'white' }}>
            <SettingsIcon />
          </IconButton>
        </Box>
      </Box>

      {/* Content */}
      <Box sx={{ display: 'flex', flex: 1, overflow: 'hidden' }}>

        {/* Sidebar */}
        <Paper
          elevation={0}
          sx={{
            width: 260,
            borderRight: '1px solid #e0e0e0',
            display: 'flex',
            flexDirection: 'column',
            bgcolor: 'white',
            zIndex: 1100,
          }}
        >
          <Box sx={{ p: 2, borderBottom: '1px solid #f0f0f0' }}>
            <Typography variant="caption" sx={{ color: 'text.secondary', fontWeight: 600, mb: 0.5, display: 'block' }}>
              SUBJECT AREA
            </Typography>
            <Select
              fullWidth
              size="small"
              value={selectedDataset}
              onChange={(e) => {
                 setSelectedDataset(e.target.value);
                 setSelectedColumns([]);
              }}
              displayEmpty
              variant="outlined"
              sx={{ 
                height: 36, 
                fontSize: 14,
                bgcolor: 'white',
              }}
            >
               <MenuItem value="" disabled>Select Subject Area...</MenuItem>
               {datasets?.map(ds => (
                  <MenuItem key={ds.id} value={ds.id}>{ds.name}</MenuItem>
               ))}
            </Select>
          </Box>

          <Box sx={{ flex: 1, overflow: 'auto', p: 1 }}>
             {/* Business Objects Tree */}
             {businessObjects && businessObjects.length > 0 ? (
               businessObjects.map((bo) => (
                <Box key={bo.id} sx={{ mb: 0.5 }}>
                   <Box
                      onClick={() => toggleNode(bo.id)}
                      sx={{
                        display: 'flex', 
                        alignItems: 'center', 
                        p: 1, 
                        cursor: 'pointer',
                        borderRadius: 1,
                        color: expandedNodes.has(bo.id) ? '#1976d2' : 'text.primary',
                        bgcolor: expandedNodes.has(bo.id) ? '#e3f2fd' : 'transparent',
                        '&:hover': { bgcolor: '#f5f5f5' }
                      }}
                   >
                     {expandedNodes.has(bo.id) ? <ExpandMoreIcon fontSize="small" /> : <ChevronRightIcon fontSize="small" />}
                     <Typography variant="body2" fontWeight={500} sx={{ ml: 1 }}>{bo.name}</Typography>
                   </Box>

                   <Collapse in={expandedNodes.has(bo.id)} timeout="auto" unmountOnExit>
                      <Box sx={{ pl: 4 }}>
                        {bo.fields?.map((field, idx) => (
                           <Box
                             key={`${bo.id}-${idx}`}
                             onClick={() => {
                                const col = {
                                   id: `${bo.id}-${field.name}`,
                                   label: field.label || field.name, // Use label!
                                   type: getBOPropertyType(field.type),
                                   databaseColumn: field.name,
                                };
                                if(!selectedColumns.find(c => c.id === col.id)) {
                                   setSelectedColumns([...selectedColumns, col as any]);
                                }
                             }}
                             sx={{
                               py: 0.5,
                               cursor: 'pointer',
                               display: 'flex',
                               alignItems: 'center',
                               gap: 1,
                               color: 'text.secondary',
                               '&:hover': { color: '#1976d2' }
                             }}
                           >
                              {getFieldIcon(getBOPropertyType(field.type))}
                              <Typography variant="body2">{field.label || field.name}</Typography>
                           </Box>
                        ))}
                      </Box>
                   </Collapse>
                </Box>
               ))
             ) : (
               /* Fallback: Show dataset fields when business objects are not available */
               activeDataset && availableFields.length > 0 && (
                 <Box>
                   <Box
                      sx={{
                        display: 'flex', 
                        alignItems: 'center', 
                        p: 1, 
                        borderRadius: 1,
                        color: '#1976d2',
                        bgcolor: '#e3f2fd',
                      }}
                   >
                     <Typography variant="body2" fontWeight={500} sx={{ ml: 1 }}>{activeDataset.name} Fields</Typography>
                   </Box>
                   <Box sx={{ pl: 4 }}>
                     {availableFields.map((field) => (
                        <Box
                          key={field.id}
                          onClick={() => handleAddField(field)}
                          sx={{
                            py: 0.5,
                            cursor: 'pointer',
                            display: 'flex',
                            alignItems: 'center',
                            gap: 1,
                            color: 'text.secondary',
                            '&:hover': { color: '#1976d2' }
                          }}
                        >
                           {getFieldIcon(field.type)}
                           <Typography variant="body2">{field.label}</Typography>
                        </Box>
                     ))}
                   </Box>
                 </Box>
               )
             )}
          </Box>
        </Paper>

        {/* Main Canvas */}
        <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', p: 3, gap: 3, overflow: 'auto' }}>

           {/* Query Definition Card */}
           <Paper sx={{ p: 3, borderRadius: 2 }}>
