                 flexWrap: 'wrap', 
                 gap: 1, 
                 p: 2, 
                 border: '1px solid #e0e0e0',
                 borderRadius: 1,
                 minHeight: 60,
                 alignItems: 'center',
                 bgcolor: '#fafafa'
              }}>
                 {selectedColumns.map((col) => (
                    <Chip
                       key={col.id}
                       icon={getFieldIcon(col.type)}
                       label={col.label}
                       onDelete={() => handleRemoveColumn(col.id)}
                       sx={{ 
                          bgcolor: 'white', 
                          border: '1px solid #e0e0e0',
                          borderRadius: 1,
                          '& .MuiChip-label': { fontWeight: 500 }
                       }}
                    />
                 ))}
                 <Button
                       startIcon={<Box component="span" sx={{fontSize: 18}}>+</Box>}
                    sx={{ 
                       textTransform: 'none', 
                       border: '1px dashed #bdbdbd',
                       color: 'text.secondary',
                       height: 32,
                       borderRadius: 1
                    }}
                 >
                    Add Column
                 </Button>
              </Box>

              <Box sx={{ mt: 3 }}>
                 <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                    <Typography variant="caption" fontWeight={700} color="text.secondary">
                       FILTERS
                    </Typography>
                    <Button size="small" sx={{ textTransform: 'none' }}>Clear All</Button>
                 </Box>
                 <Box sx={{ p: 2, border: '1px solid #e0e0e0', borderRadius: 1, bgcolor: '#fafafa' }}>
