            {/* Avg Score (Not a filter logic typically, but keeping style consistent) */}
            <Box sx={{ 
              p: 1.5, 
              borderRadius: 2, 
              border: '1px solid rgba(245, 158, 11, 0.2)',
              bgcolor: 'rgba(245, 158, 11, 0.04)',
              display: 'flex',
              flexDirection: 'column',
              minWidth: '130px',
              transition: 'transform 0.2s',
              '&:hover': { transform: 'translateY(-2px)' }
            }}>
              <Typography variant="caption" sx={{ color: '#64748b', fontWeight: 600, mb: 0.5 }}>Avg. Score</Typography>
              <Typography variant="h6" sx={{ color: '#d97706', fontWeight: 700 }}>{averageScore.toFixed(0)}%</Typography>
            </Box>

            {hasScopeFilter && (
               <Box sx={{ 
                p: 1.5, 
                borderRadius: 2, 
                border: '1px solid rgba(239, 68, 68, 0.2)',
                bgcolor: 'rgba(239, 68, 68, 0.04)',
                display: 'flex',
                alignItems: 'center',
                gap: 1
              }}>
                <Filter className="w-4 h-4 text-red-500" />
                <Typography variant="subtitle2" sx={{ color: '#dc2626', fontWeight: 600 }}>Filters Active</Typography>
              </Box>
            )}
          </Box>

          <Box sx={{ 
            display: 'flex', 
            alignItems: 'center', 
            gap: 1.5,
            background: 'rgba(255, 255, 255, 0.7)',
            backdropFilter: 'blur(8px)',
            borderRadius: 2,
            px: 2,
            py: 1,
            border: '1px solid rgba(226, 232, 240, 0.5)'
          }}>
            <Typography variant="caption" sx={{ fontWeight: 600, color: '#475569' }}>Sort by:</Typography>
            <Select 
              value={sortBy} 
              onChange={(e) => setSortBy(e.target.value as any)} 
              size="small" 
              sx={{ 
                minWidth: 140, 
                fontSize: '0.875rem',
                '& .MuiOutlinedInput-root': {
                  borderRadius: 1.5,
                  '& fieldset': {
                    borderColor: 'rgba(226, 232, 240, 0.5)'
                  },
                  '&:hover fieldset': {
                    borderColor: '#3b82f6'
                  }
                }
              }}
            >
              <MenuItem value="confidence">🎯 Confidence</MenuItem>
              <MenuItem value="name">🔤 Column Name</MenuItem>
              <MenuItem value="none">📋 Original</MenuItem>
            </Select>
          </Box>
        </Box>
      </CardContent>
    </Card>
  );
}

/**
 * Report Designer Component
 * 
 * A drag-drop SSRS-style report designer for creating and editing
 * report definitions using the semantic reporting platform.
 */

import React, { useState, useCallback, useMemo } from 'react';
import {
  Box,
  Paper,
  Typography,
  Drawer,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  ListItemButton,
  Divider,
  TextField,
  Button,
  IconButton,
  Toolbar,
  Tabs,
  Tab,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Chip,
  Alert,
  Snackbar,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Tooltip,
  Card,
  CardContent,
} from '@mui/material';
import {
  DndContext,
  DragOverlay,
  useDraggable,
  useDroppable,
  DragEndEvent,
  DragStartEvent,
} from '@dnd-kit/core';
import {
  Save,
  Undo,
  Redo,
  Preview,
  Settings,
  ExpandMore,
  Add,
  Delete,
  DragIndicator,
  TextFields,
  Image,
  TableChart,
  BarChart,
  PieChart,
  ShowChart,
  Dashboard,
  DataObject,
  Numbers,
  CalendarMonth,
  ToggleOn,
  FormatListBulleted,
  Close,
} from '@mui/icons-material';
import {
  useReportDefinition,
  useCreateReportDefinition,
  useUpdateReportDefinition,
} from '../../hooks/useSemanticReporting';
import {
  ReportLayout,
  ReportSection,
  Parameter,
  DataBinding,
  TableColumn,
  LayoutElement,
  CreateDefinitionRequest,
} from '../../api/semanticReporting';
import { useTenant } from '../../contexts/TenantContext';
import { devLog } from '../../utils/devLogger';

// ============================================================================
// TYPES
// ============================================================================

interface DesignerElement {
  id: string;
  type: string;
  label: string;
  icon: React.ReactNode;
}

interface DesignerSection {
  id: string;
  type: 'summary' | 'table' | 'chart' | 'text';
  title: string;
  data_binding?: string;
  columns?: TableColumn[];
  elements?: LayoutElement[];
}

interface ReportDesignerProps {
  reportId?: string; // If provided, edit existing report
  onSave?: (reportId: string) => void;
  onCancel?: () => void;
}

// ============================================================================
// TOOLBOX ELEMENTS
// ============================================================================

const SECTION_ELEMENTS: DesignerElement[] = [
  { id: 'summary', type: 'summary', label: 'Summary Section', icon: <Dashboard /> },
  { id: 'table', type: 'table', label: 'Data Table', icon: <TableChart /> },
  { id: 'chart-bar', type: 'chart', label: 'Bar Chart', icon: <BarChart /> },
  { id: 'chart-line', type: 'chart', label: 'Line Chart', icon: <ShowChart /> },
  { id: 'chart-pie', type: 'chart', label: 'Pie Chart', icon: <PieChart /> },
  { id: 'text', type: 'text', label: 'Text Block', icon: <TextFields /> },
];

const FIELD_ELEMENTS: DesignerElement[] = [
  { id: 'text-field', type: 'text', label: 'Text', icon: <TextFields /> },
  { id: 'image-field', type: 'image', label: 'Image', icon: <Image /> },
  { id: 'kpi-card', type: 'kpiCard', label: 'KPI Card', icon: <Numbers /> },
];

const PARAMETER_TYPES: DesignerElement[] = [
  { id: 'param-string', type: 'string', label: 'Text', icon: <TextFields /> },
  { id: 'param-number', type: 'number', label: 'Number', icon: <Numbers /> },
  { id: 'param-date', type: 'date', label: 'Date', icon: <CalendarMonth /> },
  { id: 'param-boolean', type: 'boolean', label: 'Yes/No', icon: <ToggleOn /> },
  { id: 'param-select', type: 'select', label: 'Dropdown', icon: <FormatListBulleted /> },
];

// ============================================================================
// DRAGGABLE TOOLBOX ITEM
// ============================================================================

const ToolboxItem: React.FC<{ element: DesignerElement }> = ({ element }) => {
  const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
    id: `toolbox-${element.id}`,
    data: { element },
  });

  return (
    <ListItem disablePadding>
      <ListItemButton
        ref={setNodeRef}
        {...listeners}
        {...attributes}
        sx={{
          opacity: isDragging ? 0.5 : 1,
          cursor: 'grab',
          '&:active': { cursor: 'grabbing' },
        }}
      >
        <ListItemIcon sx={{ minWidth: 36 }}>{element.icon}</ListItemIcon>
        <ListItemText primary={element.label} primaryTypographyProps={{ variant: 'body2' }} />
      </ListItemButton>
    </ListItem>
  );
};

// ============================================================================
// DROPPABLE CANVAS AREA
// ============================================================================

interface CanvasDropZoneProps {
  children: React.ReactNode;
  onDrop: (element: DesignerElement, position: number) => void;
}

const CanvasDropZone: React.FC<CanvasDropZoneProps> = ({ children }) => {
  const { setNodeRef, isOver } = useDroppable({ id: 'canvas-drop-zone' });

  return (
    <Box
      ref={setNodeRef}
      sx={{
        minHeight: 400,
        p: 2,
        bgcolor: isOver ? 'action.hover' : 'grey.50',
        border: '2px dashed',
        borderColor: isOver ? 'primary.main' : 'grey.300',
        borderRadius: 1,
        transition: 'all 0.2s',
      }}
    >
      {children}
    </Box>
  );
};

// ============================================================================
// SECTION CARD (Rendered in Canvas)
// ============================================================================

interface SectionCardProps {
  section: DesignerSection;
  isSelected: boolean;
  onSelect: () => void;
  onDelete: () => void;
  onUpdate: (updates: Partial<DesignerSection>) => void;
}

const SectionCard: React.FC<SectionCardProps> = ({
  section,
  isSelected,
  onSelect,
  onDelete,
  onUpdate,
}) => {
  const { attributes, listeners, setNodeRef: setDragRef } = useDraggable({
    id: `section-${section.id}`,
    data: { section },
  });

  return (
    <Card
      ref={setDragRef}
      onClick={onSelect}
      sx={{
        mb: 2,
        cursor: 'pointer',
        border: 2,
        borderColor: isSelected ? 'primary.main' : 'transparent',
        '&:hover': { borderColor: isSelected ? 'primary.main' : 'grey.300' },
      }}
    >
      <CardContent>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <IconButton size="small" {...listeners} {...attributes} sx={{ cursor: 'grab' }}>
            <DragIndicator />
          </IconButton>
          <Typography variant="subtitle1" sx={{ flexGrow: 1 }}>
            {section.title || `${section.type} section`}
          </Typography>
          <Chip label={section.type} size="small" />
          <IconButton size="small" onClick={(e) => { e.stopPropagation(); onDelete(); }}>
            <Delete fontSize="small" />
          </IconButton>
        </Box>

        {section.type === 'table' && section.columns && (
          <Box sx={{ mt: 1, display: 'flex', gap: 0.5, flexWrap: 'wrap' }}>
            {section.columns.map((col, idx) => (
              <Chip key={idx} label={col.label} size="small" variant="outlined" />
            ))}
            {section.columns.length === 0 && (
              <Typography variant="caption" color="text.secondary">
                No columns configured
              </Typography>
            )}
          </Box>
        )}

        {section.data_binding && (
          <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1 }}>
            Data: {section.data_binding}
          </Typography>
        )}
      </CardContent>
    </Card>
  );
};

// ============================================================================
// PROPERTIES PANEL
// ============================================================================

interface PropertiesPanelProps {
  section: DesignerSection | null;
  onUpdate: (updates: Partial<DesignerSection>) => void;
  dataBindings: string[];
}

const PropertiesPanel: React.FC<PropertiesPanelProps> = ({ section, onUpdate, dataBindings }) => {
  if (!section) {
    return (
      <Box sx={{ p: 2, textAlign: 'center' }}>
        <Typography color="text.secondary">
          Select a section to edit its properties
        </Typography>
      </Box>
    );
  }

  return (
    <Box sx={{ p: 2 }}>
      <Typography variant="subtitle2" gutterBottom>
        Section Properties
      </Typography>

      <TextField
        label="Title"
        value={section.title || ''}
        onChange={(e) => onUpdate({ title: e.target.value })}
        fullWidth
        size="small"
        sx={{ mb: 2 }}
      />

      <FormControl fullWidth size="small" sx={{ mb: 2 }}>
        <InputLabel>Data Binding</InputLabel>
        <Select
          value={section.data_binding || ''}
          label="Data Binding"
          onChange={(e) => onUpdate({ data_binding: e.target.value })}
        >
          <MenuItem value="">None</MenuItem>
          {dataBindings.map((binding) => (
            <MenuItem key={binding} value={binding}>
              {binding}
            </MenuItem>
          ))}
        </Select>
      </FormControl>

      {section.type === 'table' && (
        <>
          <Typography variant="subtitle2" sx={{ mt: 2, mb: 1 }}>
            Columns
          </Typography>
          {section.columns?.map((col, idx) => (
            <Box key={idx} sx={{ display: 'flex', gap: 1, mb: 1 }}>
              <TextField
                label="Label"
                value={col.label}
                size="small"
                sx={{ flex: 1 }}
                onChange={(e) => {
                  const newColumns = [...(section.columns || [])];
                  newColumns[idx] = { ...col, label: e.target.value };
                  onUpdate({ columns: newColumns });
                }}
              />
              <IconButton
                size="small"
                onClick={() => {
                  const newColumns = section.columns?.filter((_, i) => i !== idx);
                  onUpdate({ columns: newColumns });
                }}
              >
                <Delete fontSize="small" />
              </IconButton>
            </Box>
          ))}
          <Button
            size="small"
            startIcon={<Add />}
            onClick={() => {
              const newColumns = [...(section.columns || []), { label: 'New Column', dimension: '' }];
              onUpdate({ columns: newColumns });
            }}
          >
            Add Column
          </Button>
        </>
      )}
    </Box>
  );
};

// ============================================================================
// MAIN REPORT DESIGNER COMPONENT
// ============================================================================

const ReportDesigner: React.FC<ReportDesignerProps> = ({ reportId, onSave, onCancel }) => {
  const { isSelected } = useTenant();

  // Report metadata state
  const [reportKey, setReportKey] = useState('');
  const [displayName, setDisplayName] = useState('');
  const [description, setDescription] = useState('');
  const [category, setCategory] = useState('');

  // Layout state
  const [sections, setSections] = useState<DesignerSection[]>([]);
  const [parameters, setParameters] = useState<Parameter[]>([]);
  const [dataBindings, setDataBindings] = useState<Record<string, DataBinding>>({});
  const [selectedSectionId, setSelectedSectionId] = useState<string | null>(null);

  // UI state
  const [activeTab, setActiveTab] = useState(0);
  const [activeDragItem, setActiveDragItem] = useState<DesignerElement | null>(null);
  const [snackbar, setSnackbar] = useState<{ open: boolean; message: string; severity: 'success' | 'error' }>({
    open: false,
    message: '',
    severity: 'success',
  });
  const [dataBindingDialogOpen, setDataBindingDialogOpen] = useState(false);
  const [parameterDialogOpen, setParameterDialogOpen] = useState(false);

  // Load existing report if editing
  const { data: existingReport, isLoading: loadingReport } = useReportDefinition(reportId);
  const createMutation = useCreateReportDefinition();
  const updateMutation = useUpdateReportDefinition();

  // Initialize from existing report
  React.useEffect(() => {
    if (existingReport) {
      setReportKey(existingReport.report_key);
      setDisplayName(existingReport.display_name);
      setDescription(existingReport.description || '');
      setCategory(existingReport.category || '');

      if (existingReport.definition) {
        // Convert layout sections to designer sections
        const designerSections: DesignerSection[] = existingReport.definition.layout.body.sections.map((s, idx) => ({
          id: `section-${idx}`,
          type: s.type as DesignerSection['type'],
          title: s.title || '',
          data_binding: s.data_binding,
          columns: s.columns,
          elements: s.elements,
        }));
        setSections(designerSections);
        setParameters(existingReport.definition.parameters || []);
        setDataBindings(existingReport.definition.data_bindings || {});
      }
    }
  }, [existingReport]);

  // Selected section
  const selectedSection = useMemo(
    () => sections.find((s) => s.id === selectedSectionId) || null,
    [sections, selectedSectionId]
  );

  // Drag handlers
  const handleDragStart = (event: DragStartEvent) => {
    const { active } = event;
    if (active.data.current?.element) {
      setActiveDragItem(active.data.current.element);
    }
  };

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    setActiveDragItem(null);

    if (over?.id === 'canvas-drop-zone' && active.data.current?.element) {
      const element = active.data.current.element as DesignerElement;

      // Create new section
      const newSection: DesignerSection = {
        id: `section-${Date.now()}`,
        type: element.type as DesignerSection['type'],
        title: '',
        columns: element.type === 'table' ? [] : undefined,
        elements: element.type === 'text' ? [] : undefined,
      };

      setSections((prev) => [...prev, newSection]);
      setSelectedSectionId(newSection.id);
    }
  };

  // Section handlers
  const handleUpdateSection = useCallback((updates: Partial<DesignerSection>) => {
    if (!selectedSectionId) return;
    setSections((prev) =>
      prev.map((s) => (s.id === selectedSectionId ? { ...s, ...updates } : s))
    );
  }, [selectedSectionId]);

  const handleDeleteSection = useCallback((sectionId: string) => {
    setSections((prev) => prev.filter((s) => s.id !== sectionId));
    if (selectedSectionId === sectionId) {
      setSelectedSectionId(null);
    }
  }, [selectedSectionId]);

  // Build report layout from designer state
  const buildReportLayout = (): ReportLayout => {
    return {
      metadata: {
        display_name: displayName,
        description,
        category,
        page_size: 'Letter',
        orientation: 'portrait',
      },
      data_bindings: dataBindings,
      parameters,
      layout: {
        body: {
          sections: sections.map((s) => ({
            id: s.id,
            type: s.type,
            title: s.title,
            data_binding: s.data_binding,
            columns: s.columns,
            elements: s.elements,
          })),
        },
      },
    };
  };

  // Save handler
  const handleSave = async () => {
    if (!reportKey || !displayName) {
      setSnackbar({ open: true, message: 'Report key and display name are required', severity: 'error' });
      return;
    }

    const layout = buildReportLayout();

    try {
      if (reportId && existingReport) {
        // Update existing
        await updateMutation.mutateAsync({
          id: reportId,
          updates: {
            display_name: displayName,
            description,
            category,
            definition: layout,
          },
        });
        setSnackbar({ open: true, message: 'Report updated successfully', severity: 'success' });
        onSave?.(reportId);
      } else {
        // Create new
        const request: CreateDefinitionRequest = {
          report_key: reportKey,
          display_name: displayName,
          description,
          category,
          definition: layout,
        };
        const created = await createMutation.mutateAsync(request);
        setSnackbar({ open: true, message: 'Report created successfully', severity: 'success' });
        onSave?.(created.id);
      }
    } catch (err) {
      devLog('Failed to save report:', err);
      setSnackbar({ open: true, message: 'Failed to save report', severity: 'error' });
    }
  };

  if (!isSelected) {
    return (
      <Box sx={{ p: 3 }}>
        <Alert severity="warning">
          Please select a tenant and datasource to create reports.
        </Alert>
      </Box>
    );
  }

  return (
    <DndContext onDragStart={handleDragStart} onDragEnd={handleDragEnd}>
      <Box sx={{ display: 'flex', height: '100vh' }}>
        {/* Left Toolbox */}
        <Drawer
          variant="permanent"
          sx={{
            width: 240,
            flexShrink: 0,
            '& .MuiDrawer-paper': { width: 240, position: 'relative' },
          }}
        >
          <Toolbar variant="dense">
            <Typography variant="subtitle1">Toolbox</Typography>
          </Toolbar>
          <Divider />

          <Accordion defaultExpanded>
            <AccordionSummary expandIcon={<ExpandMore />}>
              <Typography variant="body2">Sections</Typography>
            </AccordionSummary>
            <AccordionDetails sx={{ p: 0 }}>
              <List dense disablePadding>
                {SECTION_ELEMENTS.map((el) => (
                  <ToolboxItem key={el.id} element={el} />
                ))}
              </List>
            </AccordionDetails>
          </Accordion>

          <Accordion>
            <AccordionSummary expandIcon={<ExpandMore />}>
              <Typography variant="body2">Fields</Typography>
            </AccordionSummary>
            <AccordionDetails sx={{ p: 0 }}>
              <List dense disablePadding>
                {FIELD_ELEMENTS.map((el) => (
                  <ToolboxItem key={el.id} element={el} />
                ))}
              </List>
            </AccordionDetails>
          </Accordion>

          <Divider sx={{ my: 1 }} />

          <Box sx={{ p: 1 }}>
            <Button
              fullWidth
              size="small"
              startIcon={<DataObject />}
              onClick={() => setDataBindingDialogOpen(true)}
            >
              Data Bindings ({Object.keys(dataBindings).length})
            </Button>
            <Button
              fullWidth
              size="small"
              startIcon={<Settings />}
              onClick={() => setParameterDialogOpen(true)}
              sx={{ mt: 1 }}
            >
              Parameters ({parameters.length})
            </Button>
          </Box>
        </Drawer>

        {/* Main Content */}
        <Box sx={{ flexGrow: 1, display: 'flex', flexDirection: 'column' }}>
          {/* Toolbar */}
          <Toolbar variant="dense" sx={{ borderBottom: 1, borderColor: 'divider' }}>
            <TextField
              label="Report Key"
              value={reportKey}
              onChange={(e) => setReportKey(e.target.value)}
              size="small"
              sx={{ width: 150, mr: 1 }}
              disabled={!!reportId}
            />
            <TextField
              label="Display Name"
              value={displayName}
              onChange={(e) => setDisplayName(e.target.value)}
              size="small"
              sx={{ width: 200, mr: 1 }}
            />
            <TextField
              label="Category"
              value={category}
              onChange={(e) => setCategory(e.target.value)}
              size="small"
              sx={{ width: 120, mr: 2 }}
            />

            <Box sx={{ flexGrow: 1 }} />

            <Tooltip title="Undo">
              <IconButton size="small">
                <Undo />
              </IconButton>
            </Tooltip>
            <Tooltip title="Redo">
              <IconButton size="small">
                <Redo />
              </IconButton>
            </Tooltip>
            <Divider orientation="vertical" flexItem sx={{ mx: 1 }} />
            <Tooltip title="Preview">
              <IconButton size="small">
                <Preview />
              </IconButton>
            </Tooltip>
            <Button
              variant="contained"
              size="small"
              startIcon={<Save />}
              onClick={handleSave}
              disabled={createMutation.isPending || updateMutation.isPending}
              sx={{ ml: 1 }}
            >
              Save
            </Button>
            {onCancel && (
              <IconButton size="small" onClick={onCancel} sx={{ ml: 1 }}>
                <Close />
              </IconButton>
            )}
          </Toolbar>

          {/* Canvas */}
          <Box sx={{ flexGrow: 1, overflow: 'auto', p: 2 }}>
            <Paper sx={{ maxWidth: 850, mx: 'auto', p: 2 }}>
              <Typography variant="h6" gutterBottom>
                {displayName || 'Untitled Report'}
              </Typography>
              {description && (
                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                  {description}
                </Typography>
              )}

              <CanvasDropZone onDrop={() => {}}>
                {sections.length === 0 ? (
                  <Box sx={{ textAlign: 'center', py: 4 }}>
                    <Typography color="text.secondary">
                      Drag sections from the toolbox to build your report
                    </Typography>
                  </Box>
                ) : (
                  sections.map((section) => (
                    <SectionCard
                      key={section.id}
                      section={section}
                      isSelected={section.id === selectedSectionId}
                      onSelect={() => setSelectedSectionId(section.id)}
                      onDelete={() => handleDeleteSection(section.id)}
                      onUpdate={handleUpdateSection}
                    />
                  ))
                )}
              </CanvasDropZone>
            </Paper>
          </Box>
        </Box>

        {/* Right Properties Panel */}
        <Drawer
          variant="permanent"
          anchor="right"
          sx={{
            width: 280,
            flexShrink: 0,
            '& .MuiDrawer-paper': { width: 280, position: 'relative' },
          }}
        >
          <Toolbar variant="dense">
            <Typography variant="subtitle1">Properties</Typography>
          </Toolbar>
          <Divider />
          <PropertiesPanel
            section={selectedSection}
            onUpdate={handleUpdateSection}
            dataBindings={Object.keys(dataBindings)}
          />
        </Drawer>

        {/* Drag Overlay */}
        <DragOverlay>
          {activeDragItem && (
            <Paper sx={{ p: 1, display: 'flex', alignItems: 'center', gap: 1 }}>
              {activeDragItem.icon}
              <Typography variant="body2">{activeDragItem.label}</Typography>
            </Paper>
          )}
        </DragOverlay>

        {/* Snackbar */}
        <Snackbar
          open={snackbar.open}
          autoHideDuration={4000}
          onClose={() => setSnackbar((s) => ({ ...s, open: false }))}
        >
          <Alert severity={snackbar.severity}>{snackbar.message}</Alert>
        </Snackbar>

        {/* Data Binding Dialog */}
        <Dialog open={dataBindingDialogOpen} onClose={() => setDataBindingDialogOpen(false)} maxWidth="md" fullWidth>
          <DialogTitle>Data Bindings</DialogTitle>
          <DialogContent>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
              Configure data sources from your Cube.dev semantic layer.
            </Typography>
            {Object.entries(dataBindings).map(([name, binding]) => (
              <Card key={name} sx={{ mb: 2 }}>
                <CardContent>
                  <Typography variant="subtitle2">{name}</Typography>
                  <Typography variant="caption" color="text.secondary">
                    Cube: {binding.cube} | Measures: {binding.measures.join(', ')}
                  </Typography>
                </CardContent>
              </Card>
            ))}
            <Button startIcon={<Add />} onClick={() => {
              const name = `binding_${Object.keys(dataBindings).length + 1}`;
              setDataBindings((prev) => ({
                ...prev,
                [name]: { cube: '', measures: [], dimensions: [] },
              }));
            }}>
              Add Data Binding
            </Button>
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setDataBindingDialogOpen(false)}>Close</Button>
          </DialogActions>
        </Dialog>

        {/* Parameter Dialog */}
        <Dialog open={parameterDialogOpen} onClose={() => setParameterDialogOpen(false)} maxWidth="sm" fullWidth>
          <DialogTitle>Report Parameters</DialogTitle>
          <DialogContent>
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
              Define parameters that users can set when running this report.
            </Typography>
            {parameters.map((param, idx) => (
              <Card key={idx} sx={{ mb: 2 }}>
                <CardContent>
                  <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                    <Typography variant="subtitle2">{param.label}</Typography>
                    <Chip label={param.type} size="small" />
                  </Box>
                  <Typography variant="caption" color="text.secondary">
                    Name: {param.name} {param.required && '(Required)'}
                  </Typography>
                </CardContent>
              </Card>
            ))}
            <Button startIcon={<Add />} onClick={() => {
              setParameters((prev) => [
                ...prev,
                { name: `param_${prev.length + 1}`, type: 'string', label: 'New Parameter' },
              ]);
            }}>
              Add Parameter
            </Button>
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setParameterDialogOpen(false)}>Close</Button>
          </DialogActions>
        </Dialog>
      </Box>
    </DndContext>
  );
};

export default ReportDesigner;

/**
 * UisceRuleBuilder - Main canvas for no-code rule creation
 * Business owners see logic and impact, never code.
 * 
 * Features:
 * - Metadata-driven field dropdowns
 * - Compound AND/OR condition logic
 * - Impact simulation against historical data
 * - CUE code generation (hidden from user)
 */
import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  TextField,
  Button,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Divider,
  Alert,
  Chip,
  CircularProgress,
} from '@mui/material';
import {
  PlayArrow as SimulateIcon,
  Publish as PublishIcon,
  Code as CodeIcon,
  Visibility as PreviewIcon,
} from '@mui/icons-material';
import ConditionGroup, { ConditionGroupType } from './ConditionGroup';
import ImpactReport, { ImpactReportData } from './ImpactReport';
import { FieldDefinition } from './ConditionRow';

export interface UIRule {
  name: string;
  description: string;
  conditionGroups: ConditionGroupType[];
  logic: 'AND' | 'OR';
  action: 'REJECT' | 'FLAG_FOR_REVIEW' | 'APPROVE' | 'LOG';
  severity: 'error' | 'warning' | 'info';
}

interface UisceRuleBuilderProps {
  tenantId: string;
  datasourceId: string;
  targetEntity?: string;
  onPublish?: (rule: UIRule, cueCode: string) => void;
}

const ACTION_OPTIONS = [
  { value: 'REJECT', label: 'Reject Transaction', color: 'error' },
  { value: 'FLAG_FOR_REVIEW', label: 'Flag for Review', color: 'warning' },
  { value: 'APPROVE', label: 'Auto-Approve', color: 'success' },
  { value: 'LOG', label: 'Log Only', color: 'info' },
];

export const UisceRuleBuilder: React.FC<UisceRuleBuilderProps> = ({
  tenantId,
  datasourceId,
  targetEntity,
  onPublish,
}) => {
  // Field definitions from metadata
  const [fields, setFields] = useState<FieldDefinition[]>([]);
  const [loadingFields, setLoadingFields] = useState(false);

  // Rule state
  const [rule, setRule] = useState<UIRule>({
    name: '',
    description: '',
    conditionGroups: [{
      id: `group-${Date.now()}`,
      logic: 'AND',
      conditions: [],
    }],
    logic: 'AND',
    action: 'REJECT',
    severity: 'error',
  });

  // Simulation state
  const [simulating, setSimulating] = useState(false);
  const [impactReport, setImpactReport] = useState<ImpactReportData | null>(null);
  const [simulationError, setSimulationError] = useState<string | null>(null);

  // Publishing state
  const [publishing, setPublishing] = useState(false);
  const [generatedCue, setGeneratedCue] = useState<string | null>(null);
  const [showCuePreview, setShowCuePreview] = useState(false);

  // Load field definitions from metadata
  useEffect(() => {
    const loadFields = async () => {
      setLoadingFields(true);
      try {
        // Try to load from business object or semantic terms
        const response = await fetch(
          `/api/business-objects/${targetEntity}/fields?tenant_id=${tenantId}&datasource_id=${datasourceId}`
        );

        if (response.ok) {
          const data = await response.json();
          const mappedFields: FieldDefinition[] = (data.fields || []).map((f: any) => ({
            name: f.name || f.key || f.field_name,
            type: mapFieldType(f.type || f.field_type),
            label: f.label || f.display_name || f.name,
            options: f.options || f.enum_values,
          }));
          setFields(mappedFields);
        } else {
          // Fallback to default fields for demo
          setFields(getDefaultFields());
        }
      } catch (error) {
        console.error('Failed to load field definitions:', error);
        setFields(getDefaultFields());
      } finally {
        setLoadingFields(false);
      }
    };

    if (tenantId && datasourceId) {
      loadFields();
    } else {
      setFields(getDefaultFields());
    }
  }, [tenantId, datasourceId, targetEntity]);

  const mapFieldType = (type: string): FieldDefinition['type'] => {
    const typeMap: Record<string, FieldDefinition['type']> = {
      'number': 'number',
      'integer': 'number',
      'decimal': 'number',
      'float': 'number',
      'string': 'string',
      'text': 'string',
      'boolean': 'boolean',
      'bool': 'boolean',
      'date': 'date',
      'datetime': 'date',
      'enum': 'enum',
      'select': 'enum',
    };
    return typeMap[type?.toLowerCase()] || 'string';
  };

  const getDefaultFields = (): FieldDefinition[] => [
    { name: 'amount', type: 'number', label: 'Transaction Amount' },
    { name: 'currency', type: 'enum', label: 'Currency', options: ['USD', 'EUR', 'GBP', 'JPY'] },
    { name: 'counterparty_rating', type: 'enum', label: 'Counterparty Rating', options: ['AAA', 'AA', 'A', 'BBB', 'BB', 'B', 'CCC'] },
    { name: 'trade_type', type: 'enum', label: 'Trade Type', options: ['BUY', 'SELL', 'TRANSFER'] },
    { name: 'trade_date', type: 'date', label: 'Trade Date' },
    { name: 'is_internal', type: 'boolean', label: 'Internal Trade' },
    { name: 'client_name', type: 'string', label: 'Client Name' },
  ];

  const handleGroupChange = (index: number, group: ConditionGroupType) => {
    const newGroups = [...rule.conditionGroups];
    newGroups[index] = group;
    setRule({ ...rule, conditionGroups: newGroups });
  };

  const handleSimulate = useCallback(async () => {
    setSimulating(true);
    setSimulationError(null);
    setImpactReport(null);

    try {
      const payload = {
        rule: {
          name: rule.name,
          description: rule.description,
          conditions: rule.conditionGroups.flatMap(g => g.conditions),
          logic: rule.logic,
          action: rule.action,
        },
        time_range: '24h',
      };

      const response = await fetch(
        `/api/rules/simulate?tenant_id=${tenantId}&datasource_id=${datasourceId}`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        }
      );

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || 'Simulation failed');
      }

      const result = await response.json();
      setImpactReport(result);
    } catch (error) {
      const err = error instanceof Error ? error.message : 'Unknown error';
      setSimulationError(err);
    } finally {
      setSimulating(false);
    }
  }, [rule, tenantId, datasourceId]);

  const handleGenerateCue = useCallback(async () => {
    try {
      const payload = {
        name: rule.name,
        description: rule.description,
        conditions: rule.conditionGroups.flatMap(g => g.conditions),
        logic: rule.logic,
        action: rule.action,
      };

      const response = await fetch(
        `/api/rules/generate-cue?tenant_id=${tenantId}&datasource_id=${datasourceId}`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        }
      );

      if (response.ok) {
        const data = await response.json();
        setGeneratedCue(data.cue_code);
        setShowCuePreview(true);
      }
    } catch (error) {
      console.error('CUE generation failed:', error);
    }
  }, [rule, tenantId, datasourceId]);

  const handlePublish = useCallback(async () => {
    if (!rule.name.trim()) {
      alert('Please enter a rule name');
      return;
    }

    if (rule.conditionGroups.every(g => g.conditions.length === 0)) {
      alert('Please add at least one condition');
      return;
    }

    setPublishing(true);
    try {
      // First generate CUE
      await handleGenerateCue();

      // Then call publish
      if (onPublish && generatedCue) {
        onPublish(rule, generatedCue);
      }
    } finally {
      setPublishing(false);
    }
  }, [rule, generatedCue, handleGenerateCue, onPublish]);

  const hasConditions = rule.conditionGroups.some(g => g.conditions.length > 0);

  return (
    <Box sx={{ maxWidth: 900, mx: 'auto' }}>
      <Card elevation={2}>
        <CardContent>
          {/* Header */}
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 3 }}>
            <Box>
              <Typography variant="h5" fontWeight="bold">
                Uisce Compliance Builder
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Build validation rules visually • See impact before you publish
              </Typography>
            </Box>
            <Chip 
              label={targetEntity || 'All Entities'} 
              color="primary" 
              variant="outlined" 
            />
          </Box>

          <Divider sx={{ mb: 3 }} />

          {/* Rule Info */}
          <Box sx={{ display: 'flex', gap: 2, mb: 3 }}>
            <TextField
              label="Rule Name"
              value={rule.name}
              onChange={(e) => setRule({ ...rule, name: e.target.value })}
              fullWidth
              placeholder="e.g., High Value Trade Check"
            />
            <FormControl sx={{ minWidth: 180 }}>
              <InputLabel>Action</InputLabel>
              <Select
                value={rule.action}
                label="Action"
                onChange={(e) => setRule({ ...rule, action: e.target.value as UIRule['action'] })}
              >
                {ACTION_OPTIONS.map((opt) => (
                  <MenuItem key={opt.value} value={opt.value}>
                    <Chip size="small" label={opt.label} color={opt.color as any} />
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Box>

          <TextField
            label="Description"
            value={rule.description}
            onChange={(e) => setRule({ ...rule, description: e.target.value })}
            fullWidth
            multiline
            rows={2}
            placeholder="Describe what this rule validates and why..."
            sx={{ mb: 3 }}
          />

          <Divider sx={{ mb: 3 }} />

          {/* Conditions */}
          <Typography variant="subtitle1" fontWeight="bold" gutterBottom>
            Conditions
          </Typography>

          {loadingFields ? (
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, py: 4, justifyContent: 'center' }}>
              <CircularProgress size={24} />
              <Typography>Loading field definitions...</Typography>
            </Box>
          ) : (
            <Box sx={{ mb: 3 }}>
              {rule.conditionGroups.map((group, index) => (
                <ConditionGroup
                  key={group.id}
                  group={group}
                  fields={fields}
                  onChange={(g) => handleGroupChange(index, g)}
                />
              ))}
            </Box>
          )}

          <Divider sx={{ mb: 3 }} />

          {/* Actions */}
          <Box sx={{ display: 'flex', gap: 2, justifyContent: 'flex-end' }}>
            <Button
              variant="outlined"
              startIcon={<CodeIcon />}
              onClick={handleGenerateCue}
              disabled={!hasConditions}
            >
              Preview CUE
            </Button>
            <Button
              variant="contained"
              color="secondary"
              startIcon={simulating ? <CircularProgress size={20} color="inherit" /> : <SimulateIcon />}
              onClick={handleSimulate}
              disabled={!hasConditions || simulating}
            >
              {simulating ? 'Simulating...' : 'Run Simulation'}
            </Button>
            <Button
              variant="contained"
              color="primary"
              startIcon={publishing ? <CircularProgress size={20} color="inherit" /> : <PublishIcon />}
              onClick={handlePublish}
              disabled={!hasConditions || publishing || !rule.name.trim()}
            >
              {publishing ? 'Publishing...' : 'Publish Rule'}
            </Button>
          </Box>
        </CardContent>
      </Card>

      {/* Impact Report */}
      {(impactReport || simulationError || simulating) && (
        <Box sx={{ mt: 3 }}>
          <ImpactReport
            data={impactReport}
            loading={simulating}
            error={simulationError}
          />
        </Box>
      )}

      {/* CUE Preview Dialog */}
      {showCuePreview && generatedCue && (
        <Card variant="outlined" sx={{ mt: 3 }}>
          <CardContent>
            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
              <Typography variant="subtitle1" fontWeight="bold">
                Generated CUE Code (Internal)
              </Typography>
              <Button size="small" onClick={() => setShowCuePreview(false)}>
                Close
              </Button>
            </Box>
            <Alert severity="info" sx={{ mb: 2 }}>
              This is the validation code generated from your visual rule. Most users never need to see this.
            </Alert>
            <Box
              component="pre"
              sx={{
                p: 2,
                bgcolor: 'grey.900',
                color: 'grey.100',
                borderRadius: 1,
                overflow: 'auto',
                fontSize: '0.85rem',
                fontFamily: 'monospace',
              }}
            >
              {generatedCue}
            </Box>
          </CardContent>
        </Card>
      )}
    </Box>
  );
};

export default UisceRuleBuilder;

import React, { useState } from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  FormControl,
  Grid,
  InputLabel,
  MenuItem,
  Select,
  TextField,
  Typography,
  IconButton,
  Chip,
  Stack,
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import DeleteIcon from '@mui/icons-material/Delete';

interface Condition {
  field: string;
  operator: string;
  value: string;
}

const OPERATORS = [
  { value: 'equals', label: 'Equals' },
  { value: 'not_equals', label: 'Not Equals' },
  { value: 'greater_than', label: 'Greater Than' },
  { value: 'less_than', label: 'Less Than' },
  { value: 'greater_equal', label: 'Greater or Equal' },
  { value: 'less_equal', label: 'Less or Equal' },
  { value: 'contains', label: 'Contains' },
  { value: 'starts_with', label: 'Starts With' },
  { value: 'ends_with', label: 'Ends With' },
  { value: 'in', label: 'In List' },
  { value: 'is_empty', label: 'Is Empty' },
  { value: 'is_not_empty', label: 'Is Not Empty' },
  { value: 'between', label: 'Between' },
];

const SAMPLE_FIELDS = [
  'age', 'email', 'status', 'salary', 'first_name', 'last_name', 'hire_date', 'is_active'
];

interface ConditionBuilderProps {
  value: string;
  onChange: (json: string) => void;
  availableFields?: Array<{ id: string; label: string; type: string }>;
}

const ConditionBuilder: React.FC<ConditionBuilderProps> = ({ value, onChange, availableFields = [] }) => {
  const [conditions, setConditions] = useState<Condition[]>(() => {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  });

  const updateAndSync = (newConditions: Condition[]) => {
    setConditions(newConditions);
    onChange(JSON.stringify(newConditions));
  };

  const addCondition = () => {
    updateAndSync([
      ...conditions,
      { field: '', operator: 'equals', value: '' }
    ]);
  };

  const updateCondition = (idx: number, field: keyof Condition, newValue: string) => {
    const updated = [...conditions];
    updated[idx] = { ...updated[idx], [field]: newValue };
    updateAndSync(updated);
  };

  const removeCondition = (idx: number) => {
    updateAndSync(conditions.filter((_, i) => i !== idx));
  };

  return (
    <Card sx={{ boxShadow: 2 }}>
      <CardContent>
        <Stack spacing={3}>
          {/* Header */}
          <Box>
            <Typography variant="h6" sx={{ fontWeight: 600, mb: 1 }}>
              Build Conditions
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Define one or more conditions to validate your data
            </Typography>
          </Box>

          {/* Available Fields Quick Access */}
          {conditions.length === 0 && availableFields.length > 0 && (
            <Box>
              <Typography variant="subtitle2" sx={{ mb: 1, fontWeight: 600 }}>
                Available Fields
              </Typography>
              <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                {availableFields.slice(0, 10).map((field) => (
                  <Chip
                    key={field.id}
                    label={field.label}
                    variant="outlined"
                    onClick={() => {
                      updateAndSync([
                        ...conditions,
                        { field: field.label, operator: 'equals', value: '' }
                      ]);
                    }}
                    clickable
                  />
                ))}
              </Box>
            </Box>
          )}

          {/* Conditions List */}
          {conditions.length > 0 && (
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
              <Typography variant="subtitle2" sx={{ fontWeight: 600 }}>
                Conditions ({conditions.length})
              </Typography>
              {conditions.map((cond, idx) => (
                <Box
                  key={idx}
                  sx={{
                    p: 2,
                    border: '1px solid #e0e0e0',
                    borderRadius: 1,
                    backgroundColor: '#fafafa',
                  }}
                >
                  <Grid container spacing={1.5} alignItems="flex-start">
                    <Grid item xs={12} sm={4}>
                      <TextField
                        fullWidth
                        size="small"
                        label="Field"
                        value={cond.field}
                        onChange={(e) => updateCondition(idx, 'field', e.target.value)}
                        placeholder="e.g., age, email"
                        variant="outlined"
                      />
                    </Grid>
                    <Grid item xs={12} sm={3}>
                      <FormControl fullWidth size="small">
                        <InputLabel>Operator</InputLabel>
                        <Select
                          value={cond.operator}
                          label="Operator"
                          onChange={(e) => updateCondition(idx, 'operator', e.target.value)}
                        >
                          {OPERATORS.map((op) => (
                            <MenuItem key={op.value} value={op.value}>
                              {op.label}
                            </MenuItem>
                          ))}
                        </Select>
                      </FormControl>
                    </Grid>
                    <Grid item xs={12} sm={4}>
                      <TextField
                        fullWidth
                        size="small"
                        label="Value"
                        value={cond.value}
                        onChange={(e) => updateCondition(idx, 'value', e.target.value)}
                        placeholder="e.g., 25, active"
                        variant="outlined"
                      />
                    </Grid>
                    <Grid item xs={12} sm={1} sx={{ display: 'flex', justifyContent: 'flex-end' }}>
                      <IconButton
                        size="small"
                        color="error"
                        onClick={() => removeCondition(idx)}
                        sx={{ mt: 0.5 }}
                      >
                        <DeleteIcon fontSize="small" />
                      </IconButton>
                    </Grid>
                  </Grid>
                </Box>
              ))}
            </Box>
          )}

          {/* Add Condition Button */}
          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={addCondition}
            sx={{ alignSelf: 'flex-start' }}
          >
            Add Condition
          </Button>

          {/* JSON Preview */}
          {conditions.length > 0 && (
            <Box>
              <Typography variant="subtitle2" sx={{ mb: 1, fontWeight: 600 }}>
                JSON Preview
              </Typography>
              <Box
                sx={{
                  p: 1.5,
                  backgroundColor: '#f5f5f5',
                  border: '1px solid #e0e0e0',
                  borderRadius: 1,
                  fontFamily: 'monospace',
                  fontSize: '0.85rem',
                  overflow: 'auto',
                  maxHeight: '200px',
                }}
              >
                <pre style={{ margin: 0 }}>
                  {JSON.stringify(conditions, null, 2)}
                </pre>
              </Box>
            </Box>
          )}
        </Stack>
      </CardContent>
    </Card>
  );
};

export default ConditionBuilder;

import React, { useState, useEffect } from 'react';
import {
  Box,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Autocomplete,
  TextField,
  CircularProgress,
  Typography,
  Chip,
} from '@mui/material';

interface BusinessObject {
  id: string;
  name: string;
  displayName?: string;
}

interface BusinessObjectInstance {
  id: string;
  coreFieldValues: Record<string, any>;
  customFieldValues: Record<string, any>;
}

interface InstanceSelectorProps {
  tenantId: string;
  datasourceId: string;
  onInstanceSelect: (instanceId: string, instance: BusinessObjectInstance | null) => void;
  selectedInstanceId?: string;
}

export const InstanceSelector: React.FC<InstanceSelectorProps> = ({
  tenantId,
  datasourceId,
  onInstanceSelect,
  selectedInstanceId,
}) => {
  const [businessObjects, setBusinessObjects] = useState<BusinessObject[]>([]);
  const [selectedBO, setSelectedBO] = useState<string>('');
  const [instances, setInstances] = useState<BusinessObjectInstance[]>([]);
  const [selectedInstance, setSelectedInstance] = useState<BusinessObjectInstance | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadingInstances, setLoadingInstances] = useState(false);

  // Load business objects on mount
  useEffect(() => {
    const loadBusinessObjects = async () => {
      setLoading(true);
      try {
        const response = await fetch(
          `/api/business-objects?tenant_id=${tenantId}&datasource_id=${datasourceId}`
        );
        if (response.ok) {
          const data = await response.json();
          setBusinessObjects(data);
        }
      } catch (error) {
        console.error('Failed to load business objects:', error);
      } finally {
        setLoading(false);
      }
    };

    if (tenantId && datasourceId) {
      loadBusinessObjects();
    }
  }, [tenantId, datasourceId]);

  // Load instances when BO is selected
  useEffect(() => {
    const loadInstances = async () => {
      if (!selectedBO) {
        setInstances([]);
        return;
      }

      setLoadingInstances(true);
      try {
        const response = await fetch(
          `/api/business-objects/${selectedBO}/instances?tenant_id=${tenantId}&datasource_id=${datasourceId}&limit=100`
        );
        if (response.ok) {
          const data = await response.json();
          setInstances(data.instances || []);
        }
      } catch (error) {
        console.error('Failed to load instances:', error);
      } finally {
        setLoadingInstances(false);
      }
    };

    loadInstances();
  }, [selectedBO, tenantId, datasourceId]);

  const handleBOChange = (event: any) => {
    setSelectedBO(event.target.value);
    setSelectedInstance(null);
    onInstanceSelect('', null);
  };

  const handleInstanceChange = (_event: any, value: BusinessObjectInstance | null) => {
    setSelectedInstance(value);
    onInstanceSelect(value?.id || '', value);
  };

  const getInstanceLabel = (instance: BusinessObjectInstance) => {
    // Try to find identifying fields
    const core = instance.coreFieldValues || {};
    const custom = instance.customFieldValues || {};

    const name = core.name || custom.name || core.displayName || custom.displayName;
    const id = core.id || custom.id || instance.id.substring(0, 8);

    return name ? `${name} (${id})` : `Instance ${id}`;
  };

  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
      <FormControl fullWidth size="small">
        <InputLabel id="business-object-select-label">Business Object Type</InputLabel>
        <Select
          labelId="business-object-select-label"
          value={selectedBO}
          onChange={handleBOChange}
          label="Business Object Type"
          disabled={loading}
          sx={{ 
            '& .MuiSelect-select': {
              padding: '10px 14px',
            }
          }}
        >
          {loading && (
            <MenuItem value="">
              <CircularProgress size={20} sx={{ mr: 1 }} />
              Loading...
            </MenuItem>
          )}
          {businessObjects.map((bo) => (
            <MenuItem key={bo.id} value={bo.id}>
              {bo.displayName || bo.name}
            </MenuItem>
          ))}
        </Select>
      </FormControl>

      {selectedBO && (
        <Autocomplete
          size="small"
          options={instances}
          value={selectedInstance}
          onChange={handleInstanceChange}
          getOptionLabel={getInstanceLabel}
          loading={loadingInstances}
          renderInput={(params) => (
            <TextField
              {...params}
              label="Select Instance"
              placeholder="Search for an instance..."
              size="small"
              InputProps={{
                ...params.InputProps,
                endAdornment: (
                  <>
                    {loadingInstances && <CircularProgress size={20} />}
                    {params.InputProps.endAdornment}
                  </>
                ),
              }}
            />
          )}
          renderOption={(props, option) => (
            <li {...props}>
              <Box sx={{ display: 'flex', flexDirection: 'column', width: '100%' }}>
                <Typography variant="body2">{getInstanceLabel(option)}</Typography>
                <Typography variant="caption" color="text.secondary">
                  ID: {option.id.substring(0, 13)}...
                </Typography>
              </Box>
            </li>
          )}
        />
      )}

      {selectedInstance && (
        <Box sx={{ mt: 1 }}>
          <Typography variant="caption" color="text.secondary" gutterBottom>
            Instance Preview:
          </Typography>
          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mt: 0.5 }}>
            {Object.entries({ ...selectedInstance.coreFieldValues, ...selectedInstance.customFieldValues })
              .slice(0, 5)
              .map(([key, value]) => (
                <Chip
                  key={key}
                  label={`${key}: ${String(value).substring(0, 20)}`}
                  size="small"
                  variant="outlined"
                />
              ))}
          </Box>
        </Box>
      )}
    </Box>
  );
};

