// Types
interface WorkflowInstance {
  id: string;
  workflowId: string;
  runId: string;
  processType: string;
  status: 'running' | 'completed' | 'failed' | 'pending' | 'cancelled';
  startTime: string;
  endTime?: string;
  currentStep?: string;
  progress: number;
  assignees: string[];
  metadata: Record<string, any>;
}

interface StepExecution {
  stepId: string;
  stepType: string;
  stepName: string;
  status: 'completed' | 'running' | 'pending' | 'failed';
  startTime?: string;
  endTime?: string;
  assignee?: string;
  action?: string;
  llmInvoked: boolean;
  routing?: {
    type: string;
    resolvedTo: string[];
  };
}

// Status chip colors
const statusColors: Record<string, 'success' | 'error' | 'warning' | 'info' | 'default'> = {
  completed: 'success',
  running: 'info',
  pending: 'warning',
  failed: 'error',
  cancelled: 'default',
};

// Status icons
const StatusIcon: React.FC<{ status: string }> = ({ status }) => {
  switch (status) {
    case 'completed':
      return <CheckCircleIcon sx={{ color: '#10b981' }} />;
    case 'running':
      return <PlayArrowIcon sx={{ color: '#3b82f6' }} />;
    case 'pending':
      return <HourglassEmptyIcon sx={{ color: '#f59e0b' }} />;
    case 'failed':
      return <ErrorIcon sx={{ color: '#ef4444' }} />;
    default:
      return <PauseIcon sx={{ color: '#6b7280' }} />;
  }
};

