                  <TableCell>
                    {instance.assignees.length > 0 ? (
                      instance.assignees.map((a, i) => (
                        <Chip key={i} label={a} size="small" sx={{ mr: 0.5 }} />
                      ))
                    ) : (
                      <Typography variant="caption" color="text.secondary">-</Typography>
                    )}
