                {instances.map((inst) => {
                  const sla = getSLAStatus(inst.slaDeadline);
                  return (
                    <TableRow key={inst.id} hover>
                      <TableCell>
                        <Stack>
                          <Typography variant="subtitle2">{inst.workflowId}</Typography>
