                  </Stack>
                </TableCell>
                <TableCell>
                  <Typography variant="caption">{formatTime(decision.timestamp)}</Typography>
                </TableCell>
                <TableCell>
                  <Chip label={`${decision.executionTimeMs}ms`} size="small" variant="outlined" />
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
    </Box>
  );
};

