          <Grid item xs={12} md={6}>
            <Paper sx={{ p: 3 }}>
              <Typography variant="h6" gutterBottom>
                Worker Utilization
              </Typography>
              <Box sx={{ height: 300 }}>
                <Typography color="text.secondary" sx={{ textAlign: 'center', pt: 10 }}>
