} from '@mui/material';
import {
  PlayArrow as RunIcon,
  Save as SaveIcon,
  Code as CodeIcon,
  BugReport as TestIcon,
} from '@mui/icons-material';
import Editor from '@monaco-editor/react';

// ============================================================================
// EXPRESSION EDITOR
// Starlark expression editor with syntax highlighting and testing
// ============================================================================

interface ExpressionEditorProps {
  initialExpression?: {
    id?: string;
    name: string;
    rule_type: 'validation' | 'calculation' | 'condition';
    script: string;
    description?: string;
  };
  onSave?: (expression: any) => void;
}

export const ExpressionEditor: React.FC<ExpressionEditorProps> = ({
  initialExpression,
  onSave,
}) => {
  const [name, setName] = useState(initialExpression?.name || '');
  const [ruleType, setRuleType] = useState<'validation' | 'calculation' | 'condition'>(
    initialExpression?.rule_type || 'calculation'
  );
  const [script, setScript] = useState(initialExpression?.script || '');
  const [description, setDescription] = useState(initialExpression?.description || '');
  const [testData, setTestData] = useState('{\n  "amount": 1000,\n  "limit": 5000\n}');
  const [testResult, setTestResult] = useState<any>(null);
  const [activeTab, setActiveTab] = useState(0);

  const handleTest = async () => {
    try {
      const data = JSON.parse(testData);
      // TODO: Call API to test expression
      // const response = await fetch('/api/expressions/test', {
      //   method: 'POST',
      //   body: JSON.stringify({ script, data, rule_type: ruleType }),
      // });
      // setTestResult(await response.json());

      // Mock result
      setTestResult({
        success: true,
        result: ruleType === 'validation' 
          ? { is_valid: true, message: 'Validation passed' }
          : ruleType === 'calculation'
          ? 42.5
          : 'auto_approve',
      });
    } catch (error) {
      setTestResult({ success: false, error: String(error) });
    }
  };

  const handleSave = () => {
    if (onSave) {
      onSave({
        id: initialExpression?.id,
        name,
        rule_type: ruleType,
        script,
        description,
      });
    }
  };

  const getExampleScript = () => {
    switch (ruleType) {
      case 'validation':
        return `# Validation Rule
# Returns (is_valid, message) tuple

if amount > limit:
    result = (False, "Amount exceeds limit of $" + str(limit))
else:
    result = (True, None)`;

      case 'calculation':
        return `# Calculation
# Returns computed value

result = (amount - cost_basis) / cost_basis * 100`;

      case 'condition':
        return `# Condition Rule
# Returns action string

if amount > 1000000:
    result = "committee_review"
elif amount > 100000:
    result = "manager_approval"
else:
    result = "auto_approve"`;

      default:
        return '';
    }
  };

  return (
    <Box>
      <Card>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            Expression Editor
          </Typography>

          <Grid container spacing={2} sx={{ mb: 2 }}>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Expression Name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="e.g., Transaction Amount Limit"
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <FormControl fullWidth>
                <InputLabel>Expression Type</InputLabel>
                <Select
                  value={ruleType}
                  onChange={(e) => setRuleType(e.target.value as any)}
                  label="Expression Type"
                >
                  <MenuItem value="validation">Validation</MenuItem>
                  <MenuItem value="calculation">Calculation</MenuItem>
                  <MenuItem value="condition">Condition</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Description"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                multiline
                rows={2}
              />
            </Grid>
          </Grid>

          <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 2 }}>
            <Tabs value={activeTab} onChange={(_, v) => setActiveTab(v)}>
              <Tab label="Script" icon={<CodeIcon />} iconPosition="start" />
              <Tab label="Test" icon={<TestIcon />} iconPosition="start" />
            </Tabs>
          </Box>

          {activeTab === 0 && (
            <Box>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                <Typography variant="subtitle2">Starlark Script</Typography>
                <Button
                  size="small"
                  onClick={() => setScript(getExampleScript())}
                >
                  Load Example
                </Button>
              </Box>
              <Paper variant="outlined" sx={{ mb: 2 }}>
                <Editor
                  height="300px"
                  defaultLanguage="python"
                  value={script}
                  onChange={(value) => setScript(value || '')}
                  theme="vs-dark"
                  options={{
                    minimap: { enabled: false },
                    fontSize: 13,
                    lineNumbers: 'on',
                    scrollBeyondLastLine: false,
                  }}
                />
              </Paper>

              <Alert severity="info" sx={{ mb: 2 }}>
                <Typography variant="subtitle2" gutterBottom>
                  Available Context Variables:
                </Typography>
                <Typography variant="body2" component="div">
                  • Access data via <code>context.field_name</code> or directly as <code>field_name</code>
                  <br />
                  • Built-in functions: <code>abs, min, max, round, len, str, int, float, bool</code>
                  <br />
                  • Set <code>result</code> variable with your return value
                </Typography>
              </Alert>
            </Box>
          )}

          {activeTab === 1 && (
            <Box>
              <Typography variant="subtitle2" gutterBottom>
                Test Data (JSON)
              </Typography>
              <Paper variant="outlined" sx={{ mb: 2 }}>
                <Editor
                  height="200px"
                  defaultLanguage="json"
                  value={testData}
                  onChange={(value) => setTestData(value || '')}
                  theme="vs-dark"
                  options={{
                    minimap: { enabled: false },
                    fontSize: 13,
                    lineNumbers: 'on',
                  }}
                />
              </Paper>

              <Button
                variant="contained"
                startIcon={<RunIcon />}
                onClick={handleTest}
                sx={{ mb: 2 }}
              >
                Run Test
              </Button>

              {testResult && (
                <Alert
                  severity={testResult.success ? 'success' : 'error'}
                  sx={{ mb: 2 }}
                >
                  <Typography variant="subtitle2" gutterBottom>
                    Test Result:
                  </Typography>
                  <Paper
                    variant="outlined"
                    sx={{
                      p: 1,
                      bgcolor: 'background.default',
                      fontFamily: 'monospace',
                      fontSize: '0.875rem',
                    }}
                  >
                    <pre style={{ margin: 0 }}>
                      {JSON.stringify(testResult.result || testResult.error, null, 2)}
                    </pre>
                  </Paper>
                </Alert>
              )}
            </Box>
          )}

          <Box sx={{ display: 'flex', gap: 1, justifyContent: 'flex-end', mt: 2 }}>
            <Button variant="outlined" onClick={() => setActiveTab(1)}>
              Test
            </Button>
            <Button
              variant="contained"
              startIcon={<SaveIcon />}
              onClick={handleSave}
              disabled={!name || !script}
            >
              Save Expression
            </Button>
          </Box>
        </CardContent>
      </Card>

      {/* Expression Examples */}
      <Card sx={{ mt: 2 }}>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            Expression Examples
          </Typography>
          <Grid container spacing={2}>
            <Grid item xs={12} md={4}>
              <Paper variant="outlined" sx={{ p: 2 }}>
                <Chip label="Validation" size="small" color="primary" sx={{ mb: 1 }} />
                <Typography variant="subtitle2" gutterBottom>
                  Amount Limit Check
                </Typography>
                <Typography
                  variant="body2"
                  sx={{ fontFamily: 'monospace', fontSize: '0.75rem', color: 'text.secondary' }}
                >
                  {`if amount > limit:\n  result = (False, "Exceeds")\nelse:\n  result = (True, None)`}
                </Typography>
              </Paper>
            </Grid>
            <Grid item xs={12} md={4}>
              <Paper variant="outlined" sx={{ p: 2 }}>
                <Chip label="Calculation" size="small" color="success" sx={{ mb: 1 }} />
                <Typography variant="subtitle2" gutterBottom>
                  Portfolio Return %
                </Typography>
                <Typography
                  variant="body2"
                  sx={{ fontFamily: 'monospace', fontSize: '0.75rem', color: 'text.secondary' }}
                >
                  {`result = ((current - cost) / cost * 100) if cost > 0 else 0`}
                </Typography>
              </Paper>
            </Grid>
            <Grid item xs={12} md={4}>
              <Paper variant="outlined" sx={{ p: 2 }}>
                <Chip label="Condition" size="small" color="warning" sx={{ mb: 1 }} />
                <Typography variant="subtitle2" gutterBottom>
                  Approval Routing
                </Typography>
                <Typography
                  variant="body2"
                  sx={{ fontFamily: 'monospace', fontSize: '0.75rem', color: 'text.secondary' }}
                >
                  {`if amount > 1000000:\n  result = "committee"\nelse:\n  result = "auto"`}
                </Typography>
              </Paper>
            </Grid>
          </Grid>
        </CardContent>
      </Card>
    </Box>
  );
};

export default ExpressionEditor;

import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Grid,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Chip,
  IconButton,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Tabs,
  Tab,
} from '@mui/material';
import {
  Add as AddIcon,
  Edit as EditIcon,
  PlayArrow as RunIcon,
  History as HistoryIcon,
} from '@mui/icons-material';
import ExpressionEditor from './ExpressionEditor';

// ============================================================================
// EXPRESSION LIBRARY
// Manages all Starlark expressions (validations, calculations, conditions)
// ============================================================================

interface Expression {
  id: string;
  name: string;
  rule_type: 'validation' | 'calculation' | 'condition';
  description?: string;
  script: string;
  is_active: boolean;
  version: number;
  created_at: string;
}

export const ExpressionLibrary: React.FC = () => {
  const [expressions, setExpressions] = useState<Expression[]>([]);
  const [filteredType, setFilteredType] = useState<string>('all');
  const [editorOpen, setEditorOpen] = useState(false);
  const [selectedExpression, setSelectedExpression] = useState<Expression | null>(null);

  useEffect(() => {
    loadExpressions();
  }, []);

  const loadExpressions = async () => {
    // TODO: Call API to get expressions
    // const response = await fetch('/api/expressions');
    // setExpressions(await response.json());

    // Mock data
    setExpressions([
      {
        id: '1',
        name: 'Transaction Amount Limit',
        rule_type: 'validation',
        description: 'Validates transaction amount does not exceed limit',
        script: 'result = (amount <= limit, "Amount exceeds limit") if amount > limit else (True, None)',
        is_active: true,
        version: 1,
        created_at: new Date().toISOString(),
      },
      {
        id: '2',
        name: 'Calculate Net Worth',
        rule_type: 'calculation',
        description: 'Calculates net worth from assets and liabilities',
        script: 'result = context.assets - context.liabilities',
        is_active: true,
        version: 1,
        created_at: new Date().toISOString(),
      },
      {
        id: '3',
        name: 'Approval Routing',
        rule_type: 'condition',
        description: 'Determines approval path based on amount',
        script: 'if amount > 1000000:\n    result = "committee_review"\nelif amount > 100000:\n    result = "manager_approval"\nelse:\n    result = "auto_approve"',
        is_active: true,
        version: 1,
        created_at: new Date().toISOString(),
      },
    ]);
  };

  const handleSaveExpression = async (expression: any) => {
    // TODO: Call API to save expression
    // const response = await fetch('/api/expressions', {
    //   method: 'POST',
    //   body: JSON.stringify(expression),
    // });

    setEditorOpen(false);
    loadExpressions();
  };

  const handleEditExpression = (expression: Expression) => {
    setSelectedExpression(expression);
    setEditorOpen(true);
  };

  const filteredExpressions = filteredType === 'all'
    ? expressions
    : expressions.filter((e) => e.rule_type === filteredType);

  const getTypeColor = (type: string) => {
    switch (type) {
      case 'validation':
        return 'error';
      case 'calculation':
        return 'success';
      case 'condition':
        return 'warning';
      default:
        return 'default';
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 3 }}>
        <Typography variant="h4">Expression Library</Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => {
            setSelectedExpression(null);
            setEditorOpen(true);
          }}
        >
          New Expression
        </Button>
      </Box>

      <Card>
        <CardContent>
          <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 2 }}>
            <Tabs
              value={filteredType}
              onChange={(_, v) => setFilteredType(v)}
            >
              <Tab label="All" value="all" />
              <Tab label="Validations" value="validation" />
              <Tab label="Calculations" value="calculation" />
              <Tab label="Conditions" value="condition" />
            </Tabs>
          </Box>

          <Table>
            <TableHead>
              <TableRow>
                <TableCell>Name</TableCell>
                <TableCell>Type</TableCell>
                <TableCell>Description</TableCell>
                <TableCell>Status</TableCell>
                <TableCell>Version</TableCell>
                <TableCell align="right">Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredExpressions.map((expr) => (
                <TableRow key={expr.id} hover>
                  <TableCell>
                    <Typography variant="body2" fontWeight="medium">
                      {expr.name}
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={expr.rule_type}
                      size="small"
                      color={getTypeColor(expr.rule_type) as any}
                    />
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2" color="text.secondary">
                      {expr.description}
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={expr.is_active ? 'Active' : 'Inactive'}
                      size="small"
                      color={expr.is_active ? 'success' : 'default'}
                    />
                  </TableCell>
                  <TableCell>
                    <Chip label={`v${expr.version}`} size="small" variant="outlined" />
                  </TableCell>
                  <TableCell align="right">
                    <IconButton
                      size="small"
                      onClick={() => handleEditExpression(expr)}
                    >
                      <EditIcon fontSize="small" />
                    </IconButton>
                    <IconButton size="small">
                      <RunIcon fontSize="small" />
                    </IconButton>
                    <IconButton size="small">
                      <HistoryIcon fontSize="small" />
                    </IconButton>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {/* Expression Editor Dialog */}
      <Dialog
        open={editorOpen}
        onClose={() => setEditorOpen(false)}
        maxWidth="lg"
        fullWidth
      >
        <DialogTitle>
          {selectedExpression ? 'Edit Expression' : 'New Expression'}
        </DialogTitle>
        <DialogContent>
          <ExpressionEditor
            initialExpression={selectedExpression || undefined}
            onSave={handleSaveExpression}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setEditorOpen(false)}>Close</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default ExpressionLibrary;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  Box,
  Paper,
  Typography,
  TextField,
  Button,
  IconButton,
  Chip,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Stack,
  Avatar,
  Checkbox,
  CircularProgress,
  useTheme,
  alpha,
} from '@mui/material';
import {
  Add as AddIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  Download as DownloadIcon,
  FilterList as FilterListIcon,
  Search as SearchIcon,
} from '@mui/icons-material';
import { useIPWhitelistAPI, useIPWhitelistTable } from '../hooks/useIPWhitelist';
import { useNotification } from '../../../hooks/useNotification';
import { IPWhitelistEntry } from '../types/ipWhitelist';


const IPManagementView: React.FC = () => {
  const theme = useTheme();
  const notification = useNotification();
  const api = useIPWhitelistAPI();

  const [entries, setEntries] = useState<IPWhitelistEntry[]>([]);
  const [tenants, setTenants] = useState<any[]>([]);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [deleteConfirm, setDeleteConfirm] = useState<IPWhitelistEntry | null>(null);
  const tableRef = useRef<HTMLDivElement>(null);

  const table = useIPWhitelistTable(entries, tenants);

  // Load data on mount
  useEffect(() => {
    const loadData = async () => {
      const [entriesData, tenantsData] = await Promise.all([
        api.fetchAllIPWhitelist(),
        api.fetchTenants(),
      ]);
      setEntries(entriesData);
      setTenants(tenantsData);
    };
    loadData();
  }, []);

  // Infinite scroll handler
  const handleScroll = useCallback(() => {
    if (!tableRef.current) return;
    const element = tableRef.current.querySelector('[role="table"]');
    if (!element) return;

    const { scrollHeight, clientHeight, scrollTop } = element;
    if (scrollHeight - scrollTop <= clientHeight + 100) {
      if (table.hasMore && !table.isLoadingMore) {
        table.loadMore();
      }
    }
  }, [table]);

  useEffect(() => {
    const container = tableRef.current;
    if (!container) return;
    container.addEventListener('scroll', handleScroll);
    return () => container.removeEventListener('scroll', handleScroll);
  }, [handleScroll]);

  // Handle select all
  const handleSelectAll = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (event.target.checked) {
      const allIds = new Set(table.visibleEntries.map(e => e.ipAddress));
      setSelectedIds(allIds);
    } else {
      setSelectedIds(new Set());
    }
  };

  // Handle select row
  const handleSelectRow = (ipAddress: string) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(ipAddress)) {
      newSelected.delete(ipAddress);
    } else {
      newSelected.add(ipAddress);
    }
    setSelectedIds(newSelected);
  };

  // Handle delete
  const handleDelete = async (entry: IPWhitelistEntry) => {
    const success = await api.removeIPWhitelist(entry.tenantIds?.[0] || '', entry.ipAddress);
    if (success) {
      setEntries(prev => prev.filter(e => e.ipAddress !== entry.ipAddress));
      notification.success(`IP ${entry.ipAddress} removed successfully`);
      setDeleteConfirm(null);
    } else {
      notification.error(`Failed to remove IP ${entry.ipAddress}`);
    }
  };

  // Handle export
  const handleExport = () => {
    const csv = [
      ['Status', 'IP Address', 'Tenant', 'Label', 'Date Added'],
      ...table.visibleEntries.map(e => [
        (e as any).allTenants ? 'Global' : 'Active',
        e.ipAddress,
        e.tenantIds?.map(id => tenants.find(t => t.id === id)?.displayName || id).join('; ') || 'None',
        e.label || '',
        e.createdAt || '',
      ])
    ].map(row => row.map(cell => `"${cell}"`).join(',')).join('\n');

    const blob = new Blob([csv], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'ip-whitelist.csv';
    a.click();
    notification.success('IP whitelist exported successfully');
  };

  const getTenantInitials = (tenantId: string): string => {
    const tenant = tenants.find(t => t.id === tenantId);
    if (!tenant) return 'UN';
    const parts = tenant.displayName?.split(' ') || ['U'];
    return (parts[0]?.[0] + (parts[1]?.[0] || '')).toUpperCase();
  };

  const getTenantColor = (index: number): string => {
    const colors = ['#f3f4f6', '#e5e7eb', '#d1d5db', '#9ca3af', '#6b7280'];
    return colors[index % colors.length];
  };

  const allSelected = table.visibleEntries.length > 0 && table.visibleEntries.every(
    e => selectedIds.has(e.ipAddress)
  );

  return (
    <>
      {/* Toolbar */}
      <Stack spacing={3}>
        <Stack
          direction={{ xs: 'column', md: 'row' }}
          spacing={2}
          justifyContent="space-between"
          alignItems={{ xs: 'stretch', md: 'center' }}
          sx={{
            p: 2,
            backgroundColor: alpha(theme.palette.common.white, theme.palette.mode === 'dark' ? 0.05 : 0.5),
            borderRadius: 1.5,
            border: `1px solid ${theme.palette.divider}`,
          }}
        >
          {/* Search */}
          <TextField
            placeholder="Search by IP, CIDR or Label"
            size="small"
            value={table.searchQuery}
            onChange={(e) => table.setSearchQuery(e.target.value)}
            InputProps={{
              startAdornment: <SearchIcon sx={{ mr: 1, color: 'text.secondary', fontSize: 20 }} />,
            }}
            sx={{
              flex: { xs: 1, md: 'none' },
              maxWidth: { md: '320px' },
              '& .MuiOutlinedInput-root': {
                backgroundColor: theme.palette.background.paper,
              }
            }}
          />

          {/* Action Buttons */}
          <Stack direction="row" spacing={1} sx={{ flex: 1, justifyContent: { xs: 'flex-start', md: 'flex-end' } }}>
            <Button
              startIcon={<FilterListIcon />}
              variant="outlined"
              size="small"
              sx={{ textTransform: 'none' }}
            >
              Filter
            </Button>
            <Button
              startIcon={<DownloadIcon />}
              variant="outlined"
              size="small"
              onClick={handleExport}
              sx={{ textTransform: 'none' }}
            >
              Export
            </Button>
            <Button
              startIcon={<AddIcon />}
              variant="contained"
              size="small"
              sx={{ textTransform: 'none' }}
            >
              Add New IP
            </Button>
          </Stack>
        </Stack>

        {/* Table Container */}
        <TableContainer
          ref={tableRef}
          component={Paper}
          sx={{
            maxHeight: '650px',
            overflowY: 'auto',
            backgroundColor: theme.palette.background.paper,
            borderRadius: 1.5,
            border: `1px solid ${theme.palette.divider}`,
            '&::-webkit-scrollbar': {
              height: '6px',
              width: '6px',
            },
            '&::-webkit-scrollbar-track': {
              background: 'transparent',
            },
            '&::-webkit-scrollbar-thumb': {
              backgroundColor: theme.palette.action.disabled,
              borderRadius: '20px',
            },
          }}
        >
          <Table stickyHeader size="small">
            <TableHead>
              <TableRow 
                sx={{ 
                  backgroundColor: theme.palette.mode === 'dark' 
                    ? alpha(theme.palette.common.white, 0.05) 
                    : alpha(theme.palette.common.black, 0.02)
                }}
              >
                <TableCell padding="checkbox">
                  <Checkbox
                    indeterminate={selectedIds.size > 0 && selectedIds.size < table.visibleEntries.length}
                    checked={allSelected}
                    onChange={handleSelectAll}
                  />
                </TableCell>
                <TableCell
                  sx={{ 
                    fontSize: '0.75rem', 
                    fontWeight: 700, 
                    textTransform: 'uppercase', 
                    color: 'text.secondary',
                    letterSpacing: '0.5px'
                  }}
                >
                  Status
                </TableCell>
                <TableCell
                  sx={{ 
                    fontSize: '0.75rem', 
                    fontWeight: 700, 
                    textTransform: 'uppercase', 
                    color: 'text.secondary',
                    letterSpacing: '0.5px'
                  }}
                >
                  IP Address / CIDR
                </TableCell>
                <TableCell
                  sx={{ 
                    fontSize: '0.75rem', 
                    fontWeight: 700, 
                    textTransform: 'uppercase', 
                    color: 'text.secondary',
                    letterSpacing: '0.5px'
                  }}
                >
                  Tenant
                </TableCell>
                <TableCell
                  sx={{ 
                    fontSize: '0.75rem', 
                    fontWeight: 700, 
                    textTransform: 'uppercase', 
                    color: 'text.secondary',
                    letterSpacing: '0.5px'
                  }}
                >
                  Label
                </TableCell>
                <TableCell
                  sx={{ 
                    fontSize: '0.75rem', 
                    fontWeight: 700, 
                    textTransform: 'uppercase', 
                    color: 'text.secondary',
