interface CalculationsLibraryPageProps {
  tenantId: string;
  datasourceId: string;
}

interface CalculationOption {
  name: string;
  title: string;
  type: string;
  sql: string;
  description?: string;
  sourceTable?: string;
  sourceColumn?: string;
  format?: string;
  aggregationType?: string;
  defaultValue?: string;
  category?: string;
  subcategory?: string;
  preAggregationTemplate?: any;
  backendEndpoint?: string;
