// Helper to convert ConditionGroup to CUE string
const conditionGroupToCue = (group: ConditionGroup): string => {
  if (!group.conditions || group.conditions.length === 0) return 'true';

  const parts = group.conditions.map((node: any) => {
    if (node.type === 'group') {
      return `(${conditionGroupToCue(node)})`;
    } else {
      // Condition
      const field = node.field;
      const val = isNaN(Number(node.value)) ? `"${node.value}"` : node.value;

      switch (node.operator) {
        case 'equals': return `${field} == ${val}`;
        case 'not_equals': return `${field} != ${val}`;
        case 'greater_than': return `${field} > ${val}`;
        case 'less_than': return `${field} < ${val}`;
        case 'greater_equal': return `${field} >= ${val}`;
        case 'less_equal': return `${field} <= ${val}`;
        case 'contains': return `strings.Contains(${field}, ${val})`;
        case 'starts_with': return `strings.HasPrefix(${field}, ${val})`;
        case 'ends_with': return `strings.HasSuffix(${field}, ${val})`;
        case 'is_empty': return `${field} == "" || ${field} == null`;
        case 'is_not_empty': return `${field} != "" && ${field} != null`;
        case 'is_true': return `${field} == true`;
        case 'is_false': return `${field} == false`;
        // Date operators (simplistic mapping for CUE)
        case 'before': return `${field} < ${val}`;
        case 'after': return `${field} > ${val}`;
        default: return `${field} == ${val}`;
      }
    }
  });

  const joinOp = group.operator === 'AND' ? ' && ' : ' || ';
  return parts.join(joinOp);
};

// Helper to attempt parsing CUE string back to ConditionGroup (Basic implementation)
// Note: This is a heuristic parser and only works for simple expressions generated by the builder.
// Complex CUE manually written will likely fail to parse perfectly and should default to Code mode.
const cueToConditionGroup = (cue: string): ConditionGroup | null => {
  try {
    if (!cue || cue.trim() === '') return null;

    // Very basic check if it looks like a builder expression
    // If it contains advanced CUE syntax not generated by builder, return null
    if (cue.includes('{') || cue.includes('for ') || cue.includes('if ')) return null;

    // This is a placeholder. Implementing a full CUE parser is complex.
    // For now, we only initialize the builder if logic matches a known pattern or is empty.
    // If we can't parse it, we return null, confusing the user less than a wrong tree.
    return null; 
  } catch (e) {
    return null;
  }
};

interface ValidationRule {
  id: string;
  name: string;
  description: string;
  type: 'expression' | 'regex' | 'lookup';
  severity: 'error' | 'warning' | 'info';
  status: 'active' | 'inactive';
  logic?: string;
  appliedFields?: string[];
}

interface SemanticField {
  key: string;
  name: string;
  displayName?: string;
  technicalName?: string;
  type: string;
  semanticTerms?: string[];
  semanticId?: string;
  description?: string;
  group?: string;
}

interface ValidationRulesPageProps {
  businessObjectId?: string;
  businessObjectName?: string;
  selectedNodeType?: 'root' | 'subtype' | 'field' | 'group';
  selectedNodeName?: string;
  fields?: SemanticField[];
  rules?: ValidationRule[];
  onRulesUpdate?: (rules: ValidationRule[]) => void;
  onAddRule?: () => void;
  onEditRule?: (rule: any) => void;
}

const ValidationRulesPage: React.FC<ValidationRulesPageProps> = ({ 
  businessObjectId, 
  businessObjectName,
  selectedNodeType,
  selectedNodeName,
  fields = [],
  rules: externalRules,
  onRulesUpdate,
  onAddRule,
  onEditRule
}) => {
  const theme = useTheme();
  const notification = useNotification();
  const { tenant, datasource } = useTenant();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [rules, setRules] = useState<ValidationRule[]>([]);

  const [searchQuery, setSearchQuery] = useState('');
  const [severityFilter, setSeverityFilter] = useState<string>('');
  const [typeFilter, setTypeFilter] = useState<string>('');
  const [statusFilter, setStatusFilter] = useState<string>('');
  const [visibleCount, setVisibleCount] = useState(20);
  const observerTarget = useRef(null);
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [viewLogicOpen, setViewLogicOpen] = useState(false);
  const [auditLogOpen, setAuditLogOpen] = useState(false);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [selectedRule, setSelectedRule] = useState<ValidationRule | null>(null);
  const [deleteConfirm, setDeleteConfirm] = useState<ValidationRule | null>(null);
  const [formData, setFormData] = useState<Partial<ValidationRule>>({});
  const [selectedRules, setSelectedRules] = useState<Set<string>>(new Set());
  const [bulkActionAnchor, setBulkActionAnchor] = useState<null | HTMLElement>(null);
  const [exportMenuAnchor, setExportMenuAnchor] = useState<null | HTMLElement>(null);
  const [advancedFiltersExpanded, setAdvancedFiltersExpanded] = useState(false);
  const [availableFields, setAvailableFields] = useState<SemanticField[]>([]);
  const [validationSettings, setValidationSettings] = useState<ValidationSettings>({
    stopOnFirstError: true,
    notifyOnFailures: true,
    emailDigest: false,
    cacheResults: true,
    cacheDurationMinutes: 5,
    logAllValidations: true,
    maxRulesPerObject: 100,
    timeoutSeconds: 30,
  });

  // Visual Builder State
  const [isVisualMode, setIsVisualMode] = useState(true);
  const [visualTree, setVisualTree] = useState<ConditionGroup>({
    id: 'root',
    type: 'group',
    operator: 'AND',
    conditions: []
  });

  const tenantId = tenant?.id || '';
  const datasourceId = datasource?.id || datasource?.alpha_datasource_id || '';

  // Sync fields from parent component
  useEffect(() => {
    if (fields && fields.length > 0) {
      setAvailableFields(fields);
      devLog('Available semantic fields:', fields.length);
    }
  }, [fields]);

  // Sync rules from external prop if provided - avoid loop by checking identity
  useEffect(() => {
    if (externalRules && externalRules !== rules) {
      // Normalize external rules to match ValidationRule interface
      const normalized = externalRules.map((rule: any) => ({
        id: rule.id || rule.key || rule.rule_id,
        name: rule.name || rule.rule_name || 'Untitled Rule',
        description: rule.description || '',
        type: (rule.type || rule.rule_type || 'expression').toLowerCase() as 'expression' | 'regex' | 'lookup',
        severity: (rule.severity || 'error').toLowerCase() as 'error' | 'warning' | 'info',
        status: rule.status === 'inactive' || rule.status === false || rule.is_inactive ? 'inactive' : 'active',
        logic: rule.logic || rule.rule_definition || '',
      })) as ValidationRule[];

      setRules(normalized);
      setLoading(false); // Stop loading if rules are provided
    }
  }, [externalRules]);

  // Fetch validation rules from backend
  const fetchRules = async () => {
      if (externalRules) return; // Skip if parent is managing rules
      if (!tenantId || !datasourceId) {
        // No tenant/datasource context - show sample data
        devLog('No tenant/datasource context, using sample data');
        setRules([
          {
            id: '1',
            name: 'check_invoice_total_positive',
            description: 'Ensures total is > 0',
            type: 'expression',
            severity: 'error',
            status: 'active',
            logic: 'total > 0',
          },
          {
            id: '2',
            name: 'validate_vendor_tax_id',
            description: 'Checks format of Tax ID',
            type: 'regex',
            severity: 'warning',
            status: 'active',
            logic: '^[0-9]{9}$',
          },
          {
            id: '3',
            name: 'cross_reference_po',
            description: 'Matches against PO table',
            type: 'lookup',
            severity: 'error',
            status: 'inactive',
            logic: 'SELECT * FROM po_table WHERE po_id = @po_id',
          },
          {
            id: '4',
            name: 'check_due_date_future',
            description: 'Due date must be > today',
            type: 'expression',
            severity: 'warning',
            status: 'active',
            logic: 'due_date > TODAY()',
          },
        ]);
        setLoading(false);
        return;
      }

      setLoading(true);
      setError(null);

      try {
        const params = new URLSearchParams({
          tenant_id: tenantId,
          datasource_id: datasourceId,
          page: '1',
          limit: '100',
        });

        if (businessObjectName) {
          // If a subtype is selected, filter by subtype, otherwise filter by business object
          const targetEntity = selectedNodeType === 'subtype' && selectedNodeName ? selectedNodeName : businessObjectName;
          params.append('target_entity', targetEntity);
        }

        const response = await fetch(`/api/validation-rules?${params.toString()}`, {
          headers: {
            'X-Tenant-ID': tenantId,
            'X-Tenant-Datasource-ID': datasourceId,
          },
        });

        if (!response.ok) {
          throw new Error('Failed to fetch validation rules');
        }

        const data = await response.json();
        const rulesData = Array.isArray(data) ? data : (data.rules || []);

        devLog('[ValidationRulesPage] Raw rulesData from API:', rulesData);

        // Transform backend data to local ValidationRule format
        const transformedRules: ValidationRule[] = rulesData.map((rule: any) => {
          devLog('[ValidationRulesPage] Transforming rule:', rule.rule_name || rule.name);
          devLog('[ValidationRulesPage] - script_content:', rule.script_content);
          devLog('[ValidationRulesPage] - rule_definition:', rule.rule_definition);
          devLog('[ValidationRulesPage] - logic:', rule.logic);

          const transformed = {
            id: rule.id || rule.key,
            name: rule.rule_name || rule.name,
            description: rule.description || '',
            type: (rule.rule_type || 'expression').toLowerCase() as 'expression' | 'regex' | 'lookup',
            severity: (rule.severity || 'error').toLowerCase() as 'error' | 'warning' | 'info',
            status: rule.is_active === false ? 'inactive' : 'active',
            logic: rule.script_content || rule.rule_definition || rule.logic || '',
          };

          devLog('[ValidationRulesPage] - transformed.logic:', transformed.logic);
          return transformed;
        });

        setRules(transformedRules);
        devLog('Loaded validation rules:', transformedRules.length);
      } catch (err) {
        const msg = err instanceof Error ? err.message : 'Failed to load validation rules';
        devError('Error fetching validation rules:', err);
        setError(msg);
        // Fall back to sample data
        setRules([
          {
            id: '1',
            name: 'check_invoice_total_positive',
            description: 'Ensures total is > 0',
            type: 'expression',
            severity: 'error',
            status: 'active',
            logic: 'total > 0',
          },
          {
            id: '2',
            name: 'validate_vendor_tax_id',
            description: 'Checks format of Tax ID',
            type: 'regex',
            severity: 'warning',
            status: 'active',
            logic: '^[0-9]{9}$',
          },
        ]);
      } finally {
        setLoading(false);
      }
    };


  useEffect(() => {
    fetchRules();
  }, [tenantId, datasourceId, businessObjectId, businessObjectName, selectedNodeType, selectedNodeName]);

  // Reset visibleCount when filters change
  useEffect(() => {
    setVisibleCount(20);
  }, [searchQuery, severityFilter, typeFilter, statusFilter]);

  // Lazy loading IntersectionObserver
  useEffect(() => {
    const observer = new IntersectionObserver(
      entries => {
        if (entries[0].isIntersecting) {
          setVisibleCount(prev => prev + 20);
        }
      },
      { threshold: 0.1 }
    );

    if (observerTarget.current) {
      observer.observe(observerTarget.current);
    }

    return () => {
      if (observerTarget.current) {
        observer.unobserve(observerTarget.current);
      }
    };
  }, []);

  // No longer notify parent via useEffect to avoid circular loops

  const filteredRules = rules.filter(rule => {
    const matchesSearch = searchQuery === '' || 
      rule.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      rule.description.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesSeverity = severityFilter === '' || rule.severity === severityFilter;
    const matchesType = typeFilter === '' || rule.type === typeFilter;
    const matchesStatus = statusFilter === '' || rule.status === statusFilter;
    return matchesSearch && matchesSeverity && matchesType && matchesStatus;
  });

  const lazyLoadedRules = filteredRules.slice(0, visibleCount);

  const handleCreateRule = () => {
    if (onAddRule) {
      onAddRule();
      return;
    }
    setFormData({ name: '', description: '', type: 'expression', severity: 'error', status: 'active' });
    setIsVisualMode(true);
    setVisualTree({ id: 'root', type: 'group', operator: 'AND', conditions: [] });
    setCreateDialogOpen(true);
  };

  const handleSaveRule = async () => {
    if (!formData.name?.trim() || (!formData.description?.trim() && !formData.logic?.trim() && !isVisualMode)) {
      notification.error('Please fill in required fields');
      return;
    }

    // Determine payload
    const payload: any = {
      rule_name: formData.name,
      description: formData.description || '',
      rule_type: formData.type || 'business_logic',
      severity: formData.severity || 'error',
      target_entity: selectedNodeType === 'subtype' && selectedNodeName ? selectedNodeName : businessObjectName,
      datasource_id: datasourceId,
      is_active: formData.status !== 'inactive',
      is_core: false // Pending logic for core rules
    };

    // Handle Logic/Condition
    if (isVisualMode && formData.type === 'expression') {
      // Send Visual Tree as condition_json
      payload.condition_json = visualTree;
      // Also generate CUE for script_content as fallback/backend usage
      payload.script_content = conditionGroupToCue(visualTree);
    } else {
      // Code mode
      payload.script_content = formData.logic;
      // Clear condition_json if switching to code to avoid ambiguity or keep it? 
      // Safest to send what we have.
    }

    try {
      if (editDialogOpen && selectedRule) {
        // Update
        const response = await fetch(`/api/validation-rules/${selectedRule.id}?tenant_id=${tenantId}`, {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json',
            'X-Tenant-ID': tenantId
          },
          body: JSON.stringify(payload)
        });

        if (!response.ok) throw new Error('Failed to update rule');

        notification.success('Rule updated successfully');
        setEditDialogOpen(false);
      } else {
        // Create
        const response = await fetch(`/api/validation-rules?tenant_id=${tenantId}&datasource_id=${datasourceId}`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-Tenant-ID': tenantId,
            'X-Tenant-Datasource-ID': datasourceId
          },
          body: JSON.stringify(payload)
        });

        if (!response.ok) {
           const errData = await response.json();
           throw new Error(errData.details || errData.error || 'Failed to create rule');
        }

        notification.success('Rule created successfully');
        setCreateDialogOpen(false);
      }

      setFormData({});
      // Refresh list
      fetchRules();

    } catch (err: any) {
      console.error('Save rule error:', err);
      notification.error(err.message || 'Failed to save rule');
    }
  };

  const handleEditRule = (rule: ValidationRule) => {
    if (onEditRule) {
      onEditRule(rule);
      return;
    }
    setSelectedRule(rule);
    setFormData(rule);

    // Attempt to parse logic to visual tree, else switch to code mode
    const parsedTree = cueToConditionGroup(rule.logic || '');
    if (parsedTree) {
      setVisualTree(parsedTree);
      setIsVisualMode(true);
    } else {
      setIsVisualMode(false);
      // setVisualTree empty/default
      setVisualTree({ id: 'root', type: 'group', operator: 'AND', conditions: [] });
    }
    setEditDialogOpen(true);
  };

  const handleDeleteRule = async (rule: ValidationRule) => {
    try {
      // Call the backend API to delete the rule
      const response = await fetch(`/api/validation-rules/${rule.id}`, {
        method: 'DELETE',
        headers: {
          'X-Tenant-ID': tenantId,
          'X-Tenant-Datasource-ID': datasourceId,
        },
      });

      if (!response.ok) {
        throw new Error('Failed to delete rule');
      }

      // Update local state after successful deletion
      const updatedRules = rules.filter(r => r.id !== rule.id);
      setRules(updatedRules);
      if (onRulesUpdate) onRulesUpdate(updatedRules);
      notification.success('Rule deleted successfully');
      setDeleteConfirm(null);
    } catch (err) {
      notification.error(err instanceof Error ? err.message : 'Failed to delete rule');
    }
  };

  const handleSelectRule = (ruleId: string) => {
    const newSelected = new Set(selectedRules);
    if (newSelected.has(ruleId)) {
      newSelected.delete(ruleId);
    } else {
      newSelected.add(ruleId);
    }
    setSelectedRules(newSelected);
  };

  const handleSelectAll = () => {
    if (selectedRules.size === lazyLoadedRules.length) {
      setSelectedRules(new Set());
    } else {
      setSelectedRules(new Set(lazyLoadedRules.map(r => r.id)));
    }
  };

  const handleBulkToggleStatus = () => {
    const updatedRules = rules.map(r => {
      if (selectedRules.has(r.id)) {
        return { ...r, status: r.status === 'active' ? 'inactive' : 'active' as 'active' | 'inactive' };
      }
      return r;
    });
    setRules(updatedRules as ValidationRule[]);
    if (onRulesUpdate) onRulesUpdate(updatedRules as ValidationRule[]);
    setSelectedRules(new Set());
    notification.success(`${selectedRules.size} rule(s) updated successfully`);
    setBulkActionAnchor(null);
  };

  const handleBulkDelete = () => {
    const updatedRules = rules.filter(r => !selectedRules.has(r.id));
    setRules(updatedRules);
    if (onRulesUpdate) onRulesUpdate(updatedRules);
    setSelectedRules(new Set());
    notification.success(`${selectedRules.size} rule(s) deleted successfully`);
    setBulkActionAnchor(null);
  };

  const handleExport = (format: 'csv' | 'json') => {
    const dataToExport = selectedRules.size > 0 
      ? rules.filter(r => selectedRules.has(r.id))
      : filteredRules;

    if (format === 'csv') {
      const headers = ['Rule Name', 'Description', 'Type', 'Severity', 'Status'];
      const csvContent = [
        headers.join(','),
        ...dataToExport.map(rule =>
          [rule.name, rule.description, rule.type, rule.severity, rule.status].map(v => `"${v}"`).join(',')
        )
      ].join('\n');
      downloadFile(csvContent, `validation-rules-${new Date().toISOString().split('T')[0]}.csv`, 'text/csv');
    } else {
      const jsonContent = JSON.stringify(dataToExport, null, 2);
      downloadFile(jsonContent, `validation-rules-${new Date().toISOString().split('T')[0]}.json`, 'application/json');
    }
    notification.success(`Exported ${dataToExport.length} rule(s) successfully`);
  };

  const downloadFile = (content: string, filename: string, type: string) => {
    const blob = new Blob([content], { type });
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    window.URL.revokeObjectURL(url);
  };

  const getSeverityIcon = (severity: string) => {
    switch (severity) {
      case 'error':
        return <ErrorIcon sx={{ color: '#dc2626', fontSize: '18px' }} />;
      case 'warning':
        return <WarningIcon sx={{ color: '#f59e0b', fontSize: '18px' }} />;
      case 'info':
        return <InfoIcon sx={{ color: '#3b82f6', fontSize: '18px' }} />;
      default:
        return null;
    }
  };

  const getTypeColor = (type: string) => {
    switch (type) {
      case 'expression':
        return 'primary';
      case 'regex':
        return 'secondary';
      case 'lookup':
        return 'warning';
      default:
        return 'default';
    }
  };

  return (
    <Box sx={{ width: '100%', bgcolor: theme.palette.mode === 'dark' ? '#101922' : '#f5f7f8' }}>
      {error && (
        <Alert severity="error" sx={{ mx: 2, my: 2 }}>
          {error}
        </Alert>
      )}

      {loading && (
        <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', py: 6 }}>
          <CircularProgress />
        </Box>
      )}

      {!loading && (
        <>
          {/* Header */}
          <Box sx={{ px: 2, py: 2, borderBottom: '1px solid', borderColor: 'divider' }}>
            <Typography variant="subtitle1" sx={{ fontWeight: 500 }}>
              Validation Rules for: <strong>{selectedNodeType === 'subtype' ? selectedNodeName : businessObjectName}</strong>
              {selectedNodeType === 'subtype' && (
                <Chip label="Subtype" size="small" sx={{ ml: 1 }} />
              )}
            </Typography>
          </Box>

          {/* Search and Filters */}
          <Box sx={{ px: 2, py: 2 }}>
            <Stack direction={{ xs: 'column', md: 'row' }} spacing={2} alignItems="center">
              <TextField
                size="small"
                placeholder="Search by rule name or description..."
                InputProps={{
                  startAdornment: <SearchIcon sx={{ mr: 1, color: theme.palette.mode === 'dark' ? '#9aaab9' : '#60758a' }} />,
                }}
                value={searchQuery}
                onChange={(e) => {
                  setSearchQuery(e.target.value);
                  setVisibleCount(20);
                }}
                sx={{
                  flex: 1,
                  '& .MuiOutlinedInput-root': {
                    bgcolor: theme.palette.mode === 'dark' ? '#1a2632' : '#ffffff',
                    color: theme.palette.mode === 'dark' ? '#fff' : '#111418',
                    '& fieldset': { borderColor: theme.palette.mode === 'dark' ? '#3a4b5c' : '#dbe0e6' },
                    '&:hover fieldset': { borderColor: theme.palette.mode === 'dark' ? '#4a5b6c' : '#bbc1c9' }
                  }
                }}
              />
              <IconButton
                size="small"
                onClick={() => setAdvancedFiltersExpanded(!advancedFiltersExpanded)}
                sx={{ color: theme.palette.mode === 'dark' ? '#9aaab9' : '#60758a' }}
              >
                <FilterListIcon />
              </IconButton>
              <Button
                variant="contained"
                startIcon={<AddIcon />}
                onClick={handleCreateRule}
                sx={{
                  bgcolor: '#0d7ff2',
                  color: '#fff',
                  '&:hover': { bgcolor: '#0a5fb8' }
                }}
              >
                Add Rule
              </Button>
            </Stack>

            {/* Advanced Filters */}
            {advancedFiltersExpanded && (
              <Stack direction={{ xs: 'column', md: 'row' }} spacing={2} sx={{ mt: 2 }}>
                <Select
                  size="small"
                  value={severityFilter}
                  onChange={(e) => {
                    setSeverityFilter(e.target.value);
                    setVisibleCount(20);
                  }}
                  displayEmpty
                  sx={{
                    flex: 1,
                    bgcolor: theme.palette.mode === 'dark' ? '#1a2632' : '#ffffff',
                    color: theme.palette.mode === 'dark' ? '#fff' : '#111418',
                    '& .MuiOutlinedInput-notchedOutline': { borderColor: theme.palette.mode === 'dark' ? '#3a4b5c' : '#dbe0e6' }
                  }}
                >
                  <MenuItem value="">All Severities</MenuItem>
                  <MenuItem value="error">Error</MenuItem>
                  <MenuItem value="warning">Warning</MenuItem>
                  <MenuItem value="info">Info</MenuItem>
                </Select>

                <Select
                  size="small"
                  value={typeFilter}
                  onChange={(e) => {
                    setTypeFilter(e.target.value);
                    setVisibleCount(20);
                  }}
                  displayEmpty
                  sx={{
                    flex: 1,
                    bgcolor: theme.palette.mode === 'dark' ? '#1a2632' : '#ffffff',
                    color: theme.palette.mode === 'dark' ? '#fff' : '#111418',
                    '& .MuiOutlinedInput-notchedOutline': { borderColor: theme.palette.mode === 'dark' ? '#3a4b5c' : '#dbe0e6' }
                  }}
                >
                  <MenuItem value="">All Types</MenuItem>
                  <MenuItem value="expression">Expression</MenuItem>
                  <MenuItem value="regex">Regex</MenuItem>
                  <MenuItem value="lookup">SQL Lookup</MenuItem>
                </Select>

                <Select
                  size="small"
                  value={statusFilter}
                  onChange={(e) => {
                    setStatusFilter(e.target.value);
                    setVisibleCount(20);
                  }}
                  displayEmpty
                  sx={{
                    flex: 1,
                    bgcolor: theme.palette.mode === 'dark' ? '#1a2632' : '#ffffff',
                    color: theme.palette.mode === 'dark' ? '#fff' : '#111418',
                    '& .MuiOutlinedInput-notchedOutline': { borderColor: theme.palette.mode === 'dark' ? '#3a4b5c' : '#dbe0e6' }
                  }}
                >
                  <MenuItem value="">All Statuses</MenuItem>
                  <MenuItem value="active">Active</MenuItem>
                  <MenuItem value="inactive">Inactive</MenuItem>
                </Select>
              </Stack>
            )}

            {/* Bulk Actions */}
            {selectedRules.size > 0 && (
              <Stack direction={{ xs: 'column', md: 'row' }} spacing={1} sx={{ mt: 2, p: 2, bgcolor: theme.palette.mode === 'dark' ? '#202b38' : '#f3f4f6', borderRadius: '0.5rem' }}>
                <Typography variant="body2" sx={{ flex: 1, color: theme.palette.mode === 'dark' ? '#fff' : '#111418', fontWeight: 500 }}>
                  {selectedRules.size} rule{selectedRules.size > 1 ? 's' : ''} selected
                </Typography>
