              placeholder="What this rule validates"
              size="small"
            />
            {availableFields.length > 0 && (
              <Box>
                <Typography variant="subtitle2" sx={{ mb: 1 }}>Apply to Fields (Optional)</Typography>
                <Stack direction="row" spacing={1} sx={{ flexWrap: 'wrap', gap: 1 }}>
                  {availableFields.map((field) => (
                    <Chip
                      key={field.key}
                      label={field.displayName || field.name}
                      onClick={() => {
                        const appliedFields = formData.appliedFields || [];
                        const index = appliedFields.indexOf(field.key);
                        if (index > -1) {
                          appliedFields.splice(index, 1);
                        } else {
                          appliedFields.push(field.key);
                        }
                        setFormData({ ...formData, appliedFields: [...appliedFields] });
                      }}
                      variant={formData.appliedFields?.includes(field.key) ? 'filled' : 'outlined'}
                      color={formData.appliedFields?.includes(field.key) ? 'primary' : 'default'}
                      size="small"
                    />
                  ))}
                </Stack>
              </Box>
            )}
            <Select
              fullWidth
              value={formData.type || 'expression'}
              onChange={(e) => setFormData({ ...formData, type: e.target.value as any })}
              size="small"
            >
              <MenuItem value="expression">Expression</MenuItem>
              <MenuItem value="regex">Regex</MenuItem>
              <MenuItem value="lookup">SQL Lookup</MenuItem>
            </Select>
            <Select
              fullWidth
              value={formData.severity || 'error'}
              onChange={(e) => setFormData({ ...formData, severity: e.target.value as any })}
              size="small"
            >
              <MenuItem value="error">Error</MenuItem>
              <MenuItem value="warning">Warning</MenuItem>
              <MenuItem value="info">Info</MenuItem>
            </Select>

            {/* Toggle between Visual and Code */}
            {formData.type === 'expression' && (
               <Stack direction="row" spacing={1} alignItems="center" justifyContent="flex-end">
                 <Typography variant="caption" color="text.secondary">Mode:</Typography>
                 <Button 
                   size="small" 
                   variant={isVisualMode ? 'contained' : 'outlined'} 
                   onClick={() => setIsVisualMode(true)}
                   sx={{ fontSize: '0.7rem', py: 0.5, minWidth: 'auto' }}
                 >
                   Visual
                 </Button>
                 <Button 
                   size="small" 
                   variant={!isVisualMode ? 'contained' : 'outlined'} 
                   onClick={() => setIsVisualMode(false)}
                   sx={{ fontSize: '0.7rem', py: 0.5, minWidth: 'auto' }}
                 >
                   Code (CUE)
                 </Button>
               </Stack>
            )}

            {isVisualMode && formData.type === 'expression' ? (
              <Box sx={{ border: '1px solid', borderColor: 'divider', borderRadius: 1, p: 1 }}>
                <ExpressionBuilder
                  availableFields={availableFields.map(f => ({
                    name: f.name,
                    label: f.displayName || f.name,
                    type: f.type || 'string'
                  }))}
                  onChange={(tree: ConditionGroup) => {
                    setVisualTree(tree);
                    const cue = conditionGroupToCue(tree);
                    setFormData({ ...formData, logic: cue });
                  }}
                  autosave={false}
                />
                <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                  Generated Logic: <code>{formData.logic}</code>
                </Typography>
              </Box>
            ) : (
              <TextField
                fullWidth
                label="Logic / Formula"
                value={formData.logic || ''}
                onChange={(e) => setFormData({ ...formData, logic: e.target.value })}
                multiline
                rows={4}
                placeholder="Enter the validation logic (CUE expression)"
                size="small"
                inputProps={{ style: { fontFamily: 'monospace', fontSize: '0.875rem' } }}
              />
            )}
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => { setCreateDialogOpen(false); setEditDialogOpen(false); }}>Cancel</Button>
          <Button onClick={handleSaveRule} variant="contained">
            {editDialogOpen ? 'Update Rule' : 'Create Rule'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* View Logic Dialog */}
      <Dialog open={viewLogicOpen} onClose={() => setViewLogicOpen(false)} maxWidth="md" fullWidth>
        <DialogTitle>Rule Logic: {selectedRule?.name}</DialogTitle>
        <DialogContent sx={{ pt: 2 }}>
          <Stack spacing={2}>
            {selectedRule && (
              <>
                {/* CUE Code Section */}
                <Box>
                  <Typography variant="subtitle2" sx={{ mb: 1, fontWeight: 600 }}>
                    CUE Validation Code
                  </Typography>
                  <Box sx={{ 
                    p: 2, 
                    bgcolor: theme.palette.mode === 'dark' ? 'grey.900' : 'grey.100', 
                    borderRadius: 1, 
                    fontFamily: 'monospace', 
                    whiteSpace: 'pre-wrap', 
                    wordBreak: 'break-word',
                    fontSize: '0.875rem',
                    border: `1px solid ${theme.palette.mode === 'dark' ? 'grey.800' : 'grey.300'}`
                  }}>
                    {selectedRule?.logic || 'No CUE code available for this rule'}
                  </Box>
                  <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                    This is the CUE validation code that will be executed against your data.
                  </Typography>
                </Box>

                {/* Raw Logic/Metadata Section */}
                <Box>
                  <Typography variant="subtitle2" sx={{ mb: 1, fontWeight: 600 }}>
                    Rule Details
                  </Typography>
                  <Box sx={{ 
                    p: 2, 
                    bgcolor: theme.palette.mode === 'dark' ? '#1a1a1a' : '#f9f9f9', 
                    borderRadius: 1, 
                    fontSize: '0.875rem',
                    border: `1px solid ${theme.palette.mode === 'dark' ? 'grey.800' : 'grey.300'}`
                  }}>
                    <Stack spacing={1}>
                      <Box>
                        <Typography variant="caption" color="text.secondary">Type:</Typography>
                        <Typography variant="body2">{selectedRule.type}</Typography>
                      </Box>
                      <Box>
                        <Typography variant="caption" color="text.secondary">Severity:</Typography>
                        <Typography variant="body2">{selectedRule.severity}</Typography>
                      </Box>
                      <Box>
                        <Typography variant="caption" color="text.secondary">Status:</Typography>
                        <Typography variant="body2">{selectedRule.status}</Typography>
                      </Box>
                    </Stack>
                  </Box>
                </Box>
              </>
            )}
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setViewLogicOpen(false)}>Close</Button>
        </DialogActions>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog open={Boolean(deleteConfirm)} onClose={() => setDeleteConfirm(null)}>
        <DialogTitle>Delete Validation Rule</DialogTitle>
        <DialogContent>
          <Typography>
            Are you sure you want to delete <strong>{deleteConfirm?.name}</strong>?
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteConfirm(null)}>Cancel</Button>
          <Button onClick={() => deleteConfirm && handleDeleteRule(deleteConfirm)} color="error" variant="contained">
            Delete
          </Button>
        </DialogActions>
      </Dialog>

      {/* Bulk Actions Menu */}
      <Menu
        anchorEl={bulkActionAnchor}
        open={Boolean(bulkActionAnchor)}
        onClose={() => setBulkActionAnchor(null)}
      >
        <MenuItem onClick={handleBulkToggleStatus}>
          {rules.some(r => selectedRules.has(r.id) && r.status === 'active') ? 'Deactivate Selected' : 'Activate Selected'}
        </MenuItem>
        <MenuItem onClick={() => handleExport('csv')}>Export Selected as CSV</MenuItem>
        <MenuItem onClick={() => handleExport('json')}>Export Selected as JSON</MenuItem>
        <MenuItem onClick={handleBulkDelete} sx={{ color: 'error.main' }}>Delete Selected</MenuItem>
      </Menu>

      {/* Audit Log Dialog */}
      <AuditLogDialog open={auditLogOpen} onClose={() => setAuditLogOpen(false)} />

      {/* Settings Dialog */}
      <SettingsDialog
        open={settingsOpen}
        onClose={() => setSettingsOpen(false)}
        initialSettings={validationSettings}
        onSave={(newSettings) => {
          setValidationSettings(newSettings);
          notification.success('Settings saved successfully');
        }}
      />
    </Box>
  );
};

export default ValidationRulesPage;

import React, { useState, useEffect } from 'react';
import { DollarSign, TrendingUp, Users, Calendar, CheckCircle, AlertCircle, Settings } from 'lucide-react';

interface FeeSchedule {
  scheduleId: string;
  scheduleName: string;
  feeType: string;
  aumTiers: Array<{ threshold: number; rate: number }>;
  performanceFeeRate?: number;
  highWaterMark?: number;
  isActive: boolean;
}

interface FeeCalculation {
  calculationId: string;
  clientName: string;
  period: string;
  aumBaseFee: number;
  performanceFee: number;
  totalFee: number;
  status: string;
  calculatedAt: string;
}

export const FeeBillingCenter: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'overview' | 'schedules' | 'calculations'>('overview');
  const [schedules, setSchedules] = useState<FeeSchedule[]>([]);
  const [calculations, setCalculations] = useState<FeeCalculation[]>([]);
  const [stats, setStats] = useState({
    totalRevenue: 0,
    pendingApprovals: 0,
    activeClients: 0,
    avgFee: 0,
  });

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [schedulesRes, calculationsRes] = await Promise.all([
        fetch('/api/fee-billing/schedules'),
        fetch('/api/fee-billing/calculations'),
      ]);

      setSchedules(await schedulesRes.json());
      const calcs = await calculationsRes.json();
      setCalculations(calcs);

      // Calculate stats
      const totalRev = calcs.reduce((sum: number, c: FeeCalculation) => sum + c.totalFee, 0);
      const pending = calcs.filter((c: FeeCalculation) => c.status === 'PENDING').length;

      setStats({
        totalRevenue: totalRev,
        pendingApprovals: pending,
        activeClients: calcs.length,
        avgFee: totalRev / (calcs.length || 1),
      });
    } catch (error) {
      console.error('Failed to fetch fee billing data:', error);
    }
  };

  return (
    <div className="max-w-7xl mx-auto p-6">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">Fee Billing Center</h1>
          <p className="text-gray-600 mt-1">Manage fee schedules, calculations, and revenue recognition</p>
        </div>
        <button className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors">
          <Settings className="w-5 h-5 inline mr-2" />
          Configure Billing
        </button>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
        <StatCard
          icon={<DollarSign />}
          label="Total Revenue YTD"
          value={`$${(stats.totalRevenue / 1000).toFixed(0)}K`}
          change="+12.5%"
          positive
        />
        <StatCard
          icon={<AlertCircle />}
          label="Pending Approvals"
          value={stats.pendingApprovals.toString()}
          change="Requires action"
          positive={false}
        />
        <StatCard
          icon={<Users />}
          label="Active Clients"
          value={stats.activeClients.toString()}
          change="+8 this month"
          positive
        />
        <StatCard
          icon={<TrendingUp />}
          label="Avg Fee per Client"
          value={`$${(stats.avgFee / 1000).toFixed(1)}K`}
          change="+5.2%"
          positive
        />
      </div>

      {/* Tabs */}
      <div className="flex gap-4 border-b border-gray-200 mb-6">
        <TabButton
          label="Overview"
          active={activeTab === 'overview'}
          onClick={() => setActiveTab('overview')}
        />
        <TabButton
          label="Fee Schedules"
          active={activeTab === 'schedules'}
          onClick={() => setActiveTab('schedules')}
        />
        <TabButton
          label="Calculations"
          active={activeTab === 'calculations'}
          onClick={() => setActiveTab('calculations')}
        />
      </div>

      {/* Tab Content */}
      {activeTab === 'overview' && <OverviewTab calculations={calculations} />}
      {activeTab === 'schedules' && <SchedulesTab schedules={schedules} onUpdate={fetchData} />}
      {activeTab === 'calculations' && <CalculationsTab calculations={calculations} onUpdate={fetchData} />}
    </div>
  );
};

const StatCard: React.FC<{ icon: React.ReactNode; label: string; value: string; change: string; positive: boolean }> = ({
  icon,
  label,
  value,
  change,
  positive,
}) => (
  <div className="bg-white rounded-xl border border-gray-200 p-6">
    <div className="flex items-start justify-between mb-4">
      <div className="p-3 bg-indigo-100 rounded-lg">
        <div className="text-indigo-600">{icon}</div>
      </div>
      <span className={`text-sm font-medium ${positive ? 'text-green-600' : 'text-orange-600'}`}>
        {change}
      </span>
    </div>
    <p className="text-3xl font-bold text-gray-900">{value}</p>
    <p className="text-sm text-gray-600 mt-1">{label}</p>
  </div>
);

const TabButton: React.FC<{ label: string; active: boolean; onClick: () => void }> = ({ label, active, onClick }) => (
  <button
    onClick={onClick}
    className={`px-4 py-3 border-b-2 transition-colors font-medium ${
      active ? 'border-indigo-600 text-indigo-600' : 'border-transparent text-gray-600 hover:text-gray-900'
    }`}
  >
    {label}
  </button>
);

const OverviewTab: React.FC<{ calculations: FeeCalculation[] }> = ({ calculations }) => {
  const recentCalcs = calculations.slice(0, 5);

  return (
    <div className="space-y-6">
