// Conditional Rule Builder Component - inspired by ValidationRuleCreator
const ConditionBuilderDialog: React.FC<{
  open: boolean;
  onClose: () => void;
  onApply: (conditions: ConditionGroup) => void;
  availableFields: string[];
  currentConditions?: ConditionGroup;
}> = ({ open, onClose, onApply, availableFields, currentConditions }) => {
  const [conditions, setConditions] = useState<ConditionGroup>(
    currentConditions || { conditions: [], logic: 'AND' }
  );

  const addCondition = () => {
    setConditions({
      ...conditions,
      conditions: [
        ...conditions.conditions,
        { id: `cond-${Date.now()}`, field: '', operator: 'equals', value: '' }
      ]
    });
  };

  const removeCondition = (id: string) => {
    setConditions({
      ...conditions,
      conditions: conditions.conditions.filter(c => c.id !== id)
    });
  };

  const updateCondition = (id: string, updates: Partial<WhereCondition>) => {
    setConditions({
      ...conditions,
      conditions: conditions.conditions.map(c => c.id === id ? { ...c, ...updates } : c)
    });
  };

  const handleApply = () => {
    onApply(conditions);
    onClose();
  };

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle>Build WHERE Clause</DialogTitle>
      <DialogContent sx={{ pt: 2 }}>
        <Stack spacing={2}>
          {/* Logic Operator */}
          <FormControl size="small" fullWidth>
            <InputLabel>Match</InputLabel>
            <Select
              value={conditions.logic}
              onChange={(e) => setConditions({ ...conditions, logic: e.target.value as 'AND' | 'OR' })}
              label="Match"
            >
              <MenuItem value="AND">ALL conditions</MenuItem>
              <MenuItem value="OR">ANY condition</MenuItem>
            </Select>
          </FormControl>

          {/* Conditions */}
          <Stack spacing={2}>
            {conditions.conditions.map((cond, idx) => (
              <Card key={cond.id} variant="outlined">
                <CardContent sx={{ p: 2, '&:last-child': { pb: 2 } }}>
                  <Stack direction="row" spacing={1} alignItems="flex-start">
                    {/* Field */}
                    <Autocomplete
                      options={availableFields}
                      value={cond.field}
                      onChange={(_, val) => updateCondition(cond.id, { field: val || '' })}
                      renderInput={(params) => <TextField {...params} label="Field" size="small" />}
                      sx={{ flex: 1 }}
                      noOptionsText="No fields"
                    />

                    {/* Operator */}
                    <FormControl size="small" sx={{ minWidth: 120 }}>
                      <InputLabel>Operator</InputLabel>
                      <Select
                        value={cond.operator}
                        onChange={(e) => updateCondition(cond.id, { operator: e.target.value as any })}
                        label="Operator"
                      >
                        {OPERATOR_OPTIONS.map(op => (
                          <MenuItem key={op.value} value={op.value}>{op.label}</MenuItem>
                        ))}
                      </Select>
                    </FormControl>

                    {/* Value (hidden for IS NULL / IS NOT NULL) */}
                    {!['is_null', 'is_not_null'].includes(cond.operator) && (
                      <TextField
                        value={cond.value}
                        onChange={(e) => updateCondition(cond.id, { value: e.target.value })}
                        placeholder="Value"
                        size="small"
                        sx={{ flex: 1 }}
                      />
                    )}

                    {/* Delete Button */}
                    <IconButton
                      size="small"
                      onClick={() => removeCondition(cond.id)}
                      sx={{ mt: 0.5 }}
                    >
                      <DeleteIcon fontSize="small" />
                    </IconButton>
                  </Stack>
                </CardContent>
              </Card>
            ))}
          </Stack>

          {/* Add Condition Button */}
          <Button
            variant="outlined"
            startIcon={<AddIcon />}
            onClick={addCondition}
            size="small"
          >
            Add Condition
          </Button>
        </Stack>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>Cancel</Button>
        <Button onClick={handleApply} variant="contained">Apply Filters</Button>
      </DialogActions>
    </Dialog>
  );
};

// A reusable component for chip-based input
const ChipInput: React.FC<{ label: string; chips: string[]; setChips: (c: string[]) => void }> = ({ label, chips, setChips }) => {
  const [inputValue, setInputValue] = useState<string>('');

  const handleAddChip = (e: KeyboardEvent<HTMLInputElement>) => {
    if ((e as KeyboardEvent<HTMLInputElement>).key === 'Enter' && inputValue.trim() !== '') {
      (e as KeyboardEvent<HTMLInputElement>).preventDefault();
      // Prevent duplicates
      if (!chips.includes(inputValue.trim())) {
        setChips([...chips, inputValue.trim()]);
      }
      setInputValue('');
    }
  };

  const handleDeleteChip = (chipToDelete: string) => {
    setChips(chips.filter((chip) => chip !== chipToDelete));
  };

  return (
    <Box>
      <TextField
        label={label}
        variant="outlined"
        value={inputValue}
        onChange={(e) => setInputValue(e.target.value)}
        onKeyDown={handleAddChip}
        fullWidth
        helperText="Type a value and press Enter to add."
      />
      <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mt: 1, minHeight: '32px' }}>
        {chips.map((chip, index) => (
          <Chip
            key={index}
            label={chip}
            onDelete={() => handleDeleteChip(chip)}
          />
        ))}
      </Box>
    </Box>
  );
};

const QueryBuilder = () => {
  const { tenant, datasource } = useTenant();
  const { user } = useAuth();
  const [activeTab, setActiveTab] = useState(0);
  const [view, setView] = useState('orders');
  const [dimensions, setDimensions] = useState(['order_date', 'ship_country']);
  const [measures, setMeasures] = useState(['total_freight']);
  const [filters, setFilters] = useState('');

  const [results, setResults] = useState<any[] | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // Results Tab Enhancements
  const [searchText, setSearchText] = useState('');
  const [sortColumn, setSortColumn] = useState<string | null>(null);
  const [sortDirection, setSortDirection] = useState<'asc' | 'desc'>('asc');
  const [conditionBuilderOpen, setConditionBuilderOpen] = useState(false);
  const [whereConditions, setWhereConditions] = useState<ConditionGroup>({ conditions: [], logic: 'AND' });

  // Lazy loading and limit
  const [currentPage, setCurrentPage] = useState(0);
  const [pageSize, setPageSize] = useState(100);
  const [limit, setLimit] = useState<number>(100);



  const handleExecuteQuery = async () => {
    setLoading(true);
    setError('');
    setResults(null);

    const queryPayload = {
      view,
      dimensions,
      measures,
      filters,
    };

    try {
      const apiBase = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000';
      const response = await axios.post(`${apiBase.replace(/\/$/, '')}/api/query`, queryPayload);
      setResults(response.data);
    } catch (err) {
      const e: any = err
      setError(e?.response?.data?.details || e?.message || 'An unexpected error occurred.');
    } finally {
      setLoading(false);
    }
  };

  const getTableHeaders = () => {
    if (!results || results.length === 0) return [];
    return Object.keys(results[0]);
  };

  // Filtered and sorted results with pagination
  const processedResults = useMemo(() => {
    if (!results) return [];

    let filtered = results;

    // Apply text search across all columns
    if (searchText.trim()) {
      const searchLower = searchText.toLowerCase();
      filtered = filtered.filter(row =>
        Object.values(row).some(val =>
          String(val).toLowerCase().includes(searchLower)
        )
      );
    }

    // Apply sorting
    if (sortColumn) {
      filtered = [...filtered].sort((a, b) => {
        const aVal = a[sortColumn];
        const bVal = b[sortColumn];

        // Handle null/undefined
        if (aVal == null && bVal == null) return 0;
        if (aVal == null) return sortDirection === 'asc' ? 1 : -1;
        if (bVal == null) return sortDirection === 'asc' ? -1 : 1;

        // Compare values
        if (typeof aVal === 'number' && typeof bVal === 'number') {
          return sortDirection === 'asc' ? aVal - bVal : bVal - aVal;
        }

        const aStr = String(aVal).toLowerCase();
        const bStr = String(bVal).toLowerCase();
        return sortDirection === 'asc' ? aStr.localeCompare(bStr) : bStr.localeCompare(aStr);
      });
    }

    // Apply limit before pagination
    const limitedResults = filtered.slice(0, limit);

    // Apply pagination (lazy loading)
    const startIdx = currentPage * pageSize;
    const endIdx = startIdx + pageSize;
    return limitedResults.slice(startIdx, endIdx);
  }, [results, searchText, sortColumn, sortDirection, limit, currentPage, pageSize]);

  const handleSort = (column: string) => {
    if (sortColumn === column) {
      // Toggle direction if same column
      setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc');
    } else {
      // New column
      setSortColumn(column);
      setSortDirection('asc');
    }
  };

  const handleApplyConditions = (conditions: ConditionGroup) => {
    setWhereConditions(conditions);
    // Build SQL WHERE clause from conditions
    const whereClauses = conditions.conditions
      .filter(c => c.field && c.operator && (c.value || ['is_null', 'is_not_null'].includes(c.operator)))
      .map(c => {
        switch (c.operator) {
          case 'equals':
            return `${c.field} = '${c.value}'`;
          case 'not_equals':
            return `${c.field} != '${c.value}'`;
          case 'contains':
            return `${c.field} LIKE '%${c.value}%'`;
          case 'starts_with':
            return `${c.field} LIKE '${c.value}%'`;
          case 'ends_with':
            return `${c.field} LIKE '%${c.value}'`;
          case 'greater_than':
            return `${c.field} > ${c.value}`;
          case 'less_than':
            return `${c.field} < ${c.value}`;
          case 'greater_or_equal':
            return `${c.field} >= ${c.value}`;
          case 'less_or_equal':
            return `${c.field} <= ${c.value}`;
          case 'is_null':
            return `${c.field} IS NULL`;
          case 'is_not_null':
            return `${c.field} IS NOT NULL`;
          default:
            return '';
        }
      })
      .filter(Boolean);

    if (whereClauses.length > 0) {
      setFilters(whereClauses.join(` ${conditions.logic} `));
    }
  };

  return (
    <Box sx={{ flexGrow: 1, p: 3 }}>
      <Typography variant="h4" gutterBottom>
        Query Builder
      </Typography>
      <Tabs value={activeTab} onChange={(_, newValue) => setActiveTab(newValue)} sx={{ borderBottom: 1, borderColor: 'divider' }}>
        <Tab label="Query Builder" />
        <Tab label="NL Query" />
      </Tabs>
      {activeTab === 0 && (
        <Grid container spacing={3} sx={{ mt: 2 }}>
          <Grid item xs={12} md={4}>
            <Typography variant="h6" gutterBottom>Schema</Typography>
            <Paper sx={{ p: 2, height: '100%' }}>
              <SchemaBrowserAdapter
                setDimensions={setDimensions as any}
                setMeasures={setMeasures as any}
                setView={setView as any}
              />
            </Paper>
          </Grid>
          <Grid item xs={12} md={8}>
            <Typography variant="h6" gutterBottom>Query</Typography>
            <Paper sx={{ p: 2, mb: 3 }}>
              <Box component="form" noValidate autoComplete="off" sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                <TextField
                  label="View Name"
                  variant="outlined"
                  value={view}
                  onChange={(e) => setView(e.target.value)}
                  fullWidth
                />
                <ChipInput label="Dimensions" chips={dimensions} setChips={setDimensions} />
                <ChipInput label="Measures" chips={measures} setChips={setMeasures} />
                <TextField
                  label="Filters (SQL WHERE clause)"
                  variant="outlined"
                  multiline
                  rows={4}
                  value={filters}
                  onChange={(e) => setFilters(e.target.value)}
                  fullWidth
                />
                <Box>
                  <Button variant="contained" onClick={handleExecuteQuery} disabled={loading}>
                    {loading ? <CircularProgress size={24} /> : 'Execute Query'}
                  </Button>
                </Box>
              </Box>
            </Paper>
          </Grid>
        </Grid>

        {/* WHERE Clause Filter Builder - Always Visible */}
        <Paper sx={{ p: 3, mt: 3 }}>
          <Typography variant="h6" gutterBottom>WHERE Clause Builder</Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Build WHERE conditions to filter query results
          </Typography>
          <Stack direction="row" spacing={2}>
            <Button
              variant="outlined"
              startIcon={<TuneIcon />}
              onClick={() => setConditionBuilderOpen(true)}
              size="small"
            >
              {whereConditions.conditions.length > 0 ? `Edit Filters (${whereConditions.conditions.length})` : 'Add Filters'}
            </Button>
            {whereConditions.conditions.length > 0 && (
              <>
                <Typography variant="body2" sx={{ py: 1 }}>
                  Logic: <strong>{whereConditions.logic}</strong>
                </Typography>
                <Button
                  size="small"
                  variant="text"
                  color="error"
                  onClick={() => {
                    setWhereConditions({ conditions: [], logic: 'AND' });
                    setFilters('');
                  }}
                >
                  Clear All
                </Button>
              </>
            )}
          </Stack>

          {/* Display current filters */}
          {whereConditions.conditions.length > 0 && (
            <Box sx={{ mt: 2, p: 2, backgroundColor: '#f5f5f5', borderRadius: 1 }}>
              <Typography variant="subtitle2" gutterBottom>Active Filters:</Typography>
              <Stack spacing={1}>
                {whereConditions.conditions.map((cond, idx) => (
                  <Typography key={cond.id} variant="body2">
                    {idx > 0 && <strong>{whereConditions.logic}</strong>} {cond.field} {OPERATOR_OPTIONS.find(op => op.value === cond.operator)?.label} {cond.value}
                  </Typography>
                ))}
              </Stack>
              <Typography variant="caption" sx={{ mt: 2, display: 'block', color: 'text.secondary' }}>
                Generated WHERE clause: <code>{filters}</code>
              </Typography>
            </Box>
          )}
        </Paper>
      )}
      {activeTab === 1 && (
        <Box sx={{ mt: 2 }}>
          <ConversationalQueryInterface
            currentDatasource={datasource?.id || ''}
            currentUser={user?.id || ''}
            currentTenant={tenant?.id || ''}
          />
        </Box>
      )}

      {activeTab === 0 && error && (
        <Typography color="error" sx={{ mt: 2 }}>
          Error: {error}
        </Typography>
      )}

      {activeTab === 0 && results && results.length > 0 && (
        <Box>
          <Typography variant="h5" gutterBottom sx={{ mt: 4 }}>
            Results
          </Typography>
          <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
              <Typography variant="h6" gutterBottom>Chart</Typography>
              <Paper sx={{ p: 2, height: 400 }}>
                <RechartsBarChart data={results} xKey={dimensions[0]} yKey={measures[0]} />
              </Paper>
            </Grid>
            <Grid item xs={12} md={6}>
              <Typography variant="h6" gutterBottom>Table</Typography>
              <Paper sx={{ p: 2 }}>
                {/* Search, Filter, and Control Bar */}
                <Stack spacing={2} sx={{ mb: 3 }}>
                  {/* Row 1: Search with Typeahead */}
                  <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems="center">
                    <Autocomplete
                      freeSolo
                      size="small"
                      value={searchText}
                      onChange={(_, value) => {
                        setSearchText(value || '');
                        setCurrentPage(0); // Reset to first page on search
                      }}
                      inputValue={searchText}
                      onInputChange={(_, value) => {
                        setSearchText(value);
                        setCurrentPage(0);
                      }}
                      options={getTableHeaders()}
                      getOptionLabel={(option) => {
                        if (typeof option === 'string') return option;
                        return '';
                      }}
                      renderInput={(params) => (
                        <TextField
                          {...params}
                          placeholder="Search results or select column..."
                          variant="outlined"
                          size="small"
                          InputProps={{
                            ...params.InputProps,
                            startAdornment: <SearchIcon sx={{ mr: 1, color: 'text.secondary' }} />,
                          }}
                          sx={{ flex: 1, minWidth: 250 }}
                        />
                      )}
                    />

                    <Tooltip title="Build WHERE clause using conditional builder">
                      <Button
                        variant="outlined"
                        size="small"
                        startIcon={<TuneIcon />}
                        onClick={() => setConditionBuilderOpen(true)}
                      >
                        Filters
                      </Button>
                    </Tooltip>
                  </Stack>

                  {/* Row 2: LIMIT Selector and Row Count Info */}
                  <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems="center">
                    <FormControl size="small" sx={{ minWidth: 120 }}>
                      <InputLabel>Result Limit</InputLabel>
                      <Select
                        value={limit}
                        onChange={(e) => {
                          setLimit(e.target.value as number);
                          setCurrentPage(0); // Reset to first page
                        }}
                        label="Result Limit"
                      >
                        <MenuItem value={100}>100 rows</MenuItem>
                        <MenuItem value={1000}>1,000 rows</MenuItem>
                        <MenuItem value={10000}>10,000 rows</MenuItem>
                      </Select>
                    </FormControl>

                    <Typography variant="body2" sx={{ color: 'text.secondary', whiteSpace: 'nowrap' }}>
                      Showing {currentPage * pageSize + 1}-{Math.min((currentPage + 1) * pageSize, Math.min(limit, results?.length || 0))} of {Math.min(limit, results?.length || 0)} rows
                    </Typography>
                  </Stack>
                </Stack>

                {/* Results Table with Sortable Headers */}
                <TableContainer sx={{ maxHeight: 440, border: '1px solid', borderColor: 'divider', borderRadius: 1 }}>
                  <Table stickyHeader size="small">
                    <TableHead>
                      <TableRow sx={{ backgroundColor: '#f5f5f5' }}>
                        {getTableHeaders().map((header) => (
                          <TableCell
                            key={header}
                            onClick={() => handleSort(header)}
                            sx={{
                              cursor: 'pointer',
                              userSelect: 'none',
                              fontWeight: 600,
                              backgroundColor: '#f5f5f5',
                              '&:hover': {
                                backgroundColor: '#eeeeee',
                              },
                              display: 'flex',
                              alignItems: 'center',
                              gap: 1,
                            }}
                          >
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                              {header}
                              {sortColumn === header && (
                                <ArrowUpDownIcon
                                  sx={{
                                    fontSize: 16,
                                    transform: sortDirection === 'desc' ? 'rotate(180deg)' : 'rotate(0deg)',
                                    transition: 'transform 0.2s',
                                  }}
                                />
                              )}
                            </Box>
                          </TableCell>
                        ))}
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {processedResults.map((row, index) => (
                        <TableRow key={index} sx={{ '&:hover': { backgroundColor: '#fafafa' } }}>
                          {getTableHeaders().map((header) => (
                            <TableCell key={header}>
                              {typeof row[header] === 'object' ? JSON.stringify(row[header]) : String(row[header])}
                            </TableCell>
                          ))}
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>

                {processedResults.length === 0 && results.length > 0 && (
                  <Typography variant="body2" sx={{ mt: 2, textAlign: 'center', color: 'text.secondary' }}>
                    No results match your search criteria.
                  </Typography>
                )}

                {/* Pagination Controls for Lazy Loading */}
                {Math.ceil(Math.min(limit, results?.length || 0) / pageSize) > 1 && (
                  <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mt: 2 }}>
                    <Typography variant="caption" color="text.secondary">
                      Page {currentPage + 1} of {Math.ceil(Math.min(limit, results?.length || 0) / pageSize)}
                    </Typography>
                    <Stack direction="row" spacing={1}>
                      <Button
                        size="small"
                        variant="outlined"
                        disabled={currentPage === 0}
                        onClick={() => setCurrentPage(prev => Math.max(0, prev - 1))}
                      >
                        Previous
                      </Button>
                      <Button
                        size="small"
                        variant="outlined"
                        disabled={(currentPage + 1) * pageSize >= Math.min(limit, results?.length || 0)}
                        onClick={() => setCurrentPage(prev => prev + 1)}
                      >
                        Next
                      </Button>
                    </Stack>
                  </Stack>
                )}
              </Paper>
            </Grid>
          </Grid>

          {/* Condition Builder Dialog */}
          <ConditionBuilderDialog
            open={conditionBuilderOpen}
            onClose={() => setConditionBuilderOpen(false)}
            onApply={handleApplyConditions}
            availableFields={getTableHeaders()}
            currentConditions={whereConditions}
          />
        </Box>
      )}
    </Box>
  );
};

