interface ReportBusinessObject {
  id: string;
  key: string;
  name: string;
  display_name: string;
  description: string;
  category: string;
  report_type: 'standard' | 'composite' | 'scheduled';
  output_formats: string[];
  is_system: boolean;
}

interface ReportParameter {
  name: string;
  label: string;
  type: 'string' | 'number' | 'date' | 'daterange' | 'select' | 'multiselect';
  required: boolean;
  default_value?: any;
  options?: { label: string; value: any }[];
}

interface ReportExecution {
  id: string;
  report_key: string;
  status: 'queued' | 'running' | 'completed' | 'failed';
  parameters: Record<string, any>;
  output_format: string;
  output_url?: string;
  row_count?: number;
  generation_ms?: number;
  started_at: string;
  completed_at?: string;
  error?: string;
}

// ============================================================================
// Report Category Icons
// ============================================================================

const getCategoryIcon = (category: string) => {
  switch (category) {
    case 'portfolio':
      return <ChartIcon />;
    case 'performance':
      return <AssessmentIcon />;
    case 'activity':
    case 'billing':
      return <TableIcon />;
    default:
      return <ReportIcon />;
  }
};

const getCategoryColor = (category: string) => {
  switch (category) {
    case 'portfolio':
      return '#2196f3';
    case 'performance':
      return '#4caf50';
    case 'activity':
      return '#ff9800';
    case 'billing':
      return '#9c27b0';
    case 'tax':
      return '#f44336';
    default:
      return '#607d8b';
  }
};

