// ============================================================================
// Parameter Input Component
// ============================================================================

interface ParameterInputProps {
  parameter: ReportParameter;
  value: any;
  onChange: (value: any) => void;
}

const ParameterInput: React.FC<ParameterInputProps> = ({ parameter, value, onChange }) => {
  switch (parameter.type) {
    case 'date':
      return (
        <TextField
          fullWidth
          type="date"
          label={parameter.label}
          value={value || ''}
          onChange={(e) => onChange(e.target.value)}
          required={parameter.required}
          InputLabelProps={{ shrink: true }}
        />
      );
    case 'select':
      return (
        <FormControl fullWidth>
          <InputLabel>{parameter.label}</InputLabel>
          <Select
            value={value || ''}
            label={parameter.label}
            onChange={(e) => onChange(e.target.value)}
          >
            {parameter.options?.map((opt) => (
              <MenuItem key={opt.value} value={opt.value}>
                {opt.label}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
      );
    case 'number':
      return (
        <TextField
          fullWidth
          type="number"
          label={parameter.label}
          value={value || ''}
          onChange={(e) => onChange(e.target.value)}
          required={parameter.required}
        />
      );
    default:
      return (
        <TextField
          fullWidth
          label={parameter.label}
          value={value || ''}
          onChange={(e) => onChange(e.target.value)}
          required={parameter.required}
        />
      );
  }
};

// ============================================================================
// Run Report Dialog
// ============================================================================

interface RunReportDialogProps {
  open: boolean;
  report: ReportBusinessObject | null;
  parameters: ReportParameter[];
  onClose: () => void;
  onRun: (params: Record<string, any>, format: string) => Promise<void>;
}

const RunReportDialog: React.FC<RunReportDialogProps> = ({
  open,
  report,
  parameters,
  onClose,
  onRun,
}) => {
  const [paramValues, setParamValues] = useState<Record<string, any>>({});
  const [outputFormat, setOutputFormat] = useState('html');
  const [loading, setLoading] = useState(false);

  const handleRun = async () => {
    setLoading(true);
    try {
      await onRun(paramValues, outputFormat);
      onClose();
    } finally {
      setLoading(false);
    }
  };

  if (!report) return null;

  return (
    <Dialog open={open} onClose={onClose} maxWidth="sm" fullWidth>
      <DialogTitle>
        <Stack direction="row" spacing={1} alignItems="center">
          {getCategoryIcon(report.category)}
          <span>Run {report.display_name}</span>
        </Stack>
      </DialogTitle>
      <DialogContent>
        <Typography variant="body2" color="text.secondary" gutterBottom>
          {report.description}
        </Typography>

        {parameters.length > 0 && (
          <Box sx={{ mt: 2 }}>
            <Typography variant="subtitle2" gutterBottom>
              Parameters
            </Typography>
            <Grid container spacing={2}>
              {parameters.map((param) => (
                <Grid item xs={12} sm={6} key={param.name}>
                  <ParameterInput
                    parameter={param}
                    value={paramValues[param.name]}
                    onChange={(v) =>
                      setParamValues({ ...paramValues, [param.name]: v })
                    }
                  />
                </Grid>
              ))}
            </Grid>
          </Box>
        )}

        <FormControl fullWidth sx={{ mt: 2 }}>
          <InputLabel>Output Format</InputLabel>
          <Select
            value={outputFormat}
            label="Output Format"
            onChange={(e) => setOutputFormat(e.target.value)}
          >
            {report.output_formats.map((format) => (
              <MenuItem key={format} value={format}>
                {format.toUpperCase()}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose}>Cancel</Button>
        <Button
          variant="contained"
          onClick={handleRun}
          disabled={loading}
          startIcon={loading ? <CircularProgress size={20} /> : <RunIcon />}
        >
          Run Report
        </Button>
      </DialogActions>
    </Dialog>
  );
};

