interface DataSource {
  id: string;
  name: string;
  displayName: string;
  description?: string;
  type: 'business_object' | 'semantic_model';
  icon: 'customer' | 'order' | 'product' | 'employee' | 'analytics' | 'performance';
  fields: Field[];
  measures?: Measure[];
  rowCount?: number;
}

interface Field {
  id: string;
  name: string;
  label: string;
  type: 'string' | 'number' | 'date' | 'boolean' | 'currency';
  isPrimaryKey?: boolean;
  isForeignKey?: boolean;
  isRequired?: boolean;
  description?: string;
}

interface Measure {
  id: string;
  name: string;
  label: string;
  aggregation: 'SUM' | 'COUNT' | 'AVG' | 'MIN' | 'MAX';
  format?: 'number' | 'currency' | 'percent';
  description?: string;
}

interface SelectedField {
  field: Field;
  sortDirection?: 'asc' | 'desc';
  aggregation?: string;
}

interface FilterCondition {
  id: string;
  field: Field;
  operator: 'equals' | 'not_equals' | 'contains' | 'starts_with' | 'greater_than' | 'less_than' | 'between' | 'in';
  value: string;
  value2?: string; // For 'between'
}

interface ReportConfig {
  name: string;
  description: string;
  dataSource: DataSource | null;
  columns: SelectedField[];
  measures: Measure[];
  filters: FilterCondition[];
  groupBy: Field[];
  sortBy: { field: Field; direction: 'asc' | 'desc' }[];
  limit: number;
  chartType: 'table' | 'bar' | 'line' | 'pie' | 'area' | 'scatter';
  showTotals: boolean;
  showPercentages: boolean;
}

