      tags: formData.tags ? formData.tags.split(',').map((t) => t.trim()) : [],
    };

    try {
      if (editingSecret) {
        await updateSecret({ variables: { id: editingSecret.id, set: secretData } });
      } else {
        await insertSecret({ variables: { object: secretData } });
      }
      setDialogOpen(false);
      refetch();
    } catch (error) {
      console.error('Error saving secret:', error);
    }
  };

  const handleDelete = async (id: string) => {
    if (!window.confirm('Delete this secret configuration?')) return;
    try {
      await deleteSecret({ variables: { id } });
      refetch();
    } catch (error) {
      console.error('Error deleting secret:', error);
    }
  };

  const getTypeChipColor = (type: string) => {
    switch (type) {
      case 'database': return 'primary';
      case 'api-key': return 'secondary';
      case 'aws': return 'warning';
      case 'azure': return 'info';
      default: return 'default';
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Box>
          <Typography variant="h4" sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <SecurityIcon /> Secrets Configuration
          </Typography>
          <Typography color="text.secondary">
            Manage secret paths, rotation policies, and access controls
          </Typography>
        </Box>
        <Button variant="contained" startIcon={<AddIcon />} onClick={() => handleOpenDialog()}>
          Add Secret
        </Button>
      </Box>

      {/* Stats Cards */}
      <Grid container spacing={2} sx={{ mb: 3 }}>
        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Typography color="text.secondary" gutterBottom>Total Secrets</Typography>
              <Typography variant="h4">{secrets.length}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Typography color="text.secondary" gutterBottom>With Rotation</Typography>
              <Typography variant="h4">{secrets.filter(s => s.ttl).length}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Typography color="text.secondary" gutterBottom>Database Creds</Typography>
              <Typography variant="h4">{secrets.filter(s => s.secret_type === 'database').length}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Typography color="text.secondary" gutterBottom>API Keys</Typography>
              <Typography variant="h4">{secrets.filter(s => s.secret_type === 'api-key').length}</Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Secrets Table */}
      <Paper>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Name</TableCell>
              <TableCell>Path</TableCell>
              <TableCell>Type</TableCell>
              <TableCell>Rotation</TableCell>
              <TableCell>Tags</TableCell>
              <TableCell>Updated</TableCell>
              <TableCell align="right">Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {loading ? (
              <TableRow>
                <TableCell colSpan={7} align="center">Loading...</TableCell>
              </TableRow>
            ) : secrets.length === 0 ? (
              <TableRow>
                <TableCell colSpan={7} align="center">
                  No secrets configured. Click "Add Secret" to create one.
                </TableCell>
              </TableRow>
            ) : (
              secrets.map((secret) => (
                <TableRow key={secret.id} hover>
                  <TableCell>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                      <LockIcon fontSize="small" color="action" />
                      {secret.name}
                    </Box>
                  </TableCell>
                  <TableCell>
                    <code style={{ fontSize: '0.85em' }}>{secret.path}</code>
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={SECRET_TYPES.find(t => t.value === secret.secret_type)?.label || secret.secret_type}
                      size="small"
                      color={getTypeChipColor(secret.secret_type) as any}
                    />
                  </TableCell>
                  <TableCell>
                    {secret.ttl ? (
                      <Chip icon={<ScheduleIcon />} label={secret.ttl} size="small" variant="outlined" />
                    ) : (
                      <Typography color="text.secondary" variant="caption">None</Typography>
                    )}
                  </TableCell>
                  <TableCell>
                    {secret.tags?.map((tag) => (
                      <Chip key={tag} label={tag} size="small" sx={{ mr: 0.5 }} />
                    ))}
                  </TableCell>
                  <TableCell>
                    {new Date(secret.updated_at).toLocaleDateString()}
                  </TableCell>
                  <TableCell align="right">
                    <Tooltip title="Edit">
                      <IconButton size="small" onClick={() => handleOpenDialog(secret)}>
                        <EditIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                    <Tooltip title="Rotate Now">
                      <IconButton size="small" color="primary">
                        <RefreshIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                    <Tooltip title="Delete">
                      <IconButton size="small" color="error" onClick={() => handleDelete(secret.id)}>
                        <DeleteIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </Paper>

      {/* Add/Edit Dialog */}
      <Dialog open={dialogOpen} onClose={() => setDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>{editingSecret ? 'Edit Secret' : 'Add Secret'}</DialogTitle>
        <DialogContent>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 1 }}>
            <TextField
              label="Name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              required
              fullWidth
            />
            <TextField
              label="Path"
              value={formData.path}
              onChange={(e) => setFormData({ ...formData, path: e.target.value })}
              required
              fullWidth
              placeholder="secret/myapp/database"
              helperText="Vault path or cloud secret identifier"
            />
            <FormControl fullWidth>
              <InputLabel>Secret Type</InputLabel>
              <Select
                value={formData.secret_type}
                onChange={(e) => setFormData({ ...formData, secret_type: e.target.value })}
                label="Secret Type"
              >
                {SECRET_TYPES.map((type) => (
                  <MenuItem key={type.value} value={type.value}>{type.label}</MenuItem>
                ))}
              </Select>
            </FormControl>
            <TextField
              label="Description"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              multiline
              rows={2}
              fullWidth
            />
            <TextField
              label="Rotation TTL"
              value={formData.ttl}
              onChange={(e) => setFormData({ ...formData, ttl: e.target.value })}
              placeholder="7 days"
              helperText="Leave empty for no auto-rotation"
              fullWidth
            />
            <TextField
              label="Tags"
              value={formData.tags}
              onChange={(e) => setFormData({ ...formData, tags: e.target.value })}
              placeholder="production, critical, database"
              helperText="Comma-separated tags"
              fullWidth
            />
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDialogOpen(false)}>Cancel</Button>
          <Button onClick={handleSave} variant="contained" disabled={!formData.name || !formData.path}>
            {editingSecret ? 'Update' : 'Create'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}

import React, { useState } from 'react';
import {
  Box,
  Typography,
  Paper,
  Card,
  CardContent,
  Grid,
  Chip,
  LinearProgress,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  IconButton,
  Tooltip,
  Alert,
  Button,
} from '@mui/material';
import MonitorHeartIcon from '@mui/icons-material/MonitorHeart';
import RefreshIcon from '@mui/icons-material/Refresh';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import ErrorIcon from '@mui/icons-material/Error';
import WarningIcon from '@mui/icons-material/Warning';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import TrendingDownIcon from '@mui/icons-material/TrendingDown';
import ScheduleIcon from '@mui/icons-material/Schedule';
import LockIcon from '@mui/icons-material/Lock';
import { useQuery } from '@apollo/client';
import { gql } from '@apollo/client';

const GET_MONITORING_DATA = gql`
  query GetMonitoringData($tenantId: uuid!) {
    secret_metadata(where: { tenant_id: { _eq: $tenantId }, deleted_at: { _is_null: true } }) {
      id
      name
      path
      secret_type
      ttl
      updated_at
    }
    secrets_needing_rotation: secret_metadata(
      where: { 
        tenant_id: { _eq: $tenantId }, 
        deleted_at: { _is_null: true },
        ttl: { _is_null: false }
      }
    ) {
      id
      name
      ttl
      updated_at
    }
    recent_access: secret_access_log(
      where: { secret_metadata: { tenant_id: { _eq: $tenantId } } }
      order_by: { requested_at: desc }
      limit: 50
    ) {
      success
      action
      requested_at
    }
  }
`;

interface SecretsMonitoringPageProps {
  tenantId: string;
}

export default function SecretsMonitoringPage({ tenantId }: SecretsMonitoringPageProps) {
  const { data, loading, refetch } = useQuery(GET_MONITORING_DATA, {
    variables: { tenantId },
    skip: !tenantId,
    pollInterval: 30000, // Auto-refresh every 30 seconds
  });

  const secrets = data?.secret_metadata || [];
  const needsRotation = data?.secrets_needing_rotation || [];
  const recentAccess = data?.recent_access || [];

  // Calculate metrics
  const totalSecrets = secrets.length;
  const rotationEnabled = secrets.filter((s: any) => s.ttl).length;
  const successfulAccess = recentAccess.filter((a: any) => a.success).length;
  const failedAccess = recentAccess.filter((a: any) => !a.success).length;
  const successRate = recentAccess.length > 0 ? (successfulAccess / recentAccess.length) * 100 : 100;

  // Check for secrets needing rotation
  const overdueRotations = needsRotation.filter((s: any) => {
    if (!s.ttl || !s.updated_at) return false;
    const lastUpdate = new Date(s.updated_at);
    const ttlMatch = s.ttl.match(/(\d+)\s*(day|hour|minute)/i);
    if (!ttlMatch) return false;
    const value = parseInt(ttlMatch[1]);
    const unit = ttlMatch[2].toLowerCase();
    const msMultiplier = unit === 'day' ? 86400000 : unit === 'hour' ? 3600000 : 60000;
    const dueDate = new Date(lastUpdate.getTime() + value * msMultiplier);
    return new Date() > dueDate;
  });

  const getHealthStatus = () => {
    if (overdueRotations.length > 0 || successRate < 90) return 'warning';
    if (failedAccess > successfulAccess * 0.1) return 'error';
    return 'healthy';
  };

  const healthStatus = getHealthStatus();

  return (
    <Box sx={{ p: 3 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Box>
          <Typography variant="h4" sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            <MonitorHeartIcon /> Secrets Monitoring
          </Typography>
          <Typography color="text.secondary">
            Real-time health and status of your secrets infrastructure
          </Typography>
        </Box>
        <Button variant="outlined" startIcon={<RefreshIcon />} onClick={() => refetch()}>
          Refresh
        </Button>
      </Box>

      {/* Health Status Banner */}
      <Alert 
        severity={healthStatus === 'healthy' ? 'success' : healthStatus === 'warning' ? 'warning' : 'error'}
        sx={{ mb: 3 }}
        icon={healthStatus === 'healthy' ? <CheckCircleIcon /> : healthStatus === 'warning' ? <WarningIcon /> : <ErrorIcon />}
      >
        <strong>System Health: </strong>
        {healthStatus === 'healthy' && 'All secrets are healthy and up to date.'}
        {healthStatus === 'warning' && `${overdueRotations.length} secret(s) need rotation. Success rate: ${successRate.toFixed(1)}%`}
        {healthStatus === 'error' && 'Critical issues detected. Review failed access attempts immediately.'}
      </Alert>

      {/* Metrics Grid */}
      <Grid container spacing={2} sx={{ mb: 3 }}>
        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <Box>
                  <Typography color="text.secondary" gutterBottom>Total Secrets</Typography>
                  <Typography variant="h4">{totalSecrets}</Typography>
                </Box>
                <LockIcon sx={{ fontSize: 40, color: 'primary.main', opacity: 0.5 }} />
              </Box>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <Box>
                  <Typography color="text.secondary" gutterBottom>Auto-Rotation</Typography>
                  <Typography variant="h4">{rotationEnabled}</Typography>
                </Box>
                <ScheduleIcon sx={{ fontSize: 40, color: 'info.main', opacity: 0.5 }} />
              </Box>
              <LinearProgress 
                variant="determinate" 
                value={totalSecrets > 0 ? (rotationEnabled / totalSecrets) * 100 : 0} 
                sx={{ mt: 1 }}
              />
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={3}>
          <Card sx={{ borderLeft: overdueRotations.length > 0 ? '4px solid orange' : '4px solid green' }}>
            <CardContent>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <Box>
                  <Typography color="text.secondary" gutterBottom>Needs Rotation</Typography>
                  <Typography variant="h4" color={overdueRotations.length > 0 ? 'warning.main' : 'success.main'}>
                    {overdueRotations.length}
                  </Typography>
                </Box>
                {overdueRotations.length > 0 ? (
                  <TrendingUpIcon sx={{ fontSize: 40, color: 'warning.main', opacity: 0.5 }} />
                ) : (
                  <TrendingDownIcon sx={{ fontSize: 40, color: 'success.main', opacity: 0.5 }} />
                )}
              </Box>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <Box>
                  <Typography color="text.secondary" gutterBottom>Access Success Rate</Typography>
                  <Typography variant="h4" color={successRate >= 95 ? 'success.main' : successRate >= 80 ? 'warning.main' : 'error.main'}>
                    {successRate.toFixed(1)}%
                  </Typography>
                </Box>
              </Box>
              <LinearProgress 
                variant="determinate" 
                value={successRate} 
                color={successRate >= 95 ? 'success' : successRate >= 80 ? 'warning' : 'error'}
                sx={{ mt: 1 }}
              />
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Secrets Needing Rotation */}
      {overdueRotations.length > 0 && (
        <Paper sx={{ mb: 3 }}>
          <Box sx={{ p: 2, bgcolor: 'warning.lighter', borderBottom: 1, borderColor: 'divider' }}>
            <Typography variant="h6" sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <WarningIcon color="warning" /> Secrets Needing Rotation
            </Typography>
          </Box>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>Secret</TableCell>
                <TableCell>TTL</TableCell>
                <TableCell>Last Rotated</TableCell>
                <TableCell>Status</TableCell>
                <TableCell align="right">Action</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {overdueRotations.map((secret: any) => (
                <TableRow key={secret.id}>
                  <TableCell>{secret.name}</TableCell>
                  <TableCell>{secret.ttl}</TableCell>
                  <TableCell>{new Date(secret.updated_at).toLocaleDateString()}</TableCell>
                  <TableCell>
                    <Chip label="Overdue" color="warning" size="small" />
                  </TableCell>
                  <TableCell align="right">
                    <Button size="small" variant="outlined" startIcon={<RefreshIcon />}>
                      Rotate Now
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </Paper>
      )}

      {/* Recent Activity */}
      <Paper>
        <Box sx={{ p: 2, borderBottom: 1, borderColor: 'divider' }}>
          <Typography variant="h6">Recent Access Activity</Typography>
        </Box>
        <Box sx={{ p: 2 }}>
          <Grid container spacing={1}>
            {recentAccess.slice(0, 20).map((access: any, index: number) => (
              <Grid item key={index}>
                <Tooltip title={`${access.action} - ${new Date(access.requested_at).toLocaleString()}`}>
                  <Box
                    sx={{
                      width: 12,
                      height: 12,
                      borderRadius: '2px',
                      bgcolor: access.success ? 'success.main' : 'error.main',
                      opacity: 0.8,
                    }}
                  />
                </Tooltip>
              </Grid>
            ))}
          </Grid>
          <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
            Last 20 access attempts • Green = Success, Red = Failed
          </Typography>
        </Box>
      </Paper>
    </Box>
  );
}

import React from 'react';
import {
  Box,
  Paper,
  Stack,
  Typography,
  Chip,
  Divider,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
} from '@mui/material';
import {
  Timeline,
  TimelineItem,
  TimelineSeparator,
  TimelineConnector,
  TimelineContent,
  TimelineDot,
  TimelineOppositeContent,
} from '@mui/lab';
import {
  Edit as EditIcon,
  Add as AddIcon,
  Delete as DeleteIcon,
  CheckCircle as ApproveIcon,
} from '@mui/icons-material';

interface AuditEntry {
  id: string;
  timestamp: string;
  user: string;
  action: 'created' | 'updated' | 'deleted' | 'approved' | 'rejected';
  changes?: Array<{ field: string; oldValue: any; newValue: any }>;
  comment?: string;
}

interface AuditTrailProps {
  ruleId: string;
  entries: AuditEntry[];
}

const actionIcons = {
  created: <AddIcon />,
  updated: <EditIcon />,
  deleted: <DeleteIcon />,
  approved: <ApproveIcon />,
  rejected: <DeleteIcon />,
};

const actionColors = {
  created: 'success',
  updated: 'primary',
  deleted: 'error',
  approved: 'success',
  rejected: 'warning',
} as const;

export const AuditTrail: React.FC<AuditTrailProps> = ({ ruleId, entries }) => {
  const formatDate = (timestamp: string) => {
    const date = new Date(timestamp);
    return date.toLocaleString();
  };

  const formatValue = (value: any) => {
    if (typeof value === 'object') {
      return JSON.stringify(value);
    }
    return String(value);
  };

  return (
    <Box>
      <Typography variant="h6" sx={{ fontWeight: 600, mb: 3 }}>
        Change History
      </Typography>

      {entries.length === 0 ? (
        <Paper elevation={0} sx={{ p: 3, bgcolor: 'grey.50', textAlign: 'center' }}>
          <Typography variant="body2" color="text.secondary">
            No change history available
          </Typography>
        </Paper>
      ) : (
        <Timeline position="right">
          {entries.map((entry, index) => (
            <TimelineItem key={entry.id}>
              <TimelineOppositeContent color="text.secondary" sx={{ flex: 0.3 }}>
                <Typography variant="caption">{formatDate(entry.timestamp)}</Typography>
                <Typography variant="caption" sx={{ display: 'block', fontWeight: 600 }}>
                  {entry.user}
                </Typography>
              </TimelineOppositeContent>

              <TimelineSeparator>
                <TimelineDot color={actionColors[entry.action]}>
                  {actionIcons[entry.action]}
                </TimelineDot>
                {index < entries.length - 1 && <TimelineConnector />}
              </TimelineSeparator>

              <TimelineContent>
                <Paper elevation={2} sx={{ p: 2, mb: 2 }}>
                  <Stack spacing={2}>
                    <Stack direction="row" spacing={1} alignItems="center">
                      <Chip
                        label={entry.action.toUpperCase()}
                        size="small"
                        color={actionColors[entry.action]}
                      />
                    </Stack>

                    {entry.comment && (
                      <Typography variant="body2" color="text.secondary">
                        {entry.comment}
                      </Typography>
                    )}

                    {entry.changes && entry.changes.length > 0 && (
                      <Box>
                        <Divider sx={{ my: 1 }} />
                        <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mb: 1 }}>
                          Changes:
                        </Typography>
                        <Stack spacing={1}>
                          {entry.changes.map((change, idx) => (
                            <Paper key={idx} elevation={0} sx={{ p: 1, bgcolor: 'grey.50' }}>
                              <Typography variant="caption" sx={{ fontWeight: 600 }}>
                                {change.field}
                              </Typography>
                              <Stack direction="row" spacing={1} alignItems="center" sx={{ mt: 0.5 }}>
                                <Chip
                                  label={formatValue(change.oldValue) || '(empty)'}
                                  size="small"
                                  variant="outlined"
                                  color="error"
                                />
                                <Typography variant="caption">→</Typography>
                                <Chip
                                  label={formatValue(change.newValue) || '(empty)'}
                                  size="small"
                                  variant="outlined"
                                  color="success"
                                />
                              </Stack>
                            </Paper>
                          ))}
                        </Stack>
                      </Box>
                    )}
                  </Stack>
                </Paper>
              </TimelineContent>
            </TimelineItem>
          ))}
        </Timeline>
      )}
    </Box>
  );
};

export default AuditTrail;

import React, { useState } from 'react';
import {
  Menu,
  MenuItem,
  ListItemIcon,
  ListItemText,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Typography,
  Alert,
} from '@mui/material';
import {
  Delete as DeleteIcon,
  Edit as EditIcon,
  GetApp as ExportIcon,
  CheckCircle as ApproveIcon,
} from '@mui/icons-material';
import { AccessRule, accessRulesApi } from '../../../api/accessRules';

interface BulkActionsMenuProps {
  anchorEl: HTMLElement | null;
  open: boolean;
  onClose: () => void;
  selectedRules: AccessRule[];
  onComplete: () => void;
}

export const BulkActionsMenu: React.FC<BulkActionsMenuProps> = ({
  anchorEl,
  open,
  onClose,
  selectedRules,
  onComplete,
}) => {
  const [confirmDialog, setConfirmDialog] = useState<'delete' | 'approve' | null>(null);
  const [processing, setProcessing] = useState(false);

  const handleExport = () => {
    const dataStr = JSON.stringify(selectedRules, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(dataBlob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `access-rules-${new Date().toISOString().split('T')[0]}.json`;
    link.click();
    URL.revokeObjectURL(url);
    onClose();
  };

  const handleBulkDelete = async () => {
    setProcessing(true);
    try {
      await Promise.all(
        selectedRules.map((rule) => accessRulesApi.delete(rule.ruleId))
      );
      setConfirmDialog(null);
      onComplete();
      onClose();
    } catch (error) {
      console.error('Bulk delete failed:', error);
    } finally {
      setProcessing(false);
    }
  };

  const handleBulkApprove = async () => {
    setProcessing(true);
    try {
      await Promise.all(
        selectedRules.map((rule) =>
          accessRulesApi.update(rule.ruleId, { ...rule, status: 'APPROVED' })
        )
      );
      setConfirmDialog(null);
      onComplete();
      onClose();
    } catch (error) {
      console.error('Bulk approve failed:', error);
    } finally {
      setProcessing(false);
    }
  };

  return (
    <>
      <Menu anchorEl={anchorEl} open={open} onClose={onClose}>
        <MenuItem onClick={handleExport}>
          <ListItemIcon>
            <ExportIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText>Export Selected ({selectedRules.length})</ListItemText>
        </MenuItem>
        <MenuItem onClick={() => setConfirmDialog('approve')}>
          <ListItemIcon>
            <ApproveIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText>Approve Selected</ListItemText>
        </MenuItem>
        <MenuItem onClick={() => setConfirmDialog('delete')}>
          <ListItemIcon>
            <DeleteIcon fontSize="small" color="error" />
          </ListItemIcon>
          <ListItemText>Delete Selected</ListItemText>
        </MenuItem>
      </Menu>

      {/* Delete Confirmation */}
      <Dialog open={confirmDialog === 'delete'} onClose={() => setConfirmDialog(null)}>
        <DialogTitle>Confirm Bulk Delete</DialogTitle>
        <DialogContent>
          <Alert severity="warning" sx={{ mb: 2 }}>
            This action cannot be undone.
          </Alert>
          <Typography>
            Are you sure you want to delete {selectedRules.length} rule(s)?
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setConfirmDialog(null)}>Cancel</Button>
          <Button
            variant="contained"
            color="error"
            onClick={handleBulkDelete}
            disabled={processing}
          >
            {processing ? 'Deleting...' : 'Delete'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Approve Confirmation */}
      <Dialog open={confirmDialog === 'approve'} onClose={() => setConfirmDialog(null)}>
        <DialogTitle>Confirm Bulk Approve</DialogTitle>
        <DialogContent>
          <Typography>
            Are you sure you want to approve {selectedRules.length} rule(s)?
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setConfirmDialog(null)}>Cancel</Button>
          <Button
            variant="contained"
            color="success"
            onClick={handleBulkApprove}
            disabled={processing}
          >
            {processing ? 'Approving...' : 'Approve'}
          </Button>
        </DialogActions>
      </Dialog>
    </>
  );
};

