            ))}
          </List>
        </Paper>
      )}

      {/* Field Restrictions */}
      {impact.fieldsRestricted > 0 && (
        <Alert severity="info" icon={<CheckIcon />}>
          <Typography variant="body2">
            <strong>{impact.fieldsRestricted}</strong> field(s) will be masked or hidden for this group
          </Typography>
        </Alert>
      )}
    </Stack>
  );
};

