              {!loading &&
                filteredRules.map((rule) => (
                  <TableRow key={rule.ruleId} hover>
                    <TableCell>
                      <Typography variant="body2" sx={{ fontWeight: 500 }}>
                        {rule.businessObjectId}
                      </Typography>
                    </TableCell>
                    <TableCell>
                      <Tooltip title={rule.groupDn}>
                        <Typography variant="body2" noWrap sx={{ maxWidth: 200 }}>
                          {rule.groupDn}
                        </Typography>
                      </Tooltip>
                    </TableCell>
                    <TableCell>
                      <Chip
                        label={rule.accessLevel}
                        size="small"
                        color={rule.accessLevel === 'WRITE' ? 'primary' : 'default'}
                      />
                    </TableCell>
                    <TableCell>
                      <Chip
                        label={rule.status}
                        size="small"
                        color={statusColors[rule.status]}
                      />
                    </TableCell>
                    <TableCell>
                      <Typography variant="body2" color="text.secondary">
                        {rule.rowFilterDsl ? '✓ Active' : '—'}
                      </Typography>
                    </TableCell>
                    <TableCell>
                      <Typography variant="body2" color="text.secondary">
                        {rule.columnMasks?.length || 0} fields
                      </Typography>
                    </TableCell>
                    <TableCell align="right">
                      <Tooltip title="Edit Rule">
                        <IconButton
                          size="small"
                          color="primary"
                          onClick={() => navigate(`/security/access-rules/${rule.ruleId}`)}
                        >
                          <EditIcon fontSize="small" />
                        </IconButton>
                      </Tooltip>
                    </TableCell>
                  </TableRow>
                ))}
            </TableBody>
          </Table>
        </TableContainer>
      </Paper>
    </Container>
  );
};

