          <Grid container spacing={2}>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Template Name"
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
            </Grid>

            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Description"
                multiline
                rows={2}
                value={description}
                onChange={(e) => setDescription(e.target.value)}
              />
            </Grid>

            <Grid item xs={6}>
              <TextField
                fullWidth
                label="Datasource"
                value={datasource}
                onChange={(e) => setDatasource(e.target.value)}
              />
            </Grid>

            <Grid item xs={6}>
              <TextField
                fullWidth
                label="Version"
                value={version}
                onChange={(e) => setVersion(e.target.value)}
              />
            </Grid>

            <Grid item xs={6}>
              <FormControl fullWidth>
                <InputLabel>Visibility</InputLabel>
                <Select
                  value={visibility}
                  label="Visibility"
                  onChange={(e) => setVisibility(e.target.value)}
                >
                  <MenuItem value="private">Private</MenuItem>
                  <MenuItem value="team">Team</MenuItem>
                  <MenuItem value="public">Public</MenuItem>
                </Select>
              </FormControl>
            </Grid>
          </Grid>
        </Paper>
      </Grid>

      {/* Semantic Query */}
      <Grid item xs={12}>
        <Paper sx={{ p: 2 }}>
          <Typography variant="h6" sx={{ mb: 1 }}>
            Semantic Query (JSON)
          </Typography>
          <Box sx={{ border: '1px solid #ccc', borderRadius: 1, height: 300 }}>
            <Editor
              height="100%"
              defaultLanguage="json"
              value={semanticQuery}
              onChange={(value) => setSemanticQuery(value || '')}
              options={{ minimap: { enabled: false } }}
            />
          </Box>
        </Paper>
      </Grid>

      {/* Parameters */}
      <Grid item xs={12}>
        <Paper sx={{ p: 2 }}>
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
            <Typography variant="h6">Parameters</Typography>
            <Button size="small" onClick={addParameter}>
              + Add Parameter
            </Button>
          </Box>

          <TableContainer>
            <Table size="small">
              <TableHead>
                <TableRow sx={{ backgroundColor: '#f5f5f5' }}>
                  <TableCell>Name</TableCell>
                  <TableCell>Type</TableCell>
                  <TableCell>Required</TableCell>
                  <TableCell>Default</TableCell>
                  <TableCell>Help</TableCell>
                  <TableCell>Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {parameters.map((param, idx) => (
                  <TableRow key={idx}>
                    <TableCell>
                      <TextField
                        size="small"
                        value={param.name}
                        onChange={(e) => updateParameter(idx, { name: e.target.value })}
                      />
                    </TableCell>
                    <TableCell>
                      <Select
                        size="small"
                        value={param.type}
                        onChange={(e) => updateParameter(idx, { type: e.target.value as any })}
                      >
                        <MenuItem value="string">string</MenuItem>
                        <MenuItem value="number">number</MenuItem>
                        <MenuItem value="bool">bool</MenuItem>
                      </Select>
                    </TableCell>
                    <TableCell>
                      <Checkbox
                        checked={param.required}
                        onChange={(e) => updateParameter(idx, { required: e.target.checked })}
                      />
                    </TableCell>
                    <TableCell>
                      <TextField
                        size="small"
                        value={param.default || ''}
                        onChange={(e) => updateParameter(idx, { default: e.target.value })}
                      />
                    </TableCell>
                    <TableCell>
                      <TextField
                        size="small"
                        value={param.help || ''}
                        onChange={(e) => updateParameter(idx, { help: e.target.value })}
                      />
                    </TableCell>
                    <TableCell>
                      <IconButton
                        size="small"
                        onClick={() => removeParameter(idx)}
                      >
                        <DeleteIcon fontSize="small" />
                      </IconButton>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        </Paper>
      </Grid>

      {/* Change Message (for versioning) */}
      {template && (
        <Grid item xs={12}>
          <TextField
            fullWidth
            label="Change Message"
            placeholder="Describe what changed in this version"
            value={changeMessage}
            onChange={(e) => setChangeMessage(e.target.value)}
            multiline
            rows={2}
          />
        </Grid>
      )}

      {/* Save Button */}
      <Grid item xs={12}>
        <Button variant="contained" onClick={handleSave} fullWidth>
          {template ? 'Update Template' : 'Create Template'}
        </Button>
      </Grid>
    </Grid>
  );
};

// ============================================================================
// TemplateRunner - Execute Template with Parameters
// ============================================================================

interface TemplateRunnerProps {
  template: SemanticQueryTemplate;
  onClose: () => void;
}

const TemplateRunner: React.FC<TemplateRunnerProps> = ({ template, onClose }) => {
  const [paramValues, setParamValues] = useState<Record<string, any>>({});
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<TemplateRunResponse | null>(null);
  const [sqlViewerOpen, setSqlViewerOpen] = useState(false);

  const handleRun = async () => {
    setLoading(true);
    try {
      const response = await templateApi.runTemplate(template.id, paramValues);
      setResult(response);
    } catch (error) {
      console.error('Failed to run template:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open onClose={onClose} maxWidth="lg" fullWidth>
      <Box sx={{ p: 3 }}>
        <Typography variant="h5" sx={{ mb: 2 }}>
          Run: {template.name}
        </Typography>

        {!result ? (
          <Box>
            <ParameterEditor
              parameters={template.parameters}
              values={paramValues}
              onChange={setParamValues}
            />

            <Box sx={{ mt: 3, display: 'flex', gap: 1 }}>
              <Button variant="contained" onClick={handleRun} disabled={loading}>
                {loading ? 'Executing...' : 'Execute'}
              </Button>
              <Button variant="outlined" onClick={onClose}>
                Cancel
              </Button>
            </Box>
          </Box>
        ) : (
          <Box>
            <Alert severity="success" sx={{ mb: 2 }}>
              Query executed successfully in {result.duration_ms}ms - {result.count} rows
            </Alert>

            <Box sx={{ mb: 2 }}>
              <Button
                variant="outlined"
                size="small"
                onClick={() => setSqlViewerOpen(!sqlViewerOpen)}
              >
                {sqlViewerOpen ? 'Hide' : 'Show'} SQL
              </Button>
            </Box>

            {sqlViewerOpen && (
              <Paper sx={{ p: 2, mb: 2, backgroundColor: '#f5f5f5' }}>
                <Typography variant="body2" sx={{ fontFamily: 'monospace', whiteSpace: 'pre-wrap' }}>
                  {result.sql}
                </Typography>
              </Paper>
            )}

            <Typography variant="subtitle2" sx={{ mb: 1 }}>
              Results ({result.count} rows)
            </Typography>

            <TableContainer sx={{ maxHeight: 400 }}>
              <Table size="small">
                <TableHead>
                  <TableRow sx={{ backgroundColor: '#f5f5f5' }}>
                    {result.rows.length > 0 &&
                      Object.keys(result.rows[0]).map((col) => (
                        <TableCell key={col}>{col}</TableCell>
                      ))}
                  </TableRow>
                </TableHead>
                <TableBody>
                  {result.rows.map((row, idx) => (
                    <TableRow key={idx}>
                      {Object.values(row).map((cell, cidx) => (
                        <TableCell key={cidx}>{String(cell)}</TableCell>
                      ))}
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Box>
        )}
      </Box>
    </Dialog>
  );
};

