  Add,
  Refresh,
  Edit,
  FilterList,
  PlayArrow,
  Schema as SchemaIcon,
  Visibility as VisibilityIcon,
  DeleteOutline,
  Sync,
} from '@mui/icons-material';
import { ConnectionTestDialog } from '../../connections/components/ConnectionTestDialog';
import ScanProgressModal from './ScanProgressModal';
