export interface Connection {
  id: string;
  name: string;
  type: string;
  endpoint: string;
  linkedInstance?: string;
  linkedInstanceId?: string;
  linkedProduct?: string;
  linkedProductId?: string;
  linkedDatasourceId?: string;
  linkedAlphaDatasourceId?: string;
  lastSync?: string;
  status: 'connected' | 'warning' | 'error';
  // Raw data from API
  host?: string;
  port?: number;
  database?: string;
  schema?: string;
  username?: string;
  password?: string;
  base_url?: string;
  api_key?: string;
  metadata?: Record<string, any>;
  is_active?: boolean;
}

interface ConnectionsTabContentProps {
  tenantId: string;
  datasourceId: string;
  instanceFilter?: string[] | null;
  productFilter?: string[] | null;
  isGoldCopy?: boolean;
  onAddConnection?: () => void;
  onEditConnection?: (connection: Connection) => void;
  tenantData?: any;
}

// GraphQL Queries
const GET_TENANT_CONNECTIONS = gql`
  query GetTenantConnections($tenantId: uuid!) {
    connections(where: { tenant_id: { _eq: $tenantId } }) {
      id
      name
      type
      host
      port
      database
      schema
      username
      password
      is_active
      created_at
      updated_at
      metadata
    }
  }
`;

// Query to get product and instance info linked to connections via tenant_product_datasources
const GET_CONNECTION_RELATIONSHIPS = gql`
  query GetConnectionRelationships($tenantId: uuid!) {
    tenant_product_datasource(
      where: {
        tenant_product: { tenant_id: { _eq: $tenantId } }
      }
    ) {
      id
      connection_id
      last_scan_at
      tenant_instance {
        id
        instance_name
        display_name
      }
      tenant_product {
        id
        tenant_id
        alpha_product {
          id
          product_name
        }
      }
    }
  }
`;

// GraphQL Mutations

const getStatusColor = (status: string) => {
  switch (status) {
    case 'connected':
    case 'success':
      return 'success';
    case 'warning':
      return 'warning';
    case 'error':
    case 'failed':
      return 'error';
    default:
      return 'default';
  }
};

const getStatusLabel = (status: string) => {
  switch (status) {
    case 'connected':
    case 'success':
      return 'Connected';
    case 'warning':
      return 'Warning';
    case 'error':
    case 'failed':
      return 'Error';
    default:
      return 'Unknown';
  }
};

const getTypeIcon = (type: string) => {
  switch (type?.toLowerCase()) {
    case 'postgres':
    case 'mysql':
    case 'database':
      return '🗄️';
    case 'api':
    case 'rest':
      return '☁️';
    case 'storage':
    case 's3':
      return '📦';
    case 'snowflake':
      return '❄️';
    default:
      return '🔌';
  }
};

const getTypeLabel = (type: string) => {
  switch (type?.toLowerCase()) {
    case 'postgres':
      return 'PostgreSQL';
    case 'mysql':
      return 'MySQL';
    case 'snowflake':
      return 'Snowflake';
    case 'api':
    case 'rest':
      return 'REST API';
    case 'storage':
    case 's3':
