                <MenuItem value="mysql">MySQL</MenuItem>
                <MenuItem value="snowflake">Snowflake</MenuItem>
                <MenuItem value="api">REST API</MenuItem>
                <MenuItem value="s3">S3 Storage</MenuItem>
                <MenuItem value="azure">Azure Storage</MenuItem>
