                <MenuItem value="bearer">Bearer Token</MenuItem>
                <MenuItem value="api_key">API Key</MenuItem>
                <MenuItem value="oauth">OAuth 2.0</MenuItem>
                <MenuItem value="key_pair">Key Pair (SSH/TLS)</MenuItem>
