                            fullWidth
                            size="small"
                            value={formData.fieldName || ''}
                            onChange={(e) => handleChange('fieldName', e.target.value)}
                        >
                            {boFields.map((f: any) => (
                                <MenuItem key={f.name} value={f.name}>{f.label} ({f.data_type})</MenuItem>
