                        <Alert severity="success" icon={<LinkIcon />} sx={{ fontSize: '0.75rem' }}>
                            Validates referential integrity against the central catalog.
                        </Alert>
                    </>
                )}

                {/* 6. Formula */}
                {filterType === 'Formula' && (
                    <TextField 
