  ytd_tax_loss_harvested: number;
  ytd_tax_savings: number;
  ytd_return_pct: number;
  ytd_benchmark_return_pct: number;
  tracking_error_pct: number;
}

interface HarvestOpportunity {
  opportunity_id: string;
  ticker: string;
  shares_to_sell: number;
  current_price: number;
  unrealized_loss: number;
  unrealized_loss_pct: number;
  estimated_tax_savings: number;
  replacement_ticker: string;
  replacement_name: string;
  correlation_with_original: number;
  wash_sale_risk: boolean;
  detected_at: string;
}

export const DirectIndexingDashboard: React.FC = () => {
  const [accounts, setAccounts] = useState<DirectIndexAccount[]>([]);
  const [selectedAccount, setSelectedAccount] = useState<DirectIndexAccount | null>(null);
  const [opportunities, setOpportunities] = useState<HarvestOpportunity[]>([]);
  const [loading, setLoading] = useState(true);
  const [executeDialogOpen, setExecuteDialogOpen] = useState(false);
  const [selectedOpp, setSelectedOpp] = useState<HarvestOpportunity | null>(null);
  const [tabValue, setTabValue] = useState(0);

  useEffect(() => {
    fetchAccounts();
  }, []);

  useEffect(() => {
    if (selectedAccount) {
      fetchOpportunities(selectedAccount.account_id);
    }
  }, [selectedAccount]);

  const fetchAccounts = async () => {
    try {
      const clientId = localStorage.getItem('client_id'); // Get from auth context
      const response = await fetch(`/api/direct-indexing/accounts?client_id=${clientId}`);
      const data = await response.json();
      setAccounts(data.accounts || []);
      if (data.accounts && data.accounts.length > 0) {
        setSelectedAccount(data.accounts[0]);
      }
    } catch (error) {
      console.error('Failed to fetch accounts:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchOpportunities = async (accountId: string) => {
    try {
      const response = await fetch(`/api/direct-indexing/accounts/${accountId}/opportunities?status=PENDING`);
      const data = await response.json();
      setOpportunities(data.opportunities || []);
    } catch (error) {
      console.error('Failed to fetch opportunities:', error);
    }
  };

  const handleExecute = async (opportunity: HarvestOpportunity) => {
    setSelectedOpp(opportunity);
    setExecuteDialogOpen(true);
  };

  const confirmExecute = async () => {
    if (!selectedOpp) return;

    try {
      const userId = localStorage.getItem('user_id');
      await fetch(`/api/direct-indexing/opportunities/${selectedOpp.opportunity_id}/execute`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ approved_by: userId }),
      });

      // Refresh opportunities
      if (selectedAccount) {
        await fetchOpportunities(selectedAccount.account_id);
        await fetchAccounts(); // Refresh account metrics
      }

      setExecuteDialogOpen(false);
      setSelectedOpp(null);
    } catch (error) {
      console.error('Failed to execute harvest:', error);
    }
  };

  const handleDismiss = async (opportunityId: string) => {
    try {
      await fetch(`/api/direct-indexing/opportunities/${opportunityId}/dismiss`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reason: 'NOT_RELEVANT' }),
      });

      // Refresh opportunities
      if (selectedAccount) {
        await fetchOpportunities(selectedAccount.account_id);
      }
    } catch (error) {
      console.error('Failed to dismiss opportunity:', error);
    }
  };

  if (loading) {
    return <LinearProgress />;
  }

  const totalPotentialSavings = opportunities.reduce((sum, opp) => sum + opp.estimated_tax_savings, 0);

  return (
    <Box sx={{ p: 3 }}>
      {/* Header */}
      <Typography variant="h4" gutterBottom>
        Direct Indexing & Tax-Loss Harvesting
      </Typography>
      <Typography variant="body2" color="text.secondary" gutterBottom>
        Automated tax optimization delivering 1.2-2.5% annual tax alpha
      </Typography>

      {/* Account Selector */}
      {accounts.length > 1 && (
        <Paper sx={{ mb: 3 }}>
          <Tabs value={tabValue} onChange={(_, v) => {
            setTabValue(v);
            setSelectedAccount(accounts[v]);
          }}>
            {accounts.map((acc, idx) => (
              <Tab key={acc.account_id} label={acc.account_name} />
            ))}
          </Tabs>
        </Paper>
      )}

      {selectedAccount && (
        <>
          {/* Stats Cards */}
          <Grid container spacing={3} sx={{ mb: 4 }}>
            <Grid item xs={12} sm={6} md={3}>
              <Card>
                <CardContent>
                  <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                    <MoneyIcon color="primary" sx={{ mr: 1 }} />
                    <Typography variant="h6">
                      ${selectedAccount.total_market_value.toLocaleString()}
                    </Typography>
                  </Box>
                  <Typography variant="body2" color="text.secondary">
                    Account Value
                  </Typography>
                </CardContent>
              </Card>
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <Card>
                <CardContent>
                  <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                    <LossIcon color="success" sx={{ mr: 1 }} />
                    <Typography variant="h6">
                      ${selectedAccount.ytd_tax_loss_harvested.toLocaleString()}
                    </Typography>
                  </Box>
                  <Typography variant="body2" color="text.secondary">
                    YTD Losses Harvested
                  </Typography>
                </CardContent>
              </Card>
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <Card>
                <CardContent>
                  <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                    <SuccessIcon color="success" sx={{ mr: 1 }} />
                    <Typography variant="h6">
                      ${selectedAccount.ytd_tax_savings.toLocaleString()}
                    </Typography>
                  </Box>
                  <Typography variant="body2" color="text.secondary">
                    YTD Tax Savings
                  </Typography>
                </CardContent>
              </Card>
            </Grid>

            <Grid item xs={12} sm={6} md={3}>
              <Card>
                <CardContent>
                  <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                    <Typography variant="h6">
                      {selectedAccount.ytd_return_pct?.toFixed(2) || 'N/A'}%
                    </Typography>
                  </Box>
                  <Typography variant="body2" color="text.secondary">
                    YTD Return vs {selectedAccount.ytd_benchmark_return_pct?.toFixed(2)}% Benchmark
                  </Typography>
                  {selectedAccount.tracking_error_pct && (
                    <Typography variant="caption" color="text.secondary">
                      Tracking Error: {selectedAccount.tracking_error_pct.toFixed(2)}%
                    </Typography>
                  )}
                </CardContent>
              </Card>
            </Grid>
          </Grid>

          {/* Opportunities Alert */}
          {opportunities.length > 0 && (
            <Alert severity="info" sx={{ mb: 3 }}>
              <Typography variant="subtitle1">
                {opportunities.length} Tax-Loss Harvesting Opportunities Detected
              </Typography>
              <Typography variant="body2">
                Potential tax savings: ${totalPotentialSavings.toLocaleString()}
              </Typography>
            </Alert>
          )}

          {/* Opportunities Table */}
          <Paper>
            <Box sx={{ p: 2 }}>
              <Typography variant="h6" gutterBottom>
                Pending Harvest Opportunities
              </Typography>
            </Box>

            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>Ticker</TableCell>
                    <TableCell align="right">Shares</TableCell>
                    <TableCell align="right">Current Price</TableCell>
                    <TableCell align="right">Unrealized Loss</TableCell>
                    <TableCell align="right">Loss %</TableCell>
                    <TableCell align="right">Tax Savings</TableCell>
                    <TableCell>Replacement</TableCell>
                    <TableCell align="center">Action</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {opportunities.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={8} align="center">
                        <Box sx={{ py: 4 }}>
                          <SuccessIcon color="success" sx={{ fontSize: 48, mb: 1 }} />
                          <Typography variant="h6">All Caught Up!</Typography>
                          <Typography variant="body2" color="text.secondary">
                            No harvest opportunities detected. System scans daily at 4 PM ET.
                          </Typography>
                        </Box>
                      </TableCell>
                    </TableRow>
                  ) : (
                    opportunities.map((opp) => (
                      <TableRow key={opp.opportunity_id} hover>
                        <TableCell>
                          <Box sx={{ display: 'flex', alignItems: 'center' }}>
                            <strong>{opp.ticker}</strong>
                            {opp.wash_sale_risk && (
                              <Chip 
                                label="Wash Sale Risk" 
                                color="warning" 
                                size="small" 
                                sx={{ ml: 1 }}
                                icon={<WarningIcon />}
                              />
                            )}
                          </Box>
                        </TableCell>
                        <TableCell align="right">{opp.shares_to_sell.toFixed(2)}</TableCell>
                        <TableCell align="right">${opp.current_price.toFixed(2)}</TableCell>
                        <TableCell align="right" sx={{ color: 'error.main' }}>
                          ${Math.abs(opp.unrealized_loss).toLocaleString()}
                        </TableCell>
                        <TableCell align="right" sx={{ color: 'error.main' }}>
                          {opp.unrealized_loss_pct.toFixed(2)}%
                        </TableCell>
                        <TableCell align="right" sx={{ color: 'success.main', fontWeight: 'bold' }}>
                          ${opp.estimated_tax_savings.toLocaleString()}
                        </TableCell>
                        <TableCell>
                          <Box>
                            <Typography variant="body2">
                              <strong>{opp.replacement_ticker}</strong>
                            </Typography>
                            <Typography variant="caption" color="text.secondary">
                              {opp.replacement_name}
                            </Typography>
                            {opp.correlation_with_original && (
                              <Typography variant="caption" display="block" color="text.secondary">
                                Correlation: {(opp.correlation_with_original * 100).toFixed(1)}%
                              </Typography>
                            )}
                          </Box>
                        </TableCell>
                        <TableCell align="center">
                          <Box sx={{ display: 'flex', gap: 1, justifyContent: 'center' }}>
                            <Button
                              variant="contained"
                              color="primary"
                              size="small"
                              onClick={() => handleExecute(opp)}
                              disabled={opp.wash_sale_risk}
                            >
                              Execute
                            </Button>
                            <Button
                              variant="outlined"
                              color="secondary"
                              size="small"
                              onClick={() => handleDismiss(opp.opportunity_id)}
                            >
                              Dismiss
                            </Button>
                          </Box>
                        </TableCell>
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>
        </>
      )}

      {/* Execute Confirmation Dialog */}
      <Dialog open={executeDialogOpen} onClose={() => setExecuteDialogOpen(false)} maxWidth="sm" fullWidth>
        {selectedOpp && (
          <>
            <DialogTitle>Confirm Tax-Loss Harvest</DialogTitle>
            <DialogContent>
              <Alert severity="info" sx={{ mb: 2 }}>
                This will execute the following trades:
              </Alert>

              <Grid container spacing={2}>
                <Grid item xs={6}>
                  <Typography variant="subtitle2">SELL</Typography>
                  <Typography variant="body2">
                    {selectedOpp.shares_to_sell.toFixed(2)} shares of {selectedOpp.ticker}
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    @ ${selectedOpp.current_price.toFixed(2)}
                  </Typography>
                </Grid>

                <Grid item xs={6}>
                  <Typography variant="subtitle2">BUY</Typography>
                  <Typography variant="body2">
                    {selectedOpp.shares_to_sell.toFixed(2)} shares of {selectedOpp.replacement_ticker}
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    {selectedOpp.replacement_name}
                  </Typography>
                </Grid>
              </Grid>

              <Box sx={{ mt: 3, p: 2, bgcolor: 'success.light', borderRadius: 1 }}>
                <Typography variant="h6" color="success.dark">
                  Estimated Tax Savings: ${selectedOpp.estimated_tax_savings.toLocaleString()}
                </Typography>
                <Typography variant="body2" color="success.dark">
                  Realized Loss: ${Math.abs(selectedOpp.unrealized_loss).toLocaleString()}
                </Typography>
              </Box>

              <Alert severity="warning" sx={{ mt: 2 }}>
                A 30-day wash sale window will be created for {selectedOpp.ticker}
              </Alert>
            </DialogContent>
            <DialogActions>
              <Button onClick={() => setExecuteDialogOpen(false)}>Cancel</Button>
              <Button onClick={confirmExecute} variant="contained" color="primary">
                Confirm Execute
              </Button>
            </DialogActions>
          </>
        )}
      </Dialog>
    </Box>
  );
};

import React, { useState, useEffect } from 'react';
import {
  Box,
  Grid,
  Card,
  CardContent,
  Typography,
  LinearProgress,
  Chip,
  Alert,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Tabs,
  Tab,
} from '@mui/material';
import {
  Eco as EcoIcon,
  People as SocialIcon,
  Business as GovernanceIcon,
  Warning as WarningIcon,
} from '@mui/icons-material';
import { RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Cell } from 'recharts';

interface ESGMetrics {
  weighted_esg_score: number;
  weighted_environmental_score: number;
  weighted_social_score: number;
  weighted_governance_score: number;
  carbon_intensity: number;
  esg_coverage_pct: number;
  vs_benchmark_esg_score: number;
  vs_benchmark_carbon: number;
  paris_aligned: boolean;
}

interface SDGImpact {
  sdg_number: number;
  sdg_name: string;
  allocation_pct: number;
  invested_amount: number;
}

interface Violation {
  violation_id: string;
  ticker: string;
  violation_type: string;
  violation_description: string;
  severity: string;
  market_value: number;
  recommended_action: string;
}

const SDG_COLORS = ['#E5243B', '#DDA63A', '#4C9F38', '#C5192D', '#FF3A21', '#26BDE2', '#FCC30B', '#A21942', '#FD6925', '#DD1367', '#FD9D24', '#BF8B2E', '#3F7E44', '#0A97D9', '#56C02B', '#00689D', '#19486A'];

export const ESGDashboard: React.FC = () => {
  const [metrics, setMetrics] = useState<ESGMetrics | null>(null);
  const [sdgImpacts, setSdgImpacts] = useState<SDGImpact[]>([]);
  const [violations, setViolations] = useState<Violation[]>([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState(0);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const [metricsRes, sdgRes, violationsRes] = await Promise.all([
        fetch('/api/esg/portfolio-metrics'),
        fetch('/api/esg/sdg-impact'),
        fetch('/api/esg/violations?status=OPEN'),
      ]);

      const metricsData = await metricsRes.json();
      const sdgData = await sdgRes.json();
      const violationsData = await violationsRes.json();

      setMetrics(metricsData);
      setSdgImpacts(sdgData.impacts || []);
      setViolations(violationsData.violations || []);
    } catch (error) {
      console.error('Failed to fetch ESG data:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <LinearProgress />;
  }

  if (!metrics) {
    return <Alert severity="info">No ESG data available</Alert>;
  }

  // Prepare radar chart data
  const radarData = [
    { factor: 'Environmental', score: metrics.weighted_environmental_score, fullMark: 100 },
    { factor: 'Social', score: metrics.weighted_social_score, fullMark: 100 },
    { factor: 'Governance', score: metrics.weighted_governance_score, fullMark: 100 },
  ];

  const getScoreColor = (score: number) => {
    if (score >= 70) return 'success';
    if (score >= 50) return 'warning';
    return 'error';
  };

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'CRITICAL': return 'error';
      case 'HIGH': return 'error';
      case 'MEDIUM': return 'warning';
      default: return 'info';
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        ESG & Impact Investing
      </Typography>

      {/* Violations Alert */}
      {violations.length > 0 && (
        <Alert severity="warning" icon={<WarningIcon />} sx={{ mb: 3 }}>
          <Typography variant="subtitle2">
            {violations.length} ESG screening violation{violations.length > 1 ? 's' : ''} requiring attention
          </Typography>
        </Alert>
      )}

      {/* ESG Score Cards */}
      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                <EcoIcon color="success" sx={{ mr: 1 }} />
                <Typography color="text.secondary">ESG Score</Typography>
              </Box>
              <Typography variant="h4">{metrics.weighted_esg_score.toFixed(1)}</Typography>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mt: 1 }}>
                <Chip
                  label={`vs Benchmark: ${metrics.vs_benchmark_esg_score > 0 ? '+' : ''}${metrics.vs_benchmark_esg_score.toFixed(1)}`}
                  size="small"
                  color={metrics.vs_benchmark_esg_score > 0 ? 'success' : 'error'}
                />
              </Box>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Typography color="text.secondary" gutterBottom>
                Environmental
              </Typography>
              <Typography variant="h4" color="success.main">
                {metrics.weighted_environmental_score.toFixed(1)}
              </Typography>
              <LinearProgress
                variant="determinate"
                value={metrics.weighted_environmental_score}
                color="success"
                sx={{ mt: 1 }}
              />
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Typography color="text.secondary" gutterBottom>
                Social
              </Typography>
              <Typography variant="h4" color="info.main">
                {metrics.weighted_social_score.toFixed(1)}
              </Typography>
              <LinearProgress
                variant="determinate"
                value={metrics.weighted_social_score}
                color="info"
                sx={{ mt: 1 }}
              />
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} md={3}>
          <Card>
            <CardContent>
              <Typography color="text.secondary" gutterBottom>
                Governance
              </Typography>
              <Typography variant="h4" color="primary.main">
                {metrics.weighted_governance_score.toFixed(1)}
              </Typography>
              <LinearProgress
                variant="determinate"
                value={metrics.weighted_governance_score}
                color="primary"
                sx={{ mt: 1 }}
              />
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Carbon Metrics */}
      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Carbon Footprint
              </Typography>
              <Typography variant="h3" color="text.secondary">
                {metrics.carbon_intensity.toFixed(1)}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Tons CO2e per $1M invested
              </Typography>
              <Box sx={{ mt: 2 }}>
                <Chip
                  label={metrics.paris_aligned ? 'Paris Aligned' : 'Not Paris Aligned'}
                  color={metrics.paris_aligned ? 'success' : 'warning'}
                  size="small"
                />
                <Chip
                  label={`vs Benchmark: ${metrics.vs_benchmark_carbon > 0 ? '+' : ''}${metrics.vs_benchmark_carbon.toFixed(1)}%`}
                  color={metrics.vs_benchmark_carbon < 0 ? 'success' : 'error'}
                  size="small"
                  sx={{ ml: 1 }}
                />
              </Box>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                ESG Profile
              </Typography>
              <ResponsiveContainer width="100%" height={200}>
                <RadarChart data={radarData}>
                  <PolarGrid />
                  <PolarAngleAxis dataKey="factor" />
                  <PolarRadiusAxis angle={90} domain={[0, 100]} />
                  <Radar name="Score" dataKey="score" stroke="#1976d2" fill="#1976d2" fillOpacity={0.6} />
                </RadarChart>
              </ResponsiveContainer>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Tabs */}
      <Box sx={{ borderBottom: 1, borderColor: 'divider', mb: 3 }}>
        <Tabs value={tab} onChange={(_, v) => setTab(v)}>
          <Tab label="SDG Impact" />
          <Tab label={`Violations (${violations.length})`} />
        </Tabs>
      </Box>

      {/* SDG Impact Tab */}
      {tab === 0 && (
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <Paper sx={{ p: 3 }}>
              <Typography variant="h6" gutterBottom>
                UN Sustainable Development Goals Alignment
              </Typography>
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={sdgImpacts}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="sdg_number" label={{ value: 'SDG #', position: 'insideBottom', offset: -5 }} />
                  <YAxis label={{ value: '% of Portfolio', angle: -90, position: 'insideLeft' }} />
                  <Tooltip
                    content={({ active, payload }) => {
                      if (active && payload && payload.length) {
                        const data = payload[0].payload as SDGImpact;
                        return (
                          <Paper sx={{ p: 1 }}>
                            <Typography variant="body2" fontWeight="bold">SDG {data.sdg_number}</Typography>
                            <Typography variant="caption">{data.sdg_name}</Typography>
                            <Typography variant="body2">{data.allocation_pct.toFixed(1)}%</Typography>
                          </Paper>
                        );
                      }
                      return null;
                    }}
                  />
                  <Bar dataKey="allocation_pct">
                    {sdgImpacts.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={SDG_COLORS[entry.sdg_number - 1]} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </Paper>
          </Grid>
        </Grid>
      )}

      {/* Violations Tab */}
      {tab === 1 && (
        <TableContainer component={Paper}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>Ticker</TableCell>
                <TableCell>Violation</TableCell>
                <TableCell>Severity</TableCell>
                <TableCell align="right">Market Value</TableCell>
                <TableCell>Recommended Action</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {violations.map((violation) => (
                <TableRow key={violation.violation_id}>
                  <TableCell>{violation.ticker}</TableCell>
                  <TableCell>
                    <Typography variant="body2" fontWeight="medium">
                      {violation.violation_type.replace('_', ' ')}
                    </Typography>
                    <Typography variant="caption" color="text.secondary">
                      {violation.violation_description}
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={violation.severity}
                      size="small"
                      color={getSeverityColor(violation.severity)}
                    />
                  </TableCell>
                  <TableCell align="right">
                    ${violation.market_value.toLocaleString()}
                  </TableCell>
                  <TableCell>
                    <Chip label={violation.recommended_action} size="small" variant="outlined" />
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    </Box>
  );
};

