  CheckCircle,
  AlertCircle,
  XCircle,
  Clock,
  Plus,
  Play,
  Settings,
  TrendingUp,
  DollarSign,
  Shield,
  Zap,
} from 'lucide-react';
import { useTenant } from '../contexts/TenantContext';
import InvestmentValidationEngine, {
  ValidationContext,
  ValidationExecutionResult,
  RuleSeverity,
  getComplianceStatus,
