import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  Box,
  Paper,
  Typography,
  Button,
  TextField,
  Grid,
  Chip,
  CircularProgress,
  Alert,
  Divider,
  IconButton,
  Tabs,
  Tab
} from '@mui/material';
import {
  Check as CheckIcon,
  Close as CloseIcon,
  Refresh as RefreshIcon,
  Code as CodeIcon,
  Psychology as PsychologyIcon,
  AccountTree as AccountTreeIcon
} from '@mui/icons-material';
import { useTenant } from '../contexts/TenantContext';
import { Light as SyntaxHighlighter } from 'react-syntax-highlighter';
import { atomOneDark } from 'react-syntax-highlighter/dist/esm/styles/hljs';

interface MigrationJob {
  id: string;
  name: string;
  status: string;
  sourceCode: string;
  sourceLanguage: string;
  extractedIntent?: {
    summary?: string;
    preconditions?: Array<{ description: string }>;
    actions?: Array<{ description: string }>;
  };
  generatedDag?: object;
  generatedRego?: string;
  reviewNotes?: string;
  createdAt: string;
}

const MigrationReviewPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { tenant } = useTenant();

  const [migration, setMigration] = useState<MigrationJob | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [reviewNotes, setReviewNotes] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [rightPanelTab, setRightPanelTab] = useState(0);

  const fetchMigration = async () => {
    if (!id) return;

    setLoading(true);
    try {
      const res = await fetch(`/api/migrations/${id}`, {
        headers: {
          ...(tenant?.id && { 'X-Tenant-ID': tenant.id }),
        },
      });

      if (!res.ok) throw new Error('Failed to fetch migration');

      const data = await res.json();
      setMigration(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchMigration();
  }, [id, tenant?.id]);

  const handleApprove = async () => {
    if (!id) return;
    setSubmitting(true);

    try {
      const res = await fetch(`/api/migrations/${id}/approve`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(tenant?.id && { 'X-Tenant-ID': tenant.id }),
        },
        body: JSON.stringify({ notes: reviewNotes }),
      });

      if (!res.ok) throw new Error('Failed to approve');

      navigate('/migrations');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Approval failed');
    } finally {
      setSubmitting(false);
    }
  };

  const handleReject = async () => {
    if (!id) return;
    setSubmitting(true);

    try {
      const res = await fetch(`/api/migrations/${id}/reject`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(tenant?.id && { 'X-Tenant-ID': tenant.id }),
        },
        body: JSON.stringify({ notes: reviewNotes }),
      });

      if (!res.ok) throw new Error('Failed to reject');

      navigate('/migrations');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Rejection failed');
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh' }}>
        <CircularProgress />
      </Box>
    );
  }

  if (error || !migration) {
    return (
      <Box sx={{ p: 3 }}>
        <Alert severity="error">{error || 'Migration not found'}</Alert>
      </Box>
    );
  }

  const statusColor = {
    PENDING: 'default',
    ANALYZING: 'info',
    EXTRACTED: 'info',
    GENERATING: 'info',
    REVIEW: 'warning',
    APPROVED: 'success',
    REJECTED: 'error',
  }[migration.status] || 'default';

  return (
    <Box sx={{ p: 3, height: 'calc(100vh - 64px)', display: 'flex', flexDirection: 'column' }}>
      {/* Header */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Box>
          <Typography variant="h5">{migration.name}</Typography>
          <Box sx={{ display: 'flex', gap: 1, alignItems: 'center', mt: 0.5 }}>
            <Chip label={migration.status} color={statusColor as any} size="small" />
            <Chip label={migration.sourceLanguage.toUpperCase()} variant="outlined" size="small" />
          </Box>
        </Box>
        <Box sx={{ display: 'flex', gap: 1 }}>
          <IconButton onClick={fetchMigration}>
            <RefreshIcon />
          </IconButton>
        </Box>
      </Box>

      {/* Three-Panel Layout */}
      <Grid container spacing={2} sx={{ flex: 1, minHeight: 0 }}>
        {/* Left Panel: Source Code */}
        <Grid item xs={4}>
          <Paper sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
            <Box sx={{ p: 1.5, borderBottom: 1, borderColor: 'divider', display: 'flex', alignItems: 'center', gap: 1 }}>
              <CodeIcon fontSize="small" />
              <Typography variant="subtitle2">Legacy Code</Typography>
            </Box>
            <Box sx={{ flex: 1, overflow: 'auto' }}>
              <SyntaxHighlighter
                language={migration.sourceLanguage}
                style={atomOneDark}
                customStyle={{ margin: 0, height: '100%', fontSize: '12px' }}
              >
                {migration.sourceCode}
              </SyntaxHighlighter>
            </Box>
          </Paper>
        </Grid>

        {/* Center Panel: Extracted Intent */}
        <Grid item xs={4}>
          <Paper sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
            <Box sx={{ p: 1.5, borderBottom: 1, borderColor: 'divider', display: 'flex', alignItems: 'center', gap: 1 }}>
              <PsychologyIcon fontSize="small" />
              <Typography variant="subtitle2">Business Intent (AI Extracted)</Typography>
            </Box>
            <Box sx={{ flex: 1, overflow: 'auto', p: 2 }}>
              {migration.extractedIntent ? (
                <>
                  <Typography variant="h6" gutterBottom>
                    {migration.extractedIntent.summary}
                  </Typography>

                  {migration.extractedIntent.preconditions?.length > 0 && (
                    <>
                      <Typography variant="subtitle2" color="primary" sx={{ mt: 2 }}>
                        Preconditions
                      </Typography>
                      <ul>
                        {migration.extractedIntent.preconditions.map((p, i) => (
                          <li key={i}><Typography variant="body2">{p.description}</Typography></li>
                        ))}
                      </ul>
                    </>
                  )}

                  {migration.extractedIntent.actions?.length > 0 && (
                    <>
                      <Typography variant="subtitle2" color="secondary" sx={{ mt: 2 }}>
                        Actions
                      </Typography>
                      <ul>
                        {migration.extractedIntent.actions.map((a, i) => (
                          <li key={i}><Typography variant="body2">{a.description}</Typography></li>
                        ))}
                      </ul>
                    </>
                  )}
                </>
              ) : (
                <Alert severity="info">Intent extraction pending...</Alert>
              )}
            </Box>
          </Paper>
        </Grid>

        {/* Right Panel: Generated Config */}
        <Grid item xs={4}>
          <Paper sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
            <Box sx={{ p: 1.5, borderBottom: 1, borderColor: 'divider', display: 'flex', alignItems: 'center', gap: 1 }}>
              <AccountTreeIcon fontSize="small" />
              <Typography variant="subtitle2">Titan Configuration</Typography>
            </Box>

            <Tabs value={rightPanelTab} onChange={(_, v) => setRightPanelTab(v)} sx={{ borderBottom: 1, borderColor: 'divider' }}>
              <Tab label="DAG JSON" />
              <Tab label="OPA Rego" disabled={!migration.generatedRego} />
            </Tabs>

            <Box sx={{ flex: 1, overflow: 'auto' }}>
              {rightPanelTab === 0 && (
                <SyntaxHighlighter
                  language="json"
                  style={atomOneDark}
                  customStyle={{ margin: 0, height: '100%', fontSize: '12px' }}
                >
                  {migration.generatedDag ? JSON.stringify(migration.generatedDag, null, 2) : '// No DAG generated yet'}
                </SyntaxHighlighter>
              )}
              {rightPanelTab === 1 && (
                <SyntaxHighlighter
                  language="rego"
                  style={atomOneDark}
                  customStyle={{ margin: 0, height: '100%', fontSize: '12px' }}
                >
                  {migration.generatedRego || '# No Rego policy generated'}
                </SyntaxHighlighter>
              )}
            </Box>
          </Paper>
        </Grid>
      </Grid>

      {/* Review Actions */}
      {migration.status === 'REVIEW' && (
        <Paper sx={{ mt: 2, p: 2 }}>
          <Typography variant="subtitle2" gutterBottom>Review Notes</Typography>
          <TextField
            fullWidth
            multiline
            rows={2}
            placeholder="Add notes about this migration..."
            value={reviewNotes}
            onChange={(e) => setReviewNotes(e.target.value)}
            sx={{ mb: 2 }}
          />
          <Box sx={{ display: 'flex', gap: 2 }}>
            <Button
              variant="contained"
              color="success"
              startIcon={submitting ? <CircularProgress size={16} /> : <CheckIcon />}
              onClick={handleApprove}
              disabled={submitting}
            >
              Approve & Commit
            </Button>
            <Button
              variant="outlined"
              color="error"
              startIcon={<CloseIcon />}
              onClick={handleReject}
              disabled={submitting}
            >
              Reject
            </Button>
          </Box>
        </Paper>
      )}
    </Box>
  );
};

export default MigrationReviewPage;

import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  Paper,
  Typography,
  Grid,
  Card,
  CardContent,
  CardActions,
  Button,
  Chip,
  Alert,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Tabs,
  Tab,
  Badge,
  IconButton,
  Divider,
  LinearProgress,
} from '@mui/material';
import {
  TrendingUp as TrendingUpIcon,
  AttachMoney as MoneyIcon,
  Schedule as ScheduleIcon,
  CheckCircle as SuccessIcon,
  Close as CloseIcon,
  Phone as PhoneIcon,
  Email as EmailIcon,
  VideoCall as VideoIcon,
  Person as PersonIcon,
} from '@mui/icons-material';
import { format } from 'date-fns';
import { devDebug } from '../../utils/devLogger';

interface NBARecommendation {
  recommendation_id: string;
  client_id: string;
  client_name?: string;
  action_id: string;
  action_name: string;
  action_code: string;
  action_category: string;
  confidence_score: number;
  urgency_score: number;
  expected_value: number;
  success_probability: number;
  overall_score: number;
  reasoning: string;
  supporting_data: any;
  recommended_at: string;
  template_content?: {
    email_subject?: string;
    email_body?: string;
    call_script?: string;
    meeting_agenda?: string;
  };
  estimated_duration_minutes?: number;
  default_channel?: string;
}

interface NBAStats {
  pending_count: number;
  critical_count: number;
  total_potential_revenue: number;
  avg_success_rate: number;
  completed_today: number;
}

export const NBAAdvisorDashboard: React.FC = () => {
  const [recommendations, setRecommendations] = useState<NBARecommendation[]>([]);
  const [stats, setStats] = useState<NBAStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<'all' | 'critical' | 'high_value'>('all');
  const [selectedAction, setSelectedAction] = useState<NBARecommendation | null>(null);
  const [dismissDialogOpen, setDismissDialogOpen] = useState(false);
  const [dismissReason, setDismissReason] = useState('');
  const [ws, setWs] = useState<WebSocket | null>(null);

  // WebSocket connection for real-time updates
  useEffect(() => {
    const advisorId = localStorage.getItem('advisor_id'); // Get from auth context
    const wsUrl = `ws://localhost:8080/api/nba/stream?advisor_id=${advisorId}`;

    const websocket = new WebSocket(wsUrl);

    websocket.onopen = () => {
      devDebug('NBA WebSocket connected');
    };

    websocket.onmessage = (event) => {
      const newRecommendation = JSON.parse(event.data);
      setRecommendations(prev => [newRecommendation, ...prev].slice(0, 100)); // Keep top 100
    };

    websocket.onerror = (error) => {
      console.error('WebSocket error:', error);
    };

    websocket.onclose = () => {
      devDebug('NBA WebSocket disconnected');
      // Attempt reconnect after 5 seconds
      setTimeout(() => {
        setWs(websocket);
      }, 5000);
    };

    setWs(websocket);

    return () => {
      websocket.close();
    };
  }, []);

  // Fetch initial data
  useEffect(() => {
    fetchRecommendations();
    fetchStats();
  }, []);

  const fetchRecommendations = async () => {
    try {
      const advisorId = localStorage.getItem('advisor_id');
      const response = await fetch(`/api/nba/recommendations?advisor_id=${advisorId}&status=PENDING&limit=50`);
      const data = await response.json();
      setRecommendations(data.recommendations || []);
    } catch (error) {
      console.error('Failed to fetch recommendations:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchStats = async () => {
    try {
      const advisorId = localStorage.getItem('advisor_id');
      const response = await fetch(`/api/nba/stats?advisor_id=${advisorId}`);
      const data = await response.json();
      setStats(data);
    } catch (error) {
      console.error('Failed to fetch stats:', error);
    }
  };

  const handleExecute = async (recommendation: NBARecommendation) => {
    setSelectedAction(recommendation);
  };

  const handleDismiss = async (recommendationId: string, reason: string) => {
    try {
      await fetch(`/api/nba/recommendations/${recommendationId}/dismiss`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reason, notes: dismissReason })
      });

      // Remove from list
      setRecommendations(prev => prev.filter(r => r.recommendation_id !== recommendationId));
      setDismissDialogOpen(false);
      setDismissReason('');

      // Refresh stats
      fetchStats();
    } catch (error) {
      console.error('Failed to dismiss recommendation:', error);
    }
  };

  const handleCompleteAction = async () => {
    if (!selectedAction) return;

    try {
      await fetch(`/api/nba/recommendations/${selectedAction.recommendation_id}/execute`, {
        method: 'POST'
      });

      // Remove from list
      setRecommendations(prev => prev.filter(r => r.recommendation_id !== selectedAction.recommendation_id));
      setSelectedAction(null);

      // Refresh stats
      fetchStats();
    } catch (error) {
      console.error('Failed to execute recommendation:', error);
    }
  };

  const filteredRecommendations = recommendations.filter(r => {
    if (filter === 'critical') return r.urgency_score > 0.8;
    if (filter === 'high_value') return r.expected_value > 5000;
    return true;
  });

  const getUrgencyColor = (score: number): 'error' | 'warning' | 'info' => {
    if (score > 0.8) return 'error';
    if (score > 0.5) return 'warning';
    return 'info';
  };

  const getChannelIcon = (channel?: string) => {
    switch (channel) {
      case 'PHONE': return <PhoneIcon />;
      case 'EMAIL': return <EmailIcon />;
      case 'VIDEO_CALL': return <VideoIcon />;
      default: return <PersonIcon />;
    }
  };

  if (loading) {
    return <LinearProgress />;
  }

  return (
    <Box sx={{ p: 3 }}>
      {/* Header */}
      <Box sx={{ mb: 4 }}>
        <Typography variant="h4" gutterBottom>
          AI-Powered Next Best Actions
        </Typography>
        <Typography variant="body2" color="text.secondary">
          Real-time recommendations powered by machine learning
        </Typography>
      </Box>

      {/* Stats Cards */}
      {stats && (
        <Grid container spacing={3} sx={{ mb: 4 }}>
          <Grid item xs={12} sm={6} md={3}>
            <Card>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                  <ScheduleIcon color="primary" sx={{ mr: 1 }} />
                  <Typography variant="h6">{stats.pending_count}</Typography>
                </Box>
                <Typography variant="body2" color="text.secondary">
                  Pending Actions
                </Typography>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} md={3}>
            <Card>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                  <TrendingUpIcon color="error" sx={{ mr: 1 }} />
                  <Typography variant="h6">{stats.critical_count}</Typography>
                </Box>
                <Typography variant="body2" color="text.secondary">
                  Critical (Urgent)
                </Typography>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} md={3}>
            <Card>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                  <MoneyIcon color="success" sx={{ mr: 1 }} />
                  <Typography variant="h6">
                    ${stats.total_potential_revenue.toLocaleString()}
                  </Typography>
                </Box>
                <Typography variant="body2" color="text.secondary">
                  Potential Revenue
                </Typography>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} md={3}>
            <Card>
              <CardContent>
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                  <SuccessIcon color="info" sx={{ mr: 1 }} />
                  <Typography variant="h6">
                    {(stats.avg_success_rate * 100).toFixed(0)}%
                  </Typography>
                </Box>
                <Typography variant="body2" color="text.secondary">
                  Avg Success Rate
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      )}

      {/* Filter Tabs */}
      <Paper sx={{ mb: 3 }}>
        <Tabs value={filter} onChange={(_, v) => setFilter(v)}>
          <Tab 
            label={
              <Badge badgeContent={recommendations.length} color="primary">
                All
              </Badge>
            } 
            value="all" 
          />
          <Tab 
            label={
              <Badge badgeContent={recommendations.filter(r => r.urgency_score > 0.8).length} color="error">
                Critical
              </Badge>
            } 
            value="critical" 
          />
          <Tab 
            label={
              <Badge badgeContent={recommendations.filter(r => r.expected_value > 5000).length} color="success">
                High Value ($5K+)
              </Badge>
            } 
            value="high_value" 
          />
        </Tabs>
      </Paper>

      {/* Recommendations List */}
      <Grid container spacing={2}>
        {filteredRecommendations.map((rec) => (
          <Grid item xs={12} key={rec.recommendation_id}>
            <Card variant="outlined" sx={{ '&:hover': { boxShadow: 3 } }}>
              <CardContent>
                <Grid container spacing={2}>
                  {/* Left: Client Info & Action */}
                  <Grid item xs={12} md={8}>
                    <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                      <Typography variant="h6" sx={{ mr: 2 }}>
                        {rec.client_name || `Client ${rec.client_id.substring(0, 8)}`}
                      </Typography>
                      <Chip 
                        label={`Urgency: ${(rec.urgency_score * 100).toFixed(0)}%`}
                        color={getUrgencyColor(rec.urgency_score)}
                        size="small"
                        sx={{ mr: 1 }}
                      />
                      <Chip 
                        label={`Confidence: ${(rec.confidence_score * 100).toFixed(0)}%`}
                        color="primary"
                        variant="outlined"
                        size="small"
                      />
                    </Box>

                    <Typography variant="subtitle1" color="primary" gutterBottom>
                      {rec.action_name}
                    </Typography>

                    <Alert severity="info" sx={{ mb: 2 }}>
                      <Typography variant="body2">
                        <strong>AI Reasoning:</strong> {rec.reasoning}
                      </Typography>
                    </Alert>

                    <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
                      <Chip 
                        icon={getChannelIcon(rec.default_channel)}
                        label={rec.default_channel || 'PHONE'}
                        size="small"
                      />
                      <Chip 
                        icon={<ScheduleIcon />}
                        label={`${rec.estimated_duration_minutes || 30} min`}
                        size="small"
                      />
                      <Chip 
                        icon={<MoneyIcon />}
                        label={`$${rec.expected_value.toLocaleString()} value`}
                        size="small"
                        color="success"
                      />
                      <Chip 
                        icon={<SuccessIcon />}
                        label={`${(rec.success_probability * 100).toFixed(0)}% success rate`}
                        size="small"
                      />
                    </Box>
                  </Grid>

                  {/* Right: Actions */}
                  <Grid item xs={12} md={4}>
                    <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1, height: '100%', justifyContent: 'center' }}>
                      <Button
                        variant="contained"
                        color="primary"
                        fullWidth
                        onClick={() => handleExecute(rec)}
                      >
                        Execute Action
                      </Button>
                      <Button
                        variant="outlined"
                        color="secondary"
                        fullWidth
                        onClick={() => {
                          setSelectedAction(rec);
                          setDismissDialogOpen(true);
                        }}
                      >
                        Dismiss
                      </Button>
                      <Typography variant="caption" color="text.secondary" align="center">
                        Recommended {format(new Date(rec.recommended_at), 'PP')}
                      </Typography>
                    </Box>
                  </Grid>
                </Grid>
              </CardContent>
            </Card>
          </Grid>
        ))}

        {filteredRecommendations.length === 0 && (
          <Grid item xs={12}>
            <Alert severity="success">
              <Typography variant="h6">All caught up!</Typography>
              <Typography variant="body2">
                No pending recommendations at this time. New AI-powered actions will appear here automatically.
              </Typography>
            </Alert>
          </Grid>
        )}
      </Grid>

      {/* Action Execution Modal */}
      <Dialog 
        open={!!selectedAction && !dismissDialogOpen} 
        onClose={() => setSelectedAction(null)}
        maxWidth="md"
        fullWidth
      >
        {selectedAction && (
          <>
            <DialogTitle>
              Execute: {selectedAction.action_name}
              <IconButton
                onClick={() => setSelectedAction(null)}
                sx={{ position: 'absolute', right: 8, top: 8 }}
              >
                <CloseIcon />
              </IconButton>
            </DialogTitle>
            <DialogContent dividers>
              <Typography variant="subtitle2" gutterBottom>
                Client: {selectedAction.client_name || selectedAction.client_id}
              </Typography>

              <Divider sx={{ my: 2 }} />

              {selectedAction.template_content?.email_subject && (
                <Box sx={{ mb: 3 }}>
                  <Typography variant="subtitle1" gutterBottom>
                    📧 Email Template
                  </Typography>
                  <TextField
                    label="Subject"
                    fullWidth
                    defaultValue={selectedAction.template_content.email_subject}
                    sx={{ mb: 2 }}
                  />
                  <TextField
                    label="Body"
                    fullWidth
                    multiline
                    rows={6}
                    defaultValue={selectedAction.template_content.email_body}
                  />
                </Box>
              )}

              {selectedAction.template_content?.call_script && (
                <Box sx={{ mb: 3 }}>
                  <Typography variant="subtitle1" gutterBottom>
                    📞 Call Script
                  </Typography>
                  <Paper sx={{ p: 2, bgcolor: 'grey.50' }}>
                    <Typography variant="body2" sx={{ whiteSpace: 'pre-line' }}>
                      {selectedAction.template_content.call_script}
                    </Typography>
                  </Paper>
                </Box>
              )}

              {selectedAction.template_content?.meeting_agenda && (
                <Box>
                  <Typography variant="subtitle1" gutterBottom>
                    📅 Meeting Agenda
                  </Typography>
                  <Paper sx={{ p: 2, bgcolor: 'grey.50' }}>
                    <Typography variant="body2" sx={{ whiteSpace: 'pre-line' }}>
                      {selectedAction.template_content.meeting_agenda}
                    </Typography>
                  </Paper>
                </Box>
              )}
            </DialogContent>
            <DialogActions>
              <Button onClick={() => setSelectedAction(null)}>
                Cancel
              </Button>
              <Button onClick={handleCompleteAction} variant="contained" color="primary">
                Mark as Complete
              </Button>
            </DialogActions>
          </>
        )}
      </Dialog>

      {/* Dismiss Dialog */}
      <Dialog open={dismissDialogOpen} onClose={() => setDismissDialogOpen(false)}>
        <DialogTitle>Dismiss Recommendation</DialogTitle>
        <DialogContent>
          <Typography variant="body2" gutterBottom>
            Why are you dismissing this recommendation?
          </Typography>
          <TextField
            label="Reason (optional)"
            fullWidth
            multiline
            rows={3}
            value={dismissReason}
            onChange={(e) => setDismissReason(e.target.value)}
            sx={{ mt: 2 }}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDismissDialogOpen(false)}>
            Cancel
          </Button>
          <Button 
            onClick={() => selectedAction && handleDismiss(selectedAction.recommendation_id, 'NOT_RELEVANT')}
            color="secondary"
          >
            Not Relevant
          </Button>
          <Button 
            onClick={() => selectedAction && handleDismiss(selectedAction.recommendation_id, 'ALREADY_DONE')}
            color="secondary"
          >
            Already Done
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

import React, { useState, useEffect } from 'react';
import {
  Box,
  Grid,
  Paper,
  Typography,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Alert,
  Divider,
  LinearProgress,
  IconButton,
  Tooltip,
  Button,
  Stack,
} from '@mui/material';
import {
  CheckCircle as HealthyIcon,
  Warning as WarningIcon,
  Error as ErrorIcon,
  Refresh as RefreshIcon,
  TrendingUp as TrendingUpIcon,
  Speed as SpeedIcon,
  Storage as StorageIcon,
  Notifications as NotificationsIcon,
} from '@mui/icons-material';

interface SLOStatus {
  slo_id: string;
  slo_name: string;
  current_value: number;
  target: number;
  budget_total: number;
  budget_consumed: number;
  budget_remaining: number;
  status: 'healthy' | 'degraded' | 'breached';
  window_start: string;
  window_end: string;
  last_evaluated: string;
}

interface ActiveAlert {
  id: string;
  severity: 'critical' | 'warning' | 'info';
  message: string;
  status: string;
  fired_at: string;
}

interface MetricsSummary {
  total_queries: number;
  avg_query_latency: number;
  p95_query_latency: number;
  p99_query_latency: number;
  error_rate: number;
  cache_hit_rate: number;
  active_connections: number;
}

interface DashboardData {
  slo_statuses: SLOStatus[];
  active_alerts: ActiveAlert[];
  metrics_summary: MetricsSummary;
  system_health: {
    status: string;
    cpu_usage: number;
    memory_usage: number;
    last_health_check: string;
  };
}

const statusColors = {
  healthy: '#4caf50',
  degraded: '#ff9800',
  breached: '#f44336',
};

const severityColors = {
  critical: '#f44336',
  warning: '#ff9800',
  info: '#2196f3',
};

export const ObservabilityDashboard: React.FC = () => {
  const [data, setData] = useState<DashboardData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchDashboard = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/observability/dashboard');
      if (!response.ok) throw new Error('Failed to fetch dashboard data');
      const result = await response.json();
      setData(result);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchDashboard();
    const interval = setInterval(fetchDashboard, 30000); // Refresh every 30s
    return () => clearInterval(interval);
  }, []);

  if (loading && !data) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '60vh' }}>
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ p: 3 }}>
        <Alert severity="error">{error}</Alert>
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      {/* Header */}
      <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 3 }}>
        <Box>
          <Typography variant="h4" sx={{ fontWeight: 700 }}>
            Observability Dashboard
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Real-time monitoring, SLO tracking, and alerting
          </Typography>
        </Box>
        <Tooltip title="Refresh">
          <IconButton onClick={fetchDashboard} disabled={loading}>
            <RefreshIcon />
          </IconButton>
        </Tooltip>
      </Stack>

      {/* Metrics Summary Cards */}
      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ height: '100%', background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)' }}>
            <CardContent>
              <Stack direction="row" justifyContent="space-between" alignItems="flex-start">
                <Box>
                  <Typography variant="overline" sx={{ color: 'rgba(255,255,255,0.7)' }}>
                    Total Queries (24h)
                  </Typography>
                  <Typography variant="h4" sx={{ color: 'white', fontWeight: 700 }}>
                    {data?.metrics_summary.total_queries?.toLocaleString() || 0}
                  </Typography>
                </Box>
                <TrendingUpIcon sx={{ color: 'rgba(255,255,255,0.7)', fontSize: 40 }} />
              </Stack>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ height: '100%', background: 'linear-gradient(135deg, #11998e 0%, #38ef7d 100%)' }}>
            <CardContent>
              <Stack direction="row" justifyContent="space-between" alignItems="flex-start">
                <Box>
                  <Typography variant="overline" sx={{ color: 'rgba(255,255,255,0.7)' }}>
                    Avg Latency
                  </Typography>
                  <Typography variant="h4" sx={{ color: 'white', fontWeight: 700 }}>
                    {data?.metrics_summary.avg_query_latency?.toFixed(0) || 0}ms
                  </Typography>
                </Box>
                <SpeedIcon sx={{ color: 'rgba(255,255,255,0.7)', fontSize: 40 }} />
              </Stack>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ height: '100%', background: 'linear-gradient(135deg, #f093fb 0%, #f5576c 100%)' }}>
            <CardContent>
              <Stack direction="row" justifyContent="space-between" alignItems="flex-start">
                <Box>
                  <Typography variant="overline" sx={{ color: 'rgba(255,255,255,0.7)' }}>
                    Error Rate
                  </Typography>
                  <Typography variant="h4" sx={{ color: 'white', fontWeight: 700 }}>
                    {((data?.metrics_summary.error_rate || 0) * 100).toFixed(2)}%
                  </Typography>
                </Box>
                <ErrorIcon sx={{ color: 'rgba(255,255,255,0.7)', fontSize: 40 }} />
              </Stack>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ height: '100%', background: 'linear-gradient(135deg, #4facfe 0%, #00f2fe 100%)' }}>
            <CardContent>
              <Stack direction="row" justifyContent="space-between" alignItems="flex-start">
                <Box>
                  <Typography variant="overline" sx={{ color: 'rgba(255,255,255,0.7)' }}>
                    Cache Hit Rate
                  </Typography>
                  <Typography variant="h4" sx={{ color: 'white', fontWeight: 700 }}>
                    {((data?.metrics_summary.cache_hit_rate || 0) * 100).toFixed(1)}%
                  </Typography>
                </Box>
                <StorageIcon sx={{ color: 'rgba(255,255,255,0.7)', fontSize: 40 }} />
              </Stack>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      <Grid container spacing={3}>
        {/* SLO Status Cards */}
        <Grid item xs={12} md={8}>
          <Paper sx={{ p: 3 }}>
            <Typography variant="h6" sx={{ fontWeight: 600, mb: 2 }}>
              SLO Status
            </Typography>
            {(!data?.slo_statuses || data.slo_statuses.length === 0) ? (
              <Box sx={{ textAlign: 'center', py: 4 }}>
                <Typography color="text.secondary">No SLOs configured yet</Typography>
                <Button variant="outlined" sx={{ mt: 2 }} href="/observability/slos">
                  Create SLO
                </Button>
              </Box>
            ) : (
              <Grid container spacing={2}>
                {data.slo_statuses.map((slo) => (
                  <Grid item xs={12} sm={6} key={slo.slo_id}>
                    <Card variant="outlined" sx={{ borderLeft: `4px solid ${statusColors[slo.status]}` }}>
                      <CardContent>
                        <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 1 }}>
                          <Typography variant="subtitle1" sx={{ fontWeight: 600 }}>
                            {slo.slo_name}
                          </Typography>
                          <Chip
                            size="small"
                            label={slo.status.toUpperCase()}
                            sx={{
                              backgroundColor: statusColors[slo.status],
                              color: 'white',
                              fontWeight: 600,
                            }}
                          />
                        </Stack>
                        <Typography variant="h5" sx={{ mb: 1 }}>
                          {slo.current_value.toFixed(2)}% <span style={{ fontSize: '0.6em', color: '#888' }}>/ {slo.target}%</span>
                        </Typography>
                        <Box sx={{ mb: 1 }}>
                          <Typography variant="caption" color="text.secondary">
                            Error Budget: {slo.budget_remaining.toFixed(2)}% remaining
                          </Typography>
                          <LinearProgress
                            variant="determinate"
                            value={Math.max(0, (slo.budget_remaining / slo.budget_total) * 100)}
                            sx={{
                              mt: 0.5,
                              height: 6,
                              borderRadius: 3,
                              backgroundColor: 'rgba(0,0,0,0.1)',
                              '& .MuiLinearProgress-bar': {
                                backgroundColor: statusColors[slo.status],
                              },
                            }}
                          />
                        </Box>
                      </CardContent>
                    </Card>
                  </Grid>
                ))}
              </Grid>
            )}
          </Paper>
        </Grid>

        {/* Active Alerts */}
        <Grid item xs={12} md={4}>
          <Paper sx={{ p: 3, height: '100%' }}>
            <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 2 }}>
              <Typography variant="h6" sx={{ fontWeight: 600 }}>
                Active Alerts
              </Typography>
              <NotificationsIcon color="action" />
            </Stack>
            {(!data?.active_alerts || data.active_alerts.length === 0) ? (
              <Box sx={{ textAlign: 'center', py: 4 }}>
                <HealthyIcon sx={{ fontSize: 48, color: '#4caf50', mb: 1 }} />
                <Typography color="text.secondary">No active alerts</Typography>
              </Box>
            ) : (
              <Stack spacing={2}>
                {data.active_alerts.slice(0, 5).map((alert) => (
                  <Card
                    key={alert.id}
                    variant="outlined"
                    sx={{
                      borderLeft: `4px solid ${severityColors[alert.severity]}`,
                      backgroundColor: `${severityColors[alert.severity]}10`,
                    }}
                  >
                    <CardContent sx={{ py: 1.5, '&:last-child': { pb: 1.5 } }}>
                      <Stack direction="row" spacing={1} alignItems="center">
                        {alert.severity === 'critical' && <ErrorIcon sx={{ color: severityColors.critical, fontSize: 20 }} />}
                        {alert.severity === 'warning' && <WarningIcon sx={{ color: severityColors.warning, fontSize: 20 }} />}
                        <Typography variant="body2" sx={{ fontWeight: 500 }}>
                          {alert.message.slice(0, 100)}{alert.message.length > 100 ? '...' : ''}
                        </Typography>
                      </Stack>
                      <Typography variant="caption" color="text.secondary">
                        {new Date(alert.fired_at).toLocaleString()}
                      </Typography>
                    </CardContent>
                  </Card>
                ))}
              </Stack>
            )}
          </Paper>
        </Grid>

        {/* System Health */}
        <Grid item xs={12}>
          <Paper sx={{ p: 3 }}>
            <Typography variant="h6" sx={{ fontWeight: 600, mb: 2 }}>
              System Health
            </Typography>
            <Grid container spacing={3}>
              <Grid item xs={12} sm={4}>
                <Box sx={{ textAlign: 'center' }}>
                  <Typography variant="overline" color="text.secondary">Status</Typography>
                  <Box sx={{ my: 1 }}>
                    {data?.system_health.status === 'healthy' && (
                      <HealthyIcon sx={{ fontSize: 48, color: '#4caf50' }} />
                    )}
                    {data?.system_health.status === 'degraded' && (
                      <WarningIcon sx={{ fontSize: 48, color: '#ff9800' }} />
                    )}
                    {data?.system_health.status === 'critical' && (
                      <ErrorIcon sx={{ fontSize: 48, color: '#f44336' }} />
                    )}
                  </Box>
                  <Typography variant="h6" sx={{ textTransform: 'capitalize' }}>
                    {data?.system_health.status || 'Unknown'}
                  </Typography>
                </Box>
              </Grid>
              <Grid item xs={12} sm={4}>
                <Box sx={{ textAlign: 'center' }}>
                  <Typography variant="overline" color="text.secondary">CPU Usage</Typography>
                  <Typography variant="h4" sx={{ my: 1 }}>
                    {((data?.system_health.cpu_usage || 0) * 100).toFixed(0)}%
                  </Typography>
                  <LinearProgress
                    variant="determinate"
                    value={(data?.system_health.cpu_usage || 0) * 100}
                    sx={{ height: 8, borderRadius: 4 }}
                  />
                </Box>
              </Grid>
              <Grid item xs={12} sm={4}>
                <Box sx={{ textAlign: 'center' }}>
                  <Typography variant="overline" color="text.secondary">Memory Usage</Typography>
                  <Typography variant="h4" sx={{ my: 1 }}>
                    {((data?.system_health.memory_usage || 0) * 100).toFixed(0)}%
                  </Typography>
                  <LinearProgress
                    variant="determinate"
                    value={(data?.system_health.memory_usage || 0) * 100}
                    sx={{ height: 8, borderRadius: 4 }}
                  />
                </Box>
              </Grid>
            </Grid>
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default ObservabilityDashboard;

import React, { useState, useEffect } from 'react';
import {
  Box,
  Stepper,
  Step,
  StepLabel,
  Button,
  Paper,
  Typography,
  TextField,
  Grid,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Radio,
  RadioGroup,
  FormControlLabel,
  FormLabel,
  Slider,
  Alert,
  LinearProgress,
  Chip,
  IconButton,
} from '@mui/material';
import {
  CloudUpload as UploadIcon,
  Delete as DeleteIcon,
  CheckCircle as CheckIcon,
} from '@mui/icons-material';
import { useDropzone } from 'react-dropzone';
import { format } from 'date-fns';

const steps = [
  'Personal Information',
  'Financial Goals',
  'Risk Assessment',
  'Document Upload',
  'Account Selection',
];

interface OnboardingData {
  personalInfo: {
    firstName: string;
    lastName: string;
    email: string;
    phone: string;
    dob: string;
    ssn: string;
    address: {
      street: string;
      city: string;
      state: string;
      zip: string;
    };
  };
  financialGoals: Array<{
    goalType: string;
    targetAmount: number;
    targetDate: string;
    priority: number;
  }>;
  riskAssessment: {
    answers: Record<string, any>;
    riskScore: number;
    riskCategory: string;
  };
  documents: Array<{
    documentId: string;
    documentType: string;
    fileName: string;
    status: string;
  }>;
  accountSelection: {
    accountType: string;
    fundingMethod: string;
    initialInvestment: number;
  };
}

export const ClientOnboardingWizard: React.FC = () => {
  const [activeStep, setActiveStep] = useState(0);
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [resumeToken, setResumeToken] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const [data, setData] = useState<OnboardingData>({
    personalInfo: {
      firstName: '',
      lastName: '',
      email: '',
      phone: '',
      dob: '',
      ssn: '',
      address: { street: '', city: '', state: '', zip: '' },
    },
    financialGoals: [],
    riskAssessment: {
      answers: {},
      riskScore: 0,
      riskCategory: '',
    },
    documents: [],
    accountSelection: {
      accountType: '',
      fundingMethod: '',
      initialInvestment: 0,
    },
  });

  // Check for resume token in URL
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const token = params.get('resume_token');
    if (token) {
      resumeOnboarding(token);
    } else {
      startNewSession();
    }
  }, []);

  const startNewSession = async () => {
    try {
      const response = await fetch('/api/onboarding/sessions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: data.personalInfo.email }),
      });
      const session = await response.json();
      setSessionId(session.session_id);
      setResumeToken(session.resume_token);
    } catch (error) {
      console.error('Failed to start session:', error);
    }
  };

  const resumeOnboarding = async (token: string) => {
    try {
      const response = await fetch(`/api/onboarding/sessions/resume/${token}`);
      const session = await response.json();
      setSessionId(session.session_id);
      setResumeToken(session.resume_token);
      setData({
        personalInfo: session.personal_info || data.personalInfo,
        financialGoals: session.financial_goals || [],
        riskAssessment: session.risk_assessment || data.riskAssessment,
        documents: [],
        accountSelection: session.account_selection || data.accountSelection,
      });
      setActiveStep(session.completed_steps?.length || 0);
    } catch (error) {
      console.error('Failed to resume session:', error);
    }
  };

  const saveProgress = async () => {
    if (!sessionId) return;

    setSaving(true);
    try {
      await fetch(`/api/onboarding/sessions/${sessionId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          current_step: steps[activeStep],
          personal_info: data.personalInfo,
          financial_goals: data.financialGoals,
          risk_assessment: data.riskAssessment,
          account_selection: data.accountSelection,
        }),
      });
    } catch (error) {
      console.error('Failed to save progress:', error);
    } finally {
      setSaving(false);
    }
  };

  const validateStep = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (activeStep === 0) {
      if (!data.personalInfo.firstName) newErrors.firstName = 'Required';
      if (!data.personalInfo.lastName) newErrors.lastName = 'Required';
      if (!data.personalInfo.email) newErrors.email = 'Required';
      if (!data.personalInfo.dob) newErrors.dob = 'Required';
      if (!data.personalInfo.ssn || data.personalInfo.ssn.length !== 9) {
        newErrors.ssn = 'Invalid SSN format';
      }
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleNext = async () => {
    if (!validateStep()) return;

    await saveProgress();

    if (activeStep === steps.length - 1) {
      await completeOnboarding();
    } else {
      setActiveStep((prev) => prev + 1);
    }
  };

  const handleBack = () => {
    setActiveStep((prev) => prev - 1);
  };

  const completeOnboarding = async () => {
    if (!sessionId) return;

    try {
      await fetch(`/api/onboarding/sessions/${sessionId}/complete`, {
        method: 'POST',
      });
      // Redirect to success page or dashboard
      window.location.href = '/onboarding/success';
    } catch (error) {
      console.error('Failed to complete onboarding:', error);
    }
  };

  // Render step content
  const renderStepContent = (step: number) => {
    switch (step) {
      case 0:
        return renderPersonalInfo();
      case 1:
        return renderFinancialGoals();
      case 2:
        return renderRiskAssessment();
      case 3:
        return renderDocumentUpload();
      case 4:
        return renderAccountSelection();
      default:
        return null;
    }
  };

  const renderPersonalInfo = () => (
    <Grid container spacing={3}>
      <Grid item xs={12}>
        <Typography variant="h6" gutterBottom>
          Tell us about yourself
        </Typography>
        <Typography variant="body2" color="text.secondary" gutterBottom>
          We need this information to comply with federal regulations and open your account.
        </Typography>
      </Grid>

      <Grid item xs={12} sm={6}>
        <TextField
          label="First Name"
          fullWidth
          required
          value={data.personalInfo.firstName}
          onChange={(e) => setData({
            ...data,
            personalInfo: { ...data.personalInfo, firstName: e.target.value },
          })}
          error={!!errors.firstName}
          helperText={errors.firstName}
        />
      </Grid>

      <Grid item xs={12} sm={6}>
        <TextField
          label="Last Name"
          fullWidth
          required
          value={data.personalInfo.lastName}
          onChange={(e) => setData({
            ...data,
            personalInfo: { ...data.personalInfo, lastName: e.target.value },
          })}
          error={!!errors.lastName}
          helperText={errors.lastName}
        />
      </Grid>

      <Grid item xs={12} sm={6}>
        <TextField
          label="Email"
          type="email"
          fullWidth
          required
          value={data.personalInfo.email}
          onChange={(e) => setData({
            ...data,
            personalInfo: { ...data.personalInfo, email: e.target.value },
          })}
          error={!!errors.email}
          helperText={errors.email}
        />
      </Grid>

      <Grid item xs={12} sm={6}>
        <TextField
          label="Phone"
          fullWidth
          value={data.personalInfo.phone}
          onChange={(e) => setData({
            ...data,
            personalInfo: { ...data.personalInfo, phone: e.target.value },
          })}
          placeholder="+1 (555) 123-4567"
        />
      </Grid>

      <Grid item xs={12} sm={6}>
        <TextField
          label="Date of Birth"
          type="date"
          fullWidth
          required
          InputLabelProps={{ shrink: true }}
          value={data.personalInfo.dob}
          onChange={(e) => setData({
            ...data,
            personalInfo: { ...data.personalInfo, dob: e.target.value },
          })}
          error={!!errors.dob}
          helperText={errors.dob}
        />
      </Grid>

      <Grid item xs={12} sm={6}>
        <TextField
          label="Social Security Number"
          fullWidth
          required
          value={data.personalInfo.ssn}
          onChange={(e) => {
            // Only allow digits, max 9
            const cleaned = e.target.value.replace(/\D/g, '').slice(0, 9);
            setData({
              ...data,
              personalInfo: { ...data.personalInfo, ssn: cleaned },
            });
          }}
          placeholder="123456789"
          error={!!errors.ssn}
          helperText={errors.ssn || 'Your SSN is encrypted and secure'}
          inputProps={{ maxLength: 9 }}
        />
      </Grid>

      <Grid item xs={12}>
        <Typography variant="subtitle1" gutterBottom sx={{ mt: 2 }}>
          Address
        </Typography>
      </Grid>

      <Grid item xs={12}>
        <TextField
          label="Street Address"
          fullWidth
          value={data.personalInfo.address.street}
          onChange={(e) => setData({
            ...data,
            personalInfo: {
              ...data.personalInfo,
              address: { ...data.personalInfo.address, street: e.target.value },
            },
          })}
        />
      </Grid>

      <Grid item xs={12} sm={4}>
        <TextField
          label="City"
          fullWidth
          value={data.personalInfo.address.city}
          onChange={(e) => setData({
            ...data,
            personalInfo: {
              ...data.personalInfo,
              address: { ...data.personalInfo.address, city: e.target.value },
            },
          })}
        />
      </Grid>

      <Grid item xs={12} sm={4}>
        <FormControl fullWidth>
          <InputLabel>State</InputLabel>
          <Select
            value={data.personalInfo.address.state}
            onChange={(e) => setData({
              ...data,
              personalInfo: {
                ...data.personalInfo,
                address: { ...data.personalInfo.address, state: e.target.value },
              },
            })}
          >
            <MenuItem value="CA">California</MenuItem>
            <MenuItem value="NY">New York</MenuItem>
            <MenuItem value="TX">Texas</MenuItem>
            {/* Add more states */}
          </Select>
        </FormControl>
      </Grid>

      <Grid item xs={12} sm={4}>
        <TextField
          label="ZIP Code"
          fullWidth
          value={data.personalInfo.address.zip}
          onChange={(e) => {
            const cleaned = e.target.value.replace(/\D/g, '').slice(0, 5);
            setData({
              ...data,
              personalInfo: {
                ...data.personalInfo,
                address: { ...data.personalInfo.address, zip: cleaned },
              },
            });
          }}
          inputProps={{ maxLength: 5 }}
        />
      </Grid>
    </Grid>
  );

  const renderFinancialGoals = () => (
    <Box>
      <Typography variant="h6" gutterBottom>
        What are your financial goals?
      </Typography>
      <Typography variant="body2" color="text.secondary" gutterBottom>
        Help us understand what you're saving for so we can build the right portfolio.
      </Typography>

      <Button
        variant="outlined"
        onClick={() => {
          setData({
            ...data,
            financialGoals: [
              ...data.financialGoals,
              { goalType: '', targetAmount: 0, targetDate: '', priority: data.financialGoals.length + 1 },
            ],
          });
        }}
        sx={{ mt: 2, mb: 3 }}
      >
        + Add Goal
      </Button>

      {data.financialGoals.map((goal, index) => (
        <Paper key={index} sx={{ p: 2, mb: 2 }}>
          <Grid container spacing={2}>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth>
                <InputLabel>Goal Type</InputLabel>
                <Select
                  value={goal.goalType}
                  onChange={(e) => {
                    const newGoals = [...data.financialGoals];
                    newGoals[index].goalType = e.target.value;
                    setData({ ...data, financialGoals: newGoals });
                  }}
                >
                  <MenuItem value="RETIREMENT">Retirement</MenuItem>
                  <MenuItem value="EDUCATION">Education</MenuItem>
                  <MenuItem value="HOME_PURCHASE">Home Purchase</MenuItem>
                  <MenuItem value="WEALTH_BUILDING">Wealth Building</MenuItem>
                  <MenuItem value="OTHER">Other</MenuItem>
                </Select>
              </FormControl>
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
                label="Target Amount"
                fullWidth
                type="number"
                value={goal.targetAmount}
                onChange={(e) => {
                  const newGoals = [...data.financialGoals];
                  newGoals[index].targetAmount = parseFloat(e.target.value);
                  setData({ ...data, financialGoals: newGoals });
                }}
                InputProps={{ startAdornment: '$' }}
              />
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
                label="Target Date"
                type="date"
                fullWidth
                InputLabelProps={{ shrink: true }}
                value={goal.targetDate}
                onChange={(e) => {
                  const newGoals = [...data.financialGoals];
                  newGoals[index].targetDate = e.target.value;
                  setData({ ...data, financialGoals: newGoals });
                }}
              />
            </Grid>

            <Grid item xs={12} sm={6}>
              <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                <Chip label={`Priority ${goal.priority}`} color="primary" size="small" />
                <IconButton
                  size="small"
                  onClick={() => {
                    const newGoals = data.financialGoals.filter((_, i) => i !== index);
                    setData({ ...data, financialGoals: newGoals });
                  }}
                >
                  <DeleteIcon />
                </IconButton>
              </Box>
            </Grid>
          </Grid>
        </Paper>
      ))}
    </Box>
  );

  const renderRiskAssessment = () => (
    <Box>
      <Typography variant="h6" gutterBottom>
        Risk Assessment
      </Typography>
      <Typography variant="body2" color="text.secondary" gutterBottom sx={{ mb: 3 }}>
        Answer a few questions to help us understand your investment comfort level.
      </Typography>

      <FormControl component="fieldset" fullWidth sx={{ mb: 3 }}>
        <FormLabel component="legend">
          If your portfolio dropped 20% in value, what would you do?
        </FormLabel>
        <RadioGroup
          value={data.riskAssessment.answers.marketDrop || ''}
          onChange={(e) => setData({
            ...data,
            riskAssessment: {
              ...data.riskAssessment,
              answers: { ...data.riskAssessment.answers, marketDrop: e.target.value },
            },
          })}
        >
          <FormControlLabel value="sell" control={<Radio />} label="Sell everything to avoid further losses" />
          <FormControlLabel value="hold" control={<Radio />} label="Hold and wait for recovery" />
          <FormControlLabel value="buy" control={<Radio />} label="Buy more at lower prices" />
        </RadioGroup>
      </FormControl>

      <FormControl component="fieldset" fullWidth sx={{ mb: 3 }}>
        <FormLabel component="legend">
          What is your investment time horizon?
        </FormLabel>
        <RadioGroup
          value={data.riskAssessment.answers.timeHorizon || ''}
          onChange={(e) => setData({
            ...data,
            riskAssessment: {
              ...data.riskAssessment,
              answers: { ...data.riskAssessment.answers, timeHorizon: e.target.value },
            },
          })}
        >
          <FormControlLabel value="<3" control={<Radio />} label="Less than 3 years" />
          <FormControlLabel value="3-7" control={<Radio />} label="3-7 years" />
          <FormControlLabel value="7-15" control={<Radio />} label="7-15 years" />
          <FormControlLabel value=">15" control={<Radio />} label="More than 15 years" />
        </RadioGroup>
      </FormControl>

      <Alert severity="info" sx={{ mt: 3 }}>
        <Typography variant="subtitle2">Your Risk Profile</Typography>
        <Typography variant="body2">
          Based on your answers, we'll recommend a portfolio allocation that matches your comfort level.
        </Typography>
      </Alert>
    </Box>
  );

  const renderDocumentUpload = () => {
    const { getRootProps, getInputProps } = useDropzone({
      accept: {
        'image/*': ['.png', '.jpg', '.jpeg'],
        'application/pdf': ['.pdf'],
      },
      maxSize: 10485760, // 10MB
      onDrop: async (acceptedFiles) => {
        for (const file of acceptedFiles) {
          await uploadDocument(file);
        }
      },
    });

    return (
      <Box>
        <Typography variant="h6" gutterBottom>
          Upload Identity Documents
        </Typography>
        <Typography variant="body2" color="text.secondary" gutterBottom>
          We need to verify your identity per federal regulations (KYC/AML).
        </Typography>

        <Box
          {...getRootProps()}
          sx={{
            border: '2px dashed #ccc',
            borderRadius: 2,
            p: 4,
            textAlign: 'center',
            cursor: 'pointer',
            mt: 3,
            mb: 3,
            '&:hover': { borderColor: 'primary.main' },
          }}
        >
          <input {...getInputProps()} />
          <UploadIcon sx={{ fontSize: 48, color: 'primary.main', mb: 2 }} />
          <Typography variant="h6">Drag & drop files here</Typography>
          <Typography variant="body2" color="text.secondary">
            or click to select files
          </Typography>
          <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
            Accepted: Driver's License, Passport, Utility Bill (PDF, JPG, PNG, max 10MB)
          </Typography>
        </Box>

        {data.documents.map((doc) => (
          <Paper key={doc.documentId} sx={{ p: 2, mb: 1, display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <Box>
              <Typography variant="body1">{doc.fileName}</Typography>
              <Chip label={doc.documentType} size="small" sx={{ mr: 1 }} />
              <Chip label={doc.status} color={doc.status === 'VERIFIED' ? 'success' : 'default'} size="small" />
            </Box>
            <CheckIcon color="success" />
          </Paper>
        ))}
      </Box>
    );
  };

  const uploadDocument = async (file: File) => {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('session_id', sessionId!);
    formData.append('document_type', 'DRIVERS_LICENSE'); // Auto-detect via OCR

    try {
      const response = await fetch('/api/onboarding/documents', {
        method: 'POST',
        body: formData,
      });
      const doc = await response.json();
      setData({
        ...data,
        documents: [...data.documents, doc],
      });
    } catch (error) {
      console.error('Upload failed:', error);
    }
  };

  const renderAccountSelection = () => (
    <Grid container spacing={3}>
      <Grid item xs={12}>
        <Typography variant="h6" gutterBottom>
          Choose Your Account
        </Typography>
      </Grid>

      <Grid item xs={12}>
        <FormControl fullWidth>
          <InputLabel>Account Type</InputLabel>
          <Select
            value={data.accountSelection.accountType}
            onChange={(e) => setData({
              ...data,
              accountSelection: { ...data.accountSelection, accountType: e.target.value },
            })}
          >
            <MenuItem value="INDIVIDUAL">Individual Brokerage</MenuItem>
            <MenuItem value="JOINT">Joint Account</MenuItem>
            <MenuItem value="IRA">Traditional IRA</MenuItem>
            <MenuItem value="ROTH_IRA">Roth IRA</MenuItem>
          </Select>
        </FormControl>
      </Grid>

      <Grid item xs={12}>
        <FormControl fullWidth>
          <InputLabel>Funding Method</InputLabel>
          <Select
            value={data.accountSelection.fundingMethod}
            onChange={(e) => setData({
              ...data,
              accountSelection: { ...data.accountSelection, fundingMethod: e.target.value },
            })}
          >
            <MenuItem value="ACH">Bank Transfer (ACH)</MenuItem>
            <MenuItem value="WIRE">Wire Transfer</MenuItem>
            <MenuItem value="CHECK">Mail a Check</MenuItem>
          </Select>
        </FormControl>
      </Grid>

      <Grid item xs={12}>
        <TextField
          label="Initial Investment"
          fullWidth
          type="number"
          value={data.accountSelection.initialInvestment}
          onChange={(e) => setData({
            ...data,
            accountSelection: { ...data.accountSelection, initialInvestment: parseFloat(e.target.value) },
          })}
          InputProps={{ startAdornment: '$' }}
          helperText="Minimum: $1,000"
        />
      </Grid>
    </Grid>
  );

  return (
    <Box sx={{ maxWidth: 900, mx: 'auto', p: 3 }}>
      <Typography variant="h4" gutterBottom align="center">
        Welcome to Your Financial Future
      </Typography>

      <Stepper activeStep={activeStep} sx={{ mt: 4, mb: 4 }}>
        {steps.map((label) => (
          <Step key={label}>
            <StepLabel>{label}</StepLabel>
          </Step>
        ))}
      </Stepper>

      {saving && <LinearProgress sx={{ mb: 2 }} />}

      {resumeToken && (
        <Alert severity="info" sx={{ mb: 3 }}>
          Your progress is automatically saved. You can resume anytime using this link:
          <Typography variant="body2" component="div" sx={{ mt: 1, fontFamily: 'monospace', fontSize: '0.875rem' }}>
            {window.location.origin}/onboarding?resume_token={resumeToken}
          </Typography>
        </Alert>
      )}

      <Paper sx={{ p: 4, mb: 3 }}>
        {renderStepContent(activeStep)}
      </Paper>

      <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
        <Button
          disabled={activeStep === 0}
          onClick={handleBack}
        >
          Back
        </Button>
        <Button
          variant="contained"
          onClick={handleNext}
          disabled={saving}
        >
          {activeStep === steps.length - 1 ? 'Complete' : 'Next'}
        </Button>
      </Box>

      <Typography variant="caption" color="text.secondary" align="center" display="block" sx={{ mt: 3 }}>
        Step {activeStep + 1} of {steps.length} • {Math.round(((activeStep + 1) / steps.length) * 100)}% Complete
      </Typography>
    </Box>
  );
};

