import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  Paper,
  Typography,
  TextField,
  Button,
  Grid,
  CircularProgress,
  Alert,
  Divider,
  List,
  ListItem,
  ListItemText,
  ListItemSecondaryAction,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Chip
} from '@mui/material';
import {
  Psychology as AIIcon,
  Save as SaveIcon,
  Add as AddIcon,
  Delete as DeleteIcon,
  Edit as EditIcon
} from '@mui/icons-material';
import { useTenant } from '../contexts/TenantContext';
import Editor from '@monaco-editor/react';

interface Policy {
  id: string;
  name: string;
  description: string;
  regoCode: string;
  createdAt: string;
}

const PolicyEditorPage: React.FC = () => {
  const { tenant } = useTenant();
  const [policies, setPolicies] = useState<Policy[]>([]);
  const [selectedPolicy, setSelectedPolicy] = useState<Policy | null>(null);

  // AI Generation state
  const [ruleText, setRuleText] = useState('');
  const [generatedRego, setGeneratedRego] = useState('');
  const [explanation, setExplanation] = useState('');
  const [generating, setGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Save dialog
  const [saveDialogOpen, setSaveDialogOpen] = useState(false);
  const [policyName, setPolicyName] = useState('');
  const [policyDescription, setPolicyDescription] = useState('');
  const [saving, setSaving] = useState(false);

  // Fetch policies on mount
  useEffect(() => {
    fetchPolicies();
  }, [tenant?.id]);

  const fetchPolicies = async () => {
    try {
      const response = await fetch('/api/v1/policies', {
        headers: {
          ...(tenant?.id && { 'X-Tenant-ID': tenant.id }),
        },
      });
      if (response.ok) {
        const data = await response.json();
        setPolicies(data || []);
      }
    } catch (err) {
      console.error('Failed to fetch policies:', err);
    }
  };

  const handleGenerate = useCallback(async () => {
    if (!ruleText.trim()) return;

    setGenerating(true);
    setError(null);

    try {
      const response = await fetch('/api/v1/copilot/generate-rego', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(tenant?.id && { 'X-Tenant-ID': tenant.id }),
        },
        body: JSON.stringify({
          text: ruleText,
          policyName: policyName || 'custom_policy',
        }),
      });

      if (!response.ok) {
        throw new Error(await response.text());
      }

      const data = await response.json();
      setGeneratedRego(data.regoCode);
      setExplanation(data.explanation);
      if (data.policyName && !policyName) {
        setPolicyName(data.policyName);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Generation failed');
    } finally {
      setGenerating(false);
    }
  }, [ruleText, policyName, tenant?.id]);

  const handleSave = async () => {
    if (!generatedRego || !policyName) return;

    setSaving(true);
    try {
      const response = await fetch('/api/v1/policies', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(tenant?.id && { 'X-Tenant-ID': tenant.id }),
        },
        body: JSON.stringify({
          name: policyName,
          description: policyDescription || explanation,
          regoCode: generatedRego,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to save policy');
      }

      setSaveDialogOpen(false);
      setRuleText('');
      setGeneratedRego('');
      setPolicyName('');
      setPolicyDescription('');
      fetchPolicies();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Save failed');
    } finally {
      setSaving(false);
    }
  };

  const handleDeletePolicy = async (id: string) => {
    try {
      await fetch(`/api/v1/policies/${id}`, {
        method: 'DELETE',
        headers: {
          ...(tenant?.id && { 'X-Tenant-ID': tenant.id }),
        },
      });
      fetchPolicies();
    } catch (err) {
      console.error('Failed to delete policy:', err);
    }
  };

  const exampleRules = [
    "Block all trades over $1 million",
    "Require manager approval for orders from new customers",
    "Deny access if user location is outside approved regions",
    "Flag transactions with amount above customer's credit limit"
  ];

  return (
    <Box sx={{ p: 3, height: 'calc(100vh - 64px)', display: 'flex', flexDirection: 'column' }}>
      {/* Header */}
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 3 }}>
        <AIIcon sx={{ fontSize: 32, color: 'primary.main' }} />
        <Box>
          <Typography variant="h5">AI Policy Editor</Typography>
          <Typography variant="body2" color="text.secondary">
            Describe business rules in plain English and generate OPA Rego policies
          </Typography>
        </Box>
      </Box>

      <Grid container spacing={3} sx={{ flex: 1, minHeight: 0 }}>
        {/* Left: Rule Input & Generation */}
        <Grid item xs={12} md={4}>
          <Paper sx={{ p: 2, height: '100%', display: 'flex', flexDirection: 'column' }}>
            <Typography variant="subtitle1" fontWeight="bold" gutterBottom>
              Describe Your Rule
            </Typography>

            <TextField
              fullWidth
              multiline
              rows={4}
              placeholder="Example: Block all trades over $1 million"
              value={ruleText}
              onChange={(e) => setRuleText(e.target.value)}
              sx={{ mb: 2 }}
            />

            <Button
              fullWidth
              variant="contained"
              startIcon={generating ? <CircularProgress size={16} color="inherit" /> : <AIIcon />}
              onClick={handleGenerate}
              disabled={generating || !ruleText.trim()}
              sx={{ mb: 2 }}
            >
              {generating ? 'Generating...' : 'Generate Policy'}
            </Button>

            <Divider sx={{ my: 2 }} />

            <Typography variant="caption" color="text.secondary" gutterBottom>
              Example rules:
            </Typography>
            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
              {exampleRules.map((rule, i) => (
                <Chip
                  key={i}
                  label={rule.length > 25 ? rule.substring(0, 25) + '...' : rule}
                  size="small"
                  onClick={() => setRuleText(rule)}
                  sx={{ cursor: 'pointer' }}
                />
              ))}
            </Box>

            {error && (
              <Alert severity="error" sx={{ mt: 2 }}>
                {error}
              </Alert>
            )}

            <Divider sx={{ my: 2 }} />

            <Typography variant="subtitle2" gutterBottom>
              Saved Policies
            </Typography>
            <List dense sx={{ flex: 1, overflow: 'auto' }}>
              {policies.map((policy) => (
                <ListItem
                  key={policy.id}
                  button
                  selected={selectedPolicy?.id === policy.id}
                  onClick={() => {
                    setSelectedPolicy(policy);
                    setGeneratedRego(policy.regoCode);
                  }}
                >
                  <ListItemText
                    primary={policy.name}
                    secondary={policy.description?.substring(0, 50)}
                  />
                  <ListItemSecondaryAction>
                    <IconButton size="small" onClick={() => handleDeletePolicy(policy.id)}>
                      <DeleteIcon fontSize="small" />
                    </IconButton>
                  </ListItemSecondaryAction>
                </ListItem>
              ))}
              {policies.length === 0 && (
                <Typography variant="body2" color="text.secondary" sx={{ p: 2 }}>
                  No policies saved yet
                </Typography>
              )}
            </List>
          </Paper>
        </Grid>

        {/* Right: Generated Rego Code */}
        <Grid item xs={12} md={8}>
          <Paper sx={{ p: 2, height: '100%', display: 'flex', flexDirection: 'column' }}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
              <Typography variant="subtitle1" fontWeight="bold">
                Generated Rego Policy
              </Typography>
              <Button
                variant="contained"
                startIcon={<SaveIcon />}
                disabled={!generatedRego}
                onClick={() => setSaveDialogOpen(true)}
              >
                Save Policy
              </Button>
            </Box>

            {explanation && (
              <Alert severity="info" sx={{ mb: 2 }}>
                {explanation}
              </Alert>
            )}

            <Box sx={{ flex: 1, minHeight: 0, border: 1, borderColor: 'divider', borderRadius: 1 }}>
              <Editor
                height="100%"
                language="rego"
                theme="vs-dark"
                value={generatedRego || '# Generated Rego policy will appear here\n'}
                onChange={(value) => setGeneratedRego(value || '')}
                options={{
                  minimap: { enabled: false },
                  fontSize: 14,
                  lineNumbers: 'on',
                  scrollBeyondLastLine: false,
                }}
              />
            </Box>
          </Paper>
        </Grid>
      </Grid>

      {/* Save Dialog */}
      <Dialog open={saveDialogOpen} onClose={() => setSaveDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Save Policy</DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            label="Policy Name"
            value={policyName}
            onChange={(e) => setPolicyName(e.target.value)}
            sx={{ mt: 2, mb: 2 }}
          />
          <TextField
            fullWidth
            multiline
            rows={2}
            label="Description"
            value={policyDescription}
            onChange={(e) => setPolicyDescription(e.target.value)}
          />
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setSaveDialogOpen(false)}>Cancel</Button>
          <Button
            variant="contained"
            onClick={handleSave}
            disabled={saving || !policyName}
            startIcon={saving ? <CircularProgress size={16} /> : <SaveIcon />}
          >
            Save
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default PolicyEditorPage;

import React, { useState, useEffect } from 'react';
import {
  Plus,
  Trash2,
  TrendingUp,
  TrendingDown,
  PieChart as PieChartIcon,
  AlertCircle,
  CheckCircle,
  Download,
  RefreshCw,
  X,
} from 'lucide-react';
import { useTenant } from '../contexts/TenantContext';
import { useConfirm } from '../components/ConfirmProvider';
import { devLog } from '../utils/devLogger';
import { getCardClasses, getTextClasses, getButtonClasses, getAlertClasses } from '../utils/darkModeHelpers';

interface Portfolio {
  id: string;
  name: string;
  currency: string;
  totalValue: number;
  holdingsCount: number;
  allocation: {
    symbol: string;
    percentage: number;
    value: number;
  }[];
  metrics: {
    dayChange: number;
    dayChangePercent: number;
    monthReturn: number;
    yearReturn: number;
  };
  lastUpdated: string;
}

interface Holding {
  id: string;
  symbol: string;
  name: string;
  quantity: number;
  averageCost: number;
  currentPrice: number;
  currentValue: number;
  gainLoss: number;
  gainLossPercent: number;
  allocation: number;
  assetClass: string;
  sector: string;
  beta?: number;
  volatility?: number;
}

/**
 * Portfolio Dashboard Page
 * Main view for portfolio management, holdings overview, and performance tracking
 */
export const PortfolioDashboardPage: React.FC = () => {
  const { tenant, datasource } = useTenant();

  const [portfolios, setPortfolios] = useState<Portfolio[]>([]);
  const [selectedPortfolio, setSelectedPortfolio] = useState<Portfolio | null>(null);
  const [holdings, setHoldings] = useState<Holding[]>([]);
  const [loading, setLoading] = useState(false);
  const [refreshing, setRefreshing] = useState(false);

  const [showCreateForm, setShowCreateForm] = useState(false);
  // reserved/unused for now; underscore-prefixed to indicate intentional unused state
  const [_showEditForm, _setShowEditForm] = useState(false);
  const [_editingPortfolio, _setEditingPortfolio] = useState<Portfolio | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    currency: 'USD',
  });

  const confirm = useConfirm();

  const [toast, setToast] = useState<{ type: 'success' | 'error'; message: string } | null>(null);
  const [filterAssetClass, setFilterAssetClass] = useState<string>('ALL');
  const [sortBy, setSortBy] = useState<'value' | 'allocation' | 'gainLoss'>('value');

  // Initialize
  useEffect(() => {
    if (tenant && datasource) {
      loadPortfolios();
      devLog('Portfolio Dashboard initialized', { tenantId: tenant.id, datasourceId: datasource.id });
    }
  }, [tenant, datasource]);

  // Load holdings when portfolio selected
  useEffect(() => {
    if (selectedPortfolio) {
      loadHoldings(selectedPortfolio.id);
    }
  }, [selectedPortfolio]);

  const showToast = (type: 'success' | 'error', message: string) => {
    setToast({ type, message });
    setTimeout(() => setToast(null), 3000);
  };

  const loadPortfolios = async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/portfolios', {
        headers: {
          'X-User-ID': tenant?.id || '',
          'X-Tenant-ID': tenant?.id || '',
          'X-Tenant-Datasource-ID': datasource?.id || '',
        },
      });

      if (!response.ok) throw new Error('Failed to fetch portfolios');
      const data = await response.json();
      setPortfolios(data || []);
      if (data && data.length > 0) {
        setSelectedPortfolio(data[0]);
      }
      devLog('Portfolios loaded', { count: data?.length || 0 });
    } catch (error) {
      console.error('Failed to load portfolios:', error);
      showToast('error', 'Failed to load portfolios');
    } finally {
      setLoading(false);
    }
  };

  const loadHoldings = async (portfolioId: string) => {
    try {
      const response = await fetch(`/api/holdings?portfolio_id=${portfolioId}`, {
        headers: {
          'X-User-ID': tenant?.id || '',
          'X-Tenant-ID': tenant?.id || '',
          'X-Tenant-Datasource-ID': datasource?.id || '',
        },
      });

      if (!response.ok) throw new Error('Failed to fetch holdings');
      const data = await response.json();
      setHoldings(data || []);
      devLog('Holdings loaded', { portfolioId, count: data?.length || 0 });
    } catch (error) {
      console.error('Failed to load holdings:', error);
      showToast('error', 'Failed to load holdings');
    }
  };

  const handleCreatePortfolio = async () => {
    if (!formData.name.trim()) {
      showToast('error', 'Portfolio name is required');
      return;
    }

    setRefreshing(true);
    try {
      const response = await fetch('/api/portfolios', {
        method: 'POST',
        headers: {
          'X-User-ID': tenant?.id || '',
          'X-Tenant-ID': tenant?.id || '',
          'X-Tenant-Datasource-ID': datasource?.id || '',
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          name: formData.name,
          currency: formData.currency,
          holdings: [],
        }),
      });

      if (!response.ok) throw new Error('Failed to create portfolio');
      showToast('success', 'Portfolio created successfully');
      setShowCreateForm(false);
      setFormData({ name: '', currency: 'USD' });
      await loadPortfolios();
    } catch (error) {
      console.error('Failed to create portfolio:', error);
      showToast('error', 'Failed to create portfolio');
    } finally {
      setRefreshing(false);
    }
  };

  const handleDeletePortfolio = async (portfolioId: string) => {
    const confirm = useConfirm();
    if (!(await confirm({ title: 'Delete portfolio', description: 'Are you sure you want to delete this portfolio?' }))) return;

    setRefreshing(true);
    try {
      const response = await fetch(`/api/portfolios/${portfolioId}`, {
        method: 'DELETE',
        headers: {
          'X-User-ID': tenant?.id || '',
          'X-Tenant-ID': tenant?.id || '',
          'X-Tenant-Datasource-ID': datasource?.id || '',
        },
      });

      if (!response.ok) throw new Error('Failed to delete portfolio');
      showToast('success', 'Portfolio deleted successfully');
      await loadPortfolios();
    } catch (error) {
      console.error('Failed to delete portfolio:', error);
      showToast('error', 'Failed to delete portfolio');
    } finally {
      setRefreshing(false);
    }
  };

  const filteredHoldings = holdings.filter(
    (h) => filterAssetClass === 'ALL' || h.assetClass === filterAssetClass
  );

  const sortedHoldings = [...filteredHoldings].sort((a, b) => {
    switch (sortBy) {
      case 'value':
        return b.currentValue - a.currentValue;
      case 'allocation':
        return b.allocation - a.allocation;
      case 'gainLoss':
        return b.gainLoss - a.gainLoss;
      default:
        return 0;
    }
  });

  const uniqueAssetClasses = ['ALL', ...new Set(holdings.map((h) => h.assetClass))];

  if (!tenant || !datasource) {
    return (
      <div className={`${getCardClasses()} p-8 bg-gradient-to-br from-blue-50 to-blue-50/50 dark:from-blue-950/20 dark:to-blue-950/10`}>
        <AlertCircle className="w-6 h-6 text-yellow-600 dark:text-yellow-400 mb-2" />
        <p className={getTextClasses('primary')}>Please select a tenant and datasource to manage portfolios.</p>
      </div>
    );
  }

  return (
    <div className={`${getCardClasses()} space-y-6 p-6`}>
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-slate-900 dark:text-text-light">Portfolio Dashboard</h1>
          <p className={`${getTextClasses('secondary')} mt-1`}>Manage portfolios and track holdings performance</p>
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={async () => {
              await loadPortfolios();
              if (selectedPortfolio) await loadHoldings(selectedPortfolio.id);
            }}
            className={`${getButtonClasses('secondary')} flex items-center gap-2`}
            title="Refresh portfolio data"
            aria-label="Refresh portfolio data"
          >
            <RefreshCw className="w-5 h-5" />
            Refresh
          </button>
          <button
            onClick={() => setShowCreateForm(true)}
            className={`${getButtonClasses('primary')} flex items-center gap-2`}
          >
            <Plus className="w-5 h-5" />
            New Portfolio
          </button>
        </div>
      </div>

      {/* Toast */}
      {toast && (
        <div className={`p-4 rounded-lg flex items-center gap-3 ${toast.type === 'success' ? getAlertClasses('success') : getAlertClasses('error')}`}>
          {toast.type === 'success' ? (
            <CheckCircle className="w-5 h-5 text-green-600 dark:text-green-400" />
          ) : (
            <AlertCircle className="w-5 h-5 text-red-600 dark:text-red-400" />
          )}
          <span className={toast.type === 'success' ? 'text-green-800 dark:text-green-200' : 'text-red-800 dark:text-red-200'}>
            {toast.message}
          </span>
        </div>
      )}

      {/* Portfolio Selector */}
      {loading ? (
        <div className="text-center py-12">
          <div className="animate-spin inline-block w-8 h-8 border-4 border-slate-300 dark:border-slate-600 border-t-blue-600 rounded-full"></div>
          <p className={`${getTextClasses('secondary')} mt-4`}>Loading portfolios...</p>
        </div>
      ) : portfolios.length === 0 ? (
        <div className="text-center py-12 border-2 border-dashed border-slate-300 dark:border-slate-600 rounded-lg">
          <PieChartIcon className="w-12 h-12 text-slate-400 dark:text-slate-500 mx-auto mb-4" />
          <p className={`${getTextClasses('secondary')} mb-4`}>No portfolios yet</p>
          <button onClick={() => setShowCreateForm(true)} className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors">
            Create First Portfolio
          </button>
        </div>
      ) : (
        <>
          {/* Portfolio Cards */}
          <div className="grid gap-4 grid-cols-1 md:grid-cols-2 lg:grid-cols-3">
            {portfolios.map((portfolio) => (
              <div
                key={portfolio.id}
                onClick={() => setSelectedPortfolio(portfolio)}
                className={`p-4 rounded-lg border-2 cursor-pointer transition-all ${
