                      <p className={`text-sm font-medium ${getTextClasses('primary')} mt-1`}>
                        {selectedPortfolio.concentration.top10.toFixed(1)}%
                      </p>
                    </div>
                  </div>
                </div>
              </div>

              {/* Risk Factors */}
              {riskFactors.length > 0 && (
                <div className={`${getCardClasses()} p-6`}>
