import React, { useState, useEffect } from 'react';
import { 
  Box, Typography, Paper, Table, TableBody, TableCell, TableContainer, TableHead, TableRow, 
  Chip, TextField, IconButton, Button, Dialog, DialogTitle, DialogContent, Grid, Card, CardContent
} from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import VisibilityIcon from '@mui/icons-material/Visibility';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import WarningIcon from '@mui/icons-material/Warning';

interface SemanticTerm {
  id: string;
  node_name: string;
  type: 'physical' | 'calculated' | 'relationship' | 'llm';
  data_type: string;
  description: string;
  expression?: string;
  properties?: any;
}

export const SemanticCatalogPage: React.FC = () => {
  const [terms, setTerms] = useState<SemanticTerm[]>([]);
  const [loading, setLoading] = useState(false);
  const [filter, setFilter] = useState('');
  const [selectedTerm, setSelectedTerm] = useState<SemanticTerm | null>(null);

  useEffect(() => {
    setLoading(true);
    fetch('/api/semantic-terms')
      .then(res => res.json())
      .then(data => setTerms(data.data || []))
      .catch(err => console.error(err))
      .finally(() => setLoading(false));
  }, []);

  const filteredTerms = terms.filter(t => 
    t.node_name.toLowerCase().includes(filter.toLowerCase()) || 
    t.description?.toLowerCase().includes(filter.toLowerCase())
  );

  const getTypeColor = (type: string) => {
    switch (type) {
      case 'physical': return 'default';
      case 'calculated': return 'primary';
      case 'relationship': return 'secondary';
      case 'llm': return 'warning';
      default: return 'default';
    }
  };

  return (
    <Box sx={{ p: 4 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 3 }}>
        <Typography variant="h4">Semantic Term Catalog</Typography>
        <Button variant="contained" color="primary">Create New Term</Button>
      </Box>

      <Paper sx={{ p: 2, mb: 3 }}>
        <TextField 
          fullWidth 
          variant="outlined" 
          placeholder="Search semantic terms..." 
          value={filter}
          onChange={e => setFilter(e.target.value)}
        />
      </Paper>

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              <TableCell>Name</TableCell>
              <TableCell>Type</TableCell>
              <TableCell>Data Type</TableCell>
              <TableCell>Description</TableCell>
              <TableCell>Governance</TableCell>
              <TableCell align="right">Actions</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {filteredTerms.map(term => (
              <TableRow key={term.id} hover>
                <TableCell sx={{ fontWeight: 'medium' }}>{term.node_name}</TableCell>
                <TableCell>
                  <Chip label={term.type} size="small" color={getTypeColor(term.type) as any} variant="outlined" />
                </TableCell>
                <TableCell>{term.data_type}</TableCell>
                <TableCell>{term.description}</TableCell>
                <TableCell>
                  {/* Mock Status */}
                  <Chip icon={<CheckCircleIcon />} label="Approved" size="small" color="success" sx={{ mr: 1 }} />
                </TableCell>
                <TableCell align="right">
                  <IconButton size="small" onClick={() => setSelectedTerm(term)}>
                    <VisibilityIcon />
                  </IconButton>
                  <IconButton size="small">
                    <EditIcon />
                  </IconButton>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      {/* Detail Dialog */}
      <Dialog open={!!selectedTerm} onClose={() => setSelectedTerm(null)} maxWidth="md" fullWidth>
        <DialogTitle>Term Details: {selectedTerm?.node_name}</DialogTitle>
        <DialogContent>
          {selectedTerm && (
            <Grid container spacing={3} sx={{ mt: 1 }}>
              <Grid item xs={12}>
                <Typography variant="subtitle2">Description</Typography>
                <Typography variant="body1" paragraph>{selectedTerm.description}</Typography>
              </Grid>
              <Grid item xs={6}>
                 <Card variant="outlined">
                   <CardContent>
                     <Typography variant="subtitle2" color="text.secondary">Definition</Typography>
                     <Box sx={{ mt: 1, p: 1, bgcolor: '#f5f5f5', borderRadius: 1, fontFamily: 'monospace' }}>
                       {selectedTerm.type === 'calculated' ? selectedTerm.expression : 
                        selectedTerm.type === 'physical' ? `${selectedTerm.properties?.physical_mapping?.table}.${selectedTerm.properties?.physical_mapping?.column}` :
                        selectedTerm.type === 'relationship' ? selectedTerm.properties?.relationship?.join_expression : 
                        'N/A'}
                     </Box>
                   </CardContent>
                 </Card>
              </Grid>
              <Grid item xs={6}>
                 <Card variant="outlined">
                   <CardContent>
                     <Typography variant="subtitle2" color="text.secondary">Lineage</Typography>
                     <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mt: 1 }}>
                       {selectedTerm.properties?.lineage?.map((dep: string) => (
                         <Chip key={dep} label={dep} size="small" />
                       )) || <Typography variant="caption" color="text.secondary">No upstream dependencies</Typography>}
                     </Box>
                   </CardContent>
                 </Card>
              </Grid>
            </Grid>
          )}
        </DialogContent>
      </Dialog>
    </Box>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Box, Typography, Button, Paper, CircularProgress } from '@mui/material';
import { useSearchParams } from 'react-router-dom';
import ModelCatalogSidebar from '../components/UnifiedSemanticBuilder/ModelCatalogSidebar';
import SemanticModelEditor from '../components/UnifiedSemanticBuilder/SemanticModelEditor';
// import SemanticModelOverview from '../components/UnifiedSemanticBuilder/SemanticModelOverview';
import { ModelCatalogNode } from '../types/model';
import { SemanticModel } from '../components/UnifiedSemanticBuilder/types';
import axios from 'axios';
import { toast } from 'sonner';
import { useTenant } from '../contexts/TenantContext';
import { devDebug } from '../utils/devLogger';

// Type definitions matching backend
interface Cube {
  id: string;
  name: string;
  is_system: boolean;
  source_cube_id?: string;
  dimensions: any[];
  measures: any[];
  description?: string;
  source_table: string;
}

const SemanticDataModelBuilderPage: React.FC = () => {
  const [cubes, setCubes] = useState<Cube[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedModel, setSelectedModel] = useState<ModelCatalogNode | null>(null);
  const [activeTab, setActiveTab] = useState<'core' | 'custom'>('core');

  // Fetch cubes
  const fetchCubes = async () => {
    try {
      setLoading(true);
      const response = await axios.get('/api/semantic/cubes', {
        headers: { 'X-Tenant-ID': 'default' } // TODO: Get specific tenant ID
      });
      setCubes(response.data);
      setError(null);
    } catch (err) {
      console.error('Failed to fetch cubes:', err);
      setError('Failed to load semantic models');
      toast.error('Failed to load semantic models');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCubes();
  }, []);

  // Transform cubes to ModelCatalogNodes
  const models: ModelCatalogNode[] = useMemo(() => {
    return cubes.map(cube => {
      const isCustom = !cube.is_system;
      const isCore = cube.is_system;

      // Check if this core model has a custom extension
      const customExtension = cubes.find(c => c.source_cube_id === cube.id);
      // Check if this custom model extends a core model
      const coreParent = cube.source_cube_id ? cubes.find(c => c.id === cube.source_cube_id) : null;

      return {
        id: cube.id,
        model_key: cube.name,
        display_name: cube.name, // Can be enhanced with a display name field if added
        description: cube.description,
        status: 'published', // Simplified for now
        version: 1,
        is_current: true,
        is_core: isCore,
        is_custom: isCustom,
        can_edit: isCustom,
        parent_model_key: coreParent?.name,
        core_model_exists: isCore, // If it's core, it exists. If custom, invalid property?
        custom_model_exists: !!customExtension, // Does a custom version exist?
        created_at: new Date().toISOString(),
        metadata: {
          generator: 'semantic-layer',
          table_count: 1,
          measure_count: cube.measures?.length || 0,
          dimension_count: cube.dimensions?.length || 0,
          can_create: isCore && !customExtension // Can create custom ONLY if one doesn't exist
        },
        resolved_config: {
          id: cube.id,
          name: cube.name,
          dimensions: cube.dimensions || [],
          measures: cube.measures || [],
          filters: [],
          joins: [],
          is_custom: isCustom,
          is_core: isCore,
          description: cube.description,
          source_table: cube.source_table,
          // Add other required SemanticModel properties
        } as SemanticModel // Type casting as quick fix, better to map fully
      };
    });
  }, [cubes]);

  const handleModelSelect = (model: ModelCatalogNode, targetTab: 'core' | 'custom') => {
    setSelectedModel(model);
    setActiveTab(targetTab);
  };

  const [semanticModel, setSemanticModel] = useState<SemanticModel | null>(null);

  useEffect(() => {
    if (selectedModel?.resolved_config) {
      setSemanticModel(selectedModel.resolved_config as SemanticModel);
    } else {
      setSemanticModel(null);
    }
  }, [selectedModel]);

  const updateSemanticElement = (type: string, id: string, updates: any) => {
    if (!semanticModel) return;
    const list = (semanticModel as any)[type] as any[] || [];
    const updatedList = list.map((item: any) => item.id === id ? { ...item, ...updates } : item);
    setSemanticModel({ ...semanticModel, [type]: updatedList });
  };

  const removeSemanticElement = (id: string) => {
    if (!semanticModel) return;
    // SemanticModelEditor passes only ID, so we must find the type
    const types = ['dimensions', 'measures', 'filters', 'joins', 'pre_aggregations'];
    let foundType = '';
    for (const t of types) {
       if ((semanticModel as any)[t]?.some((item: any) => item.id === id)) {
           foundType = t;
           break;
       }
    }
    if (foundType) {
        const list = (semanticModel as any)[foundType] as any[] || [];
        const updatedList = list.filter((item: any) => item.id !== id);
        setSemanticModel({ ...semanticModel, [foundType]: updatedList });
    }
  };

  const toggleElementEdit = (type: string, id: string) => {
      // Implement toggle logic if needed, or just no-op if inline editing isn't crucial
      // For now, no-op or simple log
      devDebug('Toggle edit', type, id);
  };

  const { tenant } = useTenant();
  const tenantId = tenant?.id || 'default';

  const onAdd = (type: 'dimension' | 'measure' | 'filter' | 'join' | 'extends', targetTable?: string | { id: string; qualified_path: string } | null) => {
      if (!semanticModel) return;

      const newId = `${type}_${Date.now()}`;
      const newItem = {
          id: newId,
          name: `new_${type}`,
          title: `New ${type.charAt(0).toUpperCase() + type.slice(1)}`,
          type: 'string', // Default
          is_custom: true, // It's a custom addition
          isEditing: true
      };

      // Handle specific fields based on type if needed
      if (type === 'extends') {
          // Extends is special, handled via onChangeExtends usually
          return;
      }

      const listKey = type + 's'; // dimensions, measures...
      // Handle pluralization exceptions if any (none for these)

      const list = (semanticModel as any)[listKey] as any[] || [];
      const updatedList = [...list, newItem];
      setSemanticModel({ ...semanticModel, [listKey]: updatedList });

      // Ideally scroll to new item or set selection
  };

  const handleCreateCustomModel = async (baseModelKey: string) => {
    // Find base model
    const baseModel = cubes.find(c => c.name === baseModelKey);
    if (!baseModel) return;

    try {
        const newName = `${baseModelKey}_custom`;
        const newCube = {
            name: newName,
            source_table: baseModel.source_table,
            description: `Custom extension of ${baseModelKey}`,
            is_system: false,
            source_cube_id: baseModel.id
        };

        await axios.post('/api/semantic/cubes', newCube, {
             headers: { 'X-Tenant-ID': tenantId }
        });

        toast.success(`Created custom model ${newName}`);
        fetchCubes();
    } catch (err) {
        console.error('Failed to create custom model:', err);
        toast.error('Failed to create custom model');
    }
  };

  const handleSaveModel = async () => {
      if (!semanticModel) return;
      try {
          const cubeUpdate = {
              name: semanticModel.name,
              dimensions: semanticModel.dimensions,
              measures: semanticModel.measures,
              is_system: false,
              source_table: (semanticModel as any).source_table || "", 
              description: semanticModel.description
          };

          await axios.put(`/api/semantic/cubes/${semanticModel.name}`, cubeUpdate, {
               headers: { 'X-Tenant-ID': tenantId }
          });
          toast.success('Model saved successfully');
          fetchCubes();
      } catch (err) {
          console.error("Failed to save model:", err);
          toast.error("Failed to save model");
      }
  };

  return (
    <Box sx={{ display: 'flex', height: '100vh', overflow: 'hidden' }}>
      <Box sx={{ width: '320px', borderRight: '1px solid #e0e0e0', display: 'flex', flexDirection: 'column' }}>
        <ModelCatalogSidebar
          models={models}
          selectedModel={selectedModel}
          setSelectedModel={setSelectedModel as any}
          activeTab={activeTab}
          onModelSelect={handleModelSelect}
          onCreateCustomModel={handleCreateCustomModel}
          loading={loading}
          error={error || undefined}
        />
      </Box>
      <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
        <Box sx={{ p: 2, borderBottom: '1px solid #e0e0e0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <Typography variant="h6">{selectedModel?.display_name || 'Select a Model'}</Typography>
            {semanticModel && activeTab === 'custom' && (
                <Button variant="contained" color="primary" onClick={handleSaveModel}>
                    Save Changes
                </Button>
            )}
        </Box>
        {semanticModel ? (
          <Box sx={{ flex: 1, overflow: 'auto', p: 2 }}>
             {/* Using SemanticModelOverview from existing components */}
             <div className="semantic-model-overview-container">
                {/* Note: SemanticDataModelBuilderPage needs to import SemanticModelOverview */}
             </div>
             {/* Fallback to simple JSON editor or basic list if Overview fails */}
             <SemanticModelEditor
                semanticModel={semanticModel} // Correct prop name
                modelName={semanticModel.name}
                showCode={null}
                onToggleCode={() => {}}
                generateJSON={() => JSON.stringify(semanticModel, null, 2)}
                generateYAML={() => ""}
                updateSemanticElement={updateSemanticElement}
                removeSemanticElement={removeSemanticElement}
                toggleElementEdit={toggleElementEdit}
                onChange={(m) => setSemanticModel(m)} // If Editor supports onChange
                editMode={activeTab === 'custom'}
                // Fill required props
                selectedColumn={null}
                coreOptions={[]}
                onChangeExtends={() => {}}
                onAdd={onAdd}
             />
          </Box>
        ) : (
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'center', height: '100%', color: '#666' }}>
            <Typography variant="h6">Select a model to view or edit</Typography>
          </Box>
        )}
      </Box>
    </Box>
  );
};

export default SemanticDataModelBuilderPage;

import React, { useState, useEffect } from 'react';
import {
  Box,
  Button,
  Card,
  CardContent,
  CircularProgress,
  Grid,
  Typography,
  Alert,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Checkbox,
  Paper,
  Chip,
  Stack,
  Divider,
} from '@mui/material';
import { AutoAwesome, Check, Save } from '@mui/icons-material';
import BusinessEntitySemanticService, { MappingResult } from '../../services/businessEntitySemanticService';
import { useAccess } from '../../contexts/AccessContext';

const SemanticEnrichmentWizard: React.FC = () => {
  const { currentTenant: tenant, currentDatasource: datasource } = useAccess();
  const [mappings, setMappings] = useState<MappingResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [stats, setStats] = useState<{ total: number; selected: number } | null>(null);

  // Get service instance
  const getService = () => {
    if (!tenant?.id || !datasource?.id) {
      throw new Error('Please select a tenant and datasource first.');
    }
    return new BusinessEntitySemanticService(tenant.id, datasource.id);
  };

  useEffect(() => {
    // Update stats whenever mappings change
    const selectedCount = mappings.filter(m => m.selected).length;
    setStats({ total: mappings.length, selected: selectedCount });
  }, [mappings]);

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    setSuccess(null);
    setMappings([]);

    try {
      const service = getService();
      const results = await service.generateSemanticMappings();
      // Ensure results are typed correctly or mapped if needed
      if (Array.isArray(results)) {
         setMappings(results.map((m: any) => ({ ...m, selected: m.confidence > 0.7 }))); // Default select high confidence
      } else {
         // Handle case where API might return wrapped object
         setMappings([]);
         setError("Unexpected API response format");
      }
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Failed to generate mappings.');
    } finally {
      setLoading(false);
    }
  };

  const handleApply = async () => {
    const selectedMappings = mappings.filter(m => m.selected);
    if (selectedMappings.length === 0) return;

    setLoading(true);
    setError(null);
    setSuccess(null);

    try {
      const service = getService();
      const result = await service.applySemanticMappings(selectedMappings);
      setSuccess(`Successfully applied ${result.applied_count} mappings!`);
      // Update local state to reflect changes (maybe remove applied ones or mark them)
      // For now, clear the list or re-fetch could be options. Let's keep them but show success.
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Failed to apply mappings.');
    } finally {
      setLoading(false);
    }
  };

  const handleToggleSelect = (index: number) => {
    setMappings(prev => {
      const newMappings = [...prev];
      newMappings[index] = { ...newMappings[index], selected: !newMappings[index].selected };
      return newMappings;
    });
  };

  const handleSelectAll = (select: boolean) => {
      setMappings(prev => prev.map(m => ({ ...m, selected: select })));
  };

  return (
    <Box sx={{ p: 3 }}>
      <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 3 }}>
        <Box>
          <Typography variant="h4" component="h1" gutterBottom>
            Semantic Enrichment Wizard
          </Typography>
          <Typography variant="body1" color="text.secondary">
            Automatically discover and apply semantic terms to your database columns using AI and pattern matching.
          </Typography>
          {tenant && datasource ? (
             <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                Context: <strong>{tenant.name}</strong> / <strong>{datasource.source_name}</strong>
             </Typography>
          ) : (
             <Alert severity="warning" sx={{ mt: 2 }}>
                Please select a Tenant and Datasource to proceed.
             </Alert>
          )}
        </Box>
        <Button
          variant="contained"
          size="large"
          startIcon={loading ? <CircularProgress size={20} color="inherit" /> : <AutoAwesome />}
          onClick={handleGenerate}
          disabled={loading || !tenant || !datasource}
        >
          {loading ? 'Analyzing...' : 'Run Analysis'}
        </Button>
      </Stack>

      {error && <Alert severity="error" sx={{ mb: 3 }}>{error}</Alert>}
      {success && <Alert severity="success" sx={{ mb: 3 }}>{success}</Alert>}

      {mappings.length > 0 && (
        <Card>
          <CardContent>
            <Stack direction="row" justifyContent="space-between" alignItems="center" sx={{ mb: 2 }}>
              <Typography variant="h6">
                Recommendations ({stats?.selected} selected / {stats?.total} total)
              </Typography>
              <Box>
                  <Button onClick={() => handleSelectAll(true)} sx={{ mr: 1 }}>Select All</Button>
                  <Button onClick={() => handleSelectAll(false)} sx={{ mr: 2 }}>Deselect All</Button>
                  <Button
                    variant="contained"
                    color="primary"
                    startIcon={<Save />}
                    onClick={handleApply}
                    disabled={loading || (stats?.selected === 0)}
                  >
                    Apply Selected
                  </Button>
              </Box>
            </Stack>

            <TableContainer component={Paper} variant="outlined" sx={{ maxHeight: 600 }}>
              <Table stickyHeader>
                <TableHead>
                  <TableRow>
                    <TableCell padding="checkbox">
                      <Checkbox
                        indeterminate={mappings.some(m => m.selected) && !mappings.every(m => m.selected)}
                        checked={mappings.length > 0 && mappings.every(m => m.selected)}
                        onChange={(e) => handleSelectAll(e.target.checked)}
                      />
                    </TableCell>
                    <TableCell>Table / Column</TableCell>
                    <TableCell>Suggested Semantic Term</TableCell>
                    <TableCell>Confidence</TableCell>
                    <TableCell>Reason</TableCell>
                    <TableCell>Status</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {mappings.map((mapping, index) => (
                    <TableRow key={index} hover selected={mapping.selected}>
                      <TableCell padding="checkbox">
                        <Checkbox
                          checked={mapping.selected}
                          onChange={() => handleToggleSelect(index)}
                        />
                      </TableCell>
                      <TableCell>
                        <Stack>
                            <Typography variant="body2" fontWeight="bold">{mapping.database_column?.table}</Typography>
                            <Typography variant="caption" color="text.secondary">{mapping.database_column?.column} ({mapping.database_column?.data_type})</Typography>
                        </Stack>
                      </TableCell>
                      <TableCell>
                        <Chip
                            label={mapping.semantic_term}
                            color="info"
                            variant={mapping.is_new_term ? "outlined" : "filled"}
                            size="small"
                        />
                         {mapping.is_new_term && <Typography variant="caption" display="block" color="text.secondary">New Term</Typography>}
                      </TableCell>
                      <TableCell>
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                           <CircularProgress
                                variant="determinate"
                                value={mapping.confidence * 100}
                                color={mapping.confidence > 0.8 ? "success" : mapping.confidence > 0.5 ? "warning" : "error"}
                                size={24}
                                sx={{ mr: 1 }}
                            />
                            <Typography variant="body2">{Math.round(mapping.confidence * 100)}%</Typography>
                        </Box>
                      </TableCell>
                      <TableCell>
                        <Typography variant="body2" sx={{ maxWidth: 300 }}>
                            {mapping.match_reason || mapping.match_reason || "Pattern Match"}
                        </Typography>
                      </TableCell>
                      <TableCell>
                         {mapping.edge_exists ? (
                             <Chip icon={<Check />} label="Linked" color="success" size="small" variant="outlined" />
                         ) : (
                             <Chip label="Unlinked" color="default" size="small" variant="outlined" />
                         )}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </CardContent>
        </Card>
      )}

      {mappings.length === 0 && !loading && !error && (
        <Box sx={{ mt: 5, textAlign: 'center', color: 'text.secondary' }}>
             <Typography variant="h6">No mappings generated yet.</Typography>
             <Typography>Click "Run Analysis" to start discovery.</Typography>
        </Box>
      )}
    </Box>
  );
};

export default SemanticEnrichmentWizard;

