        const otherNodeId = isSource ? e.target : e.source;
        const otherNode = nodes.find(n => n.id === otherNodeId);
        return {
            edge: e,
            otherNode,
            direction: isSource ? 'outgoing' : 'incoming',
            type: e.data?.relationship_type || 'Related to'
