                        <LinearProgress
                          variant="determinate"
                          value={scenario.overall_score * 100}
                          color={scenario.overall_score > 0.7 ? 'success' : 'primary'}
                          sx={{ mt: 0.5 }}
                        />
                      </Box>
                    </TableCell>
                    <TableCell align="center">
                      <IconButton
                        size="small"
                        onClick={() => setNarrativeDialog(scenario)}
                        disabled={!scenario.narrative_explanation}
                      >
                        <Visibility fontSize="small" />
                      </IconButton>
                    </TableCell>
                  </TableRow>

                  {/* Expanded Row */}
                  <TableRow>
                    <TableCell style={{ paddingBottom: 0, paddingTop: 0 }} colSpan={10}>
                      <Collapse in={expandedRow === scenario.scenario_id} timeout="auto" unmountOnExit>
                        <Box sx={{ py: 2, px: 3, bgcolor: 'grey.50' }}>
                          <Typography variant="subtitle2" gutterBottom>
                            Structures Used:
                          </Typography>
                          <Box sx={{ display: 'flex', gap: 1, mb: 2 }}>
                            {scenario.structures_used.map((structure, i) => (
                              <Chip key={i} label={structure} size="small" variant="outlined" />
                            ))}
                          </Box>

                          {scenario.narrative_explanation && (
                            <Box sx={{ mt: 2 }}>
                              <Typography variant="subtitle2" gutterBottom>
                                Summary:
                              </Typography>
                              <Typography variant="body2" color="text.secondary" sx={{ whiteSpace: 'pre-line' }}>
                                {scenario.narrative_explanation.substring(0, 300)}...
                              </Typography>
                              <Button size="small" sx={{ mt: 1 }} onClick={() => setNarrativeDialog(scenario)}>
                                Read Full Explanation
                              </Button>
                            </Box>
                          )}
                        </Box>
                      </Collapse>
                    </TableCell>
                  </TableRow>
                </React.Fragment>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}

      {/* Narrative Dialog */}
      <Dialog
        open={narrativeDialog !== null}
        onClose={() => setNarrativeDialog(null)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>
          {narrativeDialog?.scenario_name} - Detailed Explanation
        </DialogTitle>
        <DialogContent dividers>
          <Typography variant="body1" sx={{ whiteSpace: 'pre-line', lineHeight: 1.8 }}>
            {narrativeDialog?.narrative_explanation}
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setNarrativeDialog(null)}>Close</Button>
          <Button variant="contained" startIcon={<Download />}>
            Download PDF
          </Button>
        </DialogActions>
      </Dialog>

      {/* Comparison Summary (when multiple selected) */}
      {selectedScenarios.length >= 2 && (
        <Paper elevation={3} sx={{ mt: 3, p: 3 }}>
          <Typography variant="h6" gutterBottom>
            Comparison Summary
          </Typography>
          <Box sx={{ display: 'flex', gap: 4 }}>
            <Box>
              <Typography variant="caption" color="text.secondary">
                Best Tax Savings
              </Typography>
              <Typography variant="h6" color="success.main">
                {formatCurrency(Math.max(...selectedScenarios.map(s => s.tax_savings)))}
              </Typography>
            </Box>
            <Box>
              <Typography variant="caption" color="text.secondary">
                Simplest Option
              </Typography>
              <Typography variant="h6">
                {Math.min(...selectedScenarios.map(s => s.complexity_score))}/10
              </Typography>
            </Box>
            <Box>
              <Typography variant="caption" color="text.secondary">
                Lowest Annual Cost
              </Typography>
              <Typography variant="h6">
                ${(Math.min(...selectedScenarios.map(s => s.annual_cost)) / 1000).toFixed(0)}K/yr
              </Typography>
            </Box>
            <Box>
              <Typography variant="caption" color="text.secondary">
                Fastest Implementation
              </Typography>
              <Typography variant="h6">
                {Math.min(...selectedScenarios.map(s => s.implementation_weeks))} weeks
              </Typography>
            </Box>
          </Box>
        </Paper>
      )}
    </Box>
  );
};

import React, { useState } from 'react';
import {
  Box,
  Paper,
  Typography,
  TextField,
  Button,
  Grid,
  Card,
  CardContent,
  Slider,
  MenuItem,
  Divider,
  Table,
  TableBody,
  TableCell,
  TableRow,
  Alert,
  Chip,
} from '@mui/material';
import {
  Calculate as CalculateIcon,
  TrendingUp as GrowthIcon,
  AttachMoney as MoneyIcon,
} from '@mui/icons-material';

interface TaxCalculatorProps {
  familyId: string;
}

export const TaxCalculator: React.FC<TaxCalculatorProps> = ({ familyId }) => {
  const [inputs, setInputs] = useState({
    grossEstate: 25000000,
    state: 'NY',
    priorGifts: 0,
    charitableDeductions: 0,
    spouseAlive: true,
    growthRate: 7,
    yearsToProject: 10,
  });

  const [results, setResults] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  const calculateTax = async () => {
    setLoading(true);
    try {
      // Calculate federal tax
      const federalResponse = await fetch('/api/wealth-transfer/tax/estate/federal', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          gross_estate_value: inputs.grossEstate,
          prior_lifetime_gifts: inputs.priorGifts,
          charitable_deductions: inputs.charitableDeductions,
        }),
      });
      const federalData = await federalResponse.json();

      // Calculate state tax
      const stateResponse = await fetch('/api/wealth-transfer/tax/estate/state', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          gross_estate_value: inputs.grossEstate,
          state_code: inputs.state,
        }),
      });
      const stateData = await stateResponse.json();

      setResults({
        federal: federalData,
        state: stateData,
        combined: federalData.tax_owed + stateData.tax_owed,
        effectiveRate: ((federalData.tax_owed + stateData.tax_owed) / inputs.grossEstate) * 100,
      });
    } catch (error) {
      console.error('Failed to calculate tax:', error);
    } finally {
      setLoading(false);
    }
  };

  const calculateFutureValue = () => {
    const fv = inputs.grossEstate * Math.pow(1 + inputs.growthRate / 100, inputs.yearsToProject);
    return fv;
  };

  const calculateProjectedTax = () => {
    const futureValue = calculateFutureValue();
    const federalExemption = 13990000;
    const taxableAmount = Math.max(0, futureValue - federalExemption - inputs.priorGifts);
    const federalTax = taxableAmount * 0.40;

    // Simplified state tax
    const stateTax = futureValue > 6000000 ? (futureValue - 6000000) * 0.16 : 0;

    return federalTax + stateTax;
  };

  const formatCurrency = (value: number): string => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(value);
  };

  const stateOptions = [
    { code: 'CA', name: 'California' },
    { code: 'NY', name: 'New York' },
    { code: 'FL', name: 'Florida' },
    { code: 'TX', name: 'Texas' },
    { code: 'CT', name: 'Connecticut' },
    { code: 'MA', name: 'Massachusetts' },
    { code: 'IL', name: 'Illinois' },
    { code: 'WA', name: 'Washington' },
  ];

  return (
    <Box>
      <Typography variant="h6" gutterBottom>
        Estate Tax Calculator & Projections
      </Typography>

      <Grid container spacing={3}>
        {/* Input Panel */}
        <Grid item xs={12} md={6}>
          <Paper elevation={2} sx={{ p: 3 }}>
            <Typography variant="subtitle1" gutterBottom fontWeight="bold">
              Current Situation
            </Typography>

            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2.5 }}>
              <TextField
                label="Gross Estate Value"
                type="number"
                value={inputs.grossEstate}
                onChange={(e) => setInputs({ ...inputs, grossEstate: parseFloat(e.target.value) || 0 })}
                InputProps={{
                  startAdornment: <MoneyIcon sx={{ mr: 1, color: 'grey.500' }} />,
                }}
                fullWidth
              />

              <TextField
                label="Primary State"
                select
                value={inputs.state}
                onChange={(e) => setInputs({ ...inputs, state: e.target.value })}
                fullWidth
              >
                {stateOptions.map((state) => (
                  <MenuItem key={state.code} value={state.code}>
                    {state.name}
                  </MenuItem>
                ))}
              </TextField>

              <TextField
                label="Prior Lifetime Gifts"
                type="number"
                value={inputs.priorGifts}
                onChange={(e) => setInputs({ ...inputs, priorGifts: parseFloat(e.target.value) || 0 })}
                InputProps={{
                  startAdornment: <MoneyIcon sx={{ mr: 1, color: 'grey.500' }} />,
                }}
                fullWidth
              />

              <TextField
                label="Charitable Deductions"
                type="number"
                value={inputs.charitableDeductions}
                onChange={(e) => setInputs({ ...inputs, charitableDeductions: parseFloat(e.target.value) || 0 })}
                InputProps={{
                  startAdornment: <MoneyIcon sx={{ mr: 1, color: 'grey.500' }} />,
                }}
                fullWidth
              />

              <TextField
                label="Spouse Status"
                select
                value={inputs.spouseAlive.toString()}
                onChange={(e) => setInputs({ ...inputs, spouseAlive: e.target.value === 'true' })}
                fullWidth
              >
                <MenuItem value="true">Spouse Alive (Portability Available)</MenuItem>
                <MenuItem value="false">Single / Widowed</MenuItem>
              </TextField>

              <Divider />

              <Typography variant="subtitle2" gutterBottom>
                Projection Parameters
              </Typography>

              <Box>
                <Typography variant="caption" gutterBottom display="block">
                  Annual Growth Rate: {inputs.growthRate}%
                </Typography>
                <Slider
                  value={inputs.growthRate}
                  onChange={(_, value) => setInputs({ ...inputs, growthRate: value as number })}
                  min={0}
                  max={15}
                  step={0.5}
                  marks={[
                    { value: 0, label: '0%' },
                    { value: 7, label: '7%' },
                    { value: 15, label: '15%' },
                  ]}
                  valueLabelDisplay="auto"
                />
              </Box>

              <Box>
                <Typography variant="caption" gutterBottom display="block">
                  Years to Project: {inputs.yearsToProject}
                </Typography>
                <Slider
                  value={inputs.yearsToProject}
                  onChange={(_, value) => setInputs({ ...inputs, yearsToProject: value as number })}
                  min={1}
                  max={30}
                  step={1}
                  marks={[
                    { value: 1, label: '1y' },
                    { value: 10, label: '10y' },
                    { value: 30, label: '30y' },
                  ]}
                  valueLabelDisplay="auto"
                />
              </Box>

              <Button
                variant="contained"
                size="large"
                startIcon={<CalculateIcon />}
                onClick={calculateTax}
                disabled={loading}
                fullWidth
              >
                {loading ? 'Calculating...' : 'Calculate Tax'}
              </Button>
            </Box>
          </Paper>
        </Grid>

        {/* Results Panel */}
        <Grid item xs={12} md={6}>
          <Paper elevation={2} sx={{ p: 3, height: '100%' }}>
            <Typography variant="subtitle1" gutterBottom fontWeight="bold">
              Tax Calculation Results
            </Typography>

            {!results ? (
              <Alert severity="info" sx={{ mt: 2 }}>
                Enter your estate details and click "Calculate Tax" to see results.
              </Alert>
            ) : (
              <Box sx={{ mt: 2 }}>
                {/* Current Tax */}
                <Card variant="outlined" sx={{ mb: 2 }}>
                  <CardContent>
                    <Typography variant="subtitle2" color="text.secondary" gutterBottom>
                      Current Estate Tax (Today)
                    </Typography>
                    <Typography variant="h3" color="error" gutterBottom>
                      {formatCurrency(results.combined)}
                    </Typography>
                    <Chip
                      label={`Effective Rate: ${results.effectiveRate.toFixed(1)}%`}
                      color="error"
                      size="small"
                    />
                  </CardContent>
                </Card>

                {/* Tax Breakdown Table */}
                <Table size="small">
                  <TableBody>
                    <TableRow>
                      <TableCell><strong>Gross Estate</strong></TableCell>
                      <TableCell align="right">{formatCurrency(inputs.grossEstate)}</TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell>Less: Charitable Deductions</TableCell>
                      <TableCell align="right">-{formatCurrency(inputs.charitableDeductions)}</TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell>Less: Federal Exemption</TableCell>
                      <TableCell align="right">-{formatCurrency(13990000)}</TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell><strong>Taxable Estate (Federal)</strong></TableCell>
                      <TableCell align="right"><strong>{formatCurrency(results.federal.taxable_amount)}</strong></TableCell>
                    </TableRow>
                    <TableRow sx={{ bgcolor: 'error.50' }}>
                      <TableCell><strong>Federal Estate Tax (40%)</strong></TableCell>
                      <TableCell align="right"><strong>{formatCurrency(results.federal.tax_owed)}</strong></TableCell>
                    </TableRow>
                    <TableRow sx={{ bgcolor: 'warning.50' }}>
                      <TableCell><strong>State Estate Tax ({inputs.state})</strong></TableCell>
                      <TableCell align="right"><strong>{formatCurrency(results.state.tax_owed)}</strong></TableCell>
                    </TableRow>
                    <TableRow sx={{ bgcolor: 'error.100' }}>
                      <TableCell><strong>Total Estate Tax</strong></TableCell>
                      <TableCell align="right"><strong>{formatCurrency(results.combined)}</strong></TableCell>
                    </TableRow>
                  </TableBody>
                </Table>

                <Divider sx={{ my: 2 }} />

                {/* Future Projection */}
                <Card variant="outlined" sx={{ bgcolor: 'success.50' }}>
                  <CardContent>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 1 }}>
                      <GrowthIcon color="success" />
                      <Typography variant="subtitle2" color="text.secondary">
                        Projected in {inputs.yearsToProject} Years
                      </Typography>
                    </Box>
                    <Typography variant="body2" gutterBottom>
                      <strong>Estate Value:</strong> {formatCurrency(calculateFutureValue())}
                    </Typography>
                    <Typography variant="body2" gutterBottom>
                      <strong>Projected Tax:</strong> {formatCurrency(calculateProjectedTax())}
                    </Typography>
                    <Alert severity="warning" sx={{ mt: 2 }}>
                      <Typography variant="caption">
                        Without planning, estate could grow to {formatCurrency(calculateFutureValue())}, 
                        resulting in {formatCurrency(calculateProjectedTax())} in estate taxes.
                      </Typography>
                    </Alert>
                  </CardContent>
                </Card>
              </Box>
            )}
          </Paper>
        </Grid>

        {/* Tax Savings Scenarios */}
        {results && (
          <Grid item xs={12}>
            <Paper elevation={2} sx={{ p: 3 }}>
              <Typography variant="subtitle1" gutterBottom fontWeight="bold">
                Potential Tax Savings with Planning
              </Typography>

              <Grid container spacing={2} sx={{ mt: 1 }}>
                <Grid item xs={12} md={4}>
                  <Card variant="outlined">
                    <CardContent>
                      <Typography variant="subtitle2" gutterBottom>
                        Annual Gifting Strategy
                      </Typography>
                      <Typography variant="h5" color="success.main">
                        Save {formatCurrency(results.combined * 0.30)}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        ~30% tax reduction through systematic gifting
                      </Typography>
                    </CardContent>
                  </Card>
                </Grid>

                <Grid item xs={12} md={4}>
                  <Card variant="outlined">
                    <CardContent>
                      <Typography variant="subtitle2" gutterBottom>
                        SLAT + Gifting Combination
                      </Typography>
                      <Typography variant="h5" color="success.main">
                        Save {formatCurrency(results.combined * 0.60)}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        ~60% tax reduction with comprehensive planning
                      </Typography>
                    </CardContent>
                  </Card>
                </Grid>

                <Grid item xs={12} md={4}>
                  <Card variant="outlined">
                    <CardContent>
                      <Typography variant="subtitle2" gutterBottom>
                        Dynasty Trust (Multi-Gen)
                      </Typography>
                      <Typography variant="h5" color="success.main">
                        Save {formatCurrency(results.combined * 1.5)}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        Estate tax eliminated across 3 generations
                      </Typography>
                    </CardContent>
                  </Card>
                </Grid>
              </Grid>

              <Alert severity="info" sx={{ mt: 2 }}>
                Click "Generate Estate Plan" from the main dashboard to get personalized recommendations.
              </Alert>
            </Paper>
          </Grid>
        )}
      </Grid>
    </Box>
  );
};

import React, { useState, useEffect } from 'react';
import {
  Box,
  Paper,
  Typography,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  MenuItem,
  Grid,
  Card,
  CardContent,
  Alert,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  Divider,
} from '@mui/material';
import {
  Add as AddIcon,
  CheckCircle as CheckIcon,
  Warning as WarningIcon,
  Error as ErrorIcon,
  Gavel as TrustIcon,
} from '@mui/icons-material';
import { format } from 'date-fns';

interface Trust {
  entity_id: string;
  entity_name: string;
  entity_type: string;
  formation_date: string;
  formation_state: string;
  is_revocable: boolean;
  current_value: number;
  tax_id_number?: string;
  grantor_names: string[];
  trustee_names: string[];
  beneficiary_names: string[];
  last_tax_filing_date?: string;
  next_tax_filing_due?: string;
}

interface ComplianceIssue {
  issue_type: string;
  severity: 'ERROR' | 'WARNING' | 'INFO';
  description: string;
  recommendation: string;
}

interface TrustManagementPanelProps {
  familyId: string;
}

export const TrustManagementPanel: React.FC<TrustManagementPanelProps> = ({ familyId }) => {
  const [trusts, setTrusts] = useState<Trust[]>([]);
  const [selectedTrust, setSelectedTrust] = useState<Trust | null>(null);
  const [complianceIssues, setComplianceIssues] = useState<ComplianceIssue[]>([]);
  const [newTrustDialog, setNewTrustDialog] = useState(false);
  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState({
    entity_type: 'SLAT',
    entity_name: '',
    formation_date: format(new Date(), 'yyyy-MM-dd'),
    formation_state: 'CA',
    is_revocable: false,
    grantor_member_ids: [] as string[],
    trustee_member_ids: [] as string[],
    beneficiary_member_ids: [] as string[],
  });

  useEffect(() => {
    loadTrusts();
  }, [familyId]);

  const loadTrusts = async () => {
    try {
      const response = await fetch(`/api/wealth-transfer/families/${familyId}/trusts`);
      const data = await response.json();
      setTrusts(data || []);
    } catch (error) {
      console.error('Failed to load trusts:', error);
    }
  };

  const loadComplianceIssues = async (trustId: string) => {
    try {
      const response = await fetch(`/api/wealth-transfer/trusts/${trustId}/compliance`);
      const data = await response.json();
      setComplianceIssues(data.issues || []);
    } catch (error) {
      console.error('Failed to load compliance issues:', error);
    }
  };

  const handleCreateTrust = async () => {
    setLoading(true);
    try {
      const response = await fetch('/api/wealth-transfer/trusts', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          ...formData,
          family_id: familyId,
        }),
      });

      if (response.ok) {
        setNewTrustDialog(false);
        loadTrusts();
        setFormData({
          entity_type: 'SLAT',
          entity_name: '',
          formation_date: format(new Date(), 'yyyy-MM-dd'),
          formation_state: 'CA',
          is_revocable: false,
          grantor_member_ids: [],
          trustee_member_ids: [],
          beneficiary_member_ids: [],
        });
      }
    } catch (error) {
      console.error('Failed to create trust:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleViewTrust = async (trust: Trust) => {
    setSelectedTrust(trust);
    await loadComplianceIssues(trust.entity_id);
  };

  const formatCurrency = (value: number): string => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(value);
  };

  const getTrustTypeDescription = (type: string): string => {
    const descriptions: { [key: string]: string } = {
      'SLAT': 'Spousal Lifetime Access Trust',
      'GRAT': 'Grantor Retained Annuity Trust',
      'QPRT': 'Qualified Personal Residence Trust',
      'ILIT': 'Irrevocable Life Insurance Trust',
      'DYNASTY_TRUST': 'Dynasty Trust',
      'CRT': 'Charitable Remainder Trust',
      'CLT': 'Charitable Lead Trust',
      'QTIP': 'Qualified Terminable Interest Property Trust',
      'GST': 'Generation-Skipping Trust',
      'SNT': 'Special Needs Trust',
    };
    return descriptions[type] || type;
  };

  const getSeverityIcon = (severity: string) => {
    switch (severity) {
      case 'ERROR':
        return <ErrorIcon color="error" />;
      case 'WARNING':
        return <WarningIcon color="warning" />;
      default:
        return <CheckIcon color="info" />;
    }
  };

  const getSeverityColor = (severity: string): 'error' | 'warning' | 'success' => {
    switch (severity) {
      case 'ERROR':
        return 'error';
      case 'WARNING':
        return 'warning';
      default:
        return 'success';
    }
  };

  return (
    <Box>
      {/* Header */}
      <Box sx={{ display: 'flex', gap: 2, mb: 3, alignItems: 'center' }}>
        <Typography variant="h6">Trust & Entity Management</Typography>
        <Box sx={{ flexGrow: 1 }} />
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => setNewTrustDialog(true)}
        >
          Create New Trust
        </Button>
      </Box>

      {/* Summary Cards */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} md={4}>
          <Card elevation={2}>
            <CardContent>
              <Typography color="text.secondary" gutterBottom variant="body2">
                Total Trusts
              </Typography>
              <Typography variant="h4">
                {trusts.length}
              </Typography>
              <Typography variant="caption" color="text.secondary">
                Across {new Set(trusts.map(t => t.entity_type)).size} different types
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} md={4}>
          <Card elevation={2}>
            <CardContent>
              <Typography color="text.secondary" gutterBottom variant="body2">
                Total Trust Value
              </Typography>
              <Typography variant="h4">
                {formatCurrency(trusts.reduce((sum, t) => sum + t.current_value, 0))}
              </Typography>
              <Typography variant="caption" color="text.secondary">
                Aggregate across all trusts
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} md={4}>
          <Card elevation={2}>
            <CardContent>
              <Typography color="text.secondary" gutterBottom variant="body2">
                Compliance Status
              </Typography>
              <Typography variant="h4" color={trusts.filter(t => !t.tax_id_number && !t.is_revocable).length > 0 ? 'error' : 'success'}>
                {trusts.filter(t => t.tax_id_number || t.is_revocable).length}/{trusts.length}
              </Typography>
              <Typography variant="caption" color="text.secondary">
                Trusts in good standing
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Trusts Table */}
      <TableContainer component={Paper} elevation={2}>
        <Table>
          <TableHead>
            <TableRow sx={{ bgcolor: 'grey.100' }}>
              <TableCell><strong>Trust Name</strong></TableCell>
              <TableCell><strong>Type</strong></TableCell>
              <TableCell><strong>Formation Date</strong></TableCell>
              <TableCell align="right"><strong>Value</strong></TableCell>
              <TableCell><strong>Status</strong></TableCell>
              <TableCell><strong>Tax Filing</strong></TableCell>
              <TableCell><strong>Actions</strong></TableCell>
