            setLoading(false);
        }
    };

    const handleNewEndpoint = (bo: any) => {
        setEditingEndpoint({
            env,
            tenant_id: tenantId,
            bo_name: bo.name,
            name: `${bo.name} API`,
            path: `/api/v1/${bo.name.toLowerCase()}`,
            method: 'GET',
            type: 'rest',
            fields: [],
            filters: {},
            pagination: { type: 'offset', default_limit: 100 }
