import React, { useState, useRef, useEffect } from 'react';
import { Box, Typography, TextField, Button, Paper, CircularProgress, IconButton, Avatar, Tooltip, Zoom } from '@mui/material';
import { Send as SendIcon, SmartToy as BotIcon, Person as UserIcon, AutoAwesome as AIIcon, Psychology as BrainIcon } from '@mui/icons-material';
import { motion, AnimatePresence } from 'framer-motion';
import { ApiStudioApi } from '../../api/apiStudio';
import { APIEndpoint } from '../../types/apiStudio';

interface NLDesignInterfaceProps {
    tenantId: string;
    onProposalGenerated: (proposal: APIEndpoint) => void;
}

interface Message {
    role: 'user' | 'assistant';
    content: string;
    isThinking?: boolean;
}

const NLDesignInterface: React.FC<NLDesignInterfaceProps> = ({ tenantId, onProposalGenerated }) => {
    const [prompt, setPrompt] = useState('');
    const [messages, setMessages] = useState<Message[]>([
        { role: 'assistant', content: "Hello! I'm your AI API Architect. Describe the data surface you want to expose, and I'll design a governed endpoint spec for you." }
    ]);
    const [loading, setLoading] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    };

    useEffect(() => {
        scrollToBottom();
    }, [messages]);

    const handleSend = async () => {
        if (!prompt.trim()) return;

        const userMsg: Message = { role: 'user', content: prompt };
        setMessages(prev => [...prev, userMsg]);
        setLoading(true);
        const currentPrompt = prompt;
        setPrompt('');

        try {
            const proposal = await ApiStudioApi.generateEndpointWithAI(currentPrompt, tenantId);
            setMessages(prev => [...prev, { 
                role: 'assistant', 
                content: `Architected the "${proposal.name}" endpoint. I've optimized the filters and fields based on the semantic layer mapping. You can review the full spec in the editor.` 
            }]);
            onProposalGenerated(proposal);
        } catch (err) {
            setMessages(prev => [...prev, { role: 'assistant', content: "I hit a snag while designing that endpoint. Could you provide a bit more detail on the entities involved?" }]);
        } finally {
            setLoading(false);
        }
    };

    return (
        <Paper elevation={0} sx={{ height: '100%', display: 'flex', flexDirection: 'column', borderRadius: 4, overflow: 'hidden', background: 'rgba(255, 255, 255, 0.4)', backdropFilter: 'blur(30px)', border: '1px solid rgba(255, 255, 255, 0.4)', boxShadow: '0 8px 32px rgba(0,0,0,0.05)' }}>
            <Box sx={{ p: 2, background: 'rgba(255, 255, 255, 0.6)', borderBottom: '1px solid rgba(0,0,0,0.05)', display: 'flex', alignItems: 'center', gap: 1.5 }}>
                <Avatar sx={{ width: 32, height: 32, bgcolor: 'primary.main', boxShadow: '0 2px 8px rgba(33, 150, 243, 0.3)' }}>
                    <AIIcon sx={{ fontSize: 18, color: 'white' }} />
                </Avatar>
                <Box>
                    <Typography variant="subtitle2" fontWeight="bold">AI Design Partner</Typography>
                    <Typography variant="caption" color="textSecondary" sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                        <BrainIcon sx={{ fontSize: 10 }} /> Governed Spec Generation
                    </Typography>
                </Box>
            </Box>

            <Box sx={{ flex: 1, overflowY: 'auto', p: { xs: 2, md: 3 }, display: 'flex', flexDirection: 'column', gap: 3 }}>
                <AnimatePresence>
                    {messages.map((msg, i) => (
                        <motion.div key={i} initial={{ opacity: 0, x: msg.role === 'user' ? 20 : -20 }} animate={{ opacity: 1, x: 0 }} transition={{ duration: 0.3 }} style={{ alignSelf: msg.role === 'user' ? 'flex-end' : 'flex-start', maxWidth: '85%' }}>
                            <Box sx={{ display: 'flex', gap: 1.5, flexDirection: msg.role === 'user' ? 'row-reverse' : 'row' }}>
                                <Avatar sx={{ width: 28, height: 28, bgcolor: msg.role === 'user' ? 'primary.main' : 'white', border: '1px solid rgba(0,0,0,0.05)', color: msg.role === 'user' ? 'white' : 'primary.main', fontSize: '0.75rem', fontWeight: 'bold' }}>
                                    {msg.role === 'user' ? <UserIcon sx={{ fontSize: 14 }} /> : <BotIcon sx={{ fontSize: 14 }} />}
                                </Avatar>
                                <Paper sx={{ p: 1.5, borderRadius: msg.role === 'user' ? '15px 4px 15px 15px' : '4px 15px 15px 15px', bgcolor: msg.role === 'user' ? 'primary.main' : 'white', color: msg.role === 'user' ? 'white' : '#334155', boxShadow: '0 2px 10px rgba(0,0,0,0.03)', border: msg.role === 'user' ? 'none' : '1px solid rgba(0,0,0,0.05)' }}>
                                    <Typography variant="body2" sx={{ lineHeight: 1.5 }}>{msg.content}</Typography>
                                </Paper>
                            </Box>
                        </motion.div>
                    ))}
                </AnimatePresence>
                {loading && (
                    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
                        <Box sx={{ display: 'flex', gap: 1.5 }}>
                            <Avatar sx={{ width: 28, height: 28, bgcolor: 'secondary.main', color: 'white' }}>
                                <BotIcon sx={{ fontSize: 14 }} />
                            </Avatar>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, bgcolor: 'rgba(0,0,0,0.03)', px: 2, py: 1, borderRadius: 2 }}>
                                <CircularProgress size={12} thickness={6} />
                                <Typography variant="caption" fontWeight="bold" color="textSecondary">Reasoning about entities...</Typography>
                            </Box>
                        </Box>
                    </motion.div>
                )}
                <div ref={messagesEndRef} />
            </Box>

            <Box sx={{ p: 2, background: 'rgba(255, 255, 255, 0.8)', borderTop: '1px solid rgba(0,0,0,0.05)' }}>
                <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
                    <TextField
                        fullWidth
                        size="small"
                        placeholder="Suggest an API for trade analysis..."
                        value={prompt}
                        onChange={(e) => setPrompt(e.target.value)}
                        onKeyPress={(e) => {
                            if (e.key === 'Enter' && !e.shiftKey) {
                                e.preventDefault();
                                handleSend();
                            }
                        }}
                        disabled={loading}
                        sx={{ '& .MuiOutlinedInput-root': { borderRadius: 3, bgcolor: '#f1f5f9', '&:hover': { bgcolor: '#e2e8f0' }, '&.Mui-focused': { bgcolor: 'white' } } }}
                    />
                    <Tooltip title="Send Request" TransitionComponent={Zoom}>
                        <IconButton color="primary" onClick={handleSend} disabled={loading || !prompt.trim()} sx={{ bgcolor: prompt.trim() ? 'primary.main' : 'transparent', color: prompt.trim() ? 'white' : 'inherit', '&:hover': { bgcolor: prompt.trim() ? 'primary.dark' : 'transparent' } }}>
                            <SendIcon sx={{ fontSize: 20 }} />
                        </IconButton>
                    </Tooltip>
                </Box>
                <Typography variant="caption" color="textSecondary" sx={{ mt: 1, display: 'block', textAlign: 'center', fontSize: '0.65rem' }}>
                    SemLayer Enterprise Design AI • Dialect Optimized
                </Typography>
            </Box>
        </Paper>
    );
};

export default NLDesignInterface;

import React, { useState, useEffect } from 'react';
import { Box, Typography, Paper, Grid, Card, CardContent, CircularProgress, Chip, LinearProgress } from '@mui/material';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar } from 'recharts';
import { APIEndpoint } from '../../types/apiStudio';
import { ApiStudioApi } from '../../api/apiStudio';

interface UsageDashboardProps {
    endpoint: Partial<APIEndpoint>;
}

const UsageDashboard: React.FC<UsageDashboardProps> = ({ endpoint }) => {
    const [metrics, setMetrics] = useState<any>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchMetrics = async () => {
            if (!endpoint.id) return;
            setLoading(true);
            try {
                // In a real implementation, this would fetch historical time-series data
                // For now, we simulate it or use the summary metrics
                const data = await ApiStudioApi.getEndpointMetrics(endpoint.id);
                setMetrics(data);
            } catch (err) {
                console.error("Failed to load metrics", err);
            } finally {
                setLoading(false);
            }
        };

        fetchMetrics();
    }, [endpoint.id]);

    if (loading) {
        return (
            <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
                <CircularProgress />
            </Box>
        );
    }

    if (!metrics) {
        return <Typography color="textSecondary">No usage data available.</Typography>;
    }

    // Mock time-series data for visualization (since the API currently returns summary stats)
    const timeSeriesData = Array.from({ length: 24 }, (_, i) => ({
        time: `${i}:00`,
        requests: Math.floor(Math.random() * 1000) + 50,
        latency: Math.floor(Math.random() * 200) + 20,
        errors: Math.floor(Math.random() * 10)
    }));

    return (
        <Box sx={{ p: 2 }}>
            <Grid container spacing={3} sx={{ mb: 4 }}>
                <Grid item xs={12} md={3}>
                    <Card elevation={0} sx={{ border: '1px solid #eee', borderRadius: 2 }}>
                        <CardContent>
                            <Typography variant="caption" color="textSecondary">Avg Latency (P95)</Typography>
                            <Typography variant="h4" fontWeight="bold">{metrics.p95}ms</Typography>
                             <LinearProgress variant="determinate" value={Math.min(metrics.p95 / 5, 100)} sx={{ mt: 1, height: 6, borderRadius: 3, bgcolor: '#e0e0e0', '& .MuiLinearProgress-bar': { bgcolor: metrics.p95 > 200 ? 'error.main' : 'success.main' } }} />
                        </CardContent>
                    </Card>
                </Grid>
                <Grid item xs={12} md={3}>
                    <Card elevation={0} sx={{ border: '1px solid #eee', borderRadius: 2 }}>
                        <CardContent>
                            <Typography variant="caption" color="textSecondary">Error Rate</Typography>
                            <Typography variant="h4" fontWeight="bold">{(metrics.errorRate || 0.02) * 100}%</Typography>
                             <LinearProgress variant="determinate" value={(metrics.errorRate || 0.02) * 100 * 5} sx={{ mt: 1, height: 6, borderRadius: 3 }} color="secondary" />
                        </CardContent>
                    </Card>
                </Grid>
                <Grid item xs={12} md={3}>
                    <Card elevation={0} sx={{ border: '1px solid #eee', borderRadius: 2 }}>
                        <CardContent>
                            <Typography variant="caption" color="textSecondary">Requests (24h)</Typography>
                            <Typography variant="h4" fontWeight="bold">{(metrics.qps * 60 * 60 * 24 / 1000).toFixed(1)}k</Typography>
                            <Typography variant="caption" color="success.main">+12% vs yesterday</Typography>
                        </CardContent>
                    </Card>
                </Grid>
                <Grid item xs={12} md={3}>
                    <Card elevation={0} sx={{ border: '1px solid #eee', borderRadius: 2 }}>
                        <CardContent>
                            <Typography variant="caption" color="textSecondary">Cache Hit Rate</Typography>
                            <Typography variant="h4" fontWeight="bold">{metrics.cacheHitRate * 100}%</Typography>
                            <LinearProgress variant="determinate" value={metrics.cacheHitRate * 100} sx={{ mt: 1, height: 6, borderRadius: 3 }} />
                        </CardContent>
                    </Card>
                </Grid>
            </Grid>

            {/* Charts */}
            <Grid container spacing={3}>
                <Grid item xs={12} md={8}>
                    <Paper elevation={0} sx={{ p: 2, border: '1px solid #eee', borderRadius: 2 }}>
                         <Typography variant="subtitle2" gutterBottom fontWeight="bold">Traffic Volume & Latency</Typography>
                         <Box sx={{ height: 300 }}>
                            <ResponsiveContainer width="100%" height="100%">
                                <AreaChart data={timeSeriesData}>
                                    <defs>
                                        <linearGradient id="colorReq" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="5%" stopColor="#8884d8" stopOpacity={0.8}/>
                                            <stop offset="95%" stopColor="#8884d8" stopOpacity={0}/>
                                        </linearGradient>
                                        <linearGradient id="colorLat" x1="0" y1="0" x2="0" y2="1">
                                            <stop offset="5%" stopColor="#82ca9d" stopOpacity={0.8}/>
                                            <stop offset="95%" stopColor="#82ca9d" stopOpacity={0}/>
                                        </linearGradient>
                                    </defs>
                                    <XAxis dataKey="time" />
                                    <YAxis yAxisId="left" />
                                    <YAxis yAxisId="right" orientation="right" />
                                    <CartesianGrid strokeDasharray="3 3" vertical={false} />
                                    <Tooltip />
                                    <Area yAxisId="left" type="monotone" dataKey="requests" stroke="#8884d8" fillOpacity={1} fill="url(#colorReq)" name="Requests" />
                                    <Area yAxisId="right" type="monotone" dataKey="latency" stroke="#82ca9d" fillOpacity={1} fill="url(#colorLat)" name="Latency (ms)" />
                                </AreaChart>
                            </ResponsiveContainer>
                         </Box>
                    </Paper>
                </Grid>
                <Grid item xs={12} md={4}>
                    <Paper elevation={0} sx={{ p: 2, border: '1px solid #eee', borderRadius: 2 }}>
                        <Typography variant="subtitle2" gutterBottom fontWeight="bold">Errors by Type</Typography>
                        <Box sx={{ height: 300 }}>
                             <ResponsiveContainer width="100%" height="100%">
                                <BarChart data={[
                                    { name: '400', value: 120 },
                                    { name: '401', value: 45 },
                                    { name: '403', value: 30 },
                                    { name: '404', value: 80 },
                                    { name: '500', value: 15 },
                                ]}>
                                    <XAxis dataKey="name" />
                                    <YAxis />
                                    <Tooltip />
                                    <Bar dataKey="value" fill="#ff8042" radius={[4, 4, 0, 0]} />
                                </BarChart>
                             </ResponsiveContainer>
                        </Box>
                    </Paper>
                </Grid>
            </Grid>
        </Box>
    );
};

export default UsageDashboard;

import React, { useState, useMemo, useCallback } from 'react';
import {
	Container,
	Typography,
	CircularProgress,
	Alert,
} from '@mui/material';
import { useTenant } from '../../contexts/TenantContext';
import { useAuthFetch } from '../../utils/authFetch';
import {
	DataBundle,
	SemanticObjectReference
} from '../../types/bundles';
import { useValidationErrors } from '../../hooks/useValidationErrors';
import { logInteraction } from '../../lib/analytics';
import { BundleMetadataForm } from './BundleMetadataForm';
import { SemanticObjectsSelector } from './SemanticObjectsSelector';
import { RowPolicyManager } from './RowPolicyManager';
import { ColumnPolicyManager } from './ColumnPolicyManager';
import { BundleActions } from './BundleActions';
import { useBundleData } from './useBundleData';
import { useSemanticObjects } from './useSemanticObjects';
import { operatorOptions, maskTypeOptions } from './bundleConstants';

interface BundleEditorProps {
    bundleId?: string;
    onSave: (bundle: DataBundle) => void;
    onCancel: () => void;
}

const BundleEditor: React.FC<BundleEditorProps> = ({ bundleId, onSave, onCancel }) => {
    const isEditMode = !!bundleId;

    // Use custom hooks for state management
    const bundleData = useBundleData({ bundleId });
    const semanticObjects = useSemanticObjects();
    const {
        allObjects,
        loadingObjects,
        objectsError,
        handleRefreshObjects,
    } = semanticObjects;

    const {
        name,
        description,
        includedMeasures,
        includedDimensions,
        rowPolicies,
        columnPolicies,
        loading,
        initializing,
        error,
        setName,
        setDescription,
        setIncludedMeasures,
        setIncludedDimensions,
        setRowPolicies,
        setColumnPolicies,
        setLoading,
        setError,
        addRowPolicy,
        removeRowPolicy,
        updateRowPolicy,
        handleRowPolicyFieldChange,
        handleRowPolicyValuesChange,
        addColumnPolicy,
        removeColumnPolicy,
        updateColumnPolicy,
        handleColumnPolicyFieldChange,
        handleColumnPolicyColumnsChange,
        prepareRowPoliciesForSave,
        prepareColumnPoliciesForSave,
        tenantId,
        datasourceId,
    } = bundleData;

    const {
        fieldErrors,
        clearFieldErrors,
        clearFieldError,
        hasFieldError,
        fieldHelperText,
        handleResponseError
    } = useValidationErrors();

    // UX Enhancements: Publish validation state
    // some publish helpers are not used in this pass; underscore them to quiet lint
    const [_showPublishConfirm, _setShowPublishConfirm] = useState(false);
    const [_publishChecking, _setPublishChecking] = useState(false);
    const [publishErrors, _setPublishErrors] = useState<string[]>([]);

    const { tenant, datasource } = useTenant();
    const { authFetch } = useAuthFetch();
    const selectionMissing = !tenantId || !datasourceId;
    const tenantLabel = tenant?.display_name?.trim() || tenant?.name?.trim() || (tenantId ? tenantId : 'No tenant selected');
    const datasourceLabel =
        datasource?.source_name?.trim() ||
        datasource?.alpha_datasource?.datasource_name?.trim() ||
        (datasourceId ? datasourceId : 'No datasource selected');

    const objectKey = useCallback((obj: SemanticObjectReference) => `${obj.modelId ?? ''}::${obj.id}::${obj.type ?? 'dimension'}`, []);

    const normalizedType = (obj: SemanticObjectReference) => (obj.type === 'measure' ? 'measure' : 'dimension');

    const handleSave = async () => {
        setLoading(true);
        setError(null);
        clearFieldErrors();

        const sanitizedRowPolicies = prepareRowPoliciesForSave(rowPolicies);
        const sanitizedColumnPolicies = prepareColumnPoliciesForSave(columnPolicies);

        try {
            // UX Enhancement: Log interaction
            logInteraction('bundle_save_started', {
                bundleId: bundleId || 'new',
                measuresCount: includedMeasures.length,
                dimensionsCount: includedDimensions.length,
                timestamp: Date.now()
            });

            let currentBundle: DataBundle | null = null;

            if (isEditMode && bundleId) {
                const updateResponse = await authFetch<DataBundle>(`/api/bundles/${bundleId}`, {
                    method: 'PUT',
                    json: { measures: includedMeasures, dimensions: includedDimensions }
                });

                if (!updateResponse.ok || !updateResponse.data) {
                    await handleResponseError(updateResponse.response, 'Failed to save bundle structure');
                }

                currentBundle = updateResponse.data as DataBundle;
            } else {
                const createResponse = await authFetch<DataBundle>('/api/bundles', {
                    method: 'POST',
                    json: { name, description }
                });

                if (!createResponse.ok || !createResponse.data) {
                    await handleResponseError(createResponse.response, 'Failed to create bundle');
                }

                const createdBundle = createResponse.data as DataBundle;
                currentBundle = createdBundle;

                const structureResponse = await authFetch<DataBundle>(`/api/bundles/${createdBundle.id}`, {
                    method: 'PUT',
                    json: { measures: includedMeasures, dimensions: includedDimensions }
                });

                if (!structureResponse.ok || !structureResponse.data) {
                    await handleResponseError(structureResponse.response, 'Failed to update bundle structure');
                }

                currentBundle = structureResponse.data as DataBundle;
            }

            if (!currentBundle) {
                throw new Error('Bundle could not be saved');
            }

            const policyResponse = await authFetch<DataBundle>(`/api/bundles/${currentBundle.id}/policies`, {
                method: 'PUT',
                json: {
                    rowPolicies: sanitizedRowPolicies,
                    columnPolicies: sanitizedColumnPolicies
                }
            });

            if (!policyResponse.ok || !policyResponse.data) {
                await handleResponseError(policyResponse.response, 'Failed to save bundle policies');
            }

            const updatedBundle = policyResponse.data as DataBundle;

            // UX Enhancement: Log successful save
            logInteraction('bundle_save_completed', {
                bundleId: updatedBundle.id,
                timestamp: Date.now()
            });

            onSave(updatedBundle);
        } catch (err: any) {
            // UX Enhancement: Log save error
            logInteraction('bundle_save_failed', {
                error: err.message,
                timestamp: Date.now()
            });
            setError(err.message || 'Failed to save bundle');
        } finally {
            setLoading(false);
        }
    };

    const scopeDescription = useMemo(() => {
        if (selectionMissing) {
            return 'Select a tenant and datasource to browse views.';
        }
        return `Scoped to ${tenantLabel} • ${datasourceLabel}`;
    }, [datasourceLabel, selectionMissing, tenantLabel]);

    if (initializing) {
        return <CircularProgress />;
    }

    return (
        <Container maxWidth="xl" sx={{ mt: 4 }}>
            <Typography variant="h4" gutterBottom>{isEditMode ? 'Edit Data Bundle' : 'Create Data Bundle'}</Typography>
            <BundleMetadataForm
                name={name}
                description={description}
                onNameChange={setName}
                onDescriptionChange={setDescription}
                fieldErrors={fieldErrors}
                fieldHelperText={fieldHelperText}
            />

            {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}

            <SemanticObjectsSelector
                includedMeasures={includedMeasures}
                includedDimensions={includedDimensions}
                allObjects={allObjects}
                loadingObjects={loadingObjects}
                objectsError={objectsError}
                onMeasuresChange={setIncludedMeasures}
                onDimensionsChange={setIncludedDimensions}
                onRefreshObjects={handleRefreshObjects}
            />

            <RowPolicyManager
                policies={rowPolicies}
                onAddPolicy={addRowPolicy}
                onRemovePolicy={removeRowPolicy}
                onUpdatePolicy={updateRowPolicy}
                onFieldChange={handleRowPolicyFieldChange}
                onValuesChange={handleRowPolicyValuesChange}
                fieldErrors={fieldErrors}
                fieldHelperText={fieldHelperText}
                operatorOptions={operatorOptions}
                onFieldEdit={clearFieldError}
                hasFieldError={hasFieldError}
            />

            <ColumnPolicyManager
                policies={columnPolicies}
                onAddPolicy={addColumnPolicy}
                onRemovePolicy={removeColumnPolicy}
                onUpdatePolicy={updateColumnPolicy}
                onFieldChange={handleColumnPolicyFieldChange}
                onColumnsChange={handleColumnPolicyColumnsChange}
                fieldErrors={fieldErrors}
                fieldHelperText={fieldHelperText}
                maskTypeOptions={maskTypeOptions}
                onFieldEdit={clearFieldError}
                hasFieldError={hasFieldError}
                operatorOptions={operatorOptions}
            />

            <BundleActions
                publishErrors={publishErrors}
                loading={loading}
                onCancel={onCancel}
                onSave={handleSave}
            />
        </Container>
    );
};

export default BundleEditor;

/**
 * Semantic Objects Selector Component
 *
 * Handles selection of measures and dimensions for the bundle
 */

import React, { useState, useMemo } from 'react';
import {
  Box,
  Typography,
  Paper,
  Chip,
  Alert,
  CircularProgress,
  Grid,
  IconButton,
} from '@mui/material';
import RefreshIcon from '@mui/icons-material/Refresh';
import { SemanticObjectReference } from '../../types/bundles';

interface SemanticObjectsSelectorProps {
  includedMeasures: SemanticObjectReference[];
  includedDimensions: SemanticObjectReference[];
  allObjects: SemanticObjectReference[];
  loadingObjects: boolean;
  objectsError: string | null;
  onMeasuresChange: (measures: SemanticObjectReference[]) => void;
  onDimensionsChange: (dimensions: SemanticObjectReference[]) => void;
  onRefreshObjects: () => void;
}

export const SemanticObjectsSelector: React.FC<SemanticObjectsSelectorProps> = ({
  includedMeasures,
  includedDimensions,
  allObjects,
  loadingObjects,
  objectsError,
  onMeasuresChange,
  onDimensionsChange,
  onRefreshObjects,
}) => {
  const [searchTerm, setSearchTerm] = useState('');

  const filteredObjects = useMemo(() => {
    if (!searchTerm) return allObjects;
    return allObjects.filter(obj =>
      (obj.name && obj.name.toLowerCase().includes(searchTerm.toLowerCase())) ||
      (obj.title && obj.title.toLowerCase().includes(searchTerm.toLowerCase()))
    );
  }, [allObjects, searchTerm]);

  const handleAddMeasure = (measure: SemanticObjectReference) => {
    if (!includedMeasures.find(m => m.id === measure.id)) {
      onMeasuresChange([...includedMeasures, measure]);
    }
  };

  const handleRemoveMeasure = (measureId: string) => {
    onMeasuresChange(includedMeasures.filter(m => m.id !== measureId));
  };

  const handleAddDimension = (dimension: SemanticObjectReference) => {
    if (!includedDimensions.find(d => d.id === dimension.id)) {
      onDimensionsChange([...includedDimensions, dimension]);
    }
  };

  const handleRemoveDimension = (dimensionId: string) => {
    onDimensionsChange(includedDimensions.filter(d => d.id !== dimensionId));
  };

  return (
    <Box sx={{ mb: 4 }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="h6">Semantic Objects</Typography>
        <IconButton onClick={onRefreshObjects} disabled={loadingObjects}>
          <RefreshIcon />
        </IconButton>
      </Box>

      {objectsError && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {objectsError}
        </Alert>
      )}

      <Grid container spacing={3}>
        {/* Measures Section */}
        <Grid item xs={12} md={6}>
          <Paper sx={{ p: 2 }}>
            <Typography variant="subtitle1" gutterBottom>
              Measures ({includedMeasures.length})
            </Typography>

            {includedMeasures.length > 0 && (
              <Box sx={{ mb: 2 }}>
                {includedMeasures.map((measure) => (
                  <Chip
                    key={measure.id}
                    label={measure.name || measure.id}
                    onDelete={() => handleRemoveMeasure(measure.id)}
                    sx={{ mr: 1, mb: 1 }}
                  />
                ))}
              </Box>
            )}

            {loadingObjects ? (
              <CircularProgress size={24} />
            ) : (
