/**
 * useBPDesignerAPI.ts
 * React hooks for Business Process Designer API calls
 */

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import {
  ProcessStepType,
  ValidationOperator,
  WorkflowEvent,
  BusinessObject,
  Process,
  ValidationRule,
} from './types';

/**
 * Fetch function that includes tenant scope
 */
async function fetchWithTenant(url: string, options?: RequestInit) {
  const tenantData = localStorage.getItem('selected_tenant');
  const datasourceData = localStorage.getItem('selected_datasource');

  const tenant = tenantData ? JSON.parse(tenantData) : null;
  const datasource = datasourceData ? JSON.parse(datasourceData) : null;

  if (!tenant?.id || !datasource?.id) {
    throw new Error('Tenant and datasource must be selected');
  }

  const headers = {
    'Content-Type': 'application/json',
    'X-Tenant-ID': tenant.id,
    'X-Tenant-Datasource-ID': datasource.id,
    ...options?.headers,
  };

  const separator = url.includes('?') ? '&' : '?';
  const urlWithScope = `${url}${separator}tenant_id=${tenant.id}&datasource_id=${datasource.id}`;

  const response = await fetch(urlWithScope, {
    ...options,
    headers,
  });

  if (!response.ok) {
    throw new Error(`API error: ${response.statusText}`);
  }

  return response.json();
}

// Query Hooks

export const useStepTypes = () => {
  return useQuery({
    queryKey: ['stepTypes'],
    queryFn: () => fetchWithTenant('/api/step-types'),
  });
};

export const useValidationOperators = () => {
  return useQuery({
    queryKey: ['validationOperators'],
    queryFn: () => fetchWithTenant('/api/validation-operators'),
  });
};

export const useWorkflowEvents = () => {
  return useQuery({
    queryKey: ['workflowEvents'],
    // Use the v1 triggers events endpoint to avoid collision with legacy /api/events
    queryFn: () => fetchWithTenant('/api/v1/triggers/events'),
  });
};

export const useBusinessObjects = () => {
  return useQuery({
    queryKey: ['businessObjects'],
    queryFn: () => fetchWithTenant('/api/business-objects/list'),
  });
};

export const useProcess = (processId: string | null) => {
  return useQuery({
    queryKey: ['process', processId],
    queryFn: () =>
      processId
        ? fetchWithTenant(`/api/processes/${processId}`)
        : Promise.resolve(null),
    enabled: !!processId,
  });
};

export const useValidationRules = (processId: string | null, nodeId: string | null) => {
  return useQuery({
    queryKey: ['validationRules', processId, nodeId],
    queryFn: () =>
      processId && nodeId
        ? fetchWithTenant(`/api/processes/${processId}/nodes/${nodeId}/rules`)
        : Promise.resolve([]),
    enabled: !!processId && !!nodeId,
  });
};

// Mutation Hooks

export const useCreateProcess = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (process: Omit<Process, 'id' | 'created_at' | 'updated_at'>) =>
      fetchWithTenant('/api/processes', {
        method: 'POST',
        body: JSON.stringify(process),
      }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['processes'] });
    },
  });
};

export const useUpdateProcess = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ id, nodes, edges }: { id: string; nodes: any[]; edges: any[] }) =>
      fetchWithTenant(`/api/processes/${id}`, {
        method: 'PATCH',
        body: JSON.stringify({ nodes, edges }),
      }),
    onSuccess: (_, { id }) => {
      queryClient.invalidateQueries({ queryKey: ['process', id] });
    },
  });
};

export const useSaveValidationRules = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: ({ processId, nodeId, rules }: { processId: string; nodeId: string; rules: ValidationRule[] }) =>
      fetchWithTenant(`/api/processes/${processId}/nodes/${nodeId}/rules`, {
        method: 'POST',
        body: JSON.stringify(rules),
      }),
    onSuccess: (_, { processId, nodeId }) => {
      queryClient.invalidateQueries({ queryKey: ['validationRules', processId, nodeId] });
    },
  });
};

import { useState, useCallback } from 'react';
import { type BundleRowPolicy, type BundleColumnPolicy, type AttributeCondition } from '../../types/bundles';
import { generateId } from './bundleConstants';

export const useBundlePolicies = () => {
    const [rowPolicies, setRowPolicies] = useState<BundleRowPolicy[]>([]);
    const [columnPolicies, setColumnPolicies] = useState<BundleColumnPolicy[]>([]);

    const addRowPolicy = useCallback(() => {
        const newPolicy: BundleRowPolicy = {
            id: generateId(),
            name: '',
            description: '',
            member: '',
            operator: '',
            values: [],
            conditions: [],
        };
        setRowPolicies(prev => [...prev, newPolicy]);
    }, []);

    const removeRowPolicy = useCallback((policyId: string) => {
        setRowPolicies(prev => prev.filter(policy => policy.id !== policyId));
    }, []);

    const updateRowPolicy = useCallback((policyId: string, updater: (policy: BundleRowPolicy) => BundleRowPolicy) => {
        setRowPolicies(prev => prev.map(policy =>
            policy.id === policyId ? updater(policy) : policy
        ));
    }, []);

    const handleRowPolicyFieldChange = useCallback((policyId: string, field: keyof BundleRowPolicy, value: any) => {
        updateRowPolicy(policyId, (current) => ({
            ...current,
            [field]: value,
        }));
    }, [updateRowPolicy]);

    const addColumnPolicy = useCallback(() => {
        const newPolicy: BundleColumnPolicy = {
            id: generateId(),
            name: '',
            description: '',
            columns: [],
            maskType: 'redact',
            maskValue: undefined,
            conditions: [],
        };
        setColumnPolicies(prev => [...prev, newPolicy]);
    }, []);

    const removeColumnPolicy = useCallback((policyId: string) => {
        setColumnPolicies(prev => prev.filter(policy => policy.id !== policyId));
    }, []);

    const updateColumnPolicy = useCallback((policyId: string, updater: (policy: BundleColumnPolicy) => BundleColumnPolicy) => {
        setColumnPolicies(prev => prev.map(policy =>
            policy.id === policyId ? updater(policy) : policy
        ));
    }, []);

    const handleColumnPolicyFieldChange = useCallback((policyId: string, field: keyof BundleColumnPolicy, value: any) => {
        updateColumnPolicy(policyId, (current) => ({
            ...current,
            [field]: value,
        }));
    }, [updateColumnPolicy]);

    const handleColumnPolicyColumnsChange = useCallback((policyId: string, columnsString: string) => {
        const columns = columnsString.split(',').map(col => col.trim()).filter(col => col.length > 0);
        updateColumnPolicy(policyId, (current) => ({
            ...current,
            columns,
        }));
    }, [updateColumnPolicy]);

    const prepareRowPoliciesForSave = useCallback((policies: BundleRowPolicy[]): BundleRowPolicy[] =>
        policies.map((policy) => ({
            ...policy,
            name: policy.name.trim(),
            description: policy.description.trim(),
            member: policy.member.trim(),
            operator: policy.operator.trim() || 'equals',
            values: policy.values.map(v => v.trim()).filter(v => v.length > 0),
            conditions: policy.conditions
                .map((condition) => ({
                    attribute: condition.attribute.trim(),
                    operator: (condition.operator || 'equals').trim() || 'equals',
                    values: condition.values.map(v => v.trim()).filter(v => v.length > 0)
                }))
                .filter((condition) => condition.attribute.length > 0)
        })), []);

    const prepareColumnPoliciesForSave = useCallback((policies: BundleColumnPolicy[]): BundleColumnPolicy[] =>
        policies.map((policy) => ({
            ...policy,
            name: policy.name.trim(),
            description: policy.description.trim(),
            columns: policy.columns.map(c => c.trim()).filter(c => c.length > 0),
            maskType: policy.maskType.trim() || 'redact',
            maskValue: policy.maskValue && policy.maskValue.trim().length > 0 ? policy.maskValue.trim() : undefined,
            conditions: policy.conditions
                .map((condition) => ({
                    attribute: condition.attribute.trim(),
                    operator: (condition.operator || 'equals').trim() || 'equals',
                    values: condition.values.map(v => v.trim()).filter(v => v.length > 0)
                }))
                .filter((condition) => condition.attribute.length > 0)
        })), []);

    return {
        rowPolicies,
        columnPolicies,
        setRowPolicies,
        setColumnPolicies,
        addRowPolicy,
        removeRowPolicy,
        updateRowPolicy,
        handleRowPolicyFieldChange,
        addColumnPolicy,
        removeColumnPolicy,
        updateColumnPolicy,
        handleColumnPolicyFieldChange,
        handleColumnPolicyColumnsChange,
        prepareRowPoliciesForSave,
        prepareColumnPoliciesForSave,
    };
};

import React, { useEffect, useState } from 'react';
import {
    Box,
    Typography,
    Button,
    Container,
    Paper,
    CircularProgress,
    Stack,
    Alert,
} from '@mui/material';
import { AutoAwesome as AutoIcon, Refresh as RefreshIcon } from '@mui/icons-material';
import { catalogApi, AIBusinessTermDraft } from '../../api/catalogApi';
import { SuggestionsTable } from './components/SuggestionsTable';
import { BusinessTermReviewDrawer } from './components/BusinessTermReviewDrawer';

export const AIBusinessTermSuggestionsPage: React.FC = () => {
    const [loading, setLoading] = useState(false);
    const [suggestions, setSuggestions] = useState<AIBusinessTermDraft[]>([]);
    const [error, setError] = useState<string | null>(null);
    const [selectedSuggestion, setSelectedSuggestion] = useState<AIBusinessTermDraft | null>(null);
    const [drawerOpen, setDrawerOpen] = useState(false);

    const fetchSuggestions = async () => {
        setLoading(true);
        try {
            const data = await catalogApi.listSuggestions();
            setSuggestions(data);
            setError(null);
        } catch (err) {
            setError('Failed to load suggestions. Please try again.');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchSuggestions();
    }, []);

    const handleGenerate = async () => {
        setLoading(true);
        try {
            // In a real app, this might open a dialog to select tables
            // For MVP, we'll trigger generation for a default set or all
            await catalogApi.generateSuggestion({ tableNames: ['all'] }); // Simplified
            await fetchSuggestions();
        } catch (err) {
            setError('Failed to generate suggestions.');
            setLoading(false);
        }
    };

    const handleView = (suggestion: AIBusinessTermDraft) => {
        setSelectedSuggestion(suggestion);
        setDrawerOpen(true);
    };

    const handleApprove = async (id: string) => {
        try {
            await catalogApi.approveSuggestion(id);
            setDrawerOpen(false);
            fetchSuggestions(); // Refresh list to show status change
        } catch (err) {
            setError('Failed to approve suggestion.');
        }
    };

    const handleReject = async (id: string, reason: string) => {
        try {
            await catalogApi.rejectSuggestion(id, reason);
            setDrawerOpen(false);
            fetchSuggestions();
        } catch (err) {
            setError('Failed to reject suggestion.');
        }
    };

    return (
        <Container maxWidth="xl" sx={{ mt: 4, mb: 4 }}>
            <Stack direction="row" justifyContent="space-between" alignItems="center" mb={4}>
                <Box>
                    <Typography variant="h4" component="h1" gutterBottom fontWeight="bold">
                        AI Business Term Suggestions
                    </Typography>
                    <Typography variant="body1" color="text.secondary">
                        Review and approve business terms generated from your technical metadata.
                    </Typography>
                </Box>
                <Stack direction="row" spacing={2}>
                    <Button
                        variant="outlined"
                        startIcon={<RefreshIcon />}
                        onClick={fetchSuggestions}
                        disabled={loading}
                    >
                        Refresh
                    </Button>
                    <Button
                        variant="contained"
                        startIcon={<AutoIcon />}
                        onClick={handleGenerate}
                        disabled={loading}
                        sx={{
                            background: 'linear-gradient(45deg, #2196F3 30%, #21CBF3 90%)',
                            color: 'white',
                        }}
                    >
                        Generate New
                    </Button>
                </Stack>
            </Stack>

            {error && (
                <Alert severity="error" sx={{ mb: 3 }} onClose={() => setError(null)}>
                    {error}
                </Alert>
            )}

            {loading && suggestions.length === 0 ? (
                <Box display="flex" justifyContent="center" p={8}>
                    <CircularProgress />
                </Box>
            ) : (
                <SuggestionsTable
                    suggestions={suggestions}
                    onView={handleView}
                    onApprove={handleApprove}
                    onReject={(id) => {
                        const suggestion = suggestions.find((s) => s.id === id);
                        if (suggestion) {
                            handleView(suggestion);
                        }
                    }}
                />
            )}

            <BusinessTermReviewDrawer
                open={drawerOpen}
                suggestion={selectedSuggestion}
                onClose={() => setDrawerOpen(false)}
                onApprove={handleApprove}
                onReject={handleReject}
            />
        </Container>
    );
};

import React, { useEffect, useState } from 'react';
