import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Storage as StorageIcon,
  TrendingUp as TrendingUpIcon,
  CheckCircle as CheckCircleIcon,
  Warning as WarningIcon,
  ArrowBack as ArrowBackIcon,
  AutoFixHigh as AutoFixHighIcon,
} from '@mui/icons-material';
import './IntelligenceDashboard.css';

interface IndexRecommendation {
  id: string;
  table: string;
  schema: string;
  columns: string[];
  indexType: 'btree' | 'hash' | 'composite' | 'covering';
  impact: {
    queryTimeReduction: number;
    queriesAffected: number;
    estimatedCostSavings: string;
  };
  riskLevel: 'low' | 'medium' | 'high';
  status: 'pending' | 'applied' | 'dismissed';
  createdAt: string;
  query: string;
}

const IndexAdvisorPage: React.FC = () => {
  const navigate = useNavigate();
  const [recommendations, setRecommendations] = useState<IndexRecommendation[]>([]);
  const [filter, setFilter] = useState<string>('all');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchRecommendations();
  }, []);

  const fetchRecommendations = async () => {
    setLoading(true);
    try {
      // Simulated data
      const data: IndexRecommendation[] = [
        {
          id: '1',
          table: 'positions',
          schema: 'public',
          columns: ['account_id', 'as_of_date'],
          indexType: 'btree',
          impact: { queryTimeReduction: 65, queriesAffected: 142, estimatedCostSavings: '$2,400/mo' },
          riskLevel: 'low',
          status: 'pending',
          createdAt: '2026-01-17T10:00:00Z',
          query: 'SELECT * FROM positions WHERE account_id = ? AND as_of_date >= ?',
        },
        {
          id: '2',
          table: 'transactions',
          schema: 'public',
          columns: ['tenant_id', 'created_at'],
          indexType: 'btree',
          impact: { queryTimeReduction: 40, queriesAffected: 89, estimatedCostSavings: '$1,200/mo' },
          riskLevel: 'low',
          status: 'pending',
          createdAt: '2026-01-17T09:30:00Z',
          query: 'SELECT * FROM transactions WHERE tenant_id = ? ORDER BY created_at DESC',
        },
        {
          id: '3',
          table: 'holdings',
          schema: 'public',
          columns: ['security_id', 'portfolio_id'],
          indexType: 'composite',
          impact: { queryTimeReduction: 55, queriesAffected: 67, estimatedCostSavings: '$800/mo' },
          riskLevel: 'medium',
          status: 'pending',
          createdAt: '2026-01-17T08:00:00Z',
          query: 'SELECT h.*, s.symbol FROM holdings h JOIN securities s ON h.security_id = s.id WHERE portfolio_id = ?',
        },
        {
          id: '4',
          table: 'audit_logs',
          schema: 'public',
          columns: ['entity_type', 'entity_id', 'timestamp'],
          indexType: 'composite',
          impact: { queryTimeReduction: 72, queriesAffected: 234, estimatedCostSavings: '$3,100/mo' },
          riskLevel: 'low',
          status: 'applied',
          createdAt: '2026-01-16T14:00:00Z',
          query: 'SELECT * FROM audit_logs WHERE entity_type = ? AND entity_id = ? ORDER BY timestamp DESC',
        },
      ];
      setRecommendations(data);
    } finally {
      setLoading(false);
    }
  };

  const getRiskColor = (level: string): string => {
    switch (level) {
      case 'high': return '#dc2626';
      case 'medium': return '#ca8a04';
      case 'low': return '#16a34a';
      default: return '#6b7280';
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'applied':
        return <span className="status-badge applied"><CheckCircleIcon /> Applied</span>;
      case 'dismissed':
        return <span className="status-badge dismissed">Dismissed</span>;
      default:
        return <span className="status-badge pending">Pending</span>;
    }
  };

  const handleApply = (id: string) => {
    setRecommendations(prev => 
      prev.map(r => r.id === id ? { ...r, status: 'applied' } : r) as IndexRecommendation[]
    );
  };

  const filteredRecs = recommendations.filter(r => 
    filter === 'all' || r.status === filter
  );

  if (loading) {
    return <div className="intelligence-loading"><div className="loading-spinner" /><p>Analyzing query patterns...</p></div>;
  }

  return (
    <div className="intelligence-dashboard">
      <header className="dashboard-header">
        <button className="back-btn" onClick={() => navigate('/intelligence')}>
          <ArrowBackIcon /> Back
        </button>
        <div className="header-content">
          <StorageIcon className="header-icon" />
          <div>
            <h1>Index Advisor</h1>
            <p>AI-powered index recommendations based on query patterns</p>
          </div>
        </div>
      </header>

      {/* Filters */}
      <div className="filter-bar">
        <select value={filter} onChange={e => setFilter(e.target.value)}>
          <option value="all">All Recommendations</option>
          <option value="pending">Pending</option>
          <option value="applied">Applied</option>
          <option value="dismissed">Dismissed</option>
        </select>
        <span className="result-count">{filteredRecs.length} recommendations</span>
      </div>

      {/* Recommendations List */}
      <div className="recommendations-list">
        {filteredRecs.map(rec => (
          <div key={rec.id} className="recommendation-card">
            <div className="rec-header">
              <div className="rec-title">
                <span className="table-name">{rec.schema}.{rec.table}</span>
                <span className="index-type">{rec.indexType} index</span>
              </div>
              {getStatusBadge(rec.status)}
            </div>

            <div className="rec-columns">
              <strong>Suggested Index:</strong>
              <code>{rec.columns.join(', ')}</code>
            </div>

            <div className="rec-query">
              <strong>Sample Query:</strong>
              <pre>{rec.query}</pre>
            </div>

            <div className="rec-impact">
              <div className="impact-item">
                <TrendingUpIcon />
                <span>{rec.impact.queryTimeReduction}% faster</span>
              </div>
              <div className="impact-item">
                <span>{rec.impact.queriesAffected} queries affected</span>
              </div>
              <div className="impact-item savings">
                <span>{rec.impact.estimatedCostSavings}</span>
              </div>
              <div className="impact-item">
                <span style={{ color: getRiskColor(rec.riskLevel) }}>
                  {rec.riskLevel} risk
                </span>
              </div>
            </div>

            {rec.status === 'pending' && (
              <div className="rec-actions">
                <button className="apply-btn" onClick={() => handleApply(rec.id)}>
                  <AutoFixHighIcon /> Apply Index
                </button>
                <button className="dismiss-btn">Dismiss</button>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default IndexAdvisorPage;

/**
 * Storage Tiering Page - AI-driven data lifecycle management
 */

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Layers as LayersIcon,
  TrendingDown as TrendingDownIcon,
  CheckCircle as CheckCircleIcon,
  Warning as WarningIcon,
  ArrowBack as ArrowBackIcon,
  Bolt as BoltIcon,
  AcUnit as AcUnitIcon,
  CloudQueue as CloudQueueIcon,
} from '@mui/icons-material';
import './IntelligenceDashboard.css';

import { tieringApi, TieringPlan, TieringRule, PlanStatus, StorageTier } from '../../api/tieringApi';

const StorageTieringPage: React.FC = () => {
  const navigate = useNavigate();
  const [plans, setPlans] = useState<TieringPlan[]>([]);
  const [activePlan, setActivePlan] = useState<TieringPlan | null>(null);
  const [loading, setLoading] = useState(true);

  // For demo, we use a fixed tenant ID
  const tenantId = '00000000-0000-0000-0000-000000000001';

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setLoading(true);
    try {
      const existingPlans = await tieringApi.listPlans(tenantId);
      if (existingPlans.length > 0) {
        setPlans(existingPlans);
        setActivePlan(existingPlans[0]);
      } else {
        // Generate initial plan if none exist
        const newPlan = await tieringApi.generatePlan(tenantId);
        setPlans([newPlan]);
        setActivePlan(newPlan);
      }
    } catch (error) {
      console.error('Failed to fetch storage tiering plans', error);
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateNew = async () => {
    setLoading(true);
    try {
      const newPlan = await tieringApi.generatePlan(tenantId);
      setPlans(prev => [newPlan, ...prev]);
      setActivePlan(newPlan);
    } finally {
      setLoading(false);
    }
  };


  const handleMigrate = async (planId: string) => {
    try {
      setPlans(prev =>
        prev.map(p => p.id === planId ? { ...p, status: 'migrating' as PlanStatus } : p)
      );
      if (activePlan?.id === planId) {
        setActivePlan({ ...activePlan, status: 'migrating' as PlanStatus });
      }

      await tieringApi.executePlan(planId);

      setPlans(prev =>
        prev.map(p => p.id === planId ? { ...p, status: 'completed' as PlanStatus } : p)
      );
      if (activePlan?.id === planId) {
        setActivePlan({ ...activePlan, status: 'completed' as PlanStatus });
      }
    } catch (error) {
      console.error('Migration failed', error);
      fetchData(); // Refresh on error
    }
  };

  const getTierIcon = (tier: StorageTier) => {
    switch (tier) {
      case 'hot': return <BoltIcon style={{ color: '#ef4444' }} />;
      case 'warm': return <CloudQueueIcon style={{ color: '#f59e0b' }} />;
      case 'cold': return <AcUnitIcon style={{ color: '#3b82f6' }} />;
      case 'archive': return <LayersIcon style={{ color: '#6b7280' }} />;
      default: return null;
    }
  };

  if (loading) {
    return <div className="intelligence-loading"><div className="loading-spinner" /><p>Scanning data storage utilization...</p></div>;
  }

  const totalSavings = activePlan?.rules
    .reduce((acc, r) => {
      const savings = parseInt(r.costSavings.replace('$', '').replace(',', '').replace('/month', ''));
      return isNaN(savings) ? acc : acc + savings;
    }, 0) || 0;

  return (
    <div className="intelligence-dashboard">
      <header className="dashboard-header">
        <button className="back-btn" onClick={() => navigate('/intelligence')}>
          <ArrowBackIcon /> Back
        </button>
        <div className="header-content">
          <LayersIcon className="header-icon" />
          <div>
            <h1>Storage Tiering</h1>
            <p>AI-driven recommendations for data lifecycle and cost optimization</p>
          </div>
        </div>
        <button className="generate-btn" onClick={handleGenerateNew} disabled={loading}>
          {loading ? 'Analyzing...' : 'Refresh Analysis'}
        </button>
      </header>

      <div className="summary-grid">
        <div className="summary-card savings">
          <TrendingDownIcon className="card-icon" />
          <div className="card-content">
            <span className="value">${totalSavings.toLocaleString()}/mo</span>
            <span className="label">Total Potential Savings</span>
          </div>
        </div>
        <div className="summary-card">
          <LayersIcon className="card-icon" />
          <div className="card-content">
            <span className="value">{activePlan?.rules.length || 0}</span>
            <span className="label">Storage Objects Analyzed</span>
          </div>
        </div>
      </div>

      <div className="suggestions-list">
        {!activePlan && <p>No tiering recommendations found.</p>}
        {activePlan?.rules.map((rule, idx) => (
          <div key={`${activePlan.id}-${idx}`} className="suggestion-card">
            <style>{`
              .suggestion-card {
                background: white;
                border: 1px solid #e5e7eb;
                border-radius: 12px;
                padding: 1.5rem;
                margin-bottom: 1rem;
                display: flex;
                flex-direction: column;
                gap: 1rem;
              }
              .suggestion-header {
                display: flex;
                justify-content: space-between;
                align-items: center;
              }
              .suggestion-title {
                display: flex;
                flex-direction: column;
              }
              .dataset-name {
                font-weight: 600;
                font-size: 1.1rem;
              }
              .table-path {
                font-size: 0.85rem;
                color: #6b7280;
              }
              .tier-transition {
                display: flex;
                align-items: center;
                gap: 0.75rem;
                background: #f9fafb;
                padding: 0.75rem 1rem;
                border-radius: 8px;
              }
              .tier-box {
                display: flex;
                align-items: center;
                gap: 0.5rem;
                font-weight: 500;
                font-size: 0.9rem;
                text-transform: capitalize;
              }
              .arrow-divider {
                color: #9ca3af;
              }
              .suggestion-meta {
                display: grid;
                grid-template-columns: repeat(4, 1fr);
                gap: 1.5rem;
                padding: 1rem 0;
                border-top: 1px solid #f3f4f6;
                border-bottom: 1px solid #f3f4f6;
              }
              .meta-item {
                display: flex;
                flex-direction: column;
                gap: 0.25rem;
              }
              .meta-label {
                font-size: 0.75rem;
                color: #6b7280;
                text-transform: uppercase;
                letter-spacing: 0.05em;
              }
              .meta-value {
                font-weight: 600;
                font-size: 1rem;
              }
              .meta-value.savings {
                color: #10b981;
              }
              .suggestion-actions {
                display: flex;
                justify-content: flex-end;
                gap: 0.75rem;
                align-items: center;
              }
              .rationale-text {
                font-size: 0.9rem;
                color: #4b5563;
                background: #f3f4f6;
                padding: 0.75rem;
                border-radius: 6px;
                border-left: 3px solid #673AB7;
              }
              .status-badge.completed {
                background: #ecfdf5;
                color: #059669;
                padding: 0.5rem 1rem;
                border-radius: 6px;
                font-weight: 500;
                display: flex;
                align-items: center;
                gap: 0.5rem;
              }
              .status-badge.migrating {
                background: #f5f3ff;
                color: #673AB7;
                padding: 0.5rem 1rem;
                border-radius: 6px;
                font-weight: 500;
                display: flex;
                align-items: center;
                gap: 0.5rem;
              }
              .migrating-spinner {
                width: 16px;
                height: 16px;
                border: 2px solid rgba(103, 58, 183, 0.2);
                border-top-color: #673AB7;
                border-radius: 50%;
                animation: spin 1s linear infinite;
              }
              @keyframes spin {
                from { transform: rotate(0deg); }
                to { transform: rotate(360deg); }
              }
              .generate-btn {
                background: #673AB7;
                color: white;
                border: none;
                padding: 0.6rem 1.2rem;
                border-radius: 8px;
                font-weight: 600;
                cursor: pointer;
                display: flex;
                align-items: center;
                gap: 0.5rem;
                transition: all 0.2s;
              }
              .generate-btn:hover:not(:disabled) {
                background: #5E35B1;
                transform: translateY(-1px);
                box-shadow: 0 4px 12px rgba(103, 58, 183, 0.2);
              }
              .generate-btn:disabled {
                opacity: 0.6;
                cursor: not-allowed;
              }
            `}</style>

            <div className="suggestion-header">
              <div className="suggestion-title">
                <span className="dataset-name">{rule.tableName}</span>
                <span className="table-path">{rule.condition}</span>
              </div>
              <div className="tier-transition">
                <div className="tier-box">
                  {getTierIcon('hot')}
                  Hot
                </div>
                <span className="arrow-divider">→</span>
                <div className="tier-box">
                  {getTierIcon(rule.targetTier)}
                  {rule.targetTier}
                </div>
