export const TenantUpgradeAssistant: React.FC = () => {
    const [impacts, setImpacts] = useState<UpgradeImpact[]>([]);
    const [loading, setLoading] = useState(true);
    const [expanded, setExpanded] = useState<string | null>(null);
    const [decisions, setDecisions] = useState<Record<string, Record<string, string>>>({});

    const tenantId = 'tenant-123'; // Mock

    useEffect(() => {
        loadImpacts();
    }, []);

    const loadImpacts = async () => {
        try {
            const data = await PageStudioApi.getUpgradeImpacts(tenantId);
            setImpacts(data);
        } catch (err) {
            console.error('Failed to load upgrade impacts', err);
        } finally {
            setLoading(false);
        }
    };

    const handleDecision = (impactId: string, conflictId: string, decision: string) => {
        setDecisions(prev => ({
            ...prev,
            [impactId]: {
                ...(prev[impactId] || {}),
                [conflictId]: decision
            }
        }));
    };

    const handleFinalize = async (impact: UpgradeImpact) => {
        try {
            await PageStudioApi.applyUpgradeDecision(impact.id, decisions[impact.id]);
            loadImpacts();
        } catch (err) {
            console.error('Failed to finalize upgrade', err);
        }
    };

    if (loading) return <Box sx={{ p: 4, textAlign: 'center' }}><CircularProgress /></Box>;

    if (impacts.length === 0) {
        return (
            <Box sx={{ p: 4, textAlign: 'center' }}>
                <SuccessIcon color="success" sx={{ fontSize: 64, mb: 2 }} />
                <Typography variant="h6">All clear! No pending upgrades.</Typography>
                <Button variant="outlined" startIcon={<HistoryIcon />} sx={{ mt: 2 }}>View Upgrade History</Button>
            </Box>
        );
    }

    return (
        <Box sx={{ p: 3, maxWidth: 900, mx: 'auto' }}>
            <Box sx={{ display: 'flex', alignItems: 'center', mb: 3 }}>
                <UpgradeIcon color="primary" sx={{ mr: 1, fontSize: 32 }} />
                <Typography variant="h5" fontWeight="bold">Tenant Upgrade Assistant</Typography>
                <Chip 
                    label={`${impacts.length} Upgrades Pending`} 
                    color="primary" 
                    size="small" 
                    sx={{ ml: 2, fontWeight: 'bold' }} 
                />
            </Box>

            <Stack spacing={3}>
                {impacts.map((impact) => (
                    <Paper key={impact.id} variant="outlined" sx={{ borderRadius: 3, overflow: 'hidden' }}>
                        <Box sx={{ p: 3, bgcolor: '#f8fafc', borderBottom: '1px solid', borderColor: 'divider' }}>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                                <Box>
                                    <Typography variant="h6" fontWeight="bold">Page Upgrade: v{impact.coreOldVersion} &rarr; v{impact.coreNewVersion}</Typography>
                                    <Typography variant="body2" color="textSecondary">{impact.summary}</Typography>
                                </Box>
                                <Button 
                                    variant="contained" 
                                    color="success" 
                                    startIcon={<SuccessIcon />}
                                    disabled={Object.keys(decisions[impact.id] || {}).length < impact.conflicts.length}
                                    onClick={() => handleFinalize(impact)}
                                >
                                    Finalize Upgrades
                                </Button>
                            </Box>
                        </Box>

                        <List sx={{ p: 0 }}>
                            {/* Conflicts section */}
                            {impact.conflicts.length > 0 && (
                                <>
                                    <ListItem sx={{ bgcolor: 'error.lighter', py: 1 }}>
                                        <ListItemIcon><ConflictIcon color="error" fontSize="small" /></ListItemIcon>
                                        <ListItemText 
                                            primary={<Typography variant="subtitle2" color="error.dark" fontWeight="bold">Conflicts ({impact.conflicts.length})</Typography>} 
                                        />
                                    </ListItem>
                                    {impact.conflicts.map((conflict, idx) => {
                                        const cId = `conflict-${idx}`;
                                        const decision = decisions[impact.id]?.[cId] || 'keep-tenant';
                                        return (
                                            <Box key={cId} sx={{ p: 3, borderBottom: '1px solid', borderColor: 'divider' }}>
                                                <Typography variant="subtitle2" gutterBottom>
                                                    {conflict.type === 'componentProp' ? `Prop Change: ${conflict.propName}` : `Component: ${conflict.componentId}`}
                                                </Typography>
                                                <Box sx={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 2, mb: 2 }}>
                                                    <Paper variant="outlined" sx={{ p: 1, bgcolor: '#fff' }}>
                                                        <Typography variant="caption" fontWeight="bold">Core Before</Typography>
                                                        <pre style={{ fontSize: '10px', margin: 0 }}>{JSON.stringify(conflict.coreBefore, null, 2)}</pre>
                                                    </Paper>
                                                    <Paper variant="outlined" sx={{ p: 1, bgcolor: 'primary.lighter' }}>
                                                        <Typography variant="caption" fontWeight="bold">Core After</Typography>
                                                        <pre style={{ fontSize: '10px', margin: 0 }}>{JSON.stringify(conflict.coreAfter, null, 2)}</pre>
                                                    </Paper>
                                                    <Paper variant="outlined" sx={{ p: 1, bgcolor: 'warning.lighter' }}>
                                                        <Typography variant="caption" fontWeight="bold">Your Override</Typography>
                                                        <pre style={{ fontSize: '10px', margin: 0 }}>{JSON.stringify(conflict.tenantOverride, null, 2)}</pre>
                                                    </Paper>
                                                </Box>
                                                <Stack direction="row" spacing={1}>
                                                    <Button 
                                                        size="small" 
                                                        variant={decision === 'keep-tenant' ? 'contained' : 'outlined'}
                                                        onClick={() => handleDecision(impact.id, cId, 'keep-tenant')}
                                                    >
                                                        Keep My Override
                                                    </Button>
                                                    <Button 
                                                        size="small" 
                                                        variant={decision === 'adopt-core' ? 'contained' : 'outlined'}
                                                        color="primary"
                                                        onClick={() => handleDecision(impact.id, cId, 'adopt-core')}
                                                    >
                                                        Adopt Core Change
                                                    </Button>
                                                </Stack>
                                            </Box>
                                        );
                                    })}
                                </>
                            )}

                            {/* Inherited section */}
                            {impact.inheritedChanges.length > 0 && (
                                <>
                                    <ListItem 
                                        button 
                                        onClick={() => setExpanded(expanded === impact.id ? null : impact.id)}
                                        sx={{ bgcolor: 'success.lighter', py: 1 }}
                                    >
                                        <ListItemIcon><InfoIcon color="success" fontSize="small" /></ListItemIcon>
                                        <ListItemText 
                                            primary={<Typography variant="subtitle2" color="success.dark" fontWeight="bold">Safe Inherited Changes ({impact.inheritedChanges.length})</Typography>} 
                                        />
                                        {expanded === impact.id ? <ExpandLessIcon /> : <ExpandMoreIcon />}
                                    </ListItem>
                                    <Collapse in={expanded === impact.id}>
                                        <Box sx={{ p: 2 }}>
                                            {impact.inheritedChanges.map((change, idx) => (
                                                <Typography key={idx} variant="caption" display="block" color="textSecondary">
                                                    &bull; {change.type}: {change.componentId || 'Layout'} updated from core.
                                                </Typography>
                                            ))}
                                        </Box>
                                    </Collapse>
                                </>
                            )}
                        </List>
                    </Paper>
                ))}
            </Stack>
        </Box>
    );
};

import React, { useState } from 'react';
import { useActor } from '../../contexts/ActorContext';
import './SchedulerConsole.css';

interface ChangeSetDiff {
  field: string;
  oldValue: string;
  newValue: string;
}

interface ImpactAnalysis {
  affectedJobs: string[];
  affectedDAGs: string[];
  affectedTenants: string[];
  downstreamImpact: number;
  sloImpact: 'none' | 'potential' | 'likely';
  complianceImpact: string;
  dataResidencyRisk: boolean;
}

interface AIReviewSummary {
  summary: string;
  riskAssessment: string;
  recommendations: string[];
  confidence: number;
}

interface ChangeSetData {
  id: string;
  type: string;
  title: string;
  description: string;
  createdBy: string;
  createdAt: string;
  status: 'draft' | 'pending_review' | 'approved' | 'rejected' | 'applied';
  targetId?: string;
  targetName?: string;
  riskScore: number;
  diffs: ChangeSetDiff[];
  impactAnalysis: ImpactAnalysis;
  aiReview?: AIReviewSummary;
  requiredApprovers: number;
  currentApprovals: number;
}

interface ChangeSetModalProps {
  isOpen: boolean;
  onClose: () => void;
  changeSet: ChangeSetData | null;
  mode: 'view' | 'create' | 'approve';
  onSubmit?: (changeSet: ChangeSetData) => void;
  onApprove?: (changeSetId: string, comment: string) => void;
  onReject?: (changeSetId: string, reason: string) => void;
}

/**
 * ChangeSetModal - Governance workflow modal for viewing/creating/approving changes
 */
const ChangeSetModal: React.FC<ChangeSetModalProps> = ({
  isOpen,
  onClose,
  changeSet,
  mode,
  onSubmit,
  onApprove,
  onReject,
}) => {
  const { permissions, role } = useActor();
  const [comment, setComment] = useState('');
  const [rejectReason, setRejectReason] = useState('');
  const [showRejectForm, setShowRejectForm] = useState(false);
  const [riskAcknowledged, setRiskAcknowledged] = useState(false);

  if (!isOpen || !changeSet) return null;

  const isHighRisk = changeSet.riskScore >= 0.7;

  const getRiskColor = (score: number): string => {
    if (score >= 0.7) return '#dc2626';
    if (score >= 0.4) return '#ea580c';
    if (score >= 0.2) return '#ca8a04';
    return '#16a34a';
  };

  const getStatusBadge = (status: string): string => {
    switch (status) {
      case 'draft': return 'status-draft';
      case 'pending_review': return 'status-pending';
      case 'approved': return 'status-approved';
      case 'rejected': return 'status-rejected';
      case 'applied': return 'status-applied';
      default: return '';
    }
  };

  const handleApprove = () => {
    if (onApprove) {
      onApprove(changeSet.id, comment);
      onClose();
    }
  };

  const handleReject = () => {
    if (onReject && rejectReason.trim()) {
      onReject(changeSet.id, rejectReason);
      onClose();
    }
  };

  const handleSubmit = () => {
    if (onSubmit) {
      onSubmit(changeSet);
      onClose();
    }
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="changeset-modal" onClick={e => e.stopPropagation()}>
        {/* Header */}
        <div className="modal-header">
          <div className="header-content">
            <span className={`status-badge ${getStatusBadge(changeSet.status)}`}>
              {changeSet.status.replace('_', ' ')}
            </span>
            <h2>{changeSet.title}</h2>
            <p className="changeset-type">{changeSet.type}</p>
          </div>
          <button className="close-btn" onClick={onClose}>×</button>
        </div>

        {/* Content */}
        <div className="modal-content">
          {/* Risk Score */}
          <div className="risk-section">
            <div className="risk-indicator">
              <span 
                className="risk-circle"
                style={{ backgroundColor: getRiskColor(changeSet.riskScore) }}
              >
                {Math.round(changeSet.riskScore * 100)}%
              </span>
              <span className="risk-label">Risk Score</span>
            </div>
            <div className="approval-status">
              <span className="approvals">
                {changeSet.currentApprovals} / {changeSet.requiredApprovers} approvals
              </span>
            </div>
          </div>

          {/* Diff View */}
          <div className="diff-section">
            <h3>Changes</h3>
            <div className="diff-list">
              {changeSet.diffs.map((diff, i) => (
                <div key={i} className="diff-item">
                  <span className="diff-field">{diff.field}</span>
                  <div className="diff-values">
                    <span className="diff-old">- {diff.oldValue}</span>
                    <span className="diff-new">+ {diff.newValue}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Impact Analysis */}
          <div className="impact-section">
            <h3>Impact Analysis</h3>
            <div className="impact-grid">
              {changeSet.impactAnalysis.affectedJobs.length > 0 && (
                <div className="impact-item">
                  <span className="impact-label">Affected Jobs</span>
                  <span className="impact-value">
                    {changeSet.impactAnalysis.affectedJobs.join(', ')}
                  </span>
                </div>
              )}
              {changeSet.impactAnalysis.affectedTenants.length > 0 && (
                <div className="impact-item">
                  <span className="impact-label">Affected Tenants</span>
                  <span className="impact-value">
                    {changeSet.impactAnalysis.affectedTenants.join(', ')}
                  </span>
                </div>
              )}
              <div className="impact-item">
                <span className="impact-label">Downstream Impact</span>
                <span className="impact-value">
                  {changeSet.impactAnalysis.downstreamImpact} jobs
                </span>
              </div>
              <div className="impact-item">
                <span className="impact-label">SLO Impact</span>
                <span className={`impact-value slo-${changeSet.impactAnalysis.sloImpact}`}>
                  {changeSet.impactAnalysis.sloImpact}
                </span>
              </div>
              {changeSet.impactAnalysis.dataResidencyRisk && (
                <div className="impact-item warning">
                  <span className="impact-label">⚠️ Data Residency</span>
                  <span className="impact-value">Risk Detected</span>
                </div>
              )}
            </div>
          </div>

          {/* AI Review */}
          {changeSet.aiReview && (
            <div className="ai-review-section">
              <h3>
                <span className="ai-icon">🤖</span>
                AI Review Summary
              </h3>
              <div className="ai-content">
                <p className="ai-summary">{changeSet.aiReview.summary}</p>
                <div className="ai-risk">
                  <strong>Risk Assessment:</strong> {changeSet.aiReview.riskAssessment}
                </div>
                {changeSet.aiReview.recommendations.length > 0 && (
                  <div className="ai-recommendations">
                    <strong>Recommendations:</strong>
                    <ul>
                      {changeSet.aiReview.recommendations.map((rec, i) => (
                        <li key={i}>{rec}</li>
                      ))}
                    </ul>
                  </div>
                )}
                <div className="ai-confidence">
                  Confidence: {Math.round(changeSet.aiReview.confidence * 100)}%
                </div>
              </div>
            </div>
          )}

          {/* Approval Controls (for Global Ops in approve mode) */}
          {mode === 'approve' && permissions.canApproveChangeSets && (
            <div className="approval-section">
              <h3>Approval Decision</h3>

              {!showRejectForm ? (
                <>
                  <div className="comment-input">
                    <label>Comment (optional)</label>
                    <textarea
                      value={comment}
                      onChange={e => setComment(e.target.value)}
                      placeholder="Add a comment for the approval..."
                    />
                  </div>
                  <div className="approval-actions">
                    <button className="approve-btn" onClick={handleApprove}>
                      ✓ Approve
                    </button>
                    <button 
                      className="reject-btn" 
                      onClick={() => setShowRejectForm(true)}
                    >
                      ✗ Reject
                    </button>
                  </div>
                </>
              ) : (
                <>
                  <div className="reject-input">
                    <label>Rejection Reason (required)</label>
                    <textarea
                      value={rejectReason}
                      onChange={e => setRejectReason(e.target.value)}
                      placeholder="Provide a reason for rejection..."
                      required
                    />
                  </div>
                  <div className="approval-actions">
                    <button 
                      className="reject-btn" 
                      onClick={handleReject}
                      disabled={!rejectReason.trim()}
                    >
                      Confirm Rejection
                    </button>
                    <button 
                      className="cancel-btn" 
                      onClick={() => setShowRejectForm(false)}
                    >
                      Cancel
                    </button>
                  </div>
                </>
              )}
            </div>
          )}

          {/* Submit for Review (for create mode) */}
          {mode === 'create' && (
            <div className="submit-section">
              {isHighRisk && (
                <div className="risk-acknowledgment">
                  <label className="checkbox-label">
                    <input 
                      type="checkbox" 
                      checked={riskAcknowledged}
                      onChange={e => setRiskAcknowledged(e.target.checked)}
                    />
                    I acknowledge this is a HIGH RISK change ({Math.round(changeSet.riskScore * 100)}%).
                    It may require dry-run verification or ops approval.
                  </label>
                </div>
              )}
              <button 
                className="submit-btn" 
                onClick={handleSubmit}
                disabled={isHighRisk && !riskAcknowledged}
              >
                Submit for Review
              </button>
              <p className="submit-note">
                This will create a ChangeSet that requires approval before taking effect.
              </p>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="modal-footer">
          <div className="footer-meta">
            <span>Created by {changeSet.createdBy}</span>
            <span>•</span>
            <span>{new Date(changeSet.createdAt).toLocaleString()}</span>
          </div>
          <button className="close-btn-secondary" onClick={onClose}>
            Close
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChangeSetModal;

/**
 * DAGs View - Manage Directed Acyclic Graphs of jobs
 */

import React, { useState, useMemo } from 'react';
import { 
  Plus, 
  Search, 
  Play, 
  Pause, 
  Trash2, 
  Edit2,
  GitBranch,
  Clock,
  CheckCircle,
  XCircle,
  Eye
} from 'lucide-react';
import { useTenantContext } from '../../hooks/useTenantContext';
import { useDAGs, DAG, triggerDAG, deleteDAG, updateDAG } from '../../api/schedulerApi';
import SemanticBindingsList from '../../components/scheduler/SemanticBindingsList';

const DAGsView: React.FC = () => {
  const { selectedTenant } = useTenantContext();
  const tenantId = selectedTenant?.id;
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedDAG, setSelectedDAG] = useState<DAG | null>(null);
  const [activeOnly, setActiveOnly] = useState(false);

  const { dags, loading, error, refetch } = useDAGs(tenantId || '', activeOnly);

  const filteredDAGs = useMemo(() => {
    if (!dags) return [];
    return dags.filter((dag: DAG) => {
      return dag.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        dag.description?.toLowerCase().includes(searchQuery.toLowerCase());
    });
  }, [dags, searchQuery]);

  const handleTrigger = async (dag: DAG, mode?: string) => {
    try {
      await triggerDAG(dag.id, mode);
      refetch();
    } catch (err) {
      console.error(`Failed to trigger DAG (${mode || 'normal'}):`, err);
    }
  };

  const handleToggleActive = async (dag: DAG) => {
    try {
      await updateDAG(dag.id, { is_active: !dag.is_active });
      refetch();
    } catch (err) {
      console.error('Failed to update DAG:', err);
    }
  };

  const handleDelete = async (dag: DAG) => {
    if (!confirm(`Delete DAG "${dag.name}"?`)) return;
    try {
      await deleteDAG(dag.id);
      refetch();
    } catch (err) {
      console.error('Failed to delete DAG:', err);
    }
  };

  if (loading) {
    return <div className="loading-state">Loading DAGs...</div>;
  }

  if (error) {
    return <div className="error-state">Error loading DAGs: {error.message}</div>;
  }

  return (
    <div className="dags-view">
      {/* Toolbar */}
      <div className="toolbar">
        <div className="toolbar-left">
          <div className="search-box">
            <Search className="search-icon" />
            <input
              type="text"
              placeholder="Search DAGs..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>

          <label className="checkbox-filter">
            <input 
              type="checkbox" 
              checked={activeOnly}
              onChange={(e) => setActiveOnly(e.target.checked)}
            />
            Active Only
          </label>
        </div>

        <div className="toolbar-right">
          <button className="btn-primary">
            <Plus /> New DAG
          </button>
        </div>
      </div>

      {/* DAGs Grid */}
      <div className="dags-grid">
        {filteredDAGs.length === 0 ? (
          <div className="empty-state">
            <GitBranch className="empty-icon" />
            <h3>No DAGs Found</h3>
            <p>Create a new DAG to orchestrate multiple jobs</p>
          </div>
        ) : (
          filteredDAGs.map((dag: DAG) => (
            <div 
              key={dag.id} 
              className={`dag-card ${!dag.is_active ? 'inactive' : ''}`}
            >
              <div className="dag-card-header">
                <div className="dag-info">
                  <h3 className="dag-name">{dag.name}</h3>
                  {dag.category && (
                    <span className="dag-category">{dag.category}</span>
                  )}
                </div>
                <span className={`status-indicator ${dag.is_active ? 'active' : 'inactive'}`} />
              </div>

              {dag.description && (
                <p className="dag-description">{dag.description}</p>
              )}

              <div className="dag-stats">
                <div className="stat">
                  <span className="stat-value">{dag.nodes?.length || 0}</span>
                  <span className="stat-label">Nodes</span>
                </div>
                <div className="stat">
                  <span className="stat-value">{dag.edges?.length || 0}</span>
                  <span className="stat-label">Edges</span>
                </div>
                <div className="stat">
                  <span className="stat-value">{dag.max_parallel_jobs}</span>
                  <span className="stat-label">Max Parallel</span>
                </div>
              </div>

              {dag.next_run_at && (
                <div className="dag-next-run">
                  <Clock className="icon" />
                  <span>Next: {formatDateTime(dag.next_run_at)}</span>
                </div>
              )}

              <div className="dag-card-actions">
                <button 
                  className="action-btn"
                  title="View Graph"
                  onClick={() => setSelectedDAG(dag)}
                >
                  <Eye />
                </button>
                <button 
                  className="action-btn"
                  title="Run Now"
                  onClick={() => handleTrigger(dag)}
                >
                  <Play />
                </button>
                <button 
                  className="action-btn secondary"
                  title="Dry Run"
                  onClick={() => handleTrigger(dag, 'DRY_RUN')}
                  style={{ fontSize: '0.8em' }}
                >
                  Dry
                </button>
                <button 
                  className="action-btn"
                  title={dag.is_active ? 'Pause' : 'Resume'}
                  onClick={() => handleToggleActive(dag)}
                >
                  <Pause />
                </button>
                <button 
                  className="action-btn"
                  title="Edit"
                >
                  <Edit2 />
                </button>
                <button 
                  className="action-btn danger"
                  title="Delete"
                  onClick={() => handleDelete(dag)}
                >
                  <Trash2 />
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      {/* DAG Graph Modal */}
      {selectedDAG && (
        <DAGGraphModal 
          dag={selectedDAG} 
          onClose={() => setSelectedDAG(null)} 
        />
      )}
    </div>
  );
};

interface DAGGraphModalProps {
  dag: DAG;
  onClose: () => void;
}

const DAGGraphModal: React.FC<DAGGraphModalProps> = ({ dag, onClose }) => {
  // Simple text-based DAG visualization
  const nodeMap = useMemo(() => {
    const map = new Map<string, string>();
    dag.nodes?.forEach(node => {
      map.set(node.id, node.job_id);
    });
    return map;
  }, [dag.nodes]);

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="dag-graph-modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2>{dag.name}</h2>
          <button className="close-btn" onClick={onClose}>&times;</button>
        </div>

        <div className="modal-content">
          <div className="dag-info-section">
            <h3>Configuration</h3>
            <dl>
              <dt>Max Parallel Jobs</dt>
              <dd>{dag.max_parallel_jobs}</dd>
              <dt>Fail Fast</dt>
              <dd>{dag.fail_fast ? 'Yes' : 'No'}</dd>
              <dt>Timeout</dt>
              <dd>{dag.timeout_seconds}s</dd>
            </dl>
          </div>

          <div className="dag-info-section">
            {dag.slo_critical && (
              <div className="slo-alert" style={{marginBottom: '10px'}}>
                  <span className="slo-badge critical">SLO Critical</span>
                  <a href={`/intelligence/slo?dag=${dag.id}`} className="slo-link" style={{marginLeft: '10px'}}>
                    View Forecast
                  </a>
              </div>
            )}
            <SemanticBindingsList bindings={dag.semantic_bindings} />
          </div>

          <div className="dag-structure-section">
            <h3>Structure</h3>
            <div className="nodes-list">
              <h4>Nodes ({dag.nodes?.length || 0})</h4>
              {dag.nodes?.map((node) => (
                <div key={node.id} className="node-item">
                  <span className="node-id">{node.id}</span>
                  <span className="node-job">Job: {node.job_id}</span>
                </div>
              ))}
            </div>

            <div className="edges-list">
              <h4>Edges ({dag.edges?.length || 0})</h4>
              {dag.edges?.map((edge, idx) => (
                <div key={idx} className="edge-item">
                  <span>{edge.from_node_id}</span>
                  <span className="arrow">→</span>
                  <span>{edge.to_node_id}</span>
                  {edge.type && <span className="edge-type">({edge.type})</span>}
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

function formatDateTime(isoString: string): string {
  const date = new Date(isoString);
  return date.toLocaleString(undefined, {
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
}

export default DAGsView;

