// Semantic Playground Main Page
import React, { useEffect, useState } from "react";
import {
  Box,
  Container,
  Grid,
  Paper,
  AppBar,
  Toolbar,
  Typography,
  Alert,
  Snackbar,
} from "@mui/material";
import StorageIcon from "@mui/icons-material/Storage";
import {
  NLInputPanel,
  SemanticQueryEditor,
  SQLViewer,
  ResultsTable,
} from "./components";
import {
  usePlanner,
  useExecutor,
  useSQLRunner,
  useSemanticBundle,
} from "./hooks";
import { semanticPlaygroundApi } from "./utils/api";
import { SemanticQuery, Datasource } from "./types";

export const SemanticPlaygroundPage: React.FC = () => {
  // State management
  const [datasources, setDatasources] = useState<Datasource[]>([]);
  const [selectedDatasource, setSelectedDatasource] = useState<string | null>(
    null
  );
  const [selectedVersion, setSelectedVersion] = useState<string | null>(null);
  const [nlPrompt, setNlPrompt] = useState("");
  const [mode, setMode] = useState<"exploratory" | "strict" | "CRUD">(
    "exploratory"
  );
  const [snackbar, setSnackbar] = useState<{
    open: boolean;
    message: string;
    severity: "success" | "error" | "warning";
  }>({ open: false, message: "", severity: "success" });

  // Hooks
  const { bundle, versions, loading: bundleLoading, fetchBundle, fetchVersions } =
    useSemanticBundle();
  const {
    semanticQuery,
    explanation,
    loading: plannerLoading,
    error: plannerError,
    warnings: plannerWarnings,
    callPlanner,
  } = usePlanner();
  const {
    generatedSQL,
    loading: executorLoading,
    error: executorError,
    warnings: executorWarnings,
    callExecutor,
  } = useExecutor();
  const {
    results,
    executionTime,
    loading: sqlRunnerLoading,
    error: sqlRunnerError,
    runSQL,
  } = useSQLRunner();

  // Load datasources on mount
  useEffect(() => {
    const loadDatasources = async () => {
      try {
        const ds = await semanticPlaygroundApi.getDatasources();
        setDatasources(ds);
        if (ds.length > 0) {
          setSelectedDatasource(ds[0].id);
        }
      } catch (err) {
        showSnackbar("Failed to load datasources", "error");
      }
    };

    loadDatasources();
  }, []);

  // Load bundle and versions when datasource changes
  useEffect(() => {
    if (selectedDatasource) {
      fetchBundle(selectedDatasource);
      fetchVersions(selectedDatasource);
    }
  }, [selectedDatasource]);

  // Set default version when versions load
  useEffect(() => {
    if (versions.length > 0 && !selectedVersion) {
      setSelectedVersion(versions[0].version);
    }
  }, [versions]);

  const showSnackbar = (message: string, severity: "success" | "error" | "warning") => {
    setSnackbar({ open: true, message, severity });
  };

  const handleGenerateQuery = async () => {
    if (!selectedDatasource || !selectedVersion || !nlPrompt) {
      showSnackbar("Please fill in all required fields", "warning");
      return;
    }

    await callPlanner({
      datasource: selectedDatasource,
      version: selectedVersion,
      prompt: nlPrompt,
      mode,
    });
  };

  const handleExecuteQuery = async () => {
    if (!semanticQuery || !selectedDatasource || !selectedVersion) {
      showSnackbar("Generate a semantic query first", "warning");
      return;
    }

    await callExecutor({
      datasource: selectedDatasource,
      version: selectedVersion,
      semantic_query: semanticQuery,
    });
  };

  const handleRunSQL = async () => {
    if (!generatedSQL) {
      showSnackbar("Generate SQL first", "warning");
      return;
    }

    await runSQL(generatedSQL);
  };

  const handleUpdateSemanticQuery = (newQuery: SemanticQuery) => {
    // This would require modifying the planner hook to support manual updates
    // For now, just refresh semantic query
    showSnackbar("Query updated. Run again to regenerate SQL.", "success");
  };

  const handleExplainQuery = async (): Promise<string> => {
    if (!semanticQuery || !selectedDatasource) {
      throw new Error("No query to explain");
    }

    try {
      const explanation = await semanticPlaygroundApi.explainQuery(
        selectedDatasource,
        semanticQuery
      );
      return explanation;
    } catch (err) {
      throw new Error("Failed to explain query: " + (err as Error).message);
    }
  };

  const handleExportCSV = () => {
    if (!results?.rows) {
      showSnackbar("No results to export", "warning");
      return;
    }

    const rows = results.rows;
    const columns = results.columns || Object.keys(rows[0]);

    const csvContent = [
      columns.map((c) => `"${c}"`).join(","),
      ...rows.map((row) =>
        columns
          .map((col) => {
            const val = row[col];
            if (val === null || val === undefined) return '""';
            if (typeof val === "string" && val.includes(","))
              return `"${val.replace(/"/g, '""')}"`;
            return `"${val}"`;
          })
          .join(",")
      ),
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `query-results-${Date.now()}.csv`;
    a.click();
    URL.revokeObjectURL(url);

    showSnackbar("CSV exported successfully", "success");
  };

  return (
    <Box sx={{ backgroundColor: "#0d1117", minHeight: "100vh", pb: 4 }}>
      {/* Top Bar */}
      <AppBar
        position="sticky"
        sx={{ backgroundColor: "#0d1117", borderBottom: "1px solid #333" }}
      >
        <Toolbar>
          <StorageIcon sx={{ mr: 1.5, color: "#2196F3" }} />
          <Typography
            variant="h6"
            component="div"
            sx={{ fontWeight: 700, color: "#fff" }}
          >
            Semantic Playground
          </Typography>
          <Typography
            variant="caption"
            sx={{ ml: "auto", color: "#666", fontStyle: "italic" }}
          >
            Natural Language → Semantic Query → SQL → Results
          </Typography>
        </Toolbar>
      </AppBar>

      <Container maxWidth="xl" sx={{ mt: 3 }}>
        {/* Information Alert */}
        <Alert
          severity="info"
          sx={{
            mb: 3,
            backgroundColor: "#1e2d3d",
            borderColor: "#2196F3",
            color: "#2196F3",
          }}
        >
          🎮 <strong>Welcome to the Semantic Playground!</strong> Write natural language
          queries and see them transformed into semantic queries and SQL. Perfect for
          learning, debugging, and exploring the semantic layer.
        </Alert>

        {/* Three-Pane Layout */}
        <Grid container spacing={2} sx={{ height: "calc(100vh - 200px)" }}>
          {/* Left Pane: Natural Language Input */}
          <Grid item xs={12} md={4} sx={{ display: "flex" }}>
            <Paper sx={{ width: "100%", overflow: "auto" }}>
              <NLInputPanel
                datasources={datasources}
                selectedDatasource={selectedDatasource}
                selectedVersion={selectedVersion}
                versions={versions}
                prompt={nlPrompt}
                mode={mode}
                loading={plannerLoading || executorLoading}
                error={plannerError}
                onDatasourceChange={setSelectedDatasource}
                onVersionChange={setSelectedVersion}
                onPromptChange={setNlPrompt}
                onModeChange={setMode}
                onGenerate={handleGenerateQuery}
                onClear={() => {
                  setNlPrompt("");
                }}
                bundle={bundle}
              />
            </Paper>
          </Grid>

          {/* Middle Pane: Semantic Query */}
          <Grid item xs={12} md={4} sx={{ display: "flex" }}>
            <Paper sx={{ width: "100%", overflow: "auto" }}>
              <SemanticQueryEditor
                query={semanticQuery}
                bundle={bundle}
                loading={plannerLoading}
                error={plannerError}
                warnings={plannerWarnings}
                onQueryChange={handleUpdateSemanticQuery}
                onExplain={handleExplainQuery}
              />
            </Paper>
          </Grid>

          {/* Right Pane: SQL + Results (stacked) */}
          <Grid item xs={12} md={4} sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
            {/* SQL Viewer - Top */}
            <Paper sx={{ flex: 0.4, overflow: "auto" }}>
              <SQLViewer
                sql={generatedSQL}
                loading={executorLoading}
                error={executorError}
                warnings={executorWarnings}
                onExecute={handleRunSQL}
                onDownloadCSV={handleExportCSV}
                executingSQL={sqlRunnerLoading}
              />
            </Paper>

            {/* Results Table - Bottom */}
            <Paper sx={{ flex: 0.6, overflow: "auto" }}>
              <ResultsTable
                results={results}
                executionTime={executionTime}
                loading={sqlRunnerLoading}
                error={sqlRunnerError}
                sql={generatedSQL || undefined}
              />
            </Paper>
          </Grid>
        </Grid>

        {/* Workflow Steps */}
        <Paper
          sx={{
            mt: 3,
            p: 2,
            backgroundColor: "#1e1e1e",
            border: "1px solid #333",
          }}
        >
          <Typography variant="caption" sx={{ color: "#666" }}>
            💡 <strong>Workflow:</strong> 1️⃣ Select datasource & version → 2️⃣ Write
            natural language question → 3️⃣ Click "Generate Query" → 4️⃣ Review semantic
            query (edit if needed) → 5️⃣ Click "Execute" to generate SQL → 6️⃣ SQL
            executes automatically → 7️⃣ Review results & export CSV
          </Typography>
        </Paper>
      </Container>

      {/* Snackbar for notifications */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={() => setSnackbar({ ...snackbar, open: false })}
        anchorOrigin={{ vertical: "bottom", horizontal: "right" }}
      >
        <Alert
          onClose={() => setSnackbar({ ...snackbar, open: false })}
          severity={snackbar.severity}
          sx={{ width: "100%" }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default SemanticPlaygroundPage;

// Results Table Component
import React, { useState, useMemo } from "react";
import {
  Box,
  Button,
  Card,
  CardContent,
  CircularProgress,
  Chip,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TablePagination,
  TableRow,
  TableSortLabel,
  Typography,
  TextField,
  InputAdornment,
  Alert,
} from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import GetAppIcon from "@mui/icons-material/GetApp";
import { QueryExecutionResponse } from "../types";

interface ResultsTableProps {
  results: QueryExecutionResponse | null;
  executionTime: number | null;
  loading: boolean;
  error?: string;
  sql?: string;
}

type SortOrder = "asc" | "desc";

export const ResultsTable: React.FC<ResultsTableProps> = ({
  results,
  executionTime,
  loading,
  error,
  sql,
}) => {
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(20);
  const [sortColumn, setSortColumn] = useState<string | null>(null);
  const [sortOrder, setSortOrder] = useState<SortOrder>("asc");
  const [searchText, setSearchText] = useState("");

  const paginatedRows = useMemo(() => {
    if (!results?.rows) return [];

    let filtered = results.rows;

    // Apply search filter
    if (searchText) {
      filtered = filtered.filter((row) =>
        Object.values(row).some((val) =>
          String(val).toLowerCase().includes(searchText.toLowerCase())
        )
      );
    }

    // Apply sorting
    if (sortColumn) {
      filtered = [...filtered].sort((a, b) => {
        const aVal = a[sortColumn];
        const bVal = b[sortColumn];

        if (aVal === null || aVal === undefined) return 1;
        if (bVal === null || bVal === undefined) return -1;

        let comparison = 0;
        if (typeof aVal === "number" && typeof bVal === "number") {
          comparison = aVal - bVal;
        } else {
          comparison = String(aVal).localeCompare(String(bVal));
        }

        return sortOrder === "asc" ? comparison : -comparison;
      });
    }

    // Apply pagination
    return filtered.slice(page * rowsPerPage, (page + 1) * rowsPerPage);
  }, [results, page, rowsPerPage, sortColumn, sortOrder, searchText]);

  const handleSort = (column: string) => {
    if (sortColumn === column) {
      setSortOrder(sortOrder === "asc" ? "desc" : "asc");
    } else {
      setSortColumn(column);
      setSortOrder("asc");
    }
  };

  const handleChangePage = (event: unknown, newPage: number) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleExportCSV = () => {
    if (!results?.rows || results.rows.length === 0) return;

    const rows = results.rows;
    const columns = results.columns || Object.keys(rows[0]);

    // Create CSV header
    const csvContent = [
      columns.map((c) => `"${c}"`).join(","),
      ...rows.map((row) =>
        columns
          .map((col) => {
            const val = row[col];
            if (val === null || val === undefined) return '""';
            if (typeof val === "string" && val.includes(","))
              return `"${val.replace(/"/g, '""')}"`;
            return `"${val}"`;
          })
          .join(",")
      ),
    ].join("\n");

    // Download
    const blob = new Blob([csvContent], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `query-results-${Date.now()}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  if (loading) {
    return (
      <Card
        sx={{
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          backgroundColor: "#1e1e1e",
          border: "1px solid #333",
        }}
      >
        <Stack alignItems="center" spacing={2}>
          <CircularProgress sx={{ color: "#2196F3" }} />
          <Typography sx={{ color: "#999" }}>Executing query...</Typography>
        </Stack>
      </Card>
    );
  }

  if (error) {
    return (
      <Card
        sx={{
          height: "100%",
          backgroundColor: "#1e1e1e",
          border: "1px solid #333",
        }}
      >
        <CardContent>
          <Alert severity="error">{error}</Alert>
        </CardContent>
      </Card>
    );
  }

  if (!results || results.rows.length === 0) {
    return (
      <Card
        sx={{
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          backgroundColor: "#1e1e1e",
          border: "1px solid #333",
        }}
      >
        <Typography sx={{ color: "#666" }}>
          No results yet. Execute a query to see data.
        </Typography>
      </Card>
    );
  }

  const columns = results.columns || Object.keys(results.rows[0]);
  const totalFiltered = searchText
    ? results.rows.filter((row) =>
        Object.values(row).some((val) =>
          String(val).toLowerCase().includes(searchText.toLowerCase())
        )
      ).length
    : results.row_count;

  return (
    <Card
      sx={{
        height: "100%",
        display: "flex",
        flexDirection: "column",
        backgroundColor: "#1e1e1e",
        border: "1px solid #333",
      }}
    >
      <CardContent
        sx={{
          flex: 1,
          display: "flex",
          flexDirection: "column",
          gap: 2,
          overflow: "hidden",
          p: 2,
        }}
      >
        <Stack direction="row" spacing={2} alignItems="center">
          <Typography variant="h6" sx={{ fontWeight: 600, color: "#fff" }}>
            Results
          </Typography>
          <Chip
            label={`${totalFiltered} rows`}
            size="small"
            sx={{ backgroundColor: "#2d2d2d", color: "#aaa" }}
          />
          {executionTime !== null && (
            <Chip
              label={`${executionTime}ms`}
              size="small"
              sx={{ backgroundColor: "#2d2d2d", color: "#4CAF50" }}
            />
          )}
        </Stack>

        {/* Search */}
        <TextField
          fullWidth
          size="small"
          placeholder="Search results..."
          value={searchText}
          onChange={(e) => {
            setSearchText(e.target.value);
            setPage(0);
          }}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon sx={{ color: "#666" }} />
              </InputAdornment>
            ),
          }}
          sx={{
            "& .MuiOutlinedInput-root": {
              backgroundColor: "#2d2d2d",
              color: "#fff",
              "& fieldset": { borderColor: "#444" },
              "&:hover fieldset": { borderColor: "#666" },
            },
          }}
        />

        {/* Table */}
        <TableContainer
          sx={{
            flex: 1,
            backgroundColor: "#2d2d2d",
            borderRadius: 1,
            overflow: "auto",
          }}
        >
          <Table stickyHeader size="small">
            <TableHead>
              <TableRow sx={{ backgroundColor: "#1e1e1e" }}>
                {columns.map((col) => (
                  <TableCell
                    key={col}
                    sortDirection={
                      sortColumn === col ? sortOrder : false
                    }
                    sx={{
                      backgroundColor: "#1e1e1e",
                      borderBottom: "1px solid #444",
                      color: "#999",
                      fontWeight: 600,
                      fontSize: "12px",
                    }}
                  >
                    <TableSortLabel
                      active={sortColumn === col}
                      direction={sortOrder}
                      onClick={() => handleSort(col)}
                      sx={{
                        color: sortColumn === col ? "#2196F3" : "#999",
                        "&:hover": { color: "#2196F3" },
                      }}
                    >
                      {col}
                    </TableSortLabel>
                  </TableCell>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {paginatedRows.map((row, idx) => (
                <TableRow
                  key={idx}
                  sx={{
                    backgroundColor: idx % 2 === 0 ? "#2d2d2d" : "#333",
                    "&:hover": { backgroundColor: "#3d3d3d" },
                    borderBottom: "1px solid #444",
                  }}
                >
                  {columns.map((col) => (
                    <TableCell
                      key={col}
                      sx={{
                        color: "#ddd",
                        fontSize: "12px",
                        padding: "8px",
                        fontFamily: 'monospace',
                      }}
                    >
                      {row[col] === null || row[col] === undefined
                        ? "NULL"
                        : typeof row[col] === "boolean"
                        ? String(row[col])
                        : typeof row[col] === "object"
                        ? JSON.stringify(row[col])
                        : String(row[col])}
                    </TableCell>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        {/* Pagination */}
        <Stack direction="row" justifyContent="space-between" alignItems="center">
          <TablePagination
            rowsPerPageOptions={[10, 20, 50, 100]}
            component="div"
            count={totalFiltered}
            rowsPerPage={rowsPerPage}
            page={page}
            onPageChange={handleChangePage}
            onRowsPerPageChange={handleChangeRowsPerPage}
            sx={{
              color: "#999",
              "& .MuiTablePagination-selectLabel": { margin: 0 },
              "& .MuiTablePagination-displayedRows": { margin: 0 },
              "& .MuiInputBase-root": { color: "#999" },
            }}
          />
          <Button
            size="small"
            variant="outlined"
            startIcon={<GetAppIcon />}
            onClick={handleExportCSV}
            sx={{
              borderColor: "#555",
              color: "#999",
              textTransform: "none",
              "&:hover": {
                borderColor: "#777",
              },
            }}
          >
            Export CSV
          </Button>
        </Stack>
      </CardContent>
    </Card>
  );
};

// SQL Viewer Component
import React, { useState } from "react";
import {
  Box,
  Button,
  Card,
  CardContent,
  CircularProgress,
  Stack,
  Typography,
  Alert,
} from "@mui/material";
import ContentCopyIcon from "@mui/icons-material/ContentCopy";
import PlayArrowIcon from "@mui/icons-material/PlayArrow";
import GetAppIcon from "@mui/icons-material/GetApp";

interface SQLViewerProps {
  sql: string | null;
  loading: boolean;
  error?: string;
  warnings?: string[];
  onExecute?: () => void;
  onDownloadCSV?: () => void;
  executingSQL?: boolean;
}

export const SQLViewer: React.FC<SQLViewerProps> = ({
  sql,
  loading,
  error,
  warnings,
  onExecute,
  onDownloadCSV,
  executingSQL,
}) => {
  const handleCopySQL = () => {
    if (sql) {
      navigator.clipboard.writeText(sql);
      alert("SQL copied to clipboard!");
    }
  };

  const formatSQL = (sqlText: string): string => {
    // Simple SQL formatting (could use a library like sql-formatter)
    return sqlText
      .replace(/\s+/g, " ")
      .replace(/\bSELECT\b/gi, "\nSELECT")
      .replace(/\bFROM\b/gi, "\nFROM")
      .replace(/\bWHERE\b/gi, "\nWHERE")
      .replace(/\bJOIN\b/gi, "\nJOIN")
      .replace(/\bLEFT JOIN\b/gi, "\nLEFT JOIN")
      .replace(/\bORDER BY\b/gi, "\nORDER BY")
      .replace(/\bLIMIT\b/gi, "\nLIMIT")
      .replace(/\bGROUP BY\b/gi, "\nGROUP BY")
      .trim();
  };

  return (
    <Card
      sx={{
        height: "100%",
        display: "flex",
        flexDirection: "column",
        backgroundColor: "#1e1e1e",
        border: "1px solid #333",
      }}
    >
      <CardContent
        sx={{
          flex: 1,
          display: "flex",
          flexDirection: "column",
          gap: 2,
          overflow: "hidden",
          p: 2,
        }}
      >
        <Typography variant="h6" sx={{ fontWeight: 600, color: "#fff" }}>
          Generated SQL
        </Typography>

        {/* SQL Display */}
        {sql ? (
          <Box
            sx={{
              flex: 1,
              backgroundColor: "#0d1117",
              border: "1px solid #30363d",
              borderRadius: 1,
              p: 1.5,
              fontFamily: '"Fira Code", monospace',
              fontSize: "12px",
              overflow: "auto",
              color: "#c9d1d9",
              position: "relative",
            }}
          >
            <pre
              style={{
                margin: 0,
                padding: 0,
                whiteSpace: "pre-wrap",
                wordWrap: "break-word",
                lineHeight: "1.6",
              }}
            >
              {formatSQL(sql)}
            </pre>
          </Box>
        ) : loading ? (
          <Box
            sx={{
              flex: 1,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              color: "#666",
            }}
          >
            <Stack alignItems="center" spacing={1}>
              <CircularProgress size={40} sx={{ color: "#2196F3" }} />
              <Typography sx={{ color: "#999" }}>Generating SQL...</Typography>
            </Stack>
          </Box>
        ) : (
          <Box
            sx={{
              flex: 1,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              color: "#666",
              backgroundColor: "#2d2d2d",
              borderRadius: 1,
              border: "2px dashed #444",
            }}
          >
            <Typography sx={{ color: "#999" }}>
              No SQL yet. Generate a query first.
            </Typography>
          </Box>
        )}

        {/* Warnings */}
        {warnings && warnings.length > 0 && (
          <Alert severity="warning" sx={{ backgroundColor: "#3d2d1f" }}>
            {warnings.map((w, i) => (
              <div key={i}>⚠️ {w}</div>
            ))}
          </Alert>
        )}

        {/* Error */}
        {error && <Alert severity="error">{error}</Alert>}

        {/* Action buttons */}
        <Stack direction="row" spacing={1}>
          {sql && (
            <>
              <Button
                size="small"
                variant="contained"
                startIcon={
                  executingSQL ? (
                    <CircularProgress size={16} />
                  ) : (
                    <PlayArrowIcon />
                  )
                }
                onClick={onExecute}
                disabled={executingSQL}
                sx={{
                  backgroundColor: "#4CAF50",
                  "&:hover": { backgroundColor: "#45a049" },
                  textTransform: "none",
                  fontWeight: 600,
                }}
              >
                {executingSQL ? "Executing..." : "Execute"}
              </Button>
              <Button
                size="small"
                variant="outlined"
                startIcon={<ContentCopyIcon />}
                onClick={handleCopySQL}
                sx={{
                  borderColor: "#555",
                  color: "#999",
                  textTransform: "none",
                  "&:hover": {
                    borderColor: "#777",
                  },
                }}
              >
                Copy
              </Button>
              {onDownloadCSV && (
                <Button
                  size="small"
                  variant="outlined"
                  startIcon={<GetAppIcon />}
                  onClick={onDownloadCSV}
                  sx={{
                    borderColor: "#555",
                    color: "#999",
                    textTransform: "none",
                    "&:hover": {
                      borderColor: "#777",
                    },
                  }}
                >
                  Export CSV
                </Button>
              )}
            </>
          )}
        </Stack>
      </CardContent>
    </Card>
  );
};

// Semantic Query Editor Component
import React, { useEffect, useState } from "react";
import {
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Dialog,
  DialogContent,
  DialogTitle,
  Stack,
  Tooltip,
  Typography,
} from "@mui/material";
import ContentCopyIcon from "@mui/icons-material/ContentCopy";
import FormatAlignLeftIcon from "@mui/icons-material/FormatAlignLeft";
import InfoIcon from "@mui/icons-material/Info";
import MapIcon from "@mui/icons-material/Map";
import EditIcon from "@mui/icons-material/Edit";
import { SemanticQuery, SemanticBundle } from "../types";

interface SemanticQueryEditorProps {
  query: SemanticQuery | null;
  bundle: SemanticBundle | null;
  loading: boolean;
  error?: string;
  warnings?: string[];
  onQueryChange: (query: SemanticQuery) => void;
  onExplain?: () => Promise<string>;
  onShowLineage?: (fieldId: string) => void;
}

export const SemanticQueryEditor: React.FC<SemanticQueryEditorProps> = ({
  query,
  bundle,
  loading,
  error,
  warnings,
  onQueryChange,
  onExplain,
  onShowLineage,
}) => {
  const [jsonText, setJsonText] = useState("");
  const [editMode, setEditMode] = useState(false);
  const [explanation, setExplanation] = useState<string | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [isExplaining, setIsExplaining] = useState(false);

  useEffect(() => {
    if (query) {
      setJsonText(JSON.stringify(query, null, 2));
    }
  }, [query]);

  const handleFormatJson = () => {
    try {
      const parsed = JSON.parse(jsonText);
      setJsonText(JSON.stringify(parsed, null, 2));
    } catch (err) {
      alert("Invalid JSON");
    }
  };

  const handleApplyChanges = () => {
    try {
      const parsed = JSON.parse(jsonText);
      onQueryChange(parsed);
      setEditMode(false);
    } catch (err) {
      alert("Invalid JSON: " + (err as Error).message);
    }
  };

  const handleCopyJson = () => {
    navigator.clipboard.writeText(jsonText);
    alert("Copied to clipboard!");
  };

  const handleExplain = async () => {
    if (onExplain) {
      setIsExplaining(true);
      try {
        const exp = await onExplain();
        setExplanation(exp);
        setShowExplanation(true);
      } catch (err) {
        alert("Failed to explain query: " + (err as Error).message);
      } finally {
        setIsExplaining(false);
      }
    }
  };

  return (
    <>
      <Card
        sx={{
          height: "100%",
          display: "flex",
          flexDirection: "column",
          backgroundColor: "#1e1e1e",
          border: "1px solid #333",
        }}
      >
        <CardContent
          sx={{
            flex: 1,
            display: "flex",
            flexDirection: "column",
            gap: 2,
            overflow: "hidden",
            p: 2,
          }}
        >
          <Stack direction="row" spacing={1} alignItems="center">
            <Typography variant="h6" sx={{ fontWeight: 600, color: "#fff" }}>
              Semantic Query
            </Typography>
            {query && (
              <Chip
                label={`${query.select?.length || 0} fields`}
                size="small"
                sx={{ backgroundColor: "#2d2d2d", color: "#aaa" }}
              />
            )}
            {warnings && warnings.length > 0 && (
              <Tooltip title={warnings.join("\n")}>
                <InfoIcon sx={{ color: "#FF9800", cursor: "help" }} />
              </Tooltip>
            )}
          </Stack>

          {/* JSON Editor */}
          <Box
            sx={{
              flex: 1,
              backgroundColor: "#2d2d2d",
              border: "1px solid #444",
              borderRadius: 1,
              p: 1.5,
              fontFamily: '"Fira Code", monospace',
              fontSize: "12px",
              overflow: "auto",
              color: "#e8e8e8",
              position: "relative",
            }}
          >
            {editMode ? (
              <Box
                component="textarea"
                aria-label="JSON editor"
                placeholder="Enter JSON query here"
                value={jsonText}
                onChange={(e) => setJsonText(e.target.value)}
                sx={{
                  width: '100%',
                  height: '100%',
                  backgroundColor: '#1e1e1e',
                  color: '#e8e8e8',
                  border: 'none',
                  fontFamily: '"Fira Code", monospace',
                  fontSize: '12px',
                  p: 1,
                  resize: 'none',
                }}
              />
            ) : (
              <Box
                component="pre"
                aria-label="Read-only JSON preview"
                sx={{
                  margin: 0,
                  padding: 0,
                  overflow: 'auto',
                  whiteSpace: 'pre-wrap',
                  wordWrap: 'break-word',
                }}
              >
                {jsonText || (loading ? 'Loading...' : 'No query yet')}
              </Box>
            )}
          </Box>

          {/* Action buttons */}
          <Stack direction="row" spacing={1} sx={{ flexWrap: "wrap" }}>
            {editMode ? (
              <>
                <Button
                  size="small"
                  variant="contained"
                  onClick={handleApplyChanges}
                  sx={{
                    backgroundColor: "#4CAF50",
                    "&:hover": { backgroundColor: "#45a049" },
                    textTransform: "none",
                  }}
                >
                  Apply
                </Button>
                <Button
                  size="small"
                  variant="outlined"
                  onClick={() => setEditMode(false)}
                  sx={{
                    borderColor: "#555",
                    color: "#999",
                    textTransform: "none",
                  }}
                >
                  Cancel
                </Button>
              </>
            ) : (
              <>
                <Button
                  size="small"
                  variant="text"
                  startIcon={<EditIcon />}
                  onClick={() => setEditMode(true)}
                  disabled={loading}
                  sx={{ color: "#2196F3", textTransform: "none" }}
                >
                  Edit JSON
                </Button>
                <Button
                  size="small"
                  variant="text"
                  startIcon={<FormatAlignLeftIcon />}
                  onClick={handleFormatJson}
                  disabled={loading || !jsonText}
                  sx={{ color: "#666", textTransform: "none" }}
                >
                  Format
                </Button>
                <Button
                  size="small"
                  variant="text"
                  startIcon={<ContentCopyIcon />}
                  onClick={handleCopyJson}
                  disabled={loading || !jsonText}
                  sx={{ color: "#666", textTransform: "none" }}
                >
                  Copy
                </Button>
                {onExplain && (
                  <Button
                    size="small"
                    variant="text"
                    startIcon={
                      isExplaining ? <CircularProgress size={16} /> : <InfoIcon />
                    }
                    onClick={handleExplain}
                    disabled={loading || isExplaining || !query}
                    sx={{ color: "#FF9800", textTransform: "none" }}
                  >
                    Explain
                  </Button>
                )}
                {onShowLineage && query?.select && query.select.length > 0 && (
                  <Button
                    size="small"
                    variant="text"
                    startIcon={<MapIcon />}
                    onClick={() =>
                      query.select && query.select.length > 0 &&
                      onShowLineage(query.select[0])
                    }
                    disabled={loading}
                    sx={{ color: "#9C27B0", textTransform: "none" }}
                  >
                    Lineage
                  </Button>
                )}
              </>
            )}
          </Stack>

          {/* Validation feedback */}
          {error && (
            <Box
              sx={{
                backgroundColor: "#3d1f1f",
                border: "1px solid #cc3333",
                borderRadius: 1,
                p: 1,
                color: "#ff6666",
                fontSize: "12px",
              }}
            >
              ⚠️ {error}
            </Box>
          )}
        </CardContent>
      </Card>

      {/* Explanation Dialog */}
      <Dialog
        open={showExplanation}
        onClose={() => setShowExplanation(false)}
        maxWidth="md"
        fullWidth
        PaperProps={{
          sx: { backgroundColor: "#1e1e1e", color: "#fff" },
        }}
      >
        <DialogTitle sx={{ borderBottom: "1px solid #333" }}>
          Query Explanation
        </DialogTitle>
        <DialogContent sx={{ mt: 2 }}>
          <Box
            sx={{
              backgroundColor: "#2d2d2d",
              p: 2,
              borderRadius: 1,
              fontFamily: 'monospace',
              lineHeight: 1.8,
              color: "#ddd",
              whiteSpace: "pre-wrap",
              wordWrap: "break-word",
            }}
          >
            {explanation}
          </Box>
        </DialogContent>
      </Dialog>
    </>
  );
};

// Custom hook for calling the executor LLM
import { useState } from "react";
import {
  ExecutorRequest,
  ExecutorResponse,
} from "../types";
import { semanticPlaygroundApi } from "../utils/api";

interface UseExecutorResult {
  generatedSQL: string | null;
  warnings: string[];
  loading: boolean;
  error: string | null;
  callExecutor: (request: ExecutorRequest) => Promise<void>;
}

export function useExecutor(): UseExecutorResult {
  const [generatedSQL, setGeneratedSQL] = useState<string | null>(null);
  const [warnings, setWarnings] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const callExecutor = async (request: ExecutorRequest) => {
    setLoading(true);
    setError(null);

    try {
      const response = await semanticPlaygroundApi.callExecutor(request);
      setGeneratedSQL(response.generated_sql);
      setWarnings(response.warnings || []);
    } catch (err: any) {
      setError(err.message || "Failed to call executor LLM");
      setGeneratedSQL(null);
    } finally {
      setLoading(false);
    }
  };

  return {
    generatedSQL,
    warnings,
    loading,
    error,
    callExecutor,
  };
}

// Custom hook for calling the planner LLM
import { useState } from "react";
import {
  PlannerRequest,
  PlannerResponse,
  SemanticQuery,
} from "../types";
import { semanticPlaygroundApi } from "../utils/api";

interface UsePlannerResult {
  semanticQuery: SemanticQuery | null;
  explanation: string | null;
  confidence: number | null;
  warnings: string[];
  loading: boolean;
  error: string | null;
  callPlanner: (request: PlannerRequest) => Promise<void>;
}

export function usePlanner(): UsePlannerResult {
  const [semanticQuery, setSemanticQuery] = useState<SemanticQuery | null>(
    null
  );
  const [explanation, setExplanation] = useState<string | null>(null);
  const [confidence, setConfidence] = useState<number | null>(null);
  const [warnings, setWarnings] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const callPlanner = async (request: PlannerRequest) => {
    setLoading(true);
    setError(null);

    try {
      const response = await semanticPlaygroundApi.callPlanner(request);
      setSemanticQuery(response.semantic_query);
      setExplanation(response.explanation || null);
      setConfidence(response.confidence || null);
      setWarnings(response.warnings || []);
    } catch (err: any) {
      setError(err.message || "Failed to call planner LLM");
      setSemanticQuery(null);
    } finally {
      setLoading(false);
    }
  };

  return {
    semanticQuery,
    explanation,
    confidence,
    warnings,
    loading,
    error,
    callPlanner,
  };
}

// Custom hook for running SQL queries
import { useState } from "react";
import {
  QueryExecutionResponse,
} from "../types";
import { semanticPlaygroundApi } from "../utils/api";

interface UseSQLRunnerResult {
  results: QueryExecutionResponse | null;
  executionTime: number | null;
  loading: boolean;
  error: string | null;
  runSQL: (sql: string) => Promise<void>;
}

export function useSQLRunner(): UseSQLRunnerResult {
  const [results, setResults] = useState<QueryExecutionResponse | null>(null);
  const [executionTime, setExecutionTime] = useState<number | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const runSQL = async (sql: string) => {
    setLoading(true);
    setError(null);
    const startTime = performance.now();

    try {
      const response = await semanticPlaygroundApi.runSQL({
        sql,
        limit: 1000,
      });
      const endTime = performance.now();
      setResults(response);
      setExecutionTime(response.execution_time_ms);
    } catch (err: any) {
      setError(err.message || "Failed to run SQL query");
      setResults(null);
    } finally {
      setLoading(false);
    }
  };

  return {
    results,
    executionTime,
    loading,
    error,
    runSQL,
  };
}

// Custom hook for fetching semantic bundles
import { useEffect, useState } from "react";
import {
  SemanticBundle,
  BundleVersion,
} from "../types";
import { semanticPlaygroundApi } from "../utils/api";

interface UseSemanticBundleResult {
  bundle: SemanticBundle | null;
  versions: BundleVersion[];
  loading: boolean;
  error: string | null;
  fetchBundle: (datasource: string, version?: string) => Promise<void>;
  fetchVersions: (datasource: string) => Promise<void>;
}

export function useSemanticBundle(): UseSemanticBundleResult {
  const [bundle, setBundle] = useState<SemanticBundle | null>(null);
  const [versions, setVersions] = useState<BundleVersion[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchBundle = async (datasource: string, version?: string) => {
    setLoading(true);
    setError(null);

    try {
      const bundle = await semanticPlaygroundApi.getBundle(datasource, version);
      setBundle(bundle);
    } catch (err: any) {
      setError(err.message || "Failed to fetch semantic bundle");
      setBundle(null);
    } finally {
      setLoading(false);
    }
  };

  const fetchVersions = async (datasource: string) => {
    try {
      const versions = await semanticPlaygroundApi.getBundleVersions(datasource);
      setVersions(versions);
    } catch (err: any) {
      console.error("Failed to fetch bundle versions:", err);
    }
  };

  return {
    bundle,
    versions,
    loading,
    error,
    fetchBundle,
    fetchVersions,
  };
}

