            configure(proxy: any, options: any) {
              try {
                proxy.on && proxy.on('proxyReq', (_proxyReq: any, req: any) => {
                  // eslint-disable-next-line no-console
                  console.log('[vite proxy] proxying request', { method: req.method, url: req.url, target: options.target, headers: req.headers });
                });
                // Log response status and headers for easier debugging
                proxy.on && proxy.on('proxyRes', (proxyRes: any, req: any, res: any) => {
                  try {
                    // eslint-disable-next-line no-console
                    console.log('[vite proxy] proxy response', { url: req && req.url, statusCode: proxyRes && proxyRes.statusCode, headers: proxyRes && proxyRes.headers });
                  } catch (e) { }
                });
                proxy.on && proxy.on('error', (err: any, req: any) => {
                  // eslint-disable-next-line no-console
                  console.error('[vite proxy] proxy error', err && err.message ? err.message : err, { url: req && req.url });
                });
              } catch (e) { }
            },
            onError(err: any, _req: any, res: any) {
              // eslint-disable-next-line no-console
              console.error('[vite proxy] /api error', err && err.message ? err.message : err);
              try {
                if (!res.headersSent) {
                  res.writeHead && res.writeHead(502);
                  res.end && res.end('Proxy error');
                }
              } catch (e) { }
            },
          },
          // Proxy GraphQL endpoint used by the app's Apollo client when running locally.
          // When VITE_GRAPHQL_ENDPOINT uses a relative path '/v1/graphql' the dev server
          // should forward it to the configured GraphQL target (remote Hasura) so the browser does not
          // inadvertently return index.html (SPA fallback) for GraphQL requests.
          '/v1/graphql': {
