                });
              } catch (e) { }
            },
            onError(err: any, _req: any, res: any) {
              // eslint-disable-next-line no-console
              console.error('[vite proxy] /v1/graphql error', err && err.message ? err.message : err);
              try {
                if (!res.headersSent) {
                  res.writeHead && res.writeHead(502);
                  res.end && res.end('Proxy error');
                }
              } catch (e) { }
            },
          },

        };
      })(),
    },
    optimizeDeps: {
      include: [
        '@mui/material',
        '@mui/x-date-pickers',
        '@mui/x-date-pickers/LocalizationProvider',
        '@mui/x-date-pickers/AdapterDateFns',
        '@mui/x-date-pickers/DatePicker',
        '@mui/icons-material',
        'chart.js',
        'chartjs-adapter-date-fns',
        'react-chartjs-2',
        'react-diff-view',
        'diff',
      ],
      exclude: [
        'echarts',
        'zrender',
        'echarts-for-react',
        // Common problematic dependencies that may cause issues with Vite's dep optimizer
